/// The arithmetic operators the lane decides per operator (`lane_operator`,
/// `lane_returning_operator`): `$pick!(OPERATOR)` of `$operator`'s, else `None`; or with
/// `all`, the array of every operator's `$pick!`.
macro_rules! arithmetic_operators {
    (@with $form:ident ($($args:tt)*)) => {{
        use super::operations::{
            ADDITION, BITWISE_AND, BITWISE_OR, BITWISE_XOR, DIVISION, MULTIPLICATION, REMAINDER,
            SHIFT_LEFT, SHIFT_RIGHT, SHIFT_RIGHT_ZERO_FILL, SUBTRACTION,
        };
        $form!($($args)*; ADDITION, SUBTRACTION, MULTIPLICATION, DIVISION, REMAINDER, SHIFT_LEFT,
            SHIFT_RIGHT, SHIFT_RIGHT_ZERO_FILL, BITWISE_OR, BITWISE_XOR, BITWISE_AND)
    }};
    (all $pick:ident) => {
        arithmetic_operators!(@with arithmetic_all ($pick))
    };
    ($operator:expr, $pick:ident) => {
        arithmetic_operators!(@with arithmetic_match ($operator, $pick))
    };
}

macro_rules! arithmetic_match {
    ($operator:expr, $pick:ident; $($op:ident),*) => {
        match $operator {
            $($op => Some($pick!($op)),)*
            _ => None,
        }
    };
}

macro_rules! arithmetic_all {
    ($pick:ident; $($op:ident),*) => {
        [$($pick!($op)),*]
    };
}

/// What a leaf's records read of the context its call runs them in (`leaf_body`), which is
/// what the call makes its own and its return restores: the forms of its call
/// (`lane_script_call_leaf`), its entry (`CallEntry::leaf`) and its return records
/// (`LaneView::specialize_leaf_returns`). `NOT_LEAF` is a record of no leaf's records.
type LeafForm = u8;
const NOT_LEAF: LeafForm = 0;
/// Neither its receiver nor its captures (`CallEntry::Leaf`): it runs in its caller's context.
const PLAIN_LEAF: LeafForm = 1;
/// Its captures and not its receiver (`CallEntry::CaptureLeaf`): the call makes the
/// environment its own and binds no receiver unless the leaf materializes.
const CAPTURE_LEAF: LeafForm = 2;
/// Its receiver, and maybe its captures (`CallEntry::ContextLeaf`): the call makes the
/// receiver and the environment its own.
const CONTEXT_LEAF: LeafForm = 3;
/// Its receiver and not its captures (`CallEntry::ThisLeaf`): the call binds the receiver
/// and keeps the caller's environment, which only a materialization makes the callee's.
const THIS_LEAF: LeafForm = 4;

/// Whether a leaf of `form` runs with its receiver bound (`THIS_LEAF`, `CONTEXT_LEAF`).
#[inline(always)]
const fn leaf_binds_this(form: LeafForm) -> bool {
    form == CONTEXT_LEAF || form == THIS_LEAF
}

/// Whether a leaf of `form` runs in its own environment (`CAPTURE_LEAF`, `CONTEXT_LEAF`).
#[inline(always)]
const fn leaf_swaps_env(form: LeafForm) -> bool {
    form == CONTEXT_LEAF || form == CAPTURE_LEAF
}

/// One instruction of a lane view.
#[repr(C)]
pub(super) struct LaneInstruction {
    /// The opcode's [`Handler`] for the VM that built the view.
    handler: *const (),
    operand: LaneOperand,
    a: u16,
    b: u16,
    c: u16,
    /// A call record's hint of the script call target cache entry that answered it last
    /// (`Vm::linked_script_call_entry`), which the record's next call tests first; `NO_CALL_LINK`
    /// for none. It fills the record's padding, so every record keeps its size.
    call_link: std::cell::Cell<u16>,
}

/// The callees a site's history holds unspilled: sites stay monomorphic (mandreel: 131K, none
/// polymorphic), so one keeps an entry at 32 bytes instead of 112.
const INLINE_SITE_TARGETS: usize = 1;

/// A `LaneInstruction::call_link` that names no entry: no cache holds this many.
const NO_CALL_LINK: u16 = u16::MAX;
const _: () = assert!(std::mem::size_of::<LaneInstruction>() == 3 * std::mem::size_of::<u64>());

/// The immediate, resolved by its role: a jump target becomes the byte
/// distance from the record, a constant index becomes the constant.
#[derive(Clone, Copy)]
union LaneOperand {
    imm: u32,
    /// Immutable candidates for a string selector, owned by the lane view.
    string_case_filter: *const string_case_filter::StringCaseFilter,
    /// A `GetField` record's immediate and the receiver shape of its own-field hint
    /// (`LaneInstruction::field_hint`).
    field: FieldOperand,
    /// A call record's immediate and its read memo's slot (`CallOperand::memo`).
    call: CallOperand,
    jump: isize,
    constant: Value,
    /// A loop's backward jump in compiled execution: its site (`LoopSite`), which holds the
    /// jump's distance.
    site: *const LoopSite,
    /// The first record of a vector region: the region, which the view owns.
    region: *const vector_region::VectorRegion,
}

/// A `GetField` record's operand: its immediate, and the exact receiver shape its own-field
/// hint names, `NO_FIELD_RECEIVER` for none. The hint's slot is the record's `call_link`,
/// which no field record reads otherwise (`holds_no_call_link`). An inherited read's record
/// hints the inherited entry that last answered it instead (`set_inherited_hint`): its shape
/// is then `INHERITED_HINT` and its `call_link` that entry's index; a polymorphic read's, the
/// prototype-held read that last answered it (`set_holder_hint`), `HOLDER_HINT` and its index.
#[derive(Clone, Copy)]
#[repr(C)]
struct FieldOperand {
    imm: u32,
    shape: u32,
}

/// A call record's operand: its immediate, and the slot of `LaneStack::read_memos` its read
/// memo was made in (`lane_memoize_read`), `NO_READ_MEMO` before its first. The slot is the
/// site's alone until the table refills (`READ_MEMOS`), so which sites keep a memo does not
/// depend on where their records lie.
#[derive(Clone, Copy)]
#[repr(C)]
struct CallOperand {
    imm: u32,
    memo: u32,
}

/// A `CallOperand::memo` that names no slot: no table holds this many.
const NO_READ_MEMO: u32 = u32::MAX;

/// The `FieldOperand::shape` of a record whose hint is an inherited entry
/// (`Vm::inherited_hint_operands`): no object's exact shape (`Object::exact_shape`, whose id
/// bits never all hold), so an own-field hint read (`LaneInstruction::field_hint`) misses it.
const INHERITED_HINT: u32 = super::NO_FIELD_RECEIVER - 1;

/// The `FieldOperand::shape` of a polymorphic read's record whose hint is a prototype-held
/// read (`Vm::holder_hint_hit`), as `INHERITED_HINT` no object's exact shape.
const HOLDER_HINT: u32 = super::NO_FIELD_RECEIVER - 2;

impl LaneInstruction {
    /// The own-field hint of a `GetField` or `SetField` record: an exact receiver shape and the
    /// slot of its own data field, as the site's primary entry proved it
    /// (`lane_get_field_own_refresh`) or a polymorphic store hit it (`lane_set_field_polymorphic`).
    /// Between shape compactions, which clear every hint (`LaneView::invalidate_shape_bindings`), a
    /// shape's slots never change, so the pair holds whatever the entry holds now.
    #[inline(always)]
    fn field_hint(&self) -> super::FieldCache {
        // SAFETY: the view writes `field` for every `GetField` and `SetField` record, the only
        // records whose handlers read the hint.
        super::FieldCache::own(unsafe { self.operand.field.shape }, self.call_link.get())
    }

    #[inline(always)]
    fn imm(&self) -> u32 {
        // SAFETY: the view writes `imm` for every role other than a jump
        // target or constant index, and only those handlers read it.
        unsafe { self.operand.imm }
    }

    #[inline(always)]
    fn jump(&self) -> isize {
        // SAFETY: the view writes `jump` for every jump-target immediate.
        unsafe { self.operand.jump }
    }

    #[inline(always)]
    fn constant(&self) -> Value {
        // SAFETY: the view writes `constant` for every constant index.
        unsafe { self.operand.constant }
    }

    #[inline(always)]
    fn loop_site(&self) -> &LoopSite {
        // SAFETY: `install_loop_sites` writes `site` for the records it gives
        // `lane_loop_jump`, the only handler that reads it; the sites live in the view.
        unsafe { &*self.operand.site }
    }

    #[inline(always)]
    fn vector_region(&self) -> *const vector_region::VectorRegion {
        // SAFETY: the view writes `region` for the records it gives `lane_vector_region`, the
        // only handler that reads it.
        unsafe { self.operand.region }
    }
}

/// A loop the shared compiler may run natively: the region its backward jump
/// closes, the jump's distance to the header record, and the tier's state for it.
pub(super) struct LoopSite {
    /// The bytecode function whose lane view owns this site. A lane activation may be
    /// frameless, so the VM frame's function is not necessarily the one taking this edge.
    function: u32,
    /// Observe backedge work for the JS function tier when OSR rejected this loop. These
    /// sites never attempt native loop code; the shared function compiler owns promotion.
    promotion_only: bool,
    /// First analysis failure, when admission did not produce a region.
    analysis_failure: Option<super::compiled::RegionAnalysisFailure>,
    /// Static effectful calls that leave native code at their exact PC.
    call_boundary_pcs: Box<[u32]>,
    /// The admitted region; a loop whose calls run inlined makes its region once it is hot
    /// (`lane_inlining_region`), when its callees are known.
    region: std::cell::OnceCell<super::compiled::LoopRegion>,
    /// One guarded-inline attempt for an admitted call-boundary region, before compiling.
    /// Failure retains the original exact-PC effect boundary.
    inline_region: std::cell::OnceCell<Option<Box<super::compiled::LoopRegion>>>,
    /// The loop's header and backward jump PCs.
    header: u32,
    backedge: u32,
    jump: isize,
    /// The header record's own handler while the site holds that record
    /// (`lane_loop_header`), which enters the loop's native code wherever control arrives at
    /// the header; null otherwise.
    header_handler: std::cell::Cell<*const ()>,
    /// Whether the site may hold its header record (`lane_loop_hold_header`): one that is
    /// no call record, whose `call_link` names a call target, and the header of no other
    /// site. The record's `call_link` then names the site.
    hookable: bool,
    /// Backward jumps taken in the interpreter, counted up to `needed`, and one past it once the
    /// tier model has admitted the compile (`LoopSite::interprets`).
    taken: std::cell::Cell<u32>,
    /// The backward jumps the interpreter takes before the model weighs the compile: the warm-up
    /// first, then what the model finds the compile needs (`loop_model::admission_taken`).
    needed: std::cell::Cell<u32>,
    /// Whether the site still enters native code: until its runs and declined entries cost more
    /// than their iterations save (`LoopSite::note_run`).
    entering: std::cell::Cell<bool>,
    /// Entries declined in a row since the last native run, and the entries still to pass to the
    /// interpreter before the next attempt (`LoopSite::note_decline`): a decline whose cause
    /// persists costs attempts logarithmic in the iterations, not one per iteration.
    declines_in_row: std::cell::Cell<u8>,
    skipped_entries: std::cell::Cell<u32>,
    /// Whether this VM requested OSR diagnostics when its lane view was derived.
    diagnostics: bool,
    /// The thresholds its VM's tier controllers read.
    tiers: &'static Tiers,
    lane_backedge_count: std::cell::Cell<u64>,
    native_entry_attempts: std::cell::Cell<u64>,
    native_region_runs: std::cell::Cell<u64>,
    /// Bodies published for this loop (`plan_loop_body`) and runs of them (`lane_loop_body`).
    tier_ups: std::cell::Cell<u64>,
    body_runs: std::cell::Cell<u64>,
    entry_guard_misses: std::cell::Cell<u64>,
    native_exits: std::cell::Cell<u64>,
    widenings: std::cell::Cell<u64>,
    compile_attempts: std::cell::Cell<u64>,
    compile_successes: std::cell::Cell<u64>,
    tier: std::cell::RefCell<LoopTier>,
    /// The function's lane body planned to start at this loop's header (`lane_loop_body`).
    body: std::cell::RefCell<LoopBody>,
    /// The header dispatches that found the body idle (`plan_loop_body`), each an iteration
    /// of the interpreter's or a region's entry, and the iterations the loop takes before its
    /// body is planned again (`loop_model::body_taken`, at the size its last plan had).
    body_seen: std::cell::Cell<u64>,
    body_due: std::cell::Cell<u64>,
    /// Whether a call boundary no region runs made the loop a body's (`loop_body::offer_body`).
    body_offered: std::cell::Cell<bool>,
}

impl LoopSite {
    pub(super) fn function(&self) -> u32 { self.function }

    fn active_region(&self) -> Option<&super::compiled::LoopRegion> {
        self.inline_region.get().and_then(|region| region.as_deref()).or_else(|| self.region.get())
    }

    /// Whether native code may still run the loop: its runs have paid for their entries, its
    /// entries are not declining, and it has code or may compile it. A site without it
    /// retires at its next backward jump (`lane_loop_retire`).
    fn may_run_natively(&self, policy: crate::MemoryPolicy) -> bool {
        self.enters() && self.tier.borrow().may_run(self.tiers, policy)
    }

    fn enters(&self) -> bool {
        self.entering.get()
    }

    /// Whether its loop runs in a region entered from the lane: a closed one that still enters and
    /// has run natively (a region that never ran makes none of the loop's work native).
    pub(super) fn runs_region(&self) -> bool {
        self.call_boundary_pcs.is_empty() && self.active_region().is_some() && self.enters() && self.tier.borrow().runs() > 0
    }

    fn is_admitted(&self) -> bool {
        !self.promotion_only
            && self.analysis_failure.is_none_or(|failure| failure.is_call_boundary())
    }
}

type Ip = *const LaneInstruction;

/// A function's lane view: one record per instruction, and the one register
/// its direct memory accesses go through. Accesses through any other
/// register, and lane instructions other than the binding load that would
/// write this one, take the general path, so the memory view tracks the
/// register exactly.
pub(super) struct LaneView {
    /// A record's handler may change while the lane runs (`requicken`); its other fields do not.
    records: Records,
    /// Per instruction, whether the general loop enters the lane there: the
    /// straight-line lane run from it is long enough to repay the lane's
    /// entry cost, and its record does not read the accumulator. Kept apart
    /// from the records, which only the lane reads.
    entries: Box<[u64]>,
    /// The thresholds its VM's tier controllers read, as the VM held them when the view was derived.
    tiers: &'static Tiers,
    memory_register: Option<u16>,
    /// How a lane call activates the function without a frame; `None`
    /// when its activation needs a frame (locals outside registers).
    activation: Option<ActivationShape>,
    /// The facts of its body a frameless call target records (`TargetBody`), found on its
    /// first resolution: every closure of the function shares them.
    target_body: std::cell::OnceCell<TargetBody>,
    _string_case_filters: Box<[string_case_filter::StringCaseFilter]>,
    /// The window of an environment activation, when its local and closure records also run
    /// in one (`specialize_environment_window`).
    environment_window: Option<EnvironmentWindow>,
    /// Whether the straight-line lane run from the function's first instruction reaches its
    /// `Return` (`entry_run_returns`): a call from a native runs it whole in the lane
    /// (`Vm::run_frame_from_lane`), whatever the run's length, since that call enters no
    /// general loop the lane would save.
    returns_from_entry: bool,
    /// The loops whose backward jumps run `lane_loop_jump`. The view owns them for the
    /// records that point into them, which are their only readers.
    loops: Box<[LoopSite]>,
    /// The backward jumps' PCs, ascending, each with the index in `loops` of the first loop
    /// it closes: a leave finds its loop by a binary search over the few loops, where a table
    /// over every instruction cost 4 bytes per instruction of every view.
    loop_at_backedge: Box<[(u32, u32)]>,
    /// The vector regions whose first records point into them (`vector_region`): only
    /// those records read them.
    #[cfg_attr(not(test), allow(dead_code))]
    vector_regions: Box<[vector_region::VectorRegion]>,
    /// The loop kernels whose test records name them (`loop_kernel`).
    _loop_kernels: Box<[Box<loop_kernel::LoopKernel>]>,
    /// The record an activation starts at (`LaneView::start`): its first, or `prologue`
    /// while the JavaScript tier may claim the function (`LaneView::claim_for_tier`).
    start: std::cell::Cell<Ip>,
    /// The tier prologue (`lane_tier_prologue`), outside the records so the function's PCs
    /// stay its records'; written when the tier may claim the function.
    prologue: std::cell::UnsafeCell<LaneInstruction>,
    /// The prologue's direct run of the compiled body, once the tier compiled it
    /// (`Vm::direct_tier_entry`).
    tier_direct: std::cell::Cell<Option<super::compiled::DirectTierEntry>>,
    /// The lane-body tier's state of this function (`LaneTier`), made when the tier first
    /// looks at it: a view the tier never touches (every view under `--no-jit`, most views
    /// otherwise) keeps one word instead of about 540 bytes.
    tier: std::cell::OnceCell<Box<LaneTier>>,
    /// What native callers read to enter its body (`compiled::EntryCell`); the one entry word
    /// of the function, published and withdrawn with its body.
    entry: super::compiled::entry_cell::EntryCell,
    /// Per record, the register whose value it reads as the carried accumulator
    /// (`NO_ACCUMULATOR` where it reads none): a lane body that leaves at it resumes
    /// with that register carried, as falling through from its producer would.
    accumulator_registers: Box<[u16]>,
    plain_backward_jump_sites: usize,
    osr_rejections: Option<Box<[(super::compiled::RegionRejection, usize)]>>,
    /// The `GetField`, `SetField` and `LoadCapture` records past the loop headers its sites
    /// hold, whose own-field hints a shape compaction clears.
    field_records: Box<[u32]>,
    /// The by-name load and store records past the loop headers its sites hold, whose
    /// global-object hints (`lane_load_name_bound`, `lane_store_global_name`) a shape
    /// compaction clears, and a change of the global
    /// lexical names they answer past (`LaneView::clear_name_hints`).
    name_records: Box<[u32]>,
}

