/// Conservative lane-stack admission room for `count` registers: whole blocks, at
/// least one. Only the logical range is initialized and made live.
const fn fill_room<const BLOCK: usize>(count: usize) -> usize {
    let room = count.next_multiple_of(BLOCK);
    if room < BLOCK { BLOCK } else { room }
}

/// The values of a call window to copy as one fixed-size move each; a longer window copies
/// value by value.
const FIXED_ARGUMENT_COPIES: u16 = 4;

/// Copies the `count` values at `source` to `destination`: a window of at most
/// `FIXED_ARGUMENT_COPIES` values as one move of its size, which needs no loop.
///
/// # Safety
/// Both ranges hold `count` values and do not overlap.
#[inline(always)]
pub(crate) unsafe fn copy_arguments(destination: *mut Value, source: *const Value, count: u16) {
    /// One move of `N` values.
    #[inline(always)]
    unsafe fn copy<const N: usize>(destination: *mut Value, source: *const Value) {
        // SAFETY: the caller's contract, for `N` values.
        unsafe { destination.cast::<[Value; N]>().write_unaligned(source.cast::<[Value; N]>().read_unaligned()) }
    }
    const _: () = assert!(FIXED_ARGUMENT_COPIES == 4);
    // SAFETY: the function's contract.
    unsafe {
        // Compares, not a table, so the common windows of a value or two take a branch each.
        if count <= 2 {
            if count == 2 {
                copy::<2>(destination, source);
            } else if count == 1 {
                copy::<1>(destination, source);
            }
        } else if count <= FIXED_ARGUMENT_COPIES {
            if count == FIXED_ARGUMENT_COPIES {
                copy::<4>(destination, source);
            } else {
                copy::<3>(destination, source);
            }
        } else {
            std::ptr::copy_nonoverlapping(source, destination, usize::from(count));
        }
    }
}

const WINDOW_FILL_PAIR: usize = 2;
const WINDOW_FILL_HALF: usize = WINDOW_FILL_PAIR * 2;
const WINDOW_FILL_BLOCK: usize = WINDOW_FILL_HALF * 2;
// Bound inline work to one complete block and its binary tail. Splitting longer
// ranges between inline stores and a library fill costs more than one direct fill.
const WINDOW_INLINE_FILL_LIMIT: usize = WINDOW_FILL_BLOCK * 2;

/// Initializes exactly the live register range. Admission may reserve a larger room,
/// but padding is not part of the activation's values or materialized frame.
///
/// # Safety
/// `registers` has writable storage for `count` values, none of them live.
#[inline(always)]
pub(crate) unsafe fn fill_window(registers: *mut Value, count: usize, initial: Value) {
    if count >= WINDOW_INLINE_FILL_LIMIT {
        for index in 0..count {
            // SAFETY: each destination lies within the caller's uninitialized range.
            unsafe { registers.add(index).write_unaligned(initial) };
        }
        return;
    }
    #[inline(always)]
    unsafe fn pair(destination: *mut Value, initial: Value) {
        // SAFETY: the caller provides both uninitialized values. Individual stores
        // avoid aggregate-array temporaries in the production call handlers.
        unsafe {
            destination.write_unaligned(initial);
            destination.add(1).write_unaligned(initial);
        }
    }
    #[inline(always)]
    unsafe fn half(destination: *mut Value, initial: Value) {
        // SAFETY: the caller provides a complete half block.
        unsafe {
            pair(destination, initial);
            pair(destination.add(WINDOW_FILL_PAIR), initial);
        }
    }
    let mut tail = 0;
    if count >= WINDOW_FILL_BLOCK {
        // SAFETY: the logical range contains one complete block.
        unsafe {
            half(registers, initial);
            half(registers.add(WINDOW_FILL_HALF), initial);
        }
        tail = WINDOW_FILL_BLOCK;
    }
    if count & WINDOW_FILL_HALF != 0 {
        // SAFETY: this bit proves that a half block remains in the exact tail.
        unsafe { half(registers.add(tail), initial) };
        tail += WINDOW_FILL_HALF;
    }
    if count & WINDOW_FILL_PAIR != 0 {
        // SAFETY: this bit proves that a pair remains after the half block.
        unsafe { pair(registers.add(tail), initial) };
        tail += WINDOW_FILL_PAIR;
    }
    if !count.is_multiple_of(WINDOW_FILL_PAIR) {
        // SAFETY: the odd final value is within the logical range.
        unsafe { registers.add(tail).write_unaligned(initial) };
    }
}

/// The start of a plain activation of `count` registers, whose admission reserved whole
/// `SCRIPT_FILL_BLOCK`s past them (`ScriptCallTarget::room`), every one of the first `fill`
/// `undefined`: a `fill` within one `WINDOW_FILL_BLOCK` takes that block's fixed stores, the
/// values past it landing in registers no instruction reads before writing or in the reserved
/// room, so it makes no test of its count; a longer one fills all `count`.
///
/// # Safety
/// `registers` has writable storage for `fill_room::<SCRIPT_FILL_BLOCK>(count)` values, none
/// of them live, and `fill` covers every register the activation's function reads before
/// writing (`RegisterRoots::entry_fill`).
#[inline(always)]
unsafe fn fill_admitted_window(registers: *mut Value, fill: usize, count: usize) {
    const _: () = assert!(WINDOW_FILL_BLOCK <= SCRIPT_FILL_BLOCK);
    if fill > WINDOW_FILL_BLOCK {
        // SAFETY: the function's contract.
        return unsafe { fill_window(registers, count, Value::UNDEFINED) };
    }
    for index in 0..WINDOW_FILL_BLOCK {
        // SAFETY: the admitted room holds a whole block.
        unsafe { registers.add(index).write_unaligned(Value::UNDEFINED) };
    }
}

/// A function's register window as a lane activation starts it: every
/// register its initial value, then the parameters at their base.
#[derive(Clone, Copy)]
struct ActivationShape {
    registers: u16,
    parameters: u16,
    params: u16,
    initial: Value,
}

impl ActivationShape {
    /// The window of `function`, when its parameters have registers and it keeps no locals.
    fn of(function: &Function) -> Option<Self> {
        function.parameter_registers.filter(|_| function.locals == 0).map(|parameters| Self {
            registers: function.registers,
            parameters,
            params: function.params,
            initial: function.initial_register.value(),
        })
    }
}

/// Storage and guest-call allowance proved before an inlined body runs.
#[derive(Clone, Copy, Default)]
#[repr(C)]
pub(super) struct LaneRecoverySpace {
    pub(super) values: usize,
    pub(super) activations: usize,
}

impl LaneRecoverySpace {
    /// Frames follow their parents. Take independent maxima: the deepest
    /// chain and the largest register window need not be the same chain. Each frame's window
    /// leaves the next one's context words past its registers (`lane_values::CONTEXT`).
    pub(super) fn inlined(frames: &[super::compiled::InlinedCall]) -> Self {
        let mut chains = smallvec::SmallVec::<[Self; 1]>::new();
        let mut space = Self::default();
        for frame in frames {
            let parent = frame.parent.map_or_else(Self::default, |parent| chains[parent]);
            let window = fill_room::<SCRIPT_FILL_BLOCK>(usize::from(frame.registers)) + lane_values::CONTEXT;
            let chain = Self { values: parent.values + window,
                activations: parent.activations + 1 };
            space.values = space.values.max(chain.values);
            space.activations = space.activations.max(chain.activations);
            chains.push(chain);
        }
        space
    }

    /// Room for `registers` frame slots past the caller's, which a body's rows name beyond its inlined windows (its scratch).
    pub(super) fn reaching(self, registers: usize) -> Self {
        if registers == 0 { self } else { Self { values: self.values.max(fill_room::<SCRIPT_FILL_BLOCK>(registers)), ..self } }
    }
}

/// A lane view's frameless body (`LaneView::tier_lane`). Shape compaction
/// moves a body that names shape IDs back to `Unspecialized`.
enum LaneBody {
    /// Counting its entries toward specialization; `recompiles` bodies before it left too
    /// often for their feedback (`LaneView::note_lane_body_end`), the last of them, where
    /// `stuck`, at those few leaves only.
    Unspecialized { entries: u32, recompiles: u8, stuck: LaneLeaves },
    /// Its body's code compiling on the code generator's thread; the function runs in the
    /// lane meanwhile, and looks for the code (`Vm::lane_body_work`) at entries spaced twice
    /// as far apart after each of its `looks`, up to `TIERS.lane_body.compile_poll_interval`:
    /// a function entered seldom (a hot loop's) finds its code at its next entries, and a hot
    /// one pays few looks. `wait` counts the entries left before the next.
    Compiling { pending: Box<super::compiled::PendingLaneMethod>, wait: std::cell::Cell<u16>, looks: u8, recompiles: u8, stuck: LaneLeaves },
    /// The body its prologue record enters directly (`lane_body_entry`); `tier_prologue` is
    /// the handler that record had, which it takes back when the body retires. Its
    /// publication may retire at a lifecycle edge (`ProgramStore::retire_dead_native_calls`),
    /// which the next entry settles (`LaneView::settle_retired_body`).
    Specialized {
        method: std::rc::Rc<super::compiled::PublishedLaneMethod>,
        tier_prologue: *const (),
        /// Its leaves' places (`LaneLeaves`); the counts of its leaves and completed runs since
        /// it specialized live in its entry cell (`EntryCell::evidence`), toward
        /// `TIERS.lane_body.reoptimize_exits` and `TIERS.lane_body.reoptimize_share`.
        leaves_at: std::cell::Cell<LaneLeaves>,
        /// Whether a run of it completed, natively called ones included.
        completed: std::cell::Cell<bool>,
        recompiles: u8,
        /// Its predecessor's few leaves, where it left only there.
        stuck: LaneLeaves,
    },
    Declined,
}


/// The lane-body tier's per-function state (`LaneView::tier`).
pub(super) struct LaneTier {
    /// The frameless body the prologue runs once the JavaScript tier declined the
    /// function (`Vm::compile_lane_method`).
    tier_lane: std::cell::UnsafeCell<LaneBody>,
    /// The warming tick (`lane_body_tier::warm_ticks`) of the entry its body began warming at, which a function
    /// entered rarely but for long (`LaneView::recurrent`) specializes by.
    warm_since: std::cell::Cell<u32>,
    /// Every body it published, kept until the view drops: a native frame running a body that
    /// retired recovers its leave through `ShadowFrame::body`.
    pinned: std::cell::RefCell<Vec<std::rc::Rc<super::compiled::LaneMethod>>>,
    /// What its bodies cost and earned so far (`LaneBodyHistory`).
    history: std::cell::Cell<LaneBodyHistory>,
    /// The epochs of its body's audit (`lane_body_audit`).
    audit_epochs: std::cell::Cell<lane_body_tier::Epochs>,
    /// What its lane bodies did, under `QUENCH_TRACE=js-jit` (`LaneBodyStats`).
    pub(super) body_stats: LaneBodyStats,
    /// Bodies it specialized again past (`LaneView::note_lane_body_end`), whose code the
    /// direct callers that name them still run until they retire with them at a shape
    /// compaction.
    retired: std::cell::RefCell<Vec<std::rc::Rc<super::compiled::PublishedLaneMethod>>>,
    /// The views whose bodies compiled a call of this function (`LaneView::note_caller`):
    /// they specialize again when its body publishes, to call it by its entry.
    callers: std::cell::RefCell<Vec<*const LaneView>>,
}

impl Default for LaneTier {
    fn default() -> Self {
        Self {
            tier_lane: std::cell::UnsafeCell::new(LaneBody::Unspecialized { entries: 0, recompiles: 0, stuck: LaneLeaves::NONE }),
            warm_since: std::cell::Cell::new(0),
            pinned: std::cell::RefCell::default(),
            history: Default::default(),
            audit_epochs: Default::default(),
            body_stats: LaneBodyStats::default(),
            retired: std::cell::RefCell::default(),
            callers: std::cell::RefCell::default(),
        }
    }
}

impl LaneView {
    /// Its lane-body tier state, made on first use.
    #[inline]
    pub(super) fn tier(&self) -> &LaneTier {
        self.tier.get_or_init(Box::default)
    }

    /// The name of its body's state, for the diagnostics report (`LaneBodyStats::report`).
    pub(super) fn lane_body_state(&self) -> &'static str {
        // SAFETY: as `lane_body`.
        match unsafe { &*self.tier().tier_lane.get() } {
            LaneBody::Unspecialized { .. } => "unspecialized",
            LaneBody::Compiling { .. } => "compiling",
            LaneBody::Specialized { .. } => "specialized",
            LaneBody::Declined => "declined",
        }
    }

    /// Its body's state, the entries it counted, and whether the tier claimed its prologue and
    /// is still warming, for the diagnostics report of a view that never compiled
    /// (`QUENCH_LANE_STATE`).
    pub(super) fn lane_body_detail(&self) -> (&'static str, Option<u32>, bool, bool) {
        // SAFETY: as `lane_body`.
        let entries = match unsafe { &*self.tier().tier_lane.get() } {
            LaneBody::Unspecialized { entries, .. } => Some(*entries),
            _ => None,
        };
        (self.lane_body_state(), entries, self.start.get() == self.prologue.get().cast_const(), self.warming())
    }

    /// The specialized frameless body, if there is one.
    fn lane_body(&self) -> Option<std::rc::Rc<super::compiled::LaneMethod>> {
        // SAFETY: this view is read on its VM's thread. Clone the code owner before
        // execution or recovery can reenter and change the view's publication.
        match unsafe { &*self.tier().tier_lane.get() } {
            LaneBody::Specialized { method, .. } => method.lease(),
            LaneBody::Unspecialized { .. } | LaneBody::Compiling { .. } | LaneBody::Declined => None,
        }
    }

    /// The published closed body a direct caller pins (`compiled::DirectCallee::method`, `body`), which a
    /// caller of the function itself, or of one with none, leaves to the entry cell it calls through
    /// (the stub enters nothing).
    fn pinned_callee(&self, own: bool) -> (Option<std::rc::Rc<super::compiled::PublishedLaneMethod>>, Option<std::rc::Rc<super::compiled::LaneMethod>>) {
        let method = self.published_lane_body().filter(|_| !own);
        let body = method.as_ref().and_then(|method| method.lease()).filter(|body| body.calls_only_natively());
        if body.is_some() { (method, body) } else { (None, None) }
    }

    /// The body its entry cell holds, which every caller enters through the cell's one entry
    /// word: `None` while the cell holds the stub (no closed body is published, or it retired),
    /// whose entries take `lane_body` or the warming path. Owned as `lane_body` owns it, so a
    /// reentrant change of the publication leaves the run its code.
    fn cell_body(&self) -> Option<std::rc::Rc<super::compiled::LaneMethod>> {
        let cell = &self.entry;
        self.entry_published().then(|| {
            let body = cell.body.get() as *const super::compiled::LaneMethod;
            // SAFETY: a published cell's `body` is `Rc::as_ptr` of the body `pinned` keeps
            // (`EntryCell::publish`); the strong count taken here is the run's own.
            unsafe {
                std::rc::Rc::increment_strong_count(body);
                std::rc::Rc::from_raw(body)
            }
        })
    }

    /// The body its entry cell holds, borrowed: the view pins every body it published until it
    /// drops (`pinned`), and the program store keeps the view alive through any lane run, so a
    /// run needs no count of its own, and a retirement during the run only unlinks the entry.
    #[inline(always)]
    fn cell_method(&self) -> Option<&super::compiled::LaneMethod> {
        // SAFETY: a published cell's `body` is `Rc::as_ptr` of a body `pinned` keeps (`EntryCell::publish`).
        self.entry_published().then(|| unsafe { &*(self.entry.body.get() as *const super::compiled::LaneMethod) })
    }

    /// Whether its prologue says the body reads its receiver (`claim_for_tier`'s `binds_this`).
    #[inline(always)]
    fn binds_this(&self) -> bool {
        // SAFETY: the lane runs on the view's thread; nothing writes the prologue during a call.
        unsafe { (*self.prologue.get()).b != 0 }
    }

    /// Whether its entry cell holds a published body rather than the stub.
    #[inline(always)]
    fn entry_published(&self) -> bool {
        // The body word, not the entry word: the stub is a private function whose address the
        // linker may fold into more than one copy, so comparing entry words by identity reports
        // a withdrawn cell as published (and a published body's pointer as absent).
        self.entry.body.get() != 0
    }

    /// The address of its entry cell, which native callers name (`compiled::DirectCallee::cell`).
    pub(super) fn entry_cell(&self) -> usize { std::ptr::from_ref(&self.entry).addr() }

    /// The publication of the specialized body, which a direct caller holds
    /// (`compiled::DirectCallee::method`).
    fn published_lane_body(&self) -> Option<std::rc::Rc<super::compiled::PublishedLaneMethod>> {
        // SAFETY: as `lane_body`.
        match unsafe { &*self.tier().tier_lane.get() } {
            LaneBody::Specialized { method, .. } => Some(method.clone()),
            _ => None,
        }
    }

    /// A specialized body whose publication a lifecycle edge retired
    /// (`ProgramStore::retire_dead_native_calls`) warms again: its prologue takes back the
    /// tier's handler.
    fn settle_retired_body(&self) {
        // SAFETY: as `lane_body`; settling runs no lane body.
        let body = unsafe { &mut *self.tier().tier_lane.get() };
        if let LaneBody::Specialized { method, tier_prologue, .. } = body
            && !method.is_published()
        {
            // SAFETY: as `claim_for_tier`; the prologue's handler runs no more for this entry.
            unsafe { (*self.prologue.get()).handler = *tier_prologue };
            self.drop_body(body);
        }
    }

    /// Whether it has no body yet and counts entries toward one, its first or a next.
    fn warming(&self) -> bool {
        // SAFETY: as `lane_body`.
        matches!(unsafe { &*self.tier().tier_lane.get() }, LaneBody::Unspecialized { .. }) || self.compiling()
    }


    /// Whether its body left too often and specializes again at its next entry.
    fn respecializes(&self) -> bool {
        // SAFETY: as `lane_body`.
        matches!(unsafe { &*self.tier().tier_lane.get() }, LaneBody::Unspecialized { recompiles, .. } if *recompiles > 0)
    }


    /// Retires field hints and native bodies (and plans) that name shape IDs when compaction renumbers them.
    pub(super) fn invalidate_shape_bindings(&self) {
        // SAFETY: no lane body runs during a collection.
        let body = unsafe { &mut *self.tier().tier_lane.get() };
        if let LaneBody::Compiling { pending, .. } = body { pending.retire_named_shapes(); }
        if let LaneBody::Specialized { method, tier_prologue, .. } = body
            && method.lease().is_some_and(|method| method.names_shapes)
        {
            // SAFETY: as `claim_for_tier`; no lane body or handler runs during a collection,
            // and no method borrower is held.
            unsafe {
                (*self.prologue.get()).handler = *tier_prologue;
                method.retire();
            }
            self.drop_body(body);
        }
        self.tier().retired.borrow_mut().clear();
        self.clear_hints(&self.field_records);
        self.clear_name_hints();
        for site in &self.loops {
            let tier = site.tier.borrow();
            tier.retire_named_shapes();
            if let Some(publication) = &tier.code
                && publication.lease().is_some_and(|code| !code.facts.shape_dependencies.is_empty()) {
                publication.retire();
            }
        }
    }

    /// The own-field hint of the field record at `pc`, as the layout id (`Object::hint_shape`)
    /// of the receiver it last answered: what a specializer guards in one compare to read the
    /// record's storage form with no test (`NativeFieldLoad::formed`).
    /// `None` where the record holds no own hint, or is no hinted field record.
    pub(super) fn own_field_hint(&self, pc: usize) -> Option<u32> {
        let pc = u32::try_from(pc).ok()?;
        if !self.field_records.contains(&pc) { return None; }
        // SAFETY: each listed record's operand is `field` (`holds_field_hint`).
        let shape = unsafe { (*self.records[pc as usize].get()).operand.field.shape };
        (shape < HOLDER_HINT).then_some(shape)
    }

    /// Clears the global-object hints of its by-name loads and stores: a global
    /// lexical name was declared (`Vm::note_global_lexical_names`).
    pub(super) fn clear_name_hints(&self) {
        self.clear_hints(&self.name_records);
    }

    fn clear_hints(&self, pcs: &[u32]) {
        for &pc in pcs {
            let record = std::cell::UnsafeCell::raw_get(&self.records[pc as usize]);
            // SAFETY: each listed record's operand is `field`, and it is no loop's header
            // (`holds_field_hint`); its handler reads the hint whole, between runs that write it.
            unsafe {
                (*record).operand.field.shape = super::NO_FIELD_RECEIVER;
                (*record).call_link.set(NO_CALL_LINK);
            }
        }
    }

    /// How many of its records hold an own-field hint. Profiled builds derive no lane views,
    /// so only the unprofiled test reads it.
    #[cfg(all(test, not(quench_profiled)))]
    pub(super) fn held_field_hints(&self) -> usize {
        self.held_hints(&self.field_records)
    }

    /// How many of its by-name loads hold a global-object hint (`lane_load_name_bound`).
    #[cfg(all(test, not(quench_profiled)))]
    pub(super) fn held_name_hints(&self) -> usize {
        self.held_hints(&self.name_records)
    }

    #[cfg(all(test, not(quench_profiled)))]
    fn held_hints(&self, pcs: &[u32]) -> usize {
        pcs.iter()
            // SAFETY: each listed record's operand is `field` (`holds_field_hint`).
            .filter(|&&pc| unsafe { (*self.records[pc as usize].get()).operand.field.shape } != super::NO_FIELD_RECEIVER)
            .count()
    }

    /// The address range its records span (`lane_exits::register_view`).
    #[cfg(feature = "profile-lane-exits")]
    pub(super) fn record_range(&self) -> (usize, usize) {
        let start = self.records().addr();
        (start, start + self.records.len() * std::mem::size_of::<LaneInstruction>())
    }

    #[inline] pub(super) fn records(&self) -> Ip {
        self.records.base()
    }

    /// The record a frameless activation starts at: the first, or the tier prologue.
    #[inline(always)]
    fn start(&self) -> Ip {
        self.start.get()
    }

    /// Starts the function's frameless activations at the tier prologue, which enters the
    /// JavaScript tier with its `params` parameters (`lane_tier_prologue`). Its fields: `imm`
    /// the function, `a` its parameter count, `b` whether it binds `this` (`lane_body_entry`).
    fn claim_for_tier(&self, handler: Handler, function: u32, params: u16, binds_this: bool) {
        let prologue = self.prologue.get();
        // SAFETY: the lane runs on the view's thread, and nothing reads the prologue while
        // the start does not name it.
        unsafe {
            *prologue = LaneInstruction {
                handler: handler as *const (),
                operand: LaneOperand { imm: function },
                a: params,
                b: u16::from(binds_this),
                c: 0,
                call_link: std::cell::Cell::new(NO_CALL_LINK),
            };
        }
        self.start.set(prologue.cast_const());
    }

    /// Whether a call's resolution claims the prologue for the lane tier: while its body warms
    /// (a hot loop may start its compile before any call resolves it, `lane_loop_retire`)
    /// and nothing claimed it yet. A specialized body's prologue already enters it, and any
    /// other body (declined, retired, or serving native callers only) runs its function in
    /// the lane; claiming again would take the prologue back to `lane_tier_prologue`.
    fn lane_tier_unclaimed(&self) -> bool {
        self.warming() && self.start.get() != self.prologue.get().cast_const()
    }

    /// Starts activations at the tier prologue again, which `claim_for_tier` wrote.
    fn reclaim_for_tier(&self) {
        // A function no call claimed (`LaneView::claim_for_tier`) has no prologue to start at.
        // SAFETY: as `claim_for_tier`.
        if unsafe { (*self.prologue.get()).handler }.is_null() { return; }
        self.start.set(self.prologue.get().cast_const());
    }

    /// Starts activations at the first record again, once the tier declines the function.
    fn release_from_tier(&self) {
        self.start.set(self.records());
    }
}

/// Switches the record at `ip` to `handler` for the rest of its view's life: a one-way step of
/// the record's state machine, taken when an execution of the record shows the handler it has
/// does not fit the site. Every handler a record may switch between computes the same result.
#[inline(always)]
fn requicken<H: Host>(ip: Ip, handler: Handler) {
    // SAFETY: `ip` comes from `LaneView::records`, whose records live in `UnsafeCell`s; the
    // lane runs on the view's thread, and no reference to the handler field is live. A
    // header record a loop site holds keeps `lane_loop_header`, and the site the handler.
    unsafe {
        if (*ip).handler == lane_loop_header::<H> as Handler as *const () {
            let site = lane_header_site(ip);
            (*site).header_handler.set(handler as *const ());
            return;
        }
        if loop_kernel::requicken_kernel::<H>(ip, handler) {
            return;
        }
        (*ip.cast_mut()).handler = handler as *const ();
    }
}

/// Whether the record at `ip` runs `handler` now.
#[inline(always)]
fn handler_is<H: Host>(ip: Ip, handler: Handler) -> bool {
    // SAFETY: as `requicken`, reading only.
    unsafe { (*ip).handler == handler as *const () }
}

/// The receiver's context word, counted down from register 0 (`register_file::FRAME_CONTEXT`).
const CONTEXT_THIS: usize = 1;
/// The environment's context word.
const CONTEXT_ENV: usize = 2;
/// The captures' context word.
const CONTEXT_CAPTURE: usize = 3;

/// The active frame's registers. Lane instructions never resize registers or
/// change the frame stack, so the base stays valid for the whole lane run.
#[derive(Clone, Copy)]
#[repr(transparent)]
struct Registers(*mut Value);

impl Registers {
    /// The frame's receiver, the context word just below register 0 (`FRAME_CONTEXT`): every
    /// register file (`RegisterFile`) and lane window (`LaneValues`) has it there.
    #[inline(always)]
    fn this(self) -> Value {
        // SAFETY: every frame's registers follow its context words.
        unsafe { *self.0.sub(CONTEXT_THIS) }
    }

    #[inline(always)]
    fn set_this(self, this: Value) {
        // SAFETY: as for `this`.
        unsafe { *self.0.sub(CONTEXT_THIS) = this }
    }

    /// The frame's environment, the context word below its receiver: a lane activation's
    /// closure environment, `DELETED` for a VM frame, whose environment its frame holds.
    #[inline(always)]
    fn env(self) -> Value {
        // SAFETY: as for `this`.
        unsafe { *self.0.sub(CONTEXT_ENV) }
    }

    #[inline(always)]
    fn set_env(self, env: Value) {
        // SAFETY: as for `this`.
        unsafe { *self.0.sub(CONTEXT_ENV) = env }
    }

    /// The frame's captures (`ScriptCallTarget::capture`), the context word below its
    /// environment: null where none are read yet (a VM frame's, until first found).
    #[inline(always)]
    fn capture(self) -> *const usize {
        // SAFETY: as for `this`; the word holds a pointer's bits.
        unsafe { *self.0.sub(CONTEXT_CAPTURE).cast::<*const usize>() }
    }

    #[inline(always)]
    fn set_capture(self, capture: *const usize) {
        // SAFETY: as for `capture`.
        unsafe { *self.0.sub(CONTEXT_CAPTURE).cast::<*const usize>() = capture }
    }

    #[inline(always)]
    fn get(self, register: u16) -> Value {
        // SAFETY: the view admits only register fields below
        // Function.registers, and frame setup sizes the register file to it.
        unsafe { *self.0.add(usize::from(register)) }
    }

    #[inline(always)]
    fn set(self, register: u16, value: Value) {
        // SAFETY: as for `get`; no reference into the register file is live.
        unsafe { *self.0.add(usize::from(register)) = value }
    }

    /// The register's int32, read as two dwords: the tag half compared in memory
    /// (`cmp dword [..+4], imm; jne`) and the value half loaded as it is, where a whole-word
    /// read pays a copy, a shift and a compare for the tag (V8-v7 Crypto's integer records).
    #[inline(always)]
    fn int(self, register: u16) -> Option<i32> {
        // SAFETY: as for `get`; a Value is two dwords, the tag in the high one (little endian).
        let halves = unsafe { self.0.add(usize::from(register)) }.cast::<u32>();
        if unsafe { halves.add(1).read() } != crate::value::INT_TAG_HIGH {
            return None;
        }
        Some(unsafe { halves.read() } as i32)
    }

    /// The register's Number (`Value::as_number`), its tag read as the word's top half-word
    /// (`movzx`) and a double loaded straight into a vector register: no copy and shift of
    /// the whole word for the tag.
    #[inline(always)]
    fn number(self, register: u16) -> Option<f64> {
        // SAFETY: as for `get`; the tag field is the word's high 16 bits (little endian).
        let word = unsafe { self.0.add(usize::from(register)) };
        let field = unsafe { word.cast::<u16>().add(3).read() };
        if !crate::value::tag_field_is_tagged(field) {
            return Some(unsafe { word.cast::<f64>().read() });
        }
        if u32::from(field) << 16 == crate::value::INT_TAG_HIGH {
            return Some(f64::from(unsafe { word.cast::<i32>().read() }));
        }
        None
    }

    /// `number`, and whether the register held an int32.
    #[inline(always)]
    fn number_kind(self, register: u16) -> Option<(f64, bool)> {
        // SAFETY: as for `number`.
        let word = unsafe { self.0.add(usize::from(register)) };
        let field = unsafe { word.cast::<u16>().add(3).read() };
        if !crate::value::tag_field_is_tagged(field) {
            return Some((unsafe { word.cast::<f64>().read() }, false));
        }
        if u32::from(field) << 16 == crate::value::INT_TAG_HIGH {
            return Some((f64::from(unsafe { word.cast::<i32>().read() }), true));
        }
        None
    }

    #[inline(always)]
    fn i32(self, register: u16) -> i32 {
        self.get(register).wasm_bits32() as i32
    }
}

/// The direct memory bytes behind the active function's memory register.
/// The view is resolved whenever that register can change under the lane:
/// at lane entry, when a lane call or return switches functions, and when
/// the binding instruction loads the register; no other lane instruction
/// writes it (see `LaneView`). The lane never collects, calls out or grows
/// memory, so the bytes stay alive, unborrowed and unresized at a stable
/// address. A memory the lane cannot borrow resolves to the empty view, on
/// which every access leaves the lane.
/// A carried value a record may leave unset: the accumulator after a record that produces
/// none, which only the record a producer falls through to reads, and a JavaScript view's
/// memory reach, which no JavaScript record reads. An unset slot costs its dispatch no
/// instruction; a reader gets one only where the view proves it was set.
#[derive(Clone, Copy)]
#[repr(transparent)]
struct Slot<T: Copy>(std::mem::MaybeUninit<T>);

impl<T: Copy> Slot<T> {
    #[inline(always)]
    const fn of(value: T) -> Self {
        Self(std::mem::MaybeUninit::new(value))
    }

    #[inline(always)]
    const fn unset() -> Self {
        Self(std::mem::MaybeUninit::uninit())
    }

    /// SAFETY: the slot was set (`Slot::of`) on the way here.
    #[inline(always)]
    unsafe fn get(self) -> T {
        unsafe { self.0.assume_init() }
    }
}

#[derive(Clone, Copy)]
struct MemoryView {
    bytes: *mut u8,
    /// The memory's length less the widest direct access: an access
    /// starting at or below it is in bounds whatever its width, so the hot
    /// path compares the address alone. Negative when the memory is
    /// narrower than that access. Unset in a JavaScript view (`MemoryView::script`).
    reach: Slot<isize>,
}

/// The widest access a lane record makes directly.
const WIDEST_DIRECT_ACCESS: usize = size_of::<u64>();

impl MemoryView {
    const NONE: Self = Self::new(std::ptr::null_mut(), 0);

    /// A JavaScript run's view. JavaScript binds no memory (`frame_memory_view`), so the
    /// register a Wasm view's bytes take carries the run's context instead, which
    /// `script_handler!` handlers read without the thread-local load. Its reach is unset: no
    /// JavaScript record accesses memory.
    #[inline(always)]
    fn script<H: Host>(cx: *mut LaneContext<H>) -> Self {
        Self {
            bytes: cx.cast(),
            reach: Slot::unset(),
        }
    }

    const fn new(bytes: *mut u8, len: usize) -> Self {
        Self {
            bytes,
            reach: Slot::of(len as isize - WIDEST_DIRECT_ACCESS as isize),
        }
    }

    /// Direct load `load` at `address`, when the access lies within the
    /// reach; `None` leaves it to the general path, which also decides the
    /// last bytes before the memory's end exactly.
    ///
    /// SAFETY: the view must have been resolved during the current lane run.
    #[inline(always)]
    unsafe fn read(self, load: MemoryLoad, address: u64) -> Option<crate::WasmValue> {
        // Addresses are at most 33 bits, so the signed comparison is exact.
        if (address as i64) > unsafe { self.reach.get() } as i64 || load.width() > WIDEST_DIRECT_ACCESS {
            // Off the hot path: the access falls through to its dispatch.
            std::hint::cold_path();
            return None;
        }
        // SAFETY: the access ends at or before the memory's end.
        Some(unsafe { load.read_at(self.bytes.add(address as usize)) })
    }

    /// Direct store `store` of `value` at `address`, as for `read`.
    ///
    /// SAFETY: the view must have been resolved during the current lane run.
    #[inline(always)]
    unsafe fn write(self, store: MemoryStore, address: u64, value: crate::WasmValue) -> Option<()> {
        // Addresses are at most 33 bits, so the signed comparison is exact.
        if (address as i64) > unsafe { self.reach.get() } as i64 || store.width() > WIDEST_DIRECT_ACCESS {
            std::hint::cold_path();
            return None;
        }
        // SAFETY: the access ends at or before the memory's end.
        unsafe { store.write_at(self.bytes.add(address as usize), value) };
        Some(())
    }
}

/// The state handlers carry from one to the next in machine registers.
#[derive(Clone, Copy)]
struct Carried {
    memory: MemoryView,
    integers: crate::value::IntegerEncoding,
    /// The value an accumulator producer just wrote to its result register.
    /// A record reads it only where the view proved it equals that register; unset after
    /// any other record.
    acc: Slot<Value>,
}

impl Carried {
    /// What a JavaScript record that produces no accumulator carries on: the run's view
    /// (`MemoryView::script`), tagged integers, and no accumulator, which only the record
    /// after a producer reads. Passing this instead of the incoming state frees the
    /// registers the rest of that state would occupy across the record.
    #[inline(always)]
    fn script<H: Host>(cx: *mut LaneContext<H>) -> Self {
        Self {
            memory: MemoryView::script(cx),
            integers: crate::value::IntegerEncoding::TAG,
            acc: Slot::unset(),
        }
    }

    /// `script` with the integer encoding `incoming` carried in: the same constant
    /// (`IntegerEncoding::TAG`), passed on in the register it arrived in, so a record makes no
    /// copy of it for the next.
    #[inline(always)]
    fn script_in<H: Host>(cx: *mut LaneContext<H>, incoming: Carried) -> Self {
        Self { integers: incoming.integers, ..Self::script(cx) }
    }

    /// What the general step of `instruction` carries on: `script_in`, with the accumulator its
    /// result register now holds, since the record was selected as an accumulator producer
    /// (`LaneHandler::produces`) and the next record may read the accumulator for it.
    #[inline(always)]
    fn stepped<H: Host>(cx: *mut LaneContext<H>, incoming: Carried, r: Registers, instruction: WideInstruction) -> Self {
        let produced = matches!(instruction.op().field_layout(InstructionField::A), FieldLayout::ResultRegister);
        let acc = if produced { Slot::of(r.get(instruction.result_register())) } else { Slot::unset() };
        Self { acc, ..Self::script_in(cx, incoming) }
    }
}

/// The capacity the lane stack reserves once (virtual until touched): values and activations
/// keep their addresses below it.
const LANE_STACK_VALUES: usize = 1 << 20;
const LANE_STACK_ACTIVATIONS: usize = 1 << 16;

/// An activation a lane call made without a VM frame. Its registers are
/// a window of the lane stack; it returns to the record after `call` in its
/// caller, whose registers, view and memory it keeps for the return.
#[derive(Clone, Copy)]
#[repr(C, align(128))]
pub(in crate::vm) struct Activation {
    /// The native prefix: the callee's descriptor, receiver, body and window, which emitted
    /// code writes for a direct call's frame (`ActivationKind::Native`) and which stays through
    /// its link (`NativeFrames`); only `window` for an activation the lane made.
    pub(in crate::vm) native: super::compiled::ShadowFrame,
    function: u32,
    call: Ip,
    caller_base: Ip,
    caller_registers: Registers,
    /// The program its caller runs, which its return makes the lane's again
    /// (`lane_enter_program`); its own is the next activation's caller program, or the
    /// lane's for the innermost.
    caller_program: ProgramId,
    kind: ActivationKind,
}

/// The tags of `ActivationKind`: the discriminants, which emitted code writes as the first
/// word of the kind (`NATIVE_TAG`) and the lane reads to tell a native frame from an activation.
pub(in crate::vm) use quench_bjit::shared_words::KIND_NATIVE;
/// Where the kind's tag lies in an activation.
pub(in crate::vm) const KIND_OFFSET: usize = std::mem::offset_of!(Activation, kind);
const KIND_SCRIPT: u8 = 1;
const KIND_WASM: u8 = 2;

/// What an activation keeps beyond its registers, by the kind of function it runs.
#[derive(Clone, Copy)]
#[repr(C, u8)]
enum ActivationKind {
    /// A native direct call's frame as emitted code wrote it: only the prefix words
    /// (`Activation::native`, the callee's descriptor, receiver, body and window) and this
    /// tag, no link state. `NativeFrames::link` makes it a `Script` activation when the lane
    /// first observes it; the prefix stays, as the descriptor of the frame above it.
    #[allow(dead_code)] // written by emitted code (`call_frames`), read as the tag
    Native = KIND_NATIVE,
    Script(ScriptActivation) = KIND_SCRIPT,
    /// A Wasm activation keeps its caller's memory for the return and its requested
    /// register payload for guest-stack accounting, excluding admission padding.
    Wasm { memory: MemoryView, frame_storage_bytes: usize } = KIND_WASM,
    /// A Wasm activation a JavaScript call of an exported function made
    /// (`lane_wasm_export_frame`): it runs over `instance`, the export's instance environment
    /// (`LaneContext::instance`), and its return gives its caller, JavaScript, the result's
    /// JavaScript form (`CallCompletion::WasmExport`). The caller's receiver and environments
    /// stay in the context while it runs: no Wasm record reads or writes them.
    WasmEntry { instance: Value, result: Option<crate::WasmType>, frame_storage_bytes: usize },
}

const _: () = {
    assert!(KIND_OFFSET % std::mem::size_of::<u64>() == 0);
};

impl Activation {
    /// The frame state of a JavaScript activation; `None` for Wasm and for a native frame
    /// the lane has not linked (`NativeFrames`), which no lane code observes.
    #[inline] fn script(&self) -> Option<&ScriptActivation> {
        match &self.kind {
            ActivationKind::Script(script) => Some(script),
            ActivationKind::Native | ActivationKind::Wasm { .. } | ActivationKind::WasmEntry { .. } => None,
        }
    }

    /// The pc of the call record this activation was entered from, in its caller's body
    /// (`caller_base`); `None` for a native frame, which keeps no link state.
    fn caller_pc(&self) -> Option<usize> {
        // SAFETY: a linked activation's call record lies in its caller's body.
        (!matches!(self.kind, ActivationKind::Native)).then(|| unsafe { self.call.offset_from(self.caller_base) } as usize)
    }

    /// The memory view its caller runs with: a JavaScript activation's caller is JavaScript,
    /// whose view carries the context (`MemoryView::script`).
    fn caller_memory<H: Host>(&self, cx: *mut LaneContext<H>) -> MemoryView {
        match self.kind {
            ActivationKind::Native | ActivationKind::Script(_) | ActivationKind::WasmEntry { .. } => MemoryView::script(cx),
            ActivationKind::Wasm { memory, .. } => memory,
        }
    }

    #[inline] fn frame_storage_bytes(&self) -> usize {
        match self.kind {
            ActivationKind::Native | ActivationKind::Script(_) => 0,
            ActivationKind::Wasm { frame_storage_bytes, .. } | ActivationKind::WasmEntry { frame_storage_bytes, .. } => frame_storage_bytes,
        }
    }
}

/// What a JavaScript activation's frame would hold beyond its registers
/// (`Vm::activate_plain_frame`), and the caller's lane state its return restores. Its own
/// receiver and environment live in the context while it runs (`LaneContext::this`, `env`)
/// and in the next script activation's caller state beneath that (`ActivationState::of`):
/// one fact, held once.
#[derive(Clone, Copy)]
struct ScriptActivation {
    callee: Value,
    /// Arguments passed, all in parameter registers.
    argc: u16,
    /// What its return yields to the call.
    completion: Completion,
    /// The `argc` values passed follow the registers in the window, for a forwarded
    /// `arguments` (`ScriptCallTarget::forwards`), for the construction a skipped
    /// forwarding constructor passed on (`Completion::Forwarder`), or for values passed past
    /// the parameters.
    forwards: bool,
    /// The register past its registers that holds the first value it kept (`forwards`), its
    /// function's register count, so a read of them looks up no function; 0 when it keeps none.
    kept: u16,
    /// Its environment and frame locals follow its registers (`CallEntry::Environment`).
    environment: bool,
    /// The record of the suspended frame a windowed activation runs over (`generator_windows`,
    /// `lane_roots`), which the lane's name lookups read the dynamic bindings of; null for any
    /// other activation.
    record: *mut super::activation::FrameRecord,
}

/// A JavaScript activation's own receiver and environment, which it does not store
/// (`ScriptActivation`).
#[derive(Clone, Copy)]
struct ActivationState {
    this: Value,
    env: Value,
    /// The program it runs.
    program: ProgramId,
}

impl Activation {
    /// The address of this activation's first register: its prefix's WINDOW word without its
    /// mark (`HEAP_WINDOW`), which names the lane stack's values by default and any other
    /// register file (a generator's) alike.
    #[inline(always)]
    pub(in crate::vm) fn window_ptr(&self) -> *mut Value {
        (self.native.window & !HEAP_WINDOW) as *mut Value
    }

    /// The prefix's WINDOW word as it stands, which a return hands the lane stack's values to
    /// free the window if the stack holds it (`LaneValues::release_window`).
    #[inline(always)]
    pub(in crate::vm) fn window_word(&self) -> usize {
        self.native.window
    }

    /// The first `len` values from the window: its registers, and what follows them
    /// (`ScriptActivation::forwards`, `environment`).
    ///
    /// # Safety
    /// The window holds `len` initialized values, which nothing else writes while the slice lives.
    #[inline(always)]
    unsafe fn window(&self, len: usize) -> &[Value] {
        unsafe { std::slice::from_raw_parts(self.window_ptr(), len) }
    }
}

impl ActivationState {
    /// Each activation's state, innermost from the context, each other's from the caller
    /// state the next script activation above it saved. A Wasm activation changes neither
    /// receiver nor environment; every activation names its caller's program.
    fn of<H: Host>(activations: &[Activation], cx: *mut LaneContext<H>) -> Vec<Self> {
        let mut current = unsafe { Self { this: Value::UNDEFINED, env: (*cx).registers.env(), program: (*cx).program } };
        let mut states = vec![current; activations.len()];
        for (state, activation) in states.iter_mut().zip(activations).rev() {
            *state = current;
            current.program = activation.caller_program;
        }
        // Each script activation's receiver is its window's context word; a Wasm activation
        // runs with its caller's, the frame's below the first.
        let first = activations.first().map(|first| first.caller_registers);
        let mut this = first.map_or(Value::UNDEFINED, Registers::this);
        let mut env = first.map_or(Value::DELETED, Registers::env);
        for (state, activation) in states.iter_mut().zip(activations) {
            if activation.script().is_some() {
                let window = Registers(activation.window_ptr());
                (this, env) = (window.this(), window.env());
            }
            (state.this, state.env) = (this, env);
        }
        states
    }
}

/// What a JavaScript activation's return yields to its call: one byte, so a plain return
/// tests it once.
#[derive(Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
enum Completion {
    /// The returned value.
    Plain,
    /// The returned value, from an activation of another program than its caller's, whose
    /// return makes the caller's program the lane's again (`lane_enter_program`).
    Cross,
    /// A `new` made it: `this` unless it returns an object.
    Constructs,
    /// A `new` of another program's constructor: `Constructs`, whose return makes the
    /// caller's program the lane's again as `Cross` does.
    CrossConstructs,
    /// It runs the method a forwarding constructor's body would have called
    /// (`ScriptCallTarget::forwarded_method`), whose frame `LaneStack::forwarders` keeps the
    /// last entry of: the construction yields `this`, the receiver, whatever it returns.
    Forwarder,
    /// A native's call of JavaScript run frameless from the lane that called the native
    /// (`Vm::lane_native_callback`): its return ends that run with the value, which the
    /// native receives. Made a frame, it is the entry frame of the general loop that finishes
    /// it, which no pending call names.
    ReturnsToNative,
    /// `Generates` of a for-of step whose `done` and `value` reads its records make
    /// (`lane_iterator_step_reads`): a yield or return writes them to those reads' registers and
    /// the caller goes on past them, the result object unmade. Made a frame, it is `Generates`.
    StepReads(ForOfTest),
    /// A plain call of a non-suspending async function of the caller's program
    /// (`CallEntry::Settles`): its return resolves the promise the call made, which
    /// `LaneStack::settling` keeps, and the call yields that promise. Made a frame, its
    /// pending call settles it (`PendingGeneralCall::completion`).
    SettlesPromise,
    /// A store's setter (`setters::lane_store_setter`): the assignment yields the value
    /// stored, which its record's register still holds, whatever the setter returns. Made a
    /// frame, its pending call yields it the same way (`CallCompletion::Assigned`).
    Assigns,
    /// A proxy `get` trap (`proxy_traps::lane_read_get_trap`): the read's value, once the
    /// target's invariants have checked it (`LaneStack::trap_checks`); a read the target's
    /// changed shape now constrains returns from the trap's frame, whose pending call checks
    /// it in full (`CallCompletion::Trapped`).
    ReadsTrapped,
    /// A proxy `set` trap (`proxy_traps::lane_store_set_trap`): `Assigns` for a trap whose
    /// result the target and a strict store accept, checked as `ReadsTrapped` is.
    AssignsTrapped,
    /// An array callback method's callback the lane runs for one element
    /// (`lane_begin_array_iteration`): its return steps the iteration `LaneStack::steps`
    /// keeps (`lane_step_array_iteration`). Made a frame, its pending call finishes the
    /// iteration on the native's path (`CallCompletion::ArrayStep`).
    ArrayStep,
    /// A plain call a lane body made of a callee that runs in the lane (`body_calls`): its
    /// return ends that nested run with the value, which the body's call takes. Made a
    /// frame, it is a plain call's.
    ReturnsToBody,
    /// `ReturnsToBody` of a body's `new`. Made a frame, it is a construction's.
    ConstructsToBody,
    /// A Wasm call of a JavaScript-backed import (`wasm_calls::lane_activate_js_import`), of
    /// another program than its Wasm caller's: its return gives the caller the value's Wasm
    /// form and runs the caller's program and instance again, as `LaneStack::to_wasm` keeps
    /// them (`lane_complete_to_wasm`). Made a frame, its pending call converts the value
    /// (`CallCompletion::ToWasm`).
    ToWasm,
    /// A generator the lane resumed over its suspended frame's register file
    /// (`generator_windows`): its `yield` suspends it back into the record and its return
    /// completes it, the call yielding the step's iterator result, which only a step's
    /// `done` and `value` reads observe (`Vm::reused_iterator_result`). The activation's
    /// callee is the generator. Made a frame, its pending call completes the step
    /// (`CallCompletion::Generator`).
    Generates,
    /// `Generates` for a `yield*` step of a delegate generator: the step's fresh result goes to
    /// the delegating record's state register, which that record, made again, reads
    /// (`lane_yield_star`).
    Delegates,
    /// The async function or async generator a promise job resumed over its suspended frame's
    /// register file, the root of its lane run (`LaneRoot::Job`, `Vm::run_lane_job`): its
    /// `await` suspends it back into its owner (`lane_await`) and its return ends the run with
    /// the value, which the job delivers. No call record is its caller's. Made a frame, it is
    /// the entry frame of the general loop that finishes it, which no pending call names. The
    /// activation's callee is its owner.
    ResumesJob,
}

/// A JavaScript-backed import's call facts, fixed by its wrapper (`Cell::WasmHostFunction`):
/// the wrapper and its realm, the JavaScript callee, the scalar kind of each parameter
/// (`JS_IMPORT_I32`, `_F32`, `_F64`) and the result type.
#[derive(Clone, Copy)]
pub(super) struct JsImportPlan {
    pub(super) wrapper: Value,
    pub(super) realm: Value,
    pub(super) callee: Value,
    pub(super) argc: u8,
    pub(super) kinds: [u8; JS_IMPORT_ARGUMENTS],
    pub(super) result: Option<crate::WasmType>,
}

/// The most parameters an activated import passes (`JsImportPlan`).
pub(super) const JS_IMPORT_ARGUMENTS: usize = 8;
pub(super) const JS_IMPORT_I32: u8 = 0;
pub(super) const JS_IMPORT_F32: u8 = 1;
pub(super) const JS_IMPORT_F64: u8 = 2;

/// What a `Completion::ToWasm` activation's return restores of its Wasm caller: the instance
/// it ran over (`LaneContext::instance`), the memory binding its view was of, read again on
/// return since the callee may grow the memory, and the import's result type.
#[derive(Clone, Copy)]
pub(super) struct ToWasmCall {
    pub(super) instance: Value,
    pub(super) memory: Option<Value>,
    pub(super) result: Option<crate::WasmType>,
}

impl Completion {
    /// The completion of an activation a `new` made or not, of the caller's program or not,
    /// of a target whose return settles its call's promise or not. Only a plain call of the
    /// caller's program settles one (`lane_script_call_settles`).
    #[inline] fn of(constructs: bool, cross: bool, settles: bool) -> Self {
        debug_assert!(!settles || !constructs && !cross, "only a plain call of its own program settles");
        match (constructs, cross, settles) {
            (false, false, true) => Self::SettlesPromise,
            (false, false, false) => Self::Plain,
            (false, true, _) => Self::Cross,
            (true, false, _) => Self::Constructs,
            (true, true, _) => Self::CrossConstructs,
        }
    }

    /// Whether a `new` made the activation, whose completion substitutes its receiver for a
    /// non-object result.
    #[inline] fn constructs(self) -> bool {
        matches!(self, Self::Constructs | Self::CrossConstructs | Self::ConstructsToBody)
    }

    /// Whether the activation runs a generator over its record's register file.
    #[inline] fn is_generator(self) -> bool {
        matches!(self, Self::Generates | Self::Delegates | Self::StepReads(_))
    }

    /// Whether a generator's step yields this realm's reused iterator result, which only the
    /// step's own reads observe: a delegate's step makes it fresh.
    #[inline] fn reuses_result(self) -> bool {
        matches!(self, Self::Generates | Self::StepReads(_))
    }

    /// Whether the activation runs over the register file of a heap record's frame, a
    /// generator's or a job's, which names its owner as its callee.
    #[inline] fn is_windowed(self) -> bool {
        self.is_generator() || self == Self::ResumesJob
    }

    /// Whether the activation's return makes the caller's program the lane's again.
    #[inline] fn crosses(self) -> bool {
        matches!(self, Self::Cross | Self::CrossConstructs)
    }
}

/// A forwarding constructor whose activation a construction skipped
/// (`lane_forwarded_construction`): what its frame holds when activations become frames,
/// pending at its forwarding call.
#[derive(Clone, Copy)]
pub(in crate::vm) struct SkippedForwarder {
    pub(in crate::vm) function: u32,
    pub(in crate::vm) callee: Value,
    pub(in crate::vm) env: Value,
    pub(in crate::vm) method: crate::bytecode::ForwardedThisMethod,
}

/// Where a lane activation's arguments come from: a window of the caller's registers, or
/// values a forwarding activation or frame kept (`f.apply(this, arguments)`).
#[derive(Clone, Copy)]
enum ActivationArguments {
    Window(u16),
    Kept(*const Value, usize),
}

/// A user function a lane `Call` may activate without a frame, valid as the general loop's
/// `InLoopCallTarget` is: for `callee` while the collection epoch and realm it was resolved
/// under hold, which its `generation` names. A target serves calls from `program`, the
/// callee's own, or, held apart (`LaneStack::cross_targets`), from any other program, whose
/// calls it only activates, switching the lane to its program (`lane_enter_program`).
#[derive(Clone, Copy)]
pub(super) struct ScriptCallTarget {
    callee: Value,
    /// The generation it was resolved in and the program it serves (`Admission`).
    admission: Admission,
    pub(super) function: u32,
    env: Value,
    pub(super) view: *const LaneView,
    registers: u16,
    /// The lane-stack room its plain activation reserves (`fill_room::<SCRIPT_FILL_BLOCK>` of
    /// `registers`), derived once.
    room: u16,
    params: u16,
    /// How a call binds its `this` (`ThisBinding`).
    this_binding: ThisBinding,
    /// An arrow's own `this` (`ThisBinding::Lexical`), found in its environment when it was
    /// resolved; unused for any other binding.
    lexical_this: Value,
    /// `TARGET_CONSTRUCTS` where `new` may activate it too (`Vm::inline_constructible`), and
    /// `TARGET_INITIALIZES` where `new` may run its body as the stores alone
    /// (`Function::only_initializes_this_fields`).
    forms: u8,
    /// The registers its plain activation starts `undefined` (`RegisterRoots::entry_fill`),
    /// at most `u8::MAX`: past one `WINDOW_FILL_BLOCK` it starts every register so.
    fill: u8,
    /// How a plain call enters it.
    entry: CallEntry,
    /// The dense storage header its depth-0 captures read (`LaneContext::capture`), or null where the walk
    /// does not end at a function environment or its storage is sparse. The storage of a live environment never
    /// moves, and the generation retires the target at the next collection.
    capture: *const usize,
    /// The `LaneStack::forwarded_methods` index of a constructor body forwarding to a method
    /// of `this` (`Function::forwarded_this_method`), which a construction may activate
    /// directly, or `NO_FORWARDED_METHOD`. An index, not the record, keeps every target's
    /// cache entry its size.
    forwarded_method: u16,
}

mod call_entry;
use call_entry::CallEntry;

// Recognized once per target, as it resolves; no operation runs them.
#[path = "call_body_forms.rs"]
mod call_body_forms;
use call_body_forms::{body_entry, leaf_body};

/// `ScriptCallTarget::forms`: `new` may activate it.
const TARGET_CONSTRUCTS: u8 = 1;
/// `ScriptCallTarget::forms`: `new` may run its body as the stores alone.
const TARGET_INITIALIZES: u8 = 2;
/// `ScriptCallTarget::forms`: a rest body (`CallEntry::Gathers`) that keeps the values it was
/// passed, for a kept `arguments` (`CallPlan::keeps_arguments`) or legacy reflection of a
/// sloppy function's; any other's rest array holds every value past its parameters.
const TARGET_GATHERS_KEEPING: u8 = 4;
/// `ScriptCallTarget::forms`: a rest body whose rest parameter only `RestGet` and
/// `RestLength` read (`Function::rest_view`): a plain call's activation keeps the values
/// passed and makes no rest array (`lane_activate_gathering`).
const TARGET_REST_VIEW: u8 = 8;
/// `ScriptCallTarget::forms`: an arrow that may read its maker's implicit bindings
/// (`Function::arrow_reads_implicit_bindings`), whose sibling closures read their own
/// lexical `this` (`sibling_closure_target`).
const TARGET_READS_IMPLICIT: u8 = 16;

impl ScriptCallTarget {
    /// `new` may activate it too (`Vm::inline_constructible`).
    #[inline(always)]
    fn constructs(&self) -> bool {
        self.forms & TARGET_CONSTRUCTS != 0
    }

    /// `new` may run its body as the stores alone (`Function::only_initializes_this_fields`).
    #[inline(always)]
    fn initializes(&self) -> bool {
        self.forms & TARGET_INITIALIZES != 0
    }

    /// The registers its activation starts with their initial value: `fill`, exact below
    /// `u8::MAX`, else every register.
    #[inline(always)]
    fn entry_registers(&self) -> usize {
        if self.fill < u8::MAX { usize::from(self.fill) } else { usize::from(self.registers) }
    }

    /// No legacy `arguments` reflection observes its activation: a strict function's or an
    /// arrow's (`Function::has_restricted_legacy_caller_access`), which its `this` binding
    /// names. A call passing values past its parameters need not keep them, as its frame
    /// would not (`Vm::initialize_frame_invocation`); a sloppy function's keeps them.
    #[inline(always)]
    fn drops_extra_arguments(&self) -> bool {
        !matches!(self.this_binding, ThisBinding::Sloppy)
    }

    /// It keeps the values it was passed for a forwarded `arguments`.
    #[inline(always)]
    fn forwards(&self) -> bool {
        matches!(self.entry, CallEntry::Keeps | CallEntry::Gathers)
    }

    /// Its activation's return settles its call's promise (`Completion::SettlesPromise`).
    #[inline(always)]
    fn settles(&self) -> bool {
        self.entry == CallEntry::Settles
    }
}

/// A lane run's generation (`LaneStack::generation`), narrow so a cache entry stays one
/// line; its wrap clears every entry, so no stale one can match a reused number.
type ScriptGeneration = u32;

/// A generation and a program in one word, so admitting a cached target or memo against the
/// running lane (`LaneStack::admission`) is one compare.
#[derive(Clone, Copy, PartialEq, Eq)]
struct Admission(u64);

impl Admission {
    /// Where the program sits in the word: above the generation.
    const PROGRAM_SHIFT: u32 = ScriptGeneration::BITS;

    #[inline(always)]
    const fn new(generation: ScriptGeneration, program: ProgramId) -> Self {
        Self(generation as u64 | (program.raw() as u64) << Self::PROGRAM_SHIFT)
    }

    /// A bit no target's or memo's admission has: the lane's carries it while a condition
    /// no cached call may run under holds (`LaneStack::refuse_cached_calls`), so every
    /// admission fails, and the paths that resolve again decide.
    const REFUSED: u64 = 1 << 63;

    #[inline(always)]
    const fn generation(self) -> ScriptGeneration {
        self.0 as u32
    }

    #[inline(always)]
    const fn program(self) -> ProgramId {
        ProgramId::from_raw((self.0 >> Self::PROGRAM_SHIFT) as u32)
    }
}

impl ScriptCallTarget {
    #[inline(always)]
    fn generation(&self) -> ScriptGeneration {
        self.admission.generation()
    }

    #[inline(always)]
    pub(super) fn program(&self) -> ProgramId {
        self.admission.program()
    }
}

/// The rest values a gathering activation collects inline before its array is made.
const GATHERED_INLINE_VALUES: usize = 8;

/// The size a script call cache entry keeps, one cache line, which each call reads.
const SCRIPT_CALL_TARGET_BYTES: usize = 64;
const _: () = assert!(std::mem::size_of::<ScriptCallTarget>() <= SCRIPT_CALL_TARGET_BYTES);

/// A `ScriptCallTarget::forwarded_method` that names no record. A program with more distinct
/// forwarding bodies than the index spans leaves the rest unrecorded.
const NO_FORWARDED_METHOD: u16 = u16::MAX;

const EMPTY_SCRIPT_CALL_TARGET: ScriptCallTarget = ScriptCallTarget {
    callee: Value::UNDEFINED,
    admission: Admission::new(NO_SCRIPT_GENERATION, ProgramId::MAIN),
    function: 0,
    env: Value::UNDEFINED,
    view: std::ptr::null(),
    registers: 0,
    room: 0,
    params: 0,
    this_binding: ThisBinding::Sloppy,
    lexical_this: Value::UNDEFINED,
    forms: 0,
    fill: 0,
    entry: CallEntry::Activates,
    capture: std::ptr::null(),
    forwarded_method: NO_FORWARDED_METHOD,
};

/// Entries of the script call cache, in sets of `SCRIPT_TARGET_WAYS` that a hash of the
/// callee's heap index picks (`ScriptTargets::set`), at most, under each memory policy
/// (`MemoryPolicy` order): Express's router calls a matcher closure per layer, some 400
/// distinct callees a request, which 256 entries thrashed (Callgrind: 2.4% of a ping request
/// re-resolving). 1024 still met conflicts in their two-way sets, re-resolving 34 callees a
/// body request (~380 instructions each); 4096 (256 KiB per table, reached only by a cache
/// that keeps displacing live targets) cut express body and ping 1.3% (Callgrind, per
/// request). Memory-first stops at 1024: a long run that displaces a few targets at a time
/// reaches the larger size too (EarleyBoyer, both tables: +220 KiB anonymous peak).
const SCRIPT_CALL_TARGETS: [usize; crate::MemoryPolicy::ALL.len()] = [4096, 1024];

/// The largest script call cache `policy` allows.
fn script_call_targets(policy: crate::MemoryPolicy) -> usize {
    SCRIPT_CALL_TARGETS[policy as usize]
}
/// Entries a script call cache starts with: a program that calls few distinct callees keeps
/// 16 KiB per table resident instead of 64 (V8-v7 max RSS, both tables: about 100 KiB per
/// fixture). A cache grows to `SCRIPT_CALL_TARGETS` by this factor each time it has
/// displaced more live targets than it holds.
const SCRIPT_CALL_TARGETS_INITIAL: usize = 256;
const SCRIPT_CALL_TARGETS_GROWTH: usize = 4;
const _: () = {
    assert!(SCRIPT_CALL_TARGETS_INITIAL.is_power_of_two() && SCRIPT_CALL_TARGETS_GROWTH.is_power_of_two());
    let mut policy = 0;
    while policy < SCRIPT_CALL_TARGETS.len() {
        let most = SCRIPT_CALL_TARGETS[policy];
        assert!(most.is_power_of_two() && SCRIPT_CALL_TARGETS_INITIAL <= most && most <= NO_CALL_LINK as usize);
        policy += 1;
    }
};
/// Entries per set: the one most recently resolved first, then the one before it, so two
/// callees whose indices share a set both stay resolved.
const SCRIPT_TARGET_WAYS: usize = 2;
const _: () = assert!(SCRIPT_TARGET_WAYS == 2);

/// A script call cache (`LaneStack::script_targets`, `cross_targets`): sets of
/// `SCRIPT_TARGET_WAYS` entries, growing from `SCRIPT_CALL_TARGETS_INITIAL` entries.
/// Entry pointers (`Vm::script_call_entry`) are not held across a resolution, which is
/// where it grows.
struct ScriptTargets {
    entries: Box<[ScriptCallTarget]>,
    /// Live targets displaced from their set since it last grew.
    displaced: usize,
    /// The hash shift of its sets (`shape_memo::direct_mapped_shift`), derived with its size.
    set_shift: u32,
}

impl ScriptTargets {
    fn with_len(len: usize) -> Self {
        Self {
            entries: vec![EMPTY_SCRIPT_CALL_TARGET; len].into_boxed_slice(),
            displaced: 0,
            set_shift: super::shape_memo::direct_mapped_shift(len / SCRIPT_TARGET_WAYS),
        }
    }

    /// The first entry of `callee`'s set, when it names a heap cell; the set's other entry
    /// follows it (`| 1`). The set is the shared direct-mapped index of the heap index
    /// (`shape_memo::direct_mapped_index`): a family's closures take indices at a fixed
    /// stride, which a multiplicative hash of the index alone crowds into a few sets.
    #[inline(always)]
    fn set(&self, callee: Value) -> Option<usize> {
        Some(super::shape_memo::direct_mapped_index_by_shift(callee.heap_index()?, self.set_shift) * SCRIPT_TARGET_WAYS)
    }

    /// Record `target` first in its set, the entry it displaces moving second; a cache that
    /// has displaced more live targets than it holds grows, empty, before recording it, up to
    /// `most` entries.
    fn remember(&mut self, target: ScriptCallTarget, most: usize) {
        let Some(set) = self.set(target.callee) else {
            return;
        };
        if self.entries[set].callee != target.callee {
            if self.entries[set | 1].generation() == target.generation() {
                self.displaced += 1;
            }
            self.entries[set | 1] = self.entries[set];
        }
        self.entries[set] = target;
        if self.displaced > self.entries.len() && self.entries.len() < most {
            *self = Self::with_len(self.entries.len() * SCRIPT_CALL_TARGETS_GROWTH);
            self.remember(target, most);
        }
    }

    fn clear(&mut self) {
        self.entries.fill(EMPTY_SCRIPT_CALL_TARGET);
        self.displaced = 0;
    }
}

impl std::ops::Index<usize> for ScriptTargets {
    type Output = ScriptCallTarget;
    #[inline(always)]
    fn index(&self, index: usize) -> &ScriptCallTarget {
        &self.entries[index]
    }
}

/// Entries of the function target memo (`LaneStack::function_targets`), one per function
/// id modulo the count: a closure first called finds its function's target derived when a
/// closure of the same function was resolved before, as each call of a closure-making
/// function makes a new one. A conflict overwrites the entry, which only costs the next
/// closure of the displaced function a full resolution.
const FUNCTION_TARGETS: usize = 64;
const _: () = assert!(FUNCTION_TARGETS.is_power_of_two());

/// Where a forwarding constructor's reads of `this.<method>` and its `apply` resolved under
/// a construct plan (`ConstructPlan::forwarded`). The plan's dependency covers the plan's
/// prototype (the method's slot value), the method (its shape and prototype, which could
/// shadow `apply`) and the holder of `apply`, so while the plan holds `method` is what the
/// forwarding reads and `apply` is the intrinsic: a use reads them from here.
#[derive(Clone, Copy)]
struct ForwardedResolution {
    method: Value,
    apply_holder: Value,
    /// The forwarded method's function whose initializer stores the plan's fields record
    /// (`lane_record_forwarded_fields`), when it has fields: the method this resolution
    /// reads must still be of it.
    initializer: Option<(ProgramId, u32)>,
}

/// Fields a `ConstructPlan` names; an initializer storing more keeps running its adds.
const CONSTRUCT_PLAN_FIELDS: usize = 8;
// A plan's values fill a receiver's inline slots (`ConstructPlan::allocate`).
const _: () = assert!(INLINE_PROPERTY_COUNT <= CONSTRUCT_PLAN_FIELDS);
// `ConstructPlan::defaulted` holds a bit per field.
const _: () = assert!(CONSTRUCT_PLAN_FIELDS <= u8::BITS as usize);

/// Entries of the construct plan cache, indexed by the callee's heap index.
const CONSTRUCT_PLANS: usize = 64;
const _: () = assert!(CONSTRUCT_PLANS.is_power_of_two());

/// A `ConstructPlan::epoch` no epoch reaches: the entry plans nothing.

/// Activations a lane runs without VM frames, innermost last, over the
/// bottom VM frame of the lane run. They exist only while the lane runs:
/// every exit makes them VM frames with pending calls, exactly as frame
/// pushes would have, so the general loop, traps and collection see the
/// usual frame stack. The register storage grows only between activations,
/// so register windows stay put while any exists.
pub(super) struct LaneStack {
    /// Per call record (by its `call_link`'s address), the callees it resolved or memoized,
    /// in the order first seen, up to `tier_policy::POLYMORPHISM` (`note_site_callee`): the targets a region
    /// inlines as a guarded switch (`lane_unit::unit`). A link's slot may hold another site's
    /// callee since; this record alone names the site's own. A collection drops the callees it
    /// swept (`forget_dead_callees`).
    call_sites: std::cell::RefCell<rustc_hash::FxHashMap<usize, smallvec::SmallVec<[super::compiled::CallTarget; INLINE_SITE_TARGETS]>>>,
    values: LaneValues,
    pub(in crate::vm) activations: LaneActivations,
    /// Wasm activation payload represented by `values` before lane materialization.
    wasm_storage_bytes: usize,
    /// Resolved targets of lane `Call` records (`Vm::script_call_entry`) of callees of the
    /// running program.
    script_targets: ScriptTargets,
    /// Resolved targets of callees of another program than the calling one, which those
    /// calls only activate (`Vm::resolve_script_call_target`): one per callee serves every
    /// other program, apart from the target its own program's calls use.
    cross_targets: ScriptTargets,
    /// The last target resolved for a closure of each function (`FUNCTION_TARGETS`), under
    /// its generation and program: every field but the closure's own (`callee`, `env`,
    /// `capture`, an arrow's `lexical_this`) depends on the function alone.
    function_targets: Box<[ScriptCallTarget; FUNCTION_TARGETS]>,
    /// `function_targets` of other programs' callees (`cross_targets`), whose closures a
    /// program's code makes afresh as often as its own.
    cross_function_targets: Box<[ScriptCallTarget; FUNCTION_TARGETS]>,
    /// Constructors' plans (`lane_initialize_fields`, `lane_planned_receiver`).
    construct_plans: Box<[ConstructPlan; CONSTRUCT_PLANS]>,
    /// Per plan, the one dependency its proof is (`watch_construct_plan`): published while
    /// every object the plan read keeps its values and layout.
    construct_watches: Box<[Option<crate::heap::PrototypeValueWatch>; CONSTRUCT_PLANS]>,
    /// The reads call sites answered (`ReadMemo`), each in the slot its record names
    /// (`CallOperand::memo`).
    read_memos: Vec<ReadMemo>,
    /// The forwarding constructors whose activations constructions skipped, one per
    /// `Completion::Forwarder` activation, innermost last.
    forwarders: Vec<SkippedForwarder>,
    /// The rooted promises of the `Completion::SettlesPromise` activations, innermost last:
    /// each activation's return resolves its own, which its frame's pending call takes when
    /// it materializes (`PendingGeneralCall::completion`). `None` for a call whose result
    /// only the `await` after it reads (`ImmediateLayout::LANE_CALL_RESULT_AWAITED_FLAG`): its
    /// promise is made only where one is observable, and a primitive return reaches the
    /// `await` as it is.
    settling: Vec<Option<crate::heap::RootId>>,
    /// The array iterations of the `Completion::ArrayStep` activations, innermost last; each
    /// activation's frame takes its own when it materializes (`CallCompletion::ArrayStep`).
    steps: Vec<LaneArrayStep>,
    /// The iterators the activations' `for-of` loops would close, each with the index of
    /// the activation whose loop pushed it (`IteratorCleanupPush`), innermost last: a
    /// frame's `active_iterators`, which the activation's frame takes when it materializes.
    /// A completion drops its activation's entries, as a frame's pop drops its list.
    iterators: Vec<(usize, super::ActiveIterator)>,
    /// What the `Completion::ReadsTrapped` and `AssignsTrapped` activations owe their targets'
    /// invariants, each with the index of its activation, innermost last; its frame takes it
    /// when it materializes (`CallCompletion::Trapped`).
    trap_checks: Vec<(usize, TrapCheck)>,
    /// What each `Completion::ToWasm` activation restores of its caller, innermost last; each
    /// activation's frame takes its result type when it materializes (`CallCompletion::ToWasm`).
    pub(super) to_wasm: Vec<ToWasmCall>,
    /// The JavaScript-backed import a Wasm call last activated (`wasm_calls::lane_activate_js_import`),
    /// read off its wrapper once; a collection forgets it (`forget_dead_callees`).
    pub(super) js_import: Option<JsImportPlan>,
    /// The bound function without bound arguments a `lane_function_call` last forwarded through,
    /// with its target and bound receiver, which never change (`Vm::bound_function_parts`); a
    /// collection forgets it (`forget_dead_callees`).
    pub(super) bound_call: Option<(Value, Value, Value)>,
    /// The `with` objects of the activations' scope chains (`with_scopes`), each with the index of
    /// the activation that owns it, innermost last: a frame's `with_objects`, which the
    /// activation's frame takes when it materializes. A completion drops its activation's
    /// entries, as a frame's pop truncates the VM's scope stack.
    with_objects: Vec<(usize, Value)>,
    /// The records ordinary activations made for a direct eval (`lane_eval`), each with the
    /// index of the activation that owns it, innermost last; the activation names it
    /// (`ScriptActivation::record`). A completion drops its activation's, and a materialization
    /// its frame's own state takes over: the environment the eval promoted.
    records: Vec<(usize, Box<super::activation::FrameRecord>)>,
    /// The forwarding constructor bodies call targets name (`ScriptCallTarget::forwarded_method`),
    /// each once: a program's bodies are fixed, so the table only grows with distinct ones.
    forwarded_methods: Vec<crate::bytecode::ForwardedThisMethod>,
    /// The activation count at which a JavaScript lane call leaves for
    /// `lane_script_call_frame`: the activations' capacity, the guest calls the thread still
    /// admits (the activations hold no guards; their frames take them when they materialize,
    /// which `lane_call_native` does before any guest code runs), or none while a collection
    /// is due (`note_allocation`). One comparison stands for the three.
    activation_limit: std::cell::Cell<usize>,
    /// Names the collection epoch and realm of the running lane, which no lane instruction
    /// changes: a target resolved under another generation is stale. Lane runs move between
    /// programs far more often than either changes, so each target names its program instead.
    generation: ScriptGeneration,
    /// `generation` and the running program (`Vm::active_program`), which a cached target's
    /// own admission must equal.
    admission: Admission,
    /// `Admission::REFUSED` once no cached call may run (`refuse_cached_calls`), else 0.
    refused: u64,
    /// The epoch and realm `generation` names.
    generation_key: (u64, Value),
    /// The boundary below a deferred native's callback while it runs (`NativeBoundary`).
    native_boundary: Option<NativeBoundary>,
    /// The frame the innermost activation a body's call runs in the lane became, once a
    /// materialization made it one (`body_calls::finish`): its return leaves the lane.
    body_boundary: Option<usize>,
    /// The frames the boundary's caller activations became, once a materialization made them.
    boundary_frames: Option<usize>,
    /// The exported Wasm function a JavaScript call last entered (`Vm::wasm_export_frame_call`),
    /// so the next call of it reads its closure and signature once. A collection forgets it.
    pub(super) wasm_export: Option<super::wasm_js::WasmExportCall>,
    /// The window plan last derived for a frame that made no environment of its own
    /// (`generator_windows::cached_window_plan`): every new activation of the same function
    /// under the same environment, as each call of an async function is, shares it.
    pub(super) last_window_plan: Option<(ProgramId, u32, generator_windows::WindowPlan)>,
}

/// The addresses a lane run's direct calls push onto (`Vm::lane_stack_words`).
#[derive(Clone, Copy)]
pub(in crate::vm) struct LaneStackWords {
    pub(in crate::vm) values_top: usize,
    pub(in crate::vm) values_end: usize,
    pub(in crate::vm) activations_top: usize,
    pub(in crate::vm) frames_end: usize,
}

/// A generation no lane runs under: an empty target entry never matches.
const NO_SCRIPT_GENERATION: ScriptGeneration = 0;

impl Default for LaneStack {
    fn default() -> Self {
        Self {
            values: LaneValues::with_capacity(LANE_STACK_VALUES),
            activations: LaneActivations::with_capacity(LANE_STACK_ACTIVATIONS),
            wasm_storage_bytes: 0,
            call_sites: std::cell::RefCell::default(),
            script_targets: ScriptTargets::with_len(SCRIPT_CALL_TARGETS_INITIAL),
            cross_targets: ScriptTargets::with_len(SCRIPT_CALL_TARGETS_INITIAL),
            function_targets: Box::new([EMPTY_SCRIPT_CALL_TARGET; FUNCTION_TARGETS]),
            cross_function_targets: Box::new([EMPTY_SCRIPT_CALL_TARGET; FUNCTION_TARGETS]),
            construct_plans: Box::new([EMPTY_CONSTRUCT_PLAN; CONSTRUCT_PLANS]),
            construct_watches: Box::new([const { None }; CONSTRUCT_PLANS]),
            read_memos: Vec::new(),
            forwarders: Vec::new(),
            settling: Vec::new(),
            steps: Vec::new(),
            iterators: Vec::new(),
            trap_checks: Vec::new(),
            to_wasm: Vec::new(),
            js_import: None,
            bound_call: None,
            with_objects: Vec::new(),
            records: Vec::new(),
            forwarded_methods: Vec::new(),
            activation_limit: std::cell::Cell::new(0),
            generation: NO_SCRIPT_GENERATION,
            admission: Admission::new(NO_SCRIPT_GENERATION, ProgramId::MAIN),
            refused: 0,
            generation_key: (0, Value::UNDEFINED),
            native_boundary: None,
            body_boundary: None,
            boundary_frames: None,
            wasm_export: None,
            last_window_plan: None,
        }
    }
}

impl LaneStack {
    /// Records a target of the running program's callee (`script_targets`), the cache
    /// growing up to what `policy` allows.
    fn remember_script_target(&mut self, target: ScriptCallTarget, policy: crate::MemoryPolicy) {
        self.script_targets.remember(target, script_call_targets(policy));
    }

    /// `remember_script_target` of another program's callee (`cross_targets`).
    fn remember_cross_target(&mut self, target: ScriptCallTarget, policy: crate::MemoryPolicy) {
        self.cross_targets.remember(target, script_call_targets(policy));
    }

    /// Forget resolved call targets, as the general loop's call target cache is reset.
    pub(super) fn clear_script_targets(&mut self) {
        self.script_targets.clear();
        self.cross_targets.clear();
        *self.function_targets = [EMPTY_SCRIPT_CALL_TARGET; FUNCTION_TARGETS];
        *self.cross_function_targets = [EMPTY_SCRIPT_CALL_TARGET; FUNCTION_TARGETS];
        self.read_memos.clear();
    }

    /// The target `function_targets` holds for a closure of `function` of `program` in this
    /// generation, or `cross_function_targets` for calls from another program, whose closure
    /// fields the caller rebinds.
    fn function_target(&self, program: ProgramId, function: u32, cross: bool) -> Option<ScriptCallTarget> {
        let targets = if cross { &self.cross_function_targets } else { &self.function_targets };
        let known = targets[function as usize & (FUNCTION_TARGETS - 1)];
        (known.generation() == self.generation && known.program() == program && known.function == function)
            .then_some(known)
    }

    /// Record `target` in its set and as its function's (`function_targets`), or a `cross`
    /// one in the other programs' tables.
    fn remember_function_target(&mut self, target: ScriptCallTarget, cross: bool, policy: crate::MemoryPolicy) {
        let index = target.function as usize & (FUNCTION_TARGETS - 1);
        if cross {
            self.cross_function_targets[index] = target;
            self.remember_cross_target(target, policy);
        } else {
            self.function_targets[index] = target;
            self.remember_script_target(target, policy);
        }
    }

    /// The index of `method` in `forwarded_methods`, recording it when new, or
    /// `NO_FORWARDED_METHOD` once the index space is spent.
    fn forwarded_method_index(&mut self, method: crate::bytecode::ForwardedThisMethod) -> u16 {
        if let Some(index) = self.forwarded_methods.iter().position(|known| *known == method) {
            return index as u16;
        }
        match u16::try_from(self.forwarded_methods.len()) {
            Ok(index) if index != NO_FORWARDED_METHOD => {
                self.forwarded_methods.push(method);
                index
            }
            _ => NO_FORWARDED_METHOD,
        }
    }

    /// Push `activation` onto the stack's reserved capacity, without `Vec::push`'s growth.
    ///
    /// # Safety
    /// The caller checked that the activations' capacity exceeds their length.
    #[inline(always)]
    unsafe fn push_activation(&mut self, mut activation: Activation, window: *mut Value) {
        activation.native.window = window.addr();
        let len = self.activations.len();
        let frame_storage_bytes = activation.frame_storage_bytes();
        debug_assert!(len < self.activations.capacity(), "lane activations stay within capacity");
        // SAFETY: the slot at `len` lies within capacity and is uninitialized; the top
        // covers it only once written.
        unsafe { self.activations.push_unchecked(activation); }
        self.wasm_storage_bytes += frame_storage_bytes;
    }

    #[inline(always)]
    fn pop_activation(&mut self) -> Option<Activation> {
        let activation = self.activations.pop()?;
        self.wasm_storage_bytes -= activation.frame_storage_bytes();
        self.drop_owned_from(self.activations.len());
        Some(activation)
    }

    /// Drops what the activations from index `depth` on owned, which completed: their loops'
    /// iterators, their `with` objects, eval records and trap checks.
    #[inline(always)]
    fn drop_owned_from(&mut self, depth: usize) {
        if !self.iterators.is_empty() || !self.with_objects.is_empty() || !self.records.is_empty() || !self.trap_checks.is_empty() {
            self.drop_owned_held_from(depth);
        }
    }

    #[cold]
    #[inline(never)]
    fn drop_owned_held_from(&mut self, depth: usize) {
        self.iterators.retain(|(owner, _)| *owner < depth);
        self.with_objects.retain(|(owner, _)| *owner < depth);
        self.records.retain(|(owner, _)| *owner < depth);
        self.trap_checks.retain(|(owner, _)| *owner < depth);
    }

    /// The generation of a lane run under `key`: the current one while the key holds, else
    /// a new one, which retires every target resolved before.
    /// Derive `activation_limit` from the activations' capacity, the guest calls the
    /// thread admits beyond the frames and activations already counted, and a due
    /// collection.
    #[inline(always)] fn refresh_activation_limit(&self) {
        let limit = if lane_floor().load(std::sync::atomic::Ordering::Relaxed) == COLLECTION_DUE_FLOOR {
            0
        } else {
            let admitted = self.activations.len() + crate::stack::GuestCallGuard::remaining();
            self.activations.capacity().min(admitted)
        };
        self.activation_limit.set(limit);
    }

    /// Records `target` as a callee of the call record whose link is `link`, in the order
    /// first seen. The link names the latest callee, so a callee already recorded changes
    /// nothing: a polymorphic site's steady state only reads its record.
    fn note_site_callee(&self, link: &std::cell::Cell<u16>, target: super::compiled::CallTarget) {
        let mut sites = self.call_sites.borrow_mut();
        let site = sites.entry(std::ptr::from_ref(link).addr()).or_default();
        if !site.contains(&target) {
            if site.len() == super::compiled::tier_policy::POLYMORPHISM { site.remove(0); }
            site.push(target);
        }
    }

    /// Drops the callees a collection swept from the sites' records before any allocation
    /// reuses their records: a body inlining one would take another function for it.
    pub(super) fn forget_dead_callees(&mut self, live: impl Fn(Value) -> bool) {
        self.wasm_export = None;
        self.js_import = None;
        self.bound_call = None;
        self.call_sites.get_mut().retain(|_, targets| { targets.retain(|target| target.identity().is_none_or(&live)); !targets.is_empty() });
    }

    /// Retires everything this stack resolved before the collection that ended under `key`
    /// (the new epoch and the realm): call targets, function targets and read memos name
    /// callees, environments and storages the collection may have swept, whose heap indices
    /// the next allocations reuse. The collector calls it, so a lane run that continues past
    /// any call out that collected (a native such as `gc()`, a host callback, an allocation
    /// that made a collection due) never admits a target of a swept closure whose index a
    /// new closure took: its depth-0 captures would read the dead closure's storage.
    pub(super) fn retire_after_collection(&mut self, key: (u64, Value)) {
        self.enter_generation(key);
    }

    fn enter_generation(&mut self, key: (u64, Value)) {
        if self.generation == NO_SCRIPT_GENERATION || self.generation_key != key {
            self.generation = self.generation.wrapping_add(1);
            if self.generation == NO_SCRIPT_GENERATION {
                // A wrapped number could name entries of a generation long past.
                self.clear_script_targets();
                self.generation = NO_SCRIPT_GENERATION + 1;
            }
            self.generation_key = key;
            self.admission = Admission(Admission::new(self.generation, self.admission.program()).0 | self.refused);
        }
    }

    /// Notes the program the lane now runs (`Vm::activate_program`).
    #[inline(always)]
    pub(super) fn enter_program(&mut self, program: ProgramId) {
        self.admission = Admission(Admission::new(self.generation, program).0 | self.refused);
    }

    /// Whether no cached target or memo admits a call (`Admission::REFUSED`): while a `with`
    /// scope was entered (`Vm::with_scope_entered`) or a construction's callee is pending
    /// (`Vm::construct_target`), under which a lane call leaves the lane, so the cached paths
    /// need not test either (`Vm::refresh_call_refusal`).
    pub(super) fn set_refused(&mut self, refused: bool) {
        self.refused = if refused { Admission::REFUSED } else { 0 };
        self.admission = Admission(self.admission.0 & !Admission::REFUSED | self.refused);
    }

    /// Whether cached calls are refused (`set_refused`).
    #[inline(always)]
    fn refuses(&self) -> bool {
        self.refused != 0
    }

    /// The admission a target or memo made now holds: the lane's, without `Admission::REFUSED`.
    #[inline(always)]
    fn current_admission(&self) -> Admission {
        Admission(self.admission.0 & !Admission::REFUSED)
    }
}

/// A lane native call made beside the lane's activations (`Vm::runs_beside_activations`):
/// the lane's context and the call's record, whose frames the first observer of the frame
/// stack makes (`Vm::materialize_deferred_lane`).
#[derive(Clone, Copy)]
pub(super) struct DeferredLaneCall {
    /// The lane's `LaneContext`, of the VM's host.
    cx: *mut (),
    call_pc: usize,
    /// The frame count the native runs at, below its caller's activations.
    frames: usize,
}

/// The activations below a callback a deferred native runs in the lane
/// (`Vm::lane_deferred_callback`): they are the native's caller's, whose pending calls and
/// executing program are the lane's outer ones, not the callback's.
#[derive(Clone, Copy)]
struct NativeBoundary {
    /// The callback's activation: those before it are the caller's.
    activation: usize,
    pending: *mut Vec<PendingGeneralCall>,
    executing: *mut super::dispatch_frame::ExecutingProgram,
    deferred: DeferredLaneCall,
    /// The promise natives running when the callback began (`active_native`): the native
    /// caller's, which its activations' frames move; those the callback starts keep theirs.
    natives: usize,
}

/// A native a lane called from its running frame after its activations became frames
/// (`lane_call_native`): the lane's `LaneContext`, the call's record and the frame count the
/// native runs at. A JavaScript call the native makes while all three still hold runs as an
/// activation of that lane (`Vm::lane_native_callback`).
#[derive(Clone, Copy)]
pub(super) struct LaneNativeCall {
    cx: *mut (),
    call: Ip,
    frames: usize,
}

/// A lane's immutable record-range binding and its owning Host's resume operation.
/// Every context starts with this prefix, so nested runs can resume a different Host safely.
#[repr(C)]
struct LaneBinding {
    resume: unsafe fn(*mut ()),
    /// Drops what the context resolved under the collection epoch before
    /// (`retire_lane_binding`), for its owning Host.
    retire: unsafe fn(*mut ()),
    object_base: *const Object,
}

/// Drops the storage pointers a lane context resolved before a collection, as
/// `lane_after_nested_collection` does after an in-place operation collected: the run's
/// capture storage (whose `CAPTURE_STORES` tag let stores skip the barrier until the next
/// collection), its last outer capture walk, a frame's captured-locals storage and a Wasm
/// instance's slots. Each is found again by the path that found it first. The context's
/// stack is retired by the collector itself (`LaneStack::retire_after_collection`).
unsafe fn retire_lane_binding<H: Host>(context: *mut ()) {
    let cx = context.cast::<LaneContext<H>>();
    // SAFETY: the prefix's callback was installed for this context's Host; the context is
    // live while it is the thread's running or a suspended outer one.
    unsafe {
        (*cx).registers.set_capture(std::ptr::null());
        (*cx).outer = NO_OUTER_WALK;
        (*cx).root_walk = NO_OUTER_WALK;
        (*cx).frame_storage = NO_FRAME_STORAGE;
        (*cx).instance_slots = (Value::DELETED, std::ptr::null());
    }
}

/// Retires the thread's running lane context after a collection ran under it: a native call
/// out of the lane (`gc()`, a host callback) or an allocation that made one due. The run
/// continues past the call with nothing it resolved under the epoch before.
pub(super) fn retire_running_lane_context() {
    let cx = tls_lane_context();
    if cx.is_null() {
        return;
    }
    // SAFETY: every active context has the repr(C) `LaneBinding` prefix, whose callback
    // owns its actual Host type.
    unsafe { (cx.cast::<LaneBinding>().as_ref().unwrap_unchecked().retire)(cx) };
}

unsafe fn resume_lane_binding<H: Host>(context: *mut ()) {
    let cx = context.cast::<LaneContext<H>>();
    // SAFETY: the prefix's callback was installed for this context's Host.
    let base = unsafe { vm(cx) }.heap.object_record_base().unwrap_or(std::ptr::null());
    unsafe { (*cx).binding.object_base = base };
}

/// Lane state that handlers read rarely; the hot state travels in handler
/// arguments so it stays in machine registers across dispatches. Its fields keep their
/// declared order: a plain call saves and restores `this`, `env` and `capture` together
/// (`lane_push_passed`), so they stay adjacent, and the Wasm tier's rarely read counters
/// come last.
#[repr(C)]
struct LaneContext<H: Host> {
    binding: LaneBinding,
    vm: *mut Vm<H>,
    /// The executing program, which every inline call stays within.
    code: *const ResidualProgram,
    program: ProgramId,
    /// What the run starts from: the VM frame it runs, or a job's frame in its record
    /// (`LaneRoot`). The registers and the view of the function the lane runs follow.
    root: LaneRoot,
    registers: Registers,
    base: Ip,
    /// The general loop's pending inline calls, which lane calls extend and
    /// lane returns complete exactly as the general loop would.
    pending: *mut Vec<PendingGeneralCall>,
    /// The general loop's executing program, which a materialized call into another
    /// program sets aside in its pending call as the loop's own push does.
    executing: *mut super::dispatch_frame::ExecutingProgram,
    /// The program's lane views by function, which a call reads when its
    /// callee's view is derived.
    views: *const [super::program_store::LaneViewCell],
    /// The program's constants, which constant operands index. A program's lane views are
    /// derived from its constants and replaced with them, so they hold for the run.
    constants: *const [Value],
    /// Lane calls and returns manage activations: the interpreter runs a
    /// Wasm program in a loop that allows inline calls. A compiled callee
    /// runs from the general path, which raises its traps.
    inline_calls: bool,
    /// The view handlers start from when the lane loop dispatches.
    memory: MemoryView,
    /// The last memory binding resolved in this lane run and its view. No
    /// lane instruction grows memory or runs host code, so a binding's view
    /// holds for the whole run; calls and returns within one instance reuse
    /// it instead of resolving the binding again.
    resolved: (Value, MemoryView),
    /// JavaScript calls may activate their callees without frames: the general loop
    /// would push them in place (`Vm::try_inline_user_call`).
    script_calls: bool,
    /// `new` may activate its callee without a frame too: the run's frame is an ordinary
    /// body, from which the general loop pushes constructions (`Vm::inline_construct_target`).
    script_constructs: bool,
    /// The running activation's `this`, or `DELETED` when the frame's binding decides
    /// it (`Vm::current_this`).
    /// The instance environment of the Wasm activations above a JavaScript call of an export
    /// (`ActivationKind::WasmEntry`), or `DELETED` where the frame's environment is the
    /// instance's (`lane_instance_env`).
    instance: Value,
    /// The last outer capture walk an activation read through (`lane_load_outer_capture`).
    /// One walk measured better than one per depth parity on closure-heavy code.
    outer: OuterWalk,
    /// The last walk a root binding read took (`lane_root_slots`): from the running
    /// activation's environment word, or its frame's, out to the root environment's slots.
    root_walk: OuterWalk,
    /// The storage of the environment a frame run's captured locals live in, once a local
    /// access found it (`lane_frame_storage`).
    frame_storage: FrameStorage,
    /// The instance environment the run's Wasm bindings last read and its dense slot storage
    /// (`lane_instance_binding`), found this run as `frame_storage` is.
    instance_slots: (Value, *const usize),
    /// Backward jumps left before the running Wasm function is credited with an
    /// interpreter entry's worth of loop work (`TIERS.wasm.backedges_per_entry`), or `None`
    /// when this run's code earns none (`Vm::lane_credits_backedges`). A crediting run keeps
    /// its floor raised, so every backward jump reaches `lane_safepoint`, which counts: the
    /// handlers stay as they are.
    backedges_left: Option<u32>,
    /// The accumulator the lane loop dispatches its next record with: the one a safepoint
    /// jump carried to its target (`lane_safepoint`), else none.
    resumed_acc: Slot<Value>,
    /// The record a lane body's native call left the lane to continue at, one of the callee's
    /// records in the activation it made (`lane_body_call`), and the accumulator that record reads.
    callee_resume: Ip,
    callee_acc: Value,
    /// The call a lane body's helper decoded last (`BodyCall::at`): its program, function, record and
    /// form, which the run's code fixes, so a loop's repeated call or construction decodes
    /// its instruction once per run.
    body_site: Option<(*const ResidualProgram, u32, u64, crate::staged::Invocation)>,
    /// What this run proved about the storage of the arrays its loops index
    /// (`ArrayStorageProofs`), which the proved element records read
    /// (`specialize_proved_arrays`). The heap retires them at any change that could falsify
    /// one; a nested run retires them on entry, and they end with the run.
    proofs: crate::heap::ArrayStorageProofs,
    /// The run's floor cell (`lane_floor`), which a JavaScript safepoint reads from here
    /// (`script_below_floor`).
    floor: *const std::sync::atomic::AtomicUsize,
    /// Backward jumps left before one reaches `lane_safepoint` (`script_fuel_out`), which
    /// credits the work clock and refills it; zero while the floor is raised at entry or a
    /// collection is due (`note_allocation`), so every backward jump reaches it.
    fuel: u32,
    /// Whether that callee left the lane because it has no body yet and is still warming
    /// toward one (`lane_body_activate`): its caller's leave says nothing of the caller's own
    /// specialization (`lane_leave_counts`).
    callee_warming: bool,
    /// The leaf call whose records run (`lane_script_call_leaf`), which holds what its
    /// activation would until its return or materialization; `NO_LEAF_CALL` for none.
    leaf: LeafCall,
    /// The dispatch payload of the native loop region running on this activation, zero for none
    /// (`lane_region_payload`): the heap bases a call it makes may move are reloaded there too
    /// (`lane_region_call`).
    region_payload: usize,
}

/// A running leaf call (`CallEntry::Leaf`): what its activation would hold that the context
/// does not. The context's registers and records are the callee's; what its form makes its
/// own (`LeafForm`) of the receiver and environment is the callee's, the rest the caller's.
#[derive(Clone, Copy)]
struct LeafCall {
    /// The call record, null while no leaf runs.
    call: Ip,
    /// The form the call ran as, which decides what its activation takes from the caller
    /// (`lane_materialize_leaf`): a published body's entry (`lane_enter_cell_body`) runs as `CONTEXT_LEAF`.
    form: LeafForm,
    /// The values the call passed, which its activation records.
    argc: u16,
    caller_registers: Registers,
    caller_base: Ip,
    /// The target the call resolved, which stays in its cache while the leaf runs: nothing
    /// in a leaf resolves a target.
    target: *const ScriptCallTarget,
    /// The caller's program, for a leaf of another program (`lane_cross_leaf_call`), which
    /// its return enters again; `None` for one of the caller's own.
    caller_program: Option<ProgramId>,
}

const NO_LEAF_CALL: LeafCall = LeafCall {
    call: std::ptr::null(),
    form: NOT_LEAF,
    argc: 0,
    caller_registers: Registers(std::ptr::null_mut()),
    caller_base: std::ptr::null(),
    target: std::ptr::null(),
    caller_program: None,
};

/// The slot storage of environment `env`, which frame `frame` held when a lane local access
/// looked it up; null for none. A live environment's storage never moves, and no
/// collection runs in the lane, so it holds while that frame runs with that environment.
#[derive(Clone, Copy)]
struct FrameStorage {
    frame: usize,
    env: Value,
    slots: *mut crate::heap::EnvironmentSlots,
}

const NO_FRAME_STORAGE: FrameStorage =
    FrameStorage { frame: usize::MAX, env: Value::DELETED, slots: std::ptr::null_mut() };

/// The storage of the running frame's captured environment (`LaneContext::frame_storage`),
/// for a frame run of a function other than the root whose frame holds one; `None` leaves
/// the access to the heap.
#[inline(always)]
fn lane_frame_storage<H: Host>(cx: *mut LaneContext<H>) -> Option<&'static mut crate::heap::EnvironmentSlots> {
    let vm = unsafe { vm(cx) };
    let index = unsafe { (*cx).frame() };
    let frame = &vm.frames[index];
    if !frame.captured || frame.function == super::ROOT_FUNCTION_ID {
        return None;
    }
    let known = unsafe { (*cx).frame_storage };
    let slots = if known.frame == index && known.env == frame.env {
        known.slots
    } else {
        lane_find_frame_storage(cx, index, frame.env)
    };
    // SAFETY: as `FrameStorage`; the lane holds no other reference to the storage.
    unsafe { slots.as_mut() }
}

/// `lane_frame_storage` where its cache already holds the running frame's, without the
/// lookup, and the environment it belongs to, whose barrier a store takes.
#[inline(always)]
fn lane_known_frame_storage<H: Host>(
    cx: *mut LaneContext<H>,
) -> Option<(&'static mut crate::heap::EnvironmentSlots, Value)> {
    let known = unsafe { (*cx).frame_storage };
    let vm = unsafe { vm(cx) };
    if known.frame != unsafe { (*cx).frame() } || known.slots.is_null() || vm.frames[known.frame].env != known.env {
        return None;
    }
    // SAFETY: as `FrameStorage`; the lane holds no other reference to the storage.
    Some((unsafe { &mut *known.slots }, known.env))
}

/// `lane_frame_storage` past its cache: the environment's storage, recorded.
#[cold]
#[inline(never)]
fn lane_find_frame_storage<H: Host>(
    cx: *mut LaneContext<H>,
    frame: usize,
    env: Value,
) -> *mut crate::heap::EnvironmentSlots {
    let vm = unsafe { vm(cx) };
    let slots = match vm.heap.environment_mut(env) {
        Some(crate::heap::EnvironmentRecord { slots, .. }) => std::ptr::from_mut(slots),
        _ => std::ptr::null_mut(),
    };
    unsafe { (*cx).frame_storage = FrameStorage { frame, env, slots } };
    slots
}

/// A walk from environment `env`, `DELETED` for none, `depth` layers out to the dense slots
/// `slots`. An environment's chain is fixed and its storage stays put while no collection
/// runs, so the walk holds while the running activation's environment is `env`; a re-entry
/// after the general path, which may collect, forgets it.
#[derive(Clone, Copy)]
struct OuterWalk {
    env: Value,
    depth: u16,
    slots: *const crate::heap::EnvironmentSlots,
}

const NO_OUTER_WALK: OuterWalk = OuterWalk { env: Value::DELETED, depth: 0, slots: std::ptr::null() };

/// The tag of a `LaneContext::capture` whose every dense slot a store may write directly:
/// its environment admits every direct store (`Vm::admits_every_direct_store`) and is in the
/// remembered set already, so a write needs no barrier until the next collection, which
/// retires the target that tagged it.
pub(super) const CAPTURE_STORES: usize = 1;
const _: () = assert!(std::mem::align_of::<usize>() > CAPTURE_STORES);

/// The slots a `LaneContext::capture` reads, its tag cleared.
#[inline(always)]
pub(super) fn capture_reads(capture: *const usize) -> *const usize {
    capture.map_addr(|address| address & !CAPTURE_STORES)
}

/// The local slots (address and count) of the VM frame the lane context `cx` runs, as the lane's handlers read
/// them (`lane_frame::staged_load_local_plain`); none where there is no context (a test's entry).
///
/// # Safety
/// `cx` is null or a live `LaneContext<H>`.
unsafe fn frame_locals<H: Host>(cx: *mut ()) -> (*mut Value, usize) {
    std::ptr::NonNull::new(cx.cast::<LaneContext<H>>()).map_or((std::ptr::null_mut(), 0), |cx| {
        // SAFETY: the caller's contract; the VM and its frame outlive the lane run.
        let (frames, root) = unsafe { (&mut vm(cx.as_ptr()).frames, (*cx.as_ptr()).root) };
        // A job's activations run in no frame (`LaneRoot::Job`).
        root.frame().map_or((std::ptr::null_mut(), 0), |frame| (frames[frame].locals.as_mut_ptr(), frames[frame].locals.len()))
    })
}

/// The slots a `LaneContext::capture` tagged `CAPTURE_STORES` lets a store write.
#[inline(always)]
pub(super) fn capture_stores(capture: *const usize) -> Option<*const usize> {
    (capture.addr() & CAPTURE_STORES != 0).then(|| capture_reads(capture))
}

/// A lane handler returns the next record for the lane loop, tagged with
/// [`EXIT_TAG`] when the general path must execute it. The carried state is
/// passed as scalars so every argument stays in a register; the context,
/// which hot handlers do not touch, is reached through [`LANE_CONTEXT`].
///
/// Handlers use the `rust-preserve-none` convention: every register is the caller's to save,
/// and a handler's caller is only the next handler's tail jump or the lane's entry, so the hot
/// handlers save none. Under the default convention six arguments left three scratch
/// registers, and a script call saved and restored six callee-saved ones on every record
/// (V8-v7 no-JIT, static production build, pinned, 3 interleaved runs, x86_64 4 vCPU,
/// 2026-11-01: Score DeltaBlue 1936 -> 2097, NavierStokes 4638 -> 4963, RayTrace 5083 -> 5348,
/// Richards within spread).
type Handler = extern "rust-preserve-none" fn(Registers, Ip, *mut u8, Slot<isize>, crate::value::IntegerEncoding, Slot<Value>) -> Ip;

/// A plain `#[thread_local]` cell. `thread_local!` in this position-independent rlib reads
/// through a `__tls_get_addr` call that only the linker relaxes, so LLVM gave every handler
/// that reads the lane context a frame and spills; the executable's local-exec read below
/// is one load.
struct TlsCell<T: Copy>(std::cell::Cell<T>);
impl<T: Copy> TlsCell<T> {
    #[inline(always)]
    fn with<R>(&self, f: impl FnOnce(&std::cell::Cell<T>) -> R) -> R { f(&self.0) }
}
/// The context of this thread's running lane. A lane run never calls out, so runs nest
/// only through the general path, and each run restores the outer context when it returns.
#[thread_local]
static LANE_CONTEXT: TlsCell<*mut ()> = TlsCell(std::cell::Cell::new(std::ptr::null_mut()));
/// The running lane's stack floor (`ExecutionInterrupt::lane_floor` of its VM): a taken
/// safepoint jump below it returns to the lane loop. The maximum address marks a due
/// collection or a termination request.
#[thread_local]
static LANE_FLOOR: TlsCell<*const std::sync::atomic::AtomicUsize> = TlsCell(std::cell::Cell::new(std::ptr::null()));

#[cfg(all(target_arch = "x86_64", target_os = "linux"))]
#[inline(always)]
fn tls_lane_context() -> *mut () {
    let value: *mut ();
    // SAFETY: the executable's own TLS block; local-exec offset fixed at link time.
    unsafe { std::arch::asm!("mov {}, qword ptr fs:[{}@TPOFF]", out(reg) value, sym LANE_CONTEXT, options(pure, nostack, readonly, preserves_flags)) };
    value
}
#[cfg(not(all(target_arch = "x86_64", target_os = "linux")))]
#[inline(always)]
fn tls_lane_context() -> *mut () {
    LANE_CONTEXT.0.get()
}
/// The running lane's fuel (`LaneContext::fuel`), for the handlers that do not carry the
/// context and for `note_allocation`; null while no lane runs.
#[thread_local]
static LANE_FUEL: TlsCell<*mut u32> = TlsCell(std::cell::Cell::new(std::ptr::null_mut()));
#[cfg(all(target_arch = "x86_64", target_os = "linux"))]
#[inline(always)]
fn tls_lane_fuel() -> *mut u32 {
    let value: *mut u32;
    // SAFETY: as `tls_lane_context`.
    unsafe { std::arch::asm!("mov {}, qword ptr fs:[{}@TPOFF]", out(reg) value, sym LANE_FUEL, options(pure, nostack, readonly, preserves_flags)) };
    value
}
#[cfg(not(all(target_arch = "x86_64", target_os = "linux")))]
#[inline(always)]
fn tls_lane_fuel() -> *mut u32 {
    LANE_FUEL.0.get()
}

/// Backward jumps a lane run takes between two safepoint visits: the bound on how long a
/// termination request from another thread waits (it raises the floor, which the visit reads).
const LANE_FUEL_BATCH: u32 = 4096;

/// Spend one unit of the running lane's fuel; true when it was out, so the backward jump
/// takes `lane_safepoint`. One decrement of a context field and one branch: the safepoint
/// test of every backward jump, in place of the stack-floor compare.
#[inline(always)]
fn script_fuel_out<H: Host>(cx: *mut LaneContext<H>) -> bool {
    // SAFETY: the run's context, which only this thread touches.
    unsafe {
        let (left, out) = (*cx).fuel.overflowing_sub(1);
        (*cx).fuel = left;
        out
    }
}

/// `script_fuel_out` for a handler without the context.
#[inline(always)]
fn fuel_out() -> bool {
    // SAFETY: set for the whole of a lane run to its context's fuel; only read while a lane runs.
    unsafe {
        let fuel = tls_lane_fuel();
        let (left, out) = (*fuel).overflowing_sub(1);
        *fuel = left;
        out
    }
}

#[cfg(all(target_arch = "x86_64", target_os = "linux"))]
#[inline(always)]
fn tls_lane_floor() -> *const std::sync::atomic::AtomicUsize {
    let value: *const std::sync::atomic::AtomicUsize;
    // SAFETY: as `tls_lane_context`.
    unsafe { std::arch::asm!("mov {}, qword ptr fs:[{}@TPOFF]", out(reg) value, sym LANE_FLOOR, options(pure, nostack, readonly, preserves_flags)) };
    value
}
#[cfg(not(all(target_arch = "x86_64", target_os = "linux")))]
#[inline(always)]
fn tls_lane_floor() -> *const std::sync::atomic::AtomicUsize {
    LANE_FLOOR.0.get()
}

/// A lane run's raised floor (`Vm::enter_lane_floor`): the VM's floor cell, and the cell and
/// floor of the run it nests in, which leaving restores.
struct LaneFloor {
    cell: *const std::sync::atomic::AtomicUsize,
    outer_cell: *const std::sync::atomic::AtomicUsize,
    outer_floor: usize,
}

/// The running lane's floor.
#[inline(always)]
fn lane_floor() -> &'static std::sync::atomic::AtomicUsize {
    // SAFETY: set for the whole of a lane run to its VM's interrupt state, which the VM
    // holds; only read while a lane runs.
    unsafe { &*tls_lane_floor() }
}

/// Stack a lane run may use below its entry before a safepoint jump returns
/// to the lane loop; only reachable should a build not form sibling calls.
const LANE_STACK_SLACK: usize = 64 * 1024;

/// The floor that sends the next safepoint jump through the slow path.
const COLLECTION_DUE_FLOOR: usize = crate::execution_interrupt::LANE_FLOOR_RAISED;

/// The current stack address.
#[cfg(quench_lane_tail_calls)]
#[inline(always)]
fn stack_pointer() -> usize {
    let sp: usize;
    // SAFETY: reads the stack pointer register; no memory, stack or flags.
    #[cfg(target_arch = "x86_64")]
    unsafe {
        std::arch::asm!("mov {}, rsp", out(reg) sp, options(nomem, nostack, preserves_flags));
    }
    // SAFETY: as above.
    #[cfg(target_arch = "aarch64")]
    unsafe {
        std::arch::asm!("mov {}, sp", out(reg) sp, options(nomem, nostack, preserves_flags));
    }
    sp
}

/// Without sibling calls every handler returns to the lane loop, so a run's
/// stack cannot grow; this address lies above every stack floor and below
/// the due-collection floor.
#[cfg(not(quench_lane_tail_calls))]
#[inline(always)]
fn stack_pointer() -> usize {
    COLLECTION_DUE_FLOOR - 1
}

/// `below_floor` of a JavaScript record, whose context register carries the run's floor
/// (`LaneContext::floor`) without the thread-local load.
#[inline(always)]
fn script_below_floor<H: Host>(cx: *mut LaneContext<H>) -> bool {
    // SAFETY: the run's floor cell, which its VM holds for the whole run.
    stack_pointer() < unsafe { &*(*cx).floor }.load(std::sync::atomic::Ordering::Relaxed)
}

/// After a lane allocation, a due collection raises the floor of the running lane, where
/// one runs: a linked region's general frame polls the heap's own counters instead.
#[inline(always)]
pub(super) fn note_allocation<H: Host>(vm: &Vm<H>) {
    if vm.heap.should_collect() {
        let floor = tls_lane_floor();
        // SAFETY: as `lane_floor`, while a lane runs; null otherwise.
        if let Some(floor) = unsafe { floor.as_ref() } {
            floor.store(COLLECTION_DUE_FLOOR, std::sync::atomic::Ordering::Relaxed);
        }
        // SAFETY: as `fuel_out`, while a lane runs; null otherwise.
        if let Some(fuel) = unsafe { tls_lane_fuel().as_mut() } {
            *fuel = 0;
        }
        vm.lane_stack.activation_limit.set(0);
    }
}

/// The running activation's `this`; `None` where the general path decides it (a
/// derived constructor before `super()`).
///
/// # Safety
/// `cx` is the running lane's context.
#[inline(always)]
unsafe fn lane_this<H: Host>(cx: *mut LaneContext<H>, r: Registers) -> Option<Value> {
    let this = r.this();
    if !this.is_deleted() {
        return Some(this);
    }
    unsafe { vm(cx).current_this((*cx).frame()) }
}

/// The running lane's context.
#[inline(always)]
fn lane_context<H: Host>() -> *mut LaneContext<H> {
    tls_lane_context().cast()
}

/// Records are word aligned, so the low address bit is free to mark a lane
/// exit.
const EXIT_TAG: usize = 1;
const _: () = assert!(std::mem::align_of::<LaneInstruction>() > EXIT_TAG);

/// The general path executes the instruction at `ip`.
#[inline(always)]
fn exit(ip: Ip) -> Ip {
    ip.map_addr(|address| address | EXIT_TAG)
}

/// The record a handler's result names, and whether the result leaves the lane there (`exit`).
#[inline(always)]
fn exited(ip: Ip) -> (Ip, bool) {
    (ip.map_addr(|address| address & !EXIT_TAG), ip.addr() & EXIT_TAG != 0)
}

/// SAFETY: the context outlives the lane run and no other reference to the
/// VM is live while a handler runs.
#[inline(always)]
unsafe fn vm<'a, H: Host>(cx: *mut LaneContext<H>) -> &'a mut Vm<H> {
    unsafe { &mut *(*cx).vm }
}

/// Sample the identity and body a script call site targets. Diagnostic builds use this to
/// determine whether a per-site target memo is worth implementing; production builds compile
/// every call to this helper away.
#[cfg(feature = "profile-lane-exits")]
#[inline(always)]
fn profile_script_call_target<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    callee: Value,
    target: &ScriptCallTarget,
) {
    let vm = unsafe { vm(cx) };
    let caller = vm
        .lane_stack
        .activations
        .last()
        .map_or_else(|| vm.frames[unsafe { (*cx).frame() }].function, |activation| {
            activation.function
        });
    let pc = unsafe { ip.offset_from((*cx).base) } as u32;
    super::lane_exits::call_target(
        unsafe { (*cx).program.raw() },
        caller,
        pc,
        callee,
        target.function,
    );
}

/// The handler of the record at `ip`.
#[inline(always)]
fn handler(ip: Ip) -> Handler {
    #[cfg(feature = "profile-lane-exits")]
    super::lane_exits::count_record(ip.addr(), std::mem::size_of::<LaneInstruction>());
    // SAFETY: a view is only run by the VM type whose handlers built it, and
    // every reachable record is initialized.
    unsafe { std::mem::transmute::<*const (), Handler>((*ip).handler) }
}

/// Continue with the handler of the record at `ip`.
#[cfg(quench_lane_tail_calls)]
macro_rules! next {
    ($cx:expr, $r:expr, $ip:expr, $view:expr) => {{
        let ip: Ip = $ip;
        let view: Carried = $view;
        let _ = $cx;
        become handler(ip)(
            $r,
            ip,
            view.memory.bytes,
            view.memory.reach,
            view.integers,
            view.acc,
        );
    }};
}

#[cfg(not(quench_lane_tail_calls))]
macro_rules! next {
    ($cx:expr, $r:expr, $ip:expr, $view:expr) => {{
        let ip: Ip = $ip;
        let _ = ($cx, $r, $view);
        return ip;
    }};
}

/// Where the lane continues once an activation completes (`lane_complete_activation`): after
/// the call in its caller, with these registers and view, or out of the lane at a frame's
/// call record that returns the completion (`lane_frame_return`).
enum Resumed {
    At(Registers, Ip, Carried),
    Exit(Ip),
}

/// Runs `handler` for the record at `ip` as a sibling call: the calling handler's fast path
/// then keeps no state across a slow path that needs more registers.
#[cfg(quench_lane_tail_calls)]
macro_rules! sibling {
    ($handler:expr, $r:expr, $ip:expr, $view:expr) => {{
        let view: Carried = $view;
        become $handler(
            $r,
            $ip,
            view.memory.bytes,
            view.memory.reach,
            view.integers,
            view.acc,
        );
    }};
}

#[cfg(not(quench_lane_tail_calls))]
macro_rules! sibling {
    ($handler:expr, $r:expr, $ip:expr, $view:expr) => {{
        let view: Carried = $view;
        return $handler(
            $r,
            $ip,
            view.memory.bytes,
            view.memory.reach,
            view.integers,
            view.acc,
        );
    }};
}

impl Resumed {
    /// The record the lane loop continues at for this resumption, which it dispatches with
    /// the context's registers and view, as a build without sibling calls continues every
    /// record (`next!`): for a helper whose own result is the lane loop's.
    fn into_loop(self) -> Ip {
        match self {
            Resumed::At(_, next, _) | Resumed::Exit(next) => next,
        }
    }
}

/// Continue as `lane_complete_activation` resumed.
macro_rules! resume {
    ($cx:expr, $resumed:expr) => {{
        match $resumed {
            Resumed::At(registers, next, view) => next!($cx, registers, next, view),
            Resumed::Exit(next) => return next,
        }
    }};
}

/// Continue as a comparison jump's `edge` says: the target through `lane_jump`, whose backward
/// poll every jump shares, or the record after it.
macro_rules! jump_on_edge {
    ($cx:expr, $r:expr, $ip:expr, $backward:expr, $edge:expr) => {
        jump_on_edge!($cx, $r, $ip, $backward, $edge, Carried::script($cx))
    };
    ($cx:expr, $r:expr, $ip:expr, $backward:expr, $edge:expr, $carried:expr) => {{
        match $edge {
            crate::staged::Edge::Target => resume!($cx, lane_jump::<H>($r, $ip, $backward, $carried, None)),
            crate::staged::Edge::Following => next!($cx, $r, following($ip), $carried),
        }
    }};
}

/// Define a handler with the shared signature. `$i` is the record and
/// `$view` the current memory view.
macro_rules! lane_handler {
    ($(#[$meta:meta])* $vis:vis fn $name:ident<$($param:ident: $ty:ty),*>($cx:ident, $r:ident, $ip:ident, $i:ident, $view:ident) $body:block) => {
        lane_handler!(@define bytes [lane_context::<H>()] $(#[$meta])* $vis fn $name<$($param: $ty),*>($cx, $r, $ip, $i, $view) $body);
    };
    (@define $bytes:ident [$context:expr] $(#[$meta:meta])* $vis:vis fn $name:ident<$($param:ident: $ty:ty),*>($cx:ident, $r:ident, $ip:ident, $i:ident, $view:ident) $body:block) => {
        $(#[$meta])*
        #[allow(unused_variables)]
        $vis extern "rust-preserve-none" fn $name<H: Host, $(const $param: $ty),*>(
            $r: Registers,
            $ip: Ip,
            $bytes: *mut u8,
            reach: Slot<isize>,
            integers: crate::value::IntegerEncoding,
            acc: Slot<Value>,
        ) -> Ip {
            let $cx: *mut LaneContext<H> = $context;
            let $view = Carried {
                memory: MemoryView { bytes: $bytes, reach },
                integers,
                acc,
            };
            // SAFETY: the lane only dispatches records of the running view.
            let $i = unsafe { &*$ip };
            $body
        }
    };
}

/// `lane_handler!` for a handler only JavaScript views dispatch: the run's context comes
/// from the carried view (`MemoryView::script`) rather than the thread-local load.
macro_rules! script_handler {
    ($(#[$meta:meta])* $vis:vis fn $name:ident<$($param:ident: $ty:ty),*>($cx:ident, $r:ident, $ip:ident, $i:ident, $view:ident) $body:block) => {
        lane_handler!(@define bytes [{
            let cx: *mut LaneContext<H> = bytes.cast();
            debug_assert_eq!(cx, lane_context::<H>(), "a JavaScript view carries its context");
            cx
        }] $(#[$meta])* $vis fn $name<$($param: $ty),*>($cx, $r, $ip, $i, $view) $body);
    };
}

/// `lane_handler!` for a return record of any view that has a leaf form
/// (`LaneView::specialize_leaf_returns`): a leaf's records are JavaScript, so its form takes
/// the context as `script_handler!` does, and only the others load it.
macro_rules! return_handler {
    ($(#[$meta:meta])* fn $name:ident<$($param:ident: $ty:ty),*>($cx:ident, $r:ident, $ip:ident, $i:ident, $view:ident) $body:block) => {
        lane_handler!(@define bytes [if LEAF == NOT_LEAF {
            lane_context::<H>()
        } else {
            let cx: *mut LaneContext<H> = bytes.cast();
            debug_assert_eq!(cx, lane_context::<H>(), "a JavaScript view carries its context");
            cx
        }] $(#[$meta])* fn $name<$($param: $ty),*>($cx, $r, $ip, $i, $view) $body);
    };
}

/// Which field of a record reads the accumulator: none, or the field the
/// constant names. The view selects a reading instantiation only where the
/// field's register is the previous record's result register and control
/// reaches the record only by falling through from it.
const ACC_NONE: u8 = 0;
/// `LaneView::accumulator_registers` of a record that reads no accumulator.
const NO_ACCUMULATOR: u16 = u16::MAX;
const ACC_A: u8 = 1;
const ACC_B: u8 = 2;
const ACC_C: u8 = 3;
/// The first register of the immediate's register pair: a select's
/// condition.
const ACC_PAIR: u8 = 4;
/// Accumulator positions a record may read: none, A, B, C and the pair.
const ACC_POSITIONS: usize = 5;

impl InstructionField {
    const fn accumulator(self) -> u8 {
        match self {
            Self::A => ACC_A,
            Self::B => ACC_B,
            Self::C => ACC_C,
        }
    }
}

/// The value of register field `FIELD` of a record whose accumulator field
/// is `ACC`.
#[inline(always)]
fn read<const ACC: u8, const FIELD: u8>(r: Registers, register: u16, view: Carried) -> Value {
    if ACC == FIELD {
        // SAFETY: the view selects an accumulator-reading record only after the producer
        // that set it.
        unsafe { view.acc.get() }
    } else {
        r.get(register)
    }
}

#[inline(always)]
fn read_i32<const ACC: u8, const FIELD: u8>(r: Registers, register: u16, view: Carried) -> i32 {
    read::<ACC, FIELD>(r, register, view).wasm_bits32() as i32
}

/// Write an accumulator producer's result and continue with it carried.
macro_rules! produce {
    ($cx:expr, $r:expr, $ip:expr, $register:expr, $value:expr, $view:expr) => {{
        let value: Value = $value;
        $r.set($register, value);
        next!(
            $cx,
            $r,
            following($ip),
            Carried {
                acc: Slot::of(value),
                ..$view
            }
        )
    }};
}

/// The record after `ip`.
#[inline(always)]
fn following(ip: Ip) -> Ip {
    // SAFETY: validation ends every function in a terminator, so a lane
    // instruction that falls through has a successor.
    unsafe { ip.add(1) }
}

/// The opcode a handler instantiation serves.
const fn opcode(index: u16) -> Op {
    match Op::from_index(index as usize) {
        Some(op) => op,
        None => panic!("lane handler for an opcode outside the opcode table"),
    }
}

lane_handler! {
    /// Not a lane instruction: the general path executes it.
    fn lane_exit<>(cx, r, ip, i, view) {
        exit(ip)
    }
}

