lane_handler! {
    /// `LoadLocal` and `LoadEnvLocal` of an initialized binding a VM frame owns
    /// (`staged::read_initialized_local` over the binding, `lane_frame::staged_load_local_checked`); any other read
    /// takes the general path.
    fn lane_load_local<>(cx, r, ip, i, view) {
        if !(unsafe { (*cx).registers }.env().is_deleted()
            && i.a & crate::bytecode::NUMERIC_LOCAL_TARGET == 0
            && lane_frame::staged_load_local_checked::<H, ACC_NONE>(cx, r, view, i.a, i.imm() as usize))
        {
            return exit(ip);
        }
        next!(cx, r, following(ip), view)
    }
}

/// The value a frame-backed run reads from `slot` of frame `frame`'s function: the frame's
/// environment slot when `environment` and the environment is captured, else its local.
/// `None` for a root body's frame or an uninitialized binding.
#[inline(always)]
fn frame_window_local<H: Host>(vm: &Vm<H>, frame: usize, slot: usize, environment: bool) -> Option<Value> {
    let frame = &vm.frames[frame];
    if frame.function == super::ROOT_FUNCTION_ID {
        return None;
    }
    let value = if environment && frame.captured {
        vm.heap.environment_slot(frame.env, slot)?
    } else {
        *frame.locals.get(slot)?
    };
    (!value.is_deleted()).then_some(value)
}

mod capture_append;
mod mapped_windows;
mod string_case_filter;

script_handler! {
    /// A local load of a function an environment activation may run
    /// (`specialize_environment_window`): in a frame's run, the frame's binding, as
    /// `lane_load_frame_local`; in an environment activation, its environment's slot
    /// (`ENVIRONMENT`) or its window's local. An uninitialized binding or a numeric local
    /// takes the general path. `lane_load_window_local` answers the common case first.
    #[inline(never)]
    fn lane_load_window_local_general<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        let (slot, registers) = environment_window_fields(i);
        let value = if i.a & crate::bytecode::NUMERIC_LOCAL_TARGET != 0 {
            None
        } else if unsafe { (*cx).registers }.env().is_deleted() {
            match (if ENVIRONMENT { lane_frame_storage(cx) } else { None }).and_then(|storage| storage.dense()) {
                Some(dense) => dense.dense_plain(slot).or_else(|| {
                    let vm = unsafe { vm(cx) };
                    vm.heap.environment_slot(vm.frames[unsafe { (*cx).frame() }].env, slot)
                }),
                None => frame_window_local(unsafe { vm(cx) }, unsafe { (*cx).frame() }, slot, ENVIRONMENT),
            }
        } else if ENVIRONMENT {
            // SAFETY: an environment window holds its environment's slot storage, which
            // never moves while the environment lives (`lane_activate_environment`).
            let storage = unsafe {
                &*(std::mem::transmute::<Value, u64>(r.get(registers + WINDOW_SLOTS))
                    as *const crate::heap::EnvironmentSlots)
            };
            match storage.dense().and_then(|dense| dense.dense_plain(slot)) {
                Some(value) => Some(value),
                None => unsafe { vm(cx) }.heap.environment_slot(r.get(registers + WINDOW_ENVIRONMENT), slot),
            }
        } else {
            Some(r.get(registers + WINDOW_LOCALS + slot as u16))
        };
        let Some(value) = value.filter(|value| !value.is_deleted()) else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `lane_load_window_local_general`'s store: to an initialized (or initializing)
    /// binding. `lane_store_window_local` answers the common case first.
    #[inline(never)]
    fn lane_store_window_local_general<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        let (slot, registers) = environment_window_fields(i);
        let value = r.get(i.a);
        let vm = unsafe { vm(cx) };
        let binding = if unsafe { (*cx).registers }.env().is_deleted() {
            let storage = if ENVIRONMENT { lane_frame_storage(cx) } else { None };
            let frame = &mut vm.frames[unsafe { (*cx).frame() }];
            if frame.function == super::ROOT_FUNCTION_ID {
                None
            } else if ENVIRONMENT && frame.captured {
                // A write to a slot through its storage takes the environment's barrier first.
                vm.heap.remember_cell(frame.env);
                match storage.and_then(|storage| storage.owned_mut(slot)) {
                    Some(binding) => Some(binding),
                    None => vm.heap.environment_slot_mut(frame.env, slot),
                }
            } else {
                frame.locals.get_mut(slot)
            }
        } else if ENVIRONMENT {
            let environment = r.get(registers + WINDOW_ENVIRONMENT);
            // A write to a slot through its storage takes the environment's barrier first.
            vm.heap.remember_cell(environment);
            // SAFETY: as `lane_load_window_local`'s read of the window's storage.
            let storage = unsafe {
                &mut *(std::mem::transmute::<Value, u64>(r.get(registers + WINDOW_SLOTS))
                    as *mut crate::heap::EnvironmentSlots)
            };
            match storage.owned_mut(slot) {
                Some(binding) => Some(binding),
                None => vm.heap.environment_slot_mut(environment, slot),
            }
        } else {
            // SAFETY: an environment activation's window holds its locals after its
            // environment (`lane_activate_environment`).
            Some(unsafe { &mut *r.0.add(usize::from(registers + WINDOW_LOCALS) + slot) })
        };
        match binding {
            Some(binding) if i.c != 0 || !binding.is_deleted() => *binding = value,
            _ => return exit(ip),
        }
        if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
            r.set(register, value);
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `lane_load_window_local`'s `InitializeTdz`: opens the binding's dead zone.
    fn lane_initialize_window_tdz<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        let (slot, registers) = environment_window_fields(i);
        let vm = unsafe { vm(cx) };
        let binding = if unsafe { (*cx).registers }.env().is_deleted() {
            // SAFETY: the context's program outlives the lane run.
            vm.owner_binding_mut(unsafe { &*(*cx).code }, VarOwner::Frame(unsafe { (*cx).frame() }), slot)
        } else if ENVIRONMENT {
            // SAFETY: as `lane_store_window_local_window`'s write to the window's storage; a marker needs no barrier.
            if unsafe { crate::staged::environment::concrete_environment_slot_open(window_storage(r, registers), slot as u16) } {
                next!(cx, r, following(ip), Carried::script(cx))
            }
            // SAFETY: as `lane_load_window_local`'s read of the window's storage; a marker
            // needs no barrier.
            let storage = unsafe {
                &mut *(std::mem::transmute::<Value, u64>(r.get(registers + WINDOW_SLOTS))
                    as *mut crate::heap::EnvironmentSlots)
            };
            match storage.owned_mut(slot) {
                Some(binding) => Some(binding),
                None => vm.heap.environment_slot_mut(r.get(registers + WINDOW_ENVIRONMENT), slot),
            }
        } else {
            // SAFETY: as `lane_store_window_local`.
            Some(unsafe { &mut *r.0.add(usize::from(registers + WINDOW_LOCALS) + slot) })
        };
        let Some(binding) = binding else {
            return exit(ip);
        };
        *binding = Value::DELETED;
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `MakeClosure` of a function an environment activation may run: in a frame's run, as
    /// `lane_make_closure`; in an environment activation, over its environment.
    fn lane_make_window_closure<>(cx, r, ip, i, view) {
        let (function, registers) = environment_window_fields(i);
        let value = if unsafe { (*cx).registers }.env().is_deleted() {
            lane_closure_value_of(cx, function as u32)
        } else {
            lane_window_closure_value(cx, r, function as u32, registers)
        };
        let Some(value) = value else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// `lane_make_window_closure`'s closure of `function` over the running environment
/// activation's environment, whose window starts at register `registers`. Out of line, as
/// `lane_new_object`: making the closure takes stack temporaries.
#[inline(never)]
fn lane_window_closure_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    function: u32,
    registers: u16,
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    let activation = vm.lane_stack.activations.last().copied()?;
    let owner = activation.function;
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let parent = unsafe { (*cx).registers }.env();
    // SAFETY: the running environment activation's window, whose function is the
    // innermost activation's and whose environment's parent is the context's.
    let window = |vm: &mut Vm<H>| unsafe {
        let bindings = activation.take_record_bindings();
        window_environment(vm, code, r.0.add(usize::from(registers)), owner, parent, (*cx).program, r.this(), Some(bindings))
    };
    let value = match vm.lane_closure_template(function) {
        // A recorded closure is made from its template once: over another environment where
        // it reads nothing of this activation's (`Vm::maker_free_environment`), so the
        // activation needs none of its own for it, else over the activation's.
        Some(template) => {
            let env = match vm.maker_free_environment(&template, parent, owner) {
                Some(env) => env,
                None => window(vm),
            };
            Some(vm.closure_of_template(template, env))
        }
        None => {
            let environment = window(vm);
            lane_closure(vm, code, function, environment)
        }
    };
    note_allocation(vm);
    value
}

lane_handler! {
    /// `StoreLocal` and `StoreEnvLocal` to a binding a VM frame owns that
    /// `lane_frame::staged_store_local_checked` completes; any other store takes the general
    /// path. A `StoreEnvLocal` of a function that resolves names at run time, which may
    /// write a `with` object's binding instead, has no record (`derive_lane_view`) but the
    /// scoped window's (`scoped_names::lane_store_scoped_local`).
    fn lane_store_local<>(cx, r, ip, i, view) {
        let value = r.get(i.a);
        let stored = unsafe { (*cx).registers }.env().is_deleted()
            && lane_frame::staged_store_local_checked::<H, ACC_NONE>(cx, r, view, (i.a, i.imm() as usize), i.c != 0);
        if !stored {
            return exit(ip);
        }
        if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
            r.set(register, value);
        }
        next!(cx, r, following(ip), view)
    }
}

/// The value of a register or constant operand; other operand kinds take
/// the general path.
#[inline(always)]
fn lane_operand_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    encoded: u16,
) -> Option<Value> {
    let operand = crate::bytecode::Operand(encoded);
    match operand.kind()? {
        crate::bytecode::OperandKind::Register => Some(r.get(operand.payload())),
        // SAFETY: the run's program keeps its constants (`LaneContext::constants`).
        crate::bytecode::OperandKind::Constant => unsafe { &*(*cx).constants }
            .get(usize::from(operand.payload()))
            .copied(),
        crate::bytecode::OperandKind::Local => lane_plain_local_operand(cx, operand.payload()),
        _ => None,
    }
}

/// A local operand of the running function that is a plain slot, which the general loop
/// reads as `LoadLocalPlain` does (`Vm::operand_value`): generators and other functions that
/// keep frame locals compare and compute with them in place, and an environment
/// activation reads its window's local (`lane_load_window_local`). Any other frameless
/// activation has no locals; any other local is the general path's.
#[inline(never)]
fn lane_plain_local_operand<H: Host>(cx: *mut LaneContext<H>, slot: u16) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if let Some(activation) = vm.lane_stack.activations.last() {
        activation.script().filter(|script| script.environment)?;
        let body = code.function_get(activation.function as usize)?;
        if !body.plain_local(code, usize::from(slot)) {
            return None;
        }
        // SAFETY: the running function's registers, which its window's locals follow.
        let value = unsafe { (*cx).registers }.get(body.registers + WINDOW_LOCALS + slot);
        return (!value.is_deleted()).then_some(value);
    }
    // SAFETY: its frame is the running one.
    let frame = unsafe { (*cx).frame() };
    let frame = vm.frames.get(frame)?;
    let slot = usize::from(slot);
    code.functions
        .get(frame.function as usize)?
        .plain_local(code, slot)
        .then(|| frame.locals.get(slot).copied())
        .flatten()
}

/// The local slots a lane body run on `registers` reads and writes (`JsStepDispatch::native_locals`):
/// those of the activation it runs for, where `lane_plain_local_operand` finds them. An
/// environment activation keeps them in its window after its registers; a VM frame in its own
/// storage, or in the window after its registers where that storage does not cover the function
/// (as `osr_lane::bind_frame`); any other frameless activation has none (null), and a run whose
/// activation is not pushed yet (`lane_enter_cell_body`) is a plain one's.
pub(super) fn lane_body_locals<H: Host>(lane_context: *mut (), registers: *mut Value, pending: bool) -> *mut Value {
    let cx = lane_context.cast::<LaneContext<H>>();
    if cx.is_null() || pending {
        return std::ptr::null_mut();
    }
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let window = |function: u32| code.function_get(function as usize)
        .filter(|body| body.locals != 0)
        // SAFETY: the activation's window follows its register file.
        .map_or(std::ptr::null_mut(), |body| unsafe { registers.add(usize::from(body.registers) + usize::from(WINDOW_LOCALS)) });
    if let Some(activation) = vm.lane_stack.activations.last() {
        return match activation.script() {
            Some(script) if script.environment => window(activation.function),
            _ => std::ptr::null_mut(),
        };
    }
    // SAFETY: its frame is the running one.
    let Some(frame) = vm.frames.get_mut(unsafe { (*cx).frame() }) else { return std::ptr::null_mut() };
    let function = frame.function;
    match code.function_get(function as usize) {
        Some(body) if frame.locals.len() >= usize::from(body.locals) => frame.locals.as_mut_ptr(),
        _ => window(function),
    }
}

script_handler! {
    /// `IteratorCleanupPush` in the running VM frame, as the general loop runs it: the frame's
    /// iterator to close if the loop exits abruptly. A frameless activation keeps it on the
    /// lane stack (`LaneStack::iterators`), which its frame takes if it materializes.
    fn lane_iterator_cleanup_push<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let iterator = super::ActiveIterator { iterator: i.a, done: i.b };
        if let Some(depth) = vm.lane_stack.activations.len().checked_sub(1) {
            vm.lane_stack.iterators.push((depth, iterator));
        } else {
            let frame = unsafe { (*cx).frame() };
            vm.frames[frame].active_iterators.push(iterator);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `IteratorCleanupPop` in the running VM frame (`lane_iterator_cleanup_push`).
    fn lane_iterator_cleanup_pop<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let popped = match vm.lane_stack.activations.len().checked_sub(1) {
            // The running activation's own entry, the last.
            Some(depth) => vm.lane_stack.iterators.pop_if(|(owner, _)| *owner == depth).is_some(),
            None => {
                let frame = unsafe { (*cx).frame() };
                vm.frames[frame].active_iterators.pop().is_some()
            }
        };
        if !popped {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

lane_handler! {
    /// `DefineArrayElement` into the literal's dense storage (`Vm::define_literal_element`);
    /// any other definition takes the general path.
    fn lane_define_array_element<>(cx, r, ip, i, view) {
        if !(unsafe { vm(cx) }).define_literal_element(r.get(i.b), i.imm() as usize, r.get(i.a)) {
            return exit(ip);
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `RequireIteratorResult` of an object, which passes (the staged fast arm for a record, the
    /// VM's `is_object_like` for any other object kind); any other value takes the general
    /// path, which throws.
    fn lane_require_iterator_result<>(cx, r, ip, i, view) {
        if !staged_require_iterator_result(r, Carried::script(cx), i.b)
            && !(unsafe { vm(cx) }).is_object_like(r.get(i.b))
        {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}


script_handler! {
    /// `InitializeTdz`: opens the binding's dead zone wherever the frame keeps it, as the
    /// general path does (`Vm::owner_binding_mut`).
    fn lane_initialize_tdz<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let Some(binding) = (unsafe { vm(cx) }).owner_binding_mut(
            unsafe { &*(*cx).code },
            VarOwner::Frame(unsafe { (*cx).frame() }),
            i.imm() as usize,
        ) else {
            return exit(ip);
        };
        *binding = Value::DELETED;
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `CloneEnv` in the lane's own frame, as the general path makes it
    /// (`Vm::clone_frame_environment`): nothing to copy while the frame holds no captured
    /// environment, else the frame's environment replaced by its copy (a `for (let ...)`
    /// iteration's, which a closure in the body captures), after which the run's capture
    /// caches name the old environment and are dropped. An activation's environment is its
    /// window's, which an environment view's records copy (`lane_clone_window_env`); any
    /// other activation's clone takes the general path.
    fn lane_clone_env<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !vm.lane_stack.activations.is_empty() {
            return exit(ip);
        }
        let frame = unsafe { (*cx).frame() };
        if vm.frames[frame].captured {
            // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
            // running function's view.
            let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
            let body = code.function(vm.frames[frame].function as usize);
            let Some(plan) = body.environment_clones.get(body.widened(body.code[pc]).environment_clone_index())
            else {
                return exit(ip);
            };
            // It checks the environment before it allocates the copy, so an error leaves the
            // frame for the general path to raise it from.
            if vm.clone_frame_environment(frame, &plan.fresh, body.environment_clones.resets(plan)).is_err() {
                return exit(ip);
            }
            note_allocation(vm);
            handler_edges::drop_environment_caches(cx);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `CloneEnv` of a function an environment activation may run: in a frame's run, as
    /// `lane_clone_env`; in an environment activation, nothing to copy while its window has
    /// made no environment (no closure captured its bindings yet: they all live among the
    /// window's locals), else the window's environment replaced by its iteration copy, as a
    /// frame's (`Vm::iteration_environment`). Closures made earlier keep the old environment,
    /// whose function-level slots the copy shares.
    fn lane_clone_window_env<>(cx, r, ip, i, view) {
        if unsafe { (*cx).registers }.env().is_deleted() {
            sibling!(lane_clone_env::<H>, r, ip, Carried::script_in(cx, view))
        }
        let (_, registers) = environment_window_fields(i);
        // SAFETY: the running environment activation's window starts at `registers`.
        let entries = unsafe { r.0.add(usize::from(registers)) };
        let source = unsafe { *entries.add(usize::from(WINDOW_ENVIRONMENT)) };
        if source.is_deleted() {
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        let vm = unsafe { vm(cx) };
        let Some(function) = vm.lane_stack.activations.last().map(|activation| activation.function) else {
            return exit(ip);
        };
        // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
        // running function's view.
        let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
        let body = code.function(function as usize);
        let Some(plan) = body.environment_clones.get(body.widened(body.code[pc]).environment_clone_index())
        else {
            return exit(ip);
        };
        // It checks the environment before it allocates the copy, so an error leaves the
        // activation for the general path to raise it from.
        let Ok(environment) = vm.iteration_environment(source, unsafe { (*cx).program }, function, &plan.fresh, body.environment_clones.resets(plan))
        else {
            return exit(ip);
        };
        note_allocation(vm);
        let Some(crate::heap::EnvironmentRecord { slots, .. }) = vm.heap.environment(environment) else {
            unreachable!("an iteration copy is an environment");
        };
        let storage = std::ptr::from_ref(slots);
        // SAFETY: as above; the copy's slot storage never moves while it lives.
        unsafe {
            entries.add(usize::from(WINDOW_ENVIRONMENT)).write(environment);
            entries
                .add(usize::from(WINDOW_SLOTS))
                .write(std::mem::transmute::<u64, Value>(storage as u64));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `GetIterator` of a plain array whose iteration is intact (`Vm::array_iteration_intact`):
    /// the intrinsic values iterator, made without looking up or calling `@@iterator`; any other
    /// operand takes the general step in place.
    fn lane_get_iterator<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let source = r.get(i.b);
        if !vm.array_iteration_intact(source) {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        }
        let iterator = vm.array_iterator_of(super::IteratorKind::ArrayValues, source);
        note_allocation(vm);
        r.set(i.a, iterator);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `AppendArray` spreading, with no holes before it, a source whose iteration runs no
    /// guest code (`Vm::spread_intact_in_place`): its values join the literal without an
    /// iterator or result object. Any other append takes the general step in place.
    fn lane_append_array<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let source = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS);
        let (Some(source), true, 0) = (source, i.c != 0, i.imm()) else {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        };
        if !vm.spread_intact_in_place(r.get(i.a), r.get(source)) {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        }
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `IteratorClose` of a built-in iterator whose chain lacks `return`
    /// (`Vm::iterator_close_absent`), which ends with `undefined`; any other takes the general
    /// step in place.
    fn lane_iterator_close<>(cx, r, ip, i, view) {
        if !(unsafe { vm(cx) }).iterator_close_absent(r.get(i.b)) {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        }
        r.set(i.a, Value::UNDEFINED);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `ToPropertyKey` of a string, which is itself (the staged fast arm), of a symbol, which is
    /// itself, or of an integer, its decimal string; any other value, which may run guest code
    /// or format a float, takes the general step in place.
    fn lane_to_property_key<>(cx, r, ip, i, view) {
        if staged_property_key(r, Carried::script_in(cx, view), i.a, i.b) {
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        let vm = unsafe { vm(cx) };
        let value = r.get(i.b);
        let key = if let Some(integer) = value.as_int() {
            let key = vm.heap.alloc_string(crate::vm::wtf16::JsString::from_str(&integer.to_string()));
            note_allocation(vm);
            key
        } else if matches!(vm.heap.get(value), Some(Cell::Symbol(_))) {
            value
        } else {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, key);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}


script_handler! {
    /// `MakeConstArray`: the new array of the running program's constant elements, as the
    /// general loop makes it (`Vm::const_array_value`).
    #[inline(never)]
    fn lane_make_const_array<>(cx, r, ip, i, view) {
        // The record holds the elements' constant index and count (`lane_operand`), so the
        // running function's instruction is not decoded again.
        let allocation = Allocation::ConstArray { constant: i.imm(), count: i.b };
        if !staged_allocate(cx, r, i.a, allocation) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}


lane_handler! {
    /// An instruction whose general step only continues or throws (`Op::steps_in_lane`),
    /// run in place by that step when the lane runs the frame's own code: the frame's
    /// registers are the lane's, and its PC is published as the general loop publishes it.
    /// A throw is stashed in `Vm::lane_raised` for the general path to raise at this
    /// instruction. Within a frameless activation, which has no frame, the general path runs
    /// it.
    #[inline(never)]
    fn lane_general_step<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !vm.lane_stack.activations.is_empty() {
            resume!(cx, lane_step_beside_activations(cx, r, ip));
        }
        // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
        // active view, which is the running frame's.
        let (code, frame, pc) = unsafe {
            (&*(*cx).code, (*cx).frame(), ip.offset_from((*cx).base) as usize)
        };
        let function = code.function(vm.frames[frame].function as usize);
        let instruction = function.widened(function.code[pc]);
        vm.frames[frame].pc = pc;
        vm.frames[frame].pc_is_resume = false;
        let mut next = pc + 1;
        match vm.step(code, frame, instruction, &mut next, false) {
            Ok(StepResult::Continue) => {}
            Ok(_) => unreachable!("an in-place step only continues"),
            Err(error) => {
                vm.lane_completion.raise(error);
                return exit(ip);
            }
        }
        // The step may allocate, which can make a collection due.
        note_allocation(vm);
        // SAFETY: the step continues at a record of the running frame's view.
        let target = unsafe { (*cx).base.add(next) };
        if next > pc { next!(cx, r, target, Carried::stepped(cx, view, r, instruction)) } else { exit(target) }
    }
}

/// `lane_general_step` within a frameless activation: a value step (`Vm::call_out`) of
/// the activation's registers, made beside the activations as a native runs beside them
/// (`DeferredLaneCall`), so guest code it reaches makes them frames first; its result lands
/// in the running function's registers then. Any other step takes the general path.
#[cold]
#[inline(never)]
fn lane_step_beside_activations<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip) -> Resumed {
    let vm = unsafe { vm(cx) };
    let Some(function) = vm.lane_stack.activations.last().map(|activation| activation.function) else {
        return Resumed::Exit(exit(ip));
    };
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // innermost activation's view.
    let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
    let body = code.function(function as usize);
    let instruction = body.widened(body.code[pc]);
    if !instruction.op().steps_with_result() {
        return Resumed::Exit(exit(ip));
    }
    let (operation, result) = crate::staged::Operation::<(), ()>::decode(instruction, crate::staged::DecodeContext::of(code))
        .and_then(|row| row.call_out()).expect("a result step is a call-out row");
    let operands = operation.operands().read(&code.method_arguments, |register| r.get(register));
    let Some(value) = lane_in_place(cx, ip, |vm, code| {
        let site = super::call_out::CallSite { owner: vm.call_out_owner(operation), function, resume: pc + 1 };
        vm.call_out(code, site, operation, operands)
    }) else {
        return Resumed::Exit(exit(ip));
    };
    // Guest code the step ran made the activations frames, whose registers these are.
    let r = unsafe { (*cx).registers };
    if let (Some(value), Some(result)) = (value, result) {
        r.set(result, value);
    }
    Resumed::At(r, following(ip), Carried::stepped(cx, Carried::script(cx), r, instruction))
}

/// Make `operation` of the record at `ip` from the lane, as its general step would: in a
/// frame's own run with the frame's PC published (`lane_general_step`), or beside frameless
/// activations as a native beside them runs (`DeferredLaneCall`), so guest code it reaches
/// makes them frames first. A throw is stashed in `Vm::lane_raised`, raised from those
/// frames, and `None` is returned for the general path to raise it. The running function's
/// registers are `(*cx).registers` afterwards.
#[inline(always)]
fn lane_in_place<H: Host, T>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    operation: impl FnOnce(&mut Vm<H>, &ResidualProgram) -> Result<T, JsError>,
) -> Option<T> {
    lane_materialize_running_leaf(cx);
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // running function's view.
    let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
    let beside = !vm.lane_stack.activations.is_empty();
    if beside {
        vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc: pc, frames: vm.frames.len() });
    } else {
        let frame = unsafe { (*cx).frame() };
        vm.frames[frame].pc = pc;
        vm.frames[frame].pc_is_resume = false;
    }
    let generation_key = (vm.heap.collection_epoch(), vm.realm.globals);
    let result = operation(vm, code);
    // The operation may allocate, which can make a collection due.
    note_allocation(vm);
    if (vm.heap.collection_epoch(), vm.realm.globals) != generation_key {
        lane_after_nested_collection(cx);
    }
    let unobserved = beside && vm.lane_deferred.take().is_some();
    match result {
        Ok(value) => Some(value),
        Err(error) => {
            if unobserved {
                vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc: pc, frames: vm.frames.len() });
                vm.materialize_deferred_lane();
            }
            vm.lane_completion.raise(error);
            None
        }
    }
}

/// A lane run continues past guest code an operation made in place (`lane_in_place`), and
/// that code collected or switched realms: everything the run resolved under its generation (call targets, read
/// memos, capture and frame-storage pointers) assumed no collection runs in the lane, so it
/// names cells the collection may have swept. The run takes a new generation, which retires
/// every cached target, and drops its storage pointers, as a fresh run would start.
#[cold]
#[inline(never)]
fn lane_after_nested_collection<H: Host>(cx: *mut LaneContext<H>) {
    let vm = unsafe { vm(cx) };
    vm.lane_stack.enter_generation((vm.heap.collection_epoch(), vm.realm.globals));
    // SAFETY: `cx` is the running context, of this Host.
    unsafe { retire_lane_binding::<H>(cx.cast()) };
}



script_handler! {
    /// `IncDec` of a Number followed by an unconditional jump, a loop's update and its back
    /// edge (`specialize_update_jumps`): the update, then the jump record's jump
    /// (`lane_jump`, a safepoint when backward). Any other value runs the update's own
    /// handler, which continues at the jump record.
    fn lane_inc_dec_jump<DECREMENT: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        let Some(value) = super::dispatch::number_increment(r.get(i.b), DECREMENT) else {
            sibling!(inc_dec_row::<H, DECREMENT>(), r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        resume!(cx, lane_jump::<H>(r, following(ip), BACKWARD, Carried::script_in(cx, view), None))
    }
}

script_handler! {
    /// `lane_inc_dec_jump` whose backward jump enters the loop's own integer register test
    /// (`lane_jump_binary_false_registers`, `specialize_update_jumps`): the update, the back
    /// edge's safepoint, then the test, continuing in the body or at the loop's exit, a
    /// rotated loop's one dispatch per iteration where the pair and the test took two. A pair
    /// other than two integers runs the test's own record, any update but an integer's that
    /// stays one the update's own (`lane_row` of `IncDec`).
    fn lane_inc_dec_loop<DECREMENT: bool, OP: u32, COUNTER: bool>(cx, r, ip, i, view) {
        // An overflow, a double or a BigInt runs the update's own record, which continues at
        // the jump record.
        let Some(value) = super::dispatch::integer_increment(r.get(i.b), DECREMENT) else {
            sibling!(inc_dec_row::<H, DECREMENT>(), r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        let jump_ip = following(ip);
        // SAFETY: the view records the distance to a validated jump target, the test record
        // `specialize_update_jumps` matched. Computed before the fuel test, so the test's
        // branch reads the decrement's own flags.
        let test_ip = unsafe { jump_ip.byte_offset((*jump_ip).jump()) };
        if script_fuel_out(cx) {
            resume!(cx, lane_jump_safepoint::<H>(jump_ip, Carried::script_in(cx, view)))
        }
        let test = unsafe { &*test_ip };
        // A test of the counter (`COUNTER`, `specialize_update_jumps`) reads the integer just
        // written, whose tag the update proved.
        let left = if COUNTER { value } else { r.get(test.b) };
        let Some(holds) = super::operations::integer_relation(relation_operator::<OP>(test), left, r.get(test.c))
        else {
            next!(cx, r, test_ip, Carried::script_in(cx, view))
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, test_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(test_ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_inc_dec_loop` whose back edge enters an integer test against a small constant
    /// (`lane_jump_binary_false_small`, the constant in the record), as a counting-down loop's
    /// `i >= 0`: the update, the safepoint and the test as one dispatch. A value other than
    /// an integer runs the test's own record.
    fn lane_inc_dec_small_loop<DECREMENT: bool, OP: u32>(cx, r, ip, i, view) {
        let Some(value) = super::dispatch::integer_increment(r.get(i.b), DECREMENT) else {
            sibling!(inc_dec_row::<H, DECREMENT>(), r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        let jump_ip = following(ip);
        // SAFETY: the view records the distance to a validated jump target, the test record
        // `specialize_update_jumps` matched. Computed before the fuel test, so the test's
        // branch reads the decrement's own flags.
        let test_ip = unsafe { jump_ip.byte_offset((*jump_ip).jump()) };
        if script_fuel_out(cx) {
            resume!(cx, lane_jump_safepoint::<H>(jump_ip, Carried::script_in(cx, view)))
        }
        let test = unsafe { &*test_ip };
        let right = lane_small_constant::<H, false>(cx, test);
        let Some(holds) = super::operations::integer_relation(relation_operator::<OP>(test), r.get(test.b), right) else {
            next!(cx, r, test_ip, Carried::script_in(cx, view))
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, test_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(test_ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_inc_dec_loop` whose back edge enters a fused load and register test
    /// (`lane_load_jump_binary_false_registers`), a loop bound read from a local or a capture
    /// each iteration, as NavierStokes' `i <= width`: the update, the safepoint, the load and
    /// the test as one dispatch. A load the fast read misses or a pair other than two integers
    /// runs the load's own record, which loads again and tests.
    fn lane_inc_dec_load_loop<DECREMENT: bool, CAPTURE: bool, OP: u32>(cx, r, ip, i, view) {
        let Some(value) = super::dispatch::integer_increment(r.get(i.b), DECREMENT) else {
            sibling!(inc_dec_row::<H, DECREMENT>(), r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        let jump_ip = following(ip);
        // SAFETY: the view records the distance to a validated jump target, the load record
        // `specialize_update_jumps` matched, whose branch record follows it. Computed before
        // the fuel test, so its branch reads the decrement's own flags.
        let load_ip = unsafe { jump_ip.byte_offset((*jump_ip).jump()) };
        if script_fuel_out(cx) {
            resume!(cx, lane_jump_safepoint::<H>(jump_ip, Carried::script_in(cx, view)))
        }
        let load = unsafe { &*load_ip };
        let branch_ip = following(load_ip);
        let branch = unsafe { &*branch_ip };
        let bound = if CAPTURE {
            let slots = capture_reads(unsafe { (*cx).registers }.capture());
            // SAFETY: as `lane_load_capture`'s read.
            let bound = unsafe { crate::heap::EnvironmentSlots::read_storage(slots, ImmediateLayout::capture_slot(load.imm())) };
            let Some(bound) = bound else {
                next!(cx, r, load_ip, Carried::script_in(cx, view))
            };
            bound
        } else {
            // SAFETY: as `lane_load_jump_binary_false_registers`' local read.
            unsafe { vm(cx).read_validated_local((*cx).frame(), load.imm() as usize) }
        };
        r.set(load.a, bound);
        let Some(holds) = super::operations::integer_relation(relation_operator::<OP>(branch), r.get(branch.b), r.get(branch.c))
        else {
            next!(cx, r, load_ip, Carried::script_in(cx, view))
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, branch_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(branch_ip), Carried::script_in(cx, view))
    }
}

/// The update of a BigInt (`Vm::bigint_increment`, which allocates its result); `None` for
/// any other value. Out of line: its arithmetic keeps stack temporaries a handler inlining
/// it would hold on its common path.
#[inline(never)]
fn lane_bigint_increment<H: Host, const DECREMENT: bool>(cx: *mut LaneContext<H>, value: Value) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    let next = vm.bigint_increment(value, DECREMENT)?;
    note_allocation(vm);
    Some(next)
}

script_handler! {
    /// `IncDec` of a Number whose result the next record, a register `GetIndex`
    /// (`element_read_row`), reads as its index, the `a[++i]` of compiled loops
    /// (`specialize_updated_index_reads`): the update, then that read of a record array's
    /// dense element, as one record. A read the pair's fast path leaves runs the `GetIndex`
    /// record itself; another value takes the general path at the update.
    fn lane_update_get_index<DECREMENT: bool>(cx, r, ip, i, view) {
        let Some(index) = super::dispatch::number_increment(r.get(i.b), DECREMENT) else {
            return exit(ip);
        };
        r.set(i.a, index);
        // SAFETY: the pair is two records, the second never the view's last.
        let read = unsafe { &*following(ip) };
        let Some(value) = (unsafe { vm(cx) }).direct_dense_element(r.get(read.b), index) else {
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        };
        r.set(read.a, value);
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_update_get_index` whose read element the next record, an arithmetic operator
    /// (`lane_operator` or `lane_operator_numbers` of `OP`), takes as an operand, the
    /// `t + a[++i]` of compiled loops (`specialize_updated_index_operators`): the update, the
    /// read and that Number operation as one record. A step the fast path leaves runs its
    /// own record, which stays in place.
    fn lane_update_get_index_operator<DECREMENT: bool, OP: u32>(cx, r, ip, i, view) {
        let Some(index) = super::dispatch::number_increment(r.get(i.b), DECREMENT) else {
            return exit(ip);
        };
        r.set(i.a, index);
        // SAFETY: the triple is three records, the third never the view's last.
        let read = unsafe { &*following(ip) };
        let Some(element) = (unsafe { vm(cx) }).direct_dense_element(r.get(read.b), index) else {
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        };
        r.set(read.a, element);
        resume!(cx, lane_read_operator::<H, OP, false>(cx, r, ip, element));
    }
}

/// The operation of `lane_update_get_index_operator`'s triple at `ip`, whose read the triple
/// made: the Number operation, else the operator's own record.
#[inline(always)]
fn lane_read_operator<H: Host, const OP: u32, const RAW: bool>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, element: Value) -> Resumed {
    // SAFETY: the triple is three records, the third never the view's last.
    let operator = unsafe { &*following(following(ip)) };
    // Arithmetic on two Numbers first, the register operands read in memory
    // (`Registers::number`); bitwise operators and other values take the shared operation.
    if matches!(OP, ADDITION | SUBTRACTION | MULTIPLICATION | DIVISION) {
        let numbers = if super::operations::number_result_is_commutative(OP) {
            // SAFETY: specialization stores the other register in the fused update's unused c.
            match element.as_number() { Some(left) => r.number(unsafe { (*ip).c }).map(|right| (left, right)), None => None }
        } else {
            match r.number(operator.b) { Some(left) => r.number(operator.c).map(|right| (left, right)), None => None }
        };
        if let Some((left, right)) = numbers
            && let Some(number) = super::operations::number_operator::<OP>(left, right)
        {
            let value = if RAW { raw_results::raw_number(number) } else { Value::number(number) };
            r.set(operator.a, value);
            return Resumed::At(r, following(following(following(ip))), Carried::script(cx));
        }
    }
    // SAFETY: specialization stores the other register in the fused update's unused c.
    let (left, right) = read_number_operands::<OP>(r, operator, unsafe { (*ip).c }, element);
    let value = if RAW {
        raw_results::raw_number_value_operator::<OP>(left, right)
    } else {
        super::operations::number_value_operator::<OP>(left, right)
    };
    let Some(value) = value else {
        return Resumed::At(r, following(following(ip)), Carried::script(cx));
    };
    r.set(operator.a, value);
    Resumed::At(r, following(following(following(ip))), Carried::script(cx))
}

/// A read's value may occupy either side of canonical commutative Number arithmetic.
/// Its register was already written, so reading the other register preserves aliases.
/// Ordered operations retain both original operands. A non-Number still declines through
/// the shared Number operation; its original record owns evaluation/coercion order.
#[inline(always)]
fn read_number_operands<const OP: u32>(r: Registers, operator: &LaneInstruction, other: u16, element: Value) -> (Value, Value) {
    if super::operations::number_result_is_commutative(OP) {
        (element, r.get(other))
    } else {
        (r.get(operator.b), r.get(operator.c))
    }
}

/// The index a proved element record (`specialize_proved_arrays`) reads at: a non-negative
/// integer key, as `Vm::direct_dense_element` takes one.
#[cfg(all(test, feature = "bench-primitives"))]
#[inline(always)]
pub(super) fn proof_index(key: Value) -> Option<usize> {
    usize::try_from(key.as_int()?).ok()
}

/// The index a proved element record reads or replaces at for an int32 key, as its u32
/// bits: a negative key becomes an index at or above 2^31, which every proof's bound
/// (`ArrayStorageProofs::prove`, below 2^31) declines, so the proof's bounds test is the
/// key's sign test too.
#[inline(always)]
fn proof_int_index(key: i32) -> usize {
    key as u32 as usize
}

/// The index a proved element record reads or replaces at for a key in a register, without
/// unboxing it first (`Value::int_key_offset`): an int32 key's index, and an index at or
/// above 2^31 for any other key, which every proof's bound declines as `proof_int_index`'s
/// negative keys. The key's tag test, its zero extension and the bounds test are one compare.
#[inline(always)]
fn proof_key(key: Value) -> usize {
    key.int_key_offset()
}

/// The integer `IncDec` of `value`, the update `dispatch::number_increment` makes of an
/// integer that does not overflow; `None` for any other value.
#[inline(always)]
pub(super) fn integer_increment<const DECREMENT: bool>(value: Value) -> Option<i32> {
    // As `dispatch::integer_increment`: a non-negative step by one word-range compare.
    let offset = value.int_key_offset();
    let stepped = if DECREMENT { offset.wrapping_sub(1) } else { offset.wrapping_add(1) };
    // A decrement of the least int32 (offset 2^31) would land at 2^31 - 1: its bound is one less.
    if stepped < (1 << 31) - usize::from(DECREMENT) {
        return Some(stepped as i32);
    }
    let integer = value.as_int()?;
    if DECREMENT { integer.checked_sub(1) } else { integer.checked_add(1) }
}

/// After the proved record at `ip` missed the run's proofs through base register `register`
/// (`ArrayStorageProofs`): proves the record array `base` names unless its slot already
/// holds it. Any other base gives the record its generic handler for good: the record's
/// base is loop-invariant, so it would decline every proved access.
fn lane_prove_array<H: Host>(cx: *mut LaneContext<H>, ip: Ip, register: u16, base: Value) {
    // SAFETY: the context's proofs and its VM are distinct, both live for the run.
    let (proofs, vm) = unsafe { (&mut (*cx).proofs, vm(cx)) };
    if !proofs.holds(register, base)
        && !vm.heap.prove_array_storage(proofs, register, base)
        && let Some(generic) = generic_handler::<H>(lane_own_handler::<H>(ip))
    {
        requicken::<H>(ip, generic);
    }
}

/// The handler the record at `ip` runs as its own: a header record a loop site holds
/// (`lane_loop_hold_header`) keeps it in the site.
fn lane_own_handler<H: Host>(ip: Ip) -> *const () {
    // SAFETY: a record of the running view; a held header names its site.
    unsafe {
        let handler = (*ip).handler;
        if handler == lane_loop_header::<H> as Handler as *const () {
            return (*lane_header_site(ip)).header_handler.get();
        }
        handler
    }
}

script_handler! {
    /// A proved element read or store (`lane_get_index_proved`, `lane_set_index_proved`,
    /// `lane_set_index_move_proved`) its proofs declined: proves its base
    /// (`lane_prove_array`), then runs the generic record. Apart, so the proved records' fast
    /// paths make no call.
    #[inline(never)]
    fn lane_proof_miss<>(cx, r, ip, i, view) {
        let generic = generic_handler::<H>(lane_own_handler::<H>(ip));
        lane_prove_array(cx, ip, i.b, r.get(i.b));
        let Some(generic) = generic else {
            return exit(ip);
        };
        sibling!(generic, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A proved update and read (`lane_update_get_index_proved` and its operator form) whose
    /// read its proofs declined after the update: proves the read's base
    /// (`lane_prove_array`), then runs the read's own record, as the generic pair leaves it.
    #[inline(never)]
    fn lane_updated_proof_miss<>(cx, r, ip, i, view) {
        // SAFETY: the pair is two records, the second never the view's last.
        let read = unsafe { &*following(ip) };
        lane_prove_array(cx, ip, read.b, r.get(read.b));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `element_read_row` of a base its loop does not redefine
    /// (`specialize_proved_arrays`): the element through the run's proof of the array's
    /// storage (`ArrayStorageProofs`), with no decoding of the array; any other read takes
    /// `lane_proof_miss`.
    fn lane_get_index_proved<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { (*cx).proofs.element(i.b, r.get(i.b), proof_key(r.get(i.c))) }) else {
            sibling!(lane_proof_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A register `Move` whose next record is a proved element read (`lane_get_index_proved`,
    /// `specialize_moved_index_reads`), the key copy `x[t = i]` keeps for a store whose value
    /// then updates `i` (V8-v7 NavierStokes' `x[currentRow] = ... x[++currentRow] ...`): the
    /// copy and the read as one record. A read the proofs decline continues at the read's
    /// own record, which proves its base as before.
    fn lane_move_get_index_proved<>(cx, r, ip, i, view) {
        let moved = r.get(i.b);
        r.set(i.a, moved);
        // SAFETY: the pair is two records, the second never the view's last.
        let read = unsafe { &*following(ip) };
        let Some(value) = (unsafe { (*cx).proofs.element(read.b, r.get(read.b), proof_key(r.get(read.c))) }) else {
            next!(cx, r, following(ip), Carried { acc: Slot::of(moved), ..view })
        };
        r.set(read.a, value);
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

/// The fast case of `proved_updated_read`: the key `i.b ± 1` as a word-range index
/// (`Value::int_key_offset`, then the step), which an int32 whose step stays in `[0, bound)`
/// alone passes, so no tag test, overflow test or retagging runs: the update written is the
/// key word stepped by one, with no carry into the tag below 2^31. `None` writes nothing and
/// leaves the pair to its checked form (an index past the proof, any other key, a hole).
/// The pair's base is one its loop does not redefine (`specialize_proved_arrays`), so it is
/// never the updated register.
macro_rules! proved_stepped_read {
    ($cx:expr, $r:expr, $ip:expr, $update:expr, $decrement:expr) => {{
        // SAFETY: the pair is two records, the second never the view's last.
        let read = unsafe { &*following($ip) };
        debug_assert_ne!(read.b, $update.a);
        let word = $r.get($update.b);
        let key = if $decrement { word.int_key_offset().wrapping_sub(1) } else { word.int_key_offset().wrapping_add(1) };
        match unsafe { (*$cx).proofs.element(read.b, $r.get(read.b), key) } {
            Some(element) => {
                let stepped = if $decrement { word.to_bits() - 1 } else { word.to_bits() + 1 };
                $r.set($update.a, Value::from_bits(stepped));
                Some(element)
            }
            None => None,
        }
    }};
}

/// The proved read (`lane_get_index_proved`) of `lane_update_get_index`'s pair at `ip`, of
/// the integer update `index` of record `update`, which it writes first; a read the proofs
/// decline takes `lane_updated_proof_miss`, as the pair's own fast path leaves it.
macro_rules! proved_updated_read {
    ($cx:expr, $r:expr, $ip:expr, $update:expr, $index:expr) => {{
        $r.set($update.a, Value::integer($index));
        // SAFETY: the pair is two records, the second never the view's last.
        let read = unsafe { &*following($ip) };
        let Some(element) = (unsafe { (*$cx).proofs.element(read.b, $r.get(read.b), proof_int_index($index)) })
        else {
            sibling!(lane_updated_proof_miss::<H>, $r, $ip, Carried::script($cx))
        };
        $r.set(read.a, element);
        element
    }};
}

script_handler! {
    /// `lane_update_get_index` of a base its loop does not redefine: an integer update and
    /// the proved read of its element (`proved_updated_read`); any other update takes
    /// `lane_update_get_index`.
    fn lane_update_get_index_proved<DECREMENT: bool>(cx, r, ip, i, view) {
        if let Some(element) = proved_stepped_read!(cx, r, ip, i, DECREMENT) {
            r.set(unsafe { &*following(ip) }.a, element);
            next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
        }
        let Some(index) = integer_increment::<DECREMENT>(r.get(i.b)) else {
            sibling!(lane_update_get_index::<H, DECREMENT>, r, ip, Carried::script_in(cx, view))
        };
        proved_updated_read!(cx, r, ip, i, index);
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_update_get_index_operator` of a base its loop does not redefine: an integer
    /// update, the proved read of its element (`proved_updated_read`) and the operation;
    /// any other update takes `lane_update_get_index_operator`.
    ///
    /// With `RAW` the operation's result keeps its double form (`raw_results`).
    fn lane_update_get_index_operator_proved<DECREMENT: bool, OP: u32, RAW: bool>(cx, r, ip, i, view) {
        if let Some(element) = proved_stepped_read!(cx, r, ip, i, DECREMENT) {
            r.set(unsafe { &*following(ip) }.a, element);
            resume!(cx, lane_read_operator::<H, OP, RAW>(cx, r, ip, element));
        }
        let Some(index) = integer_increment::<DECREMENT>(r.get(i.b)) else {
            sibling!(lane_update_get_index_operator::<H, DECREMENT, OP>, r, ip, Carried::script_in(cx, view))
        };
        let element = proved_updated_read!(cx, r, ip, i, index);
        resume!(cx, lane_read_operator::<H, OP, RAW>(cx, r, ip, element));
    }
}

script_handler! {
    /// A postfix update of a Number or BigInt (`lane_bigint_increment`): `ToNumeric` into `a` and the
    /// `IncDec` of its result into `c` that follows it (`specialize_updates`). Other values
    /// take the general path at the conversion.
    fn lane_postfix_update<DECREMENT: bool>(cx, r, ip, i, view) {
        let value = r.get(i.b);
        let Some(updated) = super::dispatch::number_increment(value, DECREMENT)
            .or_else(|| lane_bigint_increment::<H, DECREMENT>(cx, value))
        else {
            return exit(ip);
        };
        r.set(i.a, value);
        r.set(i.c, updated);
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// Numeric operands on the integer fast path; the regional site profile
    /// records the execution exactly as the general path does.
    fn lane_binary<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { lane_binary_value(cx, r, i) }) else {
            sibling!(lane_binary_general::<H>, r, ip, Carried::script_in(cx, view))
        };
        if i.a & crate::bytecode::NUMERIC_LOCAL_TARGET != 0 {
            lane_store_numeric_local(cx, r, i.a & crate::bytecode::REGISTER_MASK, value);
        } else {
            r.set(i.a, value);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Binary` of a Number constant and a register (`1 / i`), as the view decoded it
    /// (`constant_left_operator_handler`): two Numbers by their values
    /// (`number_value_operator`); any other right operand takes `lane_binary_general`.
    fn lane_operator_constant_left<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the run's program keeps its constants (`LaneContext::constants`), and the view
        // was derived with `b` a constant operand indexing a Number.
        let left = unsafe { *(&*(*cx).constants).get_unchecked(usize::from(crate::bytecode::Operand(i.b).payload())) };
        let right = r.get(crate::bytecode::Operand(i.c).payload());
        let Some(value) = super::operations::number_value_operator::<OP>(left, right) else {
            sibling!(lane_binary_general::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// Stores `value` to the plain local a numeric target names (`lane_binary`): the running
/// environment window's, which follows the function's registers (`lane_plain_local_operand`),
/// else the running frame's.
#[inline(always)]
fn lane_store_numeric_local<H: Host>(cx: *mut LaneContext<H>, r: Registers, local: u16, value: Value) {
    let vm = unsafe { vm(cx) };
    let window = vm.lane_stack.activations.last().filter(|activation| activation.script().is_some_and(|script| script.environment));
    // SAFETY: the context's program outlives the lane run.
    let registers = window.map(|activation| unsafe { &*(*cx).code }.function(activation.function as usize).registers);
    match registers {
        Some(registers) => r.set(registers + WINDOW_LOCALS + local, value),
        // SAFETY: the view admits a numeric local target only below `Function.locals`.
        None => unsafe { vm.write_validated_local((*cx).frame(), usize::from(local), value) },
    }
}

script_handler! {
    /// `lane_binary` of operands its value declines: the general operation made in place
    /// (`lane_in_place`), which may reach guest code (a proxy's `has`, a
    /// `Symbol.hasInstance`, a `valueOf` or `toString`) or throw. A numeric local target takes
    /// the general path.
    #[inline(never)]
    fn lane_binary_general<>(cx, r, ip, i, view) {
        let operator = i.imm();
        if i.a & crate::bytecode::NUMERIC_LOCAL_TARGET != 0 {
            return exit(ip);
        }
        let (Some(left), Some(right)) = (lane_operand_value(cx, r, i.b), lane_operand_value(cx, r, i.c))
        else {
            return exit(ip);
        };
        let Some(value) = lane_in_place(cx, ip, |vm, code| vm.binary(code, operator, left, right)) else {
            return exit(ip);
        };
        // Guest code the operator ran made the activations frames, whose registers these are.
        let r = unsafe { (*cx).registers };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// A `Binary` record's value where it runs no guest code: Number arithmetic and
/// relations, then identity equality, an ordinary `instanceof` and an `in` whose key
/// and receiver (`Vm::plain_in`) need no guest code.
///
/// # Safety
/// `cx` is the running lane's context and `r` its registers.
#[inline(always)]
unsafe fn lane_binary_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    let left = lane_operand_value(cx, r, i.b)?;
    let right = lane_operand_value(cx, r, i.c)?;
    let operator = i.imm();
    match unsafe { vm(cx) }.number_binary(operator, left, right) {
        Some(value) => Some(value),
        // `undefined`, `null` or a Boolean among Numbers, as Sunspider's `x | 0` of a missing
        // element or an emulator's `flag & mask`; a string key's `"k" + i` first.
        None if let Some(value) = lane_concatenation_or_immediate(cx, operator, left, right) => Some(value),
        None if operator == super::operations::ADDITION => lane_concatenation(cx, left, right)
            .or_else(|| lane_bigint_value(cx, operator, left, right)),
        // A comparison, `instanceof`, or an ordinary-object `in` (`lane_relation_other`),
        // decides from the operands; any other operator past Numbers may be a BigInt's.
        None if operator <= super::operations::LAST_COMPARISON_OPERATOR
            || operator == INSTANCEOF_OPERATOR
            || operator == IN_OPERATOR =>
        {
            lane_relation::<H>(operator, left, right)
                .map(|holds| if holds { Value::TRUE } else { Value::FALSE })
        }
        None => lane_bigint_value(cx, operator, left, right),
    }
}

/// `+` of a string operand (`lane_concatenation`), as a key built as `"k" + i`, before the
/// immediate operands' tests, which a string fails; else `Vm::immediate_binary`.
#[inline(always)]
fn lane_concatenation_or_immediate<H: Host>(cx: *mut LaneContext<H>, operator: u32, left: Value, right: Value) -> Option<Value> {
    let heap = &unsafe { vm(cx) }.heap;
    if operator == super::operations::ADDITION && (heap.is_string(left) || heap.is_string(right))
        && let Some(value) = lane_concatenation(cx, left, right)
    {
        return Some(value);
    }
    unsafe { vm(cx) }.immediate_binary(operator, left, right)
}

/// `lane_binary_value` of a returning `Binary`, which keeps its operands encoded: two
/// integer registers decide it in place (`integer_binary`), as the operator-specialized
/// records decide theirs; any other operands take the general value.
///
/// # Safety
/// As for `lane_binary_value`.
#[inline(always)]
unsafe fn lane_returning_binary_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    let register = |encoded: u16| {
        let operand = crate::bytecode::Operand(encoded);
        (operand.kind() == Some(crate::bytecode::OperandKind::Register)).then(|| r.get(operand.payload()))
    };
    if let (Some(left), Some(right)) = (register(i.b), register(i.c))
        && let Some((left, right)) = Value::int_pair(left, right)
        && let Some(value) = super::operations::integer_binary(i.imm(), left, right)
    {
        return Some(value);
    }
    // A folded constant operand (`binding_time`) takes the integer path a register's
    // value does, decoded as any operand is (`lane_operand_value`).
    if let (Some(left), Some(right)) = (lane_operand_value(cx, r, i.b), lane_operand_value(cx, r, i.c))
        && let Some((left, right)) = Value::int_pair(left, right)
        && let Some(value) = super::operations::integer_binary(i.imm(), left, right)
    {
        return Some(value);
    }
    unsafe { lane_binary_value(cx, r, i) }
}

/// An operator of operands not both Numbers the lane computes in place: a concatenation of
/// strings for `+`, or BigInt arithmetic; `None` leaves it to the general path.
fn lane_other_operator_value<H: Host>(cx: *mut LaneContext<H>, operator: u32, left: Value, right: Value) -> Option<Value> {
    let concatenated = (operator == super::operations::ADDITION).then(|| lane_concatenation(cx, left, right));
    concatenated.flatten().or_else(|| lane_bigint_value(cx, operator, left, right))
}

/// A BigInt operator of two BigInts that raises nothing (`Vm::bigint_binary_value`), which
/// allocates the result; `None` leaves the operation, and any error, to the general path.
#[inline(never)]
fn lane_bigint_value<H: Host>(
    cx: *mut LaneContext<H>,
    operator: u32,
    left: Value,
    right: Value,
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    let value = vm.bigint_binary_value(operator, left, right)?;
    note_allocation(vm);
    Some(value)
}

/// `+` of operands that become strings without guest code (`Vm::primitive_concatenation`),
/// which allocates the result; `None` leaves any other `+` to the general path. Out of line,
/// so the numeric handlers that fall back to it keep their code.
#[inline(never)]
fn lane_concatenation<H: Host>(cx: *mut LaneContext<H>, left: Value, right: Value) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let value = vm.primitive_concatenation(unsafe { &*(*cx).code }, left, right)?;
    note_allocation(vm);
    Some(value)
}

/// A relation the lane decides without running guest code: Number comparison, identity
/// decided from the operand words, then `lane_relation_other`. Matches rather than
/// `Option::or_else` closures, which capture the operands by reference and, left out of
/// line, would cost the calling handler its tail call to the next record.
#[inline(always)]
fn lane_relation<H: Host>(operator: u32, left: Value, right: Value) -> Option<bool> {
    // Two heap values are no Numbers: their identity decides without the Number decode.
    if left.is_heap() && right.is_heap() && let Some(holds) = Vm::<H>::word_identity_equality(operator, left, right) {
        return Some(holds);
    }
    if let Some(holds) = super::operations::number_relation(operator, left, right) {
        return Some(holds);
    }
    if let Some(holds) = Vm::<H>::word_identity_equality(operator, left, right) {
        return Some(holds);
    }
    lane_relation_other::<H>(operator, left, right)
}

/// Return `value` from the running function at the record `ip`, as `Return` would: the
/// innermost activation completes (`lane_complete_activation`); a script frame the lane
/// pushed returns in place (`lane_return_script_frame`); any other VM frame returns the value
/// from this record (`lane_frame_return`).
macro_rules! lane_return_value {
    ($cx:expr, $ip:expr, $value:expr) => {
        lane_return_value!($cx, $ip, $value, NOT_LEAF)
    };
    ($cx:expr, $ip:expr, $value:expr, $leaf:expr) => {{
        let (cx, ip, value): (*mut LaneContext<H>, Ip, Value) = ($cx, $ip, $value);
        if let Some(resumed) = lane_complete_plain_activation::<H, { $leaf }>(cx, value) {
            resume!(cx, resumed)
        }
        resume!(cx, lane_return_value_general(cx, ip, value));
    }};
}

/// `lane_return_value!` past the common return (`lane_complete_plain_activation`): any
/// other activation's completion, or the frame's return. Out of line, so the returning
/// handlers keep their registers.
#[inline(never)]
fn lane_return_value_general<H: Host>(cx: *mut LaneContext<H>, ip: Ip, value: Value) -> Resumed {
    // Another program's activation, which a program that calls across programs returns from
    // as often as the common return, completes without the frame the other completions need.
    if let Some(resumed) = lane_complete_wasm_activation(cx, value) {
        return resumed;
    }
    if let Some(resumed) = lane_complete_cross_activation(cx, value) {
        return resumed;
    }
    if let Some(resumed) = lane_complete_array_step(cx, value) {
        return resumed;
    }
    if let Some(resumed) = lane_complete_returning_chain(cx, value) {
        return resumed;
    }
    lane_return_value_other(cx, ip, value)
}

/// The return of an array callback's activation (`Completion::ArrayStep`), one per element:
/// the step of its iteration, tested before the other completions `lane_complete_returning`
/// tests it after. `None` for any other activation.
#[inline(always)]
fn lane_complete_array_step<H: Host>(cx: *mut LaneContext<H>, value: Value) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    match vm.lane_stack.activations.last().map(|activation| &activation.kind) {
        Some(ActivationKind::Script(script)) if script.completion == Completion::ArrayStep => lane_step_array_iteration_in_place(cx, value),
        _ => None,
    }
}

/// `lane_return_value_general` of any other activation's completion, or the frame's return.
#[inline(never)]
fn lane_return_value_other<H: Host>(cx: *mut LaneContext<H>, ip: Ip, value: Value) -> Resumed {
    if let Some(resumed) = lane_complete_returning(cx, ip, value) {
        return resumed;
    }
    if !unsafe { (*cx).inline_calls } && unsafe { (*cx).script_calls } {
        // This completion already owns its value; native SSA may never have
        // written the Return register. Publish it if this frame cannot retire.
        return Resumed::Exit(lane_return_script_frame(cx, ip, value, true));
    }
    Resumed::Exit(lane_frame_return(unsafe { vm(cx) }, ip, value))
}


script_handler! {
    /// `lane_load_window_local_general` in an environment activation reading an initialized
    /// non-numeric binding its window or in-place storage holds densely, saving no
    /// registers; any other load takes the general handler.
    fn lane_load_window_local<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        // An activation's read of its window's storage, then a frame run's of the environment
        // storage a local access found (`lane_frame_storage`), each inline.
        if ENVIRONMENT {
            let (slot, registers) = environment_window_fields(i);
            if i.a & crate::bytecode::NUMERIC_LOCAL_TARGET == 0 {
                let value = if !unsafe { (*cx).registers }.env().is_deleted() {
                    // SAFETY: as `lane_load_window_local_general`'s read of the window's storage; `slot` is
                    // the 16-bit field of `environment_window_fields`.
                    unsafe { crate::staged::environment::concrete_environment_slot(window_storage(r, registers), slot as u16) }
                } else {
                    lane_known_frame_storage(cx).and_then(|(storage, _)| storage.dense().and_then(|dense| dense.dense_plain(slot)))
                };
                if let Some(value) = value {
                    r.set(i.a, value);
                    next!(cx, r, following(ip), view)
                }
            }
            sibling!(lane_load_window_local_general::<H, true>, r, ip, view)
        }
        let (slot, registers) = environment_window_fields(i);
        if i.a & crate::bytecode::NUMERIC_LOCAL_TARGET == 0
            && !unsafe { (*cx).registers }.env().is_deleted()
            && let Some(value) = Some(r.get(registers + WINDOW_LOCALS + slot as u16)).filter(|value| !value.is_deleted())
        {
            r.set(i.a, value);
            next!(cx, r, following(ip), view)
        }
        sibling!(lane_load_window_local_general::<H, false>, r, ip, view)
    }
}

script_handler! {
    /// `lane_store_window_local_general` in an environment activation writing an
    /// initialized binding its window or in-place storage holds densely, saving no
    /// registers; any other store takes the general handler. The write needs no barrier:
    /// an activation's environment is made during its lane run (`window_environment`), in a
    /// slot no collection has marked since, and no collection runs in the lane, so it is
    /// young.
    fn lane_store_window_local<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        let (slot, registers) = environment_window_fields(i);
        // An activation's store to an initialized binding of its window's storage, inline.
        if ENVIRONMENT && i.c == 0 && !unsafe { (*cx).registers }.env().is_deleted() {
            // SAFETY: as `lane_load_window_local_general`'s read of the window's storage.
            let storage = unsafe {
                &mut *(std::mem::transmute::<Value, u64>(r.get(registers + WINDOW_SLOTS))
                    as *mut crate::heap::EnvironmentSlots)
            };
            if let Some(binding) = storage.dense_mut().and_then(|dense| dense.dense_plain_mut(slot)) {
                debug_assert!(!unsafe { vm(cx) }.heap.is_old(r.get(registers + WINDOW_ENVIRONMENT)));
                let value = r.get(i.a);
                *binding = value;
                if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
                    r.set(register, value);
                }
                next!(cx, r, following(ip), view)
            }
            sibling!(lane_store_window_local_general::<H, true>, r, ip, view)
        }
        // A frame run's store to an initialized binding of its environment's storage, after
        // the environment's barrier.
        if ENVIRONMENT
            && i.c == 0
            && unsafe { (*cx).registers }.env().is_deleted()
            && let Some((storage, environment)) = lane_known_frame_storage(cx)
            && let Some(binding) = storage.dense_mut().and_then(|dense| dense.dense_plain_mut(slot))
        {
            let value = r.get(i.a);
            *binding = value;
            unsafe { vm(cx) }.heap.remember_cell(environment);
            if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
                r.set(register, value);
            }
            next!(cx, r, following(ip), view)
        }
        if ENVIRONMENT {
            sibling!(lane_store_window_local_window::<H, true>, r, ip, view)
        }
        sibling!(lane_store_window_local_window::<H, false>, r, ip, view)
    }
}

script_handler! {
    /// `lane_store_window_local` of a binding its window or in-place storage holds densely,
    /// out of line so the frame run's store keeps few registers; any other store takes the
    /// general handler.
    #[inline(never)]
    fn lane_store_window_local_window<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        let (slot, registers) = environment_window_fields(i);
        if !unsafe { (*cx).registers }.env().is_deleted() && (ENVIRONMENT || i.c == 0) {
            let value = r.get(i.a);
            let stored = if ENVIRONMENT {
                // SAFETY: as `lane_load_window_local_general`'s read of the window's storage, which no
                // other reference reads while this record runs; `slot` is the 16-bit field.
                unsafe {
                    if i.c == 0 {
                        crate::staged::environment::concrete_environment_slot_store(window_storage(r, registers), slot as u16, value)
                    } else {
                        crate::staged::environment::concrete_environment_slot_define(window_storage(r, registers), slot as u16, value)
                    }
                }
            } else {
                // SAFETY: an environment activation's window holds its locals after its
                // entries (`lane_activate_environment`).
                let binding = unsafe { &mut *r.0.add(usize::from(registers + WINDOW_LOCALS) + slot) };
                let initialized = !binding.is_deleted();
                if initialized { *binding = value; }
                initialized
            };
            if stored {
                // The window's environment is young, or a resumed generator's, which joined the
                // remembered set when its window opened (`generator_windows::open_window_locals`).
                debug_assert!({
                    let heap = &unsafe { vm(cx) }.heap;
                    let environment = r.get(registers + WINDOW_ENVIRONMENT);
                    !heap.is_old(environment) || heap.is_remembered_cell(environment)
                });
                if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
                    r.set(register, value);
                }
                next!(cx, r, following(ip), view)
            }
        }
        sibling!(lane_store_window_local_general::<H, ENVIRONMENT>, r, ip, view)
    }
}

lane_handler! {
    /// `lane_load_local` of a slot whose binding facts the view fixed
    /// (`specialize_frame_locals`): no mapped `arguments` mirrors it, and it moves into the
    /// frame's environment once that is captured exactly when `ENVIRONMENT`. A root body's
    /// frame, an uninitialized binding or a numeric local takes the general path.
    fn lane_load_frame_local<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        if !unsafe { (*cx).registers }.env().is_deleted() || i.a & crate::bytecode::NUMERIC_LOCAL_TARGET != 0 {
            return exit(ip);
        }
        let vm = unsafe { vm(cx) };
        let frame = &vm.frames[unsafe { (*cx).frame() }];
        if ENVIRONMENT && frame.captured {
            sibling!(lane_load_frame_environment_local::<H>, r, ip, view)
        }
        let value = (frame.function != super::ROOT_FUNCTION_ID)
            .then(|| frame.locals.get(i.imm() as usize).copied())
            .flatten();
        let Some(value) = value.filter(|value| !value.is_deleted()) else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    /// `lane_load_frame_local` of a slot the frame's captured environment holds; out of line,
    /// so the frame-local read saves no registers.
    #[inline(never)]
    fn lane_load_frame_environment_local<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let frame = &vm.frames[unsafe { (*cx).frame() }];
        let value = (frame.function != super::ROOT_FUNCTION_ID)
            .then(|| vm.heap.environment_slot(frame.env, i.imm() as usize))
            .flatten();
        let Some(value) = value.filter(|value| !value.is_deleted()) else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    /// `lane_store_local` of a slot `lane_load_frame_local`'s facts hold for, which is no
    /// self binding either: the store to an initialized (or initializing) binding.
    fn lane_store_frame_local<ENVIRONMENT: bool>(cx, r, ip, i, view) {
        if !unsafe { (*cx).registers }.env().is_deleted() {
            return exit(ip);
        }
        let value = r.get(i.a);
        let vm = unsafe { vm(cx) };
        let frame = &mut vm.frames[unsafe { (*cx).frame() }];
        if ENVIRONMENT && frame.captured {
            sibling!(lane_store_frame_environment_local::<H>, r, ip, view)
        }
        let binding = (frame.function != super::ROOT_FUNCTION_ID)
            .then(|| frame.locals.get_mut(i.imm() as usize))
            .flatten();
        match binding {
            Some(binding) if i.c != 0 || !binding.is_deleted() => *binding = value,
            _ => return exit(ip),
        }
        if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
            r.set(register, value);
        }
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    /// `lane_store_frame_local` to a slot the frame's captured environment holds; out of
    /// line, as `lane_load_frame_environment_local`.
    #[inline(never)]
    fn lane_store_frame_environment_local<>(cx, r, ip, i, view) {
        let value = r.get(i.a);
        let vm = unsafe { vm(cx) };
        let frame = &vm.frames[unsafe { (*cx).frame() }];
        let binding = (frame.function != super::ROOT_FUNCTION_ID)
            .then(|| vm.heap.environment_slot_mut(frame.env, i.imm() as usize))
            .flatten();
        match binding {
            Some(binding) if i.c != 0 || !binding.is_deleted() => *binding = value,
            _ => return exit(ip),
        }
        if let Some(register) = i.b.checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS) {
            r.set(register, value);
        }
        next!(cx, r, following(ip), view)
    }
}


script_handler! {
    /// `LoadCallee`: the function the innermost script activation runs, or the frame's when
    /// none does, as its activation filled its self binding (`Vm::initialize_frame_locals`).
    fn lane_load_callee<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = match vm.lane_stack.activations.last() {
            // A windowed activation names the owner of its frame, which is the record's.
            Some(Activation { kind: ActivationKind::Script(script), .. }) if !script.completion.is_windowed() => script.callee,
            Some(_) => return exit(ip),
            None => vm.frames[unsafe { (*cx).frame() }].context.callee().unwrap_or(Value::UNDEFINED),
        };
        r.set(i.a, callee);
        next!(cx, r, following(ip), view)
    }
}

/// A lane record's register field as a staged operand: a lane field names a register of the
/// running function, below `Operand::PAYLOAD_MASK`, so the operand's kind test folds away.
#[inline(always)]
fn record_register_operand(register: u16) -> crate::bytecode::Operand {
    // SAFETY: a register is at most `bytecode::REGISTER_MASK` (the bits above are the result
    // field's flags, which an operand field never carries), and that mask is the payload's.
    unsafe { std::hint::assert_unchecked(register <= crate::bytecode::Operand::PAYLOAD_MASK) };
    crate::bytecode::Operand::register(register)
}

script_handler! {
    /// `Binary` of operator `OP` on two registers, its operator and operand kinds resolved
    /// when the view was derived (`specialize_register_operands`): the fields hold the
    /// operand registers themselves. Integers take the fast path here, which saves no
    /// registers; the first other operand switches the record to `lane_operator_numbers`.
    fn lane_operator<OP: u32>(cx, r, ip, i, view) {
        // An arithmetic operator is its staged Number row in the int32 domain, widening as the
        // operator's Number result does; operands other than two int32 are the row's miss. A
        // division has no int32 form (its result is a binary64): its own path below takes it.
        if let Some(operation) = super::operations::NumberArithmetic::from_operator(OP)
            .filter(|operation| !matches!(operation, super::operations::NumberArithmetic::Divide))
        {
            let mut stage = crate::staged::Concrete::new(std::ptr::null());
            let mut frame = lane_frame::LaneFrame::<ACC_NONE>::new(r, Carried::script_in(cx, view));
            let row = crate::staged::Operation::Number(crate::staged::NumberOperation::Arithmetic {
                destination: i.a, left: record_register_operand(i.b), right: record_register_operand(i.c),
                operation, domain: crate::staged::Domain::Int32, overflow: crate::staged::Overflow::Widen,
                zero: crate::staged::NegativeZero::Exit });
            match crate::staged::step(&mut stage, &mut frame, row) {
                crate::staged::Step::Value(_) => next!(cx, r, following(ip), Carried::script_in(cx, view)),
                _ => sibling!(lane_operator_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view)),
            }
        }
        let (Some(left), Some(right)) = (r.int(i.b), r.int(i.c)) else {
            sibling!(lane_operator_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        let Some(value) = super::operations::integer_pair_operator::<OP>(left, right) else {
            sibling!(lane_operator_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator`'s first operands other than two integers, out of line: the feedback
    /// note is a call, and a call on a path that rejoins none left the integer handler a frame
    /// on its hit path (shrink-wrapping places the save in the entry block).
    #[inline(never)]
    fn lane_operator_first_miss<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_first_miss(cx, ip, r.get(i.b), r.get(i.c)) };
        requicken::<H>(ip, lane_operator_numbers::<H, OP>);
        sibling!(lane_operator_numbers::<H, OP>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Binary` of a comparison (`LAST_COMPARISON_OPERATOR`) on a register and a register
    /// (`CONSTANT` false: the operator stays in the immediate) or a constant (`CONSTANT`
    /// true: the operator moves to `c`), decoded when the view was derived
    /// (`specialize_register_operands`): the boolean of Number comparison of two integers
    /// (`integer_relation`). Any other pair takes `lane_relation_value_other`.
    fn lane_relation_value<CONSTANT: bool>(cx, r, ip, i, view) {
        let (operator, left, right) = lane_relation_operands::<CONSTANT>(r, i);
        let Some(holds) = super::operations::integer_relation(operator, left, right) else {
            sibling!(lane_relation_value_other::<H, CONSTANT>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// `lane_value_jump`'s `OP` of a comparison record (`lane_relation_value`), whose operator
/// the record carries.
const RELATION_VALUE: u32 = u32::MAX;

script_handler! {
    /// A value record whose next record branches on the value it writes (`lane_jump_false`, or
    /// `lane_jump_true` where `WHEN`; `specialize_value_jumps`): the value, its register write
    /// and the branch as one record. `OP` is `RELATION_VALUE` for an integer comparison kept as
    /// a value and also tested (`lane_relation_value`, as `return (s & HELD) != 0 || ...`), else
    /// the integer bitwise or remainder operator of a `lane_operator_integer_constant` record
    /// (`if (i & 3)`, whose canonical bytecode keeps the operator and the test apart). Any other
    /// operand takes the value's own path, which continues at the jump record. Without `WRITE`
    /// the value's register is dead past the jump (`specialize_value_jumps`), so only the branch
    /// reads the value.
    fn lane_value_jump<CONSTANT: bool, BACKWARD: bool, WHEN: bool, OP: u32, WRITE: bool>(cx, r, ip, i, view) {
        let holds = if OP == RELATION_VALUE {
            let (operator, left, right) = lane_relation_operands::<CONSTANT>(r, i);
            let Some(holds) = super::operations::integer_relation(operator, left, right) else {
                sibling!(lane_relation_value_other::<H, CONSTANT>, r, ip, Carried::script_in(cx, view))
            };
            if WRITE {
                r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
            }
            holds
        } else {
            let Some(value) = r.int(i.b).and_then(|left| super::operations::integer_pair_operator::<OP>(left, i.imm() as i32))
            else {
                sibling!(lane_operator_integer_constant_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view))
            };
            if WRITE {
                r.set(i.a, value);
            }
            // A bitwise result of two integers is an integer; a remainder may be -0 (`-8 % 4`).
            match value.as_int() {
                Some(integer) => integer != 0,
                None => value.as_number().is_some_and(|number| number != 0.0 && !number.is_nan()),
            }
        };
        let jump_ip = following(ip);
        if holds == WHEN {
            resume!(cx, lane_jump::<H>(r, jump_ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(jump_ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_relation_value` of operands other than two integers: the relations the lane
    /// decides without guest code (`lane_relation`); any other takes the general path. Out
    /// of line, so the integer case keeps few values live.
    #[inline(never)]
    fn lane_relation_value_other<CONSTANT: bool>(cx, r, ip, i, view) {
        let (operator, left, right) = lane_relation_operands::<CONSTANT>(r, i);
        // SAFETY: the record is a comparison record of the running view.
        unsafe { note_operands(cx, ip, left, right) };
        let Some(holds) = lane_relation::<H>(operator, left, right) else {
            return exit(ip);
        };
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// A `lane_relation_value` record's operator and operands.
#[inline(always)]
fn lane_relation_operands<const CONSTANT: bool>(
    r: Registers,
    i: &LaneInstruction,
) -> (u32, Value, Value) {
    if CONSTANT {
        (u32::from(i.c), r.get(i.b), i.constant())
    } else {
        (i.imm(), r.get(i.b), r.get(i.c))
    }
}

script_handler! {
    /// `lane_operator` at a site that has met operands other than two integers: any Numbers,
    /// through their double values. Other operands take `lane_operator_other`, out of line,
    /// so this handler saves no registers for them.
    #[inline(never)]
    fn lane_operator_numbers<OP: u32>(cx, r, ip, i, view) {
        // Arithmetic on two Numbers, its operands read in memory (`Registers::number`), an
        // overflowing int32 sum (SJCL's `w[i] + k[i] + h7`) included, past the general path.
        if matches!(OP, ADDITION | SUBTRACTION | MULTIPLICATION | DIVISION)
            && let Some((left, left_int)) = r.number_kind(i.b)
            && let Some((right, right_int)) = r.number_kind(i.c)
        {
            // Two int32 again, as a site that met a double once mostly sees afterwards
            // (`-a + i` after its one `-0`): the checked int32 step, which widens itself,
            // in place of the round trip through doubles. Only two int32 can widen.
            if left_int && right_int {
                let value = if OP == DIVISION {
                    super::operations::number_operator::<OP>(left, right).map(Value::number)
                } else {
                    super::operations::integer_pair_operator::<OP>(r.i32(i.b), r.i32(i.c))
                };
                if let Some(value) = value {
                    // SAFETY: an arithmetic record of the running view.
                    unsafe { note_widened(cx, ip, value) };
                    r.set(i.a, value);
                    next!(cx, r, following(ip), Carried::script_in(cx, view))
                }
            } else if let Some(number) = super::operations::number_operator::<OP>(left, right) {
                r.set(i.a, Value::number(number));
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
        }
        let Some(value) = super::operations::number_value_operator::<OP>(r.get(i.b), r.get(i.c))
        else {
            sibling!(lane_operator_other::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_pair_result(cx, ip, r.get(i.b), r.get(i.c), value) };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator` whose double result may stay raw (`raw_results::raw_result_allowed`,
    /// `specialize_raw_operators`): integers as there; the first other operands switch the
    /// record to `lane_operator_numbers_raw`.
    fn lane_operator_raw<OP: u32>(cx, r, ip, i, view) {
        let (Some(left), Some(right)) = (r.int(i.b), r.int(i.c)) else {
            sibling!(lane_operator_first_miss_raw::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        let Some(value) = super::operations::integer_pair_operator::<OP>(left, right) else {
            sibling!(lane_operator_first_miss_raw::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_first_miss` of `lane_operator_raw`.
    #[inline(never)]
    fn lane_operator_first_miss_raw<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_first_miss(cx, ip, r.get(i.b), r.get(i.c)) };
        requicken::<H>(ip, lane_operator_numbers_raw::<H, OP>);
        sibling!(lane_operator_numbers_raw::<H, OP>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_numbers` whose result of two Numbers not both int32 keeps its double
    /// form (`raw_results::raw_number`); every other case runs `lane_operator_numbers`.
    fn lane_operator_numbers_raw<OP: u32>(cx, r, ip, i, view) {
        if let Some((left, left_int)) = r.number_kind(i.b)
            && let Some((right, right_int)) = r.number_kind(i.c)
            && !(left_int && right_int)
            && let Some(number) = super::operations::number_operator::<OP>(left, right)
        {
            r.set(i.a, raw_results::raw_number(number));
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        sibling!(lane_operator_numbers::<H, OP>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_numbers` of operands not both Numbers: a concatenation of strings or
    /// BigInt arithmetic in place; anything else takes the general path.
    #[inline(never)]
    fn lane_operator_other<OP: u32>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), r.get(i.c));
        // Two heap operands neither a string: BigInt arithmetic first, which notes its kind
        // without classifying the operands and skips the concatenation's tests.
        if left.is_heap() && right.is_heap() && !(unsafe { vm(cx) }).heap.is_string(left) && !(unsafe { vm(cx) }).heap.is_string(right)
            && let Some(value) = lane_bigint_value(cx, OP, left, right)
        {
            // SAFETY: the record is an arithmetic record of the running view.
            unsafe { note_kind(cx, ip, OperandKinds::BIGINT) };
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_operands(cx, ip, left, right) };
        let Some(value) = lane_other_operator_value(cx, OP, r.get(i.b), r.get(i.c)) else {
            return exit(ip);
        };
        // A `+` record of its own that joined a string: later runs go straight to the join
        // (`lane_operator_strings`), past the Number and BigInt tests and the feedback note,
        // which already holds the string kind.
        if OP == super::operations::ADDITION && unsafe { vm(cx) }.heap.is_string(value) {
            let own = unsafe { (*ip).handler };
            if own == lane_operator_numbers::<H, OP> as Handler as *const ()
                || own == lane_operator_numbers_raw::<H, OP> as Handler as *const ()
            {
                requicken::<H>(ip, lane_operator_strings::<H>);
            }
        }
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_numbers` of `+` at a site that has joined strings: two strings joined
    /// in place (`Vm::intern_dynamic_concat`), or a string and a Number by
    /// `lane_concatenation`. Any other operands give the record back to
    /// `lane_operator_numbers`, which notes them.
    fn lane_operator_strings<>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), r.get(i.c));
        let vm = unsafe { vm(cx) };
        let value = if vm.heap.is_string(left) && vm.heap.is_string(right) {
            let value = vm.intern_dynamic_concat(left, right);
            note_allocation(vm);
            value
        } else {
            lane_concatenation(cx, left, right)
        };
        if let Some(value) = value {
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        requicken::<H>(ip, lane_operator_numbers::<H, { super::operations::ADDITION }>);
        sibling!(lane_operator_numbers::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// Two arithmetic operators, the second taking the first's result as an operand, the
    /// `(a + b) * c` of compiled code (`specialize_operator_pairs`), each as the lane's
    /// operator records compute it (`lane_number_operator`); after a first step on doubles
    /// the second reads its result as the double it stores. Other operands run the record
    /// whose step declines them, which stays in place.
    ///
    /// With `FIRST_DEAD` the first result's register is dead after the pair (liveness, or the
    /// second overwrites it), so it is stored only when the second record runs on its own.
    /// With `SECOND_RAW` a double second result keeps its double form (`raw_results`).
    fn lane_operator_pair<FIRST: u32, SECOND: u32, FIRST_DEAD: bool, SECOND_RAW: bool>(cx, r, ip, i, view) {
        use super::operations::{int32_operator, number_operator};
        // SAFETY: the pair is two records, the second never the view's last.
        let second = unsafe { &*following(ip) };
        // Two int32 results in a row stay raw i32: the first never gets re-tested as an
        // operand of the second (V8-v7 Crypto am3, `a*b + c` on 14-bit digits).
        // One operand at a time, as `integer_operator`: a combined pair probe cost the
        // int-left double-right pairs (V8-v7 NavierStokes) a second tag test.
        // Both int32 or neither path: the integer forms below run only under this one pair
        // of in-memory tag tests (`Registers::int`), so a double operand pays them once.
        let ints = match r.int(i.b) {
            Some(l) => r.int(i.c).map(|rr| (l, rr)),
            None => None,
        };
        if let Some((l, rr)) = ints
            && let Some(first) = int32_operator::<FIRST>(l, rr)
        {
            let operand = |register: u16| if register == i.a { Some(first) } else { r.int(register) };
            if let (Some(second_left), Some(second_right)) = (operand(second.b), operand(second.c))
                && let Some(value) = int32_operator::<SECOND>(second_left, second_right)
            {
                if !FIRST_DEAD {
                    r.set(i.a, Value::integer(first));
                }
                r.set(second.a, Value::integer(value));
                next!(cx, r, following(following(ip)), Carried::script(cx))
            }
        }
        if let Some((l, rr)) = ints
            && let Some(value) = super::operations::integer_pair_operator::<FIRST>(l, rr)
        {
            let operand = |register: u16| if register == i.a { value } else { r.get(register) };
            let Some(result) = lane_number_operator::<SECOND>(operand(second.b), operand(second.c)) else {
                r.set(i.a, value);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            };
            if !FIRST_DEAD {
                r.set(i.a, value);
            }
            r.set(second.a, result);
            next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
        }
        let Some(first) = (match (r.number(i.b), r.number(i.c)) {
            (Some(left), Some(right)) => number_operator::<FIRST>(left, right),
            _ => None,
        }) else {
            sibling!(lane_operator_numbers::<H, FIRST>, r, ip, Carried::script_in(cx, view))
        };
        // One operand at a time, each declining on its own branch: an `Option` of the
        // first result (a zip, then a closure) stayed a constant flag register tested after
        // both reads (`mov bl,1 .. test bl,bl`, V8-v7 NavierStokes).
        macro_rules! second_operand {
            ($register:expr) => {
                if $register == i.a {
                    first
                } else if let Some(number) = r.number($register) {
                    number
                } else {
                    r.set(i.a, Value::number(first));
                    next!(cx, r, following(ip), Carried::script_in(cx, view))
                }
            };
        }
        let second_left = second_operand!(second.b);
        let second_right = second_operand!(second.c);
        let Some(value) = number_operator::<SECOND>(second_left, second_right) else {
            r.set(i.a, Value::number(first));
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        };
        if !FIRST_DEAD {
            r.set(i.a, Value::number(first));
        }
        r.set(second.a, if SECOND_RAW { raw_results::raw_number(value) } else { Value::number(value) });
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

/// Number operator `OP` as the lane's operator records compute it: two integers by
/// `integer_operator`, any other Numbers through their double values.
#[inline(always)]
fn lane_number_operator<const OP: u32>(left: Value, right: Value) -> Option<Value> {
    // A branch, not `Option::or_else`: the closure was left out of line as a call per
    // double operation (V8-v7 Crypto, 0.7M calls).
    if let Some(value) = super::operations::integer_operator::<OP>(left, right) {
        return Some(value);
    }
    super::operations::number_value_operator::<OP>(left, right)
}

script_handler! {
    /// `lane_operator` whose right operand is a constant, carried in the record.
    fn lane_operator_constant<OP: u32>(cx, r, ip, i, view) {
        let Some(value) = super::operations::integer_operator::<OP>(r.get(i.b), i.constant())
        else {
            sibling!(lane_operator_constant_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_constant`'s first operand other than an integer, out of line, as
    /// `lane_operator_first_miss`.
    #[inline(never)]
    fn lane_operator_constant_first_miss<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_first_miss(cx, ip, r.get(i.b), i.constant()) };
        requicken::<H>(ip, lane_operator_constant_numbers::<H, OP>);
        sibling!(lane_operator_constant_numbers::<H, OP>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_constant` of an integer constant, which the view proved when it chose
    /// the handler (`constant_operator_handler`) and carries as the record's immediate: only
    /// the register operand's tag is tested.
    fn lane_operator_integer_constant<OP: u32>(cx, r, ip, i, view) {
        let Some(value) = r.int(i.b).and_then(|left| super::operations::integer_pair_operator::<OP>(left, i.imm() as i32))
        else {
            sibling!(lane_operator_integer_constant_first_miss::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_integer_constant`'s first operand other than an integer, out of line,
    /// as `lane_operator_first_miss`.
    #[inline(never)]
    fn lane_operator_integer_constant_first_miss<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_first_miss(cx, ip, r.get(i.b), Value::integer(i.imm() as i32)) };
        requicken::<H>(ip, lane_operator_integer_constant_numbers::<H, OP>);
        sibling!(lane_operator_integer_constant_numbers::<H, OP>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_constant_numbers` and `lane_operator_constant_other` of
    /// `lane_operator_integer_constant`'s integer, out of line.
    #[inline(never)]
    fn lane_operator_integer_constant_numbers<OP: u32>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), Value::integer(i.imm() as i32));
        let value = super::operations::number_value_operator::<OP>(left, right).or_else(|| {
            // SAFETY: the record is an arithmetic record of the running view.
            unsafe { note_operands(cx, ip, left, right) };
            (OP == super::operations::ADDITION).then(|| lane_concatenation(cx, left, right)).flatten()
        });
        let Some(value) = value else {
            return exit(ip);
        };
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_pair_result(cx, ip, left, right, value) };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_numbers` with a constant right operand; other operands take
    /// `lane_operator_constant_other`, out of line.
    #[inline(never)]
    fn lane_operator_constant_numbers<OP: u32>(cx, r, ip, i, view) {
        let Some(value) = super::operations::number_value_operator::<OP>(r.get(i.b), i.constant())
        else {
            sibling!(lane_operator_constant_other::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The double a `lane_operator_double_constant` record carries as its constant: a Number no
/// integer holds, whose value bits are its double's (`constant_operator_handler`).
#[inline(always)]
fn double_constant(i: &LaneInstruction) -> f64 {
    f64::from_bits(i.constant().to_bits())
}

script_handler! {
    /// `lane_operator_constant` of an arithmetic operator (`fused_arithmetic`) whose constant is
    /// a double no integer holds, proved when the view chose the handler
    /// (`constant_operator_handler`): no integer step, which such a constant always declines,
    /// and no tag test of the constant. A left operand other than a Number takes
    /// `lane_operator_constant_numbers`.
    fn lane_operator_double_constant<OP: u32>(cx, r, ip, i, view) {
        let Some(value) = r.get(i.b).as_number().and_then(|left| super::operations::number_operator::<OP>(left, double_constant(i)))
        else {
            sibling!(lane_operator_constant_numbers::<H, OP>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, Value::number(value));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_pair` whose first operator takes a double constant
    /// (`lane_operator_double_constant`), the `a * 0.5 + b` of compiled code: the first double
    /// feeds the second as it is, so only the pair's result is made a Number; each operator
    /// rounds once, as the two records do. Other operands run the record whose step declines
    /// them, which stays in place.
    fn lane_operator_constant_pair<FIRST: u32, SECOND: u32, FIRST_DEAD: bool>(cx, r, ip, i, view) {
        use super::operations::number_operator;
        let Some(first) = r.get(i.b).as_number().and_then(|left| number_operator::<FIRST>(left, double_constant(i)))
        else {
            sibling!(lane_operator_constant_numbers::<H, FIRST>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: the pair is two records, the second never the view's last.
        let second = unsafe { &*following(ip) };
        // One operand at a time, each declining on its own: a zip of the two options kept
        // the first result's constant `Some` as flag registers tested after both reads.
        let operand = |register: u16| if register == i.a { Some(first) } else { r.get(register).as_number() };
        let (Some(second_left), Some(second_right)) = (operand(second.b), operand(second.c)) else {
            r.set(i.a, Value::number(first));
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        };
        let Some(value) = number_operator::<SECOND>(second_left, second_right) else {
            r.set(i.a, Value::number(first));
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        };
        if !FIRST_DEAD {
            r.set(i.a, Value::number(first));
        }
        r.set(second.a, Value::number(value));
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_operator_other` of `lane_operator_constant_numbers`, whose right operand is the
    /// record's constant.
    #[inline(never)]
    fn lane_operator_constant_other<OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the record is an arithmetic record of the running view.
        unsafe { note_operands(cx, ip, r.get(i.b), i.constant()) };
        let Some(value) = lane_other_operator_value(cx, OP, r.get(i.b), i.constant()) else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An addition or subtraction (`OP`) of a register and a register or, where `CONSTANT`, an
    /// integer constant (the record's immediate, `lane_operator_integer_constant`), whose
    /// result the next record truncates to an int32 (`| 0`) and nothing after reads
    /// (`specialize_int32_truncations`), as `(a + b) | 0` compiles: the exact sum of two int32s
    /// is an integer a double holds, so its truncation is their wrapping sum, which the record
    /// writes to the truncation's register. Other operands run the operator's own record
    /// (`lane_operator`, `lane_operator_integer_constant`), then the truncation's.
    fn lane_operator_int32<OP: u32, CONSTANT: bool>(cx, r, ip, i, view) {
        let right = if CONSTANT { Some(i.imm() as i32) } else { r.int(i.c) };
        let (Some(left), Some(right)) = (r.int(i.b), right) else {
            let own: Handler = if CONSTANT { lane_operator_integer_constant::<H, OP> } else { lane_operator::<H, OP> };
            sibling!(own, r, ip, Carried::script_in(cx, view))
        };
        let value = if OP == super::operations::SUBTRACTION { left.wrapping_sub(right) } else { left.wrapping_add(right) };
        // SAFETY: the pair is two records, the second never the view's last.
        let truncation = unsafe { &*following(ip) };
        r.set(truncation.a, Value::integer(value));
        next!(cx, r, following(following(ip)), Carried::script_in(cx, view))
    }
}

/// `plain_keyed_get` at lane site `ip`, recording the own slot a symbol or index key's proof
/// gives for the site's next read (`Vm::site_keyed_own_read`). Out of line: the site's hits
/// skip it.
#[inline(never)]
fn lane_site_keyed_get<H: Host>(vm: &mut Vm<H>, ip: Ip, base: Value, key: Value) -> Option<Value> {
    let value = vm.plain_keyed_get(base, key)?;
    vm.record_site_keyed_read(ip.addr(), base, key);
    Some(value)
}

/// A string's element in the lane (`Vm::string_element`), which allocates its one-unit string.
#[inline(never)]
fn lane_string_element<H: Host>(vm: &mut Vm<H>, base: Value, key: Value) -> Option<Value> {
    let value = vm.string_element(base, key)?;
    note_allocation(vm);
    Some(value)
}

lane_handler! {
    /// A present dense array element; any other read takes the general path.
    fn lane_get_index<>(cx, r, ip, i, view) {
        let (Some(base), Some(key)) =
            (lane_operand_value(cx, r, i.b), lane_operand_value(cx, r, i.c))
        else {
            return exit(ip);
        };
        let vm = unsafe { vm(cx) };
        let key = vm.canonical_index_key(key);
        let Some(value) = vm
            .dense_array_element(base, key)
            .or_else(|| vm.plain_typed_element(base, key))
            .or_else(|| lane_string_element(vm, base, key))
            .or_else(|| vm.absent_array_element(base, key))
            .or_else(|| vm.plain_keyed_get(base, key))
            .or_else(|| vm.keyed_array_length(base, key))
        else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `element_read_row` past a record array.
    #[inline(never)]
    fn lane_get_index_slot<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (base, key) = (r.get(i.b), r.get(i.c));
        // A symbol-keyed read this site made of the same shape and key reads its own slot.
        if let Some(value) = vm.site_keyed_own_read(ip.addr(), base, key) {
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        let Some(value) = lane_index_slot_element(vm, ip, base, key) else {
            sibling!(lane_get_index_getter::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_index_slot` of an element no data read answers: an index getter's
    /// activation (`lane_index_getter_activation`), else the general path. Apart, since the
    /// activation's result is a stack temporary of the handler that makes it.
    #[inline(never)]
    fn lane_get_index_getter<>(cx, r, ip, i, view) {
        let (base, key) = (r.get(i.b), r.get(i.c));
        match proxy_traps::lane_keyed_get_trap(cx, r, ip, base, key) {
            Some(Ok((registers, base))) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Some(Err(next)) => return next,
            None => {}
        }
        let vm = unsafe { vm(cx) };
        if !vm.lane_stack.activations.is_empty() && vm.proved_symbol_getter(base, key).is_none() {
            resume!(cx, lane_get_index_beside_activations(cx, ip, i, base, key));
        }
        match lane_index_getter_activation(cx, r, ip, base, key) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

/// A `GetIndex` of `base[key]` past the lane's reads within a frameless activation: the
/// general read made in place (`lane_in_place`), as `lane_get_field_beside_activations`
/// makes a field's, so a getter, proxy or throw makes the activations frames only when it
/// runs.
#[cold]
#[inline(never)]
fn lane_get_index_beside_activations<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    i: &LaneInstruction,
    base: Value,
    key: Value,
) -> Resumed {
    let Some(value) = lane_in_place(cx, ip, |vm, code| vm.get_index(code, base, key)) else {
        return Resumed::Exit(exit(ip));
    };
    // Guest code the read ran made the activations frames, whose registers these are.
    let r = unsafe { (*cx).registers };
    r.set(i.a, value);
    Resumed::At(r, following(ip), Carried::script(cx))
}

/// `base[key]` of a data element `lane_get_index_slot` reads past a record array: a dense
/// or absent array element, a keyed read this site recorded, a typed array's or a string's
/// element. Out of line, as `lane_set_index_slot_store`.
#[inline(never)]
fn lane_index_slot_element<H: Host>(vm: &mut Vm<H>, ip: Ip, base: Value, key: Value) -> Option<Value> {
    let key = vm.canonical_index_key(key);
    // A typed array answers every index read itself, never its prototype chain, and a string
    // every index inside its length, so their reads come before the ordinary array probes,
    // which would only decline them.
    vm.dense_array_element(base, key)
        .or_else(|| lane_named_key_element(ip, vm, base, key))
        .or_else(|| lane_typed_array_element(ip, vm, base, key))
        .or_else(|| lane_string_index_element(ip, vm, base, key))
        .or_else(|| vm.absent_array_element(base, key))
        .or_else(|| lane_site_keyed_get(vm, ip, base, key))
        .or_else(|| vm.keyed_array_length(base, key))
}

/// A typed array's element at an index key (`Vm::plain_typed_element`), which no dense array
/// read before it serves: the site then tries it first (`lane_get_index_typed`), as a typed
/// store's site does (`lane_typed_array_store`).
fn lane_typed_array_element<H: Host>(ip: Ip, vm: &mut Vm<H>, base: Value, key: Value) -> Option<Value> {
    let value = vm.plain_typed_element(base, key)?;
    requicken::<H>(ip, typed_kind_handler::<H>(vm.typed_array_kind_of(base), true));
    Some(value)
}

/// The typed array element record for a site that has seen kind `kind`: its kind variant
/// (`lane_get_index_typed_kind`, `lane_set_index_typed_kind`), or the any-kind record for a
/// kind no variant serves; `read` picks reads, else stores.
fn typed_kind_handler<H: Host>(kind: Option<TypedArrayKind>, read: bool) -> Handler {
    macro_rules! kinds {
        ($($kind:ident),*) => {
            match kind {
                $(Some(TypedArrayKind::$kind) => if read {
                    lane_get_index_typed_kind::<H, { TypedArrayKind::$kind as usize }> as Handler
                } else {
                    lane_set_index_typed_kind::<H, { TypedArrayKind::$kind as usize }> as Handler
                },)*
                _ => if read { lane_get_index_typed::<H> as Handler } else { lane_set_index_typed::<H> as Handler },
            }
        };
    }
    kinds!(Uint8, Uint8Clamped, Uint16, Uint32, Int8, Int16, Int32, Float32, Float64)
}

script_handler! {
    /// `element_read_row` at a site that read a typed array: a non-BigInt typed
    /// array's element at an integer index, or `undefined` past its end, is the whole read;
    /// any other read takes the generic order (`element_read_row`).
    fn lane_get_index_typed<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { vm(cx) }).typed_cached_element::<{ super::typed_array_access::ANY_TYPED_KIND }>(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_get_index_typed_fill::<H, { super::typed_array_access::ANY_TYPED_KIND }>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_index_typed` at a site that has read typed arrays of one kind only, `KIND`,
    /// whose element access is compiled for it. Any other read makes the site any-kind
    /// (`lane_get_index_typed`) and runs there.
    fn lane_get_index_typed_kind<KIND: usize>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { vm(cx) }).typed_cached_element::<KIND>(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_get_index_typed_fill::<H, KIND>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A typed read whose view has no current cached entry (`Vm::typed_cached_element`):
    /// the entry made (`Vm::fill_typed_view`) and the read through the view's cells; any
    /// other read takes the general typed read, or makes a one-kind site any-kind.
    #[inline(never)]
    fn lane_get_index_typed_fill<KIND: usize>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (base, key) = (r.get(i.b), r.get(i.c));
        vm.fill_typed_view(base);
        let Some(value) = vm.typed_element_quick::<KIND>(base, key) else {
            if KIND == super::typed_array_access::ANY_TYPED_KIND {
                sibling!(lane_get_index_typed_full::<H>, r, ip, view)
            }
            sibling!(lane_get_index_typed_mixed::<H>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An address computed as C computes one and its typed array read, three records as one
    /// (`specialize_typed_addresses`): `t = x + K` (`lane_operator_integer_constant` of
    /// addition), with `SHIFT` `u = t >> S` (of right shift), then `base[u]` (or `base[t]`)
    /// through the view cache (`Vm::typed_cached_element`), as mandreel's `heapU16[(p+K)>>1]`.
    /// The intermediates are written as their records write them. Any other case (a non-int
    /// `x`, a sum past int32 unshifted, a view with no current entry) runs the addition's own
    /// record and the records after it.
    fn lane_typed_address_get<SHIFT: bool, KIND: usize>(cx, r, ip, i, view) {
        if KIND == UNSEEN_TYPED_KIND {
            sibling!(lane_typed_address_miss::<H, SHIFT, KIND, true>, r, ip, Carried::script_in(cx, view))
        }
        let Some(x) = r.int(i.b) else {
            sibling!(lane_operator_integer_constant::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
        };
        let sum = x.wrapping_add(i.imm() as i32);
        // SAFETY: the pass fused this record with the one or two after it in the view.
        let (key, read) = if SHIFT {
            let shift = unsafe { &*following(ip) };
            (sum >> (shift.imm() & 31), unsafe { &*following(following(ip)) })
        } else {
            // An unshifted sum past int32 is a double key: the records' own path reads it.
            if i64::from(x) + i64::from(i.imm() as i32) != i64::from(sum) {
                sibling!(lane_operator_integer_constant::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
            }
            (sum, unsafe { &*following(ip) })
        };
        let Some(value) = (unsafe { vm(cx) }).typed_cached_element::<KIND>(r.get(read.b), Value::integer(key)) else {
            sibling!(lane_typed_address_miss::<H, SHIFT, KIND, true>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, Value::integer(sum));
        if SHIFT {
            // SAFETY: as above.
            r.set(unsafe { (*following(ip)).a }, Value::integer(key));
        }
        r.set(read.a, value);
        let after = if SHIFT { following(following(following(ip))) } else { following(following(ip)) };
        next!(cx, r, after, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_typed_address_get` of a store: `base[(x + K) >> S] = v` (or `base[x + K] = v`)
    /// as one record (`specialize_typed_addresses`), through the view cache
    /// (`Vm::typed_cached_store`). Any other case runs the addition's own record.
    fn lane_typed_address_set<SHIFT: bool, KIND: usize>(cx, r, ip, i, view) {
        if KIND == UNSEEN_TYPED_KIND {
            sibling!(lane_typed_address_miss::<H, SHIFT, KIND, false>, r, ip, Carried::script_in(cx, view))
        }
        let Some(x) = r.int(i.b) else {
            sibling!(lane_operator_integer_constant::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
        };
        let sum = x.wrapping_add(i.imm() as i32);
        // SAFETY: the pass fused this record with the one or two after it in the view.
        let (key, store) = if SHIFT {
            let shift = unsafe { &*following(ip) };
            (sum >> (shift.imm() & 31), unsafe { &*following(following(ip)) })
        } else {
            if i64::from(x) + i64::from(i.imm() as i32) != i64::from(sum) {
                sibling!(lane_operator_integer_constant::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
            }
            (sum, unsafe { &*following(ip) })
        };
        if !(unsafe { vm(cx) }).typed_cached_store::<KIND>(r.get(store.b), Value::integer(key), r.get(store.a)) {
            sibling!(lane_typed_address_miss::<H, SHIFT, KIND, false>, r, ip, Carried::script_in(cx, view))
        }
        r.set(i.a, Value::integer(sum));
        if SHIFT {
            // SAFETY: as above.
            r.set(unsafe { (*following(ip)).a }, Value::integer(key));
        }
        let after = if SHIFT { following(following(following(ip))) } else { following(following(ip)) };
        next!(cx, r, after, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_typed_address_get` (or `_set`) whose access found no current view entry. A base
    /// that is no typed array (a plain array read `a[i + 1]` has the same shape) makes the
    /// record its addition again for good; a typed array base gets its entry made
    /// (`Vm::fill_typed_view`) and makes the record the variant of its kind, or any-kind for
    /// a second kind. Either way the addition's own record runs.
    #[inline(never)]
    fn lane_typed_address_miss<SHIFT: bool, KIND: usize, READ: bool>(cx, r, ip, i, view) {
        // SAFETY: the pass fused this record with the one or two after it in the view.
        let access = unsafe { &*if SHIFT { following(following(ip)) } else { following(ip) } };
        let vm = unsafe { vm(cx) };
        let base = r.get(access.b);
        match vm.typed_array_kind_of(base) {
            None => requicken::<H>(ip, lane_operator_integer_constant::<H, { super::operations::ADDITION }>),
            Some(kind) => {
                if KIND == UNSEEN_TYPED_KIND {
                    requicken::<H>(ip, typed_address_handler::<H, SHIFT, READ>(Some(kind)));
                } else if KIND != super::typed_array_access::ANY_TYPED_KIND && kind != crate::heap::TYPED_ARRAYS[KIND % TypedArrayKind::COUNT].kind {
                    requicken::<H>(ip, typed_address_handler::<H, SHIFT, READ>(None));
                }
                vm.fill_typed_view(base);
            }
        }
        sibling!(lane_operator_integer_constant::<H, { super::operations::ADDITION }>, r, ip, Carried::script_in(cx, view))
    }
}

/// The `KIND` of a fused address record that has run no access yet: its first access runs
/// the miss (`lane_typed_address_miss`), which picks the variant of the kind it sees.
const UNSEEN_TYPED_KIND: usize = usize::MAX - 1;

/// The fused address record (`lane_typed_address_get`, `lane_typed_address_set`) for a site
/// that has seen kind `kind`, or the any-kind record for no kind or one no variant serves.
fn typed_address_handler<H: Host, const SHIFT: bool, const READ: bool>(kind: Option<TypedArrayKind>) -> Handler {
    macro_rules! kinds {
        ($($kind:ident),*) => {
            match kind {
                $(Some(TypedArrayKind::$kind) => if READ {
                    lane_typed_address_get::<H, SHIFT, { TypedArrayKind::$kind as usize }> as Handler
                } else {
                    lane_typed_address_set::<H, SHIFT, { TypedArrayKind::$kind as usize }> as Handler
                },)*
                _ => if READ {
                    lane_typed_address_get::<H, SHIFT, { super::typed_array_access::ANY_TYPED_KIND }> as Handler
                } else {
                    lane_typed_address_set::<H, SHIFT, { super::typed_array_access::ANY_TYPED_KIND }> as Handler
                },
            }
        };
    }
    kinds!(Uint8, Uint8Clamped, Uint16, Uint32, Int8, Int16, Int32, Float32, Float64)
}

script_handler! {
    /// A kind variant's miss (`lane_get_index_typed_kind`): the site becomes any-kind.
    #[inline(never)]
    fn lane_get_index_typed_mixed<>(cx, r, ip, i, view) {
        requicken::<H>(ip, lane_get_index_typed::<H>);
        sibling!(lane_get_index_typed::<H>, r, ip, view)
    }
}

script_handler! {
    /// `lane_get_index_typed` past its quick read (`Vm::typed_element_quick`): any typed
    /// array read that allocates nothing (`Vm::plain_typed_element`), or the generic order.
    #[inline(never)]
    fn lane_get_index_typed_full<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { vm(cx) }).plain_typed_element(r.get(i.b), r.get(i.c)) else {
            sibling!(element_read_row::<H>(), r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `delete base[key]` by the staged row: a string key on an ordinary object runs no guest
    /// code (`lane_delete_value`); any other deletion takes the general path.
    #[inline(never)]
    fn lane_delete<>(cx, r, ip, i, view) {
        if !lane_frame::staged_delete(cx, r, [i.a, i.b, i.c], i.imm() != 0) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// A lane `GetIndex` of a symbol key whose proof records an inherited getter
/// (`Vm::proved_symbol_getter`): the getter runs as a frameless activation of the read's
/// record, as `lane_getter_activation` runs a field's, with the base as receiver. `Err`
/// carries the record to continue at: the general path for any other read.
#[inline(never)]
fn lane_index_getter_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    base: Value,
    key: Value,
) -> Result<(Registers, Ip), Ip> {
    if !unsafe { (*cx).script_calls } {
        return Err(exit(ip));
    }
    let vm = unsafe { vm(cx) };
    let Some(getter) = vm.proved_symbol_getter(base, key) else {
        return Err(exit(ip));
    };
    lane_activate_getter(cx, r, ip, getter, base, None)
}

script_handler! {
    /// `element_write_row` whose stored value the next record, a register `Move`, copies, the
    /// `t = a[i] = v` of compiled code (`specialize_store_moves`): the store and the copy as
    /// one record, the copy carried as `lane_row` carries a `Move`. A store the fast path leaves
    /// runs the store's own slow path, which continues at the `Move` record.
    fn lane_set_index_move<>(cx, r, ip, i, view) {
        let (object, key, value) = (r.get(i.b), r.get(i.c), r.get(i.a));
        if !(unsafe { vm(cx) }).try_replace_record_element(object, key, value) {
            sibling!(lane_set_index_slot::<H>, r, ip, Carried::script_in(cx, view))
        }
        // SAFETY: the pair is two records, the second never the view's last.
        let copy = unsafe { &*following(ip) };
        produce!(cx, r, following(ip), copy.a, value, Carried::script_in(cx, view))
    }
}

/// The value the proved store of `SetIndex` record `i` (`ArrayStorageProofs::replace`) of a
/// base its loop does not redefine (`specialize_proved_arrays`) wrote; `None` stores
/// nothing.
#[inline(always)]
fn lane_proved_store<H: Host>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> Option<Value> {
    let value = r.get(i.a);
    let index = proof_key(r.get(i.c));
    unsafe { (*cx).proofs.replace(i.b, r.get(i.b), index, value) }.then_some(value)
}

/// `lane_proved_store` of a heap value (`arr[i] = o`): through the proof where the write
/// barrier admits the store unlogged (`Heap::array_store_unlogged`). Out of line, so the
/// immediate store keeps its few registers.
#[inline(always)]
fn lane_proved_heap_store<H: Host>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> bool {
    let (base, value) = (r.get(i.b), r.get(i.a));
    value.heap_index().is_some()
        && unsafe { vm(cx) }.heap.array_store_unlogged(base, value)
        && unsafe { (*cx).proofs.replace_admitted(i.b, base, proof_key(r.get(i.c)), value) }
}

script_handler! {
    /// `lane_set_index_proved` whose immediate store its proof declined: a heap value the
    /// barrier admits unlogged through the proof (`lane_proved_heap_store`), else
    /// `lane_proof_miss`. Apart, so the immediate store keeps its code.
    #[inline(never)]
    fn lane_set_index_proved_miss<>(cx, r, ip, i, view) {
        if !lane_proved_heap_store(cx, r, i) {
            sibling!(lane_proof_miss::<H>, r, ip, Carried::script_in(cx, view))
        }
        // A site that stores a heap value stores heap values: it tries that store first from now.
        requicken::<H>(ip, lane_set_index_proved_heap::<H>);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_index_proved` of a site whose stores are heap values (`arr[i] = o`), as
    /// `lane_set_index_proved_miss` found: the admitted heap store first, then the immediate
    /// one, else `lane_proof_miss`. One record, not the immediate store's miss and this.
    fn lane_set_index_proved_heap<>(cx, r, ip, i, view) {
        if !lane_proved_heap_store(cx, r, i) && lane_proved_store(cx, r, i).is_none() {
            sibling!(lane_proof_miss::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `element_write_row` of a base its loop does not redefine: the replacement through the
    /// run's proof of the array's storage (`lane_proved_store`), else `lane_proof_miss`.
    fn lane_set_index_proved<>(cx, r, ip, i, view) {
        if lane_proved_store(cx, r, i).is_none() {
            sibling!(lane_set_index_proved_miss::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_index_move` of a base its loop does not redefine: the replacement through
    /// the run's proof of the array's storage (`lane_proved_store`) and the copy, else
    /// `lane_proof_miss`.
    fn lane_set_index_move_proved<>(cx, r, ip, i, view) {
        let Some(value) = lane_proved_store(cx, r, i) else {
            sibling!(lane_proof_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: the pair is two records, the second never the view's last.
        let copy = unsafe { &*following(ip) };
        produce!(cx, r, following(ip), copy.a, value, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `element_write_row` past a record array, appending to a dense array at its length,
    /// filling one of its holes, a Number stored into a typed array
    /// (`Vm::typed_array_set_number`), or a plain symbol-, string- or integer-keyed write. A
    /// symbol write repeats the step its site recorded for the receiver's shape first
    /// (`Vm::site_symbol_set`).
    #[inline(never)]
    fn lane_set_index_slot<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !lane_set_index_slot_store(vm, ip, r.get(i.b), r.get(i.c), r.get(i.a)) {
            if vm.lane_stack.activations.is_empty() {
                return exit(ip);
            }
            resume!(cx, lane_set_index_beside_activations(cx, r, ip, i));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// `lane_set_index_slot` past the lane's stores within a frameless activation: the general
/// store made in place (`lane_in_place`), strict as its record or function is.
#[cold]
#[inline(never)]
fn lane_set_index_beside_activations<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, i: &LaneInstruction) -> Resumed {
    let vm = unsafe { vm(cx) };
    let Some(function) = vm.lane_stack.activations.last().map(|activation| activation.function) else {
        return Resumed::Exit(exit(ip));
    };
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // innermost activation's view.
    let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
    let body = code.function(function as usize);
    let instruction = body.widened(body.code[pc]);
    if !instruction.op().is_set_index() {
        return Resumed::Exit(exit(ip));
    }
    let strict = body.strict || instruction.boolean_flag().unwrap_or(false);
    let (object, key, value) = (r.get(i.b), r.get(i.c), r.get(i.a));
    if lane_in_place(cx, ip, |vm, code| vm.set_index_mode(code, object, key, value, strict)).is_none() {
        return Resumed::Exit(exit(ip));
    }
    // Guest code the store ran made the activations frames, whose registers these are.
    let r = unsafe { (*cx).registers };
    Resumed::At(r, following(ip), Carried::script(cx))
}

/// `lane_set_index_slot`'s store of `value` at `object[key]` for the record at `ip`; `false`
/// stores nothing. Out of line, as every store a lane handler makes through calls whose
/// stack temporaries escape: the handler's frame then holds none.
#[inline(never)]
fn lane_set_index_slot_store<H: Host>(vm: &mut Vm<H>, ip: Ip, object: Value, key: Value, value: Value) -> bool {
    if !vm.try_fill_record_hole(object, key, value)
        && !vm.site_symbol_set(ip.addr(), object, key, value)
        && !vm.try_replace_dense_element(object, key, value)
        && !vm.try_append_dense_element(object, key, value)
        && !vm.try_fill_dense_hole(object, key, value)
        && !vm.try_site_symbol_set(ip.addr(), object, key, value)
        && !vm.try_host_private_symbol_set(object, key, value)
        && !lane_typed_array_store(ip, vm, object, key, value)
        && !lane_string_key_store(ip, vm, object, key, value)
        && !key
            .as_int()
            .and_then(|index| usize::try_from(index).ok())
            .is_some_and(|index| vm.set_plain_index_property(object, index, value).is_some())
    {
        return false;
    }
    // Appending an element or adding a property can allocate.
    note_allocation(vm);
    true
}

/// A store of a number at an index of a typed array, which none of the array and symbol
/// paths before it serve: the site then tries it first (`lane_set_index_typed`).
fn lane_typed_array_store<H: Host>(ip: Ip, vm: &mut Vm<H>, object: Value, key: Value, value: Value) -> bool {
    let stored = vm
        .array_index_key(key)
        .is_some_and(|index| vm.typed_array_set_number(object, index as usize, value));
    if stored {
        requicken::<H>(ip, typed_kind_handler::<H>(vm.typed_array_kind_of(object), false));
    }
    stored
}

/// A plain string-keyed write (`Vm::try_plain_string_key_set`), which every array, symbol
/// and typed-array path before it declines: the site then tries it first
/// (`lane_set_index_string`).
fn lane_string_key_store<H: Host>(ip: Ip, vm: &mut Vm<H>, object: Value, key: Value, value: Value) -> bool {
    let stored = vm.try_plain_string_key_set(object, key, value);
    if stored {
        requicken::<H>(ip, lane_set_index_string::<H>);
    }
    stored
}

script_handler! {
    /// `lane_set_index_slot` at a site that made a plain string-keyed write: that write is
    /// the whole store, as the generic order reaches it once every array, symbol and typed
    /// path declines a string key; any other store takes the generic order.
    fn lane_set_index_string<>(cx, r, ip, i, view) {
        let (object, key, value) = (r.get(i.b), r.get(i.c), r.get(i.a));
        let vm = unsafe { vm(cx) };
        if !vm.try_plain_string_key_set(object, key, value) {
            sibling!(lane_set_index_slot::<H>, r, ip, view)
        }
        // Adding a property can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_index_slot` at a site that stored into a typed array: a number stored at an
    /// index of one is the whole store, as the generic order reaches it once every array and
    /// symbol path declines a typed array; any other store takes the generic order.
    fn lane_set_index_typed<>(cx, r, ip, i, view) {
        if !(unsafe { vm(cx) }).typed_cached_store::<{ super::typed_array_access::ANY_TYPED_KIND }>(r.get(i.b), r.get(i.c), r.get(i.a)) {
            sibling!(lane_set_index_typed_fill::<H, { super::typed_array_access::ANY_TYPED_KIND }>, r, ip, view)
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_index_typed` at a site that has stored into typed arrays of one kind only,
    /// `KIND` (as `lane_get_index_typed_kind`).
    fn lane_set_index_typed_kind<KIND: usize>(cx, r, ip, i, view) {
        if !(unsafe { vm(cx) }).typed_cached_store::<KIND>(r.get(i.b), r.get(i.c), r.get(i.a)) {
            sibling!(lane_set_index_typed_fill::<H, KIND>, r, ip, view)
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_index_typed_kind` at a site that has stored a double into its integer kind:
    /// any Number converts in place (`Vm::typed_cached_store_number`).
    fn lane_set_index_typed_number_kind<KIND: usize>(cx, r, ip, i, view) {
        if !(unsafe { vm(cx) }).typed_cached_store_number::<KIND>(r.get(i.b), r.get(i.c), r.get(i.a)) {
            sibling!(lane_set_index_typed_fill::<H, KIND>, r, ip, view)
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A typed store whose view has no current cached entry (as `lane_get_index_typed_fill`).
    #[inline(never)]
    fn lane_set_index_typed_fill<KIND: usize>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (base, key, value) = (r.get(i.b), r.get(i.c), r.get(i.a));
        // A double into an integer kind misses the hot store only: the entry is current, and a
        // kind variant's site moves to the variant that converts doubles in place.
        if vm.typed_cached_store_number::<KIND>(base, key, value) {
            if KIND != super::typed_array_access::ANY_TYPED_KIND {
                requicken::<H>(ip, lane_set_index_typed_number_kind::<H, KIND>);
            }
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        vm.fill_typed_view(base);
        if !vm.typed_set_quick::<KIND>(base, key, value) {
            if KIND == super::typed_array_access::ANY_TYPED_KIND {
                sibling!(lane_set_index_typed_full::<H>, r, ip, view)
            }
            sibling!(lane_set_index_typed_mixed::<H>, r, ip, view)
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A kind variant's miss (`lane_set_index_typed_kind`): the site becomes any-kind.
    #[inline(never)]
    fn lane_set_index_typed_mixed<>(cx, r, ip, i, view) {
        requicken::<H>(ip, lane_set_index_typed::<H>);
        sibling!(lane_set_index_typed::<H>, r, ip, view)
    }
}

script_handler! {
    /// `lane_set_index_typed` past its quick store (`Vm::typed_set_quick`): any Number stored
    /// at an index of a typed array (`Vm::typed_array_set_number`), or the generic order.
    #[inline(never)]
    fn lane_set_index_typed_full<>(cx, r, ip, i, view) {
        let (object, key, value) = (r.get(i.b), r.get(i.c), r.get(i.a));
        let vm = unsafe { vm(cx) };
        let stored = vm
            .array_index_key(key)
            .is_some_and(|index| vm.typed_array_set_number(object, index as usize, value));
        if !stored {
            sibling!(lane_set_index_slot::<H>, r, ip, view)
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// `lane_load_outer_capture`'s first read: up the links from the closure environment's
/// storage (`EnvironmentSlots::link`) to the capture `imm` names, in an activation; `None`
/// leaves the read to that handler's other ways.
#[inline(always)]
fn linked_outer_capture<H: Host>(cx: *mut LaneContext<H>, imm: u32) -> Option<Value> {
    if unsafe { (*cx).registers }.env().is_deleted() {
        return None;
    }
    let capture = capture_reads(unsafe { (*cx).registers }.capture());
    if capture.is_null() {
        return None;
    }
    let epoch = unsafe { vm(cx) }.heap.collection_epoch();
    let mut storage = capture;
    // SAFETY: as `lane_load_outer_capture`'s walk.
    for _ in 0..ImmediateLayout::capture_depth(imm) {
        storage = unsafe { crate::heap::EnvironmentSlots::linked_parent(storage, epoch) }?;
    }
    unsafe { crate::heap::EnvironmentSlots::read_storage(storage, ImmediateLayout::capture_slot(imm)) }
}

script_handler! {
    /// Two outer capture reads in a row (`specialize_captures`), as Earley-Boyer's nested
    /// closures read their free variables: both through the closure's storage links
    /// (`linked_outer_capture`) as one record. A first read the links miss runs the first
    /// record's own handler, a second the second record's.
    fn lane_load_outer_capture_pair<>(cx, r, ip, i, view) {
        let Some(value) = linked_outer_capture(cx, i.imm()) else {
            sibling!(lane_load_outer_capture::<H>, r, ip, view)
        };
        r.set(i.a, value);
        let second_ip = following(ip);
        // SAFETY: the pair is two records, the second never the view's last.
        let second = unsafe { &*second_ip };
        let Some(value) = linked_outer_capture(cx, second.imm()) else {
            next!(cx, r, second_ip, view)
        };
        r.set(second.a, value);
        next!(cx, r, following(second_ip), view)
    }
}

script_handler! {
    /// `lane_load_capture` of a capture past the running function's own scope
    /// (`specialize_captures`): the staged read through the walk the lane remembers (a frame's
    /// remembered walk, an activation's `LaneContext::outer`) or a new walk it then remembers;
    /// any other read takes `lane_load_capture_walk`.
    fn lane_load_outer_capture<>(cx, r, ip, i, view) {
        let imm = i.imm();
        // The links from the closure environment's storage up its chain (`EnvironmentSlots::link`),
        // one load and compare per level.
        if let Some(value) = linked_outer_capture(cx, imm) {
            r.set(i.a, value);
            next!(cx, r, following(ip), view)
        }
        sibling!(lane_load_outer_capture_remembered::<H>, r, ip, view)
    }
}

script_handler! {
    /// `lane_load_outer_capture` past its links: the staged read through the walk the lane
    /// remembers. Apart, so the linked read spills nothing for it.
    #[inline(never)]
    fn lane_load_outer_capture_remembered<>(cx, r, ip, i, view) {
        let imm = i.imm();
        let at = (ImmediateLayout::capture_depth(imm), ImmediateLayout::capture_slot(imm));
        if !lane_frame::staged_load_capture::<H>(cx, r, view, i.a, at, false) {
            #[cfg(feature = "profile-lane-exits")]
            super::lane_exits::capture(super::lane_exits::CaptureEvent::LaneMiss);
            sibling!(lane_load_capture_walk::<H>, r, ip, view)
        }
        #[cfg(feature = "profile-lane-exits")]
        super::lane_exits::capture(super::lane_exits::CaptureEvent::LaneHit);
        next!(cx, r, following(ip), view)
    }
}

/// A capture of a root environment's global var or global lexical
/// (`Vm::plain_projected_root_binding`), which a script's functions read for its top-level
/// `var`s, and in an eval script's context its `let`s and `const`s: the capture's environment
/// as the general path finds it, from the frame or from the activation's environment.
#[inline(never)]
fn lane_projected_capture<H: Host>(cx: *mut LaneContext<H>, depth: u16, slot: u16) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    let env = unsafe { (*cx).registers }.env();
    let env = if env.is_deleted() {
        vm.owner_capture_env(VarOwner::Frame(unsafe { (*cx).frame() }), depth)?
    } else {
        vm.environment_capture_env(env, false, depth)?
    };
    vm.plain_projected_root_binding(env, slot)
}

/// A frame run's innermost capture slots for `LaneContext::capture`, when the frame's
/// cache holds them dense: tagged `CAPTURE_STORES` when their environment admits every
/// store, whose barrier this takes once, as `Vm::target_capture` tags an activation's. The
/// first store of a frame run asks (`lane_store_capture`).
#[inline(never)]
fn lane_frame_capture<H: Host>(cx: *mut LaneContext<H>) -> Option<*const usize> {
    let vm = unsafe { vm(cx) };
    let frame = unsafe { (*cx).frame() };
    let Some((slots, None)) = vm.current_capture_slots(frame) else {
        return None;
    };
    // SAFETY: the frame's cache names live slots this collection; none runs in the lane.
    let dense = unsafe { &*slots }.dense_storage()?;
    // The cache's slots are those of the frame's depth-0 capture environment.
    let env = vm.owner_capture_env(VarOwner::Frame(frame), 0)?;
    // SAFETY: the context's program outlives the lane run.
    let (code, program) = unsafe { (&*(*cx).code, (*cx).program) };
    if vm.admits_every_direct_store(code, program, env) {
        vm.heap.remember_cell(env);
        return Some(dense.map_addr(|address| address | CAPTURE_STORES));
    }
    Some(dense)
}

/// Resolve an owned or shared lane capture without guest code, refreshing the dense cache.
/// OSR entry and the LoadCapture slow lane use the same binding and TDZ guards.
#[inline(never)]
fn lane_capture_value<H: Host>(cx: *mut LaneContext<H>, depth: u16, slot: u16) -> Option<Value> {
    lane_read_capture_value::<H, false>(cx, depth, slot).0
}

/// `lane_capture_value`, with `PLAIN` also a root projection's plain read
/// (`Vm::plain_capture`), for a `LoadCapture` record, which takes the value however held;
/// with the global var whose global object property answered it, and whether an
/// activation's walk ended at a root environment.
#[inline(always)]
fn lane_read_capture_value<H: Host, const PLAIN: bool>(
    cx: *mut LaneContext<H>,
    depth: u16,
    slot: u16,
) -> (Option<Value>, Option<super::environment::RootRead>, bool) {
    let vm = unsafe { vm(cx) };
    let env = unsafe { (*cx).registers }.env();
    
    if env.is_deleted() {
        let frame = unsafe { (*cx).frame() };
        let (value, source) = if PLAIN {
            vm.cached_plain_capture(frame, depth, slot)
        } else {
            (vm.cached_direct_capture(frame, depth, slot), None)
        };
        (value, source, depth == 0 && frame_capture_at_root(cx, frame))
    } else {
        // A frameless activation's function has no environment of its own.
        let Some((slots, root)) = vm.walked_capture_slots(env, false, depth) else {
            return (None, None, false);
        };
        // SAFETY: as `Vm::walked_capture_slots`; no collection runs in the lane.
        let slots = unsafe { &*slots };
        if depth == 0
            && root.is_none()
            && let Some(dense) = slots.dense_storage()
        {
            unsafe { (*cx).registers.set_capture(dense) };
        }
        let (value, source) = if PLAIN { vm.plain_capture(slots, root, slot) } else { (vm.owned_capture(slots, root, slot), None) };
        (value, source, root.is_some())
    }
}

script_handler! {
    /// `lane_load_capture` before the running function's slots are known: the walk from
    /// the frame's cache, or from the activation's environment, which keeps them.
    #[inline(never)]
    fn lane_load_capture_walk<>(cx, r, ip, i, view) {
        let imm = i.imm();
        let depth = ImmediateLayout::capture_depth(imm);
        let slot = ImmediateLayout::capture_slot(imm);
        let (value, source, root) = lane_read_capture_value::<H, true>(cx, depth, slot);
        // A global var's own data property on the global object becomes the record's hint
        // (`lane_load_root_var`); a retained global lexical binding's name and index in the
        // realm's bindings do (`lane_load_root_lexical`); a root slot that is the binding
        // itself, as a module's top-level declarations are, is read in place
        // (`lane_load_root_binding`).
        if value.is_some() {
            use super::environment::RootRead;
            let vm = unsafe { vm(cx) };
            if root && source.is_none() && lane_root_binding_slot(cx, depth, slot) {
                requicken::<H>(ip, lane_load_root_binding::<H>);
            }
            match source {
                Some(RootRead::GlobalVar(atom)) => {
                    if let Some(hint) = vm.own_data_field_hint::<false>(vm.realm.globals, atom) {
                        set_field_hint(ip, hint);
                        requicken::<H>(ip, lane_load_root_var::<H>);
                    }
                }
                Some(RootRead::GlobalLexical(atom, index)) => {
                    if let Ok(index) = u16::try_from(index)
                        && index != NO_CALL_LINK
                    {
                        set_field_hint(ip, super::FieldCache::own(atom, index));
                        requicken::<H>(ip, lane_load_root_lexical::<H>);
                    }
                }
                None => {}
            }
        }
        #[cfg(feature = "profile-lane-exits")]
        {
            let vm = unsafe { vm(cx) };
            let env = unsafe { (*cx).registers }.env();
            let code = unsafe { &*(*cx).code };
            let function = lane_running_function(cx);
            let body = code.function_get(function as usize);
            let shape = vm.current_capture_slots(unsafe { (*cx).frame() }).map(|(slots, root)| {
                (root.is_some(), unsafe { &*slots }.dense().is_some(), unsafe { &*slots }.len())
            });
            super::lane_exits::record_detail(format!(
                "capture walk in {} {} span={:?} depth={depth} frame_run={} (root, dense)={shape:?}",
                vm.programs.source_name(unsafe { (*cx).program }).unwrap_or_default(),
                body.and_then(|body| body.name).map(|atom| code.atoms[atom as usize].to_string()).unwrap_or_default(),
                body.and_then(|body| body.source_span).map(|span| span.start),
                env.is_deleted(),
            ));
        }
        if let Some(value) = value {
            r.set(i.a, value);
            next!(cx, r, following(ip), view)
        }
        // A capture of a root environment's global var or lexical: the staged row's root read.
        if !lane_frame::staged_load_capture::<H>(cx, r, view, i.a, (depth, slot), true) {
            return exit(ip);
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// A `LoadCapture` of a root environment's binding slot (`lane_root_binding_slot`), as a
    /// module function reads a top-level `const`: the slot of the root environment the parent
    /// links reach while the root owns it and it holds a value; any other read, one in its
    /// temporal dead zone or of a slot another environment shares, takes the walk.
    fn lane_load_root_binding<>(cx, r, ip, i, view) {
        let imm = i.imm();
        let slot = usize::from(ImmediateLayout::capture_slot(imm));
        let depth = ImmediateLayout::capture_depth(imm);
        let env = r.env();
        // The activation's own environment is the root one: one record read, which costs less
        // than the remembered walk's test, and nothing to remember.
        if depth == 0 && !env.is_deleted() {
            let vm = unsafe { vm(cx) };
            let Some(crate::heap::EnvironmentRecord { function, slots, .. }) = vm.heap.reachable_environment(env) else {
                sibling!(lane_load_capture_walk::<H>, r, ip, view)
            };
            if *function != super::ROOT_FUNCTION_ID {
                sibling!(lane_load_capture_walk::<H>, r, ip, view)
            }
            let Some(value) = slots.dense().and_then(|dense| dense.dense_plain(slot)) else {
                sibling!(lane_load_capture_walk::<H>, r, ip, view)
            };
            r.set(i.a, value);
            next!(cx, r, following(ip), view)
        }
        // SAFETY: the root record's slots, live while no collection runs (`lane_root_slots`).
        // A dense slot's ordinary value; a sparse storage, a shared slot or a binding in its
        // temporal dead zone takes the walk.
        let value = lane_root_slots(cx, depth)
            .and_then(|slots| unsafe { &*slots }.dense()?.dense_plain(slot));
        let Some(value) = value else {
            sibling!(lane_load_capture_walk::<H>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

/// The slots of the root environment `depth` layers out from the running activation, as
/// `lane_root_environment` walks to it, through the walk the lane remembers
/// (`LaneContext::root_walk`): an environment's chain is fixed and its record stays put while
/// no collection runs, which retires the walk (`retire_lane_binding`), so the walk holds while
/// the activation's environment word, or its frame's, is the one it started from.
#[inline(always)]
fn lane_root_slots<H: Host>(cx: *mut LaneContext<H>, depth: u16) -> Option<*const crate::heap::EnvironmentSlots> {
    let env = unsafe { (*cx).registers }.env();
    let key = if env.is_deleted() {
        let frame = unsafe { (*cx).frame() };
        unsafe { vm(cx) }.frames.get(frame).map_or(Value::DELETED, |frame| frame.env)
    } else {
        env
    };
    let walk = unsafe { (*cx).root_walk };
    if walk.env == key && walk.depth == depth && !walk.slots.is_null() {
        return Some(walk.slots);
    }
    lane_root_slots_walk(cx, depth, key)
}

/// `lane_root_slots` past its remembered walk: the walk, remembered when its start is an
/// environment word.
#[inline(never)]
fn lane_root_slots_walk<H: Host>(cx: *mut LaneContext<H>, depth: u16, key: Value) -> Option<*const crate::heap::EnvironmentSlots> {
    let root = lane_root_environment(cx, depth)?;
    let slots = lane_root_record_slots(cx, root)?;
    if !key.is_deleted() {
        unsafe { (*cx).root_walk = OuterWalk { env: key, depth, slots } };
    }
    Some(slots)
}

/// The slots of `env` where it is a root environment's record (`ROOT_FUNCTION_ID`).
#[inline(always)]
fn lane_root_record_slots<H: Host>(cx: *mut LaneContext<H>, env: Value) -> Option<*const crate::heap::EnvironmentSlots> {
    match unsafe { vm(cx) }.heap.reachable_environment(env)? {
        crate::heap::EnvironmentRecord { function, slots, .. } if *function == super::ROOT_FUNCTION_ID => Some(std::ptr::from_ref(slots)),
        _ => None,
    }
}

script_handler! {
    /// A `StoreCapture` of a root environment's binding slot (`lane_root_binding_slot`), as a
    /// module function's `count++` of a top-level `let`: the slot of the root environment the
    /// parent links reach while it holds an initialized value; any other store takes
    /// `lane_store_outer_capture`.
    fn lane_store_root_binding<>(cx, r, ip, i, view) {
        let imm = i.imm();
        let slot = usize::from(ImmediateLayout::capture_slot(imm));
        let value = r.get(i.a);
        let stored = lane_root_environment(cx, ImmediateLayout::capture_depth(imm)).is_some_and(|env| {
            let vm = unsafe { vm(cx) };
            match vm.heap.reachable_environment_mut(env) {
                Some(crate::heap::EnvironmentRecord { function, slots, .. }) if *function == super::ROOT_FUNCTION_ID => {
                    match slots.owned_mut(slot) {
                        Some(binding) if !binding.is_internal_marker() => {
                            *binding = value;
                            true
                        }
                        _ => false,
                    }
                }
                _ => false,
            }
        });
        if !stored {
            sibling!(lane_store_outer_capture::<H>, r, ip, view)
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// A `LoadCapture` of a script's retained top-level `let`, `const` or class, whose name and
    /// index in the active realm's global lexical bindings its record's hint holds
    /// (`lane_load_capture_walk`): the binding at that index while it is that name's and
    /// initialized, else the walk. Bindings are never removed from an active realm, so the
    /// name at the index is the one a lookup of it finds.
    fn lane_load_root_lexical<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let hint = i.field_hint();
        let value = vm
            .realm
            .global_lexical_bindings
            .get_index(usize::from(hint.slot))
            .filter(|(atom, value)| **atom == hint.receiver && !value.is_deleted())
            .map(|(_, value)| *value);
        let Some(value) = value else {
            sibling!(lane_load_capture_walk::<H>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// A `LoadCapture` of a script's top-level `var`, whose global object property its record's
    /// hint names (`lane_load_capture_walk`): the property's slot while the global object keeps
    /// the hinted shape and no direct eval's var scope intervenes, else the walk.
    fn lane_load_root_var<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let value = vm
            .direct_eval_var_program
            .is_none()
            .then(|| vm.record_field_entry_hit(i.field_hint(), vm.realm.globals))
            .flatten();
        let Some(value) = value else {
            sibling!(lane_load_capture_walk::<H>, r, ip, view)
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

/// The index of "number" in `bytecode::TYPEOF_NAMES`.
const NUMBER_NAME_INDEX: usize = 3;

/// The handler of a `Unary` record whose operator the view decides once
/// (`specialize_register_operands`): a `typeof` test (`lane_typeof_test`), a Number operator
/// (`lane_unary_number`) or logical not (`lane_logical_not`), so the record dispatches on no
/// operator at run time; `None` keeps the general `lane_unary`.
fn unary_operator_handler<H: Host>(operator: u32) -> Option<Handler> {
    use oxc_ast::ast::UnaryOperator as U;
    if let Some((index, negated)) = crate::bytecode::typeof_test(operator) {
        macro_rules! names {
            ($($index:literal),*) => {
                match (index, negated) {
                    $(($index, false) => lane_typeof_test::<H, $index, false> as Handler,
                      ($index, true) => lane_typeof_test::<H, $index, true> as Handler,)*
                    _ => return None,
                }
            };
        }
        return Some(names!(0, 1, 2, 3, 4, 5, 6, 7));
    }
    const NEGATION: u32 = U::UnaryNegation as u32;
    const PLUS: u32 = U::UnaryPlus as u32;
    match operator {
        NEGATION => Some(lane_unary_number::<H, NEGATION> as Handler),
        PLUS => Some(lane_unary_number::<H, PLUS> as Handler),
        super::coercion::LOGICAL_NOT => Some(lane_logical_not::<H> as Handler),
        _ => None,
    }
}

script_handler! {
    /// `Unary` of a `typeof` test of the name at `INDEX` (`typeof x === "number"`, negated for
    /// `!==`), chosen when the view was derived: an immediate's name decided here; a heap
    /// operand's name is the VM's (`Vm::typeof_test_value`).
    fn lane_typeof_test<INDEX: usize, NEGATED: bool>(cx, r, ip, i, view) {
        let value = r.get(i.b);
        if value.is_heap() {
            sibling!(lane_typeof_test_heap::<H, INDEX, NEGATED>, r, ip, Carried::script_in(cx, view))
        }
        // An immediate's name (`immediate_typeof_index`), which a test of "number" decides by
        // the Number test alone.
        let named = if INDEX == NUMBER_NAME_INDEX {
            value.as_number().is_some()
        } else {
            match super::coercion::immediate_typeof_index(value) {
                Some(name) => name == INDEX,
                None => sibling!(lane_typeof_test_heap::<H, INDEX, NEGATED>, r, ip, Carried::script_in(cx, view)),
            }
        };
        let holds = named != NEGATED;
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The `lane_typeof_test_jump` of the `typeof` test `operator`, `None` for another operator.
fn typeof_test_jump_handler<H: Host>(operator: u32) -> Option<Handler> {
    let (index, negated) = crate::bytecode::typeof_test(operator)?;
    macro_rules! names {
        ($($index:literal),*) => {
            match (index, negated) {
                $(($index, false) => lane_typeof_test_jump::<H, $index, false> as Handler,
                  ($index, true) => lane_typeof_test_jump::<H, $index, true> as Handler,)*
                _ => return None,
            }
        };
    }
    Some(names!(0, 1, 2, 3, 4, 5, 6, 7))
}

script_handler! {
    /// `lane_typeof_test` whose result a forward `JumpFalse` record tests next (`if (typeof x
    /// === "number")`): the test and the branch as one dispatch, the result register written
    /// as the test writes it. An operand whose name the test alone does not decide runs
    /// `lane_typeof_test_heap`, which continues at the jump record.
    fn lane_typeof_test_jump<INDEX: usize, NEGATED: bool>(cx, r, ip, i, view) {
        let value = r.get(i.b);
        if value.is_heap() {
            sibling!(lane_typeof_test_heap::<H, INDEX, NEGATED>, r, ip, Carried::script_in(cx, view))
        }
        let named = if INDEX == NUMBER_NAME_INDEX {
            value.as_number().is_some()
        } else {
            match super::coercion::immediate_typeof_index(value) {
                Some(name) => name == INDEX,
                None => sibling!(lane_typeof_test_heap::<H, INDEX, NEGATED>, r, ip, Carried::script_in(cx, view)),
            }
        };
        let holds = named != NEGATED;
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        let jump_ip = following(ip);
        if !holds {
            resume!(cx, lane_jump::<H>(r, jump_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(jump_ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_typeof_test` of a heap operand: its kind's name (`Vm::typeof_test_value`).
    #[inline(never)]
    fn lane_typeof_test_heap<INDEX: usize, NEGATED: bool>(cx, r, ip, i, view) {
        r.set(i.a, unsafe { vm(cx) }.typeof_test_value(r.get(i.b), INDEX, NEGATED));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Unary` of the Number operator `OP` (`-x`, `+x`), chosen when the view was derived: a
    /// Number operand's result made here (`number_unary_result`); any other operand takes the
    /// general `lane_unary`.
    fn lane_unary_number<OP: u32>(cx, r, ip, i, view) {
        // An integer stays one: `+x` is itself, and `-x` of any but 0 (whose negation is -0)
        // and the least int32 (whose negation is past int32).
        if let Some(integer) = r.int(i.b) {
            const NEGATION: u32 = oxc_ast::ast::UnaryOperator::UnaryNegation as u32;
            if OP != NEGATION {
                r.set(i.a, Value::integer(integer));
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            if integer != 0 && integer != i32::MIN {
                r.set(i.a, Value::integer(-integer));
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
        }
        let Some(number) = r.get(i.b).as_number() else {
            sibling!(lane_unary::<H>, r, ip, Carried::script_in(cx, view))
        };
        let Some(result) = super::operations::number_unary_result(OP, number) else {
            sibling!(lane_unary::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, Value::number(result));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Unary` logical not, chosen when the view was derived: a value that decides its own
    /// truthiness (`Value::truthiness`) here; a heap value whose cell decides it takes the
    /// general `lane_unary`.
    fn lane_logical_not<>(cx, r, ip, i, view) {
        let Some(truthy) = r.get(i.b).truthiness() else {
            sibling!(lane_unary::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, if truthy { Value::FALSE } else { Value::TRUE });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Unary` of `UNARY_TYPEOF_INDEX`, chosen when the view was derived
    /// (`specialize_register_operands`): the index of `typeof`'s name, which runs no guest code.
    fn lane_typeof_index<>(cx, r, ip, i, view) {
        if !staged_typeof_index(r, Carried::script_in(cx, view), i.a, i.b) {
            r.set(i.a, unsafe { vm(cx) }.typeof_index_value(r.get(i.b)));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The direct write of `value` to the running function's own capture `slot` through its dense
/// slots, where they admit every store (`CAPTURE_STORES`) and the slot holds an initialized
/// binding: whether it wrote.
#[inline(always)]
fn lane_store_own_capture<H: Host>(cx: *mut LaneContext<H>, slot: u16, value: Value) -> bool {
    capture_stores(unsafe { (*cx).registers }.capture())
        // SAFETY: the running function's dense capture slots, which admit this write
        // (`CAPTURE_STORES`); no collection runs in the lane.
        .and_then(|slots| unsafe { crate::heap::EnvironmentSlots::write_storage(slots, usize::from(slot), value) })
        .is_some()
}

script_handler! {
    /// `StoreCapture` past the running function's dense slots, or of a capture past its own
    /// scope: the lane's store (`lane_capture_store`), else the general path.
    #[inline(never)]
    fn lane_store_outer_capture<>(cx, r, ip, i, view) {
        let imm = i.imm();
        let (depth, slot) = (ImmediateLayout::capture_depth(imm), ImmediateLayout::capture_slot(imm));
        if !lane_frame::staged_store_capture::<H>(cx, r, view, i.a, (depth, slot)) {
            return exit(ip);
        }
        // A root environment's binding slot is stored in place from now on.
        if lane_root_binding_slot(cx, depth, slot) {
            requicken::<H>(ip, lane_store_root_binding::<H>);
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `lane_store_capture` followed by a `LoadCapture` of the same capture
    /// (`specialize_captures`), as `c = c + 1; return c;` compiles: a direct write leaves the
    /// slot holding the value, which is the read's value, so the record runs both. Any other
    /// store takes `lane_store_outer_capture`, and the read then runs its own record.
    fn lane_store_capture_load<>(cx, r, ip, i, view) {
        let value = r.get(i.a);
        if !lane_store_own_capture(cx, ImmediateLayout::capture_slot(i.imm()), value) {
            sibling!(lane_store_outer_capture::<H>, r, ip, view)
        }
        // SAFETY: the pair is two records, the second never the view's last.
        let load = unsafe { &*following(ip) };
        r.set(load.a, value);
        next!(cx, r, following(following(ip)), view)
    }
}

/// How the run of a fused capture update (`lane_update_capture_int32`) ends, which records it
/// covers after the store (`specialize_capture_updates`).
type UpdateForm = u8;
/// The store alone (`lane_store_capture`).
const UPDATE_STORES: UpdateForm = 0;
/// The store and its read of the capture (`lane_store_capture_load`).
const UPDATE_LOADS: UpdateForm = 1;
/// The records an `UPDATE_LOADS` run covers: the read, the operator, its truncation, the store
/// and the store's read.
const UPDATE_LOADS_RUN: usize = 5;

/// The int32 update a fused record `update` (`lane_update_capture_int32`) makes of its capture
/// in the dense slots `capture` (`LaneContext::capture`, `ScriptCallTarget::capture`): the old
/// value and the stored one; `None` where the slots do not admit the store directly
/// (`CAPTURE_STORES`) or the capture holds no integer, which stores nothing.
#[inline(always)]
fn capture_int32_update<const OP: u32>(capture: *const usize, update: &LaneInstruction) -> Option<(Value, Value)> {
    let slots = capture_stores(capture)?;
    // SAFETY: the operator record follows the read in the fused run (`specialize_capture_updates`).
    let right = unsafe { &*following(update) }.imm() as i32;
    // SAFETY: the dense capture slots of a running function or resolved target, which admit
    // this write (`CAPTURE_STORES`); an integer needs no barrier and no collection runs in the
    // lane.
    unsafe {
        crate::heap::EnvironmentSlots::update_storage(slots, usize::from(ImmediateLayout::capture_slot(update.imm())), |value| {
            let value = value.as_int()?;
            Some(Value::integer(if OP == super::operations::SUBTRACTION {
                value.wrapping_sub(right)
            } else {
                value.wrapping_add(right)
            }))
        })
    }
}

script_handler! {
    /// `lane_load_capture`, `lane_operator_int32` of its value and an integer constant, and the
    /// store of the truncated result to the same capture, ended as `FORM` says (`UpdateForm`),
    /// the `c = (c + 1) | 0` of compiled code (`specialize_capture_updates`), as one record:
    /// one proof of the slots and one bounds test serve the read and the write
    /// (`capture_int32_update`). Slots that do not admit the store directly, or a value other
    /// than an integer, run the read's own record, then the others.
    fn lane_update_capture_int32<OP: u32, FORM: u8>(cx, r, ip, i, view) {
        let Some((old, value)) = capture_int32_update::<OP>(unsafe { (*cx).registers }.capture(), i) else {
            sibling!(lane_row::<H, CAPTURE_READ, ACC_NONE, FLAG_UNREAD>, r, ip, view)
        };
        // SAFETY: the run is the read, the operator, its truncation and the store, then the
        // store's read past `UPDATE_STORES` (`specialize_capture_updates`).
        let truncation = unsafe { &*following(following(ip)) };
        let store = following(following(following(ip)));
        r.set(i.a, old);
        r.set(truncation.a, value);
        if FORM == UPDATE_STORES {
            next!(cx, r, following(store), view)
        }
        // SAFETY: as above.
        r.set(unsafe { &*following(store) }.a, value);
        next!(cx, r, following(following(store)), view)
    }
}

/// The running lane activation's dense capture slots, the view a lane body's reads take
/// (`EnvironmentSlots::native_storage_view`), and whether they admit every direct store
/// (`capture_stores`): a frame run finds them as its first store does (`lane_capture_store`).
///
/// # Safety
/// `context` is the running lane's context.
pub(super) unsafe fn lane_context_captures<H: Host>(context: usize) -> Option<((*const Value, usize), bool)> {
    let cx = context as *mut LaneContext<H>;
    unsafe {
        if capture_reads((*cx).registers.capture()).is_null() && (*cx).registers.env().is_deleted() {
            (*cx).registers.set_capture(lane_frame_capture(cx)?);
        }
        // SAFETY: the context's slots stay live while the lane runs, which collects nothing.
        let view = crate::heap::EnvironmentSlots::native_storage_view(capture_reads((*cx).registers.capture()))?;
        Some((view, capture_stores((*cx).registers.capture()).is_some()))
    }
}

/// The running lane activation's receiver (`lane_this`), which a loop region it runs reads as a
/// lane body does: a frameless activation's own, not the VM frame's beneath it; `DELETED` where
/// it has none.
///
/// # Safety
/// `context` is the running lane's context.
pub(super) unsafe fn lane_context_this<H: Host>(context: usize) -> Value {
    let cx = context as *mut LaneContext<H>;
    unsafe { lane_this(cx, (*cx).registers) }.unwrap_or(Value::DELETED)
}

script_handler! {
    /// `CreateRegExpLiteral` (`Vm::regexp_literal`), which allocates and runs no guest code.
    fn lane_regexp_literal<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::RegExp { site: i.imm() }) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `MakeClosure` in a frame's own lane run: the staged closure row (`lane_closure_value_of`).
    fn lane_make_closure<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::Closure { function: i.imm() }) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The closure a `MakeClosure` record makes as the general loop does, in a frame's own lane
/// run of a function with no binding sites outside a module's root: its environment is the
/// frame's, promoted once, and making it allocates and runs no guest code. Any other
/// closure takes the general path; a promotion made first is idempotent.
#[inline(never)]
fn lane_closure_value_of<H: Host>(cx: *mut LaneContext<H>, id: u32) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    if !vm.lane_stack.activations.is_empty() {
        return None;
    }
    // SAFETY: the context's program outlives the lane run.
    let (code, frame) = unsafe { (&*(*cx).code, (*cx).frame()) };
    let function = vm.frames[frame].function;
    if function == super::ROOT_FUNCTION_ID
        || !code.function_get(function as usize)?.binding_sites.is_empty()
    {
        return None;
    }
    let env = vm.promote_frame_environment(frame);
    // Promotion moves the frame's captured locals into the environment, so a capture
    // slot pointer found before it is not reused.
    unsafe { (*cx).registers.set_capture(std::ptr::null()) };
    let value = lane_closure(vm, code, id, env);
    note_allocation(vm);
    value
}

/// The closure of `function` over `env` that a lane `MakeClosure` makes: a call-only one
/// (`Function::prototype_unobservable`) as a `Value::known_closure`, with no function object,
/// while no `with` was ever entered (a `with` object could take the binding's store);
/// any other through `Vm::closure`.
#[inline(always)]
fn lane_closure<H: Host>(vm: &mut Vm<H>, code: &ResidualProgram, function: u32, env: Value) -> Option<Value> {
    if !vm.with_scope_entered
        && code.functions.get(function as usize).is_some_and(|slot| slot.header().prototype_unobservable)
        && let Some(known) = Value::known_closure(function, env)
    {
        return Some(known);
    }
    vm.closure(code, function, env).ok()
}

/// The object a `CreateRegExpLiteral` record makes in the lane: its site belongs to the
/// running program, the frame's or an activation's (`LaneContext::program`). A pattern that
/// fails to compile raises at its instruction through `Vm::lane_raised` in a frame's own
/// run; inside a lane activation, `None` leaves it to the general path, which raises the
/// same error from the site's cached record.
#[inline(never)]
fn lane_regexp_literal_value<H: Host>(cx: *mut LaneContext<H>, site: u32) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let (code, program) = unsafe { (&*(*cx).code, (*cx).program) };
    let result = vm.regexp_literal_of(code, program, site as usize);
    note_allocation(vm);
    match result {
        Ok(value) => Some(value),
        Err(error) => {
            if vm.lane_stack.activations.is_empty() {
                vm.lane_completion.raise(error);
            }
            None
        }
    }
}

script_handler! {
    /// `MakeObject2`: a two-property literal allocates and runs no guest code.
    fn lane_make_object2<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::ObjectPair { site: i.imm(), first: i.b, second: i.c }) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `MakeObjectLiteral`: an ordinary object of the literal site's shape holding the
    /// record's window of registers, as the general loop makes it.
    fn lane_make_object_literal<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::ObjectLiteral { site: i.imm(), window: lane_literal_window(i) }) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The window of property values a `MakeObjectLiteral` record reads.
#[inline(always)]
fn lane_literal_window(i: &LaneInstruction) -> crate::bytecode::RegisterWindow {
    crate::bytecode::RegisterWindow { base: i.b, count: i.c }
}

/// The object a staged object literal row makes: its site's shape over the window of property
/// values (`Vm::object_site_shape`).
#[inline(always)]
fn lane_object_literal_value<H: Host>(cx: *mut LaneContext<H>, r: Registers, site: u32,
    window: crate::bytecode::RegisterWindow) -> Value {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let shape = vm.object_site_shape(unsafe { &*(*cx).code }, site as usize);
    // SAFETY: `lane_fields_fit` admitted the window inside the register file, and no
    // other reference into it is live while the object is allocated.
    let properties = unsafe { std::slice::from_raw_parts(r.0.add(usize::from(window.base)), usize::from(window.count)) };
    let value = vm.heap.alloc_object_with_properties(vm.object_proto, shape, properties);
    note_allocation(vm);
    value
}

script_handler! {
    /// `MakeObject`: an empty ordinary object (`Vm::object`), as the general loop makes it.
    fn lane_make_object<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::Empty) {
            return exit(ip);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

lane_handler! {
    /// `MakeArray`: a fresh array of the record's length in holes (`Vm::hole_array`).
    fn lane_make_array<>(cx, r, ip, i, view) {
        if !staged_allocate(cx, r, i.a, Allocation::Array { length: i.imm() }) {
            return exit(ip);
        }
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    /// `MakeArray` whose literal's `DefineArrayElement` records follow it, one per index in
    /// order (`specialize_array_literals`): the array made with those elements at once, as
    /// their definitions into its holes would leave it, and the run goes on past them.
    fn lane_make_array_elements<>(cx, r, ip, i, view) {
        let length = i.imm() as usize;
        // SAFETY: `specialize_array_literals` matched the `length` records after this one.
        let elements = RegisterList::collect(length, |index| unsafe { (*ip.add(index + 1)).a })
            .expect("a fused literal fits the window");
        if !staged_allocate(cx, r, i.a, Allocation::ArrayOf { elements }) {
            return exit(ip);
        }
        // SAFETY: as above.
        next!(cx, r, unsafe { ip.add(length + 1) }, view)
    }
}

/// The array of the values in `elements` (`Vm::literal_array`), out of line as `lane_new_object`.
#[inline(never)]
fn lane_literal_array_value<H: Host>(vm: &mut Vm<H>, r: Registers, elements: RegisterList) -> Value {
    let registers = elements.registers();
    let value = vm.literal_array(registers.len(), |index| r.get(registers[index]));
    note_allocation(vm);
    value
}

/// `lane_make_object`'s object. Out of line: an allocation whose record space is full falls
/// back to a heap slot, which takes the new object by its stack address, a temporary the
/// handler then does not hold.
#[inline(never)]
fn lane_new_object<H: Host>(vm: &mut Vm<H>) -> Value {
    let value = vm.object();
    note_allocation(vm);
    value
}

/// `lane_make_array`'s array of `length` holes, out of line as `lane_new_object`.
#[inline(never)]
fn lane_new_hole_array<H: Host>(vm: &mut Vm<H>, length: usize) -> Value {
    let value = vm.hole_array(length);
    note_allocation(vm);
    value
}

/// The object of literal `site`'s shape holding registers `first` and `second` (`Vm::object_pair`).
#[inline(always)]
fn lane_object_pair<H: Host>(cx: *mut LaneContext<H>, r: Registers, site: u32, [first, second]: [u16; 2]) -> Value {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let value = vm.object_pair(unsafe { &*(*cx).code }, site as usize, r.get(first), r.get(second));
    note_allocation(vm);
    value
}

script_handler! {
    /// `SuperConstArrayObject2` whose two fused operations see primitives only: its parts
    /// as `Vm::execute_const_array_object2` runs them; any other operand takes the
    /// general path, which runs the whole record again.
    fn lane_const_array_object2<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { lane_literal_value(cx, r, i) }) else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// A `SuperConstArrayObject2` record's object: a copy of the constant array, the two
/// fused `Binary` results, and the literal holding them, with each part's result in its
/// register as the general path leaves it. `None` before any guest code could run: an
/// operation on an object, or one that throws.
///
/// Out of line: its general binary result returns through a stack slot, which would cost a
/// handler inlining it the tail call to the next record.
///
/// # Safety
/// `cx` is the running lane's context and `r` its registers.
#[inline(never)]
unsafe fn lane_literal_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let parts = &code.superinstructions.get(i.imm() as usize)?.wide;
    let [array, first, second, object] = [parts[0], parts[1], parts[2], parts[3]];
    let start = array.constant_index();
    let elements = vm.programs.const_array(
        unsafe { (*cx).program },
        start,
        usize::from(array.element_count()),
    )?;
    let array_value = vm.heap.alloc(Cell::Array {
        object: crate::heap::ArrayObject::new(Vm::<H>::empty_object(vm.array_proto), elements),
    });
    r.set(array.result_register(), array_value);
    for part in [first, second] {
        let left = lane_operand_value(cx, r, part.operand_b().0)?;
        let right = lane_operand_value(cx, r, part.operand_c().0)?;
        if vm.is_object_like(left) || vm.is_object_like(right) {
            return None;
        }
        let value = vm.binary(code, part.binary_operator(), left, right).ok()?;
        r.set(part.result_register(), value);
    }
    let value = vm.object_pair(
        code,
        object.object_site_index(),
        r.get(object.register_b()),
        r.get(object.register_c()),
    );
    note_allocation(vm);
    Some(value)
}

/// The object a non-nested field record's base names: a register, or `this` where the lane
/// knows it. `None` for a nested site, whose record names no single base.
///
/// # Safety
/// As for `lane_field_value`.
#[inline(always)]
unsafe fn lane_single_field_base<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    base: u16,
) -> Option<Value> {
    if crate::bytecode::FieldBase(base).local_index().is_some() {
        return None;
    }
    if base == crate::bytecode::FieldBase::NESTED {
        return None;
    }
    match crate::bytecode::FieldBase(base).register_index() {
        Some(register) => Some(r.get(register)),
        None => unsafe { lane_fixed_this(cx, r) },
    }
}

/// `this` where the lane holds it or the frame fixed it; `None` for a lexical `this`, which
/// the general lookup (`lane_this`) resolves with a call. Without that call, a handler's
/// fast path keeps its values in registers no callee preserves.
///
/// # Safety
/// `cx` is the running lane's context.
#[inline(always)]
unsafe fn lane_fixed_this<H: Host>(cx: *mut LaneContext<H>, r: Registers) -> Option<Value> {
    let this = r.this();
    if !this.is_deleted() {
        return Some(this);
    }
    let frame = (unsafe { vm(cx) }).frames.get(unsafe { (*cx).frame() })?;
    frame.fixed_this.then_some(frame.this)
}

/// `this` as the context holds it, for a record whose cached hit answers only an object:
/// `DELETED` where the frame's binding decides it (`LaneContext::this`), which no cache entry
/// answers, so the record declines to its general form, which resolves the binding
/// (`lane_fixed_this`, `lane_this`). One load, with no test of its own.
///
/// # Safety
/// `cx` is the running lane's context.
#[inline(always)]
unsafe fn lane_held_this<H: Host>(_cx: *mut LaneContext<H>, r: Registers) -> Value {
    r.this()
}

/// The base of a single-base record whose handler was chosen for it (`single_base_handler`):
/// `this` when `THIS`, else the register the field names.
///
/// # Safety
/// As for `lane_single_field_base`; the record's base is `this` exactly when `THIS`.
#[inline(always)]
unsafe fn lane_known_field_base<H: Host, const THIS: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    base: u16,
) -> Option<Value> {
    if THIS {
        debug_assert_eq!(base, crate::bytecode::FieldBase::THIS.0);
        // Every caller reads a cached object field of it, which declines `DELETED`.
        Some(unsafe { lane_held_this(cx, r) })
    } else {
        debug_assert!(base < crate::bytecode::FieldBase::NESTED);
        Some(r.get(base))
    }
}

/// The instantiation of a single-base read handler that a record of base `base` takes: the
/// one for `this` or the one for a register. A nested record, which names no single base,
/// takes `nested`.
fn single_base_handler(base: u16, this: Handler, register: Handler, nested: Handler) -> Handler {
    match base {
        base if base == crate::bytecode::FieldBase::THIS.0 => this,
        base if crate::bytecode::FieldBase(base).register_index().is_some() => register,
        // A nested record names no single base, and a local base (`FieldBase::local`) is no
        // register the single-base handlers could read.
        _ => nested,
    }
}

/// Whether a field record's base is one the single-base handlers read
/// (`lane_known_field_base`): `this` or a register, not a nested chain or a local slot.
fn is_single_field_base(base: u16) -> bool {
    base == crate::bytecode::FieldBase::THIS.0 || crate::bytecode::FieldBase(base).register_index().is_some()
}

use crate::staged::HINTED_FORM;

/// The value the bound own-field read of record `i` answers (the own-field read the math call fusions make, `own_formed_handler`), `None`
/// where its hint misses.
#[inline(always)]
fn own_bound_value<H: Host, const THIS: bool, const FORM: u32>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> Option<Value> {
    // No closure: an `and_then` over one stays a call where its caller is not a handler.
    let object = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })?;
    {
        let record = object.direct_object_index()?;
        // SAFETY: binding preceded handler installation; the rooted direct Value names
        // a live record of this range. Resumption binds an initially empty outer context.
        #[cfg(all(target_arch = "aarch64", target_pointer_width = "64"))]
        let (base, machine) = {
            const {
                assert!(std::mem::offset_of!(LaneContext<H>, vm)
                    == std::mem::offset_of!(LaneContext<H>, binding)
                        + std::mem::offset_of!(LaneBinding, object_base)
                        + std::mem::size_of::<*const Object>());
            }
            let base: *const Object;
            let machine: *const Vm<H>;
            // SAFETY: the asserted adjacent pointer fields belong to this live context.
            // Loading both together starts the independent heap lookup before the shape
            // branch, instead of delaying the VM load until after that branch.
            unsafe {
                std::arch::asm!(
                    "ldp {base}, {machine}, [{source}, #{offset}]",
                    base = out(reg) base,
                    machine = out(reg) machine,
                    source = in(reg) std::ptr::addr_of!((*cx).binding),
                    offset = const std::mem::offset_of!(LaneBinding, object_base),
                    options(pure, readonly, nostack, preserves_flags),
                );
            }
            (base, machine)
        };
        #[cfg(not(all(target_arch = "aarch64", target_pointer_width = "64")))]
        let (base, machine) = unsafe { ((*cx).binding.object_base, (*cx).vm.cast_const()) };
        let receiver = unsafe { &*base.add(record as usize) };
        unsafe { &*machine }.own_field_hint_hit::<FORM>(i.field_hint(), receiver)
    }
}

script_handler! {
    /// the own-field row (`own_formed_handler`) past its record's hint: the site's primary own entry, whose hit
    /// becomes the hint; any other read goes through `lane_get_field_miss`.
    #[inline(never)]
    fn lane_get_field_own_refresh<THIS: bool, BOUND: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let Some((object, value)) = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })
            .and_then(|object| own_entry_hit(vm, code, object, i.c).map(|value| (object, value)))
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        if !BOUND {
            // SAFETY: a successful direct-object lookup proves the range is reserved.
            unsafe { (*cx).binding.object_base = vm.heap.object_record_base().unwrap_unchecked() };
        }
        // The hit proved the entry an own one of the receiver's shape.
        let hint = vm.form_hint(vm.field_cache_entry(i.c), object);
        set_field_hint(ip, hint);
        requicken::<H>(ip, own_formed_handler::<H, THIS>(Some(hint.receiver)));
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The value the primary own entry of site `site` reads in `object`, in whatever storage form
/// the object keeps it: the site row (`primary_own_field_hit`) reads arena runs and packed
/// values; an object whose values a collection narrowed (`NARROW_FORM`) is read through the
/// entry formed to its word (`form_hint`), so its record settles on the narrow handler instead
/// of missing on every read.
#[inline(always)]
fn own_entry_hit<H: Host>(vm: &mut Vm<H>, code: &ResidualProgram, object: Value, site: u16) -> Option<Value> {
    if let Some(value) = vm.primary_own_field_hit(code, object, site) {
        return Some(value);
    }
    let entry = vm.field_cache_entry(site);
    let receiver = vm.heap.record_object_value(object)?;
    if entry.holder != super::NO_FIELD_HOLDER || receiver.exact_shape() != entry.receiver {
        return None;
    }
    vm.own_field_hint_hit::<HINTED_FORM>(vm.form_hint(entry, object), receiver)
}

/// The opcode of the catalog's field leaf read (`Traits::FIELD_LEAF`), whose generated row
/// (`lane_row`) an own-field read's record runs once its hint is bound (`own_formed_handler`).
const FIELD_LEAF_READ: u16 = {
    let mut index = 0;
    loop {
        match Op::from_index(index) {
            Some(op) if op.traits().has(crate::bytecode::Traits::FIELD_LEAF) => break index as u16,
            Some(_) => index += 1,
            None => panic!("the catalog names a field leaf read"),
        }
    }
};

/// The opcode of the catalog's keyed read: the element row whose record defines a result
/// register (`Decoder::Element`), whose generated row (`lane_row`) a register-keyed read runs.
const ELEMENT_READ: u16 = {
    let mut index = 0;
    loop {
        match Op::from_index(index) {
            Some(op) if matches!(op.staged(), Some(crate::bytecode::Decoder::Element))
                && matches!(op.field_layout(InstructionField::A), FieldLayout::ResultRegister) => break index as u16,
            Some(_) => index += 1,
            None => panic!("the catalog names a keyed read"),
        }
    }
};

/// The opcode of the catalog's keyed write: the element row whose record's `a` is the stored
/// value's register (`Decoder::Element` without a result register).
const ELEMENT_WRITE: u16 = {
    let mut index = 0;
    loop {
        match Op::from_index(index) {
            Some(op) if matches!(op.staged(), Some(crate::bytecode::Decoder::Element))
                && !matches!(op.field_layout(InstructionField::A), FieldLayout::ResultRegister) => break index as u16,
            Some(_) => index += 1,
            None => panic!("the catalog names a keyed write"),
        }
    }
};

/// The generated keyed write (`lane_row` of `ELEMENT_WRITE`): a present dense element replaced in
/// place, any other write `lane_set_index_slot`.
/// The write's boolean immediate (its strictness) is no operand of the in-place row, whose misses
/// read it from the record: the row is installed at its cleared flag, so the passes that
/// recognise the record's handler (`specialize_proved_arrays`) find it before a first run
/// would requicken it.
const fn element_write_row<H: Host>() -> Handler { lane_row::<H, ELEMENT_WRITE, ACC_NONE, FLAG_CLEAR> }

/// The generated keyed read (`lane_row` of `ELEMENT_READ`) of a register base and key.
const fn element_read_row<H: Host>() -> Handler { lane_row::<H, ELEMENT_READ, ACC_NONE, FLAG_UNREAD> }

/// The opcode of the catalog's named field store of `receiver`, strict or not (`Op::field_store`),
/// whose generated row (`lane_row`) a store record runs: its hint as a layout store.
const fn field_store_opcode(receiver: StoreReceiver, strict: bool) -> u16 {
    let mut index = 0;
    loop {
        match Op::from_index(index) {
            Some(op) => match op.field_store() {
                Some(FieldStore { receiver: found, strict: s })
                    if s == strict && matches!((found, receiver), (StoreReceiver::This, StoreReceiver::This)
                        | (StoreReceiver::Register, StoreReceiver::Register)) => break index as u16,
                _ => index += 1,
            },
            None => panic!("the catalog names every field store"),
        }
    }
}
const FIELD_STORE: u16 = field_store_opcode(StoreReceiver::Register, false);
const FIELD_STORE_STRICT: u16 = field_store_opcode(StoreReceiver::Register, true);
const THIS_FIELD_STORE: u16 = field_store_opcode(StoreReceiver::This, false);
const THIS_FIELD_STORE_STRICT: u16 = field_store_opcode(StoreReceiver::This, true);

/// The generated own-field store (`lane_row` of the store opcode) of a store record whose
/// receiver and strictness `store` names.
const fn field_store_row<H: Host>(store: FieldStore) -> Handler {
    match (store.receiver, store.strict) {
        (StoreReceiver::Register, false) => lane_row::<H, FIELD_STORE, ACC_NONE, FLAG_UNREAD>,
        (StoreReceiver::Register, true) => lane_row::<H, FIELD_STORE_STRICT, ACC_NONE, FLAG_UNREAD>,
        (StoreReceiver::This, false) => lane_row::<H, THIS_FIELD_STORE, ACC_NONE, FLAG_UNREAD>,
        (StoreReceiver::This, true) => lane_row::<H, THIS_FIELD_STORE_STRICT, ACC_NONE, FLAG_UNREAD>,
    }
}

/// The storage forms an own-field read's hint fixes, by index: the generated row's site fact
/// (`own_site`) names one, so the row folds the layout it reads (`concrete_hinted_own_field_hit`).
/// `HINTED_FORM` reads the hint layout's own bits.
const OWN_FORMS: [u32; 9] = {
    use crate::staged::TAGGED_SLOTS;
    use crate::value_vec::{EXTRAS_FORM, INLINE_FORM, NARROW_FORM};
    [HINTED_FORM, 0, EXTRAS_FORM, INLINE_FORM, EXTRAS_FORM | INLINE_FORM, NARROW_FORM,
        TAGGED_SLOTS, EXTRAS_FORM | TAGGED_SLOTS, EXTRAS_FORM | INLINE_FORM | TAGGED_SLOTS]
};

/// The site fact (`lane_row`'s `FLAG`) of an own-field read of `this` (else of a register) whose
/// hint fixes form `OWN_FORMS[form]`. Zero is no site: the row reads it as unread.
const fn own_site(this: bool, form: usize) -> u8 { 1 + (form as u8) * 2 + this as u8 }

/// The site facts of a generated read through a prototype hint (`IcOp::Held`), of `this` and of
/// a register: past every own-field site.
pub(super) const HELD_SITE_THIS: u8 = own_site(true, OWN_FORMS.len());
pub(super) const HELD_SITE_REGISTER: u8 = own_site(false, OWN_FORMS.len());

/// The site facts of the held read of a receiver other than a direct object (an array, function
/// or ordinary builtin, as `a.push` or `f.call`), which a held site's miss takes: its object part
/// is resolved out of line (`RecordPlan::other`).
/// One instantiation for both bases: the base is a runtime test (`runtime_base`), as these rows are cold.
pub(super) const HELD_OTHER_THIS: u8 = own_site(false, OWN_FORMS.len() + 1);
pub(super) const HELD_OTHER_REGISTER: u8 = HELD_OTHER_THIS;

/// The site fact of a string register's read through a `String.prototype` hint
/// (`IcOp::HeldString`), as `s.charCodeAt`.
pub(super) const STRING_SITE: u8 = own_site(false, OWN_FORMS.len() + 2);

/// Whether site `site` is a read through a prototype hint.
pub(super) const fn held_site(site: u8) -> bool {
    site == HELD_SITE_THIS || site == HELD_SITE_REGISTER || held_other_site(site)
}

/// The site fact of a held read at a site whose receivers live outside the object records, as
/// `a.push` or `f.call` (`FieldSiteTier::Holder` of a cell): the held-other read from the first,
/// whose miss takes the site's holder entry (`lane_get_field_holder_cell_refresh`).
pub(super) const HELD_CELL_REGISTER: u8 = own_site(false, OWN_FORMS.len() + 3);

/// The site facts of a read through the record's inherited hint, a method beyond the immediate
/// prototype (`FieldSiteTier::Inherited`): of a direct object, then of any receiver's object
/// part, each of `this` and of a register.
pub(super) const INHERITED_THIS: u8 = own_site(true, OWN_FORMS.len() + 4);
pub(super) const INHERITED_REGISTER: u8 = own_site(false, OWN_FORMS.len() + 4);
pub(super) const INHERITED_OTHER_THIS: u8 = own_site(false, OWN_FORMS.len() + 5);
pub(super) const INHERITED_OTHER_REGISTER: u8 = INHERITED_OTHER_THIS;

/// Whether site `site` reads `this` or a register as its record says at run time, not as a
/// site fact: a cold row kept to one instantiation for both bases.
pub(super) const fn runtime_base(site: u8) -> bool { site == HELD_OTHER_THIS || site == INHERITED_OTHER_THIS }

/// The site fact of an own read of a receiver outside the object records, as a function's static
/// field (`Strength.REQUIRED`): the record's hint is the receiver's layout id and slot
/// (`Vm::cell_own_hint`), guarded by one compare of the function's record (`IcOp::GuardLayout`);
/// one instantiation per base: the register one (`A.x`) is the common read, and a fixed base
/// saves the base test (5 Ir per read).
pub(super) const CELL_OWN_THIS: u8 = own_site(true, OWN_FORMS.len() + 6);
pub(super) const CELL_OWN_REGISTER: u8 = own_site(false, OWN_FORMS.len() + 6);
pub(super) const fn cell_own_site(site: u8) -> bool { site == CELL_OWN_THIS || site == CELL_OWN_REGISTER }

/// Whether site `site` reads through the record's inherited hint; of any receiver (`other`).
pub(super) const fn inherited_site(site: u8) -> bool {
    site == INHERITED_THIS || site == INHERITED_REGISTER || inherited_other_site(site)
}
pub(super) const fn inherited_other_site(site: u8) -> bool { site == INHERITED_OTHER_THIS || site == INHERITED_OTHER_REGISTER }

/// Whether held site `site` reads any receiver's object part, not a direct object's alone.
pub(super) const fn held_other_site(site: u8) -> bool {
    site == HELD_OTHER_THIS || site == HELD_OTHER_REGISTER || site == HELD_CELL_REGISTER
}

/// Whether own-field or held site `site` reads `this`.
pub(super) const fn own_site_this(site: u8) -> bool { site.wrapping_sub(1) & 1 == 1 }

/// The storage form own-field site `site` fixes (`OWN_FORMS`); `HINTED_FORM` for none.
pub(super) const fn own_site_form(site: u8) -> u32 {
    let index = (site.wrapping_sub(1) / 2) as usize;
    if index < OWN_FORMS.len() { OWN_FORMS[index] } else { HINTED_FORM }
}

/// Whether the word own-field site `site` reads is a slot word to decode (`decode_staged_word`):
/// every form but a fixed tagged one and packed or narrow values, which hold no raw double.
pub(super) const fn own_site_decodes(site: u8) -> bool {
    if held_site(site) || site == STRING_SITE || inherited_site(site) { return false; }
    let form = own_site_form(site);
    form == HINTED_FORM || (form & crate::staged::TAGGED_SLOTS == 0 && form != crate::value_vec::INLINE_FORM
        && form != crate::value_vec::NARROW_FORM)
}

/// Every generated own-field read: `$each!(site)` for each site, `this` and register alike.
macro_rules! own_sites {
    ($each:ident) => {
        [$each!(own_site(true, 0)), $each!(own_site(false, 0)), $each!(own_site(true, 1)), $each!(own_site(false, 1)),
            $each!(own_site(true, 2)), $each!(own_site(false, 2)), $each!(own_site(true, 3)), $each!(own_site(false, 3)),
            $each!(own_site(true, 4)), $each!(own_site(false, 4)), $each!(own_site(true, 5)), $each!(own_site(false, 5)),
            $each!(own_site(true, 6)), $each!(own_site(false, 6)), $each!(own_site(true, 7)), $each!(own_site(false, 7)),
            $each!(own_site(true, 8)), $each!(own_site(false, 8))]
    };
}

/// The generated own-field read (`lane_row` at an `own_site`) for the base `THIS` names and the
/// storage form the layout id `hint`'s form bits name: an arena run, extras or packed inline values,
/// whose layout it then reads untested; `None` for the form of no particular hint.
fn own_formed_handler<H: Host, const THIS: bool>(hint: Option<u32>) -> Handler {
    use crate::value_vec::{EXTRAS_FORM, INLINE_FORM, NARROW_FORM};
    // A narrow run's hint names neither inline values nor extras: those tests fold away and
    // the read takes the run's halves. Packed and narrow slots never hold a raw double; the
    // other forms skip the decode where float slots are off for the process.
    let tagged = !crate::vm::switches::float_slots();
    // The hint is a layout id; its form bits are its entry's (`layouts::auxiliary`).
    let form = match hint.map(crate::heap::layouts::auxiliary) {
        None => 0,
        Some(hint) if hint & NARROW_FORM != 0 => 5,
        Some(hint) => match (hint & (INLINE_FORM | EXTRAS_FORM), tagged) {
            (0, true) => 6,
            (0, false) => 1,
            (EXTRAS_FORM, true) => 7,
            (EXTRAS_FORM, false) => 2,
            (INLINE_FORM, _) => 3,
            (_, true) => 8,
            (_, false) => 4,
        },
    };
    macro_rules! row { ($site:expr) => { lane_row::<H, FIELD_LEAF_READ, ACC_NONE, { $site }> as Handler } }
    own_sites!(row)[form * 2 + usize::from(!THIS)]
}

/// Makes the own field entry `entry` the hint of the field read/store record at `ip`
/// (`LaneInstruction::field_hint`). A held loop header's `call_link` names its site
/// (`lane_header_site`), and such a record keeps no hint: an empty hint's link is
/// `NO_CALL_LINK`, a held one's shape a recorded one.
#[inline(always)]
fn set_field_hint(ip: Ip, entry: super::FieldCache) {
    set_record_hint(ip, entry.receiver, entry.slot);
}

/// Makes inherited entry `index` the hint of the `GetField` record at `ip`
/// (`Vm::hinted_inherited_field_hit`), where `call_link` can name it.
#[inline(always)]
fn set_inherited_hint(ip: Ip, index: u32) {
    if let Ok(index) = u16::try_from(index)
        && index != NO_CALL_LINK
    {
        set_record_hint(ip, INHERITED_HINT, index);
    }
}

/// Makes the prototype's answer `hold` keeps (`Vm::hold_holder_hint`, `Vm::hold_string_hint`)
/// the hint of the `GetField` record at `ip`, in place of the one it holds, which `hold` takes.
/// Out of line, so the reads that keep their hint keep their registers.
#[cold]
#[inline(never)]
fn set_prototype_hint(ip: Ip, hold: impl FnOnce(Option<u16>) -> Option<u16>) {
    if holds_loop_site(ip) {
        return;
    }
    // SAFETY: `ip` is a `GetField` record of a live view.
    let i = unsafe { &*ip };
    let owned = (unsafe { i.operand.field.shape } == HOLDER_HINT).then(|| i.call_link.get());
    if let Some(index) = hold(owned) {
        set_record_hint(ip, HOLDER_HINT, index);
    }
}

/// Writes a field record's hint, `shape` and `link`, unless it is a held loop header
/// (`holds_loop_site`).
#[inline(always)]
fn set_record_hint(ip: Ip, shape: u32, link: u16) {
    if !holds_loop_site(ip) {
        // SAFETY: as `requicken`; `ip` is a field read/store record of a live view.
        unsafe {
            (*ip.cast_mut()).operand.field.shape = shape;
            (*ip).call_link.set(link);
        }
    }
}

/// Whether the field record at `ip` is a held loop header's, whose `call_link` names its
/// site (`lane_header_site`), so it keeps no hint: an empty hint's link is `NO_CALL_LINK`,
/// and a held one's shape a recorded one, `INHERITED_HINT` or `HOLDER_HINT`.
#[inline(always)]
fn holds_loop_site(ip: Ip) -> bool {
    // SAFETY: `ip` is a field read/store record of a live view.
    let i = unsafe { &*ip };
    (unsafe { i.operand.field.shape }) == super::NO_FIELD_RECEIVER && i.call_link.get() != NO_CALL_LINK
}

/// The polymorphic read of `object` by the `GetField` record at `ip` (`lane_get_field_polymorphic`,
/// `RETURNING_FIELD_POLYMORPHIC`): its hint, the last own entry that answered it, first, then
/// the site's inline entries, whose own hit becomes the hint; with whether a prototype's entry
/// answered, which no hint holds.
#[inline(always)]
fn polymorphic_read<H: Host>(vm: &mut Vm<H>, code: &ResidualProgram, ip: Ip, object: Value) -> Option<(Value, bool)> {
    use super::object::PolymorphicHit;
    // SAFETY: `ip` is a `GetField` record of a live view.
    let i = unsafe { &*ip };
    let (value, hit) = vm.hinted_polymorphic_field_hit(code, object, i.c, i.field_hint())?;
    if let PolymorphicHit::Own(entry) = hit {
        set_field_hint(ip, vm.form_hint(entry, object));
    }
    Some((value, matches!(hit, PolymorphicHit::Holder)))
}

script_handler! {
    /// `GetField` of a register or `this` at a site past one shape
    /// (`Vm::field_site_polymorphic`): its inline megamorphic entries, after its hint where
    /// `HINTED` (`polymorphic_read`), which a read a prototype's entry answers drops for good,
    /// since its site's receivers keep no own hint: the record then hints the last read a
    /// prototype answered instead, with its value (`Vm::holder_hint_hit`), as a parser whose
    /// shape grows while it runs reads its methods. Any other read takes
    /// `lane_get_field_hashed`, which a site whose entries moved to the hash runs from then on.
    fn lane_get_field_polymorphic<THIS: bool, HINTED: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let value = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) }).and_then(|object| {
            if !HINTED {
                if let Some(value) = vm.holder_hint_hit(i.call_link.get(), i.imm(), object) {
                    return Some(value);
                }
                let (value, hit) = vm.hinted_polymorphic_field_hit(code, object, i.c, super::EMPTY_CACHE)?;
                // A live hint another receiver of this site answers stays: rewriting it at
                // every receiver switch re-marked and re-watched the prototype each time
                // (V8-v7 Richards: 0.71M rewrites, 5% of its run).
                // SAFETY: `ip` is this live `GetField` record.
                let kept = unsafe { (*ip).operand.field.shape == HOLDER_HINT && vm.holder_hint_live((*ip).call_link.get()) };
                if matches!(hit, super::object::PolymorphicHit::Holder) && !kept {
                    set_prototype_hint(ip, |owned| {
                        if owned.is_some_and(|index| vm.holder_hint_live(index)) {
                            return None;
                        }
                        vm.hold_holder_hint(owned, i.imm(), object, value, NO_CALL_LINK)
                    });
                }
                return Some(value);
            }
            let (value, holder) = polymorphic_read(vm, code, ip, object)?;
            if holder {
                requicken::<H>(ip, lane_get_field_polymorphic::<H, THIS, false>);
            }
            Some(value)
        });
        let Some(value) = value else {
            if vm.field_site_hashed(i.c) {
                requicken::<H>(ip, lane_get_field_hashed::<H, THIS>);
            }
            sibling!(lane_get_field_hashed::<H, THIS>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_field_polymorphic` past its inline entries: the site's hashed entries, own or
    /// of the immediate prototype (`Vm::polymorphic_field_hit`), as an AST walk reads `type`
    /// of a node of any of dozens of shapes. Out of line, so the inline probe keeps no hash
    /// temporaries across its dispatch; any other read takes `lane_get_field`.
    #[inline(never)]
    fn lane_get_field_hashed<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let Some(value) = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })
            .and_then(|object| (unsafe { vm(cx) }).polymorphic_field_hit(code, object, i.c))
        else {
            sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_field_holder` past its hint: the site's primary holder entry
    /// (`Vm::primary_record_holder_field_hit`), whose answer becomes the hint. Any other read
    /// takes `lane_get_field_holder_any`.
    #[inline(never)]
    fn lane_get_field_holder_refresh<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let Some((object, value)) = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })
            .and_then(|object| vm.primary_record_holder_field_hit(code, object, i.c).map(|value| (object, value)))
        else {
            sibling!(lane_get_field_holder_any::<H, THIS>, r, ip, Carried::script_in(cx, view))
        };
        set_prototype_hint(ip, |owned| vm.hold_holder_hint(owned, i.imm(), object, value, NO_CALL_LINK));
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_field_holder` past a record prototype (`Vm::primary_holder_field_hit`), out
    /// of line so the record read makes no call: any other read takes `lane_get_field_miss`.
    #[inline(never)]
    fn lane_get_field_holder_any<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let Some(value) = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })
            .and_then(|object| (unsafe { vm(cx) }).primary_holder_field_hit(code, object, i.c))
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `GetField` of a string primitive, which `String.prototype` answers through the
    /// site's cache (`Vm::string_prototype_field_hit`), a method read as `s.substring`, or
    /// its chain's data walk for an absent name, at a site `Vm::string_field_site_cacheable`
    /// admits. A miss moves the record on as `lane_get_field_miss` decides.
    fn lane_get_field_string<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        // The site checks (`Vm::string_field_site_cacheable`) ran when the handler was
        // installed, so a hit reads the site's `String.prototype` entry directly; any other
        // read is `Vm::cached_string_field_hit`'s, whose miss records the site's entry.
        let Some(value) = (unsafe { lane_single_field_base(cx, r, i.b) })
            .filter(|object| vm.heap.is_string(*object))
            .and_then(|object| {
                vm.string_prototype_field_hit(i.c)
                    .or_else(|| vm.cached_string_field_hit(unsafe { &*(*cx).code }, object, i.imm(), i.c))
            })
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `GetField` of a number primitive, which `Number.prototype` answers through the site's
    /// cache (`Vm::number_prototype_field_hit`), a method read as `n.toString`, at a site
    /// `Vm::number_field_site_cacheable` admits. A miss moves the record on as
    /// `lane_get_field_miss` decides, whose general read records the site's entry.
    fn lane_get_field_number<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let Some(value) = (unsafe { lane_single_field_base(cx, r, i.b) })
            .filter(|object| object.as_number().is_some())
            .and_then(|_| vm.number_prototype_field_hit(i.c))
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// The generated string read (`lane_row` at `STRING_SITE`) past its hint: the site's `String.prototype` entry
    /// (`Vm::string_prototype_field_hit`), whose answer becomes the hint. Any other read
    /// takes `lane_get_field_string`.
    #[inline(never)]
    fn lane_get_field_string_refresh<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let base = r.get(i.b);
        let Some(value) = vm.heap.is_string(base).then(|| vm.string_prototype_field_hit(i.c)).flatten() else {
            sibling!(lane_get_field_string::<H>, r, ip, Carried::script_in(cx, view))
        };
        set_prototype_hint(ip, |owned| vm.hold_string_hint(owned, i.imm(), value, NO_CALL_LINK));
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_field_holder` for a receiver in a heap cell rather than the object records
    /// (`Vm::cell_holder_field_hit`): a method read from a function, as `f.apply`. A miss
    /// moves the record on as `lane_get_field_miss` decides.
    fn lane_get_field_holder_cell<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let Some(value) = (unsafe { lane_single_field_base(cx, r, i.b) })
            .and_then(|object| (unsafe { vm(cx) }).cell_holder_field_hit(code, object, i.c))
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// The generated held read at `HELD_CELL_REGISTER` past its hint: the site's holder entry
    /// (`Vm::cell_holder_field_hit`), whose answer becomes the hint. A miss takes
    /// `lane_get_field_holder_cell`, which moves the record on.
    #[inline(never)]
    fn lane_get_field_holder_cell_refresh<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let base = r.get(i.b);
        let Some(value) = vm.cell_holder_field_hit(code, base, i.c) else {
            sibling!(lane_get_field_holder_cell::<H>, r, ip, Carried::script_in(cx, view))
        };
        set_prototype_hint(ip, |owned| vm.hold_holder_hint(owned, i.imm(), base, value, NO_CALL_LINK));
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// The generated inherited read (`INHERITED_OTHER_*`) past its hint: the site's entries and their chain walk,
    /// which proves one again (`Vm::inherited_field_entry_hit`); the entry that answered
    /// becomes the hint. Any other read takes `lane_get_field_miss`.
    #[inline(never)]
    fn lane_get_field_inherited_walk<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let Some((value, entry)) = (unsafe { lane_known_field_base::<H, THIS>(cx, r, i.b) })
            .and_then(|object| (unsafe { vm(cx) }).inherited_field_entry_hit(code, object, i.c))
        else {
            sibling!(lane_get_field_miss::<H>, r, ip, Carried::script_in(cx, view))
        };
        set_inherited_hint(ip, entry);
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A `GetField`'s first run: a read of `name` or `length` can enter prototype lookup
    /// mode (`Vm::reads_function_info`), which only `lane_get_field`'s general probe
    /// prepares, so such a site keeps it; any other takes the own-field row (`own_formed_handler`).
    #[inline(never)]
    fn lane_get_field_first<>(cx, r, ip, i, view) {
        if crate::bytecode::FieldBase(i.b).local_index().is_some() {
            if let Some(handler) = local_field_handler(cx, i) {
                requicken::<H>(ip, handler);
            }
            sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
        }
        let vm = unsafe { vm(cx) };
        if vm.is_private_name(i.imm()) && i.b != crate::bytecode::FieldBase::NESTED {
            requicken::<H>(ip, lane_get_private_field::<H>);
            sibling!(lane_get_private_field::<H>, r, ip, Carried::script_in(cx, view))
        }
        // `name` reads take the own-field handlers: an own hit needs the receiver's exact shape
        // to hold `name` as a data slot the general read recorded, which a function's unprepared
        // `name` never is (it is no slot until `prepare_function_info_prototypes` makes it one),
        // and every miss still reaches the general read, which prepares it. `user.name` then
        // costs an own read, not the general probe.
        if vm.reads_function_info(i.imm()) && i.imm() == vm.length_atom {
            // A register's `length` is most often an array's, which no function information
            // can answer.
            let handler: Handler = if i.imm() == vm.length_atom
                && crate::bytecode::FieldBase(i.b).register_index().is_some()
                && i.b != crate::bytecode::FieldBase::NESTED
            {
                lane_get_length::<H>
            } else {
                lane_get_field::<H>
            };
            requicken::<H>(ip, handler);
            sibling!(handler, r, ip, Carried::script_in(cx, view))
        }
        // The generated own read of the form of no particular hint, which binds the lane's
        // object records on its first miss where they are not yet bound.
        let (this, register) = (own_formed_handler::<H, true>(None), own_formed_handler::<H, false>(None));
        let own = single_base_handler(i.b, this, register, lane_get_field_miss::<H>);
        requicken::<H>(ip, own);
        sibling!(own, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `GetField` of `length` from a register (`lane_get_field_first`): an array's own
    /// `length` (`Vm::array_length_field`, which `lane_get_field` answers for an array
    /// after a probe that cannot hit) inline; any other receiver takes `lane_get_field`.
    fn lane_get_length<>(cx, r, ip, i, view) {
        let Some(length) = (unsafe { vm(cx) }).array_length_value(r.get(i.b)) else {
            sibling!(lane_get_length_other::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, length);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_length` of a receiver other than an array, which the general cached read
    /// does not answer: a string primitive's length (`Vm::string_length`) here, and any
    /// other receiver past `lane_get_length_arguments`.
    #[inline(never)]
    fn lane_get_length_other<>(cx, r, ip, i, view) {
        let Some(length) = (unsafe { vm(cx) }).string_length(r.get(i.b)) else {
            sibling!(lane_get_length_arguments::<H>, r, ip, Carried::script_in(cx, view))
        };
        // A site that reads a string's length mostly reads strings, as a scan over one does.
        requicken::<H>(ip, lane_get_length_string::<H>);
        r.set(i.a, Value::length(length));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_length` at a site that read a string's length (`lane_get_length_other`):
    /// a string's length here; any other receiver, an array's included, takes
    /// `lane_get_length` out of line, which keeps this one's registers to the string.
    fn lane_get_length_string<>(cx, r, ip, i, view) {
        // The staged row (`staged::string_length`), as compiled code reads it; a rope, a slice
        // or a small string takes the units' count.
        let Some(length) = (unsafe { vm(cx) }).string_length_value(r.get(i.b)) else {
            sibling!(lane_get_length::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, length);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_length_other` of a receiver other than a string: an arguments object's own
    /// data `length` in its creation layout (`Vm::arguments_object_length`), or a user
    /// function's own data `length` (`Vm::plain_function_length`), as a middleware stack
    /// reads a handler's arity. Any other receiver takes `lane_get_field`.
    #[inline(never)]
    fn lane_get_length_arguments<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let receiver = r.get(i.b);
        let Some(length) = vm.arguments_object_length(receiver).or_else(|| vm.plain_function_length(receiver)) else {
            // A site that reads a typed array's length mostly reads typed arrays, as a loop
            // over one does: it reads the intrinsic getter's geometry first from now on.
            if let Some(length) = vm.typed_array_geometry_read(receiver, vm.length_atom) {
                requicken::<H>(ip, lane_get_length_typed::<H>);
                r.set(i.a, length);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            // A plain object's own `length` data slot (`{ length: n }`), as the site's primary
            // entry recorded it; a miss takes the general read, which prepares function info.
            // SAFETY: the context's program outlives the lane run.
            let code = unsafe { &*(*cx).code };
            if let Some(value) = vm.primary_own_field_hit(code, receiver, i.c) {
                // A site that read a plain object's own `length` mostly reads such objects: it
                // takes the own-field handler, whose misses still reach the general read.
                if crate::bytecode::FieldBase(i.b).register_index().is_some() && i.b != crate::bytecode::FieldBase::NESTED {
                    let own = own_formed_handler::<H, false>(None);
                    requicken::<H>(ip, own);
                }
                r.set(i.a, value);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, length);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_length` at a site that read a typed array's length
    /// (`lane_get_length_arguments`): the intrinsic `length` getter's value for a typed array
    /// that shadows it nowhere (`Vm::typed_array_geometry_read`); any other receiver takes
    /// `lane_get_length`.
    fn lane_get_length_typed<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let Some(length) = vm.typed_array_geometry_read_inline(r.get(i.b), vm.length_atom) else {
            sibling!(lane_get_length::<H>, r, ip, view)
        };
        r.set(i.a, length);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A miss of a single-entry read (the own-field row, `lane_get_field_holder`, `_inherited`): a nested record moves to
    /// `lane_get_field`, one whose site went polymorphic to `lane_get_field_polymorphic`,
    /// one whose primary entry names a prototype holder to `lane_get_field_holder`, one with
    /// an inherited entry to the generated inherited read; the read itself takes
    /// `lane_get_field`.
    #[inline(never)]
    fn lane_get_field_miss<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let base = unsafe { lane_single_field_base(cx, r, i.b) };
        let string_base = base.is_some_and(|base| {
            (unsafe { vm(cx) }).heap.is_string(base)
        });
        if let Some(handler) = local_field_handler(cx, i) {
            requicken::<H>(ip, handler);
            sibling!(lane_get_field::<H>, r, ip, Carried::script(cx))
        }
        let geometry_base = base.is_some_and(|base| lane_geometry_read(unsafe { vm(cx) }, base, i.imm()).is_some());
        let handler: Option<Handler> = match lane_field_site_tier(unsafe { vm(cx) }, code, i) {
            // A site that read a typed array's, DataView's, Map's or Set's geometry mostly
            // reads such views, as a loop over one does: it reads the intrinsic getter first.
            _ if geometry_base => Some(lane_get_field_geometry::<H>),
            // A string primitive reads `String.prototype`, whatever tier its entries name,
            // where the site admits that read; any other read of one is the general read's.
            _ if string_base && (unsafe { vm(cx) }).string_field_site_cacheable(code, i.imm()) => {
                Some(single_base_handler(
                    i.b,
                    lane_get_field_string::<H>,
                    lane_row::<H, FIELD_LEAF_READ, ACC_NONE, STRING_SITE>,
                    lane_get_field_string::<H>,
                ))
            }
            _ if string_base => Some(lane_get_field::<H>),
            _ if base.is_some_and(|base| base.as_number().is_some())
                && (unsafe { vm(cx) }).number_field_site_cacheable(code, i.imm()) =>
            {
                Some(lane_get_field_number::<H>)
            }
            FieldSiteTier::Nested => Some(lane_get_field_nested::<H>),
            FieldSiteTier::General => Some(lane_get_field::<H>),
            FieldSiteTier::Getter => Some(lane_get_field_getter_hinted::<H>),
            FieldSiteTier::Polymorphic => Some(single_base_handler(
                i.b,
                lane_get_field_polymorphic::<H, true, true>,
                lane_get_field_polymorphic::<H, false, true>,
                lane_get_field::<H>,
            )),
            // A receiver outside the object records, such as a function, takes the cell lookup.
            FieldSiteTier::Holder
                if base.is_some_and(|object| object.direct_object_index().is_none()) =>
            {
                Some(if crate::bytecode::FieldBase(i.b).register_index().is_some() {
                    lane_row::<H, FIELD_LEAF_READ, ACC_NONE, HELD_CELL_REGISTER>
                } else {
                    lane_get_field_holder_cell::<H>
                })
            }
            FieldSiteTier::Holder => Some(single_base_handler(
                i.b,
                lane_row::<H, FIELD_LEAF_READ, ACC_NONE, HELD_SITE_THIS>,
                lane_row::<H, FIELD_LEAF_READ, ACC_NONE, HELD_SITE_REGISTER>,
                lane_get_field::<H>,
            )),
            FieldSiteTier::Inherited => Some(single_base_handler(
                i.b,
                lane_row::<H, FIELD_LEAF_READ, ACC_NONE, INHERITED_THIS>,
                lane_row::<H, FIELD_LEAF_READ, ACC_NONE, INHERITED_REGISTER>,
                lane_get_field::<H>,
            )),
            // A receiver outside the object records, such as a function, reads its own slot by the
            // receiver's layout id, which the record's hint holds (a loop header's keeps none).
            FieldSiteTier::Own
                if base.is_some_and(|object| object.direct_object_index().is_none()) =>
            {
                match base.and_then(|object| (unsafe { vm(cx) }).cell_own_hint(object, i.c)) {
                    Some((layout, slot)) if !holds_loop_site(ip) => {
                        set_record_hint(ip, layout, slot);
                        Some(single_base_handler(i.b, lane_row::<H, FIELD_LEAF_READ, ACC_NONE, CELL_OWN_THIS>,
                            lane_row::<H, FIELD_LEAF_READ, ACC_NONE, CELL_OWN_REGISTER>, lane_get_field::<H>))
                    }
                    _ => Some(lane_get_field::<H>),
                }
            }
            FieldSiteTier::Own => None,
        };
        if let Some(handler) = handler {
            requicken::<H>(ip, handler);
        }
        sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
    }
}

/// The intrinsic geometry getter's value of `atom` on `base` (`Vm::typed_array_geometry_read`)
/// for a geometry name (`AtomClass::VIRTUAL_FIELD`); `None` for any other read.
#[inline(always)]
fn lane_geometry_read<H: Host>(vm: &mut Vm<H>, base: Value, atom: crate::bytecode::Atom) -> Option<Value> {
    if !vm.atom_class(atom).contains(super::object::AtomClass::VIRTUAL_FIELD) {
        return None;
    }
    vm.typed_array_geometry_read(base, atom)
}

script_handler! {
    /// `lane_get_field` at a site that read a view's geometry (`lane_get_field_miss`): the
    /// intrinsic getter's value where the receiver shadows it nowhere
    /// (`Vm::typed_array_geometry_read`); any other read takes `lane_get_field`.
    fn lane_get_field_geometry<>(cx, r, ip, i, view) {
        let base = unsafe { lane_single_field_base(cx, r, i.b) };
        let Some(value) = base.and_then(|base| lane_geometry_read(unsafe { vm(cx) }, base, i.imm())) else {
            sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The cache tier a single-read `GetField` site's entries call for, to which a miss of its
/// single-entry handler moves the record (`lane_get_field_miss`, `lane_returning_field_miss`).
#[derive(Clone, Copy, PartialEq, Eq)]
enum FieldSiteTier {
    /// A nested read whose steps hit primary own entries, or an array's own `length`
    /// (`lane_nested_own_value`).
    Nested,
    /// A nested read with another step, which only the general cached read makes.
    General,
    /// A read that met an accessor the site cached (`Vm::field_site_getter`).
    Getter,
    /// Past one shape (`Vm::field_site_polymorphic`).
    Polymorphic,
    /// A primary entry naming a prototype holder (`Vm::field_site_holder`).
    Holder,
    /// An entry beyond the immediate prototype (`Vm::field_site_inherited`).
    Inherited,
    /// The primary own entry, which the record already reads.
    Own,
}

fn lane_field_site_tier<H: Host>(
    vm: &Vm<H>,
    code: &ResidualProgram,
    i: &LaneInstruction,
) -> FieldSiteTier {
    if i.b == crate::bytecode::FieldBase::NESTED {
        // A step that reads `name` or `length` may prepare prototype lookup
        // (`Vm::reads_function_info`); only an array's own `length` needs no preparing.
        let nested_own = code.field_sites.get(i.imm() as usize).is_some_and(|site| {
            !vm.reads_function_info(site.first.0)
                && site.second.is_none_or(|(atom, _)| {
                    atom == vm.length_atom || !vm.reads_function_info(atom)
                })
        });
        if nested_own { FieldSiteTier::Nested } else { FieldSiteTier::General }
    } else if vm.field_site_getter(i.c) {
        FieldSiteTier::Getter
    } else if vm.field_site_polymorphic(i.c) {
        FieldSiteTier::Polymorphic
    } else if vm.field_site_holder(i.c) {
        FieldSiteTier::Holder
    } else if vm.field_site_inherited(i.c) {
        FieldSiteTier::Inherited
    } else {
        FieldSiteTier::Own
    }
}

/// A nested `GetField`'s value (`this.a.b`, `r.a.b`) where the first step hits the record's
/// own-field hint (`LaneInstruction::field_hint`), which holds the receiver shape that step
/// last met however many its site has seen (a parser's `this` gains a field mid-parse), and
/// the second its site's primary own entry or an array's or a string's own `length`
/// (`nested_last_step`); `None` leaves the read to `lane_nested_polymorphic_value`, which
/// refreshes the hint. The site reads neither `name` nor another `length`
/// (`lane_field_site_tier`).
///
/// # Safety
/// `cx` is the running lane's context and `i` a nested record of it.
#[inline(always)]
unsafe fn lane_nested_own_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    // SAFETY: the context's program outlives the lane run; a nested record names its site.
    let code = unsafe { &*(*cx).code };
    let site = unsafe { code.field_sites.get_unchecked(i.imm() as usize) };
    let vm = unsafe { vm(cx) };
    let base = match site.base.register_index() {
        Some(register) => r.get(register),
        None => unsafe { lane_fixed_this(cx, r) }?,
    };
    let first = vm.record_field_entry_hit(i.field_hint(), base)?;
    nested_last_step(vm, code, site, first)
}

/// `lane_nested_own_value` past the record's hint: each step's site's entries, the primary own
/// one or the polymorphic ones, inline or hashed (`Vm::polymorphic_field_entry_hit`), as an
/// AST walk's `node.loc.start` reads nodes of many shapes, and a string's own `length`, as a
/// tokenizer's `this.input.length` reads (`lane_cached_field`); none runs guest code. The own
/// entry that answered the first step becomes the record's hint. Out of line, so the hinted
/// probe keeps its registers; `None` leaves the read to `lane_get_field`.
///
/// # Safety
/// As for `lane_nested_own_value`, with `ip` that record.
#[inline(never)]
unsafe fn lane_nested_polymorphic_value<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip) -> Option<Value> {
    // SAFETY: the context's program outlives the lane run; a nested record names its site.
    let code = unsafe { &*(*cx).code };
    let site = unsafe { code.field_sites.get_unchecked((*ip).imm() as usize) };
    let base = unsafe { lane_field_base(cx, r, site.base) }?;
    let vm = unsafe { vm(cx) };
    let (first, own) = match vm.primary_own_field_hit(code, base, site.first.1) {
        Some(value) => (value, Some(vm.field_cache_entry(site.first.1))),
        None => match vm.polymorphic_field_entry_hit(code, base, site.first.1)? {
            (value, super::object::PolymorphicHit::Own(entry)) => (value, Some(entry)),
            (value, _) => (value, None),
        },
    };
    if let Some(entry) = own {
        set_field_hint(ip, entry);
    }
    match site.second {
        None => Some(first),
        Some((atom, _)) if atom == vm.length_atom => own_length(vm, first),
        Some((_, cache)) => vm
            .primary_own_field_hit(code, first, cache)
            .or_else(|| vm.polymorphic_field_hit(code, first, cache)),
    }
}

/// A nested site's read of `base` where both steps hit primary own entries
/// (`lane_nested_own_value`), which runs no guest code.
#[inline(always)]
pub(super) fn nested_own_field_hit<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    site: &crate::bytecode::FieldSite,
    base: Value,
) -> Option<Value> {
    // Two ordinary field reads are one chain row, which proves the tables once
    // (`Vm::primary_own_chain_hit`); a single read or a `length` step is `nested_last_step`'s.
    let Some((_, second)) = site.second.filter(|(atom, _)| *atom != vm.length_atom) else {
        let first = vm.primary_own_field_hit(code, base, site.first.1)?;
        return nested_last_step(vm, code, site, first);
    };
    let value = vm.primary_own_chain_hit(code, base, (site.first.1, second));
    #[cfg(feature = "profile-field-primitives")]
    pair_census(vm, code, (site.first.1, base), value.is_some());
    value
}

/// The census of a nested pair read: its attempt, whether its first step hit (a miss of the chain
/// reads the first step alone to attribute it) and whether both did.
#[cfg(feature = "profile-field-primitives")]
fn pair_census<H: Host>(vm: &mut Vm<H>, code: &ResidualProgram, (first, base): (u16, Value), hit: bool) {
    use crate::profile::field_primitives::Path;
    vm.profile.field_primitives.hit(Path::NestedOwnPairAttempt);
    if hit || vm.primary_own_field_hit(code, base, first).is_some() {
        vm.profile.field_primitives.hit(Path::NestedOwnPairFirstHit);
    }
    if hit {
        vm.profile.field_primitives.hit(Path::NestedOwnPairHit);
    }
}

/// A nested site's last step from `first`, the first step's value: none, an array's or a
/// string's own `length`, or the second step's primary own entry.
#[inline(always)]
fn nested_last_step<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    site: &crate::bytecode::FieldSite,
    first: Value,
) -> Option<Value> {
    match site.second {
        None => Some(first),
        Some((atom, _)) if atom == vm.length_atom => own_length(vm, first),
        Some((_, cache)) => {
            let value = vm.primary_own_field_hit(code, first, cache);
            #[cfg(feature = "profile-field-primitives")]
            if value.is_some() { vm.profile.field_primitives.hit(crate::profile::field_primitives::Path::NestedOwnPairHit); }
            value
        }
    }
}

/// The own `length` of an array or a string, which no prototype shadows, as a nested
/// read's last step reads it (`nested_own_field_hit`, `lane_nested_polymorphic_value`).
#[inline(always)]
fn own_length<H: Host>(vm: &Vm<H>, object: Value) -> Option<Value> {
    // The staged row answers either by the value's tag; a form it leaves is read through the
    // string's units, or the array's record.
    vm.length_value(object).or_else(|| match vm.heap.string(object) {
        Some(text) => Some(Value::length(text.len())),
        None => vm.array_length_field(object, vm.length_atom),
    })
}

script_handler! {
    /// A nested `GetField` whose steps hit primary own entries (`lane_nested_own_value`);
    /// any other read takes `lane_get_field`.
    fn lane_get_field_nested<>(cx, r, ip, i, view) {
        let Some(value) = (unsafe { lane_nested_own_value(cx, r, i) })
            .or_else(|| unsafe { lane_nested_polymorphic_value(cx, r, ip) })
        else {
            sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A field read that hits its cache; any other read takes the general
    /// path, which repeats the side-effect-free lookup.
    #[inline(never)]
    fn lane_get_field<>(cx, r, ip, i, view) {
        // A method read whose receivers find it at different prototype depths (an override in
        // one class, the base's in another) stays here: the site's primary holder entry and its
        // proved inherited entry first, neither of which walks the chain.
        let quick = crate::bytecode::FieldBase(i.b).register_index().and_then(|register| {
            let vm = unsafe { vm(cx) };
            // SAFETY: the context's program outlives the lane run.
            let code = unsafe { &*(*cx).code };
            let object = r.get(register);
            vm.specialized_operations_enabled(code).then_some(())?;
            vm.primary_record_holder_field_hit(code, object, i.c).or_else(|| vm.proved_inherited_field_hit(code, object, i.c))
        });
        let Some(value) = quick.or_else(|| unsafe { lane_field_value(cx, r, i) }) else {
            if let Some(base) = lane_field_read_beside_activations(cx, r, i) {
                // A proxy's trap runs as an activation beside the others (`lane_read_get_trap`);
                // the in-place general read would call it across the native boundary.
                if unsafe { vm(cx) }.proxy_parts(base).is_some() {
                    match lane_getter_activation(cx, r, ip, i) {
                        Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                        // A native getter that raised is not called again: the general path raises it.
                        Err(next) if (unsafe { vm(cx) }).lane_completion.is_raised() => return next,
                        Err(_) => {}
                    }
                }
                sibling!(lane_get_field_beside_activations::<H>, unsafe { (*cx).registers }, ip, Carried::script_in(cx, view))
            }
            return match lane_getter_activation(cx, r, ip, i) {
                Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                Err(next) => next,
            };
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_get_field` at a site whose reads met a getter (`FieldSiteTier::Getter`): the
    /// getter activation first, whose cache check fails without effect, so a data read the
    /// cached probes answer stays `lane_get_field`'s. An activation without lane-stack room
    /// makes the activations frames first (`lane_script_call_frame`), so the read goes on with
    /// the running function's registers read again (the rollup npm scenario's
    /// `childNodeKeys[this.type]` was written to the emptied lane stack, not its frame).
    #[inline(never)]
    fn lane_get_field_getter<>(cx, r, ip, i, view) {
        if let Some(value) = lane_memoized_getter_read(cx, r, i) {
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        match lane_getter_activation(cx, r, ip, i) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            // A native getter that raised is not called again: the general path raises it.
            Err(next) if (unsafe { vm(cx) }).lane_completion.is_raised() => next,
            Err(_) => sibling!(lane_get_field::<H>, unsafe { (*cx).registers }, ip, Carried::script_in(cx, view)),
        }
    }
}

/// The value of a `GetField` record `i` of a register or `this` that writes its register,
/// where its site's accessor entry memoizes the getter's read (`Vm::memoized_getter_answer`).
#[inline(always)]
fn lane_memoized_getter_read<H: Host>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> Option<Value> {
    if i.a & crate::bytecode::RETURN_REGISTER != 0 || i.b == crate::bytecode::FieldBase::NESTED {
        return None;
    }
    let base = unsafe { lane_field_base(cx, r, crate::bytecode::FieldBase(i.b)) }?;
    let vm = unsafe { vm(cx) };
    vm.memoized_getter_answer(base, vm.field_cache_index(i.c))
}

/// The base of a `GetField` of a register or `this` that a frameless activation makes in
/// place (`lane_get_field_beside_activations`): a public name whose site caches no getter,
/// which `lane_getter_activation` would run as an activation. `None` for a frame's run, a
/// nested or local base, a private name or such a getter.
#[inline(never)]
fn lane_field_read_beside_activations<H: Host>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    if vm.lane_stack.activations.is_empty() || i.b == crate::bytecode::FieldBase::NESTED || vm.is_private_name(i.imm()) {
        return None;
    }
    let base = unsafe { lane_field_base(cx, r, crate::bytecode::FieldBase(i.b)) }?;
    vm.cached_field_getter(base, i.imm(), vm.field_cache_index(i.c)).is_none().then_some(base)
}

script_handler! {
    /// `lane_get_field` past its caches within a frameless activation
    /// (`lane_field_read_beside_activations`): the general read made in place
    /// (`lane_in_place`), so an uncached getter, a proxy or a throw makes the activations
    /// frames only when it runs, instead of leaving the lane, which makes them all frames.
    #[inline(never)]
    fn lane_get_field_beside_activations<>(cx, r, ip, i, view) {
        let Some(base) = lane_field_read_beside_activations(cx, r, i) else {
            return exit(ip);
        };
        let (atom, site) = (i.imm(), i.c);
        let Some(value) = lane_in_place(cx, ip, |vm, code| vm.get_field_cached(code, base, atom, site)) else {
            return exit(ip);
        };
        // Guest code the read ran made the activations frames, whose registers these are.
        let r = unsafe { (*cx).registers };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// A lane `GetField` whose read meets the accessor its site cached
/// (`Vm::cached_field_getter`): the getter runs as a frameless activation of the read's
/// record, as `lane_script_call` runs a call, with the base as receiver and no arguments,
/// and its completion is the read's value. `Err` carries the record to continue at: the
/// general path for any other read.
#[inline(never)]
fn lane_getter_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
) -> Result<(Registers, Ip), Ip> {
    if !unsafe { (*cx).script_calls } {
        #[cfg(feature = "profile-lane-exits")]
        super::lane_exits::record_detail("getter decline script_calls".into());
        return Err(exit(ip));
    }
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    // The object the getter's read is of and its site: a nested site's second field is read
    // of the value its first, cached read gives.
    let read = if i.b == crate::bytecode::FieldBase::NESTED {
        code.field_sites.get(i.imm() as usize).copied().and_then(|site| {
            let base = unsafe { lane_field_base(cx, r, site.base) }?;
            match site.second {
                Some((atom, cache)) => {
                    Some((lane_cached_field(cx, code, base, site.first.0, site.first.1)?, atom, cache))
                }
                None => Some((base, site.first.0, site.first.1)),
            }
        })
    } else {
        unsafe { lane_field_base(cx, r, crate::bytecode::FieldBase(i.b)) }.map(|base| (base, i.imm(), i.c))
    };
    let vm = unsafe { vm(cx) };
    #[cfg(feature = "profile-lane-exits")]
    if let Some((base, atom, cache)) = read
        && vm.cached_field_getter(base, atom, vm.field_cache_index(cache)).is_none()
    {
        super::lane_exits::record_detail(format!(
            "getter decline uncached {} recorded={}",
            &code.atoms[atom as usize],
            vm.field_site_getter(cache)
        ));
    } else if read.is_none() {
        super::lane_exits::record_detail("getter decline base".into());
    }
    let Some((base, getter)) = read.and_then(|(base, atom, cache)| {
        Some((base, vm.cached_field_getter(base, atom, vm.field_cache_index(cache))?))
    }) else {
        return proxy_traps::lane_read_get_trap(cx, r, ip, read.map(|(base, atom, _)| (base, atom)));
    };
    lane_read_getter(cx, r, ip, i, getter, base)
}

/// The activation of `getter` with receiver `base` and no arguments for the read record at
/// `ip`, whose completion is the read's value (`resolved`: its frameless target, which the read
/// resolved already): a frameless target of the running program, or
/// another program's plain activation (`Vm::cross_call_entry`), which runs in its program.
/// `Err` carries the record to continue at: the general path for any other getter.
fn lane_activate_getter<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    getter: Value,
    base: Value,
    resolved: Option<ScriptCallTarget>,
) -> Result<(Registers, Ip), Ip> {
    // The getter's activation is pushed above the reading function's, and resolving its
    // target may displace the cached target a running leaf names, so a leaf's read makes the
    // leaf an activation first. A target the read resolved (`resolved`) is a copy, which
    // that leaves as it was.
    lane_materialize_running_leaf(cx);
    let vm = unsafe { vm(cx) };
    if let Some(target) = resolved.or_else(|| lane_script_target(cx, getter)).filter(|target| !target.forwards()) {
        let Some(this) = lane_call_this(vm, &target, base) else {
            return Err(exit(ip));
        };
        return lane_activate_kept::<H, false>(cx, r, ip, &target, &[], this);
    }
    // A getter that makes closures, of this program or another, runs as the environment
    // activation its plain call makes (`lane_activate_environment`), with no arguments, as
    // Zod's `get error() { ... issues.map((iss) => ...) }` does.
    // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
    let environment = vm
        .script_call_entry(getter)
        .or_else(|| vm.cross_call_entry(getter))
        .map(|target| unsafe { *target })
        .filter(|target| target.entry == CallEntry::Environment && !lane_constructing(vm, getter));
    if let Some(target) = environment {
        let Some(this) = lane_call_this(vm, &target, base) else {
            return Err(exit(ip));
        };
        return lane_activate_environment(cx, r, ip, &target, &[], (this, false));
    }
    // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
    let Some(target) = vm
        .cross_call_entry(getter)
        .map(|target| unsafe { *target })
        .filter(|target| target.entry.activates() && !lane_constructing(vm, getter))
    else {
        #[cfg(feature = "profile-lane-exits")]
        super::lane_exits::record_detail(format!(
            "getter decline target cross={:?} constructing={}",
            vm.cross_call_entry(getter).map(|target| unsafe { (*target).entry } as u8),
            lane_constructing(vm, getter)
        ));
        return Err(exit(ip));
    };
    let Some(this) = lane_call_this(vm, &target, base) else {
        return Err(exit(ip));
    };
    lane_activate_kept::<H, true>(cx, r, ip, &target, &[], this)
}

/// The private-name site keys of a nested read's two steps, as offsets from its record's
/// address (`lane_private_field_slot_at`): a record spans more bytes than steps, so no other
/// record's key is one of them.
const NESTED_STEPS: [usize; 2] = [1, 2];

/// A `GetField` record's value where caches answer it (`lane_cached_field`): one read of a
/// register or `this`, or a nested site's chain of two. `None` leaves the read to the
/// general path.
///
/// Out of line: the generic reads (`lane_get_field`, `lane_get_field_sink`, a returning
/// `GetField`) run it on their slower paths, so one copy serves them all instead of each
/// carrying its own probe (DeltaBlue, PGO build: ~40 instruction-cache lines of warm code).
///
/// # Safety
/// `cx` is the running lane's context and `r` its registers.
#[inline(never)]
unsafe fn lane_field_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    // The record's address names its private-name sites (`lane_private_field_slot_at`).
    let record = std::ptr::from_ref(i).addr();
    if i.b == crate::bytecode::FieldBase::NESTED {
        let site = *code.field_sites.get(i.imm() as usize)?;
        let base = unsafe { lane_field_base(cx, r, site.base) }?;
        let value = lane_field_step(cx, record + NESTED_STEPS[0], code, base, site.first.0, site.first.1)?;
        return match site.second {
            Some((atom, cache)) => lane_field_step(cx, record + NESTED_STEPS[1], code, value, atom, cache),
            None => Some(value),
        };
    }
    let base = unsafe { lane_field_base(cx, r, crate::bytecode::FieldBase(i.b)) }?;
    lane_field_step(cx, record, code, base, i.imm(), i.c)
}

/// The object a field base names: a register, or `this` where the lane knows it.
///
/// # Safety
/// As for `lane_field_value`.
#[inline(always)]
unsafe fn lane_field_base<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    base: crate::bytecode::FieldBase,
) -> Option<Value> {
    if let Some(slot) = base.local_index() {
        return lane_plain_local_operand(cx, slot);
    }
    match base.register_index() {
        Some(register) => Some(r.get(register)),
        None => unsafe { lane_this(cx, r) },
    }
}

/// A field read the caches answer: the general loop's probe (`cached_field_hit`, own,
/// megamorphic and holder entries, or an array's `length`), then the data lookup its slower
/// paths make before any that runs guest code (`Vm::probed_field_miss_value`).
#[inline(always)]
fn lane_cached_field<H: Host>(
    cx: *mut LaneContext<H>,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
    site: u16,
) -> Option<Value> {
    lane_cached_field_at(cx, code, object, atom, site, 0)
}

/// `lane_cached_field` of a read whose private name, if any, has the private-name site
/// `private_site` (`lane_private_field_slot_at`); `0` for none, which reads it uncached.
#[inline(always)]
fn lane_cached_field_at<H: Host>(
    cx: *mut LaneContext<H>,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
    site: u16,
    private_site: usize,
) -> Option<Value> {
    let probe = {
        let vm = unsafe { vm(cx) };
        // A string's own `length`, which its chain never shadows, as a tokenizer's
        // `this.input.length` reads: no cache records a primitive's, and the probes below
        // all decline it (`Vm::cached_string_field_hit`).
        if atom == vm.length_atom {
            if let Some(length) = vm.string_length_value(object) {
                return Some(length);
            }
            // An array's own `length` (`Vm::own_array_length`), which no field cache records
            // either, as `lane_get_length` reads it: a returning or local-based `GetField`
            // (`return rest.length`) otherwise reaches it only past the getter and miss paths.
            if let Some(length) = vm.own_array_length(object) {
                return Some(Value::length(length));
            }
        }
        let class = vm.atom_class(atom);
        // A private field, which no field cache records, at its site.
        if private_site != 0 && class.contains(super::object::AtomClass::PRIVATE) {
            return lane_private_field_value(cx, private_site, code, object, atom);
        }
        // A typed array's geometry, which no field cache records (`AtomClass::VIRTUAL_FIELD`).
        if class.contains(super::object::AtomClass::VIRTUAL_FIELD)
            && let Some(value) = vm.typed_array_geometry_read(object, atom)
        {
            return Some(value);
        }
        vm.prepare_named_function_info_lookup(object, atom);
        vm.cached_field_hit(code, object, site)
    };
    match probe {
        super::object::FieldCacheProbe::Hit(value) => Some(value),
        // A proxy's handler answers its reads (`lane_getter_activation` runs the trap): no
        // getter entry or data lookup below holds one.
        super::object::FieldCacheProbe::Ineligible if unsafe { vm(cx) }.proxy_parts(object).is_some() => None,
        // An accessor's entry answers before the data lookups, which would walk the chain to
        // reach the same accessor and decline it.
        // A getter the lane cannot answer in place is the activation's to call
        // (`lane_getter_activation`); only a virtual field may still answer.
        probe => match unsafe { lane_getter_read(cx, object, atom, site) } {
            Some(Some(value)) => Some(value),
            Some(None) => unsafe { vm(cx) }.pure_virtual_field(object, atom),
            // SAFETY: the context outlives the lane run.
            None => lane_cached_field_miss(unsafe { vm(cx) }, code, object, atom, site, probe, unsafe { (*cx).registers }.env()),
        },
    }
}

/// `lane_cached_field` past its probe. Out of line so that no handler inlining the probe
/// keeps the lookups' stack locals, which would cost it the tail call to the next record.
#[inline(never)]
fn lane_cached_field_miss<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
    site: u16,
    probe: super::object::FieldCacheProbe,
    environment: Value,
) -> Option<Value> {
    // A private field reads from the object's private elements before any cache, as the
    // general loop's `GetField` does. Its home follows the running function and the
    // environment its frame would capture from: the lane's frame, or a frameless activation's
    // function and environment, whose frame would hold that environment as its closure's.
    if vm.is_private_name(atom) {
        return match vm.lane_stack.activations.last() {
            None => vm.private_field_value(code, object, atom),
            Some(activation) => {
                let function = activation.script().map(|_| activation.function)?;
                vm.memoized_private_field_value(code, environment, function, object, atom)
            }
        };
    }
    match probe {
        super::object::FieldCacheProbe::Hit(value) => Some(value),
        // The order `Vm::get_field_cached` takes: an array's `length` before the lookups.
        super::object::FieldCacheProbe::OrdinaryMiss => vm
            .array_length_field(object, atom)
            // The entries of a site past one shape, whose handler may be a nested site's or a
            // local base's, as `lane_get_field_hashed` reads them.
            .or_else(|| vm.polymorphic_field_hit(code, object, site))
            .or_else(|| vm.cell_polymorphic_holder_hit(object, site))
            .or_else(|| vm.probed_field_miss_value(object, atom, site)),
        super::object::FieldCacheProbe::Ineligible => vm
            .array_length_field(object, atom)
            .or_else(|| vm.cached_string_field_hit(code, object, atom, site))
            .or_else(|| vm.cached_primitive_field_hit(object, atom)),
    }
    // A collection's `size` or a buffer view's field, which no cache records
    // (`AtomClass::VIRTUAL_FIELD`).
    .or_else(|| vm.pure_virtual_field(object, atom))
}

script_handler! {
    /// A sinking `GetField`'s first run: a site that reads `name` or `length`
    /// (`Vm::reads_function_info`) keeps `lane_get_field_sink`, whose reads prepare them;
    /// any other takes `lane_get_field_sink_own`.
    #[inline(never)]
    fn lane_get_field_sink_first<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let own = i.b == crate::bytecode::FieldBase::NESTED
            && code.field_sites.get(i.imm() as usize).is_some_and(|site| {
                !vm.reads_function_info(site.first.0)
                    && site.second.is_none_or(|(atom, _)| !vm.reads_function_info(atom))
            });
        if own {
            requicken::<H>(ip, lane_get_field_sink_own::<H>);
            sibling!(lane_get_field_sink_own::<H>, r, ip, Carried::script_in(cx, view))
        }
        requicken::<H>(ip, lane_get_field_sink::<H>);
        sibling!(lane_get_field_sink::<H>, r, ip, Carried::script_in(cx, view))
    }
}

/// `lane_get_field_sink_own`'s first step past the record's hint: the site's primary own
/// entry, whose hit becomes the hint. Out of line, so the hinted probe keeps its registers.
///
/// # Safety
/// `cx` is the running lane's context and `ip` a nested sink record of it.
#[inline(never)]
unsafe fn lane_sink_first_refresh<H: Host>(cx: *mut LaneContext<H>, ip: Ip, base: Value) -> Option<Value> {
    // SAFETY: the context's program outlives the lane run; a nested record names its site.
    let code = unsafe { &*(*cx).code };
    let site = unsafe { code.field_sites.get_unchecked((*ip).imm() as usize) };
    let vm = unsafe { vm(cx) };
    let value = vm.primary_own_field_hit(code, base, site.first.1)?;
    set_field_hint(ip, vm.field_cache_entry(site.first.1));
    Some(value)
}

script_handler! {
    /// `lane_get_field_sink` where every step hits its site's primary own entry: the
    /// nested read (`Vm::primary_own_field_hit`), then the store to `this`
    /// (`Vm::primary_own_field_store_hit`) where the write barrier logs nothing. Any other
    /// run takes `lane_get_field_sink`, which repeats the side-effect-free reads.
    fn lane_get_field_sink_own<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        // SAFETY: `lane_get_field_sink_first` installs this handler only on a nested site.
        let site = unsafe { code.field_sites.get_unchecked(i.imm() as usize) };
        let base = match site.base.register_index() {
            Some(register) => r.get(register),
            None => unsafe { lane_held_this(cx, r) },
        };
        // Each step declines on its own branch: the `Option` chain kept a materialized
        // `Some` flag tested between the reads (V8-v7 Richards, 0.85M runs).
        macro_rules! or_general {
            ($step:expr) => {
                match $step {
                    Some(value) => value,
                    None => sibling!(lane_get_field_sink::<H>, r, ip, Carried::script_in(cx, view)),
                }
            };
        }
        let value = match vm.record_field_entry_hit(i.field_hint(), base) {
            Some(value) => value,
            None => or_general!(unsafe { lane_sink_first_refresh(cx, ip, base) }),
        };
        let value = match site.second {
            Some((_, cache)) => or_general!(vm.primary_own_field_hit(code, value, cache)),
            None => value,
        };
        let (atom, cache) = or_general!(site.sink);
        let this = unsafe { lane_held_this(cx, r) };
        if !vm.primary_own_field_store_hit::<false>(code, this, atom, value, cache, crate::heap::PropertyStoreLayout::Preserve) {
            sibling!(lane_get_field_sink::<H>, r, ip, Carried::script_in(cx, view))
        }
        r.set(i.a & crate::bytecode::REGISTER_MASK, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A nested `GetField` that also stores its value to a field of `this` (`this.a =
    /// this.b.c`): the read as `lane_get_field` makes it, then the cached write of
    /// `SetThisField`. A read or write the caches do not answer takes the general path,
    /// which repeats the side-effect-free read.
    fn lane_get_field_sink<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let (Some(value), Some(this), Some(sink)) = (
            unsafe { lane_field_value(cx, r, i) },
            unsafe { lane_this(cx, r) },
            code.field_sites.get(i.imm() as usize).and_then(|site| site.sink),
        ) else {
            return exit(ip);
        };
        let vm = unsafe { vm(cx) };
        if !vm.cached_field_write_hit(code, this, sink.0, value, sink.1) {
            return exit(ip);
        }
        // Adding a property can allocate.
        note_allocation(vm);
        r.set(i.a & crate::bytecode::REGISTER_MASK, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// Store through the field cache; any other store takes the general path.
#[inline(always)]
fn lane_set_field<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    object: Value,
    i: &LaneInstruction,
) -> Resumed {
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let vm = unsafe { vm(cx) };
    // A private field's store writes the object's private element, as the general loop's
    // `SetField` does, before any cache; the general loop's cached write otherwise: the store
    // inline, the add out of line.
    let private = vm.is_private_name(i.imm());
    let stored = if private {
        lane_private_field_store(cx, ip, code, object, i.imm(), r.get(i.a))
    } else {
        vm.cached_field_write_hit(code, object, i.imm(), r.get(i.a), i.c)
    };
    if !stored {
        if private {
            return Resumed::Exit(exit(ip));
        }
        return lane_set_field_in_place(cx, r, ip, object, i);
    }
    // Adding a property can allocate.
    note_allocation(vm);
    Resumed::At(r, following(ip), Carried::script(cx))
}

/// `lane_set_field` of a public name past its caches: the general store made in place
/// (`lane_in_place`), in the frame's own run or beside frameless activations, strict as its
/// record is. A store that adds a property to receivers of many shapes (zod's schema
/// initializers in the playwright npm scenario: 51K of its 79K lane exits) otherwise left the
/// lane at every store.
#[cold]
#[inline(never)]
fn lane_set_field_in_place<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    object: Value,
    i: &LaneInstruction,
) -> Resumed {
    // The running function decides the store's strictness: a running leaf's is its
    // materialized activation's.
    lane_materialize_running_leaf(cx);
    if let Some(resumed) = setters::lane_store_setter(cx, r, ip, i, object) {
        return resumed;
    }
    let Some(strict) = lane_store_is_strict(cx, ip) else {
        return Resumed::Exit(exit(ip));
    };
    let (atom, value, site) = (i.imm(), r.get(i.a), i.c);
    if let Some(resumed) = proxy_traps::lane_store_set_trap(cx, r, ip, object, atom, value, strict) {
        return resumed;
    }
    if lane_in_place(cx, ip, |vm, code| vm.set_field_cached(code, object, atom, value, site, strict)).is_none() {
        return Resumed::Exit(exit(ip));
    }
    // Guest code the store ran made the activations frames, whose registers these are.
    let r = unsafe { (*cx).registers };
    Resumed::At(r, following(ip), Carried::script(cx))
}

/// Whether the named field store at the record `ip` rejects a refused write with a
/// `TypeError`, as its opcode says; `None` for any other record.
fn lane_store_is_strict<H: Host>(cx: *mut LaneContext<H>, ip: Ip) -> Option<bool> {
    field_store_at(cx, ip).map(|store| store.strict)
}

/// The named field store at the record `ip`, as its opcode says; `None` for any other record.
fn field_store_at<H: Host>(cx: *mut LaneContext<H>, ip: Ip) -> Option<FieldStore> {
    let vm = unsafe { vm(cx) };
    let function = match vm.lane_stack.activations.last() {
        Some(activation) => activation.function,
        None => vm.frames[unsafe { (*cx).frame() }].function,
    };
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // innermost activation's view.
    let (code, pc) = unsafe { (&*(*cx).code, ip.offset_from((*cx).base) as usize) };
    let body = code.function(function as usize);
    body.widened(body.code[pc]).op().field_store()
}

/// The brand of private name `atom` at the record `ip`, whose home follows the running
/// function and the environment its frame would capture from: the lane's frame, or a
/// frameless activation's function and closure environment (`Vm::site_private_brand`).
#[inline(always)]
fn lane_private_brand<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    code: &ResidualProgram,
    atom: crate::bytecode::Atom,
) -> Option<crate::heap::PrivateBrand> {
    let (environment, function, frame) = lane_private_site(cx)?;
    unsafe { vm(cx) }.site_private_brand(code, ip.addr(), environment, function, frame, atom)
}

/// What a lane read of a private name of an object resolves to (`lane_get_private_field`).
enum PrivateRead {
    Value(Value),
    /// A private accessor's getter, called with the object.
    Getter(Value, Value),
}

/// The running function's private-name scope: the environment its frame, or its activation,
/// captures from, the function, and whether it runs in a frame (`Vm::site_private_brand`).
#[inline(always)]
fn lane_private_site<H: Host>(cx: *mut LaneContext<H>) -> Option<(Value, u32, bool)> {
    let vm = unsafe { vm(cx) };
    Some(match vm.lane_stack.activations.last() {
        None => {
            // The running frame is the top one, whose home `Vm::private_name_home` finds.
            let frame = vm.frames.len().checked_sub(1)?;
            (vm.captured_parent_environment(vm.frame_caller(frame)), vm.frames[frame].function, true)
        }
        // SAFETY: the context outlives the lane run.
        Some(activation) => (unsafe { (*cx).registers }.env(), activation.script().map(|_| activation.function)?, false),
    })
}

/// The slot of private field `atom` of `object` at the record `ip`, under its brand there: a
/// private field is a shape slot (`private_slots`), so the site's last shape and slot under
/// the home its environment finds (`PrivateSiteHomes::field_slot`) answer inline. `None` for
/// an object without the field, a private method's or accessor's brand included.
#[inline(always)]
fn lane_private_field_slot<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
) -> Option<usize> {
    lane_private_field_slot_at(cx, ip.addr(), code, object, atom)
}

/// `lane_private_field_slot` at site `site`: a record's address, or an address inside it for
/// a nested read's step (`lane_field_value`), which no other record's site can be.
#[inline(always)]
fn lane_private_field_slot_at<H: Host>(
    cx: *mut LaneContext<H>,
    site: usize,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
) -> Option<usize> {
    let scope = lane_private_site(cx)?;
    (unsafe { vm(cx) }).site_private_field_slot(code, site, scope, object, atom)
}

/// A `GetField` step's private field value at site `site` (`lane_private_field_slot_at`):
/// `None` for an object without the field, which the general path throws for, or a private
/// method's or accessor's name, which it reads.
#[inline(always)]
fn lane_private_field_value<H: Host>(
    cx: *mut LaneContext<H>,
    site: usize,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
) -> Option<Value> {
    let slot = lane_private_field_slot_at(cx, site, code, object, atom)?;
    let vm = unsafe { vm(cx) };
    vm.heap.property_get(vm.object_data(object)?, slot)
}

/// One `GetField` step of `lane_field_value`: a private name's at its site, any other name's
/// through the field caches (`lane_cached_field`).
#[inline(always)]
fn lane_field_step<H: Host>(
    cx: *mut LaneContext<H>,
    site: usize,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
    cache: u16,
) -> Option<Value> {
    lane_cached_field_at(cx, code, object, atom, cache, site)
}

/// The store of private field `atom` of `object` at the record `ip`, under its brand there
/// (`lane_private_field_slot`). `false` leaves the store, a private accessor's or method's
/// included, to the general path.
#[inline(never)]
fn lane_private_field_store<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    code: &ResidualProgram,
    object: Value,
    atom: crate::bytecode::Atom,
    value: Value,
) -> bool {
    let Some(slot) = lane_private_field_slot(cx, ip, code, object, atom) else {
        return false;
    };
    (unsafe { vm(cx) }).heap.property_set(object, slot, value);
    true
}

/// Leave the lane at `ip` after its instruction failed with `error` before any effect: a frame
/// run raises it there (`Vm::lane_raised`); an activation leaves the instruction to the general
/// path, which runs it again and raises the same error.
#[inline(never)]
fn lane_raise<H: Host>(cx: *mut LaneContext<H>, ip: Ip, error: JsError) -> Ip {
    let vm = unsafe { vm(cx) };
    if vm.lane_stack.activations.is_empty() {
        vm.lane_completion.raise(error);
    }
    exit(ip)
}

script_handler! {
    /// `DefineField` (`Vm::define_field_cached`), as the general step defines it. A Proxy
    /// receiver's define runs its trap, which a frameless activation leaves to the general path.
    #[inline(never)]
    fn lane_define_field<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let object = r.get(i.b);
        // An object record, which is never a proxy, takes its site's proved define inline.
        if vm.proved_field_define_hit(object, i.imm(), r.get(i.a), i.c) {
            // Adding a property can allocate.
            note_allocation(vm);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        if !vm.lane_stack.activations.is_empty() && vm.proxy_parts(object).is_some() {
            return exit(ip);
        }
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        if let Err(error) = vm.define_field_cached(code, object, i.imm(), r.get(i.a), i.c) {
            return lane_raise(cx, ip, error);
        }
        // Adding a property can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `DefinePrivateField` (`Vm::initialize_private_field`) of the object in `b` under the home
    /// in `c`, which runs no guest code.
    #[inline(never)]
    fn lane_define_private_field<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (object, home) = (r.get(i.b), r.get(i.c));
        // The site's last add from this shape under this home (`PrivateSiteHomes::define_shape`).
        if let Some(data) = vm.object_data(object)
            && let Some(next) = vm.private_site_homes.define_shape(ip.addr(), home, data.shape())
            && vm.private_element_addable(data)
        {
            vm.heap.property_add(object, r.get(i.a), next);
            note_allocation(vm);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let before = vm.object_data(object).map(|data| data.shape());
        if let Err(error) = vm.initialize_private_field(code, object, home, i.imm(), r.get(i.a)) {
            return lane_raise(cx, ip, error);
        }
        if let (Some(before), Some(after)) = (before, vm.object_data(object).map(|data| data.shape()))
            && vm.private_shape_cacheable(before)
            && vm.private_shape_cacheable(after)
        {
            vm.private_site_homes.record_define(ip.addr(), home, before, after);
        }
        // Adding a private element can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `MarkPrivateName` (`Vm::mark_private_name`) of the object in `b` under the home in `c`,
    /// which runs no guest code: a constructor's private methods, branded in place where a
    /// general step would materialize the activations it runs beside.
    #[inline(never)]
    fn lane_mark_private_name<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (object, home) = (r.get(i.b), r.get(i.c));
        // The site's last brand from this shape under this home (`PrivateSiteHomes::define_shape`);
        // the shape lacks the brand, so the object is not branded yet.
        if object != home
            && let Some(data) = vm.object_data(object)
            && let Some(next) = vm.private_site_homes.define_shape(ip.addr(), home, data.shape())
            && vm.private_element_addable(data)
        {
            vm.heap.property_add(object, Value::UNDEFINED, next);
            note_allocation(vm);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let before = vm.object_data(object).map(|data| data.shape());
        if let Err(error) = vm.mark_private_name(code, object, home, i.imm()) {
            return lane_raise(cx, ip, error);
        }
        if object != home
            && let (Some(before), Some(after)) = (before, vm.object_data(object).map(|data| data.shape()))
            && before != after
            && vm.private_shape_cacheable(before)
            && vm.private_shape_cacheable(after)
        {
            vm.private_site_homes.record_define(ip.addr(), home, before, after);
        }
        // Adding a private element can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// `DefinePropertyRecord` of the record at `ip`, defined as the general step defines it: a
/// class method or accessor, or an object literal accessor. An out-of-domain mode or a throw
/// leaves the instruction to the general path. Out of line, as `lane_set_index_slot_store`:
/// the handler's frame then holds none of the descriptor.
#[inline(never)]
fn lane_define_property_record_in_place<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    i: &LaneInstruction,
) -> Option<()> {
    let mode = crate::bytecode::PropertyDefinitionMode::from_word(i.imm())?;
    let (value, target, key) = (i.a, i.b, i.c);
    lane_in_place(cx, ip, |vm, code| {
        let (value, target, key) = {
            let r = unsafe { (*cx).registers };
            (r.get(value), r.get(target), r.get(key))
        };
        let descriptor =
            super::object_descriptors::PropertyDescriptorRecord::for_definition(mode, value);
        vm.define_property_or_throw(code, target, key, descriptor)
    })
}

script_handler! {
    /// `DefinePropertyRecord`, whose computed key's conversion or a proxy's define may run
    /// guest code. An out-of-domain mode leaves the instruction to the general path before it
    /// has any effect.
    #[inline(never)]
    fn lane_define_property_record<>(cx, r, ip, i, view) {
        if lane_define_property_record_in_place(cx, ip, i).is_none() {
            return exit(ip);
        }
        // Guest code the definition ran made the activations frames, whose registers these are.
        let r = unsafe { (*cx).registers };
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `CheckPrivate` of an object holding the private field under the name's brand at this
    /// record (`lane_private_brand`), which proves the check; any other check takes
    /// `lane_general_step`.
    #[inline(never)]
    fn lane_check_private<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let present = lane_private_field_slot(cx, ip, code, r.get(i.a), i.imm()).is_some();
        if !present {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `CopyDataProperties` (an object spread or rest) that a plain copy answers
    /// (`Vm::copy_plain_data_properties`), which runs no guest code and cannot throw, so it
    /// runs beside activations; any other copy takes `lane_general_step`.
    #[inline(never)]
    fn lane_copy_data_properties<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !vm.copy_plain_data_properties(r.get(i.a), r.get(i.b), r.get(i.c)) {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        }
        // The copy can allocate property storage.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `PrivateIn` (`#x in object`) of an object with its own data (`Vm::object_data`): whether
    /// it carries the name's brand at this record (`lane_private_brand`), a field's or a
    /// method's. Any other operand, which may raise, takes `lane_general_step`.
    #[inline(never)]
    fn lane_private_in<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let carries = lane_private_brand(cx, ip, code, i.imm()).and_then(|brand| {
            let vm = unsafe { vm(cx) };
            vm.object_data(r.get(i.b)).map(|_| vm.has_private_name(r.get(i.b), brand))
        });
        let Some(carries) = carries else {
            sibling!(lane_general_step::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, Value::boolean(carries));
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `GetField` of a private name (`Vm::is_private_name`) from a register or `this`, which
    /// no field cache records (`lane_get_field_first`): the object's private field under
    /// the name's brand at this record (`lane_private_brand`). Any other read, a private
    /// method's or accessor's included, takes `lane_get_field`.
    #[inline(never)]
    fn lane_get_private_field<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let read = unsafe { lane_field_base(cx, r, crate::bytecode::FieldBase(i.b)) }.and_then(|object| {
            if let Some(slot) = lane_private_field_slot(cx, ip, code, object, i.imm()) {
                let vm = unsafe { vm(cx) };
                return vm.heap.property_get(vm.object_data(object)?, slot).map(PrivateRead::Value);
            }
            let brand = lane_private_brand(cx, ip, code, i.imm())?;
            let vm = unsafe { vm(cx) };
            match vm.private_field(object, brand) {
                Some(value) => Some(PrivateRead::Value(value)),
                // A method or accessor of a brand the object carries (`Vm::site_private_element`).
                None if vm.has_private_name(object, brand) => {
                    match vm.site_private_element(ip.addr(), brand, object)? {
                        super::private_site_home::PrivateElement::Method(value) => Some(PrivateRead::Value(value)),
                        super::private_site_home::PrivateElement::Getter(getter) => Some(PrivateRead::Getter(object, getter)),
                    }
                }
                None => None,
            }
        });
        match read {
            Some(PrivateRead::Value(value)) => {
                r.set(i.a, value);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            // The getter runs as the read's activation, as a cached accessor's does.
            Some(PrivateRead::Getter(object, getter)) => match lane_activate_getter(cx, r, ip, getter, object, None) {
                Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                Err(next) => next,
            },
            None => sibling!(lane_get_field::<H>, r, ip, Carried::script_in(cx, view)),
        }
    }
}

script_handler! {
    /// A named store's own-field hint in a runtime whose arena keeps slot representations
    /// (`Heap::tracks_slot_representations`), which the generated store (`field_store_row`)
    /// refuses: the tracked store (`Vm::hinted_primary_field_store_hit`), of `this` or field
    /// B's register; any other takes `lane_set_field_logged`.
    fn lane_set_field_own_tracked<THIS: bool>(cx, r, ip, i, view) {
        let object = if THIS { unsafe { lane_held_this(cx, r) } } else { r.get(i.b) };
        if !unsafe { vm(cx) }.hinted_primary_field_store_hit::<true>(i.field_hint(), object, i.imm(), r.get(i.a)) {
            sibling!(lane_set_field_own_miss::<H, THIS, true>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A refused hinted own-field store (`field_store_row`, `lane_set_field_own_tracked`):
    /// in a runtime whose arena keeps slot representations, which the untracked store refuses,
    /// the record moves to the tracked store for good; the store itself takes
    /// `lane_set_field_logged`.
    #[inline(never)]
    fn lane_set_field_own_miss<THIS: bool, TRACKED: bool>(cx, r, ip, i, view) {
        if !TRACKED && unsafe { vm(cx) }.heap.tracks_slot_representations() {
            requicken::<H>(ip, lane_set_field_own_tracked::<H, THIS>);
        }
        sibling!(lane_set_field_logged::<H, THIS>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An own-field store (`field_store_row`, `lane_set_field_own_tracked`) the write
    /// barrier logs, which may grow its log: the store with the barrier, out of line so the
    /// inline store makes no call. Any other takes `lane_set_field_miss`.
    #[inline(never)]
    fn lane_set_field_logged<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let object = if THIS { unsafe { lane_fixed_this(cx, r) } } else { Some(r.get(i.b)) };
        let stored = object.is_some_and(|object| {
            let vm = unsafe { vm(cx) };
            let stored = vm.primary_own_field_store_hit::<true>(code, object, i.imm(), r.get(i.a), i.c, crate::heap::PropertyStoreLayout::MayWiden);
            if stored {
                // The store may move the values (`MayWiden`): the hint takes the form after it.
                let hint = vm.form_hint(vm.field_cache_entry(i.c), object);
                set_field_hint(ip, hint);
                // A narrow run's site stores in place from now on (`lane_set_field_narrow`); a
                // narrow site whose object is no longer narrow goes back to the own store.
                let narrow = crate::heap::layouts::auxiliary(hint.receiver) & crate::value_vec::STORAGE_FORM == crate::value_vec::NARROW_FORM;
                if !vm.heap.tracks_slot_representations() {
                    if narrow {
                        requicken::<H>(ip, lane_set_field_narrow::<H, THIS>);
                    } else if handler_is::<H>(ip, lane_set_field_narrow::<H, THIS>) {
                        if let Some(store) = field_store_at(cx, ip) {
                            requicken::<H>(ip, field_store_row::<H>(store));
                        }
                    }
                }
            }
            stored
        });
        if !stored {
            sibling!(lane_set_field_miss::<H, THIS>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An own-field store at a site whose objects keep narrow runs (`value_vec::NARROW_FORM`),
    /// which `lane_set_field_logged` installs: the value's narrow form in place
    /// (`Vm::hinted_narrow_field_store_hit`). Any other store takes `lane_set_field_logged`.
    #[inline(never)]
    fn lane_set_field_narrow<THIS: bool>(cx, r, ip, i, view) {
        let object = if THIS { unsafe { lane_held_this(cx, r) } } else { r.get(i.b) };
        if !unsafe { vm(cx) }.hinted_narrow_field_store_hit(i.field_hint(), object, i.imm(), r.get(i.a)) {
            sibling!(lane_set_field_logged::<H, THIS>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An own-field store at a site past one shape (`lane_set_field_miss`):
    /// the slot its megamorphic entries record for the receiver's shape
    /// (`Vm::polymorphic_own_field_store_hit`), as a parser's `this.pos =` reads a parser
    /// whose shape grows while it runs. A miss takes the general cached write.
    ///
    /// A site that also adds (splay's `Node.prototype.left = null` gives `.left =` four receiver
    /// shapes, one of them without the property): a miss takes the proved add
    /// (`Vm::proved_field_add_hit`, one of the site's add entries) before the general write.
    #[inline(never)]
    fn lane_set_field_polymorphic<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let object = if THIS { unsafe { lane_fixed_this(cx, r) } } else { Some(r.get(i.b)) };
        let stored = object.is_some_and(|object| {
            let vm = unsafe { vm(cx) };
            // The record's hint first, the own entry its last store named, then the entries.
            vm.hinted_own_field_store_hit(i.field_hint(), object, i.imm(), r.get(i.a))
                || vm.polymorphic_own_field_store_hit(code, object, i.imm(), r.get(i.a), i.c, crate::heap::PropertyStoreLayout::MayWiden).is_some_and(|own| {
                    set_field_hint(ip, own);
                    true
                })
        });
        if !stored {
            let vm = unsafe { vm(cx) };
            if object.is_some_and(|object| vm.proved_field_add_hit(object, i.imm(), r.get(i.a), i.c)) {
                // Adding a property can allocate.
                note_allocation(vm);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            if THIS {
                sibling!(lane_set_this_field::<H>, r, ip, Carried::script_in(cx, view))
            }
            sibling!(lane_set_object_field::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A miss of an own-field store (`field_store_row`, `lane_set_field_own_tracked`):
    /// a site that adds properties or went polymorphic moves to the general cached write
    /// (`lane_set_object_field`, `lane_set_this_field`), which the store itself takes.
    #[inline(never)]
    fn lane_set_field_miss<THIS: bool>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let polymorphic = vm.field_site_polymorphic(i.c);
        let adds = vm.field_site_adds(i.c);
        // A receiver outside the object records (a RegExp's or a function's cell) hits the
        // own store's logged path (`Vm::primary_cell_field_store_hit`) only at one shape, so
        // a polymorphic site of one takes the general cached write from now on.
        let cell_receiver = !THIS && r.get(i.b).direct_object_index().is_none() && vm.is_object_like(r.get(i.b));
        // A private field's store takes the private element path (`lane_set_field`).
        let handler: Option<Handler> = if vm.is_private_name(i.imm()) {
            Some(if THIS { lane_set_this_field::<H> } else { lane_set_object_field::<H> })
        } else if adds && !polymorphic && vm.field_add_atom_eligible(i.imm()) {
            Some(if THIS { lane_set_this_field_add::<H> } else { lane_set_object_field_add::<H> })
        } else if polymorphic && !cell_receiver {
            Some(lane_set_field_polymorphic::<H, THIS>)
        } else if adds || polymorphic {
            Some(if THIS { lane_set_this_field::<H> } else { lane_set_object_field::<H> })
        } else {
            None
        };
        if let Some(handler) = handler {
            requicken::<H>(ip, handler);
        }
        if THIS {
            sibling!(lane_set_this_field::<H>, r, ip, Carried::script_in(cx, view))
        }
        sibling!(lane_set_object_field::<H>, r, ip, Carried::script_in(cx, view))
    }
}

/// The cached add of an add record (`Vm::primary_field_add_hit`) of `r[i.a]` to `object`.
/// Out of line: the add keeps locals whose addresses its callees take, which the handler's
/// common path then does not hold.
#[inline(never)]
fn lane_field_add<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    object: Value,
    i: &LaneInstruction,
) -> bool {
    // SAFETY: the record's registers belong to the running activation, which the add
    // neither moves nor frees.
    let value = unsafe { (*lane_context::<H>()).registers }.get(i.a);
    vm.primary_field_add_hit(code, object, i.imm(), value, i.c)
}

script_handler! {
    /// `SetField` or `SetFieldStrict` at a site that adds a property to records of one shape
    /// (`lane_set_field_miss`): the proved add inline (`Vm::proved_field_add_hit`), else the
    /// cached add alone, out of line (`lane_set_field_add_any`).
    fn lane_set_object_field_add<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !vm.proved_field_add_hit(r.get(i.b), i.imm(), r.get(i.a), i.c) {
            sibling!(lane_set_field_add_any::<H, false>, r, ip, Carried::script_in(cx, view))
        }
        // Adding a property can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_set_object_field_add` for `SetThisField` and `SetThisFieldStrict`.
    fn lane_set_this_field_add<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let added = unsafe { lane_fixed_this(cx, r) }.is_some_and(|this| vm.proved_field_add_hit(this, i.imm(), r.get(i.a), i.c));
        if !added {
            sibling!(lane_set_field_add_any::<H, true>, r, ip, Carried::script_in(cx, view))
        }
        // Adding a property can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An add record's add past a proved one (`lane_set_object_field_add`,
    /// `lane_set_this_field_add`): the cached add (`Vm::primary_field_add_hit`), which may
    /// prove the chain or move storage. Any other write moves the record to the general
    /// cached write (`lane_set_object_field`, `lane_set_this_field`), which makes it.
    #[inline(never)]
    fn lane_set_field_add_any<THIS: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let object = if THIS { unsafe { lane_fixed_this(cx, r) } } else { Some(r.get(i.b)) };
        if !object.is_some_and(|object| lane_field_add(vm, code, object, i)) {
            let general: Handler = if THIS { lane_set_this_field::<H> } else { lane_set_object_field::<H> };
            requicken::<H>(ip, general);
            if THIS {
                sibling!(lane_set_this_field::<H>, r, ip, Carried::script_in(cx, view))
            }
            sibling!(lane_set_object_field::<H>, r, ip, Carried::script_in(cx, view))
        }
        // Adding a property can allocate.
        note_allocation(vm);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `SetField` and `SetFieldStrict`.
    fn lane_set_object_field<>(cx, r, ip, i, view) {
        resume!(cx, lane_set_field(cx, r, ip, r.get(i.b), i))
    }
}

script_handler! {
    /// `SetThisField` and `SetThisFieldStrict`.
    fn lane_set_this_field<>(cx, r, ip, i, view) {
        let Some(this) = (unsafe { lane_this(cx, r) }) else {
            return exit(ip);
        };
        resume!(cx, lane_set_field(cx, r, ip, this, i))
    }
}

script_handler! {
    /// The comparison of the record's operator over its register, constant and local operands, by
    /// the staged step on the interpreter's stage: two observed Numbers decide a relation, the
    /// words and the lane's strict decision an equality. Any other pair takes
    /// `lane_jump_binary_false_chain`.
    fn lane_jump_binary_false<BACKWARD: bool>(cx, r, ip, i, view) {
        let (Some(left), Some(right)) = (RecordOperand::encoded(i.b), RecordOperand::encoded(i.c)) else {
            return exit(ip);
        };
        let Some(edge) = lane_frame::staged_record_jump::<H>(cx, r, view, u32::from(i.a), [left, right]) else {
            sibling!(lane_jump_binary_false_chain::<H, BACKWARD>, r, ip, Carried::script(cx))
        };
        jump_on_edge!(cx, r, ip, BACKWARD, edge)
    }
}

/// The edge a decided comparison takes: the jump is taken where it fails.
#[inline(always)]
const fn holds_edge(holds: bool) -> crate::staged::Edge {
    if holds { crate::staged::Edge::Following } else { crate::staged::Edge::Target }
}

script_handler! {
    /// `lane_jump_binary_false` of a pair the staged step leaves: the relations the lane decides
    /// without guest code (`lane_relation_other`); any other takes the general path. Out of line,
    /// so the staged case keeps few values live.
    #[inline(never)]
    fn lane_jump_binary_false_chain<BACKWARD: bool>(cx, r, ip, i, view) {
        let (Some(left), Some(right)) =
            (lane_operand_value(cx, r, i.b), lane_operand_value(cx, r, i.c))
        else {
            return exit(ip);
        };
        // SAFETY: the record is a comparison record of the running view.
        unsafe { note_operands(cx, ip, left, right) };
        let Some(holds) = lane_relation_other::<H>(u32::from(i.a), left, right) else {
            return exit(ip);
        };
        jump_on_edge!(cx, r, ip, BACKWARD, holds_edge(holds), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `Binary` `instanceof` of two registers, decoded when the view was derived
    /// (`specialize_register_operands`): the ordinary prototype-chain walk
    /// (`Vm::ordinary_instanceof`), which runs no guest code. Any other case, which the full
    /// algorithm decides, takes the general path.
    fn lane_instanceof_value<>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).proved_instanceof(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_instanceof_value_walk::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        // `instanceof` is a JavaScript record, which carries the script state.
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_instanceof_value` run with the `JumpTrue` of its result that follows it, the
    /// `!(x instanceof C)` test of compiled code (`specialize_negated_instanceof`): the
    /// record carries the jump's distance from itself, and the result register is written
    /// as the pair would. A case the steady test leaves runs the pair unfused, from the walk.
    fn lane_instanceof_jump_true<BACKWARD: bool>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).record_instanceof(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_instanceof_jump_true_proving::<H, BACKWARD>, r, ip, Carried::script_in(cx, view))
        };
        if holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), Some((i.a, Value::TRUE))));
        }
        r.set(i.a, Value::FALSE);
        // SAFETY: the fused pair is two records, the second never the view's last.
        next!(cx, r, unsafe { ip.add(2) }, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_instanceof_jump_true` for whatever its record walk leaves (`Vm::record_instanceof`):
    /// the proved test in full, which may prove, out of line so the walk calls nothing.
    #[inline(never)]
    fn lane_instanceof_jump_true_proving<BACKWARD: bool>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).proved_instanceof(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_instanceof_value_walk::<H>, r, ip, Carried::script_in(cx, view))
        };
        if holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), Some((i.a, Value::TRUE))));
        }
        r.set(i.a, Value::FALSE);
        // SAFETY: the fused pair is two records, the second never the view's last.
        next!(cx, r, unsafe { ip.add(2) }, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_instanceof_value` that its steady case leaves (`Vm::steady_instanceof`): the
    /// whole ordinary walk, out of line so the steady case calls nothing.
    #[inline(never)]
    fn lane_instanceof_value_walk<>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).ordinary_instanceof(r.get(i.b), r.get(i.c)) else {
            return exit(ip);
        };
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false` of `instanceof` with register operands, decoded when the view
    /// was derived (`specialize_register_operands`), as `lane_instanceof_value` decides it.
    fn lane_jump_instanceof_false<BACKWARD: bool>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).proved_instanceof(r.get(i.b), r.get(i.c)) else {
            sibling!(lane_jump_instanceof_false_walk::<H, BACKWARD>, r, ip, Carried::script_in(cx, view))
        };
        // `instanceof` is a JavaScript record, which carries the script state.
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_instanceof_false` that its steady case leaves: the whole ordinary walk, out
    /// of line so the steady case calls nothing.
    #[inline(never)]
    fn lane_jump_instanceof_false_walk<BACKWARD: bool>(cx, r, ip, i, view) {
        let Some(holds) = (unsafe { vm(cx) }).ordinary_instanceof(r.get(i.b), r.get(i.c)) else {
            return exit(ip);
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false` with register operands, decoded when the view was derived
    /// (`specialize_register_operands`): Number comparison of two integers
    /// (`integer_relation`); any other pair takes `lane_jump_binary_false_registers_other`.
    fn lane_jump_binary_false_registers<BACKWARD: bool, OP: u32>(cx, r, ip, i, view) {
        let Some(holds) = (match (r.int(i.b), r.int(i.c)) {
            (Some(left), Some(right)) => super::operations::integer_test_i32(relation_operator::<OP>(i), left, right),
            _ => None,
        }) else {
            sibling!(lane_jump_binary_false_registers_other::<H, BACKWARD, OP>, r, ip, Carried::script_in(cx, view))
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A plain local load (`CAPTURE` false) or a capture the frame's environment owns
    /// directly (`CAPTURE` true, as `lane_load_capture` reads it) followed by a
    /// register/register comparison branch. The load still writes its destination before the
    /// branch reads either operand, preserving aliases and values live beyond the branch
    /// while skipping one threaded dispatch. A capture the fast read misses runs the load's
    /// own walk, which continues at the branch record.
    fn lane_load_jump_binary_false_registers<BACKWARD: bool, CAPTURE: bool, OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the view installs this handler only for an adjacent supported branch record.
        let branch_ip = unsafe { ip.add(1) };
        let branch = unsafe { &*branch_ip };
        let value = if CAPTURE {
            let slots = capture_reads(unsafe { (*cx).registers }.capture());
            // SAFETY: as `lane_load_capture`'s read.
            let value = unsafe { crate::heap::EnvironmentSlots::read_storage(slots, ImmediateLayout::capture_slot(i.imm())) };
            let Some(value) = value else {
                sibling!(lane_load_capture_walk::<H>, r, ip, view)
            };
            value
        } else {
            // SAFETY: the function's validated bytecode bounds the local slot, and the lane
            // keeps its frame installed for the whole run.
            unsafe { vm(cx).read_validated_local((*cx).frame(), i.imm() as usize) }
        };
        r.set(i.a, value);
        let Some(comparison) = lane_integer_comparison(relation_operator::<OP>(branch), r.get(branch.b), r.get(branch.c)) else {
            sibling!(
                lane_jump_binary_false_registers_other::<H, BACKWARD, OP>,
                r,
                branch_ip,
                Carried::script_in(cx, view)
            )
        };
        let edge = lane_frame::staged_compare_jump::<H>(cx, r, view, comparison, [branch.b, branch.c])
            .expect("two integers decide a relation");
        jump_on_edge!(cx, r, branch_ip, BACKWARD, edge, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false_registers` of operands other than two integers: the relations
    /// the lane decides without guest code (`lane_relation`); any other takes the general
    /// path. Out of line, so the integer case keeps few values live.
    #[inline(never)]
    fn lane_jump_binary_false_registers_other<BACKWARD: bool, OP: u32>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), r.get(i.c));
        // Two string records under an ordering operator: their code-unit order decides, the
        // first answer `lane_relation_other` gives the pair, and the pair is no Number one
        // for `requicken_number_relation` to move.
        if left.direct_string_index().is_some()
            && right.direct_string_index().is_some()
            && let operator = relation_operator::<OP>(i)
            && super::operations::NumberRelation::from_operator(operator).is_some()
            && let Some(holds) = unsafe { vm(cx) }.string_relation(operator, left, right)
        {
            // SAFETY: the record is a comparison record of the running view.
            unsafe { note_kind(cx, ip, OperandKinds::STRING) };
            if !holds {
                resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
            }
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        // SAFETY: the record is a comparison record of the running view.
        unsafe { note_operands(cx, ip, left, right) };
        // SAFETY: as above.
        unsafe { requicken_number_relation::<H, BACKWARD, OP, false, false>(cx, ip, r.get(i.b), r.get(i.c)) };
        let Some(holds) = lane_relation::<H>(relation_operator::<OP>(i), r.get(i.b), r.get(i.c)) else {
            return exit(ip);
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A jump test whose site met a Number that is no int32 (`requicken_number_relation`):
    /// any two Numbers compare through their doubles, as `number_relation` decides, with the
    /// right operand a register or (`SMALL`) the record's constant (`lane_small_constant`).
    /// The site's feedback already holds both Number kinds, so a Number pair notes nothing;
    /// any other pair runs the integer handler's out-of-line case, which notes it.
    fn lane_jump_binary_false_numbers<BACKWARD: bool, OP: u32, SMALL: bool, TABLE: bool>(cx, r, ip, i, view) {
        let right = if SMALL { lane_small_constant::<H, TABLE>(cx, i).as_number() } else { r.number(i.c) };
        let (Some(left), Some(right)) = (r.number(i.b), right) else {
            if SMALL {
                sibling!(lane_jump_binary_false_small_other::<H, BACKWARD, TABLE>, r, ip, Carried::script_in(cx, view))
            }
            sibling!(lane_jump_binary_false_registers_other::<H, BACKWARD, OP>, r, ip, Carried::script_in(cx, view))
        };
        if !super::operations::double_relation(relation_operator::<OP>(i), left, right) {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// Moves the integer jump test at `ip` (`lane_jump_binary_false_registers`, `_small`) to
/// `lane_jump_binary_false_numbers` once its site met a Number pair that is not two int32s,
/// a relational or equality operator's: its feedback byte gains both Number kinds first, as
/// the moved handler stops noting Number pairs (the site's class is Number either way, a
/// double having been met). The handler there must be the integer one: a fused load test
/// runs the out-of-line case for its branch record directly.
///
/// # Safety
/// As `note_operands`.
#[inline(always)]
unsafe fn requicken_number_relation<H: Host, const BACKWARD: bool, const OP: u32, const SMALL: bool, const TABLE: bool>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    left: Value,
    right: Value,
) {
    // SAFETY: the record is a live record of the running view.
    let i = unsafe { &*ip };
    let integer: Handler = if SMALL {
        lane_jump_binary_false_small::<H, BACKWARD, OP, TABLE>
    } else {
        lane_jump_binary_false_registers::<H, BACKWARD, OP>
    };
    if relation_operator::<OP>(i) <= super::operations::LAST_COMPARISON_OPERATOR
        && i.handler == integer as *const ()
        && left.as_number().is_some()
        && right.as_number().is_some()
        && Value::int_pair(left, right).is_none()
    {
        // SAFETY: the caller's.
        unsafe { note_number_kinds(cx, ip) };
        requicken::<H>(ip, lane_jump_binary_false_numbers::<H, BACKWARD, OP, SMALL, TABLE>);
    }
}

/// The integer constant of a jump test against a constant (`lane_jump_binary_false_small`): the
/// record's own 16 bits, or with `TABLE` the program's constant its `c` indexes, for one past them.
#[inline(always)]
fn lane_small_constant<H: Host, const TABLE: bool>(cx: *mut LaneContext<H>, i: &LaneInstruction) -> Value {
    if TABLE {
        // SAFETY: the run's program keeps its constants (`LaneContext::constants`), and the
        // view was derived with `c` indexing an integer one.
        unsafe { *(&*(*cx).constants).get_unchecked(usize::from(i.c)) }
    } else {
        Value::integer(i32::from(i.c as i16))
    }
}

script_handler! {
    /// `lane_jump_binary_false` of a register and an integer constant small enough for the
    /// record's `c` field, both decoded when the view was derived
    /// (`specialize_register_operands`): integer comparison of an integer register
    /// (`integer_test_i32`), which also decides a bitwise result's truth; any other takes
    /// `lane_jump_binary_false_small_other`.
    fn lane_jump_binary_false_small<BACKWARD: bool, OP: u32, TABLE: bool>(cx, r, ip, i, view) {
        let right = lane_small_constant::<H, TABLE>(cx, i);
        let Some(holds) = (match (r.int(i.b), right.as_int()) {
            (Some(left), Some(right)) => super::operations::integer_test_i32(relation_operator::<OP>(i), left, right),
            _ => None,
        }) else {
            sibling!(lane_jump_binary_false_small_other::<H, BACKWARD, TABLE>, r, ip, view)
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, None));
        }
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `lane_jump_binary_false_small` of an operator or register value other than an integer
    /// comparison: a Number comparison (`number_relation`), else the truth of a Number
    /// operator's result (`if (x & MASK)`) or another relation (`lane_relation_other`). Out of
    /// line, so the integer case keeps few values live and makes no call.
    #[inline(never)]
    fn lane_jump_binary_false_small_other<BACKWARD: bool, TABLE: bool>(cx, r, ip, i, view) {
        let right = lane_small_constant::<H, TABLE>(cx, i);
        // SAFETY: the record is a comparison record of the running view.
        unsafe { note_operands(cx, ip, r.get(i.b), right) };
        // SAFETY: as above.
        unsafe { requicken_small_number_relation::<H, BACKWARD, TABLE>(cx, ip, r.get(i.b), right) };
        let Some(holds) = super::operations::number_relation(u32::from(i.a), r.get(i.b), right)
            .or_else(|| lane_relation_other::<H>(u32::from(i.a), r.get(i.b), right))
        else {
            return exit(ip);
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false` of a register under strict (in)equality against a heap
    /// constant (a string or BigInt), both decoded when the view was derived
    /// (`specialize_register_operands`): equal exactly when identical or of equal contents
    /// (`Vm::strict_equal`), with no Number or `instanceof` test on the way: the staged equality
    /// decides identity, and `lane_jump_strict_constant_contents` the contents.
    fn lane_jump_strict_constant_false<BACKWARD: bool>(cx, r, ip, i, view) {
        let operands = [RecordOperand::Register(i.b), RecordOperand::Constant(i.c)];
        let Some(edge) = lane_frame::staged_record_jump::<H>(cx, r, view, u32::from(i.a), operands) else {
            sibling!(lane_jump_strict_constant_contents::<H, BACKWARD>, r, ip, Carried::script(cx))
        };
        jump_on_edge!(cx, r, ip, BACKWARD, edge)
    }
}

script_handler! {
    /// `lane_jump_strict_constant_false` of a value the words leave (identity and two integers
    /// decide the rest): a heap value of equal contents to the heap constant
    /// (`Vm::heap_values_strictly_equal`) is equal, any other is not.
    #[inline(never)]
    fn lane_jump_strict_constant_contents<BACKWARD: bool>(cx, r, ip, i, view) {
        let value = r.get(i.b);
        // SAFETY: the run's program keeps its constants (`LaneContext::constants`), and the
        // view was derived with `c` indexing one.
        let constant = unsafe { *(&*(*cx).constants).get_unchecked(usize::from(i.c)) };
        let negated = u32::from(i.a) == STRICT_INEQUALITY_OPERATOR;
        let equal = constant.is_heap() && value.is_heap() && unsafe { vm(cx) }.heap_values_strictly_equal(value, constant);
        jump_on_edge!(cx, r, ip, BACKWARD, holds_edge(equal != negated), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `StringCaseIndex`: the case a string `switch` selects (`Vm::string_case_index`) among
    /// the run of constants the record's immediate starts, which the view checked lies in
    /// the program's constants (`lane_operand`).
    fn lane_string_case_index<>(cx, r, ip, i, view) {
        let start = i.imm() as usize;
        // SAFETY: the run's program keeps its constants (`LaneContext::constants`).
        let cases = unsafe { (&*(*cx).constants).get_unchecked(start..start + usize::from(i.b)) };
        let index = unsafe { vm(cx) }.string_case_index(r.get(i.c), cases);
        r.set(i.a, Value::integer(index as i32));
        next!(cx, r, following(ip), view)
    }
}

/// The strict operators `lane_jump_strict_constant_false` decides.
const STRICT_INEQUALITY_OPERATOR: u32 = oxc_ast::ast::BinaryOperator::StrictInequality as u32;

/// Whether `value` is strictly equal to `constant`, a constant that is no Number: a boolean,
/// null or undefined is equal only to itself, a heap constant (a string or BigInt) also to
/// a value of equal contents (`Vm::heap_values_strictly_equal`).
#[inline(always)]
fn strictly_equal_constant<H: Host>(vm: &Vm<H>, value: Value, constant: Value) -> bool {
    value == constant || vm.heap_values_strictly_equal(value, constant)
}

lane_handler! {
    /// `lane_relation_value` under strict (in)equality against a constant that is no Number,
    /// carried in the record with the operator in `c` (`strictly_equal_constant`).
    fn lane_strict_constant_value<>(cx, r, ip, i, view) {
        let equal = strictly_equal_constant(unsafe { vm(cx) }, r.get(i.b), i.constant());
        let holds = equal != (u32::from(i.c) == STRICT_INEQUALITY_OPERATOR);
        r.set(i.a, if holds { Value::TRUE } else { Value::FALSE });
        next!(cx, r, following(ip), view)
    }
}

/// The nullish test of a `lane_jump_nullish_false` instantiation (`NULLISH`): strict
/// identity with `null` or with `undefined`, or loose equality with either.
const NULLISH_NULL: u16 = 0;
const NULLISH_UNDEFINED: u16 = 1;
const NULLISH_LOOSE: u16 = 2;

script_handler! {
    /// `lane_jump_binary_false` of a register under an equality operator against a `null` or
    /// `undefined` constant, decoded when the view was derived
    /// (`specialize_register_operands`) into the instantiation's negation and `NULLISH` test:
    /// strict equality is identity with the constant; loose equality holds for `null` and
    /// `undefined`, and among other values only for [[IsHTMLDDA]] objects
    /// (`Vm::identity_equality`).
    fn lane_jump_nullish_false<BACKWARD: bool, NEGATED: bool, NULLISH: u16>(cx, r, ip, i, view) {
        let (expected, strict) = match NULLISH {
            NULLISH_NULL => (crate::staged::Nullish::Null, true),
            NULLISH_UNDEFINED => (crate::staged::Nullish::Undefined, true),
            _ => (crate::staged::Nullish::Null, false),
        };
        let comparison = crate::staged::Comparison::Nullish { expected, strict, negated: NEGATED };
        // A heap cell outside the records may be the [[IsHTMLDDA]] object, which the step leaves.
        let Some(edge) = lane_frame::staged_compare_jump::<H>(cx, r, view, comparison, [i.b, i.b]) else {
            sibling!(lane_jump_nullish_cell::<H, BACKWARD, NEGATED>, r, ip, Carried::script_in(cx, view))
        };
        jump_on_edge!(cx, r, ip, BACKWARD, edge, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false` of a register under strict equality against a boolean
    /// constant (`specialize_register_operands`), the `x !== false` truthiness test of
    /// compiled code: a boolean strictly equals only itself, which has one encoding, so the
    /// test is the register's identity with the instantiation's constant (`TRUE`).
    fn lane_jump_boolean_false<BACKWARD: bool, NEGATED: bool, TRUE: bool>(cx, r, ip, i, view) {
        let comparison = crate::staged::Comparison::Boolean { expected: TRUE, negated: NEGATED };
        let operands = [RecordOperand::Register(i.b), RecordOperand::Immediate(Value::boolean(TRUE))];
        let edge = lane_frame::staged_comparison_jump::<H>(cx, r, view, comparison, operands)
            .expect("identity with a Boolean always decides");
        jump_on_edge!(cx, r, ip, BACKWARD, edge, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_binary_false` of two registers under `===` (`!==` where `NEGATED`)
    /// (`specialize_register_operands`): strict equality runs no guest code, so the lane
    /// decides every pair (`Vm::strict_equal`) without the general relation chain. Values
    /// outside the heap compare as numbers or by identity, and a heap value equals only
    /// itself among them, inline; two distinct heap values, which may be equal strings or
    /// BigInts, take `lane_jump_strict_equal_cells`.
    fn lane_jump_strict_equal_false<BACKWARD: bool, NEGATED: bool>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), r.get(i.c));
        // Equal words are strictly equal but for NaN, tested first: about half of a symbol-
        // comparing program's compares (V8-v7 Boyer) are of one value with itself.
        // Two distinct heap words, the common unequal case of reference-comparing code, are
        // decided by their families first, without decoding either word as a Number.
        let equal = if left == right { left.as_number().is_none_or(|number| !number.is_nan()) } else if !(left.is_heap() && right.is_heap()) {
            matches!((left.as_number(), right.as_number()), (Some(left), Some(right)) if left == right)
        } else {
            // Two distinct heap values are equal only as strings or BigInts, which their
            // handles' families name; a slot cell that is no BigInt (a Symbol) is not.
            match left.distinct_heap_pair(right) {
                crate::value::DistinctHeapPair::Unequal => false,
                crate::value::DistinctHeapPair::Strings => {
                    sibling!(lane_jump_strict_equal_cells::<H, BACKWARD, NEGATED>, r, ip, Carried::script_in(cx, view))
                }
                crate::value::DistinctHeapPair::Slots => {
                    if matches!(unsafe { vm(cx) }.heap.get(left), Some(crate::heap::Cell::BigInt(_))) {
                        sibling!(lane_jump_strict_equal_cells::<H, BACKWARD, NEGATED>, r, ip, Carried::script_in(cx, view))
                    }
                    false
                }
            }
        };
        if equal == NEGATED {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_strict_equal_false` of two distinct strings or BigInts (`Vm::distinct_heap_values_equal`); out
    /// of line, so the common tests make no call.
    #[inline(never)]
    fn lane_jump_strict_equal_cells<BACKWARD: bool, NEGATED: bool>(cx, r, ip, i, view) {
        if unsafe { vm(cx) }.distinct_heap_values_equal(r.get(i.b), r.get(i.c)) == NEGATED {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_jump_nullish_false`'s loose test of a heap value outside the records, which only
    /// an [[IsHTMLDDA]] object passes; out of line, so the common tests make no call.
    #[inline(never)]
    fn lane_jump_nullish_cell<BACKWARD: bool, NEGATED: bool>(cx, r, ip, i, view) {
        if unsafe { vm(cx) }.is_html_dda(r.get(i.b)) == NEGATED {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The instantiation of an equality jump-test handler for its direction and negation, the
/// const-generic prefix the view decodes from the record (`specialize_register_operands`).
macro_rules! equality_test_handler {
    ($handler:ident::<$host:ident $(, $rest:tt)*>, $backward:expr, $negated:expr) => {
        match ($backward, $negated) {
            (false, false) => $handler::<$host, false, false $(, $rest)*> as Handler,
            (false, true) => $handler::<$host, false, true $(, $rest)*> as Handler,
            (true, false) => $handler::<$host, true, false $(, $rest)*> as Handler,
            (true, true) => $handler::<$host, true, true $(, $rest)*> as Handler,
        }
    };
}

/// The tests the general loop decides past Number comparison without running guest code:
/// identity equality, an ordinary `instanceof`, BigInt order, and the truth of a Number
/// operator's result.
/// Out of line, so the comparison handlers keep their Number path's shape.
#[cold]
#[inline(never)]
fn lane_relation_other<H: Host>(operator: u32, left: Value, right: Value) -> Option<bool> {
    let vm = unsafe { vm(lane_context::<H>()) };
    // A nullish value is unequal to every Number under both loose and strict equality.
    // The Number/nullish pair cannot invoke conversion hooks or `document.all`; keep this
    // check in the shared cold fallback so it does not enlarge each hot comparison handler.
    if operator <= STRICT_INEQUALITY_OPERATOR
        && ((left.is_null() || left.is_undefined()) && right.as_number().is_some()
            || (right.is_null() || right.is_undefined()) && left.as_number().is_some())
    {
        return Some(matches!(operator, 1 | STRICT_INEQUALITY_OPERATOR));
    }
    // An ordering operator (`<`, `<=`, `>`, `>=`) is decided by its operand pair alone: the
    // membership, prototype and identity tests below never answer it.
    if super::operations::NumberRelation::from_operator(operator).is_some() {
        return vm.string_relation(operator, left, right)
            .or_else(|| vm.bigint_relation(operator, left, right))
            .or_else(|| vm.primitive_comparison(operator, left, right))
            .or_else(|| vm.number_binary(operator, left, right)?.truthiness());
    }
    vm.instanceof_truthy(operator, left, right)
        .or_else(|| vm.plain_in(operator, left, right))
        .or_else(|| vm.identity_equality(operator, left, right))
        .or_else(|| vm.string_relation(operator, left, right))
        // A test of an arithmetic or bitwise result (`if (flags & MASK)`): the Number
        // operator's value, whose ToBoolean runs no guest code.
        .or_else(|| vm.bigint_relation(operator, left, right))
        // The remaining primitive pairs, whose conversions are pure: `undefined > 5`,
        // `flag == 1`, `"3" == 3`.
        .or_else(|| vm.primitive_comparison(operator, left, right))
        .or_else(|| vm.number_binary(operator, left, right)?.truthiness())
}

/// A taken jump. Backward jumps, the only ones that close a loop, are
/// safepoints: they leave the lane when a collection is due; forward jumps
/// dispatch directly. Every jump's direction is fixed when the view is
/// derived. Leaving hands the whole instruction to the general path, so
/// `commit`, the register write the instruction makes before its jump,
/// applies only when the lane takes the jump itself.
#[inline(always)]
fn lane_jump<H: Host>(
    r: Registers,
    ip: Ip,
    backward: bool,
    view: Carried,
    commit: Option<(u16, Value)>,
) -> Resumed {
    let jump = unsafe { (*ip).jump() };
    // SAFETY: the view records the distance to a validated jump target.
    let target = unsafe { ip.byte_offset(jump) };
    if backward && fuel_out() {
        return Resumed::Exit(match commit {
            None => lane_safepoint::<H>(ip, target, view.acc),
            Some((register, value)) => lane_safepoint_writing::<H>(r, ip, target, view.acc, register, value),
        });
    }
    if let Some((register, value)) = commit {
        r.set(register, value);
    }
    Resumed::At(r, target, view)
}

/// A backward jump whose fuel ran out (`script_fuel_out`): its safepoint, as `lane_jump`
/// takes it, for the handlers that fuse the jump with its target's records.
#[inline(always)]
fn lane_jump_safepoint<H: Host>(ip: Ip, view: Carried) -> Resumed {
    // SAFETY: the view records the distance to a validated jump target.
    let target = unsafe { ip.byte_offset((*ip).jump()) };
    Resumed::Exit(lane_safepoint::<H>(ip, target, view.acc))
}

/// Count one backward jump of a crediting run (`LaneContext::backedges_left`); at the budget's
/// end, credit the running Wasm function with one interpreter entry for the loop work
/// (`ProgramStore::note_wasm_tier_backedges`) and refill it. A function entered once and
/// looping hot (JetStream's tsf and zlib) then promotes at its next entry, as one called often
/// does.
fn lane_count_backedge<H: Host>(cx: *mut LaneContext<H>) {
    // SAFETY: called from `lane_safepoint` with the run's context.
    let Some(left) = (unsafe { (*cx).backedges_left }) else {
        return;
    };
    if let Some(left) = left.checked_sub(1) {
        unsafe { (*cx).backedges_left = Some(left) };
        return;
    }
    let machine = unsafe { vm(cx) };
    let program = unsafe { (*cx).program };
    let function = machine
        .lane_stack
        .activations
        .last()
        .map_or_else(|| machine.frames[unsafe { (*cx).frame() }].function, |activation| activation.function);
    machine.programs.note_wasm_tier_backedges(program, function);
    unsafe { (*cx).backedges_left = Some(machine.programs.tiers().wasm.backedges_per_entry) };
}

script_handler! {
    /// A loop's backward jump whose target is its head's forward `null`/`undefined` test
    /// (`lane_jump_nullish_false`, `specialize_nullish_back_edges`), the `while (p != null)`
    /// of a list walk: the safepoint and the test as one dispatch. A heap value other than a
    /// record runs the test's own record.
    fn lane_jump_back_nullish<NEGATED: bool, NULLISH: u16>(cx, r, ip, i, view) {
        // SAFETY: the view records the distance to a validated jump target, the test record
        // `specialize_nullish_back_edges` matched. Computed before the fuel test, so its
        // branch reads the decrement's own flags.
        let test_ip = unsafe { ip.byte_offset(i.jump()) };
        if script_fuel_out(cx) {
            resume!(cx, lane_jump_safepoint::<H>(ip, Carried::script_in(cx, view)))
        }
        let value = r.get(unsafe { (*test_ip).b });
        let equal = match NULLISH {
            NULLISH_NULL => value == Value::NULL,
            NULLISH_UNDEFINED => value == Value::UNDEFINED,
            _ if value.is_heap() => {
                if !value.is_record() {
                    next!(cx, r, test_ip, Carried::script_in(cx, view))
                }
                false
            }
            _ => value.is_null() || value.is_undefined(),
        };
        if equal == NEGATED {
            resume!(cx, lane_jump::<H>(r, test_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(test_ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A loop's backward jump whose target is its head's integer update, an optional copy of
    /// the update's result and a test of it against a small constant
    /// (`specialize_update_back_edges`), the `while (--n >= 0)` of compiled loops: the
    /// safepoint, the update, the copy and the test as one dispatch. An update other than an
    /// integer's runs the update's own record, a test of anything else the test's.
    fn lane_jump_back_update_small<DECREMENT: bool, MOVE: bool, OP: u32>(cx, r, ip, i, view) {
        // SAFETY: the view records the distance to a validated jump target, the update record
        // `specialize_update_back_edges` matched, which the copy and the test follow. Computed
        // before the fuel test, so its branch reads the decrement's own flags.
        let update_ip = unsafe { ip.byte_offset(i.jump()) };
        if script_fuel_out(cx) {
            resume!(cx, lane_jump_safepoint::<H>(ip, Carried::script_in(cx, view)))
        }
        let update = unsafe { &*update_ip };
        let Some(value) = super::dispatch::integer_increment(r.get(update.b), DECREMENT) else {
            next!(cx, r, update_ip, Carried::script_in(cx, view))
        };
        r.set(update.a, value);
        let mut test_ip = following(update_ip);
        if MOVE {
            let copy = unsafe { &*test_ip };
            r.set(copy.a, r.get(copy.b));
            test_ip = following(test_ip);
        }
        let test = unsafe { &*test_ip };
        let right = lane_small_constant::<H, false>(cx, test);
        let Some(holds) = super::operations::integer_relation(relation_operator::<OP>(test), r.get(test.b), right) else {
            next!(cx, r, test_ip, Carried::script_in(cx, view))
        };
        if !holds {
            resume!(cx, lane_jump::<H>(r, test_ip, false, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(test_ip), Carried::script_in(cx, view))
    }
}

lane_handler! {
    fn lane_jump_always<BACKWARD: bool>(cx, r, ip, i, view) {
        match staged_jump(r, view) {
            crate::staged::Edge::Target => resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, None)),
            crate::staged::Edge::Following => unreachable!("an unconditional jump takes its target"),
        }
    }
}

script_handler! {
    /// A loop's backward jump in compiled execution (`LoopSite`): the jump's safepoint, then
    /// the loop's native code once the jump is hot and the region compiled. Native code
    /// resumes the lane where control leaves the region, or leaves to the general path at an
    /// instruction outside its subset; a run its entry guards decline takes the jump.
    fn lane_loop_jump<>(cx, r, ip, i, view) {
        let site = i.loop_site();
        if site.diagnostics {
            site.lane_backedge_count
                .set(site.lane_backedge_count.get().saturating_add(1));
        }
        // SAFETY: the site records the distance to a validated jump target.
        let header = unsafe { ip.byte_offset(site.jump) };
        // SAFETY: the region carries its validated header and latch PCs, and
        // every instruction record remains contiguous in this lane view.
        let at = |pc: u32| unsafe { header.offset(pc as isize - site.header as isize) };
        if script_fuel_out(cx) {
            return lane_safepoint::<H>(ip, header, Slot::unset());
        }
        if site.interprets() {
            next!(cx, r, header, Carried::script_in(cx, view))
        }
        // A site backing off after declined entries runs the header as a declined entry does
        // (`LoopSite::note_decline`).
        if site.skips_entry() {
            lane_at_header!(cx, r, header, site)
        }
        // The header rule (`lane_loop_enter_body`): a ready body first, then the region.
        if let Some(attempt) = loop_body::lane_loop_enter_body::<H>(cx, r, ip, site) {
            lane_attempt!(cx, r, attempt);
        }
        // A loop whose body is still to come keeps its backward jump, which a loop no region
        // runs would otherwise retire before the body is planned.
        if unsafe { vm(cx) }.programs.js_jit_lane_methods_enabled() && site.body.borrow().pending() && site.region.get().is_none() {
            next!(cx, r, header, Carried::script_in(cx, view))
        }
        // A loop no region runs takes its plain jump from now on.
        if site.promotion_only {
            lane_loop_retire::<H>(cx, ip, site);
            next!(cx, r, header, Carried::script_in(cx, view))
        }
        if site.analysis_failure.is_some_and(|failure| !failure.is_call_boundary()) {
            lane_loop_retire::<H>(cx, ip, site);
            next!(cx, r, header, Carried::script_in(cx, view))
        }
        if !site.may_run_natively(unsafe { vm(cx) }.heap.memory_policy()) {
            lane_loop_retire::<H>(cx, ip, site);
            next!(cx, r, header, Carried::script_in(cx, view))
        }
        let region = match site.region.get() {
            Some(region) => region,
            // The calls do not run inlined: the loop leaves at them, as at any other call.
            None => match lane_inlining_region(cx, r, site).or_else(|| {
                let _ = site.inline_region.set(None);
                loop_tier::lane_method_call_region(cx, site)
            }) {
                Some(region) => site.region.get_or_init(|| region),
                // A call no region runs (a native's, a callee the inliner cannot take) is a
                // loop body's: the body planner inlines what it knows (`native_calls`) and
                // starts at the header, so the loop runs natively without a function entry.
                None if loop_body::offer_body(cx, r, site) => next!(cx, r, header, Carried::script_in(cx, view)),
                None => {
                    site.entering.set(false);
                    lane_loop_retire::<H>(cx, ip, site);
                    next!(cx, r, header, Carried::script_in(cx, view))
                }
            },
        };
        let region = if !site.call_boundary_pcs.is_empty() && region.inlining.is_none() {
            site.inline_region.get_or_init(|| lane_inlining_region(cx, r, site).map(Box::new)).as_deref().unwrap_or(region)
        } else { region };
        match lane_loop_native::<H>(cx, r, ip, header, site, region) {
            LoopAttempt::Declined => lane_at_header!(cx, r, header, site),
            LoopAttempt::At(next) => next!(cx, r, next, Carried::script_in(cx, view)),
            LoopAttempt::Leave(next) => next,
            LoopAttempt::Resumed(resumed) => resume!(cx, resumed),
            LoopAttempt::Carry(registers, next, carried) => next!(cx, registers, next, carried),
        }
    }
}

/// The header record's own handler at `header`, as the interpreter runs it: the one `site`
/// holds while it holds the record (`lane_loop_header`), which the backward jump thus does
/// not try again.
macro_rules! lane_at_header {
    ($cx:expr, $r:expr, $header:expr, $site:expr) => {{
        let held = $site.header_handler.get();
        if held.is_null() || held == RETIRED_HEADER {
            next!($cx, $r, $header, Carried::script($cx))
        }
        // SAFETY: the site holds the record's handler, which has the shared signature.
        let handler: Handler = unsafe { std::mem::transmute::<*const (), Handler>(held) };
        sibling!(handler, $r, $header, Carried::script($cx))
    }};
}
use lane_at_header;

/// Continues the lane as a loop site's attempt says, or falls through where it declined.
macro_rules! lane_attempt {
    ($cx:expr, $r:expr, $attempt:expr) => {
        match $attempt {
            LoopAttempt::Declined => {}
            LoopAttempt::At(next) => next!($cx, $r, next, Carried::script($cx)),
            LoopAttempt::Leave(next) => return next,
            LoopAttempt::Resumed(resumed) => resume!($cx, resumed),
            LoopAttempt::Carry(registers, next, carried) => next!($cx, registers, next, carried),
        }
    };
}
use lane_attempt;

/// What a loop site's native attempt leaves the lane to do.
enum LoopAttempt {
    /// Nothing ran natively: the header record runs as the interpreter's.
    Declined,
    /// Continue at this record.
    At(Ip),
    /// Return this from the handler: an exit, or a safepoint's continuation.
    Leave(Ip),
    /// Continue in the activation this completion resumes.
    Resumed(Resumed),
    /// Continue at this record of these registers with this carried state.
    Carry(Registers, Ip, Carried),
}

/// `lane_loop_native`'s entry and run of `region` into `entry`: how it continues, or `None`
/// where its code is awaited or its entry record cannot be built (the site notes the decline).
#[inline(always)]
fn lane_loop_run_native<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    site: &LoopSite,
    region: &super::compiled::LoopRegion,
    entry: &mut super::compiled::LoopEntry,
) -> Option<LoopContinuation> {
    if site.tier.borrow_mut().awaits_code(unsafe { vm(cx) }, site) {
        return None;
    }
    let Some(views) = lane_loop_entry(cx, r, region, entry) else {
        site.note_decline();
        return None;
    };
    // The tier's state is borrowed only here, so the dispatch after it holds no borrow.
    let continuation = lane_loop_run(cx, r, site, region, entry, views, site.header);
    count_continuation(cx, &continuation);
    if matches!(continuation, LoopContinuation::Jump) { site.note_decline(); }
    Some(continuation)
}

/// Runs `site`'s region on `r` from its `header` record, reached at `record` (the backward
/// jump, or the header itself): the entry guards, then native code, which resumes the lane
/// where control leaves the region or leaves to the general path. Once the region has code,
/// the site holds its header record, so a loop entered from outside runs natively from its
/// first iteration.
#[inline(always)]
fn lane_loop_native<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    record: Ip,
    header: Ip,
    site: &LoopSite,
    region: &super::compiled::LoopRegion,
) -> LoopAttempt {
    // SAFETY: the region carries its validated header and latch PCs, and every instruction
    // record remains contiguous in this lane view.
    let at = |pc: u32| unsafe { header.offset(pc as isize - site.header as isize) };
    if site.skips_entry() { return LoopAttempt::Declined; }
    // The record is filled where it lives, so its words are neither cleared nor copied.
    let mut entry = super::compiled::LoopEntry::new();
    let Some(continuation) = lane_loop_run_native(cx, r, site, region, &mut entry) else { return LoopAttempt::Declined };
    lane_loop_hold_header::<H>(header, site);
    match continuation {
        LoopContinuation::Jump | LoopContinuation::Compiling => LoopAttempt::Declined,
        LoopContinuation::Resume(pc) => LoopAttempt::At(at(pc)),
        LoopContinuation::Exit(pc) if loop_body::left_for_tier_up(cx, site, pc) => LoopAttempt::At(at(site.header)),
        LoopContinuation::Exit(pc) => { count_arithmetic_leave(cx, site, pc, region.header..=region.backedge); LoopAttempt::Leave(exit(at(pc))) }
        LoopContinuation::Inlined { frame, pc } => { let frame = region.inlining.as_ref().expect("an inlining region").frames[frame];
            LoopAttempt::Leave(exit(lane_inlined_activation(cx, r, region, &entry, frame, at(frame.call), pc))) }
        LoopContinuation::Recovered(resumed) => loop_body::loop_attempt(cx, record, resumed),
        LoopContinuation::Safepoint => LoopAttempt::Leave(lane_safepoint::<H>(record, header, Slot::unset())),
        // SAFETY: the call set the callee's activation and its resume record before the body
        // left (`lane_body_activate`), so the run leaves at a record of that view.
        LoopContinuation::Callee => LoopAttempt::Leave(exit(unsafe { (*cx).callee_resume })),
        LoopContinuation::Completed(pc, value) =>
            LoopAttempt::Resumed(lane_return_value_general::<H>(cx, at(pc), value)),
        LoopContinuation::Threw(pc) => LoopAttempt::Leave(lane_raised_exit(cx, at(pc))),
    }
}

/// Counts a leave at `pc` (`LoopTier::left_at`) where it is a Number operator, whose int32
/// speculation a compilation can drop, an element read, whose observed type it can drop, an
/// element store, whose append helper it can compile, a field store, whose VM store it can call
/// (`Lowering::store_leaves`), or a capture read, whose root-held binding
/// it can read by helper; a leave at any other guard (a shape, say) widens nothing.
#[cold]
fn count_arithmetic_leave<H: Host>(cx: *mut LaneContext<H>, site: &LoopSite, pc: u32, region: std::ops::RangeInclusive<u32>) {
    if !region.contains(&pc) { return; }
    // SAFETY: the lane's VM is live, and nothing borrows it across the read.
    let machine = unsafe { vm(cx) };
    let counted = machine.programs.get(machine.active_program).as_deref().and_then(|program| {
        let body = program.function(site.function() as usize);
        body.code.get(pc as usize).and_then(|packed| {
            let op = body.widened(*packed).op();
            super::compiled::base_region::leave(site.function(), pc, op);
            (op.js_denotation() == crate::bytecode::JsDenotation::NumericBinary || op.is_get_index() || op.stores_element()
                || op.is_field_store() || crate::staged::miss(op) == crate::staged::Miss::WalkScopes).then(|| (op.is_get_index(), op.is_field_store()))
        })
    });
    match counted {
        Some((_, true)) => site.tier.borrow_mut().left_store(site.tiers, pc as usize),
        Some((read, false)) => site.tier.borrow_mut().left_at(site.tiers, pc as usize, read),
        None => {}
    }
}

/// Gives `site` its `header` record (`LoopSite::hookable`) once its region has code: the
/// record runs `lane_loop_header`, and the site keeps the record's own handler.
fn lane_loop_hold_header<H: Host>(header: Ip, site: &LoopSite) {
    // A retired site (`RETIRED_HEADER`) never holds its header again: its jump record is a plain
    // jump and the header's `call_link` a field hint, so `lane_header_site` would read garbage.
    if !site.hookable || !site.header_handler.get().is_null() || !site.tier.borrow().is_published() {
        return;
    }
    // SAFETY: as `requicken`: the record lives in an `UnsafeCell` of the running view.
    unsafe {
        site.header_handler.set((*header).handler);
        (*header.cast_mut()).handler = lane_loop_header::<H> as Handler as *const ();
    }
}

/// The site whose header record is at `ip` (`LoopSite::hookable`): the header's `call_link`
/// is the distance, in records, to the site's backward jump, whose operand is the site
/// (`install_loop_sites`). A held header's jump still holds it: retiring the site gives the
/// header its own handler back first (`lane_loop_retire`).
///
/// # Safety
/// `ip` is a held header record of a live view.
#[inline(always)]
unsafe fn lane_header_site(ip: Ip) -> *const LoopSite {
    // SAFETY: the jump lies `call_link` records past its header in the same view.
    unsafe { (*ip.add(usize::from((*ip).call_link.get()))).loop_site() }
}

script_handler! {
    /// A loop's header record while its site holds it (`lane_loop_hold_header`): arriving at
    /// the header enters the loop's native code as its backward jump does, and otherwise
    /// runs the record's own handler.
    fn lane_loop_header<>(cx, r, ip, i, view) {
        // SAFETY: a record runs this handler only while a site holds it.
        let site = unsafe { &*lane_header_site(ip) };
        if !script_below_floor(cx)
            && let Some(attempt) = loop_body::lane_loop_enter_body::<H>(cx, r, ip, site)
        {
            lane_attempt!(cx, r, attempt);
        }
        if !script_below_floor(cx)
            && site.enters()
            && let Some(region) = site.active_region()
        {
            match lane_loop_native::<H>(cx, r, ip, ip, site, region) {
                LoopAttempt::Declined => {}
                LoopAttempt::At(next) => next!(cx, r, next, Carried::script_in(cx, view)),
                LoopAttempt::Leave(next) => return next,
                LoopAttempt::Resumed(resumed) => resume!(cx, resumed),
                LoopAttempt::Carry(registers, next, carried) => next!(cx, registers, next, carried),
            }
        }
        lane_at_header!(cx, r, ip, site)
    }
}


/// Counts an entry of `function`'s lane activation toward its lane body (`own`), or, `now`,
/// specializes it at once, from the targets and callees the program's views hold now. Whether the body
/// is still warming or specialized (`LaneView::specialize_lane_body`).
fn lane_specialize<H: Host>(cx: *mut LaneContext<H>, own: &LaneView, function: u32, now: bool, parameters: &[Value]) -> bool {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let diagnostics = vm.programs.js_jit_diagnostics_enabled();
    // The entry activation's array parameters, sampled: a lane body's loops read them typed (`observed_reads`).
    let arrays = loop_tier::sampled_arrays(vm, parameters.iter().copied());
    let specialize = |work: super::compiled::LaneBodyWork| {
        let work = match work {
            super::compiled::LaneBodyWork::Start { generic, shrinks, observed, looped, called, caller, .. } =>
                super::compiled::LaneBodyWork::Start { generic, shrinks, observed, looped, called, caller, arrays: &arrays },
            poll => poll,
        };
        let direct = |vm: &Vm<H>| code.function_get(function as usize).map(|body| lane_direct_callees(vm, own, function, body)).unwrap_or_default();
        // `--b-jit` stitches its body at once: it calls the callees its sites recorded by their entries and waits for none.
        if crate::jit_mode::base_only() {
            let super::compiled::LaneBodyWork::Start { generic, .. } = work else { unreachable!("a stencil body never compiles in the background") };
            return vm.base_body_work(code, function, generic, parameters, own, &direct);
        }
        if matches!(work, super::compiled::LaneBodyWork::Start { .. })
            && let Some(outcome) = lane_body_tier::start_gate(vm, own, code.function_get(function as usize))
        {
            return outcome;
        }
        let outcome = vm.lane_body_work(code, function, &|function, pc| lane_unit_targets(cx, function, pc), &|function, header| lane_unit_trips(cx, function, header), &|callee| lane_callee_captures(cx, callee), &direct, work, None);
        if diagnostics && let super::compiled::LaneBodyOutcome::Published(method) = &outcome {
            if let Some(method) = method.lease() { own.tier().body_stats.compiled(function, &method.inlined); }
        }
        outcome
    };
    if now {
        own.specialize_lane_body_now(lane_body_entry::<H>, specialize);
        own.lane_body().is_some()
    } else {
        own.specialize_lane_body(lane_body_entry::<H>, specialize)
    }
}

/// Gives a loop site that will not enter native code again its plain backward jump back,
/// so each iteration takes the jump without the site's checks.
fn lane_loop_retire<H: Host>(cx: *mut LaneContext<H>, ip: Ip, site: &LoopSite) {
    // A hot loop no region runs makes its function worth a body past the entry warm-up: its
    // calls have run, so their sites have linked, and its next entry runs the loop natively.
    // The site stays, and asks again a threshold of jumps on, while that body warms: the
    // function's entries may be too few to wait for its callees' bodies or look for its code.
    // SAFETY: the program's views outlive the lane run.
    if unsafe { vm(cx) }.programs.js_jit_lane_methods_enabled()
        && let Some(own) = unsafe { &*(*cx).views }.get(site.function as usize).and_then(super::program_store::derived_lane_view)
    {
        lane_specialize(cx, own, site.function, true, &[]);
        if own.warming() { return site.taken.set(0); }
    }
    // SAFETY: as `requicken`: the record lives in an `UnsafeCell` of the running view, and
    // the jump reads its distance from the operand, which the site kept (`LoopSite::jump`).
    // A header record the site holds gets its own handler back.
    let header = unsafe { ip.byte_offset(site.jump) };
    lane_loop_release_header(header, site);
    // A run of this site still on the stack (a native attempt that retired it) must not hold
    // the header again on its way out (`lane_loop_hold_header`).
    site.header_handler.set(RETIRED_HEADER);
    // No site holds the header from now on, so its record, which linked this site alone, takes
    // field hints again (`holds_loop_site`).
    if site.hookable { unsafe { (*header).call_link.set(NO_CALL_LINK) }; }
    unsafe { (*ip.cast_mut()).operand = LaneOperand { jump: site.jump }; }
    requicken::<H>(ip, lane_jump_always::<H, true>);
    // The site kept the update before the jump from fusing with it (`install_loop_sites`
    // runs before `specialize_update_jumps`): the plain jump takes the loader's fusion now.
    if site.backedge > site.header {
        // SAFETY: the record before the backedge is the loop body's, in the same view as the jump and the header;
        // the record after the header is read only for a fused load, whose test record it is.
        let update = unsafe { ip.sub(1) };
        if let Some(fused) = update_fusion::<H>(unsafe { &*update }, unsafe { &*ip }, |offset| Some(unsafe { &*header.add(offset) })) {
            requicken::<H>(update, fused);
        }
    }
}

/// Restore the semantic header at the event that replaces its native owner.
/// `LoopSite::header_handler` of a retired site (`lane_loop_retire`): no record, so the site
/// never holds its header again.
const RETIRED_HEADER: *const () = std::ptr::without_provenance(1);

fn lane_loop_release_header(header: Ip, site: &LoopSite) {
    let held = site.header_handler.replace(std::ptr::null());
    if !held.is_null() && held != RETIRED_HEADER {
        // SAFETY: the validated site owns this record on the running view's thread.
        unsafe { (*header.cast_mut()).handler = held; }
    }
}

/// Where the lane goes after a loop site's native attempt.
enum LoopContinuation {
    /// Take the backward jump in the interpreter.
    Jump,
    Resume(u32),
    /// The general path executes the instruction at this PC.
    Exit(u32),
    /// The general path executes callee PC `pc` of inlined frame `frame`, in the activation
    /// its call makes (`LaneExit::Inlined`).
    Inlined { frame: usize, pc: u32 },
    /// Native code of a stitched region left inside an inlined callee, and the lane recovered the
    /// activations around it (`lane_inlined_continuation`).
    Recovered(LaneBodyLeft),
    /// The backward jump's safepoint ends the execution termination stopped.
    Safepoint,
    /// The region's code compiles: take the jump, which declines nothing.
    Compiling,
    /// The region completed its activation with this value at this record.
    Completed(u32, Value),
    /// The region raised the exception in `Vm::lane_raised` at this record: unwind from it.
    Threw(u32),
    /// A call activated the callee's lane body: leave the run in that activation.
    Callee,
}

/// Counts what a loop run came to: in the VM's tier events, and under `QUENCH_TRACE=js-jit` in the report's.
fn count_continuation<H: Host>(cx: *mut LaneContext<H>, continuation: &LoopContinuation) {
    use super::compiled::base_region::{count, Event as Region};
    let (region, tier) = match continuation {
        LoopContinuation::Jump | LoopContinuation::Compiling => (Region::Declined, None),
        LoopContinuation::Exit(_) | LoopContinuation::Inlined { .. } | LoopContinuation::Recovered(_) | LoopContinuation::Safepoint | LoopContinuation::Callee | LoopContinuation::Threw(_) => (Region::Left, Some(Event::OsrLeft)),
        LoopContinuation::Resume(_) | LoopContinuation::Completed(..) => (Region::Entered, Some(Event::OsrEntered)),
    };
    count(region);
    if let Some(event) = tier { unsafe { vm(cx) }.programs.tier_events().record(event); }
}

/// Compiles `site`'s region if it has no current code, for the element `views` its entry
/// proved, then runs it on `r` with `entry`. A representation an outcome shows wrong is
/// widened, and the code dropped for the next compilation.
#[inline(never)]
fn lane_loop_run<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    site: &LoopSite,
    region: &super::compiled::LoopRegion,
    entry: &mut super::compiled::LoopEntry,
    views: super::compiled::ElementViews,
    from: u32,
) -> LoopContinuation {
    use super::compiled::{LaneExit, RegionRun};
    let mut tier = site.tier.borrow_mut();
    if !tier.select(site.tiers, views) {
        return LoopContinuation::Jump;
    }
    if !tier.is_published() {
        // SAFETY: the lane's VM is live, and nothing borrows it across the read.
        if !tier.may_run(site.tiers, unsafe { vm(cx) }.heap.memory_policy()) {
            return LoopContinuation::Jump;
        }
        let number_arrays = loop_tier::number_arrays(unsafe { vm(cx) }, r, region);
        let int_entries = loop_tier::int_entries(r, region);
        let typed_captures = loop_tier::typed_capture_slots(cx);
        let int_captures = loop_tier::int_capture_slots(cx);
        lane_loop_compile(cx, r, site, region, &mut tier, &number_arrays, &int_entries, &typed_captures, &int_captures);
        if !tier.is_published() {
            return LoopContinuation::Compiling;
        }
    }
    let publication = Rc::clone(tier.code.as_ref().expect("compiled above"));
    let code = publication.lease().expect("compiled above");
    drop(tier);
    // The native field probe may access the VM only through its synchronous, cache-only
    // callback. Pass raw pointers so no Rust borrow of the VM overlaps that callback.
    let (machine, program, interrupt) = unsafe {
        let context = &*cx;
        (
            context.vm,
            context.program,
            std::ptr::addr_of!((*context.vm).execution_interrupt),
        )
    };
    // SAFETY: `r` and `machine` are the running lane activation's storage and VM; the
    // callback executes no guest code, allocates nothing, and retains no VM references.
    let run = unsafe { lane_region_run::<H>(cx, r, entry, (&*code, region), (site.function, from), (machine, program, interrupt)) };
    if site.diagnostics {
        lane_loop_diagnose(cx, r, site, region, run, program);
    }
    let RegionRun { exit, nested } = run;
    if exit.entered_nothing() {
        // An entry guard missed: registers are untouched, so the backward jump runs in the interpreter.
        site.tier.borrow_mut().missed_entry(site.tiers);
        return LoopContinuation::Jump;
    }
    if matches!(exit, LaneExit::Terminated) {
        return LoopContinuation::Safepoint;
    }
    // A run pays for its entry with the iterations it completed, wherever it leaves.
    site.note_run(entry.backedge_count());
    if nested {
        return lane_region_left(cx, r, site.function, exit);
    }
    match exit {
        LaneExit::At(pc) if region.holds_exit(exit) => LoopContinuation::Exit(pc as u32),
        LaneExit::At(pc) => LoopContinuation::Resume(pc as u32),
        LaneExit::Inlined { frame, pc } => lane_inlined_continuation(cx, r, site, (region, &code), (frame, pc)),
        // The call made the callee's activation, whose own records the lane runs next.
        LaneExit::Callee => LoopContinuation::Callee,
        LaneExit::Returned { pc, value } => LoopContinuation::Completed(pc as u32, value),
        LaneExit::Threw { pc } => LoopContinuation::Threw(pc as u32),
        LaneExit::Entry | LaneExit::Stub | LaneExit::Terminated => unreachable!("handled before the run paid"),
    }
}

/// The diagnostics of a loop site's native attempt that ended in `run`, under its `site.diagnostics`.
fn lane_loop_diagnose<H: Host>(cx: *mut LaneContext<H>, r: Registers, site: &LoopSite, region: &super::compiled::LoopRegion, run: super::compiled::RegionRun, program: ProgramId) {
    use super::compiled::LaneExit;
    let bump = |count: &std::cell::Cell<u64>| count.set(count.get().saturating_add(1));
    bump(&site.native_entry_attempts);
    if run.nested {
        bump(&site.native_region_runs);
        return;
    }
    match run.exit {
        LaneExit::Entry | LaneExit::Stub => {
            if crate::trace::Channel::OsrReject.on() {
                eprintln!("QUENCH_JS_JIT_OSR_ENTRY_MISS function={} header={}", site.function, site.header);
            }
            bump(&site.entry_guard_misses);
        }
        LaneExit::Terminated => {}
        LaneExit::Inlined { .. } => {
            bump(&site.native_region_runs);
            bump(&site.native_exits);
        }
        // A guard's exit inside the loop; the poll's leave for a published body is a handover, not one.
        LaneExit::At(pc) if region.holds_exit(run.exit) && !loop_body::left_for_tier_up(cx, site, pc as u32) => {
            bump(&site.native_region_runs);
            bump(&site.native_exits);
            lane_loop_trace_exit(cx, r, site, region, program, pc as u32);
        }
        _ => bump(&site.native_region_runs),
    }
}

/// Attributes a guard exit at `pc` to its recovery PC before the lane resumes, under the opt-in
/// OSR trace; ordinary execution keeps no extra table or per-site allocation.
fn lane_loop_trace_exit<H: Host>(cx: *mut LaneContext<H>, r: Registers, site: &LoopSite, region: &super::compiled::LoopRegion, program: ProgramId, pc: u32) {
    if crate::trace::Channel::OsrReject.on() {
        eprintln!(
            "QUENCH_JS_JIT_OSR_EXIT program={} function={} header={} pc={pc}",
            program.raw(), site.function, site.header,
        );
        // Read recovered operands only for a non-inlined activation. These
        // getters neither coerce a guest value nor allocate guest storage.
        // Raw state distinguishes index/append/capacity guards without
        // changing native exits or inventing a second guard policy.
        if region.inlining.is_none() {
            // SAFETY: the lane's program and VM outlive this synchronous trace;
            // native execution has returned and restored the canonical registers.
            let body = unsafe { &*(*cx).code }.function_get(site.function as usize);
            if let Some((body, packed)) = body.and_then(|body| body.code.get(pc as usize).map(|packed| (body, *packed))) {
                let instruction = body.widened(packed);
                if instruction.op().is_set_index() {
                    let key = r.get(instruction.register_c());
                    let base = r.get(instruction.register_b());
                    if let Some(array) = unsafe { vm(cx) }.heap.record_array(base) {
                        eprintln!(
                            "QUENCH_JS_JIT_OSR_SET_INDEX_EXIT program={} function={} header={} pc={pc} key_bits={:016x} key_number={:?} length={} capacity={}",
                            program.raw(), site.function, site.header,
                            key.to_bits(), key.as_number(),
                            array.elements().len(), array.elements().capacity(),
                        );
                    }
                }
            }
        }
    }
}

/// Runs `code`, the region of the loop of `function` over the activation with registers `r`, from
/// its header or the record `from`, where the lane admits the run (`lane_region_admits`); a run it
/// does not admit enters nothing, as an entry guard that missed.
///
/// # Safety
/// As `CompiledOsrRegion::run`: `machine` and `interrupt` belong to the running lane.
unsafe fn lane_region_run<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    entry: &mut super::compiled::LoopEntry,
    (code, region): (&super::compiled::CompiledOsrRegion, &super::compiled::LoopRegion),
    (function, from): (u32, u32),
    (machine, program, interrupt): (*mut Vm<H>, ProgramId, *const crate::execution_interrupt::ExecutionInterrupt),
) -> super::compiled::RegionRun {
    use super::compiled::{LaneExit, RegionRun};
    // A job's frameless lane (a generator step) has no frame for the region's activation.
    if code.needs_frame() && !unsafe { &*cx }.has_frame() {
        return RegionRun::own(LaneExit::Entry);
    }
    if !lane_region_admits(cx, code) {
        // A run the lane lacks room for grows it and leaves at the loop's header, so the next entry admits.
        let grown = lane_frame_holds_window(cx, &code.calls) && lane_room_prepare(cx, code.calls.recovery_space());
        return RegionRun::own(if grown { LaneExit::At(region.header as usize) } else { LaneExit::Entry });
    }
    // SAFETY: the caller's contract.
    unsafe { code.run::<H>(r.0, entry, region, machine, program, function, (*cx).frame(), interrupt, (cx as usize, lane_direct_calls(cx)), from) }
}

/// Whether a run of `code`, the region of the loop of `function` the lane is in, may start: the lane
/// has the room to make the activations of the calls it inlines should it leave inside one
/// (`lane_room_admits`), and the activation keeps its locals apart from the window past its
/// registers, which the registers of those callees occupy (`CompiledOsrRegion::run_lane`).
#[inline(always)]
fn lane_region_admits<H: Host>(cx: *mut LaneContext<H>, code: &super::compiled::CompiledOsrRegion) -> bool {
    let room = code.calls.recovery_space();
    room.activations == 0 || (lane_room_admits(cx, room, NO_PENDING_ACTIVATIONS) && lane_frame_holds_window(cx, &code.calls))
}

/// Whether the running activation's register storage holds the windows of the callees `calls` inlines,
/// which start past the function's environment window (`base_region::function::inline_base`): a lane
/// activation's value stack has the room `lane_room_admits` proved (`CallCode::recovery_space` covers
/// the reach); a VM frame's register file, sized to its own words, needs that much capacity past its
/// registers (`INLINED_WINDOW_ROOM`, which an environment window reserves).
#[inline(always)]
fn lane_frame_holds_window<H: Host>(cx: *mut LaneContext<H>, calls: &super::compiled::CallCode) -> bool {
    let vm = unsafe { vm(cx) };
    if vm.lane_stack.activations.last().is_some() {
        return true;
    }
    lane_frame_reaches(cx, calls.caller_registers(), calls.window())
}

/// Whether the running VM frame's register file holds `reach` words past its `registers`, where code
/// writes past them (`base_region::function::inline_base`); a lane activation's storage, at the top of
/// the value stack, is proved by its room instead (`lane_room_admits`).
#[inline(always)]
fn lane_frame_reaches<H: Host>(cx: *mut LaneContext<H>, registers: u16, reach: usize) -> bool {
    let vm = unsafe { vm(cx) };
    reach == 0 || vm.lane_stack.activations.last().is_some()
        || vm.frames.get(unsafe { (*cx).frame() }).is_some_and(|frame| frame.registers.capacity() >= usize::from(registers) + reach)
}


/// Whether the running activation keeps its locals in the window past its registers, as
/// `lane_body_locals` finds them: an environment activation does, and so does a VM frame whose
/// own storage does not cover the function.
/// # Safety
/// `context` is the running lane's context.
pub(super) unsafe fn lane_context_locals_in_window<H: Host>(context: usize) -> bool {
    let cx = context as *mut LaneContext<H>;
    let vm = unsafe { vm(cx) };
    if let Some(activation) = vm.lane_stack.activations.last() {
        return activation.script().is_some_and(|script| script.environment);
    }
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    vm.frames.get(unsafe { (*cx).frame() }).is_some_and(|frame| code.function_get(frame.function as usize)
        .is_some_and(|body| frame.locals.len() < usize::from(body.locals)))
}

/// Where the lane goes after a region of the loop of `function` left inside the callee of a call it
/// made by its entry, with `exit`: in the innermost of the native frames the call pushed
/// (`lane_frames_resumed`).
fn lane_region_left<H: Host>(cx: *mut LaneContext<H>, r: Registers, function: u32, exit: super::compiled::LaneExit) -> LoopContinuation {
    // SAFETY: the program's views outlive the lane run, and the loop's function has the view its site was made from.
    let own = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view).expect("the loop's function has its view");
    if exit == super::compiled::LaneExit::Terminated {
        // As a body's: a fault can bypass the native exit's register snapshots.
        native_frames::discard_frames(cx);
        return LoopContinuation::Safepoint;
    }
    LoopContinuation::Recovered(lane_frames_resumed(cx, r, (own, None), exit))
}

/// Where the lane goes after native code left inside inlined `frame` of `region`'s callee, at its PC
/// `pc`. An inlining region of the Cranelift tier makes the callee's activation from the entry's
/// scratch window (`lane_inlined_activation`); a stitched region's registers are in the activation's
/// register file past its own, which the lane recovers as a lane body's (`lane_body_inlined_activation`).
fn lane_inlined_continuation<H: Host>(cx: *mut LaneContext<H>, r: Registers, site: &LoopSite, (region, code): (&super::compiled::LoopRegion, &super::compiled::CompiledOsrRegion), (frame, pc): (usize, u32)) -> LoopContinuation {
    if region.inlining.is_some() {
        return LoopContinuation::Inlined { frame, pc };
    }
    // The exit is feedback as a top-level one is: the callee's instruction widens in the next plan, and is counted.
    let call = code.calls.inlined[frame];
    site.tier.borrow_mut().left_at(site.tiers, super::compiled::base_region::inlined_exit_key(call.call, pc), false);
    // SAFETY: the context's program outlives the lane run.
    if let Some(body) = unsafe { &*(*cx).code }.function_get(call.target.function as usize) {
        super::compiled::base_region::leave(call.target.function, pc, body.widened(body.code[pc as usize]).op());
    }
    // SAFETY: the context's records are the activation's, which the region ran on.
    let base = unsafe { (*cx).base };
    let (registers, resume, carried) = lane_body_inlined_activation(cx, r, base, InlinedRun::of_region(&code.calls), frame, pc);
    LoopContinuation::Recovered(LaneBodyLeft::Resume(registers, resume, carried))
}

/// The entry record of `site`'s native code from the running activation, and the element
/// views of its arrays (`loop_tier::lane_loop_arrays`), when its arrays and captures pass the
/// region's guards: each capture an initialized binding resolved without guest code by the
/// same lookup as LoadCapture (`lane_capture_value`).
#[inline(never)]
fn lane_loop_entry<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    region: &super::compiled::LoopRegion,
    entry: &mut super::compiled::LoopEntry,
) -> Option<super::compiled::ElementViews> {
    if !region.captures.is_empty() {
        let slots = capture_reads(unsafe { (*cx).registers }.capture());
        for slot in &region.captures {
            // The activation's `this`, for reads of `this` the region stores (`THIS_CAPTURE`).
            if *slot == super::compiled::THIS_CAPTURE {
                entry.push_capture(unsafe { lane_held_this(cx, r) });
                continue;
            }
            // An inlined callee's capture reads its own environment (`Inlining::callee_captures`).
            if slot & super::compiled::CALLEE_CAPTURE != 0 {
                let inlining = region.inlining.as_deref()?;
                let &(frame, callee_slot) = inlining.callee_captures.get(usize::from(slot & !super::compiled::CALLEE_CAPTURE))?;
                let callee = inlining.frames.get(frame)?.callee;
                let vm = unsafe { vm(cx) };
                // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target.
                let env = unsafe { &*vm.script_call_entry(callee)? }.env;
                // A top-level binding the global object projects is its property, which the
                // region keeps only while it stores no field (as the caller's own captures).
                let value = vm.environment_capture(env, callee_slot).or_else(|| {
                    (!region.writes_fields())
                        .then(|| vm.environment_capture_env(env, false, 0)
                            .and_then(|env| vm.plain_projected_root_binding(env, callee_slot)))
                        .flatten()
                })?;
                entry.push_capture(value);
                continue;
            }
            // SAFETY: the context's dense slots remain live until the next collection.
            // A cache miss follows the same non-effectful lookup as LoadCapture.
            let value = unsafe { crate::heap::EnvironmentSlots::read_storage(slots, *slot) }
                .or_else(|| lane_capture_value(cx, 0, *slot))
                .or_else(|| {
                    // A projected global var aliases its global object's property. Native
                    // field stores could change it after entry, invalidating this snapshot.
                    (!region.writes_fields())
                        .then(|| lane_projected_capture(cx, 0, *slot))
                        .flatten()
                })?;
            entry.push_capture(value);
        }
    }
    let vm = unsafe { vm(cx) };
    // No guest call or collection occurs in a native run, and an array literal it allocates
    // is no entry value. Field writes replace guarded own slots, and element stores change
    // no shape slot. Immutable fields keep their entry values; admitted same-receiver Number
    // writes update SSA field cells. Other possible aliases are rejected by region
    // admission. Any miss, accessor, private name or non-Number declines before native
    // effects. Nested receivers follow the earlier field's value.
    for (index, field) in region.fields.iter().enumerate() {
        // A field native code reads at its instruction (`LoopRegion::is_dynamic_field`) takes
        // its entry value only to seed its representation: a receiver it does not answer for
        // now (a null child, another shape), or a value its Number representation does not
        // hold, seeds the representation's own placeholder.
        let blind = region.seeds_without_receiver(index);
        let value = (!blind).then(|| lane_region_field(cx, r, field, |index| entry.field_value(region, index)))
            .flatten()
            .filter(|value| field.tagged || !region.is_dynamic_field(index) || value.as_number().is_some())
            .or_else(|| {
                (region.is_dynamic_field(index)
                    && (blind || vm.field_cache_entry(field.cache_site).receiver != super::NO_FIELD_RECEIVER))
                    .then(|| if field.tagged { Value::UNDEFINED } else { Value::integer(0) })
            })?;
        entry.push_field(value, field.tagged)?;
    }
    let views = loop_tier::lane_loop_arrays(vm, r, region, entry)?;
    lane_loop_field_stores(cx, r, region, entry)?;
    if region.reads_heap_natively() {
        let object_base = vm.heap.object_record_base().unwrap_or(std::ptr::null());
        let (properties_base, properties_len) = vm.heap.native_property_values();
        let array_base = vm.heap.array_record_base().unwrap_or(std::ptr::null());
        entry.push_native_heap(object_base, properties_base, properties_len, array_base);
    }
    if let Some(inlining) = &region.inlining {
        // Leaving at an inlined instruction makes its callee's activation as the call would:
        // each call must still be one the lane activates in place (`lane_inlined_activation`).
        for frame in &inlining.frames {
            lane_inlined_target(cx, r, lane_inlined_receiver(r, region, entry, frame), frame)?;
        }
    }
    Some(views)
}

/// A cached data field's value as the region's entry reads it: a hit of the field's cache
/// on its receiver, or a typed array's geometry, for no private name. `earlier` gives the value of the earlier field a
/// receiver may be (`FieldReceiver::Field`).
fn lane_region_field<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    field: &super::compiled::FieldUse,
    earlier: impl FnOnce(usize) -> Value,
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if vm.is_private_name(field.atom) { return None; }
    let receiver = match field.receiver {
        super::compiled::FieldReceiver::This => unsafe { lane_held_this(cx, r) },
        super::compiled::FieldReceiver::Register(register) => r.get(register),
        super::compiled::FieldReceiver::Capture(slot) => lane_capture_value(cx, 0, slot)?,
        super::compiled::FieldReceiver::Field(index) => earlier(index),
    };
    // The site's primary entry first, as the lane's own reads take it (`own_formed_handler`).
    if let Some(value) = vm.record_field_entry_hit(vm.field_cache_entry(field.cache_site), receiver) {
        return Some(value);
    }
    match vm.cached_field_hit(code, receiver, field.cache_site) {
        super::object::FieldCacheProbe::Hit(value) => Some(value),
        // A site of several shapes answers from its polymorphic entries, own or of the
        // immediate prototype, as the lane's polymorphic read does (`lane_get_field_polymorphic`).
        // A typed array's geometry is its intrinsic getter's answer, which only a call (a
        // detach, a resize, a redefinition) changes, and a call leaves the region.
        _ => vm.polymorphic_field_hit(code, receiver, field.cache_site)
            .or_else(|| vm.typed_array_geometry_read(receiver, field.atom))
            .or_else(|| (field.atom == vm.length_atom).then(|| vm.own_array_length(receiver).map(Value::length)
                // A string's length is its own, immutable: the region reads it at the instruction too.
                .or_else(|| vm.string_length_value(receiver))).flatten()),
    }
}

/// The call target of an inlined `frame`'s callee, when `lane_script_call` would activate it
/// in place now, binding the frame's receiver as its `this`: the target the call caches, an
/// activation of the running program with room on the lane stack.
fn lane_inlined_target<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    receiver: Value,
    frame: &super::compiled::InlineFrame,
) -> Option<*const ScriptCallTarget> {
    match frame.guard {
        super::compiled::InlineGuard::Capture(slot) => (lane_capture_value(cx, 0, slot)? == frame.callee).then_some(())?,
        super::compiled::InlineGuard::Register(register) => (r.get(register) == frame.callee).then_some(())?,
        _ => {}
    }
    let vm = unsafe { vm(cx) };
    let target_pointer = vm.script_call_entry(frame.callee)?;
    // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target.
    let target = unsafe { &*target_pointer };
    (target.entry.activates()
        && target.program() == unsafe { (*cx).program }
        && unsafe { (*cx).script_calls }
        && !vm.with_scope_entered
        && lane_activation_room(vm, target)
        && lane_call_this(vm, target, receiver).is_some_and(|bound| {
            bound == receiver || matches!(frame.guard, super::compiled::InlineGuard::Capture(_) | super::compiled::InlineGuard::Register(_))
        }))
    .then_some(target_pointer)
}

/// The receiver of an inlined `frame`'s call: the field value a register the region writes
/// holds (`LoopRegion::held_field`), else the register's.
fn lane_inlined_receiver(
    r: Registers,
    region: &super::compiled::LoopRegion,
    entry: &super::compiled::LoopEntry,
    frame: &super::compiled::InlineFrame,
) -> Value {
    match region.held_field(frame.receiver) {
        Some(index) => entry.field_value(region, index),
        None => r.get(frame.receiver),
    }
}

/// The region of `site`'s loop with its calls inlined, each callee the function the cached
/// field it is read from holds now, whose call the lane activates in place.
#[inline(never)]
fn lane_inlining_region<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    site: &LoopSite,
) -> Option<super::compiled::LoopRegion> {
    // `--b-jit` runs no inlining regions, so it does not analyze them.
    if crate::jit_mode::base_only() { return None; }
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let program = unsafe { (*cx).program };
    let (function_index, function, decoded, constants) = loop_tier::lane_loop_function(cx, code)?;
    let live = code.register_root_masks(function_index)?;
    // The callee is the last of the fields its read reads through, each read from the
    // registers and the fields before it as they are now.
    let mut resolve = |chain: &[super::compiled::FieldUse], source: super::compiled::CalleeSource| -> Option<super::compiled::InlineCallee<'_>> {
        let mut values = Vec::with_capacity(chain.len());
        for field in chain {
            let value = lane_region_field(cx, r, field, |index| values[index])?;
            values.push(value);
        }
        let callee = match source {
            super::compiled::CalleeSource::Capture(slot) => lane_capture_value(cx, 0, slot)?,
            super::compiled::CalleeSource::Register(register) => r.get(register),
            super::compiled::CalleeSource::Path => *values.last()?,
        };
        let vm = unsafe { vm(cx) };
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target.
        let target = unsafe { &*vm.script_call_entry(callee)? };
        (target.entry.activates() && target.program() == program).then_some(())?;
        let body = code.function_get(target.function as usize)?;
        Some(super::compiled::InlineCallee {
            callee,
            function: target.function,
            params: body.params,
            registers: body.registers,
            instructions: body.instructions().collect(),
            live: code.register_root_masks(target.function)?,
        })
    };
    super::compiled::analyze_inlining_osr_region(
        function,
        &decoded,
        &constants,
        &code.field_sites,
        live,
        site.header,
        site.backedge,
        &mut resolve,
    )
}

/// The record native code leaving at the inlined instruction `callee_pc` of `frame`
/// continues at: the callee's activation the call at `call` makes (`lane_push_activation`),
/// a parameter bound to a caller register that register's value, each register live at
/// `callee_pc` the value native code left in the scratch window (as a lane body's leave,
/// `lane_body_inlined_activation`), and any other `undefined`, which nothing reads before
/// writing. The entry checked the call activates in place (`lane_inlined_target`).
#[inline(never)]
fn lane_inlined_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    region: &super::compiled::LoopRegion,
    entry: &super::compiled::LoopEntry,
    frame: super::compiled::InlineFrame,
    call: Ip,
    callee_pc: u32,
) -> Ip {
    let receiver = lane_inlined_receiver(r, region, entry, &frame);
    let target = lane_inlined_target(cx, r, receiver, &frame).expect("the entry checked the inlined call");
    // SAFETY: as `Vm::script_call_entry`; `call` is the call's record in the running view.
    let (target, arguments) =
        unsafe { (&*target, ImmediateLayout::call_window_base((*call).imm())) };
    let receiver = lane_call_this(unsafe { vm(cx) }, target, receiver)
        .expect("entry checked the receiver's effect-free binding");
    let (registers, _) =
        lane_push_activation::<H, false, false>(cx, r, call, target, arguments, receiver, false);
    let inlining = region.inlining.as_ref().expect("an inlining region");
    // SAFETY: the context's program outlives the lane run.
    let live = unsafe { &*(*cx).code }.register_root_masks(frame.function)
        .expect("an inlined callee has its register roots (`lane_inlining_region`)");
    for register in 0..frame.registers {
        let bound = frame.bound.get(usize::from(register)).copied().flatten().map(|source| r.get(source));
        // SAFETY: native code wrote back the registers live where it left.
        let held = || live.is_live(callee_pc as usize, register).then(|| unsafe { entry.scratch_value(inlining, frame.base + register) });
        registers.set(register, bound.or_else(held).unwrap_or(Value::UNDEFINED));
    }
    // SAFETY: the activation's view holds a record for each of its function's PCs.
    unsafe { (*cx).base.add(callee_pc as usize) }
}

script_handler! {
    /// `JumpFalse` of a value that decides its own truthiness (`Value::truthiness`); a heap
    /// value whose cell decides it takes `lane_jump_test_cell`.
    fn lane_jump_false<BACKWARD: bool>(cx, r, ip, i, view) {
        match staged_jump_if::<false>(r, Carried::script_in(cx, view), i.a) {
            Some(crate::staged::Edge::Target) =>
                resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None)),
            Some(crate::staged::Edge::Following) =>
                next!(cx, r, following(ip), Carried::script_in(cx, view)),
            None => sibling!(lane_jump_test_cell::<H, BACKWARD, false>, r, ip, Carried::script_in(cx, view)),
        }
    }
}

script_handler! {
    /// `JumpTrue` as `lane_jump_false`: ToBoolean runs no guest code.
    fn lane_jump_true<BACKWARD: bool>(cx, r, ip, i, view) {
        match staged_jump_if::<true>(r, Carried::script_in(cx, view), i.a) {
            Some(crate::staged::Edge::Target) =>
                resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None)),
            Some(crate::staged::Edge::Following) =>
                next!(cx, r, following(ip), Carried::script_in(cx, view)),
            None => sibling!(lane_jump_test_cell::<H, BACKWARD, true>, r, ip, Carried::script_in(cx, view)),
        }
    }
}

script_handler! {
    /// `JumpFalse` (`WHEN` false) or `JumpTrue` (`WHEN` true) of a heap value whose cell
    /// decides its truthiness; out of line, so the common tests make no call.
    #[inline(never)]
    fn lane_jump_test_cell<BACKWARD: bool, WHEN: bool>(cx, r, ip, i, view) {
        if unsafe { vm(cx) }.heap_cell_truthy(r.get(i.a)) == WHEN {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried::script_in(cx, view), None));
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

lane_handler! {
    /// Take the selected entry's jump; the view admits a table only when
    /// every entry is a lane jump.
    fn lane_branch_table<BACKWARD: bool>(cx, r, ip, i, view) {
        let case = r.get(i.a).wasm_bits32().min(i.imm());
        // SAFETY: validation places `imm + 1` entries after the table.
        let entry = unsafe { ip.add(1 + case as usize) };
        resume!(cx, lane_jump::<H>(r, entry, BACKWARD, view, None))
    }
}

lane_handler! {
    fn lane_bit_field<ACC: u8>(cx, r, ip, i, view) {
        let value = crate::wasm::integer::shift_right_unsigned_and(
            read_i32::<ACC, ACC_B>(r, i.b, view),
            i32::from(i.c as i16),
            i.imm() as i32,
        );
        produce!(cx, r, ip, i.a, view.integers.encode(value), view)
    }
}

lane_handler! {
    /// A counted loop's step and test.
    fn lane_add_jump_nonzero<BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let sum = read_i32::<ACC, ACC_B>(r, i.b, view).wrapping_add(i32::from(i.c as i16));
        if sum != 0 {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, Some((i.a, view.integers.encode(sum)))));
        }
        // Falling through, the step is an accumulator producer.
        produce!(cx, r, ip, i.a, view.integers.encode(sum), view)
    }
}

lane_handler! {
    /// `WasmJumpI32Zero` and `WasmJumpI32NonZero`. With `CARRY`, the taken
    /// jump carries register `c` (a field the instruction leaves unused) as
    /// the accumulator, for a target that reads it there.
    fn lane_jump_i32_zero<WHEN_ZERO: bool, BACKWARD: bool, ACC: u8, CARRY: bool>(cx, r, ip, i, view) {
        if (read_i32::<ACC, ACC_A>(r, i.a, view) == 0) == WHEN_ZERO {
            let view = if CARRY { Carried { acc: Slot::of(r.get(i.c)), ..view } } else { view };
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, None));
        }
        next!(cx, r, following(ip), view)
    }
}

/// The zero-test jumps, indexed by whether they jump on zero, direction and
/// accumulator position; `CARRY` as in `lane_jump_i32_zero`.
struct ZeroJumps<H, const CARRY: bool>(std::marker::PhantomData<H>);

impl<H: Host, const CARRY: bool> ZeroJumps<H, CARRY> {
    const HANDLERS: [[[Handler; ACC_POSITIONS]; 2]; 2] = {
        macro_rules! positions {
            ($zero:literal, $backward:literal) => {
                [
                    lane_jump_i32_zero::<H, $zero, $backward, ACC_NONE, CARRY>,
                    lane_jump_i32_zero::<H, $zero, $backward, ACC_A, CARRY>,
                    lane_jump_i32_zero::<H, $zero, $backward, ACC_B, CARRY>,
                    lane_jump_i32_zero::<H, $zero, $backward, ACC_C, CARRY>,
                    lane_jump_i32_zero::<H, $zero, $backward, ACC_PAIR, CARRY>,
                ]
            };
        }
        [
            [positions!(false, false), positions!(false, true)],
            [positions!(true, false), positions!(true, true)],
        ]
    };
}

lane_handler! {
    /// Fused i32 comparison and branch, against a register or a constant.
    fn lane_compare_jump<OP: u16, BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let (comparison, immediate) = const {
            match I32BinaryOperator::from_jump_op(opcode(OP)) {
                Some(comparison) => (comparison, false),
                None => match I32BinaryOperator::from_immediate_jump_op(opcode(OP)) {
                    Some(comparison) => (comparison, true),
                    None => panic!("not an i32 comparison jump"),
                },
            }
        };
        let right = if immediate {
            i32::from(i.b as i16)
        } else {
            read_i32::<ACC, ACC_B>(r, i.b, view)
        };
        let Ok(taken) = comparison.evaluate(read_i32::<ACC, ACC_A>(r, i.a, view), right) else {
            return exit(ip);
        };
        if taken != 0 {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, None));
        }
        next!(cx, r, following(ip), view)
    }
}

#[path = "vector_region.rs"]
mod vector_region;
mod wasm_instance;
use wasm_instance::{lane_global_get, lane_global_set, lane_instance_binding, lane_wasm_memory_address, lane_wasm_memory_load, lane_wasm_memory_store, lane_wasm_simd, lane_wasm_simd_shuffle};

/// `if condition { chosen } else { other }` of two loaded values, picked after both load, so
/// neither load waits on the condition; the compiler would otherwise load once from a picked
/// register address, a load the condition delays.
#[inline(always)]
fn select_loaded(condition: bool, chosen: Value, other: Value) -> Value {
    #[cfg(target_arch = "x86_64")]
    {
        let mut picked = other.to_bits();
        // SAFETY: a register-only conditional move; no memory or stack.
        unsafe {
            std::arch::asm!(
                "test {condition:e}, {condition:e}",
                "cmovnz {picked}, {chosen}",
                condition = in(reg) u32::from(condition),
                chosen = in(reg) chosen.to_bits(),
                picked = inout(reg) picked,
                options(pure, nomem, nostack),
            );
        }
        Value::from_bits(picked)
    }
    #[cfg(not(target_arch = "x86_64"))]
    {
        std::hint::select_unpredictable(condition, chosen, other)
    }
}

lane_handler! {
    fn lane_select<ACC: u8>(cx, r, ip, i, view) {
        let (condition, _) = ImmediateLayout::register_pair(i.imm());
        let condition = if ACC == ACC_PAIR {
            // SAFETY: as for `read`.
            unsafe { view.acc.get() }.wasm_bits32() as i32
        } else {
            r.i32(condition)
        };
        let value = select_loaded(condition != 0, r.get(i.b), r.get(i.c));
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    fn lane_fill_registers<>(cx, r, ip, i, view) {
        let value = i.constant();
        for offset in 0..i.c {
            r.set(i.b + offset, value);
        }
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    fn lane_i32_unary<ACC: u8>(cx, r, ip, i, view) {
        let Some(operator) = I32UnaryOperator::from_tag(i.imm()) else {
            return exit(ip);
        };
        let value = operator.evaluate(read_i32::<ACC, ACC_B>(r, i.b, view));
        produce!(cx, r, ip, i.a, view.integers.encode(value), view)
    }
}

lane_handler! {
    /// An i32 operator over two registers or a register and a constant; a
    /// trap leaves the lane.
    fn lane_i32_binary<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let (operator, immediate) = const {
            match I32BinaryOperator::from_register_op(opcode(OP)) {
                Some(operator) => (operator, false),
                None => match I32BinaryOperator::from_immediate_op(opcode(OP)) {
                    Some(operator) => (operator, true),
                    None => panic!("not an i32 binary operator"),
                },
            }
        };
        let right = if immediate {
            i.imm() as i32
        } else {
            read_i32::<ACC, ACC_C>(r, i.c, view)
        };
        let Ok(value) = operator.evaluate(read_i32::<ACC, ACC_B>(r, i.b, view), right) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, view.integers.encode(value), view)
    }
}

/// A scalar of static Wasm type `ty` read from a slot value.
#[inline(always)]
fn lane_scalar(value: Value, ty: crate::WasmType) -> Option<crate::WasmValue> {
    Some(match ty {
        crate::WasmType::I32 => crate::WasmValue::I32(value.as_int()?),
        crate::WasmType::F32 => crate::WasmValue::F32(value.as_int()? as u32),
        crate::WasmType::I64 => crate::WasmValue::I64(value.bits64()? as i64),
        crate::WasmType::F64 => crate::WasmValue::F64(value.bits64()?),
        _ => return None,
    })
}

/// A numeric scalar as a slot value.
#[inline(always)]
fn lane_encode(view: Carried, value: crate::WasmValue) -> Option<Value> {
    Some(match value {
        crate::WasmValue::I32(value) => view.integers.encode(value),
        crate::WasmValue::F32(bits) => view.integers.encode(bits as i32),
        crate::WasmValue::I64(value) => Value::from_bits64(value as u64)?,
        crate::WasmValue::F64(bits) => Value::from_bits64(bits)?,
        _ => return None,
    })
}

lane_handler! {
    /// An f32 or f64 operator: each width's selector applies its own
    /// semantics (`crate::wasm::float`).
    fn lane_float_binary<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let left = read::<ACC, ACC_B>(r, i.b, view);
        let right = read::<ACC, ACC_C>(r, i.c, view);
        let value = if const { opcode(OP).class().eq(Class::WasmFloatBinary64) } {
            let (Some(left), Some(right), Some(operator)) = (
                left.bits64(),
                right.bits64(),
                F64BinaryOperator::from_tag(i.imm()),
            ) else {
                return exit(ip);
            };
            operator.evaluate(f64::from_bits(left), f64::from_bits(right))
        } else {
            let (Some(left), Some(right), Some(operator)) = (
                left.as_int(),
                right.as_int(),
                F32BinaryOperator::from_tag(i.imm()),
            ) else {
                return exit(ip);
            };
            operator.evaluate(f32::from_bits(left as u32), f32::from_bits(right as u32))
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

/// The float operators a lane record runs as one hardware operation or
/// comparison, by index: the operator is part of the handler, not a
/// selector it decodes.
const FLOAT_ADD: u8 = 0;
const FLOAT_SUBTRACT: u8 = 1;
const FLOAT_MULTIPLY: u8 = 2;
const FLOAT_DIVIDE: u8 = 3;
/// Comparisons, whose result is an i32 truth value.
const FLOAT_EQUAL: u8 = 4;
const FLOAT_NOT_EQUAL: u8 = 5;
const FLOAT_LESS: u8 = 6;
const FLOAT_GREATER: u8 = 7;
const FLOAT_LESS_EQUAL: u8 = 8;
const FLOAT_GREATER_EQUAL: u8 = 9;
const FLOAT_ARITHMETIC: usize = 10;

/// The arithmetic index of a float binary selector, when it has one.
fn float_arithmetic(op: Op, selector: u32) -> Option<u8> {
    Some(match op.class() {
        Class::WasmFloatBinary64 => match F64BinaryOperator::from_tag(selector)? {
            F64BinaryOperator::Add => FLOAT_ADD,
            F64BinaryOperator::Subtract => FLOAT_SUBTRACT,
            F64BinaryOperator::Multiply => FLOAT_MULTIPLY,
            F64BinaryOperator::Divide => FLOAT_DIVIDE,
            F64BinaryOperator::Equal => FLOAT_EQUAL,
            F64BinaryOperator::NotEqual => FLOAT_NOT_EQUAL,
            F64BinaryOperator::Less => FLOAT_LESS,
            F64BinaryOperator::Greater => FLOAT_GREATER,
            F64BinaryOperator::LessEqual => FLOAT_LESS_EQUAL,
            F64BinaryOperator::GreaterEqual => FLOAT_GREATER_EQUAL,
            _ => return None,
        },
        Class::WasmFloatBinary32 => match F32BinaryOperator::from_tag(selector)? {
            F32BinaryOperator::Add => FLOAT_ADD,
            F32BinaryOperator::Subtract => FLOAT_SUBTRACT,
            F32BinaryOperator::Multiply => FLOAT_MULTIPLY,
            F32BinaryOperator::Divide => FLOAT_DIVIDE,
            F32BinaryOperator::Equal => FLOAT_EQUAL,
            F32BinaryOperator::NotEqual => FLOAT_NOT_EQUAL,
            F32BinaryOperator::Less => FLOAT_LESS,
            F32BinaryOperator::Greater => FLOAT_GREATER,
            F32BinaryOperator::LessEqual => FLOAT_LESS_EQUAL,
            F32BinaryOperator::GreaterEqual => FLOAT_GREATER_EQUAL,
            _ => return None,
        },
        _ => return None,
    })
}

lane_handler! {
    /// Float arithmetic `ARITH` of width f64 (`WIDE`) or f32, with the
    /// operators' own semantics (`crate::wasm::float`): the hardware result.
    fn lane_float_arithmetic<WIDE: bool, ARITH: u8, ACC: u8>(cx, r, ip, i, view) {
        let left = read::<ACC, ACC_B>(r, i.b, view);
        let right = read::<ACC, ACC_C>(r, i.c, view);
        /// The arithmetic result, or a comparison's truth value.
        enum Outcome<F> {
            Float(F),
            Truth(bool),
        }
        macro_rules! apply {
            ($left:expr, $right:expr) => {{
                let (left, right) = ($left, $right);
                match ARITH {
                    FLOAT_ADD => Outcome::Float(left + right),
                    FLOAT_SUBTRACT => Outcome::Float(left - right),
                    FLOAT_MULTIPLY => Outcome::Float(left * right),
                    FLOAT_DIVIDE => Outcome::Float(left / right),
                    FLOAT_EQUAL => Outcome::Truth(left == right),
                    FLOAT_NOT_EQUAL => Outcome::Truth(left != right),
                    FLOAT_LESS => Outcome::Truth(left < right),
                    FLOAT_GREATER => Outcome::Truth(left > right),
                    FLOAT_LESS_EQUAL => Outcome::Truth(left <= right),
                    _ => Outcome::Truth(left >= right),
                }
            }};
        }
        // Registers hold their static Wasm types: an f32 slot an encoded
        // i32, an f64 slot its bits in place or a box whose bits read as a
        // NaN, which these operators treat as any other NaN.
        let value = if WIDE {
            let left = f64::from_bits(left.float_bits64());
            let right = f64::from_bits(right.float_bits64());
            match apply!(left, right) {
                Outcome::Float(result) => Value::from_float_bits64(result.to_bits()),
                Outcome::Truth(truth) => view.integers.encode(i32::from(truth)),
            }
        } else {
            let left = f32::from_bits(left.wasm_bits32());
            let right = f32::from_bits(right.wasm_bits32());
            match apply!(left, right) {
                Outcome::Float(result) => view.integers.encode(result.to_bits() as i32),
                Outcome::Truth(truth) => view.integers.encode(i32::from(truth)),
            }
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

/// The f64 operator `ARITH` over two operands, as `lane_float_arithmetic`
/// applies it: the hardware result, or a comparison's truth value.
#[inline(always)]
fn f64_operation(arith: u8, left: f64, right: f64) -> Result<f64, bool> {
    match arith {
        FLOAT_ADD => Ok(left + right),
        FLOAT_SUBTRACT => Ok(left - right),
        FLOAT_MULTIPLY => Ok(left * right),
        FLOAT_DIVIDE => Ok(left / right),
        FLOAT_EQUAL => Err(left == right),
        FLOAT_NOT_EQUAL => Err(left != right),
        FLOAT_LESS => Err(left < right),
        FLOAT_GREATER => Err(left > right),
        FLOAT_LESS_EQUAL => Err(left <= right),
        _ => Err(left >= right),
    }
}

/// Which operand of the second fused float record the first one's result
/// is: its left (`b`) or right (`c`) register.
const FUSED_LEFT: bool = true;

lane_handler! {
    /// An f64 arithmetic `FIRST` whose result the next record, f64 operator
    /// `SECOND`, takes as its left (`LEFT`) or right operand: both records
    /// run here, each result written as its own record writes it.
    fn lane_f64_pair<FIRST: u8, SECOND: u8, LEFT: bool, ACC: u8>(cx, r, ip, i, view) {
        let first = match f64_operation(
            FIRST,
            f64::from_bits(read::<ACC, ACC_B>(r, i.b, view).float_bits64()),
            f64::from_bits(read::<ACC, ACC_C>(r, i.c, view).float_bits64()),
        ) {
            Ok(result) => result,
            Err(_) => unreachable!("a fused first operator is arithmetic"),
        };
        r.set(i.a, Value::from_float_bits64(first.to_bits()));
        let next = following(ip);
        // SAFETY: the view fuses a float record only with a following one.
        let second = unsafe { &*next };
        let (left, right) = if LEFT {
            (first, f64::from_bits(r.get(second.c).float_bits64()))
        } else {
            (f64::from_bits(r.get(second.b).float_bits64()), first)
        };
        let value = match f64_operation(SECOND, left, right) {
            Ok(result) => Value::from_float_bits64(result.to_bits()),
            Err(truth) => view.integers.encode(i32::from(truth)),
        };
        produce!(cx, r, next, second.a, value, view)
    }
}

lane_handler! {
    /// An f64 load whose value the next record, f64 operator `SECOND`,
    /// takes as its left (`LEFT`) or right operand: both records run here.
    /// Bits that need a box leave the lane at the load.
    fn lane_f64_load_pair<SECOND: u8, LEFT: bool>(cx, r, ip, i, view) {
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::F64(bits)) = (unsafe { view.memory.read(MemoryLoad::F64Load, lane_address::<ACC_NONE>(r, i, view)) })
        else {
            return exit(ip);
        };
        let Some(loaded) = Value::from_bits64(bits) else {
            return exit(ip);
        };
        r.set(i.a, loaded);
        let next = following(ip);
        // SAFETY: the view fuses a load only with a following record.
        let second = unsafe { &*next };
        let first = f64::from_bits(bits);
        let (left, right) = if LEFT {
            (first, f64::from_bits(r.get(second.c).float_bits64()))
        } else {
            (f64::from_bits(r.get(second.b).float_bits64()), first)
        };
        let value = match f64_operation(SECOND, left, right) {
            Ok(result) => Value::from_float_bits64(result.to_bits()),
            Err(truth) => view.integers.encode(i32::from(truth)),
        };
        produce!(cx, r, next, second.a, value, view)
    }
}

lane_handler! {
    /// An f64 load, the f64 arithmetic `ARITH` taking the loaded value as
    /// its left (`LEFT`) or right operand, and the f64 store writing the
    /// arithmetic's result (`mem[x] += v`): three records run here, each
    /// result written as its own record writes it. An access the general
    /// path must run exits at its record.
    fn lane_f64_update<ARITH: u8, LEFT: bool>(cx, r, ip, i, view) {
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::F64(bits)) = (unsafe {
            view.memory.read(MemoryLoad::F64Load, lane_address::<ACC_NONE>(r, i, view))
        }) else {
            return exit(ip);
        };
        let Some(loaded) = Value::from_bits64(bits) else {
            return exit(ip);
        };
        r.set(i.a, loaded);
        let operator = following(ip);
        // SAFETY: the view fuses a load only with a following operator and
        // store.
        let o = unsafe { &*operator };
        let first = f64::from_bits(bits);
        let (left, right) = if LEFT {
            (first, f64::from_bits(r.get(o.c).float_bits64()))
        } else {
            (f64::from_bits(r.get(o.b).float_bits64()), first)
        };
        let Ok(result) = f64_operation(ARITH, left, right) else {
            unreachable!("a fused update's operator is arithmetic");
        };
        let value = Value::from_float_bits64(result.to_bits());
        r.set(o.a, value);
        let store = following(operator);
        // SAFETY: as above.
        let access = unsafe { &*store };
        // SAFETY: as for `lane_store`.
        if unsafe {
            view.memory.write(
                MemoryStore::F64Store,
                lane_address::<ACC_NONE>(r, access, view),
                crate::WasmValue::F64(value.float_bits64()),
            )
        }
        .is_none()
        {
            return exit(store);
        }
        next!(cx, r, following(store), view)
    }
}

lane_handler! {
    /// An f64 arithmetic `ARITH` whose result the next record, an f64
    /// store, writes to memory: both records run here. A store the general
    /// path must run exits at its record, the result already written.
    fn lane_f64_store_pair<ARITH: u8, ACC: u8>(cx, r, ip, i, view) {
        let result = match f64_operation(
            ARITH,
            f64::from_bits(read::<ACC, ACC_B>(r, i.b, view).float_bits64()),
            f64::from_bits(read::<ACC, ACC_C>(r, i.c, view).float_bits64()),
        ) {
            Ok(result) => result,
            Err(_) => unreachable!("a fused store's operator is arithmetic"),
        };
        let value = Value::from_float_bits64(result.to_bits());
        r.set(i.a, value);
        let next = following(ip);
        // SAFETY: the view fuses an operator only with a following store.
        let store = unsafe { &*next };
        let bits = value.float_bits64();
        // SAFETY: as for `lane_store`.
        if unsafe {
            view.memory.write(
                MemoryStore::F64Store,
                lane_address::<ACC_NONE>(r, store, view),
                crate::WasmValue::F64(bits),
            )
        }
        .is_none()
        {
            return exit(next);
        }
        next!(cx, r, following(next), view)
    }
}

/// The accumulator fields a fused first float record may read: none, its
/// left operand, or its right operand.
const FUSED_ACC_FIELDS: [u8; 3] = [ACC_NONE, ACC_B, ACC_C];

macro_rules! float_store_pair_handlers {
    ($host:ty, $arith:expr) => {
        [
            lane_f64_store_pair::<$host, $arith, ACC_NONE> as Handler,
            lane_f64_store_pair::<$host, $arith, ACC_B> as Handler,
            lane_f64_store_pair::<$host, $arith, ACC_C> as Handler,
        ]
    };
}

macro_rules! float_load_pair_handlers {
    ($host:ty; $($second:expr),+) => {
        [$([
            lane_f64_load_pair::<$host, $second, false> as Handler,
            lane_f64_load_pair::<$host, $second, FUSED_LEFT> as Handler,
        ]),+]
    };
}

struct FloatPairs<H>(std::marker::PhantomData<H>);

macro_rules! float_pair_handlers {
    ($host:ty) => {
        [
            float_pair_handlers!($host, FLOAT_ADD),
            float_pair_handlers!($host, FLOAT_SUBTRACT),
            float_pair_handlers!($host, FLOAT_MULTIPLY),
            float_pair_handlers!($host, FLOAT_DIVIDE),
        ]
    };
    ($host:ty, $first:expr) => {
        [
            float_pair_handlers!($host, $first, FLOAT_ADD),
            float_pair_handlers!($host, $first, FLOAT_SUBTRACT),
            float_pair_handlers!($host, $first, FLOAT_MULTIPLY),
            float_pair_handlers!($host, $first, FLOAT_DIVIDE),
            float_pair_handlers!($host, $first, FLOAT_EQUAL),
            float_pair_handlers!($host, $first, FLOAT_NOT_EQUAL),
            float_pair_handlers!($host, $first, FLOAT_LESS),
            float_pair_handlers!($host, $first, FLOAT_GREATER),
            float_pair_handlers!($host, $first, FLOAT_LESS_EQUAL),
            float_pair_handlers!($host, $first, FLOAT_GREATER_EQUAL),
        ]
    };
    ($host:ty, $first:expr, $second:expr) => {
        [
            float_pair_handlers!($host, $first, $second, false),
            float_pair_handlers!($host, $first, $second, FUSED_LEFT),
        ]
    };
    ($host:ty, $first:expr, $second:expr, $left:expr) => {
        [
            lane_f64_pair::<$host, $first, $second, $left, ACC_NONE> as Handler,
            lane_f64_pair::<$host, $first, $second, $left, ACC_B> as Handler,
            lane_f64_pair::<$host, $first, $second, $left, ACC_C> as Handler,
        ]
    };
}

/// The f64 arithmetic operators a fused pair can begin with: add,
/// subtract, multiply and divide, whose results are floats.
const FLOAT_PAIR_FIRSTS: usize = 4;

impl<H: Host> FloatPairs<H> {
    /// By first operator, second operator, whether the first result is the
    /// second's left operand, and the first's accumulator field.
    const HANDLERS: [[[[Handler; FUSED_ACC_FIELDS.len()]; 2]; FLOAT_ARITHMETIC];
        FLOAT_PAIR_FIRSTS] = float_pair_handlers!(H);
    /// An f64 load fused with the operator taking its value, by second
    /// operator and whether the value is its left operand.
    /// An f64 arithmetic fused with the store of its result, by operator.
    /// By operator and the operator's accumulator field (none, `b`, `c`).
    const STORES: [[Handler; FUSED_ACC_FIELDS.len()]; FLOAT_PAIR_FIRSTS] = [
        float_store_pair_handlers!(H, FLOAT_ADD),
        float_store_pair_handlers!(H, FLOAT_SUBTRACT),
        float_store_pair_handlers!(H, FLOAT_MULTIPLY),
        float_store_pair_handlers!(H, FLOAT_DIVIDE),
    ];
    /// An f64 load, arithmetic and store of its result, by operator and
    /// whether the loaded value is the left operand.
    const UPDATES: [[Handler; 2]; FLOAT_PAIR_FIRSTS] = [
        [
            lane_f64_update::<H, FLOAT_ADD, false>,
            lane_f64_update::<H, FLOAT_ADD, FUSED_LEFT>,
        ],
        [
            lane_f64_update::<H, FLOAT_SUBTRACT, false>,
            lane_f64_update::<H, FLOAT_SUBTRACT, FUSED_LEFT>,
        ],
        [
            lane_f64_update::<H, FLOAT_MULTIPLY, false>,
            lane_f64_update::<H, FLOAT_MULTIPLY, FUSED_LEFT>,
        ],
        [
            lane_f64_update::<H, FLOAT_DIVIDE, false>,
            lane_f64_update::<H, FLOAT_DIVIDE, FUSED_LEFT>,
        ],
    ];
    const LOADS: [[Handler; 2]; FLOAT_ARITHMETIC] = float_load_pair_handlers!(H;
        FLOAT_ADD, FLOAT_SUBTRACT, FLOAT_MULTIPLY, FLOAT_DIVIDE, FLOAT_EQUAL,
        FLOAT_NOT_EQUAL, FLOAT_LESS, FLOAT_GREATER, FLOAT_LESS_EQUAL, FLOAT_GREATER_EQUAL);
}

struct FloatArithmetic<H>(std::marker::PhantomData<H>);

macro_rules! float_arithmetic_handlers {
    ($host:ty, $wide:expr) => {
        [
            float_arithmetic_handlers!($host, $wide, FLOAT_ADD),
            float_arithmetic_handlers!($host, $wide, FLOAT_SUBTRACT),
            float_arithmetic_handlers!($host, $wide, FLOAT_MULTIPLY),
            float_arithmetic_handlers!($host, $wide, FLOAT_DIVIDE),
            float_arithmetic_handlers!($host, $wide, FLOAT_EQUAL),
            float_arithmetic_handlers!($host, $wide, FLOAT_NOT_EQUAL),
            float_arithmetic_handlers!($host, $wide, FLOAT_LESS),
            float_arithmetic_handlers!($host, $wide, FLOAT_GREATER),
            float_arithmetic_handlers!($host, $wide, FLOAT_LESS_EQUAL),
            float_arithmetic_handlers!($host, $wide, FLOAT_GREATER_EQUAL),
        ]
    };
    ($host:ty, $wide:expr, $arith:expr) => {
        [
            lane_float_arithmetic::<$host, $wide, $arith, ACC_NONE> as Handler,
            lane_float_arithmetic::<$host, $wide, $arith, ACC_A> as Handler,
            lane_float_arithmetic::<$host, $wide, $arith, ACC_B> as Handler,
            lane_float_arithmetic::<$host, $wide, $arith, ACC_C> as Handler,
            lane_float_arithmetic::<$host, $wide, $arith, ACC_PAIR> as Handler,
        ]
    };
}

impl<H: Host> FloatArithmetic<H> {
    /// By width (f32, then f64), arithmetic index and accumulator field.
    const HANDLERS: [[[Handler; ACC_POSITIONS]; FLOAT_ARITHMETIC]; 2] = [
        float_arithmetic_handlers!(H, false),
        float_arithmetic_handlers!(H, true),
    ];
}

lane_handler! {
    /// f64 square root: an arithmetic operator, so a NaN operand matters
    /// only as a NaN (see `float_bits64`), and its result is held in place.
    fn lane_f64_sqrt<ACC: u8>(cx, r, ip, i, view) {
        let input = f64::from_bits(read::<ACC, ACC_B>(r, i.b, view).float_bits64());
        produce!(cx, r, ip, i.a, Value::from_float_bits64(input.sqrt().to_bits()), view)
    }
}

lane_handler! {
    fn lane_float_unary<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let input = read::<ACC, ACC_B>(r, i.b, view);
        let value = if const { opcode(OP).is_wasm_f64_unary() } {
            let (Some(input), Some(operator)) =
                (input.bits64(), F64UnaryOperator::from_tag(i.imm()))
            else {
                return exit(ip);
            };
            operator.evaluate(f64::from_bits(input))
        } else {
            let (Some(input), Some(operator)) =
                (input.as_int(), F32UnaryOperator::from_tag(i.imm()))
            else {
                return exit(ip);
            };
            operator.evaluate(f32::from_bits(input as u32))
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    /// An i64 operator; a trap leaves the lane, where the general loop
    /// raises it.
    fn lane_i64_binary<ACC: u8>(cx, r, ip, i, view) {
        let (Some(left), Some(right), Some(operator)) = (
            read::<ACC, ACC_B>(r, i.b, view).bits64(),
            read::<ACC, ACC_C>(r, i.c, view).bits64(),
            I64BinaryOperator::from_tag(i.imm()),
        ) else {
            return exit(ip);
        };
        let Ok(value) = operator.evaluate(left as i64, right as i64) else {
            return exit(ip);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    fn lane_i64_binary_immediate<ACC: u8>(cx, r, ip, i, view) {
        let (Some(left), Some(operator)) = (
            read::<ACC, ACC_B>(r, i.b, view).bits64(),
            I64BinaryOperator::from_tag(i.imm()),
        ) else {
            return exit(ip);
        };
        let Ok(value) = operator.evaluate(left as i64, i64::from(i.c as i16)) else {
            return exit(ip);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    fn lane_i64_unary<ACC: u8>(cx, r, ip, i, view) {
        let (Some(input), Some(operator)) = (
            read::<ACC, ACC_B>(r, i.b, view).bits64(),
            I64UnaryOperator::from_tag(i.imm()),
        ) else {
            return exit(ip);
        };
        let Some(value) = lane_encode(view, operator.evaluate(input as i64)) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    /// A scalar conversion; a trapping truncation leaves the lane.
    fn lane_scalar_convert<ACC: u8>(cx, r, ip, i, view) {
        let Some(operator) = ScalarConversionOperator::from_tag(i.imm()) else {
            return exit(ip);
        };
        let Some(input) = lane_scalar(read::<ACC, ACC_B>(r, i.b, view), operator.source_type())
        else {
            return exit(ip);
        };
        let Ok(value) = operator.evaluate(input) else {
            return exit(ip);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

/// The memory32 effective address of a direct access through the function's
/// memory register.
#[inline(always)]
fn lane_address<const ACC: u8>(r: Registers, i: &LaneInstruction, view: Carried) -> u64 {
    u64::from(read::<ACC, ACC_C>(r, i.c, view).wasm_bits32()) + u64::from(i.imm())
}

/// The bytes of memory binding `binding` code addresses in place (`MemoryStorage::direct_view`).
pub(super) fn direct_memory<H: Host>(vm: &Vm<H>, binding: Value) -> Option<(*mut u8, usize)> {
    direct_memory_and_guard(vm, binding).map(|(bytes, _)| bytes)
}

/// `direct_memory` with the memory's guard reservation, read together.
pub(super) fn direct_memory_and_guard<H: Host>(
    vm: &Vm<H>,
    binding: Value,
) -> Option<((*mut u8, usize), Option<(*mut u8, usize)>)> {
    let Some(Cell::WasmMemory { bytes, .. }) = vm.heap.get(binding) else {
        return None;
    };
    bytes.direct_view()
}

fn memory_view<H: Host>(vm: &Vm<H>, binding: Value) -> MemoryView {
    direct_memory(vm, binding).map_or(MemoryView::NONE, |(bytes, len)| MemoryView::new(bytes, len))
}

/// The view of memory binding `binding`, reusing the run's last resolution.
#[inline(always)]
fn resolve_memory<H: Host>(cx: *mut LaneContext<H>, binding: Value) -> MemoryView {
    // SAFETY: handlers run with exclusive access to their context.
    let (resolved, view) = unsafe { (*cx).resolved };
    if resolved == binding {
        return view;
    }
    let view = memory_view(unsafe { vm(cx) }, binding);
    unsafe { (*cx).resolved = (binding, view) };
    view
}

/// The view behind `view`'s memory register in `registers`.
fn frame_memory_view<H: Host>(
    cx: *mut LaneContext<H>,
    view: &LaneView,
    registers: Registers,
) -> MemoryView {
    // A lane run is all JavaScript or all Wasm (`LaneContext::script_calls`, `inline_calls`).
    // SAFETY: the context's program outlives the lane run.
    if unsafe { (*(*cx).code).kind } != crate::bytecode::ProgramKind::Wasm {
        return MemoryView::script(cx);
    }
    view.memory_register.map_or(MemoryView::NONE, |register| {
        resolve_memory(cx, registers.get(register))
    })
}

/// A taken safepoint jump whose fuel ran out (`script_fuel_out`): leave the lane when a
/// collection is due or termination requested, otherwise refill the fuel, credit the work
/// clock and dispatch the target from the lane loop,
/// which unwinds the stack, with the accumulator `acc` the jump carries
/// (`LaneContext::resumed_acc`): a loop head whose every edge carries a
/// register reads it there. Out of line, so a
/// safepoint's fast path neither loads the context nor saves registers.
#[cold]
#[inline(never)]
fn lane_safepoint<H: Host>(ip: Ip, target: Ip, acc: Slot<Value>) -> Ip {
    let cx = lane_context::<H>();
    // SAFETY: called only while a lane runs, from one of its handlers.
    if unsafe { vm(cx) }.heap.should_collect() || unsafe { vm(cx) }.execution_interrupt.is_termination_requested() {
        // SAFETY: as above.
        unsafe { (*cx).fuel = 0 };
        return exit(ip);
    }
    // A crediting run counts every backward jump here; any other run takes a batch of
    // jumps before its next visit, and credits the work clock with the batch it spent.
    // SAFETY: as above.
    unsafe {
        if (*cx).backedges_left.is_some() {
            (*cx).fuel = 0;
        } else {
            (*cx).fuel = LANE_FUEL_BATCH;
            crate::clock::note_backedges(LANE_FUEL_BATCH);
        }
    }
    lane_count_backedge::<H>(cx);
    // SAFETY: as above; the lane loop takes it before dispatching `target`.
    unsafe { (*cx).resumed_acc = acc };
    target
}

/// `lane_safepoint` for a jump that writes `register` when taken.
#[cold]
#[inline(never)]
fn lane_safepoint_writing<H: Host>(
    r: Registers,
    ip: Ip,
    target: Ip,
    acc: Slot<Value>,
    register: u16,
    value: Value,
) -> Ip {
    let next = lane_safepoint::<H>(ip, target, acc);
    if next == target {
        r.set(register, value);
    }
    next
}

// The lane holds 64-bit payloads only in place (`Value::from_bits64`): a
// boxed operand or a result that needs a box leaves the lane, and the
// general loop, which boxes, runs the instruction. The handlers then make
// no calls.

lane_handler! {
    fn lane_load<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let load = const {
            match MemoryLoad::from_direct_op(opcode(OP)) {
                Some(load) => load,
                None => panic!("not a direct load"),
            }
        };
        // SAFETY: the view admits direct accesses only through the memory
        // register, whose bytes `view` holds; see MemoryView.
        let Some(value) = (unsafe { view.memory.read(load, lane_address::<ACC>(r, i, view)) })
        else {
            return exit(ip);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(ip);
        };
        produce!(cx, r, ip, i.a, value, view)
    }
}

lane_handler! {
    /// An i32 shift left by a constant, reading its operand through field
    /// `ACC`, whose result the next record, an i32 add, takes as its left
    /// (`LEFT`) or right operand: a scaled index. Both records run here,
    /// each result written as its own record writes it.
    fn lane_shift_add<ACC: u8, LEFT: bool>(cx, r, ip, i, view) {
        let Ok(shifted) = I32BinaryOperator::ShiftLeft
            .evaluate(read_i32::<ACC, ACC_B>(r, i.b, view), i.imm() as i32)
        else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(shifted));
        let next = following(ip);
        // SAFETY: the view fuses a shift only with a following add record.
        let add = unsafe { &*next };
        let other = r.i32(if LEFT { add.c } else { add.b });
        let (left, right) = if LEFT { (shifted, other) } else { (other, shifted) };
        let Ok(sum) = I32BinaryOperator::Add.evaluate(left, right) else {
            return exit(next);
        };
        produce!(cx, r, next, add.a, view.integers.encode(sum), view)
    }
}

lane_handler! {
    /// A direct i32 load `OP` whose value the next record, a branch table,
    /// selects on: both records run here, the value written as the load
    /// writes it. With `ADD`, the record is a plain add of a constant ahead
    /// of the load (`switch (*pc++)`), and the three run here, each result
    /// written as its own record writes it. A load the general path must
    /// run exits at its record.
    fn lane_load_table<OP: u16, ACC: u8, ADD: bool>(cx, r, ip, i, view) {
        let load = const {
            match MemoryLoad::from_direct_op(opcode(OP)) {
                Some(load) => load,
                None => panic!("not a direct load"),
            }
        };
        // With `ADD` and `ACC_C`, the accumulator holds the register both
        // the add and the load read.
        let ip = if ADD {
            let base = read_i32::<ACC, ACC_C>(r, i.b, view);
            r.set(i.a, view.integers.encode(base.wrapping_add(i.imm() as i32)));
            following(ip)
        } else {
            ip
        };
        // SAFETY: the view fuses an add only with a following load record.
        let i = unsafe { &*ip };
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(selector)) =
            (unsafe { view.memory.read(load, lane_address::<ACC>(r, i, view)) })
        else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(selector));
        let table = following(ip);
        // SAFETY: the view fuses a load only with a following table record.
        let case = (selector as u32).min(unsafe { (*table).imm() });
        // SAFETY: validation places `imm + 1` entries after the table.
        let entry = unsafe { table.add(1 + case as usize) };
        resume!(cx, lane_jump::<H>(r, entry, false, view, None))
    }
}

lane_handler! {
    /// An i32 add of a constant whose sum the next record, direct load `OP`,
    /// reads as its address: both records run here, the sum written as the
    /// add writes it. A load the general path must run exits at its record.
    fn lane_add_load<OP: u16>(cx, r, ip, i, view) {
        let load = const {
            match MemoryLoad::from_direct_op(opcode(OP)) {
                Some(load) => load,
                None => panic!("not a direct load"),
            }
        };
        let sum = r.i32(i.b).wrapping_add(i.imm() as i32);
        r.set(i.a, view.integers.encode(sum));
        let next = following(ip);
        // SAFETY: the view fuses an add only with a following load record.
        let access = unsafe { &*next };
        let address = u64::from(sum as u32) + u64::from(access.imm());
        // SAFETY: as for `lane_load`.
        let Some(value) = (unsafe { view.memory.read(load, address) }) else {
            return exit(next);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(next);
        };
        produce!(cx, r, next, access.a, value, view)
    }
}

lane_handler! {
    /// A jump absorbing the move (`ADD` false) or i32 add of the constant
    /// `c` (`ADD` true) at its target: the record holds the target's fields
    /// and jumps past it, carrying the result as the target would.
    fn lane_jump_through<ADD: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        let value = if ADD {
            view.integers.encode(r.i32(i.b).wrapping_add(i32::from(i.c as i16)))
        } else {
            r.get(i.b)
        };
        // A safepoint exit resumes at the jump, which runs the target
        // again, so the result is written only when the jump is taken.
        resume!(cx, lane_jump::<H>(r, ip, BACKWARD, Carried { acc: Slot::of(value), ..view }, Some((i.a, value))))
    }
}

lane_handler! {
    /// Two moves in a row (a parallel copy resolved in order): both
    /// records run here, the second's value carried as its record carries
    /// it. With `JUMP`, the unconditional jump after them runs here too, in
    /// direction `BACKWARD`.
    fn lane_move_pair<JUMP: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        r.set(i.a, r.get(i.b));
        let next = following(ip);
        // SAFETY: the view fuses a move only with a following move, and
        // with `JUMP` a jump after it.
        let second = unsafe { &*next };
        let value = r.get(second.b);
        if JUMP {
            r.set(second.a, value);
            let view = Carried { acc: Slot::of(value), ..view };
            resume!(cx, lane_jump::<H>(r, following(next), BACKWARD, view, None));
        }
        produce!(cx, r, next, second.a, value, view)
    }
}

lane_handler! {
    /// A move, reading its source through field `ACC`, whose next record is a zero-test jump
    /// (`lane_jump_i32_zero` without a carried register), as at a loop's latch: both records
    /// run here, the move's value carried as its own record carries it. The jump reads its
    /// operand from its register, which the move has written if it names it.
    fn lane_move_jump_i32_zero<WHEN_ZERO: bool, BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let value = read::<ACC, ACC_B>(r, i.b, view);
        r.set(i.a, value);
        let view = Carried { acc: Slot::of(value), ..view };
        let next = following(ip);
        // SAFETY: the view fuses a move only with a following zero-test jump.
        let jump = unsafe { &*next };
        if (r.i32(jump.a) == 0) == WHEN_ZERO {
            resume!(cx, lane_jump::<H>(r, next, BACKWARD, view, None));
        }
        next!(cx, r, following(next), view)
    }
}

/// The moves fused with a following zero-test jump, indexed by whether the jump is taken on
/// zero, its direction, and whether the move reads the accumulator.
struct MoveZeroJumps<H>(std::marker::PhantomData<H>);

impl<H: Host> MoveZeroJumps<H> {
    const HANDLERS: [[[Handler; 2]; 2]; 2] = {
        macro_rules! moves {
            ($zero:literal, $backward:literal) => {
                [
                    lane_move_jump_i32_zero::<H, $zero, $backward, ACC_NONE>,
                    lane_move_jump_i32_zero::<H, $zero, $backward, ACC_B>,
                ]
            };
        }
        [[moves!(false, false), moves!(false, true)], [moves!(true, false), moves!(true, true)]]
    };
}

lane_handler! {
    /// A move (`ADD` false) or an i32 add of a constant (`ADD` true) whose
    /// next record is an unconditional jump, as at a loop latch: both
    /// records run here, the result written as its own record writes it.
    fn lane_then_jump<ADD: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        let value = if ADD {
            view.integers.encode(r.i32(i.b).wrapping_add(i.imm() as i32))
        } else {
            r.get(i.b)
        };
        r.set(i.a, value);
        resume!(cx, lane_jump::<H>(r, following(ip), BACKWARD, Carried { acc: Slot::of(value), ..view }, None))
    }
}

/// The most records before a record that one fused record can run through:
/// an f64 load, arithmetic and store (`FloatPairs::UPDATES`) start two
/// records ahead of the last they run.
const FUSION_REACH: usize = 2;

/// The handlers fusing a move or an add of a constant with a jump, indexed
/// by whether the instruction adds and by the jump's direction.
struct JumpFusions<H>(std::marker::PhantomData<H>);

impl<H: Host> JumpFusions<H> {
    /// A jump absorbing the instruction at its target.
    const THROUGH: [[Handler; 2]; 2] = [
        [
            lane_jump_through::<H, false, false>,
            lane_jump_through::<H, false, true>,
        ],
        [
            lane_jump_through::<H, true, false>,
            lane_jump_through::<H, true, true>,
        ],
    ];
    /// The instruction followed by its next record's jump.
    const THEN: [[Handler; 2]; 2] = [
        [
            lane_then_jump::<H, false, false>,
            lane_then_jump::<H, false, true>,
        ],
        [
            lane_then_jump::<H, true, false>,
            lane_then_jump::<H, true, true>,
        ],
    ];
}

/// The scaled-index handlers, indexed by the shift's operand field (none,
/// `b`) and by whether the add takes the shifted value on its left.
struct ScaledIndex<H>(std::marker::PhantomData<H>);

impl<H: Host> ScaledIndex<H> {
    const HANDLERS: [[Handler; 2]; 2] = [
        [
            lane_shift_add::<H, ACC_NONE, false>,
            lane_shift_add::<H, ACC_NONE, true>,
        ],
        [
            lane_shift_add::<H, ACC_B, false>,
            lane_shift_add::<H, ACC_B, true>,
        ],
    ];
}

lane_handler! {
    /// An i32 add of a constant, the f64 load reading its sum, and the f64
    /// operator `SECOND` taking the loaded value as its left (`LEFT`) or
    /// right operand: three records run here, each result written as its
    /// own record writes it. Bits that need a box leave at the load.
    fn lane_add_load_f64<SECOND: u8, LEFT: bool>(cx, r, ip, i, view) {
        let sum = r.i32(i.b).wrapping_add(i.imm() as i32);
        r.set(i.a, view.integers.encode(sum));
        let load = following(ip);
        // SAFETY: the view fuses an add only with a following load and
        // float operator.
        let access = unsafe { &*load };
        let address = u64::from(sum as u32) + u64::from(access.imm());
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::F64(bits)) =
            (unsafe { view.memory.read(MemoryLoad::F64Load, address) })
        else {
            return exit(load);
        };
        let Some(loaded) = Value::from_bits64(bits) else {
            return exit(load);
        };
        r.set(access.a, loaded);
        let next = following(load);
        let second = unsafe { &*next };
        let first = f64::from_bits(bits);
        let (left, right) = if LEFT {
            (first, f64::from_bits(r.get(second.c).float_bits64()))
        } else {
            (f64::from_bits(r.get(second.b).float_bits64()), first)
        };
        let value = match f64_operation(SECOND, left, right) {
            Ok(result) => Value::from_float_bits64(result.to_bits()),
            Err(truth) => view.integers.encode(i32::from(truth)),
        };
        produce!(cx, r, next, second.a, value, view)
    }
}

macro_rules! add_load_f64_handlers {
    ($host:ty; $($second:expr),+) => {
        [$([
            lane_add_load_f64::<$host, $second, false> as Handler,
            lane_add_load_f64::<$host, $second, FUSED_LEFT> as Handler,
        ]),+]
    };
}

struct AddLoadF64<H>(std::marker::PhantomData<H>);

impl<H: Host> AddLoadF64<H> {
    /// By the float operator and whether the loaded value is its left
    /// operand.
    const HANDLERS: [[Handler; 2]; FLOAT_ARITHMETIC] = add_load_f64_handlers!(H;
        FLOAT_ADD, FLOAT_SUBTRACT, FLOAT_MULTIPLY, FLOAT_DIVIDE, FLOAT_EQUAL,
        FLOAT_NOT_EQUAL, FLOAT_LESS, FLOAT_GREATER, FLOAT_LESS_EQUAL, FLOAT_GREATER_EQUAL);
}

/// The fused add-and-load handler for direct load `op`.
/// The fused handler for direct load `load`, with address field `acc`, and
/// direct store `store` writing its value: copies of one value type.
fn load_store_handler<H: Host>(load: Op, store: Op, acc: u8) -> Option<Handler> {
    macro_rules! copies {
        ($(($load:ident, $store:ident)),+) => {
            match (load as u16, store as u16, acc) {
                $(
                    (opc::$load, opc::$store, ACC_NONE) => Some(lane_load_store::<H, { opc::$load }, { opc::$store }, ACC_NONE> as Handler),
                    (opc::$load, opc::$store, ACC_C) => Some(lane_load_store::<H, { opc::$load }, { opc::$store }, ACC_C> as Handler),
                )+
                _ => None,
            }
        };
    }
    copies!(
        (WasmI32Load, WasmI32Store),
        (WasmI32Load8U, WasmI32Store8),
        (WasmI64Load, WasmI64Store)
    )
}

/// The fused handler for i32 load `op`, with address field `acc`, the
/// branch table selecting on its value, and with `add` the plain add of a
/// constant ahead of the load.
fn load_table_handler<H: Host>(op: Op, acc: u8, add: bool) -> Option<Handler> {
    macro_rules! loads {
        ($($load:ident),+) => {
            match (op as u16, acc, add) {
                $(
                    (opc::$load, ACC_NONE, false) => Some(lane_load_table::<H, { opc::$load }, ACC_NONE, false> as Handler),
                    (opc::$load, ACC_C, false) => Some(lane_load_table::<H, { opc::$load }, ACC_C, false> as Handler),
                    (opc::$load, ACC_NONE, true) => Some(lane_load_table::<H, { opc::$load }, ACC_NONE, true> as Handler),
                    (opc::$load, ACC_C, true) => Some(lane_load_table::<H, { opc::$load }, ACC_C, true> as Handler),
                )+
                _ => None,
            }
        };
    }
    loads!(
        WasmI32Load,
        WasmI32Load8S,
        WasmI32Load8U,
        WasmI32Load16S,
        WasmI32Load16U
    )
}

const fn add_load_handler<H: Host>(op: Op) -> Option<Handler> {
    macro_rules! loads {
        ($($load:ident),+) => {
            match op as u16 {
                $(opc::$load => Some(lane_add_load::<H, { opc::$load }> as Handler),)+
                _ => None,
            }
        };
    }
    loads!(
        WasmI32Load,
        WasmI64Load,
        WasmF32Load,
        WasmF64Load,
        WasmI32Load8S,
        WasmI32Load8U,
        WasmI32Load16S,
        WasmI32Load16U,
        WasmI64Load8S,
        WasmI64Load8U,
        WasmI64Load16S,
        WasmI64Load16U,
        WasmI64Load32S,
        WasmI64Load32U
    )
}

lane_handler! {
    /// A direct load `LOAD`, with address field `ACC`, whose value the next
    /// record, direct store `STORE`, writes: both records run here, the value
    /// written to its register as the load writes it. An access the general
    /// path must run exits at its record.
    fn lane_load_store<LOAD: u16, STORE: u16, ACC: u8>(cx, r, ip, i, view) {
        let (load, store) = const {
            match (
                MemoryLoad::from_direct_op(opcode(LOAD)),
                MemoryStore::from_direct_op(opcode(STORE)),
            ) {
                (Some(load), Some(store)) => (load, store),
                _ => panic!("not a direct load and store"),
            }
        };
        // SAFETY: as for `lane_load`.
        let Some(value) = (unsafe { view.memory.read(load, lane_address::<ACC>(r, i, view)) })
        else {
            return exit(ip);
        };
        let Some(encoded) = lane_encode(view, value) else {
            return exit(ip);
        };
        r.set(i.a, encoded);
        let next = following(ip);
        // SAFETY: the view fuses a load only with a following store record.
        let access = unsafe { &*next };
        // SAFETY: as for `lane_load`.
        if unsafe { view.memory.write(store, lane_address::<ACC_NONE>(r, access, view), value) }
            .is_none()
        {
            return exit(next);
        }
        next!(cx, r, following(next), view)
    }
}

/// The direct load an instantiation serves.
const fn direct_load(op: u16) -> MemoryLoad {
    match MemoryLoad::from_direct_op(opcode(op)) {
        Some(load) => load,
        None => panic!("not a direct load"),
    }
}

lane_handler! {
    /// An i32 load, with address field `ACC`, whose value the next record, direct i32 load
    /// `SECOND`, takes as its address (a pointer chase, `p->field->member`): both records run
    /// here, each value written as its own record writes it. An access the general path must
    /// run exits at its record.
    fn lane_load_load<SECOND: u16, ACC: u8>(cx, r, ip, i, view) {
        let first = const { direct_load(opc::WasmI32Load) };
        let second = const { direct_load(SECOND) };
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(pointer)) =
            (unsafe { view.memory.read(first, lane_address::<ACC>(r, i, view)) })
        else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(pointer));
        let next = following(ip);
        // SAFETY: the view fuses a load only with a following load reading its value.
        let access = unsafe { &*next };
        let address = u64::from(pointer as u32) + u64::from(access.imm());
        // SAFETY: as for `lane_load`.
        let Some(value) = (unsafe { view.memory.read(second, address) }) else {
            return exit(next);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(next);
        };
        produce!(cx, r, next, access.a, value, view)
    }
}

lane_handler! {
    /// A direct i32 load `OP`, with address field `ACC`, whose value the next record, a
    /// zero-test jump without a carried register, tests (`p = p->next; while (p)`): both
    /// records run here, the value carried as the load carries it.
    fn lane_load_jump_i32_zero<OP: u16, ACC: u8, WHEN_ZERO: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        let load = const { direct_load(OP) };
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(value)) =
            (unsafe { view.memory.read(load, lane_address::<ACC>(r, i, view)) })
        else {
            return exit(ip);
        };
        let encoded = view.integers.encode(value);
        r.set(i.a, encoded);
        let view = Carried { acc: Slot::of(encoded), ..view };
        let next = following(ip);
        if (value == 0) == WHEN_ZERO {
            resume!(cx, lane_jump::<H>(r, next, BACKWARD, view, None));
        }
        next!(cx, r, following(next), view)
    }
}

lane_handler! {
    /// A move, reading its source through field `ACC`, whose moved value the next record,
    /// direct i32 load `OP`, takes as its address: both records run here, each value written
    /// as its own record writes it.
    fn lane_move_load<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let load = const { direct_load(OP) };
        let moved = read::<ACC, ACC_B>(r, i.b, view);
        r.set(i.a, moved);
        let next = following(ip);
        // SAFETY: the view fuses a move only with a following load reading its value.
        let access = unsafe { &*next };
        let address = u64::from(moved.wasm_bits32()) + u64::from(access.imm());
        // SAFETY: as for `lane_load`.
        let Some(value) = (unsafe { view.memory.read(load, address) }) else {
            return exit(next);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(next);
        };
        produce!(cx, r, next, access.a, value, view)
    }
}

lane_handler! {
    /// A direct store `OP`, reading through field `ACC`, followed by a move: both records run
    /// here, the moved value carried as the move carries it.
    fn lane_store_move<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let store = const {
            match MemoryStore::from_direct_op(opcode(OP)) {
                Some(store) => store,
                None => panic!("not a direct store"),
            }
        };
        let Some(value) = stored_value(store, read::<ACC, ACC_A>(r, i.a, view)) else {
            return exit(ip);
        };
        // SAFETY: as for `lane_load`.
        if unsafe { view.memory.write(store, lane_address::<ACC>(r, i, view), value) }
            .is_none()
        {
            return exit(ip);
        }
        let next = following(ip);
        // SAFETY: the view fuses a store only with a following move.
        let moved = unsafe { &*next };
        produce!(cx, r, next, moved.a, r.get(moved.b), view)
    }
}

lane_handler! {
    /// Two direct i32 loads `LOAD` and the i32 register operator `OP` combining their values
    /// (`a[i] * b[j]`), the first value as its left operand when `FIRST_LEFT`: three records
    /// run here, the loads issued together, each value written as its own record writes it.
    /// An access the general path must run exits at its record.
    fn lane_load_pair_binary<LOAD: u16, OP: u16, FIRST_LEFT: bool>(cx, r, ip, i, view) {
        let load = const { direct_load(LOAD) };
        let operator = const {
            match I32BinaryOperator::from_register_op(opcode(OP)) {
                Some(operator) => operator,
                None => panic!("not an i32 register operator"),
            }
        };
        let second_ip = following(ip);
        // SAFETY: the view fuses a load only with a following load and operator.
        let second_record = unsafe { &*second_ip };
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(first)) =
            (unsafe { view.memory.read(load, lane_address::<ACC_NONE>(r, i, view)) })
        else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(first));
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(second)) =
            (unsafe { view.memory.read(load, lane_address::<ACC_NONE>(r, second_record, view)) })
        else {
            return exit(second_ip);
        };
        r.set(second_record.a, view.integers.encode(second));
        let combine = following(second_ip);
        // SAFETY: as above.
        let o = unsafe { &*combine };
        let (left, right) = if FIRST_LEFT { (first, second) } else { (second, first) };
        let Ok(result) = operator.evaluate(left, right) else {
            return exit(combine);
        };
        produce!(cx, r, combine, o.a, view.integers.encode(result), view)
    }
}

/// The load-pair handler for i32 load `load` and register operator `op`.
fn load_pair_binary_handler<H: Host>(load: Op, op: Op, first_left: bool) -> Option<Handler> {
    macro_rules! pairs {
        ($(($load:ident, $op:ident)),+) => {
            match (load as u16, op as u16, first_left) {
                $(
                    (opc::$load, opc::$op, false) => Some(lane_load_pair_binary::<H, { opc::$load }, { opc::$op }, false> as Handler),
                    (opc::$load, opc::$op, true) => Some(lane_load_pair_binary::<H, { opc::$load }, { opc::$op }, true> as Handler),
                )+
                _ => None,
            }
        };
    }
    pairs!(
        (WasmI32Load, WasmI32Add),
        (WasmI32Load, WasmI32Multiply),
        (WasmI32Load16S, WasmI32Multiply),
        (WasmI32Load16U, WasmI32Multiply),
        (WasmI32Load8U, WasmI32Add)
    )
}

lane_handler! {
    /// An i32 add or subtract of a constant (`FIRST`), reading through field `ACC`, the and of
    /// a constant over its result, and the immediate comparison jump `JUMP` testing that
    /// (`(c - '0') & 0xff <= 9`): three records run here, each result written as its own
    /// record writes it.
    fn lane_offset_mask_jump<FIRST: u16, JUMP: u16, BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let offset = const {
            match I32BinaryOperator::from_immediate_op(opcode(FIRST)) {
                Some(operator) => operator,
                None => panic!("not an i32 immediate operator"),
            }
        };
        let comparison = const {
            match I32BinaryOperator::from_immediate_jump_op(opcode(JUMP)) {
                Some(comparison) => comparison,
                None => panic!("not an i32 immediate comparison jump"),
            }
        };
        let Ok(shifted) = offset.evaluate(read_i32::<ACC, ACC_B>(r, i.b, view), i.imm() as i32) else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(shifted));
        let mask_ip = following(ip);
        // SAFETY: the view fuses an offset only with a following mask and comparison jump.
        let mask = unsafe { &*mask_ip };
        let masked = shifted & (mask.imm() as i32);
        let encoded = view.integers.encode(masked);
        r.set(mask.a, encoded);
        let view = Carried { acc: Slot::of(encoded), ..view };
        let jump_ip = following(mask_ip);
        // SAFETY: as above.
        let jump = unsafe { &*jump_ip };
        let Ok(taken) = comparison.evaluate(masked, i32::from(jump.b as i16)) else {
            return exit(jump_ip);
        };
        if taken != 0 {
            resume!(cx, lane_jump::<H>(r, jump_ip, BACKWARD, view, None));
        }
        next!(cx, r, following(jump_ip), view)
    }
}

/// The offset-mask-test handler for offset operator `first`, immediate comparison jump `jump`.
fn offset_mask_jump_handler<H: Host>(first: Op, jump: Op, backward: bool, acc: u8) -> Option<Handler> {
    macro_rules! jumps {
        ($first:ident; $($jump:ident),+) => {
            match (jump as u16, backward, acc) {
                $(
                    (opc::$jump, false, ACC_NONE) => Some(lane_offset_mask_jump::<H, { opc::$first }, { opc::$jump }, false, ACC_NONE> as Handler),
                    (opc::$jump, true, ACC_NONE) => Some(lane_offset_mask_jump::<H, { opc::$first }, { opc::$jump }, true, ACC_NONE> as Handler),
                    (opc::$jump, false, ACC_B) => Some(lane_offset_mask_jump::<H, { opc::$first }, { opc::$jump }, false, ACC_B> as Handler),
                    (opc::$jump, true, ACC_B) => Some(lane_offset_mask_jump::<H, { opc::$first }, { opc::$jump }, true, ACC_B> as Handler),
                )+
                _ => None,
            }
        };
    }
    macro_rules! tested {
        ($first:ident) => {
            jumps!(
                $first;
                WasmJumpI32EqualImmediate,
                WasmJumpI32NotEqualImmediate,
                WasmJumpI32LessUnsignedImmediate,
                WasmJumpI32LessEqualUnsignedImmediate,
                WasmJumpI32GreaterUnsignedImmediate,
                WasmJumpI32GreaterEqualUnsignedImmediate
            )
        };
    }
    match first {
        op if op.is_wasm_i32_add_immediate() => tested!(WasmI32AddImmediate),
        op if op.is_wasm_i32_subtract_immediate() => tested!(WasmI32SubtractImmediate),
        _ => None,
    }
}

lane_handler! {
    /// A bit-field extraction, reading its operand through field `ACC`, and a following i32
    /// operator `SECOND` (another extraction, or an operator of registers or a constant): both
    /// records run here, the extraction written before the operator reads its operands.
    fn lane_bit_field_then<SECOND: u16, ACC: u8>(cx, r, ip, i, view) {
        let (operator, immediate) = const {
            let second = opcode(SECOND);
            if second.class().eq(Class::WasmI32ShiftRightUnsignedAnd) { (None, true) }
            else if let Some(operator) = I32BinaryOperator::from_register_op(second) { (Some(operator), false) }
            else if let Some(operator) = I32BinaryOperator::from_immediate_op(second) { (Some(operator), true) }
            else { panic!("not an i32 operator") }
        };
        let field = crate::wasm::integer::shift_right_unsigned_and(
            read_i32::<ACC, ACC_B>(r, i.b, view),
            i32::from(i.c as i16),
            i.imm() as i32,
        );
        r.set(i.a, view.integers.encode(field));
        let second_ip = following(ip);
        // SAFETY: the view fuses an extraction only with a following i32 operator.
        let second = unsafe { &*second_ip };
        let value = match operator {
            None => crate::wasm::integer::shift_right_unsigned_and(
                r.i32(second.b),
                i32::from(second.c as i16),
                second.imm() as i32,
            ),
            Some(operator) => {
                let right = if immediate { second.imm() as i32 } else { r.i32(second.c) };
                let Ok(value) = operator.evaluate(r.i32(second.b), right) else {
                    return exit(second_ip);
                };
                value
            }
        };
        produce!(cx, r, second_ip, second.a, view.integers.encode(value), view)
    }
}

/// The extraction-then-operator handler for i32 operator `second`, the extraction read
/// through field `acc`.
fn bit_field_then_handler<H: Host>(second: Op, acc: u8) -> Option<Handler> {
    macro_rules! seconds {
        ($($second:ident),+) => {
            match (second as u16, acc) {
                $(
                    (opc::$second, ACC_NONE) => Some(lane_bit_field_then::<H, { opc::$second }, ACC_NONE> as Handler),
                    (opc::$second, ACC_B) => Some(lane_bit_field_then::<H, { opc::$second }, ACC_B> as Handler),
                )+
                _ => None,
            }
        };
    }
    seconds!(WasmI32ShiftRightUnsignedAndImmediate, WasmI32Multiply, WasmI32XorImmediate)
}

lane_handler! {
    /// An immediate comparison jump `JUMP`, reading its operand through field `ACC`, that
    /// falls through to direct i32 load `LOAD` (`if c == k goto L; v = *p`): both records run
    /// here, the load only when the jump falls through.
    fn lane_compare_jump_load<JUMP: u16, LOAD: u16, BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let comparison = const {
            match I32BinaryOperator::from_immediate_jump_op(opcode(JUMP)) {
                Some(comparison) => comparison,
                None => panic!("not an i32 immediate comparison jump"),
            }
        };
        let load = const { direct_load(LOAD) };
        let Ok(taken) = comparison.evaluate(read_i32::<ACC, ACC_A>(r, i.a, view), i32::from(i.b as i16)) else {
            return exit(ip);
        };
        if taken != 0 {
            resume!(cx, lane_jump::<H>(r, ip, BACKWARD, view, None));
        }
        let load_ip = following(ip);
        // SAFETY: the view fuses a comparison jump only with a following plain load.
        let access = unsafe { &*load_ip };
        let address = u64::from(r.get(access.c).wasm_bits32()) + u64::from(access.imm());
        // SAFETY: as for `lane_load`.
        let Some(value) = (unsafe { view.memory.read(load, address) }) else {
            return exit(load_ip);
        };
        let Some(value) = lane_encode(view, value) else {
            return exit(load_ip);
        };
        produce!(cx, r, load_ip, access.a, value, view)
    }
}

/// The compare-jump-load handler for immediate comparison jump `jump` and i32 load `load`.
fn compare_jump_load_handler<H: Host>(jump: Op, load: Op, backward: bool, acc: u8) -> Option<Handler> {
    macro_rules! accs {
        ($jump:ident, $load:ident) => {
            match (backward, acc) {
                (false, ACC_NONE) => Some(lane_compare_jump_load::<H, { opc::$jump }, { opc::$load }, false, ACC_NONE> as Handler),
                (true, ACC_NONE) => Some(lane_compare_jump_load::<H, { opc::$jump }, { opc::$load }, true, ACC_NONE> as Handler),
                (false, ACC_A) => Some(lane_compare_jump_load::<H, { opc::$jump }, { opc::$load }, false, ACC_A> as Handler),
                (true, ACC_A) => Some(lane_compare_jump_load::<H, { opc::$jump }, { opc::$load }, true, ACC_A> as Handler),
                _ => None,
            }
        };
    }
    macro_rules! loads {
        ($jump:ident) => {
            match load.class() {
                Class::WasmI32Load => accs!($jump, WasmI32Load),
                Class::WasmI32Load8U => accs!($jump, WasmI32Load8U),
                _ => None,
            }
        };
    }
    match jump.class() {
        Class::WasmJumpI32EqualImmediate => loads!(WasmJumpI32EqualImmediate),
        Class::WasmJumpI32NotEqualImmediate => loads!(WasmJumpI32NotEqualImmediate),
        _ => None,
    }
}

lane_handler! {
    /// Two i32 adds (`FIRST`, reading through field `ACC`, then `SECOND`), each of a register
    /// or a constant, or an add and a counted loop's step and test (`SECOND` is
    /// `WasmI32AddImmediateJumpNonZero`): a strided loop's pointer and counter updates. The
    /// first result is written before the second reads its operands, as two records do.
    fn lane_add_pair<FIRST: u16, SECOND: u16, BACKWARD: bool, ACC: u8>(cx, r, ip, i, view) {
        let first_immediate = const {
            match opcode(FIRST).class() {
                Class::WasmI32AddRegister => false,
                Class::WasmI32AddImmediate => true,
                _ => panic!("not an i32 add"),
            }
        };
        let right = if first_immediate { i.imm() as i32 } else { read_i32::<ACC, ACC_C>(r, i.c, view) };
        let first = view.integers.encode(read_i32::<ACC, ACC_B>(r, i.b, view).wrapping_add(right));
        r.set(i.a, first);
        let second_ip = following(ip);
        // SAFETY: the view fuses an add only with a following add or loop step.
        let second = unsafe { &*second_ip };
        let view = Carried { acc: Slot::of(first), ..view };
        match const { opcode(SECOND).class() } {
            Class::WasmI32AddJump => {
                let sum = r.i32(second.b).wrapping_add(i32::from(second.c as i16));
                let encoded = view.integers.encode(sum);
                if sum != 0 {
                    resume!(cx, lane_jump::<H>(r, second_ip, BACKWARD, view, Some((second.a, encoded))));
                }
                produce!(cx, r, second_ip, second.a, encoded, view)
            }
            Class::WasmI32AddImmediate => {
                let sum = r.i32(second.b).wrapping_add(second.imm() as i32);
                produce!(cx, r, second_ip, second.a, view.integers.encode(sum), view)
            }
            _ => {
                let sum = r.i32(second.b).wrapping_add(r.i32(second.c));
                produce!(cx, r, second_ip, second.a, view.integers.encode(sum), view)
            }
        }
    }
}

/// The add-pair handler for add `first` read through field `acc`, then `second`.
fn add_pair_handler<H: Host>(first: Op, second: Op, backward: bool, acc: u8) -> Option<Handler> {
    macro_rules! accs {
        ($first:ident, $second:ident, $backward:literal) => {
            match acc {
                ACC_NONE => Some(lane_add_pair::<H, { opc::$first }, { opc::$second }, $backward, ACC_NONE> as Handler),
                ACC_B => Some(lane_add_pair::<H, { opc::$first }, { opc::$second }, $backward, ACC_B> as Handler),
                ACC_C => Some(lane_add_pair::<H, { opc::$first }, { opc::$second }, $backward, ACC_C> as Handler),
                _ => None,
            }
        };
    }
    macro_rules! seconds {
        ($first:ident) => {
            match (second.class(), backward) {
                (Class::WasmI32AddRegister, _) => accs!($first, WasmI32Add, false),
                (Class::WasmI32AddImmediate, _) => accs!($first, WasmI32AddImmediate, false),
                (Class::WasmI32AddJump, false) => accs!($first, WasmI32AddImmediateJumpNonZero, false),
                (Class::WasmI32AddJump, true) => accs!($first, WasmI32AddImmediateJumpNonZero, true),
                _ => None,
            }
        };
    }
    match first.class() {
        Class::WasmI32AddRegister => seconds!(WasmI32Add),
        Class::WasmI32AddImmediate => seconds!(WasmI32AddImmediate),
        _ => None,
    }
}

lane_handler! {
    /// An i32 operator of a constant (`FIRST`) and the register comparison jump `JUMP` reading
    /// its result as either operand (`(x & mask) == y`): two records run here, the result
    /// written as its own record writes it.
    fn lane_immediate_compare_jump<FIRST: u16, JUMP: u16, BACKWARD: bool>(cx, r, ip, i, view) {
        let operator = const {
            match I32BinaryOperator::from_immediate_op(opcode(FIRST)) {
                Some(operator) => operator,
                None => panic!("not an i32 immediate operator"),
            }
        };
        let comparison = const {
            match I32BinaryOperator::from_jump_op(opcode(JUMP)) {
                Some(comparison) => comparison,
                None => panic!("not an i32 register comparison jump"),
            }
        };
        let Ok(result) = operator.evaluate(r.i32(i.b), i.imm() as i32) else {
            return exit(ip);
        };
        let encoded = view.integers.encode(result);
        r.set(i.a, encoded);
        let view = Carried { acc: Slot::of(encoded), ..view };
        let jump_ip = following(ip);
        // SAFETY: the view fuses an immediate operator only with a following comparison jump.
        let jump = unsafe { &*jump_ip };
        let operand = |register: u16| if register == i.a { result } else { r.i32(register) };
        let Ok(taken) = comparison.evaluate(operand(jump.a), operand(jump.b)) else {
            return exit(jump_ip);
        };
        if taken != 0 {
            resume!(cx, lane_jump::<H>(r, jump_ip, BACKWARD, view, None));
        }
        next!(cx, r, following(jump_ip), view)
    }
}

/// The immediate-operator comparison-jump handler for operator `first`, register comparison
/// jump `jump`.
fn immediate_compare_jump_handler<H: Host>(first: Op, jump: Op, backward: bool) -> Option<Handler> {
    macro_rules! jumps {
        ($first:ident; $($jump:ident),+) => {
            match (jump as u16, backward) {
                $(
                    (opc::$jump, false) => Some(lane_immediate_compare_jump::<H, { opc::$first }, { opc::$jump }, false> as Handler),
                    (opc::$jump, true) => Some(lane_immediate_compare_jump::<H, { opc::$first }, { opc::$jump }, true> as Handler),
                )+
                _ => None,
            }
        };
    }
    macro_rules! tested {
        ($first:ident) => {
            jumps!($first; WasmJumpI32Equal, WasmJumpI32NotEqual)
        };
    }
    // Masked tag tests; each further pairing is another family of handler copies.
    match first as u16 {
        opc::WasmI32AndImmediate => tested!(WasmI32AndImmediate),
        _ => None,
    }
}

lane_handler! {
    /// An i32 operator `OP` (reading through field `ACC`; a comparison, typically), a constant
    /// load and a select choosing among their results and other registers (`cur = cur > clip
    /// ? 0 : cur`): three records run here, each result written as its own record writes it,
    /// and the select reads the two results as computed rather than back from registers.
    fn lane_operator_constant_select<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let (operator, immediate) = const {
            match I32BinaryOperator::from_register_op(opcode(OP)) {
                Some(operator) => (operator, false),
                None => match I32BinaryOperator::from_immediate_op(opcode(OP)) {
                    Some(operator) => (operator, true),
                    None => panic!("not an i32 binary operator"),
                },
            }
        };
        let right = if immediate { i.imm() as i32 } else { read_i32::<ACC, ACC_C>(r, i.c, view) };
        let Ok(result) = operator.evaluate(read_i32::<ACC, ACC_B>(r, i.b, view), right) else {
            return exit(ip);
        };
        let result = view.integers.encode(result);
        r.set(i.a, result);
        let constant_ip = following(ip);
        // SAFETY: the view fuses an operator only with a following constant and select.
        let load = unsafe { &*constant_ip };
        let constant = load.constant();
        r.set(load.a, constant);
        let select_ip = following(constant_ip);
        // SAFETY: as above.
        let select = unsafe { &*select_ip };
        // The constant's record runs second, so it wins a register both write.
        let value_of = |register: u16| {
            if register == load.a {
                constant
            } else if register == i.a {
                result
            } else {
                r.get(register)
            }
        };
        let (condition, _) = ImmediateLayout::register_pair(select.imm());
        let value = select_loaded(
            value_of(condition).wasm_bits32() != 0,
            value_of(select.b),
            value_of(select.c),
        );
        produce!(cx, r, select_ip, select.a, value, view)
    }
}

/// The operator-constant-select handler for i32 operator `op` reading through field `acc`.
fn operator_constant_select_handler<H: Host>(op: Op, acc: u8) -> Option<Handler> {
    macro_rules! operators {
        ($($op:ident),+) => {
            match (op as u16, acc) {
                $(
                    (opc::$op, ACC_NONE) => Some(lane_operator_constant_select::<H, { opc::$op }, ACC_NONE> as Handler),
                    (opc::$op, ACC_B) => Some(lane_operator_constant_select::<H, { opc::$op }, ACC_B> as Handler),
                    (opc::$op, ACC_C) => Some(lane_operator_constant_select::<H, { opc::$op }, ACC_C> as Handler),
                )+
                _ => None,
            }
        };
    }
    operators!(
        WasmI32GreaterSigned,
        WasmI32GreaterUnsigned,
        WasmI32LessSigned,
        WasmI32LessUnsigned,
        WasmI32Equal,
        WasmI32NotEqual,
        WasmI32GreaterEqualSigned,
        WasmI32LessEqualSigned
    )
}

/// The i32 loads the load fusions below serve.
macro_rules! i32_loads {
    ($m:ident) => {
        $m!(WasmI32Load, WasmI32Load8S, WasmI32Load8U, WasmI32Load16S, WasmI32Load16U)
    };
}


/// The pointer-chase handler whose second load is `op`.
fn load_load_handler<H: Host>(op: Op, acc: u8) -> Option<Handler> {
    macro_rules! loads {
        ($($load:ident),+) => {
            match (op as u16, acc) {
                $(
                    (opc::$load, ACC_NONE) => Some(lane_load_load::<H, { opc::$load }, ACC_NONE> as Handler),
                    (opc::$load, ACC_C) => Some(lane_load_load::<H, { opc::$load }, ACC_C> as Handler),
                )+
                _ => None,
            }
        };
    }
    i32_loads!(loads)
}

/// The load-and-test handler for i32 load `op` with address field `acc`, jumping on zero
/// (`zero`) in direction `backward`.
fn load_jump_handler<H: Host>(op: Op, acc: u8, zero: bool, backward: bool) -> Option<Handler> {
    macro_rules! loads {
        ($($load:ident),+) => {
            match (op as u16, acc, zero, backward) {
                $(
                    (opc::$load, ACC_NONE, false, false) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_NONE, false, false> as Handler),
                    (opc::$load, ACC_NONE, false, true) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_NONE, false, true> as Handler),
                    (opc::$load, ACC_NONE, true, false) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_NONE, true, false> as Handler),
                    (opc::$load, ACC_NONE, true, true) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_NONE, true, true> as Handler),
                    (opc::$load, ACC_C, false, false) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_C, false, false> as Handler),
                    (opc::$load, ACC_C, false, true) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_C, false, true> as Handler),
                    (opc::$load, ACC_C, true, false) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_C, true, false> as Handler),
                    (opc::$load, ACC_C, true, true) => Some(lane_load_jump_i32_zero::<H, { opc::$load }, ACC_C, true, true> as Handler),
                )+
                _ => None,
            }
        };
    }
    i32_loads!(loads)
}

/// The move-then-load handler for i32 load `op`, the move reading through field `acc`.
fn move_load_handler<H: Host>(op: Op, acc: u8) -> Option<Handler> {
    macro_rules! loads {
        ($($load:ident),+) => {
            match (op as u16, acc) {
                $(
                    (opc::$load, ACC_NONE) => Some(lane_move_load::<H, { opc::$load }, ACC_NONE> as Handler),
                    (opc::$load, ACC_B) => Some(lane_move_load::<H, { opc::$load }, ACC_B> as Handler),
                )+
                _ => None,
            }
        };
    }
    i32_loads!(loads)
}

lane_handler! {
    /// A plain direct store `OP`, a move and a zero-test jump (`WHEN_ZERO`, `BACKWARD`) testing
    /// the register the record before them carries as the accumulator, which the taken jump
    /// carries on to its target (a loop latch whose head reads the register there): three
    /// records run here, the moved value carried as the move carries it when falling through.
    fn lane_store_move_jump_i32_zero<OP: u16, WHEN_ZERO: bool, BACKWARD: bool>(cx, r, ip, i, view) {
        let store = const {
            match MemoryStore::from_direct_op(opcode(OP)) {
                Some(store) => store,
                None => panic!("not a direct store"),
            }
        };
        // SAFETY: the view selects this record only after the producer that set it.
        let tested = unsafe { view.acc.get() };
        let Some(value) = stored_value(store, r.get(i.a)) else {
            return exit(ip);
        };
        // SAFETY: as for `lane_load`.
        if unsafe { view.memory.write(store, lane_address::<ACC_NONE>(r, i, view), value) }
            .is_none()
        {
            return exit(ip);
        }
        let move_ip = following(ip);
        // SAFETY: the view fuses a store only with a following move and zero-test jump.
        let moved = unsafe { &*move_ip };
        let value = r.get(moved.b);
        r.set(moved.a, value);
        let jump_ip = following(move_ip);
        if (tested.wasm_bits32() == 0) == WHEN_ZERO {
            resume!(cx, lane_jump::<H>(r, jump_ip, BACKWARD, Carried { acc: Slot::of(tested), ..view }, None));
        }
        next!(cx, r, following(jump_ip), Carried { acc: Slot::of(value), ..view })
    }
}

/// The store-move-latch handler for direct store `op`.
fn store_move_jump_handler<H: Host>(op: Op, zero: bool, backward: bool) -> Option<Handler> {
    macro_rules! stores {
        ($($store:ident),+) => {
            match (op as u16, zero, backward) {
                $(
                    (opc::$store, false, false) => Some(lane_store_move_jump_i32_zero::<H, { opc::$store }, false, false> as Handler),
                    (opc::$store, false, true) => Some(lane_store_move_jump_i32_zero::<H, { opc::$store }, false, true> as Handler),
                    (opc::$store, true, false) => Some(lane_store_move_jump_i32_zero::<H, { opc::$store }, true, false> as Handler),
                    (opc::$store, true, true) => Some(lane_store_move_jump_i32_zero::<H, { opc::$store }, true, true> as Handler),
                )+
                _ => None,
            }
        };
    }
    stores!(WasmI32Store, WasmI32Store8, WasmI32Store16)
}

/// The store-then-move handler for direct store `op` reading through field `acc`.
fn store_move_handler<H: Host>(op: Op, acc: u8) -> Option<Handler> {
    macro_rules! stores {
        ($($store:ident),+) => {
            match (op as u16, acc) {
                $(
                    (opc::$store, ACC_NONE) => Some(lane_store_move::<H, { opc::$store }, ACC_NONE> as Handler),
                    (opc::$store, ACC_A) => Some(lane_store_move::<H, { opc::$store }, ACC_A> as Handler),
                    (opc::$store, ACC_C) => Some(lane_store_move::<H, { opc::$store }, ACC_C> as Handler),
                )+
                _ => None,
            }
        };
    }
    stores!(WasmI32Store, WasmI32Store8, WasmI32Store16)
}

/// The scalar direct store `store` writes for slot value `value`: registers
/// hold their static Wasm types, and a value whose bits need a box has none.
#[inline(always)]
fn stored_value(store: MemoryStore, value: Value) -> Option<crate::WasmValue> {
    Some(match store.value_type() {
        crate::WasmType::I32 => crate::WasmValue::I32(value.wasm_bits32() as i32),
        crate::WasmType::F32 => crate::WasmValue::F32(value.as_int()? as u32),
        crate::WasmType::I64 => crate::WasmValue::I64(value.bits64()? as i64),
        crate::WasmType::F64 => crate::WasmValue::F64(value.bits64()?),
        _ => return None,
    })
}

lane_handler! {
    fn lane_store<OP: u16, ACC: u8>(cx, r, ip, i, view) {
        let store = const {
            match MemoryStore::from_direct_op(opcode(OP)) {
                Some(store) => store,
                None => panic!("not a direct store"),
            }
        };
        let Some(value) = stored_value(store, read::<ACC, ACC_A>(r, i.a, view)) else {
            return exit(ip);
        };
        // SAFETY: as for `lane_load`.
        if unsafe { view.memory.write(store, lane_address::<ACC>(r, i, view), value) }
            .is_none()
        {
            return exit(ip);
        }
        next!(cx, r, following(ip), view)
    }
}

lane_handler! {
    /// An i32 load, with address field `ACC`, the i32 operator `OP` taking
    /// the loaded value as its left (`LEFT`) or right operand, and the i32
    /// store writing the operator's result (`mem[x] op= v`): three records
    /// run here, each result written as its own record writes it. An access
    /// the general path must run, or a trapping operator, exits at its
    /// record.
    fn lane_i32_update<OP: u16, LEFT: bool, ACC: u8>(cx, r, ip, i, view) {
        let operator = const {
            match I32BinaryOperator::from_register_op(opcode(OP)) {
                Some(operator) => operator,
                None => panic!("not an i32 register operator"),
            }
        };
        // SAFETY: as for `lane_load`.
        let Some(crate::WasmValue::I32(loaded)) = (unsafe {
            view.memory.read(MemoryLoad::I32Load, lane_address::<ACC>(r, i, view))
        }) else {
            return exit(ip);
        };
        r.set(i.a, view.integers.encode(loaded));
        let combine = following(ip);
        // SAFETY: the view fuses a load only with a following operator and
        // store.
        let o = unsafe { &*combine };
        let (left, right) = if LEFT { (loaded, r.i32(o.c)) } else { (r.i32(o.b), loaded) };
        let Ok(result) = operator.evaluate(left, right) else {
            return exit(combine);
        };
        r.set(o.a, view.integers.encode(result));
        let store = following(combine);
        // SAFETY: as above.
        let access = unsafe { &*store };
        // SAFETY: as for `lane_store`.
        if unsafe {
            view.memory.write(
                MemoryStore::I32Store,
                lane_address::<ACC_NONE>(r, access, view),
                crate::WasmValue::I32(result),
            )
        }
        .is_none()
        {
            return exit(store);
        }
        next!(cx, r, following(store), view)
    }
}

/// The i32 update handler for register operator `op`, loaded value side
/// `left` and load address field `acc`.
fn i32_update_handler<H: Host>(op: Op, left: bool, acc: u8) -> Option<Handler> {
    macro_rules! updates {
        ($($op:ident),+) => {
            match (op as u16, left, acc) {
                $(
                    (opc::$op, false, ACC_NONE) => Some(lane_i32_update::<H, { opc::$op }, false, ACC_NONE> as Handler),
                    (opc::$op, true, ACC_NONE) => Some(lane_i32_update::<H, { opc::$op }, true, ACC_NONE> as Handler),
                    (opc::$op, false, ACC_C) => Some(lane_i32_update::<H, { opc::$op }, false, ACC_C> as Handler),
                    (opc::$op, true, ACC_C) => Some(lane_i32_update::<H, { opc::$op }, true, ACC_C> as Handler),
                )+
                _ => None,
            }
        };
    }
    updates!(
        WasmI32Add,
        WasmI32Subtract,
        WasmI32Multiply,
        WasmI32And,
        WasmI32Or,
        WasmI32Xor,
        WasmI32ShiftLeft,
        WasmI32ShiftRightSigned,
        WasmI32ShiftRightUnsigned,
        WasmI32Equal,
        WasmI32NotEqual,
        WasmI32LessSigned,
        WasmI32LessUnsigned
    )
}

lane_handler! {
    /// A constant that the next record, direct store `OP`, writes to
    /// memory: both records run here, the constant written to its register
    /// as its own record writes it.
    fn lane_constant_store<OP: u16>(cx, r, ip, i, view) {
        let store = const {
            match MemoryStore::from_direct_op(opcode(OP)) {
                Some(store) => store,
                None => panic!("not a direct store"),
            }
        };
        let constant = i.constant();
        r.set(i.a, constant);
        let next = following(ip);
        // SAFETY: the view fuses a constant only with a following store.
        let access = unsafe { &*next };
        let Some(value) = stored_value(store, constant) else {
            return exit(next);
        };
        // SAFETY: as for `lane_load`.
        if unsafe { view.memory.write(store, lane_address::<ACC_NONE>(r, access, view), value) }
            .is_none()
        {
            return exit(next);
        }
        next!(cx, r, following(next), view)
    }
}

/// The constant-store handler for direct store `op`.
const fn constant_store_handler<H: Host>(op: Op) -> Option<Handler> {
    macro_rules! stores {
        ($($store:ident),+) => {
            match op as u16 {
                $(opc::$store => Some(lane_constant_store::<H, { opc::$store }> as Handler),)+
                _ => None,
            }
        };
    }
    stores!(
        WasmI32Store,
        WasmI64Store,
        WasmF32Store,
        WasmF64Store,
        WasmI32Store8,
        WasmI32Store16,
        WasmI64Store8,
        WasmI64Store16,
        WasmI64Store32
    )
}

/// Continue in `frame` at `pc`: the record the frame's function resumes at.
#[inline(always)]
fn lane_enter_frame<H: Host>(cx: *mut LaneContext<H>, frame: usize, pc: usize) -> Resumed {
    let (r, ip, view) = lane_frame_state(cx, frame, pc);
    // A frame call or return reached from an out-of-line path may nest rather than run as a
    // sibling, so a run of calls and returns with no backward jump between them grew the
    // stack until it overflowed (mandreel). Below the floor the lane loop dispatches the
    // record instead, from the frame state the context now holds.
    if script_below_floor(cx) {
        return Resumed::Exit(ip);
    }
    Resumed::At(r, ip, view)
}

/// Make `frame` the lane's running function, at the record of `pc`: its registers, that
/// record and the state its records start from.
#[inline(always)]
fn lane_frame_state<H: Host>(
    cx: *mut LaneContext<H>,
    frame: usize,
    pc: usize,
) -> (Registers, Ip, Carried) {
    let vm = unsafe { vm(cx) };
    let function = vm.frames[frame].function;
    let program = unsafe { (*cx).program };
    // The context's table holds the frame's program's views: a derived one is read there.
    // SAFETY: the table lives as long as its program entry.
    let derived = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view);
    let lane_view = match derived {
        Some(view) => view,
        None => {
            if !H::RUNS_LANE {
                unreachable!("a host that runs no lane has no lane frame");
            }
            let (diagnostics, tiers) = (vm.programs.reports_on_drop(), vm.programs.tiers());
            let Some(lane_view) = vm.programs.lane_view(program, function, |code, constants, kind, live, sites| {
                derive_lane_view::<H>(
                    function,
                    code,
                    constants,
                    &vm.heap,
                    kind,
                    live,
                    sites,
                    vm.tier_may_run(crate::jit_mode::Tier::ANY),
                    diagnostics,
                    tiers,
                )
            }) else {
                unreachable!("an inline Wasm frame runs a function of its program");
            };
            // SAFETY: views live as long as their program entry.
            unsafe { &*lane_view }
        }
    };
    let base = lane_view.records();
    let r = Registers(vm.frames[frame].registers.as_mut_ptr());
    let view = frame_memory_view(cx, lane_view, r);
    // SAFETY: the view has one record per instruction of the function, and
    // `pc` is the frame's validated resume point.
    let ip = unsafe { base.add(pc) };
    // The general path's register access names the active frame's register file.
    vm.active_registers = r.0;
    unsafe {
        (*cx).root = LaneRoot::Frame(frame);
        (*cx).registers = r;
        (*cx).base = base;
        (*cx).memory = view;
        r.set_this(vm.frame_lane_this(frame));
        r.set_env(Value::DELETED);
        (*cx).registers.set_capture(std::ptr::null());
        (*cx).outer = NO_OUTER_WALK;
        (*cx).root_walk = NO_OUTER_WALK;
    }
    let view = Carried {
        memory: view,
        integers: crate::value::IntegerEncoding::TAG,
        acc: Slot::of(Value::UNDEFINED),
    };
    (r, ip, view)
}

impl<H: Host> Vm<H> {
    /// Make the lane's activations VM frames, innermost last, each with the
    /// pending call its push would have recorded; the lane continues in the
    /// innermost one. The bottom caller is the lane run's VM frame.
    /// Whether a lane may call `native` (the function `callee`) beside its activations
    /// (`Native::runs_beside_activations`, `Host::host_function_runs_beside_activations`).
    fn runs_beside_activations(&self, native: Native, callee: Value) -> bool {
        if native != Native::HostFunction {
            return native.runs_beside_activations();
        }
        let Some(index) = self.heap.function(callee).and_then(|function| self.host_operation_index(function.env)) else {
            return false;
        };
        self.host.host_function_runs_beside_activations(index as usize)
    }

    /// Whether `native` called on `receiver` runs beside activations as the natives of
    /// `runs_beside_activations` do: `%IteratorPrototype%.next` of an array, string, map or set
    /// iterator, whose step reads its source alone. A generator's step resumes its frame and an
    /// iterator helper's may step one, so those take frames first.
    fn steps_beside_activations(&self, native: Native, receiver: Value) -> bool {
        use crate::heap::IteratorKind;
        native == Native::IteratorNext
            && self.heap.iterator(receiver).is_some_and(|iterator| {
                matches!(
                    iterator.kind,
                    IteratorKind::Array
                        | IteratorKind::ArrayKeys
                        | IteratorKind::ArrayValues
                        | IteratorKind::ArrayEntries
                        | IteratorKind::String
                        | IteratorKind::MapKeys
                        | IteratorKind::MapValues
                        | IteratorKind::MapEntries
                        | IteratorKind::SetValues
                        | IteratorKind::SetEntries
                )
            })
    }

    /// Whether `callee` is a native that runs beside a lane's activations
    /// (`runs_beside_activations`), which a call made while they stay frameless may make
    /// without making them frames.
    pub(super) fn callee_runs_beside_activations(&self, callee: Value) -> bool {
        match self.heap.function(callee) {
            Some(FunctionRecord { kind: FunctionKind::Native(native), .. }) => {
                self.runs_beside_activations(*native, callee)
            }
            _ => false,
        }
    }

    /// Whether the activations of a lane native call deferred beside them (`lane_deferred`)
    /// run a function of `program`: the innermost runs its lane context's program, and each
    /// names its caller's, the outermost's being a frame's.
    pub(super) fn deferred_activations_run(&self, program: ProgramId) -> bool {
        let Some(DeferredLaneCall { cx, .. }) = &self.lane_deferred else {
            return false;
        };
        // SAFETY: the deferred call's lane runs, so its context lives.
        let innermost = unsafe { (*cx.cast::<LaneContext<H>>()).program };
        innermost == program
            || self.lane_stack.activations.iter().any(|activation| activation.caller_program == program)
    }

    /// Make a deferred lane native call's activations frames (`DeferredLaneCall`), as
    /// `lane_call_native` would have before calling: at every point that observes the frame
    /// stack while a native runs, which guest code, a stack capture and a collection do.
    #[inline(always)]
    pub(super) fn materialize_deferred_lane(&mut self) {
        if self.lane_deferred.is_some() {
            self.materialize_deferred_lane_now();
        }
    }

    #[cold]
    #[inline(never)]
    fn materialize_deferred_lane_now(&mut self) {
        let Some(DeferredLaneCall { cx, call_pc, .. }) = self.lane_deferred.take() else {
            return;
        };
        let before = self.frames.len();
        self.materialize_lane_activations(cx.cast::<LaneContext<H>>());
        self.resume_deferred_caller(call_pc, before);
    }

    /// The deferred call's resumption once its activations became frames above `before`.
    fn resume_deferred_caller(&mut self, call_pc: usize, before: usize) {
        // The natives running beside the activations recorded the frame count without them;
        // their caller is now the innermost new frame (`Vm::function_caller`).
        let natives = self.realm.promise.active_native.len();
        self.shift_beside_natives(natives, before, self.frames.len() - before);
        // The call runs from the innermost activation's frame, resuming after it.
        let frame = self.frames.len() - 1;
        self.frames[frame].pc = call_pc + 1;
        self.frames[frame].pc_is_resume = true;
    }

    /// Running natives, innermost of the first `natives`, that recorded `depth` frames beside
    /// activations now `added` frames above it: their caller is the innermost of those.
    fn shift_beside_natives(&mut self, natives: usize, depth: usize, added: usize) {
        for native in self.realm.promise.active_native[..natives].iter_mut().rev() {
            if native.frame_depth != depth {
                break;
            }
            native.frame_depth += added;
        }
    }

    /// The lane's exit (`lane_dispatch`'s exit record): a running leaf, whose records may
    /// leave the lane (`lane_materialize_leaf`), then every activation becomes a frame the
    /// general path runs. Nothing else materializes while a leaf runs: its records call
    /// nothing, and a getter's activation makes it first.
    fn materialize_lane_exit(&mut self, cx: *mut LaneContext<H>) {
        lane_materialize_running_leaf(cx);
        self.materialize_lane_activations(cx);
    }

    fn materialize_lane_activations(&mut self, cx: *mut LaneContext<H>) {
        debug_assert!(unsafe { (*cx).leaf.call }.is_null(), "a running leaf materializes at the lane's exit");
        self.link_natives(cx);
        if self.lane_stack.activations.is_empty() {
            return;
        }
        #[cfg(feature = "profile-lane-exits")]
        super::lane_exits::record_detail(format!("materialize depth {}", self.lane_stack.activations.len()));
        let mut activations = std::mem::take(&mut self.lane_stack.activations);
        let lane_wasm_storage_bytes = std::mem::take(&mut self.lane_stack.wasm_storage_bytes);
        debug_assert_eq!(
            lane_wasm_storage_bytes,
            activations
                .iter()
                .map(Activation::frame_storage_bytes)
                .sum::<usize>()
        );
        let root = unsafe { (*cx).root };
        let mut caller = root.caller_of_first(self.frames.len());
        let mut forwarders = std::mem::take(&mut self.lane_stack.forwarders).into_iter();
        let (mut settling, mut steps, mut traps) = (std::mem::take(&mut self.lane_stack.settling).into_iter(), std::mem::take(&mut self.lane_stack.steps).into_iter(), std::mem::take(&mut self.lane_stack.trap_checks).into_iter());
        let iterators = std::mem::take(&mut self.lane_stack.iterators);
        let mut to_wasm = std::mem::take(&mut self.lane_stack.to_wasm).into_iter();
        let scopes = std::mem::take(&mut self.lane_stack.with_objects);
        // Each frame holds the environment its eval promoted; the records go with the activations.
        let _records = std::mem::take(&mut self.lane_stack.records);
        let states = ActivationState::of(&activations, cx);
        // A deferred native's caller activations below its callback take the lane's outer
        // pending calls and executing program (`NativeBoundary`).
        let boundary = self.lane_stack.native_boundary.take();
        let before = self.frames.len();
        for (depth, (activation, state)) in activations.drain().zip(states).enumerate() {
            let below = boundary.filter(|boundary| depth < boundary.activation);
            if let Some(boundary) = boundary
                && depth == boundary.activation
            {
                self.lane_stack.boundary_frames = Some(self.frames.len() - before);
            }
            // SAFETY: the pending calls and executing program outlive the lane run.
            let pending = unsafe { &mut *below.map_or((*cx).pending, |boundary| boundary.pending) };
            let executing_program = below.map_or(unsafe { (*cx).executing }, |boundary| boundary.executing);
            let program = state.program;
            // Its frame belongs to its own program, which its push makes active; a call
            // into another program sets the caller's aside as the general loop's push does.
            self.set_active_program(program);
            // SAFETY: the program store keeps the residual for the lane run.
            let Some(code) = self.programs.residual(program).map(std::ptr::from_ref) else {
                unreachable!("an activation runs a function of a program the store holds");
            };
            let code = unsafe { &*code };
            let caller_program = (program != activation.caller_program).then(|| {
                // SAFETY: the general loop's executing program outlives the lane run.
                let executing = unsafe { &mut *executing_program };
                debug_assert_eq!(executing.id, activation.caller_program);
                let retained = self.programs.get(program);
                let saved = super::dispatch_frame::SavedProgram {
                    id: executing.id,
                    retained: std::mem::replace(&mut executing.retained, retained),
                };
                executing.id = program;
                saved
            });
            // SAFETY: a call record lies in its caller's view.
            let mut call_pc = unsafe { activation.call.offset_from(activation.caller_base) } as usize;
            let (mut result, resume_pc) = activation.caller_resume(call_pc);
            self.resume_caller_frame(root, depth, caller, resume_pc);
            let count = usize::from(code.function(activation.function as usize).registers);
            // SAFETY: the activation's window holds its registers, which nothing writes until
            // its frame takes them.
            let window = unsafe { activation.window(count) };
            let completion = match activation.script().map(|script| script.completion) {
                Some(completion) if completion.constructs() => CallCompletion::Constructor(state.this),
                Some(Completion::SettlesPromise) => CallCompletion::Promise(
                    self.settling_root(settling.next().expect("each settling activation has its entry"))),
                Some(Completion::ArrayStep) => {
                    let step = steps.next().expect("each array step activation has its entry");
                    CallCompletion::ArrayStep(Box::new(self.array_step_call(step.iteration, step.element, step.index)))
                }
                Some(Completion::ToWasm) => CallCompletion::ToWasm(to_wasm.next().expect("each import activation has its entry").result),
                other => match activation.kind {
                    ActivationKind::WasmEntry { result, .. } => CallCompletion::WasmExport(result),
                    _ => setters::frame_completion(other, &mut traps),
                },
            };
            // A native's callback is the entry frame of the loop that finishes it.
            let to_native = body_calls::enters_as_frame(&mut self.lane_stack, &activation, self.frames.len());
            let call_guard = match activation.kind {
                // A windowed activation's frame is its owner's, which takes the iterators its loops pushed.
                ActivationKind::Script(script) if script.completion.is_windowed() => {
                    let owned = iterators.iter().filter(|(owner, _)| *owner == depth).map(|(_, iterator)| *iterator);
                    let entered = scopes.iter().filter(|(owner, _)| *owner == depth).map(|(_, object)| *object);
                    self.push_window_frame(root, &script, owned, entered);
                    crate::stack::GuestCallGuard::enter().ok()
                }
                ActivationKind::Script(script) => {
                    let argc = usize::from(script.argc);
                    // A forwarding activation kept the values after its registers; any other
                    // passed them all to parameter registers.
                    let passed = if script.forwards {
                        // SAFETY: the window holds the registers, then the `argc` kept values.
                        &(unsafe { activation.window(count + argc) })[count..]
                    } else if script.environment {
                        // After its environment and locals (`lane_activate_environment`).
                        let kept = count
                            + usize::from(WINDOW_LOCALS)
                            + usize::from(code.function(activation.function as usize).locals);
                        // SAFETY: the window holds them, then the `argc` kept values.
                        &(unsafe { activation.window(kept + argc) })[kept..]
                    } else {
                        &window[..argc]
                    };
                    if script.completion == Completion::Forwarder {
                        // The construction's skipped forwarding constructor becomes the frame
                        // it would have been, pending at its forwarding call, whose dead
                        // registers hold `undefined`; the method's frame runs inside it.
                        // A native frame's is its descriptor's (`NativeFrames`), which no entry holds.
                        // SAFETY: a native frame's callee outlives the run.
                        let forwarder = unsafe { activation.native.callee.as_ref() }
                            .map_or_else(|| forwarders.next(), |callee| callee.forwarder)
                            .expect("each forwarder activation has its skipped constructor");
                        let constructor_registers = vec![
                            Value::UNDEFINED;
                            usize::from(code.function(forwarder.function as usize).registers)
                        ];
                        self.push_script_frame_with_registers(
                            code,
                            forwarder.function,
                            forwarder.env,
                            state.this,
                            CallContext::user_function(forwarder.function, forwarder.callee).constructed(),
                            passed,
                            &constructor_registers,
                        );
                        pending.push(PendingGeneralCall {
                            caller,
                            caller_cursor: None,
                            call_pc: call_pc as u32,
                            destination: result & crate::bytecode::REGISTER_MASK,
                            completion: CallCompletion::Constructor(state.this),
                            returns: result & crate::bytecode::RETURN_REGISTER != 0,
                            call_guard: crate::stack::GuestCallGuard::enter().ok(),
                            caller_program: None,
                        });
                        caller = caller.wrapping_add(1);
                        call_pc = forwarder.method.call_pc as usize;
                        result = forwarder.method.call_result;
                        self.frames[caller].pc = call_pc + 1;
                        self.frames[caller].pc_is_resume = true;
                    }
                    self.push_script_frame_with_registers(
                        code,
                        activation.function,
                        state.env,
                        state.this,
                        if script.completion.constructs() {
                            CallContext::user_function(activation.function, script.callee).constructed()
                        } else {
                            CallContext::user_function(activation.function, script.callee)
                        },
                        passed,
                        window,
                    );
                    if script.environment {
                        self.materialize_environment_frame(code, &activation, (program, state.env, state.this), argc);
                    }
                    // Its frame closes the iterators its loops pushed (`LaneStack::iterators`).
                    let frame = self.frames.last_mut().expect("the activation pushed a frame");
                    frame.active_iterators.extend(
                        iterators.iter().filter(|(owner, _)| *owner == depth).map(|(_, iterator)| *iterator),
                    );
                    // The scope chain it entered sits on the VM's scope stack above its base.
                    self.with_stack.extend(scopes.iter().filter(|(owner, _)| *owner == depth).map(|(_, object)| *object));
                    // The activation counted within `LaneStack::activation_limit`; its frame
                    // takes the guest-call guard its push would have.
                    crate::stack::GuestCallGuard::enter().ok()
                }
                ActivationKind::Native => unreachable!("native frames link before the activations become frames"),
                ActivationKind::Wasm { .. } => {
                    // The lane reserved this payload while it was frameless; its materialized
                    // frame holds the same weighted guard until the call returns.
                    let env = self.frames[caller].env;
                    Some(self.push_wasm_frame_with_registers(code, env, activation.function, window))
                }
                // The export's frame, as `lane_wasm_export_frame` pushes it when it cannot
                // activate the callee: over the instance environment, with the pending call
                // that converts its result.
                ActivationKind::WasmEntry { instance, .. } => {
                    Some(self.push_wasm_frame_with_registers(code, instance, activation.function, window))
                }
            };
            if !to_native {
                pending.push(PendingGeneralCall {
                    caller,
                    caller_cursor: None,
                    call_pc: call_pc as u32,
                    destination: result & crate::bytecode::REGISTER_MASK,
                    completion,
                    returns: result & crate::bytecode::RETURN_REGISTER != 0,
                    call_guard,
                    caller_program,
                });
            }
            caller = caller.wrapping_add(1);
        }
        debug_assert!(settling.next().is_none(), "every settling root belongs to an activation");
        debug_assert!(steps.next().is_none(), "every array step belongs to an activation");
        debug_assert!(traps.next().is_none(), "every trapped activation has its entry taken");
        if let Some(boundary) = boundary {
            // The native's caller is now the innermost of its activations' frames, as when
            // its deferred call is observed (`materialize_deferred_lane_now`).
            let added = *self.lane_stack.boundary_frames.get_or_insert(self.frames.len() - before);
            let natives = boundary.natives.min(self.realm.promise.active_native.len());
            self.shift_beside_natives(natives, boundary.deferred.frames, added);
        }
        self.lane_stack.values.clear();
        self.lane_stack.activations = activations;
        // The frames now hold the guards the activations were counted against.
        self.lane_stack.refresh_activation_limit();
        // The lane continues in the innermost frame, whose register file the general path's
        // register access names from now on (`lane_enter_frame`).
        let registers = Registers(self.frames[caller].registers.as_mut_ptr());
        self.active_registers = registers.0;
        unsafe {
            (*cx).root = LaneRoot::Frame(caller);
            (*cx).registers = registers;
            registers.set_this(self.frame_lane_this(caller));
            registers.set_env(Value::DELETED);
            (*cx).instance = Value::DELETED;
            (*cx).registers.set_capture(std::ptr::null());
            (*cx).outer = NO_OUTER_WALK;
        (*cx).root_walk = NO_OUTER_WALK;
        }
    }

    /// Gives the frame an environment activation became its environment and locals: the frame its
    /// promotion would have made, `argc` values having been passed to `activation`.
    fn materialize_environment_frame(&mut self, code: &ResidualProgram, activation: &Activation, (program, env, this): (ProgramId, Value, Value), argc: usize) {
        // The frame its promotion would have made: the environment it holds,
        // and its locals.
        let held = usize::from(code.function(activation.function as usize).registers);
        // SAFETY: the activation's window, intact.
        let environment = unsafe { window_environment(self, code, activation.window_ptr().add(held), activation.function, env, program, this, None) };
        let frame = self.frames.last_mut().expect("the activation pushed a frame");
        frame.env = environment;
        frame.captured = true;
        let locals = held + usize::from(WINDOW_LOCALS);
        let count = frame.locals.len();
        // The activation never binds `arguments`: its body only reads the
        // values passed and its parameters (`Function::reads_passed_arguments_only`),
        // so the object the push made from the values is the binding, with
        // each element a parameter aliases holding that parameter now.
        let body = code.function(activation.function as usize);
        let arguments = body.arguments_slot.map(usize::from);
        let object = arguments.map(|slot| frame.locals[slot]);
        // SAFETY: the window holds the environment's locals after the registers.
        frame.locals.copy_from_slice(&unsafe { activation.window(locals + count) }[locals..]);
        if let (Some(slot), Some(object)) = (arguments, object) {
            frame.locals[slot] = object;
            if body.arguments_alias_parameters() {
                for parameter in 0..usize::from(body.params).min(argc) {
                    // SAFETY: as the locals' read.
                    let value = unsafe { activation.window(locals + parameter + 1) }[locals + parameter];
                    self.store_mapped_argument(object, parameter, value);
                }
            }
        }
    }

    /// The lane's `this` for frame `frame` (`LaneContext::this`).
    fn frame_lane_this(&self, frame: usize) -> Value {
        let frame = &self.frames[frame];
        if frame.fixed_this {
            frame.this
        } else {
            Value::DELETED
        }
    }

    /// The cached frameless target of a lane call to `callee`, if resolved, in place: its
    /// cache entry, which a call reads field by field
    /// where it uses them rather than holding a copy in registers. The cache is boxed, so
    /// the entry stays put; it holds this target until the next resolution or collection
    /// replaces it, which no activation makes.
    #[inline(always)]
    fn script_call_entry(&self, callee: Value) -> Option<*const ScriptCallTarget> {
        self.script_call_index(callee).map(|index| &self.lane_stack.script_targets[index] as *const ScriptCallTarget)
    }

    /// The index of `script_call_entry`'s entry in `LaneStack::script_targets`.
    #[inline(always)]
    fn script_call_index(&self, callee: Value) -> Option<usize> {
        let set = self.lane_stack.script_targets.set(callee)?;
        // The set's two ways, tested in turn: an array iterator here compiled to an
        // out-of-line search on every call.
        let other = set | 1;
        if self.script_call_holds(set, callee) {
            Some(set)
        } else {
            self.script_call_holds(other, callee).then_some(other)
        }
    }

    /// Whether `LaneStack::script_targets` entry `index` holds `callee`'s target for this
    /// generation and the running program.
    #[inline(always)]
    fn script_call_holds(&self, index: usize, callee: Value) -> bool {
        self.lane_stack.script_targets.entries.get(index).is_some_and(|cached| {
            cached.callee == callee && cached.admission == self.lane_stack.admission
        })
    }

    /// `script_call_entry` for the call record whose hint is `link` (`LaneInstruction::call_link`):
    /// the entry it names when that holds `callee`'s target, which skips the set's hash, else
    /// the set's, which the hint names from then on. A cache that grew or another callee only
    /// costs the hash again.
    #[inline(always)]
    fn linked_script_call_entry(&mut self, callee: Value, link: &std::cell::Cell<u16>) -> Option<*const ScriptCallTarget> {
        let linked = usize::from(link.get());
        let index = if self.script_call_holds(linked, callee) {
            linked
        } else {
            let index = match self.script_call_index(callee) {
                Some(index) => index,
                None => self.relink_site_closure(callee, linked)?,
            };
            // The callee in hand joins the site's record (`LaneStack::call_sites`): the entry it
            // linked may hold another site's callee since, so only the record names its own.
            if self.tier_may_run(crate::jit_mode::Tier::ANY) {
                self.note_linked_callee(link, index);
            }
            // The entry count stays below `NO_CALL_LINK` (`SCRIPT_CALL_TARGETS`).
            link.set(index as u16);
            index
        };
        // SAFETY: `script_call_holds` found the entry within the cache.
        Some(unsafe { self.lane_stack.script_targets.entries.get_unchecked(index) } as *const ScriptCallTarget)
    }

    /// `linked_script_call_entry`'s target for a closure no cache set holds: a fresh closure
    /// of the site's linked function, relinked in place, out of line, since a polymorphic
    /// site's every miss would otherwise carry it.
    #[cold]
    #[inline(never)]
    fn relink_site_closure(&mut self, callee: Value, linked: usize) -> Option<usize> {
        // Only a call-only closure (`Value::known_closure`) takes the known form.
        if callee.as_known_closure().is_some()
            && let Some(index) = self.relink_known_closure(callee, linked)
        {
            return Some(index);
        }
        self.relink_closure(callee, linked)
    }

    /// The site record of `link` notes entry `index`'s callee (`Vm::note_site_callee`).
    #[cold]
    #[inline(never)]
    fn note_linked_callee(&self, link: &std::cell::Cell<u16>, index: usize) {
        let current = &self.lane_stack.script_targets.entries[index];
        self.note_site_callee(link, super::compiled::CallTarget {
            callee: super::compiled::CalleeBinding::Identity(current.callee), function: current.function });
    }

    /// `script_call_entry` of a callee of another program than the running one, whose
    /// targets `LaneStack::cross_targets` holds (`lane_script_call_cross`).
    #[inline(always)]
    fn cross_call_index(&self, callee: Value) -> Option<usize> {
        let set = self.lane_stack.cross_targets.set(callee)?;
        // The set's two ways, tested in turn, as `script_call_index` does.
        if self.cross_call_holds(set, callee) {
            Some(set)
        } else {
            self.cross_call_holds(set | 1, callee).then_some(set | 1)
        }
    }

    /// Whether `LaneStack::cross_targets` entry `index` holds `callee`'s target for this
    /// generation, for a caller in another program than the callee's.
    #[inline(always)]
    fn cross_call_holds(&self, index: usize, callee: Value) -> bool {
        self.lane_stack.cross_targets.entries.get(index).is_some_and(|cached| {
            cached.callee == callee && cached.generation() == self.lane_stack.generation && cached.program() != self.active_program
        })
    }

    /// `cross_call_entry` for the call record whose hint is `link` (`LaneInstruction::call_link`),
    /// as `linked_script_call_entry` is for the running program's targets: the entry the hint
    /// names when it holds `callee`'s target, else the set's, which the hint names from then on.
    #[inline(always)]
    fn linked_cross_call_entry(&self, callee: Value, link: &std::cell::Cell<u16>) -> Option<*const ScriptCallTarget> {
        let linked = usize::from(link.get());
        let index = if self.cross_call_holds(linked, callee) {
            linked
        } else {
            let index = self.cross_call_index(callee)?;
            // The entry count stays below `NO_CALL_LINK` (`SCRIPT_CALL_TARGETS`).
            link.set(index as u16);
            index
        };
        // SAFETY: `cross_call_holds` found the entry within the cache.
        Some(unsafe { self.lane_stack.cross_targets.entries.get_unchecked(index) } as *const ScriptCallTarget)
    }

    /// `cross_call_index`'s entry, in place.
    #[inline(always)]
    fn cross_call_entry(&self, callee: Value) -> Option<*const ScriptCallTarget> {
        self.cross_call_index(callee).map(|index| &self.lane_stack.cross_targets[index] as *const ScriptCallTarget)
    }

    /// Whether `callee` activates as `function` in place, in the active program, with an
    /// ordinary `this`: the facts an inlined frame's recovery relies on
    /// (`lane_body_inlined_activation`), admitted once when its body is published; a
    /// lifecycle edge retires the body before they can expire.
    pub(super) fn lane_inlined_target_admitted(&mut self, code: &ResidualProgram, callee: Value, function: u32) -> bool {
        self.resolve_script_call_target(code, callee).is_some_and(|target| target.program() == self.active_program
            && target.function == function
            && target.entry.activates_registers_only()
            // An arrow that reads none of its maker's bindings has no receiver to bind.
            && (target.this_binding.binds_receiver() || (target.this_binding == ThisBinding::Lexical
                && !crate::bytecode::arrow_chain_reads_implicit_bindings(code, function))))
    }

    /// Resolve and cache `callee` as a lane call target: frameless when its activation is its
    /// registers (`CallPlan::registers_only`), else a `CallEntry::Frame` entry, so its calls
    /// take a frame without resolving it again.
    #[inline(never)]
    pub(in crate::vm) fn resolve_script_call_target(&mut self, code: &ResidualProgram, callee: Value) -> Option<ScriptCallTarget> {
        callee.heap_index()?;
        let (program, function, env) = self.same_realm_user_target(callee)?;
        // Only plain closures' functions are known (`remember_target`): a hit needs no class or admission.
        if program == self.active_program && let Some(known) = self.lane_stack.function_target(program, function, false) {
            let target = self.closure_target(code, program, callee, env, known)?;
            self.lane_stack.remember_script_target(target, self.heap.memory_policy());
            return Some(target);
        }
        let numeric = self.numeric_body(program, function);
        #[cfg(feature = "profile-lane-exits")]
        if let Some(body) = self.programs.residual(program).and_then(|code| { let body = code.function_get(function as usize)?;
            Some(format!("resolve {} span={:?} cross={}", body.name.map(|atom| code.atoms[atom as usize].to_string()).unwrap_or_default(),
                body.source_span.map(|span| span.start), program != self.active_program)) }) {
            super::lane_exits::record_detail(body);
        }
        // A callee of another program runs its own residual, which the program store keeps
        // alive with the program for the lane run; a closure of a program the lane admits,
        // plain or numeric, activates across programs.
        let cross = program != self.active_program;
        let code: &ResidualProgram = if cross {
            // SAFETY: as above; no program is installed or retired while a call resolves.
            let callee_code = unsafe { &*std::ptr::from_ref(self.programs.residual(program)?) };
            if !self.lane_admits(callee_code) { return None; }
            callee_code
        } else { code };
        // The JavaScript tier enters a frameless activation at its prologue as it enters a
        // frame (`lane_tier_prologue`), so a function it may claim is cached like any other.
        if function == super::ROOT_FUNCTION_ID { return None; }
        // A numeric body's target differs from its plain closures' (below), so only plain
        // closures share their function's.
        if !numeric && let Some(known) = self.lane_stack.function_target(program, function, cross) {
            let target = self.closure_target(code, program, callee, env, known)?;
            let policy = self.heap.memory_policy();
            if cross {
                self.lane_stack.remember_cross_target(target, policy);
            } else {
                self.lane_stack.remember_script_target(target, policy);
            }
            return Some(target);
        }
        if !self.lane_call_may_derive(program, function) { return None; }
        let body = code.function_get(function as usize)?;
        let plan = body.call_plan(code);
        // An arrow binds the `this` of its environment, found once here: one still
        // uninitialized (before `super()`) leaves its calls to the general path, uncached.
        let lexical_this = if body.is_arrow {
            let this = self.captured_lexical_this(env);
            if this.is_some_and(Value::is_deleted) {
                return None;
            }
            Some(this)
        } else {
            None
        };
        // A numeric body's own frame constructs nothing in place
        // (`LaneContext::script_constructs`), which its activation would inherit from the
        // caller, so only one that constructs nothing runs frameless; its other records are
        // the lane's, with or without a frame.
        // An environment body runs in an environment activation where every local and
        // closure record of its view reads one (`LaneView::environment_window`).
        let environment = !plan.registers_only
            && plan.environment_activation
            && !numeric
            && self
                .lane_view_any(program, function)
                .is_some_and(|view| unsafe { &*view }.environment_window.is_some());
        // A non-suspending async body of the running program activates for its plain calls,
        // whose promise its return settles (`CallEntry::Settles`); across programs, or under a
        // host that observes promise lifecycles, its calls take a frame.
        let settles = plan.settles_in_loop && !cross && !numeric && !self.host.observes_promise_lifecycle();
        // A non-suspending async body runs in registers only as a settling activation.
        let registers_only = plan.registers_only && (settles || !plan.settles_in_loop);
        // Across programs a construction leaves its calls a frame.
        let view = if !(registers_only || environment)
            || numeric
                && body
                    .code
                    .iter()
                    .any(|packed| body.widened(*packed).op().is_construct())
        {
            None
        } else {
            self.lane_view_any(program, function)
        };
        #[cfg(feature = "profile-lane-exits")]
        if view.is_none() {
            let closures = body.code.iter().any(|packed| body.widened(*packed).op().makes_closure());
            super::lane_exits::record_detail(format!(
                "frame entry {} plain={} registers_only={} env_activation={} environment={} arrow={} rest={} closures={} arguments={} handlers={} class_ctor={} derived={} async={} generator={} locals_promoted={} simple_params={} selective={} cross={} numeric={}",
                body.name.map(|atom| code.atoms[atom as usize].to_string()).unwrap_or_default(),
                plan.plain, plan.registers_only, plan.environment_activation, environment, body.is_arrow, body.rest, closures,
                body.arguments_slot.is_some(), !body.handlers.is_empty(), body.is_class_constructor, body.derived_constructor,
                body.is_async, body.is_generator, body.local_registers.len(), body.simple_parameters,
                body.selective_capture_slots.is_some(), cross, numeric,
            ));
        }
        let Some(view) = view else {
            // The function needs a frame, which the target records so its calls take one
            // without resolving it again.
            let target = ScriptCallTarget {
                callee,
                admission: Admission::new(self.lane_stack.generation, program),
                function,
                env,
                entry: CallEntry::Frame,
                ..EMPTY_SCRIPT_CALL_TARGET
            };
            self.remember_target(target, numeric, cross);
            return Some(target);
        };
        let tier_may_claim = self.js_tier_may_claim(code, program, function);
        // SAFETY: the program store keeps a derived view alive with its program.
        let shape = *unsafe { &*view }.target_body.get_or_init(|| {
            let constructs = Self::inline_constructible(body);
            // A class constructor's calls throw on the general path, so they take a
            // frame; only its constructions activate frameless (`lane_script_construct`).
            let entry = body_entry(body, &code.constants);
            // SAFETY: the program store keeps a derived view alive with its program.
            unsafe { &*view }.entry.set_facts(crate::staged::call::CellFacts::of_function(body.registers, body.params, entry == CallEntry::Activates && !environment));
            TargetBody {
                entry,
                constructs,
                initializes: constructs && body.only_initializes_this_fields(&code.constants),
                leaf: (entry == CallEntry::Activates)
                    .then(|| leaf_body(body, code, |atom| self.is_private_name(atom)))
                    .flatten()
                    // The claim is a fact of the body (`js_tier_may_claim`): it holds for the view.
                    .filter(|_| !tier_may_claim)
                    // SAFETY: the program store keeps a derived view alive with its program.
                    .inspect(|&form| unsafe { &*view }.specialize_leaf_returns::<H>(form)),
            }
        });
        // An environment activation (`environment`, whose view has a window layout) claims as any other: its body
        // reads its locals through the window (`window_bodies::body_locals`).
        if !settles
            && self.claims_across(cross)
            && !body.rest
            // A `keeps_arguments` target activates in the keeping form, whose window no body
            // run reads yet: its rows lower (`ArgumentsLength`, `ArgumentGet`), the entry does
            // not (lane-bodies claim for keeping activations).
            && !plan.keeps_arguments
            && shape.entry == CallEntry::Activates
            && tier_may_claim
            // SAFETY: as below.
            && (!self.programs.js_jit_lane_methods_enabled() || unsafe { &*view }.lane_tier_unclaimed())
        {
            // SAFETY: the program store keeps a derived view alive with its program.
            unsafe { &*view }.claim_for_tier(lane_tier_prologue::<H>, function, body.params, !body.is_arrow);
        }
        let capture = self.target_capture(code, program, env);
        let target = ScriptCallTarget {
            callee,
            admission: Admission::new(self.lane_stack.generation, program),
            function,
            env,
            view,
            registers: body.registers,
            // An environment activation's window also holds its environment, its locals and
            // the values passed, at most one per parameter.
            room: u16::try_from(fill_room::<SCRIPT_FILL_BLOCK>(
                usize::from(body.registers)
                    + if environment {
                        usize::from(WINDOW_LOCALS) + usize::from(body.locals) + usize::from(body.params)
                    } else {
                        0
                    },
            ))
            .ok()?,
            params: body.params,
            this_binding: match lexical_this {
                Some(Some(_)) => ThisBinding::Lexical,
                Some(None) => ThisBinding::CallerReceiver,
                None if body.strict => ThisBinding::Strict,
                None => ThisBinding::Sloppy,
            },
            lexical_this: lexical_this.flatten().unwrap_or(Value::UNDEFINED),
            // A construction activates in place (`lane_activate`), which gathers no rest, and
            // completes across programs as a call does (`Completion::CrossConstructs`); a
            // forwarding one runs its program's keeping construction
            // (`lane_construct_keeping_activation`), which another program's caller does not.
            // An environment activation's window has no record to hold the `new.target` an arrow reads.
            forms: u8::from(shape.constructs && !(environment && body.activation_bindings_observable(code)) && !settles && !body.rest && !(cross && plan.keeps_arguments)) * TARGET_CONSTRUCTS
                | u8::from(shape.initializes && !environment && !settles && !cross && !body.rest) * TARGET_INITIALIZES
                | u8::from(body.rest && (plan.keeps_arguments || plan.legacy_reflection || (lexical_this.is_none() && !body.strict))) * TARGET_GATHERS_KEEPING
                | u8::from(body.rest_view()) * TARGET_REST_VIEW
                | u8::from(lexical_this.is_some() && body.arrow_reads_implicit_bindings(code, function)) * TARGET_READS_IMPLICIT,
            fill: u8::try_from(body.register_roots.entry_fill(body.registers)).unwrap_or(u8::MAX),
            // A read target answers its call through the callee's own field sites, which
            // only its program's caches index.
            entry: target_entry(body, &plan, &shape, (settles, environment, cross)),
            capture,
            forwarded_method: match (plan.forwards_arguments && shape.constructs)
                .then(|| body.forwarded_this_method(&code.constants))
                .flatten()
            {
                Some(method) => self.lane_stack.forwarded_method_index(method),
                None => NO_FORWARDED_METHOD,
            },
        };
        self.remember_target(target, numeric, cross);
        Some(target)
    }

    /// Whether a callee of another program (where `cross`) may take the tier prologue: a lane
    /// body runs in its own program's context, which the activation enters first.
    fn claims_across(&self, cross: bool) -> bool {
        !cross || self.programs.js_jit_lane_methods_enabled()
    }

    /// Record a resolved `target`, also as its function's unless its closure is numeric; a
    /// `cross` one among the other programs' targets.
    fn remember_target(&mut self, target: ScriptCallTarget, numeric: bool, cross: bool) {
        let policy = self.heap.memory_policy();
        if numeric {
            // A numeric body's target is its closure's, held per callee: another program's in
            // the cross-program set, which its callers activate across programs.
            if cross {
                self.lane_stack.remember_cross_target(target, policy);
            } else {
                self.lane_stack.remember_script_target(target, policy);
            }
        } else {
            self.lane_stack.remember_function_target(target, cross, policy);
        }
    }

    /// The capture slots a frameless target whose closure has environment `env` reads
    /// (`ScriptCallTarget::capture`), tagged `CAPTURE_STORES` when they admit every store,
    /// whose barrier this takes once.
    pub(super) fn target_capture(
        &mut self,
        code: &ResidualProgram,
        program: ProgramId,
        env: Value,
    ) -> *const usize {
        // A frameless activation's function has no environment of its own: its depth-0
        // captures are the closure environment's dense slots (`Vm::environment_capture_slots`),
        // read here with the facts the store tag needs from the same cell.
        let Some(crate::heap::EnvironmentRecord { function, slots, scope, .. }) = self.heap.environment(env) else {
            return std::ptr::null();
        };
        if *function == u32::MAX || *function == super::ROOT_FUNCTION_ID {
            return std::ptr::null();
        }
        let Some(capture) = slots.dense_storage() else {
            return std::ptr::null();
        };
        if super::environment::direct_store_owner(code, program, *function, scope)
            .is_some_and(super::environment::owner_admits_every_direct_store)
        {
            self.heap.remember_cell(env);
            return capture.map_addr(|address| address | CAPTURE_STORES);
        }
        capture
    }

    /// Whether `program` runs in the lane when dynamic execution is allowed:
    /// Wasm always, JavaScript where it and the VM are specialized. A lane run keeps its program and the VM's specialization, so the
    /// lane's field caches (`Vm::primary_own_field_hit` and its kin) need not test them.
    pub(super) fn specialized_operations_enabled(&self, program: &ResidualProgram) -> bool {
        program.kind == crate::bytecode::ProgramKind::Wasm || (self.specialized && program.specialized)
    }

    pub(super) fn lane_admits(&self, program: &ResidualProgram) -> bool {
        self.execution_mode.allows_dynamic_execution() && self.specialized_operations_enabled(program)
    }

    /// The words a lane run's direct calls push onto (`compiled::DirectCallee`): the addresses
    /// of the values' and the activations' tops, each owned here and bumped through its
    /// address by emitted code; the end of the values' capacity; and the end of the `frames`
    /// activations the run may nest above the activations' top, bounded by what the lane may
    /// still make of them.
    pub(super) fn lane_stack_words(&mut self, frames: usize) -> LaneStackWords {
        let stack = &mut self.lane_stack;
        let frames = frames.min(stack.activation_limit.get().saturating_sub(stack.activations.len() + 1));
        let frames_end = stack.activations.top_ptr().wrapping_add(frames).addr();
        // SAFETY: the values' capacity bounds the vector's own allocation.
        let values_end = unsafe { stack.values.as_mut_ptr().add(stack.values.capacity()) }.addr();
        LaneStackWords {
            values_top: stack.values.top_word().addr(),
            values_end,
            activations_top: stack.activations.top_word().addr(),
            frames_end,
        }
    }

    /// The lane view a hot loop of `function` runs with (`Vm::note_back_edge`), or null.
    pub(super) fn hot_loop_lane_view(&self, program: ProgramId, function: u32) -> *const LaneView {
        self.lane_view_any(program, function).unwrap_or(std::ptr::null())
    }

    /// The lane view of `function`, derived on first use.
    pub(super) fn lane_view_any(&self, program: ProgramId, function: u32) -> Option<*const LaneView> {
        if !H::RUNS_LANE || !self.execution_mode.allows_dynamic_execution() { return None; }
        let diagnostics = self.programs.reports_on_drop();
        let tiers = self.programs.tiers();
        self.programs.lane_view(program, function, |code, constants, kind, live, sites| {
            derive_lane_view::<H>(
                function,
                code,
                constants,
                &self.heap,
                kind,
                live,
                sites,
                self.tier_may_run(crate::jit_mode::Tier::ANY),
                diagnostics,
                tiers,
            )
        })
    }
}

impl<H: Host> Vm<H> {
    /// Prints every loaded function's lane view, derived afresh from its bytecode (no loop
    /// tier), when `QUENCH_TRACE=bytecode=lanes` is set: per record `LANEPLAN program function pc
    /// width handler settled | instruction`, handlers as run-time addresses (symbolized against
    /// the symbol table by `quench-gate --only ir-predict`, less the anchor's bias), `settled`
    /// the handler the stored view holds after the run (`-` where no run derived one).
    pub(super) fn report_lane_plan(&mut self) {
        if crate::trace::Channel::Bytecode.value() != Some(super::inspection::LANE_PLAN) {
            return;
        }
        // A function whose load deferred its compilation (`CallFirstChunk`) compiles its chunk
        // now, as its first call would, so the plan holds its body.
        let mut stubs = Vec::new();
        for index in 0..self.programs.len() {
            let Some(residual) = self.programs.get(ProgramId::from_raw(index as u32)) else { continue };
            residual.compile_released();
            for function in 0..residual.functions.len() as u32 {
                if residual.function_get(function as usize).is_some_and(|code| code.instructions().any(|instruction| instruction.op() == Op::CallFirstChunk)) {
                    stubs.push((residual.clone(), ProgramId::from_raw(index as u32), function));
                }
            }
        }
        eprintln!("LANEPLAN-ANCHOR {:x}", lane_plan_anchor as fn() as usize);
        for (residual, id, function) in stubs {
            if let Ok(FunctionKind::User(chunk, body)) = self.compile_first_chunk(&residual, (id, function)) {
                eprintln!("LANEPLAN-CHUNK {} {function} {} {body}", id.raw(), chunk.raw());
            }
        }
        for index in 0..self.programs.len() {
            let id = ProgramId::from_raw(index as u32);
            let Some(residual) = self.programs.get(id) else { continue };
            residual.compile_released();
            for function in 0..residual.functions.len() as u32 {
                let Some(code) = residual.function_get(function as usize) else { continue };
                let name = code.name.map_or("<anonymous>", |atom| residual.atoms[atom as usize].as_ref());
                let plan = self.programs.plan_lane_view(id, function, |code, constants, kind, live, sites| {
                    derive_lane_view::<H>(function, code, constants, &self.heap, kind, live, sites, false, false, self.programs.tiers())
                });
                let Some((fresh, settled)) = plan else { continue };
                eprintln!("LANEPLAN-FUNCTION {index} {function} {name}");
                for (pc, instruction) in code.instructions().enumerate() {
                    // SAFETY: `pc` names a record of each view (both derived from `code`); no
                    // lane runs while the report reads them.
                    let handler = unsafe { (*fresh.records[pc].get()).handler };
                    let settled = settled.map_or_else(|| "-".to_owned(), |view| format!("{:x}", unsafe { (*view.records[pc].get()).handler }.addr()));
                    eprintln!("LANEPLAN {index} {function} {pc} {} {:x} {settled} | {}", fused_width::<H>(handler), handler.addr(), instruction.text());
                }
            }
        }
    }
}

/// A function whose run-time address the lane plan prints (`LANEPLAN-ANCHOR`): less its
/// address in the symbol table, it is the executable's load bias, PIE or not.
#[inline(never)]
fn lane_plan_anchor() {
    std::hint::black_box(());
}

script_handler! {
    /// `lane_script_call` of a linked target whose entry is not a plain activation: the site
    /// calls the form for that entry directly from now on, an environment or keeping
    /// activation its own handler and any other entry the out-of-line form, which sorts them
    /// out. Out of line, reached by `sibling!`, so `lane_script_call` makes no call.
    #[inline(never)]
    fn lane_script_call_requicken<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let target = vm.linked_script_call_entry(r.get(i.b), &i.call_link);
        // SAFETY: as `Vm::script_call_entry`; nothing before this read resolves a target.
        let entry = target.map(|target| unsafe { (*target).entry });
        let handler: Handler = match entry {
            Some(CallEntry::Environment) => lane_script_call_environment::<H>,
            Some(CallEntry::Settles) => lane_script_call_settles::<H>,
            Some(CallEntry::Keeps | CallEntry::Gathers) => lane_script_call_keeping::<H>,
            Some(entry) if entry.leaf_form() != NOT_LEAF => leaf_call_handler::<H>(entry, i),
            Some(_) => lane_script_call_full::<H>,
            None => sibling!(lane_script_call_resolve::<H>, r, ip, Carried::script_in(cx, view)),
        };
        // A capture leaf whose body is a capture's update takes the call that answers it.
        let handler = target
            .and_then(|target| capture_update_call_handler::<H>(unsafe { &*target }, i))
            .unwrap_or(handler);
        requicken::<H>(ip, handler);
        sibling!(handler, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A JavaScript `Call` of a frameless target (`Vm::resolve_script_call_target`): the
    /// callee runs in the lane on a window of the lane stack, with the frame facts its
    /// push would have set held by the activation until it returns or the lane exits.
    /// Any other call takes the general path. `ARGC` is the record's argument count where
    /// the view resolved it (`script_call_handler`), so the window's copy makes no test, else
    /// `ANY_ARGC`. `PLAIN` where the record's receiver is its function's `undefined`
    /// register (`Function::undefined_register`, `specialize_script_calls`), whose value the
    /// handler then knows without reading it.
    fn lane_script_call<ARGC: u16, PLAIN: bool>(cx, r, ip, i, view) {
        if !unsafe { (*cx).script_calls } {
            return exit(ip);
        }
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        // A pending construction refuses every cached target (`LaneStack::set_refused`).
        let Some(target) = vm.linked_script_call_entry(callee, &i.call_link) else {
            sibling!(lane_script_call_resolve::<H>, r, ip, Carried::script_in(cx, view))
        };
        debug_assert!(!lane_constructing(vm, callee));
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
        let target = unsafe { &*target };
        // One test: the site calls the form for its target's entry directly from now on
        // (`lane_script_call_requicken`), out of line so this handler makes no call.
        if target.entry != CallEntry::Activates {
            sibling!(lane_script_call_requicken::<H>, r, ip, Carried::script_in(cx, view))
        }
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, target);
        lane_plain_activation!(cx, vm, r, ip, i, target, ARGC, PLAIN)
    }
}

/// The plain activation of `target`, an `Activates` entry, for the call record `i` at `ip`
/// whose argument count is `ARGC` (`call_argument_count`), past its target's proof
/// (`lane_script_call`, `lane_script_call_leaf`).
macro_rules! lane_plain_activation {
    ($cx:expr, $vm:expr, $r:expr, $ip:expr, $i:expr, $target:expr, $argc:ident, $plain:expr) => {{
        let (cx, vm, r, ip, i, target) = ($cx, $vm, $r, $ip, $i, $target);
        // A plain call's receiver is `undefined` by its record (`lane_script_call`'s `PLAIN`).
        let receiver = if $plain { Value::UNDEFINED } else { r.get(i.c) };
        // A receiver whose binding needs the heap takes the out-of-line form, so this
        // handler makes no call and keeps its registers.
        let Some(this) = lane_direct_call_this(vm, target, receiver) else {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script(cx))
        };
        // Values past the parameters and a full lane stack take the out-of-line form too,
        // whose activation keeps them or grows the stack (`lane_activate`), and so does another
        // program's target (`lane_push_activation`).
        // So does a window past `FIXED_ARGUMENT_COPIES`, whose copy is a call.
        let argc = call_argument_count::<$argc>(i);
        if argc > FIXED_ARGUMENT_COPIES || !lane_admits_window(vm, target, argc) {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script(cx))
        }
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        // A `with` scope refuses every cached target (`LaneStack::refuse_cached_calls`), and
        // only an admitted one reaches here.
        debug_assert!(!vm.with_scope_entered);
        if returns && !lane_returning_call_admitted(cx) {
            return exit(ip);
        }
        // SAFETY: the record's window of `r` holds its values.
        let passed = unsafe { r.0.add(usize::from(ImmediateLayout::call_window_base(i.imm()))).cast_const() };
        // A callee whose entry cell holds a body runs it before any activation exists.
        if !returns
            && unsafe { (*target.view).entry_published() }
            && let Some(resumed) = lane_enter_cell_body(cx, r, ip, target, passed, argc, this)
        {
            resume!(cx, resumed)
        }
        let (registers, base) = lane_push_passed::<H, false, false>(cx, r, ip, target, passed, argc, this, false);
        next!(cx, registers, base, Carried::script(cx))
    }};
}
use lane_plain_activation;

mod leaf_calls;
use leaf_calls::{lane_complete_leaf, lane_materialize_running_leaf, leaf_call_handler};

/// Make the running leaf (`LaneContext::leaf`) the activation its call would have pushed
/// (`lane_enter_window`), before anything observes activations: their materialization
/// (`Vm::materialize_lane_exit`) at the lane's exit, a getter's
/// activation. Its registers, records and PC stay where they are, so a handler may make it
/// anywhere in its record.
#[cold]
#[inline(never)]
fn lane_materialize_leaf<H: Host>(cx: *mut LaneContext<H>) {
    // SAFETY: the running lane's context.
    let leaf = unsafe { std::mem::replace(&mut (*cx).leaf, NO_LEAF_CALL) };
    let vm = unsafe { vm(cx) };
    // SAFETY: the leaf's target stays in its cache while it runs, and its call record
    // belongs to the caller's live view.
    let (target, call) = unsafe { (&*leaf.target, &*leaf.call) };
    let form = leaf.form;
    let stack = &mut vm.lane_stack;
    // SAFETY: the leaf's window starts at the stack's length, within its capacity
    // (`lane_script_call_leaf`).
    let window = unsafe { (*cx).registers.0 };
    unsafe { stack.values.set_top(window.add(usize::from(target.registers) + lane_values::CONTEXT)) };
    let activation = Activation {
        native: crate::vm::compiled::ShadowFrame::EMPTY, function: target.function,
        call: leaf.call,
        caller_base: leaf.caller_base,
        caller_registers: leaf.caller_registers,
        caller_program: leaf.caller_program.unwrap_or(unsafe { (*cx).program }),
        kind: ActivationKind::Script(ScriptActivation {
            callee: target.callee,
            argc: leaf.argc,
            completion: if leaf.caller_program.is_some() { Completion::Cross } else { Completion::Plain },
            forwards: false,
            kept: 0,
            environment: false,
            record: std::ptr::null_mut(),
        }),
    };
    // SAFETY: the call proved room for the activation (`lane_activation_room`).
    unsafe { stack.push_activation(activation, window) };
    if !leaf_binds_this(form) {
        // The receiver the call proved it binds directly (`lane_script_call_leaf`), from the
        // caller's registers, which the leaf does not write.
        let this = lane_direct_call_this(vm, target, leaf.caller_registers.get(call.c))
            .expect("the leaf's call proved its receiver's binding");
        Registers(window).set_this(this);
    }
    if !leaf_swaps_env(form) {
        Registers(window).set_env(target.env);
        Registers(window).set_capture(target.capture);
    }
}

/// The `lane_script_call` argument count of a record its view did not resolve.
const ANY_ARGC: u16 = u16::MAX;

/// The argument count of the call record `i`: `ARGC`, unless that is `ANY_ARGC`.
#[inline(always)]
fn call_argument_count<const ARGC: u16>(i: &LaneInstruction) -> u16 {
    if ARGC == ANY_ARGC { ImmediateLayout::argument_count(i.imm()) } else { ARGC }
}

/// The `lane_script_call` instantiation of a call record whose immediate is `imm`: that of
/// its argument count where the copy of its window is one fixed move
/// (`FIXED_ARGUMENT_COPIES`), else the general one.
fn script_call_handler<H: Host>(imm: u32) -> Handler {
    script_call_handler_of::<H, false>(imm)
}

/// `script_call_handler` of a record whose receiver is its function's `undefined` register
/// where `PLAIN`.
fn script_call_handler_of<H: Host, const PLAIN: bool>(imm: u32) -> Handler {
    const _: () = assert!(FIXED_ARGUMENT_COPIES == 4);
    match ImmediateLayout::argument_count(imm) {
        0 => lane_script_call::<H, 0, PLAIN>,
        1 => lane_script_call::<H, 1, PLAIN>,
        2 => lane_script_call::<H, 2, PLAIN>,
        3 => lane_script_call::<H, 3, PLAIN>,
        4 => lane_script_call::<H, 4, PLAIN>,
        _ => lane_script_call::<H, ANY_ARGC, PLAIN>,
    }
}

/// Gives each call record the `lane_script_call` instantiation of its argument count, and
/// of a receiver that is the function's `undefined` register (`undefined`).
fn specialize_script_calls<H: Host>(records: &mut [LaneInstruction], undefined: Option<crate::bytecode::Register>) {
    let general = lane_script_call::<H, ANY_ARGC, false> as Handler as *const ();
    for record in records.iter_mut().filter(|record| record.handler == general) {
        let handler = if undefined.is_some_and(|register| u16::from(register) == record.c) {
            script_call_handler_of::<H, true>(record.imm())
        } else {
            script_call_handler::<H>(record.imm())
        };
        record.handler = handler as *const ();
    }
}

/// The `this` a plain call of `target` binds for `receiver`: an arrow's lexical one
/// (`ScriptCallTarget::lexical_this`), else `call_this_value`'s without its boxing of
/// primitives, which allocates, so `None` for a sloppy callee's primitive.
#[inline(always)]
fn lane_call_this<H: Host>(vm: &Vm<H>, target: &ScriptCallTarget, receiver: Value) -> Option<Value> {
    match lane_direct_call_this(vm, target, receiver) {
        Some(this) => Some(this),
        None => vm.is_object_like(receiver).then_some(receiver),
    }
}

/// `lane_call_this` where the receiver's own bits decide it: a strict callee, an object in
/// the direct record table, or `null`/`undefined`. `None` for any other receiver, whose
/// object test reads the heap.
#[inline(always)]
fn lane_direct_call_this<H: Host>(
    vm: &Vm<H>,
    target: &ScriptCallTarget,
    receiver: Value,
) -> Option<Value> {
    match target.this_binding {
        ThisBinding::Lexical => Some(target.lexical_this),
        binding => lane_receiver_this(vm, binding, receiver),
    }
}

/// `lane_direct_call_this` of a binding other than an arrow's own `this`, which the
/// receiver alone decides; `None` for `ThisBinding::Lexical`.
#[inline(always)]
fn lane_receiver_this<H: Host>(vm: &Vm<H>, binding: ThisBinding, receiver: Value) -> Option<Value> {
    // Compares, not a table: a sloppy method's object receiver, the common call, takes the
    // first two.
    if binding != ThisBinding::Sloppy {
        // An arrow whose environment binds no `this` takes its caller's receiver.
        return (binding != ThisBinding::Lexical).then_some(receiver);
    }
    // The staged binding (`protocol::bind_this`): an object receiver binds itself, `undefined`
    // and `null` bind the global object, and any other receiver is the host's to box.
    crate::staged::protocol::concrete_bind_this(receiver.to_bits(), vm.realm.globals.to_bits()).map(Value::from_bits)
}

script_handler! {
    /// `lane_script_call` out of line, so the plain call keeps its registers: a receiver
    /// whose binding reads the heap (`lane_call_this`), a forwarding target, which takes
    /// `lane_script_call_keeping`, and a target whose body is a read (`CallEntry::Reads`,
    /// `CallEntry::ReadsElement`), whose hit (`lane_call_read`) completes the
    /// call with its value as the callee's return would; a call that returns its callee's
    /// completion completes its caller in turn (`lane_return_value!`). Anything else
    /// activates the callee. A site that called such a target calls this form directly, so it
    /// makes `lane_script_call`'s own entry tests.
    #[inline(never)]
    fn lane_script_call_full<>(cx, r, ip, i, view) {
        if !unsafe { (*cx).script_calls } {
            return exit(ip);
        }
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        if lane_constructing(vm, callee) {
            sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        let Some(target) = vm.linked_script_call_entry(callee, &i.call_link) else {
            sibling!(lane_script_call_resolve::<H>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: as `Vm::script_call_entry`; a read resolves no target and collects nothing.
        let target = unsafe { &*target };
        if target.entry == CallEntry::Frame {
            sibling!(lane_frame_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        if target.entry == CallEntry::Environment {
            // The site calls its environment target's form directly from now on.
            requicken::<H>(ip, lane_script_call_environment::<H>);
            sibling!(lane_script_call_environment::<H>, r, ip, Carried::script_in(cx, view))
        }
        if target.settles() {
            sibling!(lane_script_call_settles::<H>, r, ip, Carried::script_in(cx, view))
        }
        if target.forwards() {
            sibling!(lane_script_call_keeping::<H>, r, ip, Carried::script_in(cx, view))
        }
        // A receiver whose binding reads the heap takes the general form.
        let Some(this) = lane_direct_call_this(vm, target, r.get(i.c)) else {
            sibling!(lane_script_call_general::<H>, r, ip, Carried::script_in(cx, view))
        };
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, target);
        let arguments = ImmediateLayout::call_window_base(i.imm());
        let argc = ImmediateLayout::argument_count(i.imm());
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        let value = if target.entry.activates()
            || returns && !lane_returning_call_admitted(cx)
        {
            None
        } else {
            let passed = ReadArguments { registers: r, base: arguments, passed: argc };
            // SAFETY: as `lane_call_read`.
            unsafe { lane_answered_call(cx, ip, target, passed, this) }
        };
        let Some(value) = value else {
            // An activation keeping values past the parameters, a full lane stack or another
            // program's target takes the general form (`lane_activate`). A callee that drops
            // the values past its parameters is passed those alone, as `lane_activate` passes them.
            if (argc > target.params && !target.drops_extra_arguments())
                || !lane_activation_room(vm, target)
                || (returns && !lane_returning_call_admitted(cx))
                || vm.with_scope_entered
            {
                sibling!(lane_script_call_general::<H>, r, ip, Carried::script_in(cx, view))
            }
            // SAFETY: the call's window of `r` holds its `argc` values.
            let passed = unsafe { r.0.add(usize::from(arguments)).cast_const() };
            let (registers, base) =
                lane_push_passed::<H, false, false>(cx, r, ip, target, passed, argc.min(target.params), this, false);
            next!(cx, registers, base, Carried::script_in(cx, view))
        };
        if !returns {
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        lane_return_value!(cx, ip, value)
    }
}

script_handler! {
    /// `lane_script_call_full`'s activation of a call its form declines: a receiver whose
    /// binding reads the heap (`lane_call_this`), values past the parameters, which the
    /// keeping activation holds, or a full lane stack (`lane_activate`). Out of line, so the
    /// full form makes no call; it reads no target, which the full form already answered.
    #[inline(never)]
    fn lane_script_call_general<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        let target = vm
            .linked_script_call_entry(callee, &i.call_link)
            .filter(|_| unsafe { (*cx).script_calls } && !lane_constructing(vm, callee));
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
        let Some(target) = target.map(|target| unsafe { &*target }).filter(|target| {
            !matches!(target.entry, CallEntry::Frame | CallEntry::Environment | CallEntry::Settles) && !target.forwards()
        }) else {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        };
        let Some(this) = lane_call_this(vm, target, r.get(i.c)) else {
            return exit(ip);
        };
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, target);
        let arguments = ImmediateLayout::call_window_base(i.imm());
        match lane_activate(cx, r, ip, target, arguments, this, false) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

script_handler! {
    /// `lane_script_call_full` of an environment target (`CallEntry::Environment`), out of
    /// line so the other calls keep their registers: its activation holds its environment
    /// and locals (`lane_activate_environment`). Any other callee takes the full form.
    #[inline(never)]
    fn lane_script_call_environment<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        if !unsafe { (*cx).script_calls } || lane_constructing(vm, callee) {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        }
        // The site's linked entry, which a fresh closure of a function already resolved relinks
        // (`Vm::linked_script_call_entry`); a callee with no target yet resolves in the full form.
        let Some(target) = vm.linked_script_call_entry(callee, &i.call_link) else {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
        let target = unsafe { &*target };
        if target.entry != CallEntry::Environment {
            // A site this form serves calls the full form once its callee's target differs.
            requicken::<H>(ip, lane_script_call_full::<H>);
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        }
        let Some(this) = lane_call_this(vm, target, r.get(i.c)) else {
            return exit(ip);
        };
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, target);
        // SAFETY: the call's window is registers of the running function.
        let passed = unsafe { lane_call_window(r, i) };
        match lane_activate_environment(cx, r, ip, target, passed, (this, false)) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

script_handler! {
    /// `lane_script_call_full` of a non-suspending async target (`CallEntry::Settles`), out of
    /// line so the other calls keep their registers: the call makes its promise first, as
    /// `Vm::try_settling_call` does, then activates the body, whose return settles it
    /// (`Completion::SettlesPromise`). A call passing values past the parameters, a `with`
    /// scope or a host observing promise lifecycles takes the general path, which settles the
    /// promise in a frame, and so does a full lane stack, which grows first
    /// (`lane_script_call_frame`). Any other callee takes the full form.
    #[inline(never)]
    fn lane_script_call_settles<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        let target = vm
            .linked_script_call_entry(callee, &i.call_link)
            .filter(|_| unsafe { (*cx).script_calls } && !lane_constructing(vm, callee));
        // SAFETY: as `Vm::script_call_entry`; the target is copied before anything allocates.
        let Some(target) = target.map(|target| unsafe { *target }).filter(ScriptCallTarget::settles) else {
            requicken::<H>(ip, lane_script_call_full::<H>);
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        };
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        if ImmediateLayout::argument_count(i.imm()) > target.params
            || (returns && !lane_returning_call_admitted(cx))
            || vm.with_scope_entered
            || vm.host.observes_promise_lifecycle()
        {
            return exit(ip);
        }
        if !lane_activation_room(vm, &target) {
            return lane_script_call_frame::<H>(ip, usize::from(target.room));
        }
        let Some(this) = lane_call_this(vm, &target, r.get(i.c)) else {
            return exit(ip);
        };
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, &target);
        // Without lifecycle hooks the promise's allocation runs no guest code and collects
        // nothing (`note_allocation` makes a collection due at the next frame boundary).
        let root = if ImmediateLayout::lane_call_result_awaited(i.imm()) {
            None
        } else {
            let Ok(promise) = vm.promise_object() else {
                return exit(ip);
            };
            note_allocation(vm);
            Some(vm.heap.root(promise))
        };
        vm.lane_stack.settling.push(root);
        let arguments = ImmediateLayout::call_window_base(i.imm());
        let (registers, base) = lane_push_activation::<H, false, true>(cx, r, ip, &target, arguments, this, false);
        next!(cx, registers, base, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An iteration step (`lane_iteration_step`) of this realm's array iterator `next` over a
    /// plain array (`Vm::step_present_array_value`): the step in place, with a result object
    /// only the step's `done` and `value` reads observe (`Vm::reused_iterator_result`). Any
    /// other step is the call it is.
    fn lane_iterator_step<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (method, iterator) = (r.get(i.b), r.get(i.c));
        match vm.iteration_step(iterator, method) {
            super::iterators::IterationStep::Generator if unsafe { (*cx).script_calls } => {
                sibling!(lane_generator_step::<H, 0>, r, ip, Carried::script_in(cx, view))
            }
            super::iterators::IterationStep::Call => sibling!(lane_script_call::<H, ANY_ARGC, false>, r, ip, Carried::script_in(cx, view)),
            _ => {}
        }
        let Some(result) = lane_array_iteration_result(vm, iterator) else {
            sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, result);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// An iteration step (`lane_iteration_step`) of this realm's generator `next` of a
    /// generator that is not running: the generator resumes as an activation over its record
    /// (`lane_resume_generator_step`), or, where its function has no window, as the native
    /// `next` runs it (`Vm::generator_iteration_step`), with a result only the step's `done`
    /// and `value` reads observe.
    /// `READS` names a for-of step whose `done` and `value` reads the generator's yields make
    /// (`Completion::StepReads`, the `ForOfTest` form `STEP_READS_EMITTED` or
    /// `STEP_READS_THREADED`), else `0`.
    #[inline(never)]
    fn lane_generator_step<READS: u8>(cx, r, ip, i, view) {
        let (method, iterator) = (r.get(i.b), r.get(i.c));
        let completion = match READS {
            STEP_READS_EMITTED => Completion::StepReads(ForOfTest::Emitted),
            STEP_READS_THREADED => Completion::StepReads(ForOfTest::Threaded),
            _ => Completion::Generates,
        };
        if let Some((registers, start)) = lane_resume_generator_step(cx, r, ip, i, method, iterator, completion) {
            next!(cx, registers, start, Carried::script_in(cx, view))
        }
        let value = lane_call_from_frame(cx, ip, |vm, code| vm.generator_iteration_step(code, method, iterator));
        resume!(cx, lane_native_complete(cx, ip, i, value))
    }
}

script_handler! {
    /// `lane_iterator_step` of a for-of step (`lane_for_of_step`) over a plain array or a
    /// String, Map or Set iterator (`Vm::step_collection`): the
    /// step's `done` and `value` go to the registers its reads of `done` and `value` write,
    /// and the step goes on where they would, into the body or out of the loop. The result
    /// object only those reads observe is not written. Any other step runs as
    /// `lane_iterator_step` and the records after it.
    fn lane_iterator_step_reads<THREADED: bool>(cx, r, ip, i, view) {
        let form = if THREADED { ForOfTest::Threaded } else { ForOfTest::Emitted };
        let vm = unsafe { vm(cx) };
        let (method, iterator) = (r.get(i.b), r.get(i.c));
        // SAFETY: the view checked the step's records (`lane_for_of_step`).
        let (done_read, value_read) = unsafe { (&*ip.add(FOR_OF_DONE_READ), &*ip.add(form.value_read())) };
        let reads_step = done_read.imm() == vm.runtime_atoms.done && value_read.imm() == vm.runtime_atoms.value;
        let kind = vm.iteration_step(iterator, method);
        match kind {
            super::iterators::IterationStep::Array | super::iterators::IterationStep::Collection if reads_step => {}
            // A generator's step resumes it over its record, as `lane_iterator_step` makes it.
            super::iterators::IterationStep::Generator if unsafe { (*cx).script_calls } && reads_step => {
                if THREADED {
                    sibling!(lane_generator_step::<H, STEP_READS_THREADED>, r, ip, Carried::script_in(cx, view))
                }
                sibling!(lane_generator_step::<H, STEP_READS_EMITTED>, r, ip, Carried::script_in(cx, view))
            }
            super::iterators::IterationStep::Generator if unsafe { (*cx).script_calls } => {
                sibling!(lane_generator_step::<H, 0>, r, ip, Carried::script_in(cx, view))
            }
            _ => sibling!(lane_iterator_step::<H>, r, ip, Carried::script_in(cx, view)),
        }
        let step = if kind == super::iterators::IterationStep::Array {
            vm.step_present_array_value(iterator)
        } else {
            // The compiler marks the step's `RequireIteratorResult` when its value goes only
            // to an array pattern: an entry pair may then be the shared one.
            // SAFETY: the view checked the step's records (`lane_for_of_step`).
            vm.share_entry_pair = unsafe { (*ip.add(FOR_OF_REQUIRE_RESULT)).a } != 0;
            let step = vm.step_collection(iterator);
            vm.share_entry_pair = false;
            note_allocation(vm);
            step
        };
        let Some(step) = step else {
            sibling!(lane_iterator_step::<H>, r, ip, Carried::script_in(cx, view))
        };
        match step {
            Some(value) => {
                r.set(done_read.a, Value::FALSE);
                r.set(value_read.a, value);
                // SAFETY: the step's records end at its `value` read, never the view's last.
                next!(cx, r, unsafe { ip.add(form.records()) }, Carried::script_in(cx, view))
            }
            None => {
                r.set(done_read.a, Value::TRUE);
                // The exit runs as its own record, a `Jump` or the threaded test of the `done`
                // just written: a jump absorbing the move at its target (`JumpFusions::THROUGH`)
                // makes that move before landing past it.
                next!(cx, r, unsafe { ip.add(form.exit()) }, Carried::script_in(cx, view))
            }
        }
    }
}

script_handler! {
    /// `lane_iterator_step` of a destructuring step (`lane_binding_step`) over a plain array
    /// or a String, Map or Set iterator: the step's `done` goes to the register its `done`
    /// read writes and the pattern's done flag the next record moves it to, its `value` to
    /// the register its `value` read writes, and the step goes on past them. The result
    /// object only those reads observe is not written. Any other step runs as
    /// `lane_iterator_step` and the records after it.
    fn lane_iterator_step_binding<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (method, iterator) = (r.get(i.b), r.get(i.c));
        // SAFETY: the view checked the step's records (`lane_binding_step`).
        let (done_read, flag, value_read) =
            unsafe { (&*ip.add(BINDING_DONE_READ), &*ip.add(BINDING_DONE_MOVE), &*ip.add(BINDING_VALUE_READ)) };
        let reads_step = done_read.imm() == vm.runtime_atoms.done && value_read.imm() == vm.runtime_atoms.value;
        let kind = vm.iteration_step(iterator, method);
        match kind {
            super::iterators::IterationStep::Array | super::iterators::IterationStep::Collection if reads_step => {}
            _ => sibling!(lane_iterator_step::<H>, r, ip, Carried::script_in(cx, view)),
        }
        let step = if kind == super::iterators::IterationStep::Array {
            vm.step_present_array_value(iterator)
        } else {
            let step = vm.step_collection(iterator);
            note_allocation(vm);
            step
        };
        let Some(step) = step else {
            sibling!(lane_iterator_step::<H>, r, ip, Carried::script_in(cx, view))
        };
        match step {
            Some(value) => {
                r.set(done_read.a, Value::FALSE);
                r.set(flag.a, Value::FALSE);
                r.set(value_read.a, value);
                // SAFETY: the step's records end at its `value` read, never the view's last.
                next!(cx, r, unsafe { ip.add(BINDING_VALUE_READ + 1) }, Carried::script_in(cx, view))
            }
            None => {
                r.set(done_read.a, Value::TRUE);
                r.set(flag.a, Value::TRUE);
                // The threaded test of the `done` just written leaves the step.
                next!(cx, r, unsafe { ip.add(BINDING_DONE_TEST) }, Carried::script_in(cx, view))
            }
        }
    }
}

/// `lane_iterator_step`'s step and result, out of line: the first result allocates.
#[inline(never)]
fn lane_array_iteration_result<H: Host>(vm: &mut Vm<H>, iterator: Value) -> Option<Value> {
    let step = match vm.step_present_array_value(iterator) {
        Some(step) => step,
        None => Some(vm.step_collection_value(iterator)?),
    };
    let result = vm.reused_iterator_result(step.unwrap_or(Value::UNDEFINED), step.is_none());
    note_allocation(vm);
    Some(result)
}

script_handler! {
    /// A JavaScript `Call` of another program's frameless callee (`LaneStack::cross_targets`):
    /// its activation runs in the callee's program, which its return leaves
    /// (`Completion::Cross`). A site whose callee is no such target calls `lane_script_call`
    /// again.
    #[inline(never)]
    fn lane_script_call_cross<>(cx, r, ip, i, view) {
        if !unsafe { (*cx).script_calls } {
            return exit(ip);
        }
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        if lane_constructing(vm, callee) {
            sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        let Some(target) = vm.linked_cross_call_entry(callee, &i.call_link) else {
            requicken::<H>(ip, script_call_handler::<H>(i.imm()));
            sibling!(lane_script_call::<H, ANY_ARGC, false>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
        let target = unsafe { &*target };
        // A callee that needs a frame takes it as `lane_frame_call` pushes one.
        if !target.entry.activates_across() && target.entry != CallEntry::Environment {
            #[cfg(feature = "profile-lane-exits")]
            super::lane_exits::record_detail(format!("cross call to frame entry={:?}", target.entry as u8));
            sibling!(lane_frame_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        #[cfg(feature = "profile-lane-exits")]
        profile_script_call_target(cx, ip, callee, target);
        // A leaf runs on a window without an activation, as its own program's calls run it.
        if let Some((registers, base)) = leaf_calls::lane_cross_leaf_call(cx, r, ip, i, target) {
            next!(cx, registers, base, Carried::script(cx))
        }
        let Some(this) = lane_call_this(vm, target, r.get(i.c)) else {
            return exit(ip);
        };
        let arguments = ImmediateLayout::call_window_base(i.imm());
        // A plain activation of a window the fixed copies take, not completing its caller,
        // pushes as `lane_script_call`'s does, entering the callee's program
        // (`lane_enter_window`'s cross completion); the site calls its fixed form from now on
        // (`lane_script_call_cross_plain`).
        let argc = ImmediateLayout::argument_count(i.imm());
        if target.entry == CallEntry::Activates
            && i.a & crate::bytecode::RETURN_REGISTER == 0
            && argc <= FIXED_ARGUMENT_COPIES
            && lane_admits_window(vm, target, argc)
        {
            requicken::<H>(ip, cross_plain_handler::<H>(argc));
            // SAFETY: the record's window of `r` holds its values.
            let passed = unsafe { r.0.add(usize::from(arguments)).cast_const() };
            let (registers, base) = lane_push_passed::<H, true, false>(cx, r, ip, target, passed, argc, this, false);
            next!(cx, registers, base, Carried::script(cx))
        }
        let activated = if target.entry == CallEntry::Environment {
            // SAFETY: the call's window is registers of the running function.
            lane_activate_environment(cx, r, ip, target, unsafe { lane_call_window(r, i) }, (this, false))
        } else if target.forwards() {
            lane_activate_keeping::<H, true>(cx, r, ip, target, ActivationArguments::Window(arguments), this, false, None)
        } else {
            lane_activate(cx, r, ip, target, arguments, this, false)
        };
        match activated {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

script_handler! {
    /// `lane_script_call_cross` at a site whose last callee was another program's plain
    /// activation (`CallEntry::Activates`) of `ARGC` arguments, which no completion of its
    /// caller follows: that activation alone, with the fixed copy of its window. Any other
    /// call takes the general cross form.
    fn lane_script_call_cross_plain<ARGC: u16>(cx, r, ip, i, view) {
        if !unsafe { (*cx).script_calls } {
            return exit(ip);
        }
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        let target = if lane_constructing(vm, callee) { None } else { vm.linked_cross_call_entry(callee, &i.call_link) };
        // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
        let Some(target) = target.map(|target| unsafe { &*target }) else {
            sibling!(lane_script_call_cross::<H>, r, ip, Carried::script_in(cx, view))
        };
        if target.entry != CallEntry::Activates || !lane_admits_window(vm, target, ARGC) {
            sibling!(lane_script_call_cross::<H>, r, ip, Carried::script_in(cx, view))
        }
        let Some(this) = lane_direct_call_this(vm, target, r.get(i.c)) else {
            sibling!(lane_script_call_cross::<H>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: the record's window of `r` holds its values.
        let passed = unsafe { r.0.add(usize::from(ImmediateLayout::call_window_base(i.imm()))).cast_const() };
        let (registers, base) = lane_push_passed::<H, true, false>(cx, r, ip, target, passed, ARGC, this, false);
        next!(cx, registers, base, Carried::script(cx))
    }
}

/// The `lane_script_call_cross_plain` instantiation of a window of `argc` values, at most
/// `FIXED_ARGUMENT_COPIES`.
fn cross_plain_handler<H: Host>(argc: u16) -> Handler {
    const _: () = assert!(FIXED_ARGUMENT_COPIES == 4);
    match argc {
        0 => lane_script_call_cross_plain::<H, 0>,
        1 => lane_script_call_cross_plain::<H, 1>,
        2 => lane_script_call_cross_plain::<H, 2>,
        3 => lane_script_call_cross_plain::<H, 3>,
        _ => lane_script_call_cross_plain::<H, 4>,
    }
}

script_handler! {
    /// `lane_script_call` of a callee its target cache does not hold: resolving it
    /// (`Vm::resolve_script_call_target`) makes a call, so it runs out of line and the call
    /// continues at `lane_script_call`, which then finds it, or at `lane_native_call`.
    #[inline(never)]
    fn lane_script_call_resolve<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        if vm.cross_call_entry(callee).is_some() {
            requicken::<H>(ip, lane_script_call_cross::<H>);
            sibling!(lane_script_call_cross::<H>, r, ip, Carried::script_in(cx, view))
        }
        if let Some(target) = vm.resolve_script_call_target(code, callee) {
            if target.program() == vm.active_program {
                // Under a `with` scope or a pending construction no cached target admits a
                // call (`LaneStack::set_refused`): the call leaves the lane, as it would.
                if vm.lane_stack.refuses() {
                    return exit(ip);
                }
                sibling!(lane_script_call::<H, ANY_ARGC, false>, r, ip, Carried::script_in(cx, view))
            }
            // Another program's callee that needs a frame takes it as `lane_frame_call`
            // pushes one.
            if !target.entry.activates() {
                sibling!(lane_frame_call::<H>, r, ip, Carried::script_in(cx, view))
            }
            requicken::<H>(ip, lane_script_call_cross::<H>);
            sibling!(lane_script_call_cross::<H>, r, ip, Carried::script_in(cx, view))
        }
        // A site calling a native takes the native handler from now on, which hands any other
        // callee back.
        if let Some(FunctionRecord { kind: FunctionKind::Native(native), .. }) = vm.heap.function(callee) {
            let native = *native;
            let handler = native_call_handler::<H>(native, i, || lane_call_result_dead(cx, ip, i));
            requicken::<H>(ip, handler);
            if handler as *const () != lane_native_call::<H> as *const () {
                native_calls::install_math_field_call::<H>(cx, ip, native);
            }
        }
        sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view))
    }
}

/// The by-name load a `LoadName` handler runs for: a `LoadNameCall` also
/// writes its call's receiver, and a `LoadNameTypeof` reads an absent global as `undefined`.
const LOAD_NAME: u8 = 0;
/// `LOAD_NAME` for `LoadNameCall`.
const LOAD_NAME_CALL: u8 = 1;
/// `LOAD_NAME` for `LoadNameTypeof`.
const LOAD_NAME_TYPEOF: u8 = 2;

/// What a by-name load's first run resolves its name to: the `lane_load_name_bound` instance its
/// record runs from then on, which holds the binding.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum NameResolution {
    /// The active realm's function for the native an internal name stands for
    /// (`Vm::intrinsic_natives`), which no binding can shadow and no scope affects.
    Native,
    /// The global `undefined`, which is non-writable and non-configurable and which no global
    /// lexical declaration may shadow (GlobalDeclarationInstantiation rejects a restricted
    /// global property): a read of it is always `undefined`.
    Undefined,
    /// A name the global object answers whenever no global lexical binding shadows it: a function
    /// whose unresolved names are global (`ProgramStore::names_are_global`) and resolve
    /// statically, and a name no internal binding owns. Static resolution rules out a `with`
    /// object, which the general search consults first.
    Global,
    /// An intrinsic name (`bytecode::is_intrinsic_name`), as the compiler emits for
    /// `{ __proto__: v }` or `super`: the native it stands for (`Vm::intrinsic_name_value`).
    Intrinsic,
    /// Any other name, which the general path resolves.
    General,
}

/// A `lane_load_name_bound` that reads the native an internal name stands for.
const BOUND_NATIVE: u8 = 0;
/// A `lane_load_name_bound` of the global `undefined`.
const BOUND_UNDEFINED: u8 = 1;
/// A `lane_load_name_bound` that reads the global object's own data field its record's hint names.
const BOUND_GLOBAL: u8 = 2;
/// A `lane_load_name_bound` of an intrinsic name.
const BOUND_INTRINSIC: u8 = 3;

/// The resolution of the by-name load of `atom` in the function `cx` runs. A native an internal
/// name stands for is recorded for its reads (`Vm::intrinsic_natives`). An internal name is no
/// binding source text can declare, except the internal globals the realm installs on its global
/// object, which a static lookup reads as any other.
fn lane_name_resolution<H: Host>(cx: *mut LaneContext<H>, atom: u32) -> NameResolution {
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let vm = unsafe { vm(cx) };
    let internal = vm.atom_class(atom).contains(AtomClass::INTERNAL);
    if internal && let Some(native) = crate::bytecode::intrinsic_name_native(&code.atoms[atom as usize]) {
        let slot = atom as usize;
        if vm.intrinsic_natives.len() <= slot {
            vm.intrinsic_natives.resize(slot + 1, None);
        }
        vm.intrinsic_natives[slot] = Some(native);
        return NameResolution::Native;
    }
    // The running function decides the name's scope: a running leaf's is its materialized
    // activation's.
    lane_materialize_running_leaf(cx);
    let function = lane_running_function(cx);
    let global = code.function_get(function as usize).is_some_and(|function| function.names_resolve_statically(code))
        && vm.programs.names_are_global(unsafe { (*cx).program })
        && (!internal || crate::bytecode::INTERNAL_GLOBAL_BINDINGS.contains(&vm.atom_name(atom)));
    match (global, vm.atom_name(atom)) {
        (true, UNDEFINED_GLOBAL) => NameResolution::Undefined,
        (true, _) => NameResolution::Global,
        (false, name) if crate::bytecode::is_intrinsic_name(name) => NameResolution::Intrinsic,
        (false, _) => NameResolution::General,
    }
}

script_handler! {
    /// A by-name load's first run: the VM's resolution of its name (`lane_name_resolution`) fills
    /// the record, whose handler from then on is the `lane_load_name_bound` instance holding the
    /// binding, or leaves every run to the general path. `KIND` is the load's (`LOAD_NAME`).
    #[inline(never)]
    fn lane_load_name_resolve<KIND: u8>(cx, r, ip, i, view) {
        let bound: Handler = match lane_name_resolution(cx, i.imm()) {
            NameResolution::Native => lane_load_name_bound::<H, KIND, BOUND_NATIVE>,
            NameResolution::Undefined => lane_load_name_bound::<H, KIND, BOUND_UNDEFINED>,
            NameResolution::Global => lane_load_name_bound::<H, KIND, BOUND_GLOBAL>,
            NameResolution::Intrinsic => lane_load_name_bound::<H, KIND, BOUND_INTRINSIC>,
            NameResolution::General => {
                // SAFETY: the context's program outlives the lane run.
                let code = unsafe { &*(*cx).code };
                if code.function_get(lane_running_function(cx) as usize).is_some_and(|body| body.call_plan(code).holds_window_scope()) {
                    requicken::<H>(ip, scoped_names::scoped_load_name::<H, KIND>());
                    sibling!(scoped_names::scoped_load_name::<H, KIND>(), r, ip, Carried::script_in(cx, view))
                }
                // Any other name's scope is a runtime fact, which the general path's read settles
                // (`lane_load_name_probe`).
                if !unsafe { vm(cx) }.atom_class(i.imm()).contains(AtomClass::INTERNAL) {
                    requicken::<H>(ip, probe_handler::<H, KIND>());
                    sibling!(probe_handler::<H, KIND>(), r, ip, Carried::script_in(cx, view))
                }
                requicken::<H>(ip, lane_exit::<H>);
                return exit(ip);
            }
        };
        requicken::<H>(ip, bound);
        sibling!(bound, r, ip, Carried::script_in(cx, view))
    }
}

/// The binding the record `i` of `lane_load_name_bound::<_, _, BOUND>` holds: a global's is its
/// record's own-field hint.
#[inline(always)]
fn lane_name_binding<const BOUND: u8>(i: &LaneInstruction) -> NameBinding {
    match BOUND {
        BOUND_NATIVE => NameBinding::Read(NameRead::Native),
        BOUND_UNDEFINED => NameBinding::Undefined,
        BOUND_GLOBAL => NameBinding::Read(NameRead::Field(i.field_hint())),
        BOUND_INTRINSIC => NameBinding::Read(NameRead::Intrinsic),
        _ => unreachable!("a bound name load holds one of the BOUND_ bindings"),
    }
}

script_handler! {
    /// A by-name load whose first run resolved its name (`lane_load_name_resolve`): the staged
    /// `LoadName` row over the binding `BOUND` names, whose call receiver (`LOAD_NAME_CALL`) is
    /// `undefined`, as for any global. A global object's own data field is read through its
    /// record's hint (`LaneInstruction::field_hint`): one shape test and one load, the hint set
    /// only while no realm declares the name lexically (`Vm::global_name_hintable`), a
    /// declaration clearing it (`Vm::note_global_lexical_names`), and the global object's
    /// deletes, redefinitions and storage changes changing its exact shape. A read the binding
    /// does not answer takes its residual: a global's `lane_load_global_name_refresh`, a native's
    /// resolution again, and an intrinsic name's the general path.
    fn lane_load_name_bound<KIND: u8, BOUND: u8>(cx, r, ip, i, view) {
        if !staged_load_name(cx, r, i, KIND == LOAD_NAME_CALL, lane_name_binding::<BOUND>(i)) {
            match BOUND {
                BOUND_GLOBAL => sibling!(lane_load_global_name_refresh::<H, KIND, false>, r, ip, Carried::script_in(cx, view)),
                BOUND_NATIVE => sibling!(lane_load_name_resolve::<H, KIND>, r, ip, view),
                _ => return exit(ip),
            }
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The function the lane runs: its innermost activation's, or else its frame's.
#[inline(always)]
fn lane_running_function<H: Host>(cx: *mut LaneContext<H>) -> u32 {
    let vm = unsafe { vm(cx) };
    vm.lane_stack.activations.last().map_or_else(|| vm.frames[unsafe { (*cx).frame() }].function, |activation| activation.function)
}

/// The global value property `lane_name_resolution` answers without a lookup.
const UNDEFINED_GLOBAL: &str = "undefined";

script_handler! {
    /// A `StoreName`'s first run: an assignment to a name the global object answers whenever
    /// no global lexical binding shadows it (as `lane_name_resolution` decides for a read)
    /// takes `lane_store_global_name`, a `var`'s initializer too, which stores as one: the
    /// declaration made the property, and a lexical binding is never hinted. Any other store
    /// always takes the general path.
    #[inline(never)]
    fn lane_store_name_first<>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let function = lane_running_function(cx);
        let global = !vm.atom_class(i.imm()).contains(AtomClass::INTERNAL)
            && code.function_get(function as usize).is_some_and(|function| function.names_resolve_statically(code))
            && vm.programs.names_are_global(unsafe { (*cx).program });
        if global {
            requicken::<H>(ip, lane_store_global_name::<H>);
            sibling!(lane_store_global_name::<H>, r, ip, Carried::script_in(cx, view))
        }
        if code.function_get(function as usize).is_some_and(|body| body.call_plan(code).holds_window_scope()) {
            requicken::<H>(ip, scoped_names::scoped_store_name::<H>());
            sibling!(scoped_names::scoped_store_name::<H>(), r, ip, Carried::script(cx))
        }
        requicken::<H>(ip, lane_exit::<H>);
        exit(ip)
    }
}

script_handler! {
    /// A global name store (`lane_store_name_first`) through its record's hint: the global
    /// object's own writable data field, which no realm's lexical declaration shadows while
    /// the hint is held.
    fn lane_store_global_name<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !vm.hinted_own_field_store_hit(i.field_hint(), vm.realm.globals, i.imm(), r.get(i.a)) {
            sibling!(lane_store_global_name_miss::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_store_global_name` past its hint: the global object's own writable data field,
    /// which becomes the hint where no realm declares the name lexically
    /// (`Vm::global_name_hintable`); any other store takes the general path, a shadowed name's
    /// from then on.
    #[inline(never)]
    fn lane_store_global_name_miss<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (atom, globals) = (i.imm(), vm.realm.globals);
        // A lexical declaration of the name is never withdrawn, so its stores always take the
        // general path.
        if !vm.global_name_hintable(atom) {
            requicken::<H>(ip, lane_exit::<H>);
            return exit(ip);
        }
        let Some(hint) = vm
            .own_data_field_hint::<true>(globals, atom)
            .filter(|hint| vm.hinted_own_field_store_hit(*hint, globals, atom, r.get(i.a)))
        else {
            return exit(ip);
        };
        set_field_hint(ip, hint);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A `LoadName` the general path's probe found landing on the global object
    /// (`settle_name_record`): the global object's own data field its record's hint names
    /// (`LaneInstruction::field_hint`), one shape test and one load, as `lane_load_name_bound`
    /// reads a global. Any other read takes `lane_load_global_name_refresh`. A `LoadNameCall`
    /// (`LOAD_NAME_CALL`) also writes the call's receiver, `undefined` for a global binding.
    fn lane_load_global_name<KIND: u8, SCOPED: bool>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let Some(value) = vm.record_field_entry_hit(i.field_hint(), vm.realm.globals) else {
            sibling!(lane_load_global_name_refresh::<H, KIND, SCOPED>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        if KIND == LOAD_NAME_CALL {
            r.set(i.b, Value::UNDEFINED);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_load_name_bound` of a global, or `lane_load_global_name`, past its record's hint: an
    /// initialized global lexical binding of
    /// the name, which the general path's search finds first there; else the global object's
    /// own data field, which becomes the hint (`Vm::own_data_field_hint`), or its cached field
    /// (`Vm::cached_field_hit`). Any other read takes `lane_load_global_name_miss`, or the general
    /// path for an uninitialized binding. `typeof` (`LOAD_NAME_TYPEOF`) reads an absent name as
    /// `undefined`.
    #[inline(never)]
    fn lane_load_global_name_refresh<KIND: u8, SCOPED: bool>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let vm = unsafe { vm(cx) };
        let atom = i.imm();
        // A read the general path found past a scope that could declare the name holds only
        // until some scope does (`Vm::note_dynamic_scope_name`).
        if SCOPED && vm.scope_names.declared(atom) {
            requicken::<H>(ip, lane_exit::<H>);
            return exit(ip);
        }
        let value = match vm.global_name_read(code, atom, i.c) {
            super::field_cache::GlobalNameRead::Value(value, hint) => {
                if let Some(hint) = hint { set_field_hint(ip, hint); }
                value
            }
            super::field_cache::GlobalNameRead::Uninitialized => return exit(ip),
            super::field_cache::GlobalNameRead::Miss => sibling!(lane_load_global_name_miss::<H, KIND>, r, ip, Carried::script_in(cx, view)),
        };
        r.set(i.a, value);
        if KIND == LOAD_NAME_CALL {
            r.set(i.b, Value::UNDEFINED);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_load_global_name_refresh` past its lexical binding and global property: a
    /// global accessor's getter, activated in the lane, or a plain global property, recorded
    /// in the site's entry; any other read takes the general path. Out of line: the getter's
    /// activation and the lookups take stack temporaries, which the common read then does not
    /// hold.
    #[inline(never)]
    fn lane_load_global_name_miss<KIND: u8>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let atom = i.imm();
        let globals = vm.realm.globals;
        if let Some(getter) = vm.cached_field_getter(globals, atom, vm.field_cache_index(i.c)) {
            if !unsafe { (*cx).script_calls } {
                return exit(ip);
            }
            // A binding of the global object's environment calls with an `undefined`
            // receiver.
            if KIND == LOAD_NAME_CALL {
                r.set(i.b, Value::UNDEFINED);
            }
            return match lane_activate_getter(cx, r, ip, getter, globals, None) {
                Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                Err(next) => next,
            };
        }
        // A present data property records the site's entry as the general path's read
        // does (`Vm::field_miss_data_value`): the global object changes shape as Node's
        // lazy globals materialize, and a site that only walked would miss from then
        // on. Only a present one: that read answers an absent key as `[[Get]]` does,
        // where the binding raises. A global object no cache records (a dictionary
        // shape) still answers a present data property through its shape walk. An
        // absent name is `undefined` to `typeof` and raises on the general path
        // otherwise.
        let value = match vm.plain_global_lookup(atom) {
            Some(Some(value)) => vm
                .field_miss_data_value(globals, atom, vm.field_cache_index(i.c))
                .unwrap_or(value),
            Some(None) if KIND == LOAD_NAME_TYPEOF => Value::UNDEFINED,
            _ => return exit(ip),
        };
        r.set(i.a, value);
        if KIND == LOAD_NAME_CALL {
            r.set(i.b, Value::UNDEFINED);
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `new Array(...values)` of an intrinsic `Array`, which allocates without running guest
    /// code: the array of the values passed, or for one Number argument the array of that
    /// length (`Vm::array_of_length`), with the callee's own `prototype`. An invalid length,
    /// and any other construction, take the general path.
    #[inline(never)]
    fn lane_native_construct<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        match vm.heap.function(callee) {
            Some(FunctionRecord { kind: FunctionKind::User(..), .. }) => {
                if let Some(parent) = lane_super_forwarded_parent(vm, callee) {
                    resume!(cx, lane_construct_forwarded_parent(cx, r, ip, i, callee, parent));
                }
                if let Some(this) = lane_super_construction(cx, r, i, callee) {
                    // Allocating the receiver can make a collection due.
                    note_allocation(vm);
                    if returns {
                        resume!(cx, lane_return_constructed(cx, ip, this))
                    }
                    r.set(i.a, this);
                    next!(cx, r, following(ip), Carried::script_in(cx, view))
                }
                return lane_frame_construct(cx, r, ip, i);
            }
            Some(FunctionRecord { kind: FunctionKind::Native(native), .. })
                if native.constructs_from_lane() && !returns =>
            {
                let argc = usize::from(ImmediateLayout::argument_count(i.imm()));
                // SAFETY: the construction's window is registers of the running function.
                let args = unsafe { std::slice::from_raw_parts(r.0.add(usize::from(i.c)), argc) };
                let Some(value) = lane_construct_native(cx, ip, callee, callee, args) else {
                    return exit(ip);
                };
                // The construction ran from the innermost frame, whose registers are the lane's.
                let r = unsafe { (*cx).registers };
                r.set(i.a, value);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            _ => {}
        }
        if returns && vm.lane_stack.activations.is_empty() {
            return exit(ip);
        }
        let argc = usize::from(ImmediateLayout::argument_count(i.imm()));
        // SAFETY: the construction's window is registers of the running function.
        let args = unsafe { std::slice::from_raw_parts(r.0.add(usize::from(i.c)), argc) };
        let Some(array) = vm.intrinsic_array_construction(callee, args) else {
            return exit(ip);
        };
        note_allocation(vm);
        if returns {
            let Some(resumed) = lane_complete_activation(cx, ip, array) else {
                unreachable!("a returning lane construction has an activation caller");
            };
            resume!(cx, resumed)
        }
        r.set(i.a, array);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A call that forwards without an observable step of its own (`Vm::forwarded_call`):
    /// `f.call(thisArg, ...args)`, a bound function without bound arguments, or an
    /// uncurried builtin (`uncurryThis(f)(thisArg, ...args)`). A frameless target's
    /// activation is the one `lane_script_call` makes, and a native runs as
    /// `lane_native_call` runs it, with the forwarded receiver and arguments. Any other
    /// takes the general path.
    #[inline(never)]
    fn lane_function_call<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        // SAFETY: the call's window is registers of the running function, which the
        // activation or native call copies before anything can move them.
        let window = unsafe { lane_call_window(r, i) };
        // `f.call(thisArg, ...args)` of a callee the site linked (`lane_forwarded_target`):
        // the forwarding is one step, so its activation needs no walk of `forwarded_call`.
        // SAFETY: a call record's operand is `call`.
        let link = unsafe { (*ip).operand.call.memo } as usize;
        if vm.script_call_holds(link, r.get(i.c))
            && matches!(vm.heap.function(r.get(i.b)), Some(FunctionRecord { kind: FunctionKind::Native(Native::FunctionCall), .. }))
            && !vm.tier_may_run(crate::jit_mode::Tier::ANY)
        {
            let (receiver, args) = window.split_first().map_or((Value::UNDEFINED, &[][..]), |(first, rest)| (*first, rest));
            resume!(cx, lane_function_call_activation(cx, r, ip, i, r.get(i.c), receiver, args))
        }
        // A bound function without bound arguments the lane last forwarded through, whose
        // target the site linked: its target and receiver, read once (`LaneStack::bound_call`).
        if let Some((bound, target, this)) = vm.lane_stack.bound_call
            && bound == r.get(i.b)
            && vm.script_call_holds(link, target)
            && !vm.tier_may_run(crate::jit_mode::Tier::ANY)
        {
            resume!(cx, lane_function_call_activation(cx, r, ip, i, target, this, window))
        }
        let Some(super::function::Forwarded { callee, receiver, args, kind, through_call }) = vm.forwarded_call(r.get(i.b), r.get(i.c), window) else {
            resume!(cx, lane_bound_arguments_call(cx, r, ip, i));
        };
        // The function a forwarded call calls is the site's callee, through its native, for a
        // body that inlines it (`lane_unit::Planner::through_call`).
        if through_call
            && vm.tier_may_run(crate::jit_mode::Tier::ANY)
            && let Some((program, function, _, false)) = vm.same_realm_script_target(callee)
            && program == vm.active_program
        {
            vm.note_site_callee(&i.call_link, super::compiled::CallTarget { callee: super::compiled::CalleeBinding::Forwarded { through: r.get(i.b), callee }, function });
        }
        if let Some(FunctionKind::Native(native)) = kind {
            if i.a & crate::bytecode::RETURN_REGISTER != 0 && !lane_returning_call_admitted(cx) {
                return exit(ip);
            }
            let value = lane_native_value(cx, ip, i, native, callee, receiver, args);
            resume!(cx, lane_native_complete(cx, ip, i, value));
        }
        if matches!(kind, Some(FunctionKind::User(..))) {
            lane_remember_bound_call(vm, r.get(i.b));
        }
        resume!(cx, lane_function_call_activation(cx, r, ip, i, callee, receiver, args))
    }
}

/// Remembers `callee` for `lane_function_call`'s bound fast path (`LaneStack::bound_call`)
/// when it is a bound function without bound arguments of a user function.
#[inline(never)]
fn lane_remember_bound_call<H: Host>(vm: &mut Vm<H>, callee: Value) {
    let Some(FunctionRecord { kind: FunctionKind::Native(Native::FunctionBoundCall), env, .. }) = vm.heap.function(callee) else {
        return;
    };
    let Some((target, this, bound)) = vm.bound_function_parts(*env) else { return };
    if bound.is_empty() && matches!(vm.heap.function(target), Some(FunctionRecord { kind: FunctionKind::User(..), .. })) {
        vm.lane_stack.bound_call = Some((callee, target, this));
    }
}

/// `lane_function_call` of a bound function with bound arguments, which lead the values the
/// call passes (ECMA-262 10.4.1.1): the forwarded call with the values copied out
/// (`Vm::forwarded_call`), a user function's activation or frame call
/// (`FrameCallArguments::List`), else the general path.
#[inline(never)]
fn lane_bound_arguments_call<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, i: &LaneInstruction) -> Resumed {
    let vm = unsafe { vm(cx) };
    // SAFETY: as in `lane_function_call`; the values are copied before anything runs.
    let window = unsafe { lane_call_window(r, i) };
    let copied = smallvec::SmallVec::<[Value; FRAME_CALL_INLINE_ARGUMENTS]>::from_slice(window);
    let Some(super::function::Forwarded { callee, receiver, args, kind, .. }) = vm.forwarded_call(r.get(i.b), r.get(i.c), copied) else {
        return Resumed::Exit(exit(ip));
    };
    if !matches!(kind, Some(FunctionKind::User(..))) {
        return Resumed::Exit(exit(ip));
    }
    let Some(target) = lane_passed_target(cx, callee, args.len()) else {
        return lane_passed_frame_call(cx, r, ip, i, callee, receiver, FrameCallArguments::List(&args));
    };
    let Some(this) = lane_call_this(vm, &target, receiver) else {
        return Resumed::Exit(exit(ip));
    };
    match lane_activate_passed(cx, r, ip, &target, &args, this) {
        Ok((registers, base)) => Resumed::At(registers, base, Carried::script(cx)),
        Err(next) => Resumed::Exit(next),
    }
}

/// `lane_function_call`'s activation of the frameless `callee` with the forwarded `receiver`
/// and `args`: the callee's registers and first record, or the record to continue at. Out of line, as `lane_construct_keeping_activation`.
#[inline(never)]
fn lane_function_call_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Resumed {
    let vm = unsafe { vm(cx) };
    let mut resolved = None;
    let Some(target) = lane_forwarded_target(cx, ip, callee, args.len(), &mut resolved) else {
        return Resumed::Exit(lane_forwarded_frame_call(cx, r, ip, i, callee, receiver, args));
    };
    // `call_this_value` without its boxing of primitives, which allocates.
    let Some(this) = lane_call_this(vm, target, receiver) else {
        return Resumed::Exit(exit(ip));
    };
    if let Some(resumed) = lane_forwarded_cell_entry(cx, r, ip, i, target, args, this) {
        return resumed;
    }
    match lane_activate_passed(cx, r, ip, target, args, this) {
        Ok((registers, base)) => Resumed::At(registers, base, Carried::script(cx)),
        Err(next) => Resumed::Exit(next),
    }
}

/// `lane_passed_target` of a forwarded call's `callee` at the call record `ip`, whose read
/// memo slot links the callee's cache entry, as an array callback method's call links its
/// callback's (`lane_callback_target`): the link, tested first, skips the set's hash and the
/// cross-program and environment lookups for a callee the running program activates.
#[inline(always)]
fn lane_forwarded_target<'a, H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    callee: Value,
    passed: usize,
    resolved: &'a mut Option<ScriptCallTarget>,
) -> Option<&'a ScriptCallTarget> {
    let vm = unsafe { vm(cx) };
    // SAFETY: a call record's operand is `call`.
    let link = unsafe { (*ip).operand.call.memo } as usize;
    if vm.script_call_holds(link, callee) && !lane_constructing(vm, callee) {
        // SAFETY: `script_call_holds` found the entry within the cache, which nothing
        // resolves into before the caller reads it; read in place, not copied.
        let target = unsafe { &*std::ptr::from_ref(vm.lane_stack.script_targets.entries.get_unchecked(link)) };
        if lane_admits_activation(target) {
            return Some(target);
        }
    }
    let target = resolved.insert(lane_passed_target(cx, callee, passed)?);
    if let Some(index) = vm.script_call_index(callee) {
        // SAFETY: as `requicken`: the record's operand is the call's, written in place.
        unsafe { (*ip.cast_mut()).operand.call.memo = index as u32 };
    }
    Some(target)
}

/// `lane_enter_cell_body` of a forwarded call of a plain target of the running program, passed
/// at most its parameters and not completing its caller, whose entry cell holds a body.
#[inline(always)]
fn lane_forwarded_cell_entry<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    target: &ScriptCallTarget,
    args: &[Value],
    this: Value,
) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    let argc = u16::try_from(args.len()).ok().filter(|argc| *argc <= target.params)?;
    (target.entry == CallEntry::Activates
        && !lane_crosses::<H, true>(cx, target)
        && i.a & crate::bytecode::RETURN_REGISTER == 0
        && !vm.with_scope_entered
        && lane_activation_room(vm, target)
        && unsafe { (*target.view).entry_published() })
    .then_some(())?;
    lane_enter_cell_body(cx, r, ip, target, args.as_ptr(), argc, this)
}

/// The frameless target a forwarded or applied call of `callee` with `passed` values
/// activates: one of the running program (`lane_script_target`), another program's plain,
/// keeping or environment activation (`cross_call_entry`), or the running program's
/// environment target, which `lane_script_target` leaves to plain calls; an environment
/// target only when it binds each value to a parameter (`lane_activate_environment`).
#[inline(never)]
fn lane_passed_target<H: Host>(cx: *mut LaneContext<H>, callee: Value, passed: usize) -> Option<ScriptCallTarget> {
    let vm = unsafe { vm(cx) };
    // Matched in turn rather than chained: the combinators moved the target through copies.
    let target = match lane_script_target(cx, callee) {
        Some(target) => target,
        None => {
            // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target or collects.
            let cross = (!lane_constructing(vm, callee))
                .then(|| vm.cross_call_entry(callee))
                .flatten()
                .map(|entry| unsafe { &*entry })
                .filter(|target| target.entry.activates_across() || target.entry == CallEntry::Environment);
            // SAFETY: as above.
            let own = || {
                vm.script_call_entry(callee)
                    .map(|entry| unsafe { &*entry })
                    .filter(|target| target.entry == CallEntry::Environment && target.program() == vm.active_program)
            };
            match cross {
                Some(target) => *target,
                None => *own()?,
            }
        }
    };
    if target.entry == CallEntry::Environment
        && passed > usize::from(target.params)
        && !vm.programs.residual(target.program())?.function(target.function as usize).rest
    {
        return None;
    }
    Some(target)
}

/// The activation of a `lane_passed_target` with receiver `this` and the `passed` values:
/// an environment activation, a plain call's push where the callee keeps nothing past its
/// parameters, or a keeping one, which keeps them; either may enter another program
/// (`Completion::Cross`).
#[inline(always)]
fn lane_activate_passed<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: &[Value],
    this: Value,
) -> Result<(Registers, Ip), Ip> {
    if target.entry == CallEntry::Environment {
        return lane_activate_environment(cx, r, ip, target, passed, (this, false));
    }
    lane_activate_kept::<H, true>(cx, r, ip, target, passed, this)
}

/// The activation of `target`, of the running program unless `MAY_CROSS`, for the record at
/// `ip` with receiver `this` and the `passed` values, which lie outside the caller's call
/// window (a forwarded or applied call's, a getter's none): a callee that keeps no passed
/// values (`ScriptCallTarget::forwards`) and is passed at most its parameters, or drops the
/// rest, takes the plain call's push (`lane_activate`); any other, a keeping activation.
#[inline(always)]
fn lane_activate_kept<H: Host, const MAY_CROSS: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: &[Value],
    this: Value,
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    let argc = u16::try_from(passed.len()).unwrap_or(u16::MAX);
    // SAFETY: `ip` is a record of the running view.
    let returns = unsafe { (*ip).a } & crate::bytecode::RETURN_REGISTER != 0;
    if !target.forwards()
        && (argc <= target.params || target.drops_extra_arguments())
        && (!returns || lane_returning_call_admitted(cx))
        && !vm.with_scope_entered
        && lane_activation_room(vm, target)
    {
        return Ok(lane_push_passed::<H, MAY_CROSS, false>(cx, r, ip, target, passed.as_ptr(), argc.min(target.params), this, false));
    }
    let arguments = ActivationArguments::Kept(passed.as_ptr(), passed.len());
    lane_activate_keeping::<H, MAY_CROSS>(cx, r, ip, target, arguments, this, false, None)
}

/// `lane_function_call` of a forwarded `callee` with no frameless target: a user function
/// the general loop pushes in place (`Vm::in_loop_call_target`) takes its frame as
/// `lane_frame_call` makes it, with the forwarded `receiver` and `args`, the call window's
/// tail. Any other takes the general path.
#[inline(never)]
fn lane_forwarded_frame_call<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Ip {
    let skip = usize::from(ImmediateLayout::argument_count(i.imm())) - args.len();
    lane_passed_frame_call(cx, r, ip, i, callee, receiver, FrameCallArguments::Window(skip)).into_loop()
}

/// The frame call of `callee` with `receiver` and `passed` that `lane_forwarded_frame_call`
/// and an applied call (`lane_apply_activation`) make.
fn lane_passed_frame_call<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    callee: Value,
    receiver: Value,
    passed: FrameCallArguments<'_>,
) -> Resumed {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if !unsafe { (*cx).script_calls } || returns && !lane_returning_call_admitted(cx) {
        return Resumed::Exit(exit(ip));
    }
    let Some(target) = vm.in_loop_call_target(code, callee) else {
        #[cfg(feature = "profile-lane-exits")]
        super::lane_exits::record_detail(format!(
            "passed frame call declined kind={:?} realm_matches={} name={:?}",
            vm.heap.function(callee).map(|record| match record.kind {
                FunctionKind::Native(Native::HostFunction) => vm.host_function_name(callee).unwrap_or_default().to_string(),
                FunctionKind::Native(native) => format!("{native:?}"),
                FunctionKind::User(..) => "user".to_string(),
            }),
            vm.heap.function(callee).is_some_and(|record| record.realm == vm.realm.globals),
            vm.heap.function(callee).and_then(|record| match record.kind {
                FunctionKind::User(program, function) => vm.programs.residual(program).and_then(|code| {
                    let body = code.function_get(function as usize)?;
                    Some(format!("{} @{:?} async={} generator={} in_loop={}",
                        body.name.map(|atom| code.atoms[atom as usize].to_string()).unwrap_or_default(),
                        body.source_span.map(|span| span.start), body.is_async, body.is_generator, body.call_plan(code).in_loop))
                }),
                _ => None,
            }),
        ));
        return Resumed::Exit(exit(ip));
    };
    lane_push_frame_call(cx, r, ip, i, target, callee, receiver, passed)
}

/// The values a frame call passes its callee (`lane_push_frame_call`).
#[derive(Clone, Copy)]
enum FrameCallArguments<'a> {
    /// The call window's values past its first `skip` (a forwarded call's own arguments),
    /// read again once the caller is a frame.
    Window(usize),
    /// Values the caller copied out, as an applied list's elements.
    List(&'a [Value]),
}

script_handler! {
    /// A `Call` of `Array.prototype.push` or `pop` on a dense array (`Vm::array_push_dense`,
    /// `Vm::array_pop_dense`), which completes without calling out or allocating cells, or
    /// of a string method that runs no guest code (`Vm::pure_string_method_call`), or of a
    /// native the running frame calls in place (`lane_call_native`); out of line, so script
    /// calls keep their code. Any other call takes the general path.
    #[inline(never)]
    fn lane_native_call<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        // The callee's kind, read once: a call changes no function record before it runs.
        let native = match vm.heap.function(r.get(i.b)) {
            Some(FunctionRecord {
                kind: FunctionKind::Native(native),
                ..
            }) => *native,
            _ => sibling!(lane_frame_call::<H>, r, ip, Carried::script_in(cx, view)),
        };
        if matches!(native, Native::FunctionCall | Native::FunctionBoundCall) {
            sibling!(lane_function_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        if matches!(native, Native::FunctionApply | Native::ReflectApply) {
            sibling!(lane_apply_call::<H>, r, ip, Carried::script_in(cx, view))
        }
        if native == Native::ReflectGet {
            sibling!(reflect_get_call_handler::<H>(), r, ip, Carried::script_in(cx, view))
        }
        if native == Native::WasmExportedFunction
            && let Some(resumed) = lane_wasm_export_frame(cx, r, ip, i)
        {
            resume!(cx, resumed)
        }
        resume!(cx, lane_native_call_value(cx, r, ip, i, native))
    }
}

script_handler! {
    /// `lane_native_call` of `Function.prototype.apply` or `Reflect.apply`: the applied
    /// function's activation where its list allows one (`lane_apply_activation`), else the
    /// native's call. Apart, since the activation's result is a stack temporary of the
    /// handler that makes it, whose dispatch then is a call, not a sibling jump.
    #[inline(never)]
    fn lane_apply_call<>(cx, r, ip, i, view) {
        let Some(FunctionRecord { kind: FunctionKind::Native(native), .. }) =
            (unsafe { vm(cx) }).heap.function(r.get(i.b))
        else {
            unreachable!("lane_native_call routes only a native apply here");
        };
        let native = *native;
        if let Some(activation) = lane_apply_activation(cx, r, ip, i, native) {
            return match activation {
                Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                Err(next) => next,
            };
        }
        resume!(cx, lane_native_call_value(cx, r, ip, i, native))
    }
}

/// The native call `lane_native_call` makes in place (`lane_native_value`), completed in its
/// result register or as its caller's return (`lane_native_complete`).
#[inline(always)]
fn lane_native_call_value<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    native: Native,
) -> Resumed {
    // A call that returns its result completes its caller: an activation in the lane, or
    // the frame in the general loop (`lane_frame_return`).
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    // The running function is the same activation or, once the call made activations
    // frames (`lane_call_native`), the frame it became.
    if returns && !lane_returning_call_admitted(cx) {
        return Resumed::Exit(exit(ip));
    }
    // SAFETY: the call's window is registers of the running function, which the native
    // call copies before anything can move them.
    let args = unsafe { lane_call_window(r, i) };
    let value = lane_native_value(cx, ip, i, native, r.get(i.b), r.get(i.c), args);
    lane_native_complete(cx, ip, i, value)
}

script_handler! {
    /// A call of one spread (`CallSpread`), whose window holds the iterable: an intact array
    /// (`Vm::array_iteration_intact`) of present own data elements (`present_dense_elements`)
    /// passes them, which iterating it would yield and the activation copies, as a spread call's argument array
    /// (`lane_list_activation`); any other iterable takes the general path, which builds it.
    #[inline(never)]
    fn lane_call_spread<>(cx, r, ip, i, view) {
        let list = r.get(ImmediateLayout::call_window_base(i.imm()));
        let Some(length) = (unsafe { vm(cx) }).intact_spread_length(list) else {
            if let Some(resumed) = list_calls::lane_spread_set_native_call(cx, ip, i, r.get(i.b), r.get(i.c), list) {
                resume!(cx, resumed)
            }
            return exit(ip);
        };
        if let Some((registers, base)) = lane_spread_linked_call(cx, r, ip, i, list, length) {
            next!(cx, registers, base, Carried::script_in(cx, view))
        }
        if let Some(resumed) = lane_spread_native_call(cx, ip, i, r.get(i.b), r.get(i.c), list) {
            resume!(cx, resumed)
        }
        match lane_list_activation(cx, r, ip, i, r.get(i.b), r.get(i.c), list, Some(length)) {
            Some(Ok((registers, base))) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Some(Err(next)) => next,
            None => exit(ip),
        }
    }
}

script_handler! {
    /// A spread call (`CallArray`), whose window holds the argument array the spread built:
    /// the callee's activation with its elements, as an applied call's
    /// (`lane_list_activation`); any other call takes the general path.
    #[inline(never)]
    fn lane_call_array<>(cx, r, ip, i, view) {
        let list = r.get(ImmediateLayout::call_window_base(i.imm()));
        let Some(length) = (unsafe { vm(cx) }).dense_list_length(list) else {
            return exit(ip);
        };
        match lane_list_activation(cx, r, ip, i, r.get(i.b), r.get(i.c), list, Some(length)) {
            Some(Ok((registers, base))) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Some(Err(next)) => next,
            None => exit(ip),
        }
    }
}

/// Values an applied frame call copies out without allocating their list.
const FRAME_CALL_INLINE_ARGUMENTS: usize = 8;

/// `lane_call_spread` of a callee the site links: the elements of the intact `list`, `length`
/// of them, passed as `lane_passed_linked_call` passes values, read in place from a wide
/// backing, decoded from a narrow one. `None` for any other call, which the general spread
/// path makes.
#[inline(always)]
fn lane_spread_linked_call<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    list: Value,
    length: usize,
) -> Option<(Registers, Ip)> {
    let argc = u16::try_from(length).ok()?;
    let elements = unsafe { vm(cx) }.heap.array_elements(list)?;
    let mut decoded = [Value::UNDEFINED; FRAME_CALL_INLINE_ARGUMENTS];
    let (passed, valid) = match elements.wide_values() {
        Some(values) => (values.as_ptr(), argc),
        None => {
            let mut valid = 0;
            for (slot, value) in decoded.iter_mut().zip(elements.iter().take(length)) {
                *slot = value;
                valid += 1;
            }
            (decoded.as_ptr(), valid)
        }
    };
    lane_passed_linked_call(cx, r, ip, i, passed, argc, valid)
}

/// A spread call of a callee the site links (`Vm::linked_script_call_entry`, as a plain
/// call's), passed the `argc` values at `passed`, of which the first `valid` may be read: a
/// rest body that keeps nothing as `lane_activate_gathering` activates it, else a target
/// keeping nothing (`ScriptCallTarget::forwards`) activated as a plain call is
/// (`lane_push_passed`), taking the values as its parameters or dropping those past them.
/// `passed` stays valid until the activation is made: no collection runs inside it. `None`
/// for any other call.
#[inline(always)]
fn lane_passed_linked_call<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    passed: *const Value,
    argc: u16,
    valid: u16,
) -> Option<(Registers, Ip)> {
    let vm = unsafe { vm(cx) };
    let callee = r.get(i.b);
    if !unsafe { (*cx).script_calls } || lane_constructing(vm, callee) {
        return None;
    }
    // SAFETY: as `Vm::script_call_entry`; the entry is copied before anything else runs.
    let target = vm.linked_script_call_entry(callee, &i.call_link).map(|target| unsafe { *target })?;
    if target.entry == CallEntry::Gathers && target.forms & TARGET_GATHERS_KEEPING == 0 {
        if !lane_admits_activation(&target) || valid < argc {
            return None;
        }
        let this = lane_call_this(vm, &target, r.get(i.c))?;
        return lane_activate_gathering(cx, r, ip, &target, passed, argc, this).ok();
    }
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if !lane_admits_activation(&target)
        || target.forwards()
        || (argc > target.params && !target.drops_extra_arguments())
        || (returns && !lane_returning_call_admitted(cx))
        || vm.with_scope_entered
        || !lane_activation_room(vm, &target)
    {
        return None;
    }
    let this = lane_call_this(vm, &target, r.get(i.c))?;
    let argc = argc.min(target.params);
    if valid < argc {
        return None;
    }
    Some(lane_push_passed::<H, true, false>(cx, r, ip, &target, passed, argc, this, false))
}

script_handler! {
    /// `CallRest`: the spread of a rest parameter kept as a view. Its window holds the rest
    /// register; `undefined` there means the keeping activation's entry kept the values passed,
    /// which, while array iteration is intact, a linked callee takes in place
    /// (`lane_passed_linked_call`) with no array made. Otherwise the rest array they make is
    /// put in the window and the call is `lane_call_spread`'s, an array spread as any.
    #[inline(never)]
    fn lane_call_rest<>(cx, r, ip, i, view) {
        let window = ImmediateLayout::call_window_base(i.imm());
        if r.get(window) == Value::UNDEFINED
            && let Some((argc, function)) = unsafe { lane_keeping_activation(cx) }
        {
            let vm = unsafe { vm(cx) };
            let body = unsafe { &*(*cx).code }.function(function as usize);
            let fixed = body.params - 1;
            let count = argc.saturating_sub(fixed);
            // SAFETY: the keeping activation keeps its `argc` values after its registers.
            let kept = unsafe { r.0.add(usize::from(body.registers) + usize::from(fixed)).cast_const() };
            if vm.fresh_array_iteration_intact()
                && let Some((registers, base)) = lane_passed_linked_call(cx, r, ip, i, kept, count, count)
            {
                next!(cx, registers, base, Carried::script_in(cx, view))
            }
            let rest = vm.rest_parameter_array(unsafe { std::slice::from_raw_parts(kept, usize::from(count)) });
            r.set(window, rest);
        }
        sibling!(lane_call_spread::<H>, r, ip, view)
    }
}

/// The values a lane `Call` record passes: its window of the running function's registers.
///
/// # Safety
/// `r` is the registers of the activation `i` belongs to; the slice is valid until they move.
#[inline(always)]
unsafe fn lane_call_window<'a>(r: Registers, i: &LaneInstruction) -> &'a [Value] {
    unsafe { lane_window(r, ImmediateLayout::call_window_base(i.imm()), i) }
}

/// The `argument_count` values of the record `i` at register `window` of the running function.
///
/// # Safety
/// As `lane_call_window`.
#[inline(always)]
unsafe fn lane_window<'a>(r: Registers, window: u16, i: &LaneInstruction) -> &'a [Value] {
    unsafe { std::slice::from_raw_parts(r.0.add(usize::from(window)), usize::from(ImmediateLayout::argument_count(i.imm()))) }
}

/// The value of the lane `Call` record `i` of the native `callee`, of `kind`, with
/// `receiver` and `args`: the in-place cases every tier shares (`Vm::in_place_native_value`),
/// the lane's own, else `lane_string_or_native_call`. `None` leaves the call to the general path,
/// which raises an error the call stashed in `Vm::lane_raised`. Out of line: its calls take
/// stack temporaries, which a handler inlining them would hold on its common path.
#[inline(never)]
fn lane_native_value<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    i: &LaneInstruction,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // The Native argument carries the caller's function-kind proof. Each operation uses
    // its semantic fallback; the remaining natives try `lane_string_or_native_call`.
    match native {
        // The DataView Float64 lane, in every mode: one read of the view and one of its
        // buffer; a miss takes the native, which coerces and throws.
        Native::DataViewGetFloat64 | Native::DataViewSetFloat64 => {
            let value = vm.plain_data_view_access(native, receiver, args);
            if value.is_some() {
                if vm.execution_mode == super::ExecutionMode::Compiled {
                    vm.programs.note_js_jit_dataview_float64(native == Native::DataViewSetFloat64);
                }
                return value;
            }
        }
        Native::RegExpExec | Native::RegExpTest | Native::StringReplace | Native::StringMatch => {
            return lane_regexp_call(cx, ip, i, native, callee, receiver, args);
        }
        // A generator's resumption runs its body, and a Wasm export its function: guest code
        // that no in-place shortcut of `lane_string_or_native_call` makes.
        Native::GeneratorNext | Native::GeneratorReturn | Native::GeneratorThrow | Native::WasmExportedFunction => {
            return lane_call_native(cx, ip, native, callee, receiver, args);
        }
        // `with (object)` and its exit, in a frameless activation: its scope chain is the lane stack's.
        Native::WithEnter | Native::WithExit => {
            if let Some(value) = with_scopes::lane_with_scope(cx, native, args) {
                return Some(value);
            }
        }
        // Neither a string method nor a pure native: the promise shortcut, else the native.
        Native::PromiseThen | Native::PromiseCatch | Native::PromiseResolve => {
            return lane_promise_native_call(cx, ip, native, callee, receiver, args);
        }
        _ => {}
    }
    lane_string_or_native_call(cx, ip, native, callee, receiver, args)
}

/// The value of a promise native call: the lane's shortcut where it makes one, else the native.
fn lane_promise_native_call<H: Host>(cx: *mut LaneContext<H>, ip: Ip, native: Native, callee: Value, receiver: Value, args: &[Value]) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if let Some(value) = lane_promise_native(vm, code, native, callee, receiver, args) {
        note_allocation(vm);
        return Some(value);
    }
    lane_call_native(cx, ip, native, callee, receiver, args)
}

