impl<H: Host> Vm<H> {
    /// A native call's value where its common case completes in place, without guest code
    /// or a raised error: a dense `push` or `pop`, `charCodeAt`, an ASCII `charAt`, a
    /// collection lookup, `Array.isArray`, `JSON.stringify` of plain data (a new string).
    /// `None` leaves the call to the native itself, whose own steps begin with the same cases.
    #[inline(always)]
    fn steady_native_value(&mut self, native: Native, receiver: Value, args: &[Value]) -> Option<Value> {
        let first = args.first().copied();
        match native {
            // One value appended in the handler itself; other pushes take the dense path out
            // of line.
            Native::ArrayPush => match *args {
                [value] => self.array_push_one(receiver, value).or_else(|| self.array_push_dense(receiver, args)),
                _ => self.array_push_dense(receiver, args),
            },
            Native::ArrayPop => self.array_pop_dense(receiver),
            Native::StringCharCodeAt => string_char_code_at(self, receiver, first?),
            Native::StringCharAt => string_char_at_ascii(self, receiver, first?),
            Native::MapGet | Native::MapHas | Native::SetHas | Native::WeakMapGet | Native::WeakMapHas
            | Native::WeakSetHas => self.pure_collection_lookup(native, receiver, first.unwrap_or(Value::UNDEFINED)),
            Native::MapSet if self.map_set(receiver, args) => Some(receiver),
            Native::ArrayIsArray => self.steady_is_array(first.unwrap_or(Value::UNDEFINED)).map(Value::boolean),
            Native::JsonStringify => self.json_stringify_plain_call(args),
            Native::DateNow => Some(self.date_now()),
            _ => None,
        }
    }

}

/// Whether liveness proves the result register of the running function's call record `i`
/// at `ip` dead once the call completes (`liveness::register_dead` before the next PC), so
/// its value is never read: what the call writes there is unobservable.
#[cold]
fn lane_call_result_dead<H: Host>(cx: *mut LaneContext<H>, ip: Ip, i: &LaneInstruction) -> bool {
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    // A leaf makes no call, so the innermost activation, or else the frame, runs `i`.
    let function = lane_running_function(cx);
    // SAFETY: `ip` is a record of the running view, which starts at the context's base.
    let pc = unsafe { ip.offset_from((*cx).base) } as usize;
    code.register_root_masks(function)
        .and_then(|masks| masks.get(pc + 1))
        .is_some_and(|after| crate::compile::liveness::register_dead(after, usize::from(i.a & crate::bytecode::REGISTER_MASK)))
}

script_handler! {
    /// A `Call` site whose callee was an array's callback method (`native_call_handler`,
    /// `Native::is_array_callback`), which no in-place shortcut of `lane_native_value` makes:
    /// the native's call out of the lane (`lane_call_native_out`), whose callback calls run in
    /// this lane (`Vm::lane_native_callback`). Any other callee takes `lane_native_call`.
    /// Where `DISCARDS`, nothing reads the call's result, so a `forEach` of one element is its
    /// callback's plain call (`lane_call_for_each_once`).
    #[inline(never)]
    fn lane_call_array_callback<DISCARDS: bool>(cx, r, ip, i, view) {
        let callee = r.get(i.b);
        let native = match (unsafe { vm(cx) }).heap.function(callee) {
            Some(FunctionRecord { kind: FunctionKind::Native(native), .. }) if native.is_array_callback() => *native,
            _ => sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view)),
        };
        // SAFETY: the call's window is registers of the running function, which the native
        // call copies before anything can move them.
        let args = unsafe { lane_call_window(r, i) };
        // One element, tested inline: a longer array takes the iteration at no further cost.
        if DISCARDS
            && native == Native::ArrayForEach
            && lane_array_object(unsafe { vm(cx) }, r.get(i.c)).is_some_and(|object| object.elements().len() == 1)
            && let Some((registers, start)) = lane_call_for_each_once(cx, ip, r.get(i.c), args)
        {
            next!(cx, registers, start, Carried::script_in(cx, view))
        }
        if let Some(resumed) = lane_begin_array_iteration(cx, ip, native, r.get(i.c), args) {
            resume!(cx, resumed)
        }
        let value = lane_call_native_out(cx, ip, native, callee, r.get(i.c), args);
        resume!(cx, lane_native_complete(cx, ip, i, value))
    }
}

/// Whether `callee` is a function whose behavior is the native `native`'s.
#[inline(always)]
fn callee_is_native<H: Host>(vm: &Vm<H>, callee: Value, native: Native) -> bool {
    matches!(vm.heap.function(callee), Some(FunctionRecord { kind: FunctionKind::Native(found), .. }) if *found == native)
}

script_handler! {
    /// A `Call` site whose callee was a Math function of Numbers (`native_call_handler`): the
    /// call of Number arguments in place (`number::math_inline_call`). Any other callee or
    /// argument takes `lane_native_call`.
    fn lane_call_math<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let value = match vm.heap.function(r.get(i.b)) {
            // SAFETY: the call's window is registers of the running function.
            Some(FunctionRecord { kind: FunctionKind::Native(native), .. }) => {
                super::number::math_inline_call(*native, unsafe { lane_call_window(r, i) })
            }
            _ => None,
        };
        let Some(value) = value else {
            sibling!(lane_native_call::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The lane `Call` record `i` completed with `value`: in its result register, or returned
/// from the caller for a call that returns its result; the general path for `None`.
#[inline(always)]
fn lane_native_complete<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    i: &LaneInstruction,
    value: Option<Value>,
) -> Resumed {
    let Some(value) = value else {
        return Resumed::Exit(exit(ip));
    };
    // The call may have made the lane's activations frames, so the running function's
    // registers and caller are read again.
    if i.a & crate::bytecode::RETURN_REGISTER != 0 {
        let Some(resumed) = lane_complete_activation(cx, ip, value) else {
            // A frame of a script run retires in place, as its `Return` would.
            if unsafe { !(*cx).inline_calls && (*cx).script_calls } {
                return Resumed::Exit(lane_return_script_frame(cx, ip, value, true));
            }
            return Resumed::Exit(lane_frame_return(unsafe { vm(cx) }, ip, value));
        };
        return resumed;
    }
    let r = unsafe { (*cx).registers };
    r.set(i.a, value);
    Resumed::At(r, following(ip), Carried::script(cx))
}

/// `RegExp.prototype.exec` or `test`, or `String.prototype.replace` or `match` of a RegExp, made in
/// place when it runs no guest code and raises nothing, so it observes no frame
/// (`Vm::steady_regexp_call`, `Vm::steady_string_replace`); any other such call goes on as
/// `lane_string_or_native_call` makes it.
#[inline(never)]
fn lane_regexp_call<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    i: &LaneInstruction,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let result_used = ImmediateLayout::lane_call_result_used(i.imm());
    let steady = match (native, args) {
        (Native::StringReplace, _) => vm.steady_string_replace(code, native, receiver, args, result_used),
        (Native::StringMatch, [search, ..]) => vm.steady_string_match(code, receiver, *search, result_used),
        (_, [subject, ..]) => vm.steady_regexp_call(code, native, receiver, *subject, result_used),
        _ => None,
    };
    let Some(result) = steady else {
        return lane_string_or_native_call(cx, ip, native, callee, receiver, args);
    };
    let result = vm.regexp_search_outcome(result);
    // The call's allocations may make a collection due, which the lane's safepoints take.
    note_allocation(vm);
    match result {
        Ok(value) => Some(value),
        Err(error) => {
            vm.lane_completion.raise(error);
            None
        }
    }
}

/// A lane native call that `lane_native_call` does not make inline: a pure string method or
/// a pure native in place, else the native through `lane_call_native`. Inline into its two callers: a native
/// call otherwise pays this layer's own frame.
#[inline(always)]
fn lane_string_or_native_call<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if let Some(value) = vm.in_place_native_value_inline(code, native, callee, receiver, args) {
        // An in-place case may allocate; a due collection runs at the lane's next safepoint.
        note_allocation(vm);
        return Some(value);
    }
    lane_call_native(cx, ip, native, callee, receiver, args)
}

/// A lane call of a promise native whose steps provably observe nothing, answered in place
/// so the lane's activations need not become frames (`lane_call_native`): `then` and
/// `catch` of a receiver with intrinsic species (`Vm::lane_promise_then`) and the intrinsic
/// `Promise.resolve` (`Vm::lane_promise_resolve`). A resolving function (one with an
/// environment), any other shape, or a lifecycle-observing host takes the general call.
#[inline(never)]
fn lane_promise_native<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    if !matches!(native, Native::PromiseThen | Native::PromiseCatch | Native::PromiseResolve)
        || !vm.heap.function(callee).is_some_and(|function| function.env.is_null())
    {
        return None;
    }
    match native {
        Native::PromiseThen => vm.lane_promise_then(
            code,
            receiver,
            args.first().copied().unwrap_or(Value::UNDEFINED),
            args.get(1).copied().unwrap_or(Value::UNDEFINED),
        ),
        Native::PromiseCatch => {
            // `catch` reads `then` of its receiver and calls it: only the intrinsic `then`,
            // read as plain data, is the shortcut's to make.
            let then_atom = vm.runtime_atoms.then;
            let then = vm.plain_named_load(receiver, then_atom)?;
            if !matches!(
                vm.heap.function(then),
                Some(FunctionRecord { kind: FunctionKind::Native(Native::PromiseThen), .. })
            ) {
                return None;
            }
            vm.lane_promise_then(
                code,
                receiver,
                Value::UNDEFINED,
                args.first().copied().unwrap_or(Value::UNDEFINED),
            )
        }
        Native::PromiseResolve => vm.lane_promise_resolve(
            code,
            receiver,
            args.first().copied().unwrap_or(Value::UNDEFINED),
        ),
        _ => unreachable!("only promise shortcut natives reach here"),
    }
}


/// A lane `Call` of a native that `Native::runs_from_lane` admits, made as the general path
/// makes it from the running frame: with the frame's resume PC published and the arguments
/// copied out of its registers, which stay rooted by the frame. Only a frame's own lane run
/// calls out, so the frame stack the native and its nested calls observe is the general
/// path's. `None` exits to the general path, which raises the error the call stashed in
/// `Vm::lane_raised` or makes a call this does not admit.
#[inline(never)]
fn lane_call_native<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    if !native.runs_from_lane() {
        return None;
    }
    lane_call_native_out(cx, ip, native, callee, receiver, args)
}

/// `lane_call_native` past its admission: the native's call out of the lane,
/// beside its activations where the native admits it, else from its frame
/// (`lane_call_from_frame`), as `lane_call_array_callback` calls an array's callback method,
/// which no shortcut answers.
#[inline(always)]
fn lane_call_native_out<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    native: Native,
    callee: Value,
    receiver: Value,
    args: &[Value],
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    if !unsafe { (*cx).script_calls } {
        return None;
    }
    // The values are copied before activations become frames, which moves the registers
    // they may lie in; the frames then root what the call passes.
    let arguments = super::call_arguments::CallArguments::from_slice(args);
    // SAFETY: `ip` is a record of the active view, which is the running function's.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    // A native that observes frames only through the points `materialize_deferred_lane`
    // guards runs beside the activations; the first such point makes them frames.
    if !vm.lane_stack.activations.is_empty()
        && (vm.runs_beside_activations(native, callee) || vm.steps_beside_activations(native, receiver))
    {
        vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
        let result = vm.call_native_guarded(unsafe { &*(*cx).code }, native, receiver, arguments.as_slice(), callee);
        note_allocation(vm);
        vm.lane_stack.refresh_activation_limit();
        let unobserved = vm.lane_deferred.take().is_some();
        return match result {
            Ok(value) => Some(value),
            Err(error) => {
                // The general path raises it from the frames its activations become.
                if unobserved {
                    vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
                    vm.materialize_deferred_lane();
                }
                vm.lane_completion.raise(error);
                None
            }
        };
    }
    #[cfg(feature = "profile-lane-exits")]
    if !vm.lane_stack.activations.is_empty() {
        super::lane_exits::record_detail(match native {
            Native::HostFunction => format!("materializes for host {}", vm.host_function_name(callee).unwrap_or_default()),
            native => format!("materializes for native {native:?}"),
        });
    }
    lane_call_from_frame(cx, ip, |vm, code| {
        vm.call_native_guarded(code, native, receiver, arguments.as_slice(), callee)
    })
}

/// A native call at the lane `Call` record `ip` made from the running frame: the callee
/// observes the frame stack, so lane activations become frames first, as leaving the lane
/// would make them, and `call` runs from the innermost one. `None` leaves the error it raised
/// in `Vm::lane_raised`.
#[inline(always)]
fn lane_call_from_frame<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    call: impl FnOnce(&mut Vm<H>, &ResidualProgram) -> Result<Value, JsError>,
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the active view, which is the running function's.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    vm.materialize_lane_activations(cx);
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // active view, which is the running frame's.
    let (code, frame) = unsafe { (&*(*cx).code, (*cx).frame()) };
    vm.frames[frame].pc = call_pc + 1;
    vm.frames[frame].pc_is_resume = true;
    // The native branch of `Vm::call_value_with_target_inner`, whose callee this is; its
    // calls of JavaScript run in this lane while it runs from this frame.
    let site = LaneNativeCall { cx: cx.cast(), call: ip, frames: vm.frames.len() };
    let outer = vm.lane_native.replace(site);
    let result = call(vm, code);
    vm.lane_native = outer;
    // The native's allocations may make a collection due, which the lane's safepoints take.
    note_allocation(vm);
    // A host edge can change the thread's guest-call allowance. Rebind the
    // capacity certificate here, before any lane/native entry consumes it.
    vm.lane_stack.refresh_activation_limit();
    match result {
        Ok(value) => Some(value),
        Err(error) => {
            vm.lane_completion.raise(error);
            None
        }
    }
}

/// A lane `new` of a native that `Native::constructs_from_lane` admits, made as the general
/// path makes it (`Vm::construct_value_with_new_target`) from the running frame, after
/// activations become frames, as `lane_call_native` makes a call. `None` exits to the general
/// path, which raises the error the construction stashed in `Vm::lane_raised` or makes one
/// this does not admit.
#[inline(never)]
fn lane_construct_native<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    callee: Value,
    new_target: Value,
    args: &[Value],
) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    if !unsafe { (*cx).script_calls } || vm.construct_target.is_some() {
        return None;
    }
    // The values are copied before activations become frames, which moves the registers
    // they may lie in; the frames then root what the construction passes.
    let arguments = super::call_arguments::CallArguments::from_slice(args);
    // SAFETY: the context's program outlives the lane run, and `ip` is a record of the
    // running function's view.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    // A native's construction runs beside the activations, as a native call beside them
    // runs (`lane_call_native`): the first point that observes frames makes them frames.
    let beside = !vm.lane_stack.activations.is_empty() && vm.constructs_beside_activations(callee);
    if beside {
        vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
    } else {
        vm.materialize_lane_activations(cx);
        let frame = unsafe { (*cx).frame() };
        vm.frames[frame].pc = call_pc + 1;
        vm.frames[frame].pc_is_resume = true;
    }
    // SAFETY: as above; the construction runs from the running function's program.
    let code = unsafe { &*(*cx).code };
    let result = vm.construct_value_with_new_target(code, callee, new_target, arguments.as_slice());
    // The construction's allocations may make a collection due, which the lane's safepoints
    // take.
    note_allocation(vm);
    let unobserved = beside && vm.lane_deferred.take().is_some();
    match result {
        Ok(value) => Some(value),
        Err(error) => {
            // The general path raises it from the frames the activations become.
            if unobserved {
                vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
                vm.materialize_deferred_lane();
            }
            vm.lane_completion.raise(error);
            None
        }
    }
}

/// The native parent a `new` of `callee` constructs in its place: `callee`'s own parent
/// (`[[GetPrototypeOf]]`) when its constructor only constructs it
/// (`Function::super_forwarding`) and that parent is a native the lane constructs other
/// than an error constructor, with what the constructor passes on.
#[inline(never)]
fn lane_super_forwarded_parent<H: Host>(vm: &Vm<H>, callee: Value) -> Option<(Value, crate::bytecode::SuperForwarded)> {
    let Some(FunctionRecord { kind: FunctionKind::User(program, function), .. }) = vm.heap.function(callee) else {
        return None;
    };
    let code = vm.programs.residual(*program)?;
    let body = code.function_get(*function as usize)?;
    if !body.derived_constructor {
        return None;
    }
    // The parent first: a class whose parent is no native the lane constructs, as every
    // user class hierarchy's, declines here without decoding its constructor's body
    // (`Function::super_forwarding`, ~900 Ir), which every `new` of it would otherwise pay.
    let parent = vm.object_data(callee)?.proto();
    match vm.heap.function(parent) {
        // An error's stack starts past its constructors' frames, which this construction
        // would not make.
        Some(FunctionRecord { kind: FunctionKind::Native(native), .. })
            if (native.constructs_from_lane() && !native.is_error_constructor()) || *native == Native::Array =>
        {
            Some((parent, body.super_forwarding(&code.atoms, &code.constants)?))
        }
        _ => None,
    }
}

/// `new callee(...)` of a class whose constructor only constructs its native `parent`
/// (`lane_super_forwarded_parent`): the parent's construction with what the constructor
/// passes on (every value, or its parameters with missing ones `undefined`) and `callee`
/// as `new.target`, as the body's `super(...)` makes it; its receiver is the construction's
/// value.
#[inline(never)]
fn lane_construct_forwarded_parent<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    callee: Value,
    (parent, forwarded): (Value, crate::bytecode::SuperForwarded),
) -> Resumed {
    let argc = usize::from(ImmediateLayout::argument_count(i.imm()));
    let count = match forwarded {
        crate::bytecode::SuperForwarded::Passed => argc,
        crate::bytecode::SuperForwarded::Parameters(count) => usize::from(count),
    };
    let passed = (0..count)
        .map(|index| if index < argc { r.get(i.c + index as u16) } else { Value::UNDEFINED })
        .collect::<smallvec::SmallVec<[Value; GATHERED_INLINE_VALUES]>>();
    let vm = unsafe { vm(cx) };
    // An array subclass's `super(...)`: the intrinsic's array with the class's `prototype`,
    // made in place and named as the general path names it (`capture_constructed_value`).
    if vm.construct_target.is_none()
        && matches!(vm.heap.function(parent), Some(FunctionRecord { kind: FunctionKind::Native(Native::Array), .. }))
        && let Some(array) = vm.array_construction_by(callee, &passed)
    {
        vm.capture_constructed_value(array, parent, false);
        note_allocation(vm);
        return lane_native_complete(cx, ip, i, Some(array));
    }
    let value = lane_construct_native(cx, ip, parent, callee, &passed);
    lane_native_complete(cx, ip, i, value)
}

script_handler! {
    /// `new` of a frameless target that `Vm::inline_construct_target` would push: the
    /// receiver it allocates, then the activation `lane_script_call` makes, whose
    /// completion substitutes the receiver for a non-object result. Any other
    /// construction takes the general path.
    fn lane_script_construct<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let callee = r.get(i.b);
        // Under a `with` scope or a pending construction no cached target admits the
        // construction (`LaneStack::set_refused`), so the resolve-and-retry below would
        // never find one: it leaves the lane, as a refused call does.
        if !unsafe { (*cx).script_calls && (*cx).script_constructs } || vm.lane_stack.refuses() {
            return exit(ip);
        }
        // The cached target in place, as a call reads it (`Vm::script_call_entry`); an
        // uncached callee resolves (`lane_script_target`), after which the construction
        // retries.
        let entry = if lane_constructing(vm, callee) {
            None
        } else {
            vm.script_call_entry(callee).or_else(|| vm.cross_call_entry(callee))
        };
        let Some(entry) = entry else {
            if lane_script_target(cx, callee).is_some_and(|target| target.constructs()) {
                sibling!(lane_script_construct::<H>, r, ip, Carried::script_in(cx, view))
            }
            sibling!(lane_native_construct::<H>, r, ip, Carried::script_in(cx, view))
        };
        // SAFETY: as `Vm::script_call_entry`; the planned construction below resolves no
        // target, and any other path copies the target first.
        let target = unsafe { &*entry };
        // A class constructor's target constructs with entry `Frame`, which its calls take.
        if !target.constructs() {
            sibling!(lane_native_construct::<H>, r, ip, Carried::script_in(cx, view))
        }
        // A planned construction, the common `new C(…)` or `return new C(…)`: the receiver
        // is the finished object, and the body completed with `undefined`.
        if target.initializes()
            && lane_finishes_construction(cx, i)
            && let Some(this) = lane_planned_construction(vm, callee, r, i)
        {
            // Allocating the receiver can make a collection due.
            note_allocation(vm);
            // Later runs of the site try the plan first. The site notes its callee, which a body
            // reads to keep the receiver as its field values (`scalar_construct_plan`).
            vm.note_site_callee(unsafe { &(*ip).call_link }, super::compiled::CallTarget {
                callee: super::compiled::CalleeBinding::Identity(callee), function: target.function });
            if i.a & crate::bytecode::RETURN_REGISTER == 0 {
                requicken::<H>(ip, lane_planned_construct::<H>);
                r.set(i.a, this);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            requicken::<H>(ip, lane_planned_construct_returned::<H>);
            if let Some(resumed) = lane_complete_activation(cx, ip, this) {
                resume!(cx, resumed)
            }
            return lane_frame_return(vm, ip, this);
        }
        let target = *target;
        if target.forwards() {
            // The site constructs a forwarding target: later runs enter the keeping
            // construction directly, which moves the record back for any other target.
            requicken::<H>(ip, lane_script_construct_keeping::<H>);
            sibling!(lane_script_construct_keeping::<H>, r, ip, Carried::script_in(cx, view))
        }
        let built = if target.initializes() {
            match lane_planned_construction(vm, callee, r, i) {
                Some(this) => Some((this, true)),
                // SAFETY: the context's program outlives the lane run.
                None => lane_initialize_fields(vm, unsafe { &*(*cx).code }, callee, callee, target.function, lane_construct_argument(r, i)),
            }
        } else {
            vm.inline_construct_receiver(callee).map(|this| (this, false))
        };
        let Some((this, initialized)) = built else {
            return exit(ip);
        };
        // Allocating the receiver can make a collection due.
        note_allocation(vm);
        if initialized {
            // The body completed with `undefined`, so [[Construct]] yields the receiver.
            if i.a & crate::bytecode::RETURN_REGISTER == 0 {
                r.set(i.a, this);
                next!(cx, r, following(ip), Carried::script_in(cx, view))
            }
            if let Some(resumed) = lane_complete_activation(cx, ip, this) {
                resume!(cx, resumed)
            }
            // The frame's own construct: the general loop returns the receiver from it, unless
            // proper tail calls send it to the activation below, which leaves for that loop.
            if lane_returning_call_admitted(cx) {
                return lane_frame_return(vm, ip, this);
            }
        }
        let activated = if target.entry == CallEntry::Environment {
            // SAFETY: the construction's arguments are a window of the running function's registers.
            lane_activate_environment(cx, r, ip, &target, unsafe { lane_window(r, i.c, i) }, (this, true))
        } else {
            lane_activate(cx, r, ip, &target, i.c, this, true)
        };
        match activated {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

script_handler! {
    /// `lane_script_construct` at a site into a register whose construction was planned
    /// (`lane_planned_construction`), which `lane_script_construct` moves it to: the plan of
    /// the callee alone, without resolving its call target. A plan exists only for a callee
    /// whose target constructs by its initializer stores, which its function fixes, and while
    /// it holds the finished object is what the activation would make. Any other construction
    /// moves the record back to `lane_script_construct`.
    fn lane_planned_construct<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !unsafe { (*cx).script_calls && (*cx).script_constructs } || vm.construct_target.is_some() {
            return exit(ip);
        }
        let Some(this) = lane_planned_inline_quick(vm, r.get(i.b), r, i) else {
            sibling!(lane_planned_construct_full::<H>, r, ip, Carried::script_in(cx, view))
        };
        r.set(i.a, this);
        // Allocating the receiver can make a collection due.
        if vm.heap.should_collect() {
            sibling!(lane_construct_allocation_due::<H>, r, ip, Carried::script_in(cx, view))
        }
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_planned_construct` past its quick case (`lane_planned_inline_quick`): any plan, and
    /// the slow allocations, out of line so the quick case calls nothing.
    #[inline(never)]
    fn lane_planned_construct_full<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let Some(this) = lane_planned_construction(vm, r.get(i.b), r, i) else {
            requicken::<H>(ip, lane_script_construct::<H>);
            sibling!(lane_script_construct::<H>, r, ip, Carried::script_in(cx, view))
        };
        // Allocating the receiver can make a collection due.
        note_allocation(vm);
        r.set(i.a, this);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A construction whose receiver is already in its register and whose allocation made a
    /// collection due: notes it (`note_allocation`) and goes on, out of line.
    #[inline(never)]
    fn lane_construct_allocation_due<>(cx, r, ip, i, view) {
        note_allocation(unsafe { vm(cx) });
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `lane_planned_construct` at a site whose construction is returned (`RETURN_REGISTER`),
    /// which `lane_script_construct` moves it to: the planned receiver completes the
    /// activation that returns it, or the frame's own returning construct where
    /// `lane_finishes_construction` admits it. Any other construction moves the record back
    /// to `lane_script_construct`.
    fn lane_planned_construct_returned<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        if !unsafe { (*cx).script_calls && (*cx).script_constructs } || vm.construct_target.is_some() {
            return exit(ip);
        }
        let planned = lane_finishes_construction(cx, i)
            .then(|| lane_planned_construction(vm, r.get(i.b), r, i))
            .flatten();
        let Some(this) = planned else {
            requicken::<H>(ip, lane_script_construct::<H>);
            sibling!(lane_script_construct::<H>, r, ip, Carried::script_in(cx, view))
        };
        // Allocating the receiver can make a collection due.
        note_allocation(vm);
        resume!(cx, lane_return_constructed(cx, ip, this))
    }
}

script_handler! {
    /// `lane_script_call` of a target that keeps its passed values
    /// (`ScriptCallTarget::forwards`): the keeping activation (`lane_call_keeping_activation`).
    /// Out of line, so ordinary calls keep their code.
    #[inline(never)]
    fn lane_script_call_keeping<>(cx, r, ip, i, view) {
        match lane_call_keeping_activation(cx, r, ip, i) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(Some(next)) => next,
            // A site this form serves since `lane_script_call` saw a keeping target calls
            // the full form once its callee keeps nothing.
            Err(None) => {
                requicken::<H>(ip, lane_script_call_full::<H>);
                sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
            }
        }
    }
}

/// `lane_script_call_keeping`'s activation: the callee's registers and first record, the
/// record to continue at, or `None` for a callee whose target keeps nothing, which the full
/// form calls. Inline in its one handler, which is itself out of line.
#[inline(always)]
fn lane_call_keeping_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
) -> Result<(Registers, Ip), Option<Ip>> {
    if !unsafe { (*cx).script_calls } {
        return Err(Some(exit(ip)));
    }
    let vm = unsafe { vm(cx) };
    let callee = r.get(i.b);
    // The site's linked entry, as `lane_script_call_environment` reads it, copied before the
    // activation allocates; any other callee takes the general lookup.
    let linked = if lane_constructing(vm, callee) {
        None
    } else {
        // SAFETY: as `Vm::script_call_entry`; the entry is copied before anything else runs.
        vm.linked_script_call_entry(callee, &i.call_link)
            .map(|target| unsafe { *target })
            .filter(lane_admits_activation)
    };
    let Some(target) = linked.or_else(|| lane_script_target(cx, callee)) else {
        return Err(None);
    };
    if !target.forwards() {
        return Err(None);
    }
    #[cfg(feature = "profile-lane-exits")]
    profile_script_call_target(cx, ip, callee, &target);
    let receiver = r.get(i.c);
    let Some(this) = lane_call_this(vm, &target, receiver) else {
        return Err(Some(exit(ip)));
    };
    let window = ImmediateLayout::call_window_base(i.imm());
    if target.entry == CallEntry::Gathers && target.forms & TARGET_GATHERS_KEEPING == 0 {
        // SAFETY: the call's window of `r` holds its `argc` values.
        let passed = unsafe { r.0.add(usize::from(window)).cast_const() };
        return lane_activate_gathering(cx, r, ip, &target, passed, ImmediateLayout::argument_count(i.imm()), this).map_err(Some);
    }
    if target.entry == CallEntry::Keeps {
        return lane_activate_keeping_window::<H, false>(cx, r, ip, &target, window, this).map_err(Some);
    }
    let arguments = ActivationArguments::Window(window);
    lane_activate_keeping::<H, false>(cx, r, ip, &target, arguments, this, false, None).map_err(Some)
}

/// The keeping activation of a target of the running program that keeps the values it was
/// passed (`CallEntry::Keeps`), called with its window at `arguments` of `r`, made as a plain
/// call's push is (`lane_fill_window`, `lane_enter_window`) with the values kept after its
/// registers, as `lane_activate_keeping` keeps them, and the activation marked keeping.
#[inline(always)]
fn lane_activate_keeping_window<H: Host, const GENERAL: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    arguments: u16,
    this: Value,
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the running view.
    let i = unsafe { &*ip };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if (returns && !lane_returning_call_admitted(cx)) || vm.with_scope_entered {
        return Err(exit(ip));
    }
    let argc = ImmediateLayout::argument_count(i.imm());
    let count = usize::from(target.registers);
    let window_size = count + usize::from(argc);
    let room = fill_room::<ACTIVATION_FILL_BLOCK>(window_size).max(usize::from(target.room));
    if vm.lane_stack.activations.len() >= vm.lane_stack.activation_limit.get() || vm.lane_stack.values.room() < room {
        return Err(lane_script_call_frame::<H>(ip, room));
    }
    // SAFETY: the call's window of `r` holds its `argc` values; capacity holds the window
    // and the kept values after it, each written before the length covers it.
    let callee_registers = unsafe {
        let passed = r.0.add(usize::from(arguments)).cast_const();
        let registers = lane_fill_window(vm, target, passed, argc.min(target.params));
        copy_arguments(registers.0.add(count), passed, argc);
        vm.lane_stack.values.set_top(registers.0.add(window_size + lane_values::CONTEXT));
        registers
    };
    Ok(lane_enter_window::<H, GENERAL, false>(cx, r, ip, target, callee_registers, argc, this, false, None, Some(target.registers)))
}

/// The plain activation (`lane_push_passed`) of a rest body of the running program that keeps
/// nothing (`TARGET_GATHERS_KEEPING` clear), passed the `argc` values at `passed` (its window
/// of `r`, or the elements of the array a spread call passes): the fixed parameters copied as
/// any call's are, and the rest parameter's register the array of the values past them, read
/// in place, or `undefined` for a rest view that keeps the values after its registers.
#[inline(always)]
fn lane_activate_gathering<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: *const Value,
    argc: u16,
    this: Value,
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the running view.
    let i = unsafe { &*ip };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if (returns && !lane_returning_call_admitted(cx)) || vm.with_scope_entered {
        return Err(exit(ip));
    }
    let view = target.forms & TARGET_REST_VIEW != 0;
    let room = usize::from(target.room) + if view { usize::from(argc) } else { 0 };
    if !lane_activation_room(vm, target) || vm.lane_stack.values.room() < room {
        return Err(lane_script_call_frame::<H>(ip, room));
    }
    let fixed = target.params - 1;
    if view {
        // A rest view keeps every value passed after its registers, as a keeping activation
        // does, and its rest register holds `undefined` (`LaneFrame::rest_view`).
        let callee_registers = lane_fill_window(vm, target, passed, argc.min(fixed));
        callee_registers.set(fixed, Value::UNDEFINED);
        let count = usize::from(target.registers);
        // SAFETY: the room checked above holds the kept values past the window.
        unsafe {
            copy_arguments(callee_registers.0.add(count), passed, argc);
            vm.lane_stack.values.set_top(callee_registers.0.add(count + usize::from(argc) + lane_values::CONTEXT));
        }
        return Ok(lane_enter_window::<H, false, false>(cx, r, ip, target, callee_registers, argc, this, false, None, Some(target.registers)));
    }
    let rest = vm.rest_parameter_array(unsafe {
        std::slice::from_raw_parts(passed.add(usize::from(fixed.min(argc))), usize::from(argc.saturating_sub(fixed)))
    });
    let callee_registers = lane_fill_window(vm, target, passed, argc.min(fixed));
    callee_registers.set(fixed, rest);
    Ok(lane_enter_window::<H, false, false>(cx, r, ip, target, callee_registers, argc.min(target.params), this, false, None, None))
}

script_handler! {
    /// `lane_script_construct` of a target that keeps its passed values
    /// (`ScriptCallTarget::forwards`), which `lane_script_construct` moves a site to: the
    /// keeping activation (`lane_construct_keeping_activation`). Any other construction moves
    /// the record back to `lane_script_construct`. Out of line, so ordinary constructions
    /// keep their code.
    #[inline(never)]
    fn lane_script_construct_keeping<>(cx, r, ip, i, view) {
        let finished = match lane_construct_planned_fields(cx, r, i) {
            Some(this) => Ok(KeepingConstruction::Finished(this)),
            None => lane_construct_keeping_activation(cx, r, ip, i),
        };
        match finished {
            Ok(KeepingConstruction::Activated(registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Ok(KeepingConstruction::Finished(this)) => {
                if i.a & crate::bytecode::RETURN_REGISTER == 0 {
                    r.set(i.a, this);
                    next!(cx, r, following(ip), Carried::script_in(cx, view))
                }
                if let Some(resumed) = lane_complete_activation(cx, ip, this) {
                    resume!(cx, resumed)
                }
                // The frame's own construct, which `lane_finishes_construction` admitted: the
                // general loop returns the receiver from it.
                lane_frame_return(unsafe { vm(cx) }, ip, this)
            }
            Err(Some(next)) => next,
            Err(None) => {
                requicken::<H>(ip, lane_script_construct::<H>);
                sibling!(lane_script_construct::<H>, r, ip, Carried::script_in(cx, view))
            }
        }
    }
}

/// What `lane_construct_keeping_activation` made of a construction.
enum KeepingConstruction {
    /// The callee's registers and first record.
    Activated(Registers, Ip),
    /// The construction's result, whose body ran without an activation: its site completes
    /// with it.
    Finished(Value),
}

/// Whether a construction at `i` may complete in the lane with a receiver its body finished
/// without an activation: into a register, into the activation that returns it, or from the
/// frame's own returning construct where `lane_returning_call_admitted` admits it, as
/// `lane_script_construct` completes one.
#[inline(always)]
fn lane_finishes_construction<H: Host>(cx: *mut LaneContext<H>, i: &LaneInstruction) -> bool {
    i.a & crate::bytecode::RETURN_REGISTER == 0
        || !unsafe { vm(cx) }.lane_stack.activations.is_empty()
        || lane_returning_call_admitted(cx)
}

/// The receiver a forwarding constructor's holding plan finishes with its recorded fields
/// (`lane_forwarded_fields`), the first case `lane_construct_keeping_activation` tries, in a
/// function of its own: inlined there it ran inside that function's frame (six saved
/// registers and 1.3 KB of stack for the activation paths). `None` for any other case, which
/// that function then decides from the start.
#[inline(never)]
fn lane_construct_planned_fields<H: Host>(cx: *mut LaneContext<H>, r: Registers, i: &LaneInstruction) -> Option<Value> {
    let vm = unsafe { vm(cx) };
    if !unsafe { (*cx).script_calls && (*cx).script_constructs } || vm.construct_target.is_some()
        || !lane_finishes_construction(cx, i)
    {
        return None;
    }
    let this = lane_forwarded_fields(vm, r.get(i.b), lane_construct_argument(r, i))?;
    // Allocating the receiver can make a collection due.
    note_allocation(vm);
    Some(this)
}

/// `lane_script_construct_keeping`'s activation, under `lane_script_construct`'s admission:
/// the callee's registers and first record, or the receiver its body finished; the record
/// to continue at, or `None` for a construction of any target but a forwarding one. Out of
/// line: the call target it passes on lives in its own frame, not the handler's.
#[inline(never)]
fn lane_construct_keeping_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
) -> Result<KeepingConstruction, Option<Ip>> {
    let vm = unsafe { vm(cx) };
    let callee = r.get(i.b);
    if !unsafe { (*cx).script_calls && (*cx).script_constructs } || vm.construct_target.is_some() {
        return Err(Some(exit(ip)));
    }
    let finishes = lane_finishes_construction(cx, i);
    // A plan holding for `callee` fixes its function, so the plan alone answers before its
    // target is resolved.
    if finishes && let Some(this) = lane_forwarded_fields(vm, callee, lane_construct_argument(r, i)) {
        // Allocating the receiver can make a collection due.
        note_allocation(vm);
        return Ok(KeepingConstruction::Finished(this));
    }
    // Matched rather than filtered: the combinators moved the target through copies.
    let Some(target) = lane_script_target(cx, callee) else {
        return Err(None);
    };
    if !(target.constructs() && target.forwards()) {
        return Err(None);
    }
    // One look at the plan serves the receiver and the forwarding: a plan the receiver's
    // allocation leaves records no resolution yet.
    let plan = holding_construct_plan(vm, callee);
    let Some(this) = lane_planned_receiver(vm, callee, plan.as_ref()) else {
        return Err(Some(exit(ip)));
    };
    note_allocation(vm);
    let arguments = ActivationArguments::Window(i.c);
    if let Some(&method) = vm.lane_stack.forwarded_methods.get(target.forwarded_method as usize)
        && let Some(forwarded) = match lane_resolved_forwarding(cx, callee, plan.as_ref()) {
            Some(forwarded) => Some(forwarded),
            None => lane_forwarded_construction(cx, target, method, this),
        }
    {
        // A forwarded method that only initializes `this` from its parameters, which the
        // forwarding passes the construction's arguments as: its adds alone, with neither
        // activation, where the construction completes in the lane (`lane_finishes_construction`).
        // Its body completes with `undefined`, as the forwarding body then does, so
        // [[Construct]] yields `this`.
        if forwarded.initializes() && finishes {
            // SAFETY: the context's program outlives the lane run, and the forwarded target is
            // one of its functions (`lane_script_target`).
            let code = unsafe { &*(*cx).code };
            let argument = lane_construct_argument(r, i);
            if let Some(fields) = construct_plan::lane_finish_forwarded(vm, code, forwarded.env, this, forwarded.function, argument) {
                if let Some(fields) = fields {
                    lane_record_forwarded_fields(vm, callee, (forwarded.program(), forwarded.function), this, &fields);
                }
                return Ok(KeepingConstruction::Finished(this));
            }
        }
        note_construct_site(vm, i, callee, &forwarded);
        let forwarder = SkippedForwarder {
            function: target.function,
            callee,
            env: target.env,
            method,
        };
        return lane_activate_keeping::<H, false>(cx, r, ip, &forwarded, arguments, this, false, Some(forwarder))
            .map(|(registers, base)| KeepingConstruction::Activated(registers, base))
            .map_err(Some);
    }
    lane_activate_keeping::<H, false>(cx, r, ip, &target, arguments, this, true, None)
        .map(|(registers, base)| KeepingConstruction::Activated(registers, base))
        .map_err(Some)
}

/// The finished receiver of a forwarding constructor's construction under `callee`'s
/// holding plan, when it records the fields its forwarded initializer stores
/// (`lane_record_forwarded_fields`) and its forwarding still reads that initializer
/// (`resolved_forwarded_method`): the receiver that initializer's adds would finish, whose
/// body completes with `undefined`, as the forwarding body then does.
#[inline(always)]
fn lane_forwarded_fields<H: Host>(vm: &mut Vm<H>, callee: Value, argument: impl Fn(u16) -> Value) -> Option<Value> {
    let index = holding_construct_plan_index(vm, callee)?;
    // The plan in place: the allocation borrows the heap beside it, not a copy.
    let plan = &vm.lane_stack.construct_plans[index];
    plan.forwarded?.initializer?;
    let mut values = [Value::UNDEFINED; CONSTRUCT_PLAN_FIELDS];
    plan.fill_values(vm, &mut values, argument)?;
    // A nested construction's field is a fresh object of its own plan; allocation never collects.
    if let Some(nested) = vm.lane_stack.construct_plans[index].nested {
        if !construct_plan::nested_root_holds(vm, &nested) { return None; }
        values[usize::from(nested.field)] = construct_plan::nested_construction(vm, nested.constructor, &nested.arguments)?;
    }
    Some(vm.lane_stack.construct_plans[index].allocate_values(&mut vm.heap, &values))
}

/// Records in `callee`'s holding plan of no fields, whose forwarding resolved
/// (`ConstructPlan::forwarded`), the fields `fields` the forwarded `initializer`'s adds gave
/// `this`, which that plan's receiver started as: later constructions allocate the finished
/// object (`lane_forwarded_fields`). The adds ran no guest code, so the plan's epoch still
/// holds.
#[inline(never)]
fn lane_record_forwarded_fields<H: Host>(
    vm: &mut Vm<H>,
    callee: Value,
    initializer: (ProgramId, u32),
    this: Value,
    fields: &ConstructPlan,
) {
    let Some(index) = holding_construct_plan_index(vm, callee) else {
        return;
    };
    let Some(shape) = vm.object_data(this).map(|object| object.shape()) else {
        return;
    };
    let plan = &mut vm.lane_stack.construct_plans[index];
    let Some(resolution) = plan.forwarded.filter(|_| plan.fields == 0) else {
        return;
    };
    *plan = plan.with_recorded(fields, shape, ForwardedResolution { initializer: Some(initializer), ..resolution });
    if let Some(nested) = fields.nested {
        watch_construct_plan(vm, index, false, nested.held());
    }
}

/// The method a forwarding constructor's body (`ScriptCallTarget::forwarded_method`) would
/// call on the receiver `this`, which a construction may activate in its place: the body's
/// two reads, `this.<method>` and its `apply`, as cached hits that run no guest code, the
/// intrinsic `Function.prototype.apply`, and a frameless target. `None` leaves the
/// construction to the constructor's own activation, which makes the reads itself.
#[inline(never)]
fn lane_forwarded_construction<H: Host>(
    cx: *mut LaneContext<H>,
    constructor: ScriptCallTarget,
    method: crate::bytecode::ForwardedThisMethod,
    this: Value,
) -> Option<ScriptCallTarget> {
    // SAFETY: the context's program outlives the lane run, and the constructor belongs to it
    // (`Vm::resolve_script_call_target`), so the body's sites index the run's caches.
    let code = unsafe { &*(*cx).code };
    let vm = unsafe { vm(cx) };
    // The tiers the lane's own reads of these sites take: a constructor every class shares
    // reads its method through the site's megamorphic entries, and `apply` lives on the
    // method's prototype, `Function.prototype`. Any other read takes the general cached one.
    // A read of `name` or `length` prepares its lookup (`Vm::reads_function_info`), which
    // only the general read does.
    let function = match (!vm.reads_function_info(method.method.0))
        .then(|| vm.polymorphic_field_hit(code, this, method.method.1))
        .flatten()
    {
        Some(function) => function,
        None => lane_cached_field(cx, code, this, method.method.0, method.method.1)?,
    };
    let apply = match (!vm.reads_function_info(method.apply.0))
        .then(|| vm.cell_holder_field_hit(code, function, method.apply.1))
        .flatten()
    {
        Some(apply) => apply,
        None => lane_cached_field(cx, code, function, method.apply.0, method.apply.1)?,
    };
    if !matches!(
        vm.heap.function(apply),
        Some(FunctionRecord {
            kind: FunctionKind::Native(Native::FunctionApply),
            ..
        })
    ) || function == constructor.callee
    {
        return None;
    }
    let forwarded = lane_script_target(cx, function)?;
    if let Some(resolution) = forwarded_resolution(vm, constructor.callee, method, function, apply) {
        let index = construct_plan_index(constructor.callee)?;
        record_forwarded_resolution(vm, index, function, resolution);
    }
    Some(forwarded)
}

/// Where a forwarding constructor's reads of `this.<method>` and its `apply`, which gave
/// `function` and `apply`, resolved under `callee`'s plan of no fields while it holds
/// (`ForwardedResolution`): own data properties of the plan's prototype and of the method's
/// prototype, neither shadowed by the receiver template or the method, in shapes that fix
/// their slots. `None` records nothing.
fn forwarded_resolution<H: Host>(
    vm: &Vm<H>,
    callee: Value,
    method: crate::bytecode::ForwardedThisMethod,
    function: Value,
    apply: Value,
) -> Option<ForwardedResolution> {
    let plan = holding_construct_plan(vm, callee).filter(|plan| plan.fields == 0)?;
    let data_slot = |owner: &crate::heap::Object, atom| {
        let shape = owner.shape();
        if vm.shape_is_dictionary(shape) {
            return None;
        }
        let slot = vm.shape_slot(shape, atom)?;
        // SAFETY: the slot exists in the non-dictionary shape that names it.
        let value = unsafe { vm.heap.property_get_shaped(owner, slot) }?;
        (!value.is_deleted()).then_some((u16::try_from(slot).ok()?, value))
    };
    let data = |owner: Value, atom, slot: usize| {
        let key = crate::vm::PropertyKey::string(atom);
        vm.property_attributes(owner, key).is_some_and(|attributes| !attributes.accessor)
            && vm.object_data(owner).is_some_and(|object| vm.shape_slot(object.shape(), atom) == Some(slot))
    };
    if vm.shape_slot(plan.shape, method.method.0).is_some() {
        return None;
    }
    let prototype = vm.heap.object_record(plan.prototype)?;
    let (method_slot, found) = data_slot(prototype, method.method.0)?;
    let FunctionRecord { object, .. } = vm.heap.function(function)?;
    if found != function || vm.shape_slot(object.shape(), method.apply.0).is_some() {
        return None;
    }
    let apply_holder = object.proto();
    let (apply_slot, found) = data_slot(vm.heap.object(apply_holder)?, method.apply.0)?;
    (found == apply
        && data(plan.prototype, method.method.0, usize::from(method_slot))
        && data(apply_holder, method.apply.0, usize::from(apply_slot)))
    .then_some(ForwardedResolution {
        method: function,
        apply_holder,
        initializer: None,
    })
}

/// The method a forwarding constructor's construction activates, from `callee`'s plan's
/// recorded resolution (`resolved_forwarded_method`) as a frameless target, under `plan`,
/// `callee`'s holding plan. `None` resolves afresh (`lane_forwarded_construction`).
#[inline(always)]
fn lane_resolved_forwarding<H: Host>(
    cx: *mut LaneContext<H>,
    callee: Value,
    plan: Option<&ConstructPlan>,
) -> Option<ScriptCallTarget> {
    let function = resolved_forwarded_method(callee, plan?)?;
    lane_script_target(cx, function)
}

/// The method `callee`'s forwarding reads under `plan`, its holding plan: the recorded
/// resolution's (`ConstructPlan::forwarded`), which the plan's dependency keeps (see
/// `ForwardedResolution`), unless it is `callee`.
#[inline(always)]
fn resolved_forwarded_method(callee: Value, plan: &ConstructPlan) -> Option<Value> {
    plan.forwarded.map(|resolution| resolution.method).filter(|&method| method != callee)
}

script_handler! {
    /// `f.apply(this, arguments)` of the running activation's forwarded `arguments`
    /// (`CallForwardingArguments`): `f` runs frameless with the values the activation, or
    /// the frame, kept, as `Vm::try_inline_call_apply` pushes it. Any other call takes the
    /// general path.
    fn lane_forward_call<>(cx, r, ip, i, view) {
        match lane_forward_activation(cx, r, ip, i) {
            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
            Err(next) => next,
        }
    }
}

/// `lane_forward_call`'s activation: the callee's registers and first record, or the record
/// to continue at. Out of line: the call target it passes on lives in its own frame, not
/// the handler's.
#[inline(never)]
fn lane_forward_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
) -> Result<(Registers, Ip), Ip> {
    let window = ImmediateLayout::call_window_base(i.imm());
    if !unsafe { (*cx).script_calls }
        || ImmediateLayout::argument_count(i.imm()) != FORWARDED_APPLY_ARGUMENTS
        || r.get(window + 1) != Value::UNMATERIALIZED_ARGUMENTS
    {
        return Err(exit(ip));
    }
    let vm = unsafe { vm(cx) };
    if !matches!(
        vm.heap.function(r.get(i.b)),
        Some(FunctionRecord {
            kind: FunctionKind::Native(Native::FunctionApply),
            ..
        })
    ) {
        return Err(exit(ip));
    }
    let Some(kept) = (unsafe { lane_kept_arguments(cx) }) else {
        return Err(exit(ip));
    };
    let Some(target) = lane_script_target(cx, r.get(i.c)) else {
        return Err(exit(ip));
    };
    let receiver = r.get(window);
    let Some(this) = lane_call_this(vm, &target, receiver) else {
        return Err(exit(ip));
    };
    lane_activate_keeping::<H, false>(cx, r, ip, &target, kept, this, false, None)
}

use crate::bytecode::FORWARDED_APPLY_ARGUMENTS;

/// The values the running function kept for its forwarded `arguments`: a forwarding
/// activation's, after its registers, or a frame's `original_arguments`.
///
/// # Safety
/// `cx` is the running lane's context.
#[inline(always)]
unsafe fn lane_kept_arguments<H: Host>(cx: *mut LaneContext<H>) -> Option<ActivationArguments> {
    let vm = unsafe { vm(cx) };
    if unsafe { (*cx).registers }.env().is_deleted() {
        let frame = &vm.frames[unsafe { (*cx).frame() }];
        return Some(ActivationArguments::Kept(
            frame.original_arguments.as_ptr(),
            frame.original_arguments.len(),
        ));
    }
    let activation = vm.lane_stack.activations.last()?;
    let script = activation.script().filter(|script| script.forwards)?;
    let registers = usize::from(unsafe { &*(*cx).code }.function(activation.function as usize).registers);
    // SAFETY: the activation's window holds its registers, then its kept values.
    let values = unsafe { activation.window_ptr().add(registers) };
    Some(ActivationArguments::Kept(values, usize::from(script.argc)))
}

script_handler! {
    /// `LoadLocal` of a forwarded `arguments` binding (`CallPlan::forwards_arguments`): a
    /// frameless activation's is unmaterialized, as a frame's starts; a frame's binding is
    /// read as the general path reads it.
    fn lane_load_forwarded_arguments<>(cx, r, ip, i, view) {
        let value = if unsafe { (*cx).registers }.env().is_deleted() {
            // SAFETY: validated bytecode bounds the slot by Function.locals.
            unsafe { vm(cx).read_validated_local((*cx).frame(), i.imm() as usize) }
        } else {
            Value::UNMATERIALIZED_ARGUMENTS
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

script_handler! {
    /// `LoadLocal` of an `arguments` binding a keeping activation makes at its last read
    /// (`KeptArguments::Passes`): the object made from the values it kept, as its frame
    /// makes one on entry, whose binding a frame's run reads.
    #[inline(never)]
    fn lane_load_kept_arguments_object<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let value = if unsafe { (*cx).registers }.env().is_deleted() {
            // SAFETY: validated bytecode bounds the slot by Function.locals.
            unsafe { vm.read_validated_local((*cx).frame(), i.imm() as usize) }
        } else {
            let Some((function, Some(script))) =
                vm.lane_stack.activations.last().map(|activation| (activation.function, activation.script()))
            else {
                return exit(ip);
            };
            // SAFETY: the context's program outlives the lane run.
            let body = unsafe { &*(*cx).code }.function(function as usize);
            // A keeping activation's values follow its registers (`lane_activate_keeping`).
            let kept = (0..script.argc)
                .map(|index| r.get(body.registers + index))
                .collect::<smallvec::SmallVec<[Value; GATHERED_INLINE_VALUES]>>();
            let context = CallContext::user_function(function, script.callee);
            let Ok(arguments) = vm.activation_arguments_object(body, context, &kept) else {
                return exit(ip);
            };
            note_allocation(vm);
            arguments
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), Carried::script_in(cx, view))
    }
}

/// The values the running function kept for its unmaterialized `arguments` binding, in the
/// local slot `slot` (`lane_kept_arguments`): `None` where a frame's binding was
/// materialized, which the general path then reads.
///
/// # Safety
/// `cx` is the running lane's context, and `slot` its function's validated local slot.
#[inline(always)]
unsafe fn lane_unmaterialized_arguments<H: Host>(
    cx: *mut LaneContext<H>,
    slot: usize,
) -> Option<(*const Value, usize)> {
    if unsafe { (*cx).registers }.env().is_deleted()
        && unsafe { vm(cx).read_validated_local((*cx).frame(), slot) }
            != Value::UNMATERIALIZED_ARGUMENTS
    {
        return None;
    }
    match unsafe { lane_kept_arguments(cx) }? {
        ActivationArguments::Kept(values, count) => Some((values, count)),
        ActivationArguments::Window(_) => None,
    }
}

/// The running keeping activation's kept-value count and its function, when the lane runs
/// one (`ScriptActivation::forwards`): its values follow its registers in its window, which
/// `r` names. `None` for a frame or any other activation.
///
/// # Safety
/// `cx` is the running lane's context.
#[inline(always)]
unsafe fn lane_keeping_activation<H: Host>(cx: *mut LaneContext<H>) -> Option<(u16, u32)> {
    if unsafe { (*cx).registers }.env().is_deleted() {
        return None;
    }
    let activation = unsafe { vm(cx) }.lane_stack.activations.last()?;
    let script = activation.script().filter(|script| script.forwards)?;
    Some((script.argc, activation.function))
}

script_handler! {
    /// `lane_arguments_length_general` in a keeping activation: the count of the values it
    /// kept, saving no registers.
    fn lane_arguments_length<>(cx, r, ip, i, view) {
        if let Some((argc, _)) = unsafe { lane_keeping_activation(cx) } {
            r.set(i.a, Value::integer(i32::from(argc)));
            next!(cx, r, following(ip), view)
        }
        sibling!(lane_arguments_length_general::<H>, r, ip, view)
    }
}

script_handler! {
    /// `lane_argument_get_general` in a keeping activation at an integer index it kept: the
    /// value after its registers, saving no registers.
    fn lane_argument_get<>(cx, r, ip, i, view) {
        if let Some((argc, function)) = unsafe { lane_keeping_activation(cx) }
            && let Some(index) = r.get(i.b).as_int().and_then(|index| u16::try_from(index).ok()).filter(|index| *index < argc)
        {
            // The record carries the running function's register count (`derive_lane_view`).
            let _ = function;
            r.set(i.a, r.get(i.c + index));
            next!(cx, r, following(ip), view)
        }
        sibling!(lane_argument_get_general::<H>, r, ip, view)
    }
}

script_handler! {
    /// `ArgumentsLength` of a binding only kept values answer (`Function::kept_arguments`):
    /// their count, as the object made on entry holds it. `lane_arguments_length` answers a
    /// keeping activation first.
    #[inline(never)]
    fn lane_arguments_length_general<>(cx, r, ip, i, view) {
        let Some((_, count)) = (unsafe { lane_unmaterialized_arguments(cx, i.imm() as usize) })
        else {
            return exit(ip);
        };
        r.set(i.a, Value::number(count as f64));
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `ArgumentGet` of such a binding at an integer index it holds: the kept value, as the
    /// object made on entry holds it. Any other key takes the general path, which
    /// materializes the object (`Vm::read_arguments_binding`). `lane_argument_get` answers a
    /// keeping activation first.
    #[inline(never)]
    fn lane_argument_get_general<>(cx, r, ip, i, view) {
        let Some((values, count)) = (unsafe { lane_unmaterialized_arguments(cx, i.imm() as usize) })
        else {
            return exit(ip);
        };
        let Some(index) = r.get(i.b).as_int().and_then(|index| usize::try_from(index).ok()).filter(|index| *index < count)
        else {
            return exit(ip);
        };
        // SAFETY: `values` holds `count` kept values, and the index is below it.
        r.set(i.a, unsafe { *values.add(index) });
        next!(cx, r, following(ip), view)
    }
}

script_handler! {
    /// `ArgumentsLength` (`GET` false) or `ArgumentGet` (`GET` true) of a function whose
    /// `arguments` binding is no forwarding one, in its frame's own lane run, as
    /// `Vm::read_arguments_binding` reads it: an unmaterialized binding answers its length
    /// and the indices it kept from the frame's values; a materialized object its own data
    /// `length` in its creation layout (`Vm::arguments_object_length`) and its stored
    /// elements no parameter mapping reaches (`Vm::plain_arguments_element`). Any other read,
    /// a mapped element (which aliases a parameter) among them, takes the general path. A
    /// suspended function's window holds the object made on entry (`window_arguments`).
    #[inline(never)]
    fn lane_frame_arguments<GET: bool>(cx, r, ip, i, view) {
        // An environment activation keeps the values passed after its locals
        // (`Function::reads_passed_arguments_only`); a suspended function's window keeps the
        // object itself (`Function::arguments_ride_window`).
        if !unsafe { (*cx).registers }.env().is_deleted() {
            let vm = unsafe { vm(cx) };
            let Some((function, argc)) = vm.lane_stack.activations.last().and_then(|activation| {
                let script = activation.script().filter(|script| script.environment)?;
                Some((activation.function, script.argc))
            }) else {
                return exit(ip);
            };
            // SAFETY: the context's program outlives the lane run.
            let body = unsafe { &*(*cx).code }.function(function as usize);
            if body.is_generator || body.is_async {
                let Some(value) = window_arguments::<H, GET>(vm, r, i, body) else {
                    return exit(ip);
                };
                r.set(i.a, value);
                next!(cx, r, following(ip), view)
            }
            let value = if GET {
                let Some(index) = r.get(i.b).as_int().and_then(|index| u16::try_from(index).ok()).filter(|index| *index < argc)
                else {
                    return exit(ip);
                };
                // A parameter's element is the parameter while the mapping aliases it.
                let local = if index < body.params && body.arguments_alias_parameters() {
                    index
                } else {
                    body.locals + index
                };
                r.get(body.registers + WINDOW_LOCALS + local)
            } else {
                Value::integer(i32::from(argc))
            };
            r.set(i.a, value);
            next!(cx, r, following(ip), view)
        }
        let vm = unsafe { vm(cx) };
        let frame = unsafe { (*cx).frame() };
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let Ok(binding) = vm.load_local_binding(code, VarOwner::Frame(frame), i.imm() as usize, None) else {
            return exit(ip);
        };
        let kept = &vm.frames[frame].original_arguments;
        let value = match (binding == Value::UNMATERIALIZED_ARGUMENTS, GET) {
            (true, false) => Some(Value::length(kept.len())),
            (true, true) => r
                .get(i.b)
                .as_int()
                .and_then(|index| usize::try_from(index).ok())
                .and_then(|index| kept.get(index).copied()),
            (false, false) => vm.arguments_object_length(binding),
            (false, true) => r
                .get(i.b)
                .as_int()
                .and_then(|index| usize::try_from(index).ok())
                .and_then(|index| vm.plain_arguments_element(binding, index)),
        };
        let Some(value) = value else {
            return exit(ip);
        };
        r.set(i.a, value);
        next!(cx, r, following(ip), view)
    }
}

/// `ArgumentsLength` or `ArgumentGet` in the window of a suspended function: the `arguments`
/// object it made on entry is the function's local `i.imm()` (`mapped_windows::window_binding`),
/// read as a materialized object is, a mapped element too: the window's writes to its parameter
/// reach it (`lane_store_mapped_parameter`). `None` takes the general path.
#[inline(always)]
fn window_arguments<H: Host, const GET: bool>(vm: &Vm<H>, r: Registers, i: &LaneInstruction, body: &Function) -> Option<Value> {
    let binding = mapped_windows::window_binding(vm, r, body, i.imm() as usize);
    if !GET {
        return vm.arguments_object_length(binding);
    }
    let index = usize::try_from(r.get(i.b).as_int()?).ok()?;
    vm.stored_arguments_element(binding, index)
}

/// The frameless target of a lane call to `callee`, resolved on first use.
/// Whether `callee` is the target of a `new` whose `new.target` the general path still
/// holds (`Vm::construct_target`): a lane activation would not bind it.
#[inline(always)]
fn lane_constructing<H: Host>(vm: &Vm<H>, callee: Value) -> bool {
    vm.construct_target
        .is_some_and(|target| target.callee == callee)
}

#[inline(always)]
fn lane_script_target<H: Host>(cx: *mut LaneContext<H>, callee: Value) -> Option<ScriptCallTarget> {
    lane_script_target_in(cx, callee, &mut None).copied()
}

/// `lane_script_target`'s target, read in place where the cache holds it, else resolved
/// into `resolved`. The cache's entry holds until the next resolution or collection.
#[inline(always)]
fn lane_script_target_in<H: Host>(
    cx: *mut LaneContext<H>,
    callee: Value,
    resolved: &mut Option<ScriptCallTarget>,
) -> Option<&ScriptCallTarget> {
    let vm = unsafe { vm(cx) };
    if lane_constructing(vm, callee) {
        return None;
    }
    // The paths besides a plain call (constructions, getters, forwarded and applied calls)
    // activate callees of the running program alone. Another program's callee, once
    // resolved, is held apart (`cross_call_entry`) for the callers that activate across
    // programs; resolving it again would only find it so.
    // The cached entry is tested and used in place; `script_call_holds` admitted it for the
    // active program already.
    if let Some(entry) = vm.script_call_entry(callee) {
        // SAFETY: the entry is read before anything else touches the cache.
        let target = unsafe { &*entry };
        return lane_admits_activation(target).then_some(target);
    }
    if vm.cross_call_entry(callee).is_some() {
        return None;
    }
    let active = vm.active_program;
    *resolved = vm.resolve_script_call_target(unsafe { &*(*cx).code }, callee)
        .filter(|target| target.program() == active && lane_admits_activation(target));
    resolved.as_ref()
}

/// The instance environment the running Wasm function reads its bindings from: the
/// export's (`LaneContext::instance`) above a JavaScript call of it, else its frame's.
#[inline(always)]
fn lane_instance_env<H: Host>(cx: *mut LaneContext<H>) -> Value {
    // SAFETY: the context outlives the lane run.
    let instance = unsafe { (*cx).instance };
    if !instance.is_deleted() {
        return instance;
    }
    unsafe { vm(cx).frames[(*cx).frame()].env }
}

/// Make `program` the lane's running program, as a call into or a return to one of its
/// functions makes it the general loop's executing one: the residual, lane views and
/// constants its records read, and the VM's active program, whose cache layout its sites
/// index.
#[inline(always)]
fn lane_enter_program<H: Host>(cx: *mut LaneContext<H>, program: ProgramId) {
    let vm = unsafe { vm(cx) };
    let context = vm.lane_program_context(program);
    vm.activate_context(program, context);
    // SAFETY: the context outlives the lane run; the store keeps the program's residual,
    // views and constants for it, and its context names them.
    unsafe {
        (*cx).code = (*context).code;
        (*cx).program = program;
        (*cx).views = (*context).views;
        (*cx).constants = (*context).constants;
    }
}

/// Activate `target`, which keeps no passed values (callers route those to
/// `lane_activate_keeping`), for the call record at `ip` with the arguments from register
/// `arguments` on: the activation's registers and the callee's
/// first record, or the record to continue at when the call takes the general path.
#[inline(always)]
fn lane_activate<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    arguments: u16,
    this: Value,
    constructs: bool,
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the running view.
    let i = unsafe { &*ip };
    let argc = ImmediateLayout::argument_count(i.imm());
    // A call that returns its callee's completion completes its caller too, which only an
    // activation's return does in the lane. A host permitting proper tail calls
    // sends strict terminal calls to the general dispatch path instead.
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if returns && !lane_returning_call_admitted(cx) {
        return Err(exit(ip));
    }
    if vm.with_scope_entered {
        return Err(exit(ip));
    }
    // Values past the parameters stay observable (legacy `f.arguments`, a frame made of the
    // activation): the keeping activation holds them after the registers. A callee no legacy
    // reflection observes is passed its parameters alone, as its frame would keep them.
    if argc > target.params && (!target.drops_extra_arguments() || target.forwards()) {
        // A call keeping every value it was passed, a rest body's array aside, takes the plain
        // push with the values after its registers.
        if !constructs && target.entry != CallEntry::Gathers {
            return lane_activate_keeping_window::<H, true>(cx, r, ip, target, arguments, this);
        }
        return lane_activate_keeping::<H, true>(
            cx,
            r,
            ip,
            target,
            ActivationArguments::Window(arguments),
            this,
            constructs,
            None,
        );
    }
    if !lane_activation_room(vm, target) {
        return Err(lane_script_call_frame::<H>(ip, usize::from(target.room)));
    }
    // SAFETY: the call's window of `r` holds its `argc` values.
    let passed = unsafe { r.0.add(usize::from(arguments)).cast_const() };
    Ok(lane_push_passed::<H, true, false>(cx, r, ip, target, passed, argc.min(target.params), this, constructs))
}

/// Whether the lane stack takes `target`'s activation: capacity, the guest-call budget and
/// a due collection (`LaneStack::activation_limit`).
#[inline(always)]
fn lane_activation_room<H: Host>(vm: &Vm<H>, target: &ScriptCallTarget) -> bool {
    vm.lane_stack.activations.len() < vm.lane_stack.activation_limit.get()
        && crate::staged::call::concrete_fits(vm.lane_stack.values.room() as u64, u64::from(target.room))
}

/// Whether `target`'s parameters take `argc` arguments and the lane stack holds its activation:
/// the staged admission (`staged::call::admit_room`) that the native tiers emit, run on words.
#[inline(always)]
fn lane_admits_window<H: Host>(vm: &Vm<H>, target: &ScriptCallTarget, argc: u16) -> bool {
    crate::staged::call::concrete_fits(u64::from(target.params), u64::from(argc)) && lane_activation_room(vm, target)
}

script_handler! {
    /// The tier prologue a frameless activation of a function the JavaScript tier may claim
    /// starts at (`LaneView::claim_for_tier`): the tier runs the body natively where it can
    /// (`Vm::js_tier_activation_entry`), and the activation continues at the record the
    /// native result completes, with the result in its register; else at its first record.
    /// The tier enters the activation as it would a frame, so claiming a function never
    /// changes how it is called. Once the tier declines the function, its activations start
    /// at the first record again.
    #[inline(never)]
    fn lane_tier_prologue<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let (function, params) = (i.imm(), usize::from(i.a));
        // SAFETY: the activation just set the context to its own function's.
        let base = unsafe { (*cx).base };
        // SAFETY: the program's views outlive the lane run.
        let own = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view);
        // SAFETY: the activation's registers hold its parameters from its first.
        let parameters = unsafe { std::slice::from_raw_parts(r.0, params) };
        let entered = own
            .and_then(|own| lane_tier_direct(vm, own, parameters))
            .or_else(|| lane_tier_enter(cx, function, own, parameters));
        if let Some((pc, register, value)) = entered {
            r.set(register, value);
            // SAFETY: the tier returns a PC of the function, whose records are contiguous.
            next!(cx, r, unsafe { base.add(pc) }, Carried::script_in(cx, view))
        }
        next!(cx, r, base, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// The prologue record of a function whose lane body specialized
    /// (`LaneView::specialize_lane_body`): it runs the body on the activation's registers and
    /// continues where the body left. What the specialization proved it does not test again:
    /// each inlined call's guards run in the body, and a leave inside one resolves its target
    /// (`lane_body_inlined_activation`); the entry tests only what varies per run, the room
    /// for the activation such a leave makes.
    #[inline(never)]
    fn lane_body_entry<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        let function = i.imm();
        // SAFETY: the activation just set the context to its own function's.
        let (program, base) = unsafe { ((*cx).program, (*cx).base) };
        // SAFETY: the program's views outlive the lane run; this record is the view's.
        let own = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view)
            .expect("a lane body entry runs in its view");
        // An entry of the audit's interpreted epoch runs the function's records (`lane_body_audit`).
        if own.audit_entry(true) {
            next!(cx, r, base, Carried::script_in(cx, view))
        }
        // A body a lifecycle edge retired gives its prologue back and warms again.
        let Some(method) = own.cell_body().or_else(|| own.lane_body()) else {
            own.settle_retired_body();
            next!(cx, r, base, Carried::script_in(cx, view))
        };
        // A body whose rows write past the frame's registers (its scratch, its inlined windows, past the
        // environment window) runs where the frame's storage reaches them; a lane activation's room is the stack's.
        let reaches = lane_frame_reaches(cx, method.caller_registers(), method.frame_reach());
        if !reaches || !lane_body_admits(cx, &method, NO_PENDING_ACTIVATIONS) {
            if reaches && lane_body_prepare_recovery(cx, &method) { return exit(base); }
            drop(method);
            lane_body_refused(vm, own);
            next!(cx, r, base, Carried::script_in(cx, view))
        }
        let receiver = lane_entry_receiver(cx, i.b != 0);
        // SAFETY: the activation just set the context to its own captures.
        let captures = capture_reads(unsafe { (*cx).registers }.capture());
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let exit = vm.run_lane_method(&method, lane_direct_calls(cx), program, code, r.0, receiver, captures, cx.cast());
        let resumed = lane_body_concluded::<H>(cx, r, ip, own, &method, exit, function);
        drop(method);
        resume!(cx, resumed)
    }
}

/// The receiver word a body is entered with: the running activation's `this` where the
/// prologue says the body reads it (`LaneView::binds_this`), `DELETED` otherwise. A frame
/// activation keeps its `this` in the frame (`lane_this`); an uninitialized one stays `DELETED`,
/// at which the body's `LoadThis` leaves for the general path. The activation's `this` is
/// bound already, by the call's `lane_direct_call_this` (sloppy coercion included).
#[inline(always)]
fn lane_entry_receiver<H: Host>(cx: *mut LaneContext<H>, binds_this: bool) -> Value {
    // SAFETY: the context is the running activation's, or the leaf's callee.
    if binds_this { unsafe { lane_this(cx, (*cx).registers) }.unwrap_or(Value::DELETED) } else { Value::DELETED }
}

/// Where the lane continues after a run of `method`, `own`'s body, that ran on the
/// activation `cx` holds, with registers `r`, and ended at `exit`: a returned run completes
/// the activation (no leave to resolve, no frame to materialize), any other leave resumes
/// where it names (`lane_body_left`); `started` is the audit's clock for this entry, read once
/// the run's leave is resolved.
#[inline(always)]
fn lane_body_concluded<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    own: &LaneView,
    method: &super::compiled::LaneMethod,
    left: super::compiled::LaneExit,
    function: u32,
) -> Resumed {
    let base = unsafe { (*cx).base };
    if let super::compiled::LaneExit::Returned { pc, value } = left {
        lane_record_end(cx, own, method, left);
        // SAFETY: as `lane_leave_counts`; a completed run carries no warming callee.
        unsafe { (*cx).callee_warming = false };
        lane_note_body_end(cx, own, left, |_| {});
        // SAFETY: the record that completes the activation is one of its function's.
        return lane_returned(cx, unsafe { base.add(pc) }, value);
    }
    let counts = lane_leave_counts(cx, left);
    let (resumed, feedback) = lane_body_left(cx, r, own, method, left);
    // Counted once the leave is resolved: a retirement or reoptimization moves the body.
    if counts {
        lane_note_body_end(cx, own, feedback, |left| lane_note_leave(cx, function, left));
    } else {
        lane_note_warming_leave(cx, own);
    }
    lane_body_resumed(cx, ip, resumed)
}

/// Where the lane continues after a lane body's resolved leave `resumed`, which left at `ip`.
#[inline(always)]
fn lane_body_resumed<H: Host>(cx: *mut LaneContext<H>, ip: Ip, resumed: LaneBodyLeft) -> Resumed {
    match resumed {
        LaneBodyLeft::Terminated => Resumed::Exit(exit(ip)),
        LaneBodyLeft::Resume(_, resume, _) if body_calls::left_lane(resume) => Resumed::Exit(resume),
        LaneBodyLeft::Resume(registers, resume, carried) => Resumed::At(registers, resume, carried),
        LaneBodyLeft::Raised(record) => Resumed::Exit(lane_raised_exit(cx, record)),
        LaneBodyLeft::Completed(record, value) => lane_returned(cx, record, value),
    }
}

/// `lane_return_value!` as the resumption it continues at.
#[inline(always)]
fn lane_returned<H: Host>(cx: *mut LaneContext<H>, record: Ip, value: Value) -> Resumed {
    lane_complete_plain_activation::<H, NOT_LEAF>(cx, value).unwrap_or_else(|| lane_return_value_general(cx, record, value))
}

/// The tier prologue's run of the compiled body `own` keeps for a body that reads only its
/// parameters (`LaneView::tier_direct`): the `Return` to continue at, its register and the
/// result.
#[inline(always)]
fn lane_tier_direct<H: Host>(
    vm: &mut Vm<H>,
    own: &LaneView,
    parameters: &[Value],
) -> Option<(usize, crate::bytecode::Register, Value)> {
    let direct = own.tier_direct.take()?;
    let entered = vm.run_direct_tier_entry(&direct, parameters);
    if !direct.retired() {
        own.tier_direct.set(Some(direct));
    }
    entered
}

/// The tier prologue's entry where no direct run completes the activation
/// (`Vm::js_tier_activation_entry`). A completed entry keeps the direct run the
/// compiled body admits; once the tier declines the function, its activations start at
/// the first record again (`LaneView::release_from_tier`).
#[cold]
#[inline(never)]
fn lane_tier_enter<H: Host>(
    cx: *mut LaneContext<H>,
    function: u32,
    own: Option<&LaneView>,
    parameters: &[Value],
) -> Option<(usize, crate::bytecode::Register, Value)> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the activation just set the context to its own function's.
    let (code, program) = unsafe { (&*(*cx).code, (*cx).program) };
    // A lane body runs on the activation itself, so it takes the function from the
    // frame-entering tier: the activation warms toward it in the lane, and a function whose
    // body declines runs in the lane, as it does without lane bodies.
    if vm.programs.js_jit_lane_methods_enabled()
        && let Some(own) = own
    {
        if !lane_specialize(cx, own, function, false, parameters) {
            own.release_from_tier();
        }
        return None;
    }
    // A function only lane bodies claimed (`claim_for_tier`) has no JS-tier entry to try.
    let may_claim = vm.js_tier_may_claim(code, program, function);
    if may_claim
        && let Some(entered) = vm.js_tier_activation_entry(code, program, function, parameters)
    {
        if let Some(own) = own
            && let Some(direct) = vm.direct_tier_entry(code, program, function)
        {
            own.tier_direct.set(Some(direct));
        }
        return Some(entered);
    }
    if let Some(own) = own
        && !may_claim
    {
        own.release_from_tier();
    }
    None
}

/// The script targets the call record at `pc` of `view` linked (`call_link`), newest first:
/// its latest and its history (`LaneStack::call_sites`), each where a plain call of it binds
/// an ordinary `this` and activates in place: what a lane body inlines (`lane_unit::unit`).
fn lane_site_targets<H: Host>(vm: &Vm<H>, view: &LaneView, pc: u32) -> Vec<super::compiled::CallTarget> {
    // SAFETY: the view holds a record per PC; reading its link changes nothing.
    let Some(record) = view.records.get(pc as usize).map(|record| unsafe { &*record.get() }) else { return Vec::new() };
    let history = vm.lane_stack.call_sites.borrow();
    // The callees the site resolved or memoized, in the order first seen (`LaneStack::note_site_callee`).
    let recorded = history.get(&std::ptr::from_ref(&record.call_link).addr());
    // A collection since the site linked retires its entry; the callee's own entry of this
    // generation, where a call resolved it again, is the same target. A linked entry another
    // site's callee took since names no callee of this site.
    let latest = vm.lane_stack.script_targets.entries.get(usize::from(record.call_link.get())).and_then(|linked| {
        if linked.generation() == vm.lane_stack.generation {
            Some(linked)
        } else {
            // SAFETY: as `Vm::script_call_entry`; nothing below resolves a target.
            vm.script_call_entry(linked.callee).map(|target| unsafe { &*target })
        }
    }).filter(|target| {
        target.program() == vm.active_program
            && target.entry.activates_registers_only()
            && target.this_binding.binds_receiver()
            && recorded.is_none_or(|recorded| recorded.iter().any(|site| site.identity() == Some(target.callee)))
    });
    match latest {
        Some(latest) => {
            let latest = super::compiled::CallTarget {
                callee: super::compiled::CalleeBinding::Identity(latest.callee), function: latest.function };
            std::iter::once(latest)
                .chain(recorded.into_iter().flatten().rev().copied().filter(|target| *target != latest))
                .take(super::compiled::tier_policy::POLYMORPHISM)
                .collect()
        }
        // A site that runs only in its function's lane body, or that a read memo answers,
        // links nothing current: the callees it recorded, else the body's own inlined calls
        // (`lane_unit::Frame`), are its targets.
        None => match recorded {
            Some(recorded) => recorded.iter().rev().copied().collect(),
            None => view.lane_body().map_or_else(Vec::new, |method| {
                method.inlined.iter()
                    .filter(|frame| frame.parent.is_none() && frame.call == pc)
                    .map(|frame| frame.target)
                    .collect()
            }),
        },
    }
}

/// `lane_site_targets` of any function of the running program, by its view.
fn lane_unit_targets<H: Host>(cx: *mut LaneContext<H>, function: u32, pc: u32) -> Vec<super::compiled::CallTarget> {
    // SAFETY: the program's views outlive the lane run.
    let Some(view) = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view) else {
        return Vec::new();
    };
    lane_site_targets(unsafe { vm(cx) }, view, pc)
}

/// The mean trips of the loop at `header` of any function of the running program per native
/// run of it (`LoopTier::mean_trip`): what its call sites are weighed by (`lane_unit::with_trips`).
fn lane_unit_trips<H: Host>(cx: *mut LaneContext<H>, function: u32, header: u32) -> Option<u64> {
    // SAFETY: the program's views outlive the lane run.
    let view = unsafe { &*(*cx).views }.get(function as usize).and_then(super::program_store::derived_lane_view)?;
    for site in &view.loops {
        if site.header == header {
            return site.tier.borrow().mean_trip();
        }
    }
    None
}

/// The dense capture slots of `callee`'s environment (`Vm::lane_callee_captures`).
fn lane_callee_captures<H: Host>(cx: *mut LaneContext<H>, callee: Value) -> (usize, usize) {
    unsafe { vm(cx) }.lane_callee_captures(callee)
}

impl<H: Host> Vm<H> {
    /// The dense capture slots of `callee`'s environment (`EnvironmentSlots::native_dense_view`),
    /// as values and count, or none: what an inlined frame of it reads its captures from.
    pub(super) fn lane_callee_captures(&self, callee: Value) -> (usize, usize) {
        self.script_call_entry(callee)
            // SAFETY: as `Vm::script_call_entry`; a live environment's slots never move.
            .and_then(|target| unsafe { crate::heap::EnvironmentSlots::native_storage_view(capture_reads((*target).capture)) })
            .map_or((0, 0), |(values, len)| (values.addr(), len))
    }
}

/// Per PC of `body`, the callees its call site reached where the callee's own lane body
/// specialized and the lane would activate it in place, with an ordinary `this`, from a
/// plain call of at most its parameters: what a lane body calls by its compiled entry
/// (`compiled::DirectCallee`), the latest first.
fn lane_direct_callees<H: Host>(vm: &Vm<H>, view: &LaneView, function: u32, body: &crate::bytecode::Function) -> Vec<super::compiled::DirectCandidates> {
    let tail_calls = vm.host.proper_tail_calls() && body.strict;
    body.code.iter().enumerate().map(|(pc, packed)| {
        let instruction = body.widened(*packed);
        let direct = instruction.op().is_call() && !instruction.direct_eval() && !instruction.parameter_eval()
            && !(tail_calls && instruction.returns_from_frame());
        let mut callees = super::compiled::DirectCandidates::new();
        if instruction.op().class().eq(Class::Construct) {
            callees.extend(lane_construct_callee(vm, view, function, pc, ImmediateLayout::argument_count(instruction.imm())));
            return callees;
        }
        callees.extend(lane_body_tier::site_targets(vm, view, pc).filter(|_| direct)
            .filter_map(|target| lane_direct_callee(vm, view, function, pc, ImmediateLayout::argument_count(instruction.imm()), target)));
        callees
    }).collect()
}

/// Records the forwarded initializer the construction at `i` ran, which a body may call by
/// its entry (`lane_construct_callee`).
fn note_construct_site<H: Host>(vm: &Vm<H>, i: &LaneInstruction, constructor: Value, forwarded: &ScriptCallTarget) {
    vm.lane_stack.note_site_callee(&i.call_link, super::compiled::CallTarget {
        callee: super::compiled::CalleeBinding::Forwarded { through: constructor, callee: forwarded.callee },
        function: forwarded.function,
    });
}

/// The `compiled::DirectCallee` of the construction at `pc` of `view` through a forwarding
/// constructor: the forwarded initializer the site last ran (`lane_construct_keeping_activation`)
/// as the callee, the constructor as the identity it guards and the activation it skips.
fn lane_construct_callee<H: Host>(vm: &Vm<H>, view: &LaneView, function: u32, pc: usize, argc: u16) -> Option<super::compiled::DirectCallee> {
    for site in lane_site_targets(vm, view, pc as u32) {
        let super::compiled::CalleeBinding::Forwarded { through, callee } = site.callee else { continue };
        // SAFETY: as `Vm::script_call_entry`; both targets are copied before anything resolves one.
        let (constructor, initializer) = unsafe { (*vm.script_call_entry(through)?, *vm.script_call_entry(callee)?) };
        let method = *vm.lane_stack.forwarded_methods.get(constructor.forwarded_method as usize)?;
        if !constructor.forwards() || !constructor.constructs() || holding_construct_plan(vm, through).is_none_or(|plan| plan.forwarded.is_none()) {
            return None;
        }
        let mut direct = lane_direct_callee(vm, view, function, pc, argc, initializer)?;
        direct.callee = through;
        direct.forwarder = Some(SkippedForwarder { function: constructor.function, callee: through, env: constructor.env, method });
        return Some(direct);
    }
    None
}

/// The `compiled::DirectCallee` of `target`, the callee the call at `pc` of `view` passes
/// `argc` arguments, where the lane would activate it in place.
pub(in crate::vm) fn lane_direct_callee<H: Host>(vm: &Vm<H>, view: &LaneView, function: u32, pc: usize, argc: u16, target: ScriptCallTarget) -> Option<super::compiled::DirectCallee> {
    // An arrow's body reads its environment's `this`: BaseJIT's direct row passes it none.
    let (sloppy, lexical) = match target.this_binding {
        ThisBinding::Sloppy => (Some(vm.realm.globals), false),
        ThisBinding::Strict => (None, false),
        ThisBinding::Lexical if crate::jit_mode::base_only() => (None, true),
        _ => return None,
    };
    (target.generation() == vm.lane_stack.generation && target.program() == vm.active_program
        && target.entry.activates() && !target.view.is_null() && argc <= target.params)
        .then_some(())?;
    // SAFETY: a resolved target's view outlives its program.
    let view_of = unsafe { &*target.view };
    let (method, body) = view_of.pinned_callee(target.function == function);
    // SAFETY: a live environment's slots never move (`ScriptCallTarget::capture`).
    let (capture_values, capture_len) = unsafe { crate::heap::EnvironmentSlots::native_storage_view(capture_reads(target.capture)) }
        .unwrap_or((std::ptr::null(), 0));
    Some(super::compiled::DirectCallee {
        target, method, body, call: view.records().wrapping_add(pc).addr(), cell: view_of.entry_cell(),
        callee: target.callee, registers: target.registers, sloppy, lexical, capture_values, capture_len, capture_stores: capture_stores(target.capture).is_some(), forwarder: None,
    })
}

/// Whether a lane body's run may call bodies by their compiled entries: the lane may make
/// their activations should it leave inside one (`lane_body_call`'s own conditions).
fn lane_direct_calls<H: Host>(cx: *mut LaneContext<H>) -> bool {
    let vm = unsafe { vm(cx) };
    let script_calls = unsafe { (*cx).script_calls };
    // A direct callee's registers follow the caller's window, where an activation that keeps its
    // locals there (`lane_context_locals_in_window`) has them: such a run calls through the lane.
    script_calls && !vm.with_scope_entered && vm.construct_target.is_none() && !unsafe { lane_context_locals_in_window::<H>(cx as usize) }
}

/// Whether a run of `own`'s specialized body may start: the one thing per run it cannot
/// prove at specialization, that the lane can make the activation of a call it inlines
/// should it leave inside one (`lane_body_inlined_activation`). `pending` activations are
/// the running body's own, which its call has not pushed yet (`lane_enter_cell_body`).
#[inline(always)]
fn lane_body_admits<H: Host>(cx: *mut LaneContext<H>, method: &super::compiled::LaneMethod, pending: usize) -> bool {
    lane_room_admits(cx, method.recovery_space(), pending)
}

/// Whether the lane has the room `room` names: the activations and values a leave inside an inlined
/// callee of native code about to run makes (`lane_body_inlined_activation`), past the `pending`
/// activations the running body's own call has not pushed.
#[inline(always)]
fn lane_room_admits<H: Host>(cx: *mut LaneContext<H>, room: LaneRecoverySpace, pending: usize) -> bool {
    let vm = unsafe { vm(cx) };
    // The values past the stack's top hold the frame slots the rows write past a lane activation's
    // registers (`LaneRecoverySpace::reaching`), whether or not the code inlines an activation.
    (room.activations == 0 && (vm.lane_stack.activations.is_empty() || vm.lane_stack.values.room() >= room.values))
        || (vm.lane_stack.activation_limit.get().saturating_sub(vm.lane_stack.activations.len() + pending) >= room.activations
            && vm.lane_stack.values.room() >= room.values
            && unsafe { (*cx).script_calls }
            && !vm.with_scope_entered)
}

/// A compiled region's recovery demand may exceed the calls the lane has observed.
/// Materialize before growing either Vec: live lane windows borrow their storage.
/// The caller must exit immediately and resume from its original semantic record.
#[cold]
#[inline(never)]
fn lane_body_prepare_recovery<H: Host>(cx: *mut LaneContext<H>, method: &super::compiled::LaneMethod) -> bool {
    lane_room_prepare(cx, method.recovery_space())
}

/// Grows the lane stacks to the room `room` names (`lane_room_admits`), materializing the lane's
/// activations first; whether it grew them. The caller must exit at once and resume from its
/// original semantic record.
#[cold]
#[inline(never)]
fn lane_room_prepare<H: Host>(cx: *mut LaneContext<H>, room: LaneRecoverySpace) -> bool {
    let vm = unsafe { vm(cx) };
    if !unsafe { (*cx).script_calls } || vm.with_scope_entered { return false; }
    let values = vm.lane_stack.values.room() < room.values;
    let activations = vm.lane_stack.activations.capacity() - vm.lane_stack.activations.len() < room.activations;
    if !values && !activations { return false; }
    vm.materialize_lane_activations(cx);
    if values { vm.lane_stack.reserve_values(room.values); }
    if activations { vm.lane_stack.activations.reserve(room.activations); }
    vm.lane_stack.refresh_activation_limit();
    true
}

/// The calls native code runs as their callees' rows: a lane body's (`LaneMethod`) or a loop region's
/// (`CallCode`), their frames, whether the frames' registers are in the activation's register file past
/// the caller's (a stitched body's or region's) and not in the scratch window the code fills, and the
/// registers of the function that makes them.
#[derive(Clone, Copy)]
struct InlinedRun<'a> {
    frames: &'a [super::compiled::InlinedCall],
    framed: bool,
    caller_registers: u16,
}

impl<'a> InlinedRun<'a> {
    fn of_body(method: &'a super::compiled::LaneMethod) -> Self {
        Self { frames: &method.inlined, framed: method.framed(), caller_registers: method.caller_registers() }
    }

    /// A BaseJIT region's: its frames' registers are in the register file.
    fn of_region(calls: &'a super::compiled::CallCode) -> Self {
        Self { frames: &calls.inlined, framed: true, caller_registers: calls.caller_registers() }
    }
}

/// The activation native code that left inside inlined `frame` of `run`, at its callee's
/// PC `pc`, continues in: the activations the calls of the frame and the frames around it
/// make (`lane_push_activation`), outermost first, each holding the registers native code
/// held for it (`Vm::lane_scratch`); the innermost's record at `pc`. Each frame's call
/// guard proved its callee the inlined one, whose resolution is a function of it; a cache
/// that dropped its entry resolves it again.
fn lane_body_inlined_activation<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    base: Ip,
    run: InlinedRun<'_>,
    frame: usize,
    pc: u32,
) -> (Registers, Ip, Carried) {
    let frames = run.frames;
    if run.framed {
        // Only the frames' own reach: the scratch window may be wider (another code's), past this storage.
        Vm::<H>::lane_adopt_window(r.0.cast_const(), usize::from(run.caller_registers), super::compiled::window_width(frames, run.caller_registers));
    }
    let mut chain = vec![frame];
    while let Some(parent) = frames[*chain.last().expect("a chain has a frame")].parent {
        chain.push(parent);
    }
    let (mut registers, mut records) = (r, base);
    let mut view = std::ptr::null::<LaneView>();
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    for (depth, &index) in chain.iter().enumerate().rev() {
        let call = frames[index];
        let vm = unsafe { vm(cx) };
        // Cache eviction is not invalidation of an immutable callee binding: a lifecycle
        // edge retires the body first (`ProgramStore::retire_dead_native_calls`). Resolve
        // only when recovery needs the activation, rather than scanning at entry.
        let callee = call.target.identity().expect("a lane body's inlined callee has its identity");
        let target = vm.script_call_entry(callee)
            // SAFETY: copy the current cache row before any cache mutation.
            .map(|target| unsafe { *target })
            .or_else(|| vm.resolve_script_call_target(code, callee))
            .expect("an inlined callee resolves");
        // SAFETY: the record is the call's in its parent's view.
        let (target, record) = (&target, unsafe { records.add(call.call as usize) });
        let parent = call.parent_base(frames);
        let this = lane_call_this(vm, target, registers.get(call.receiver - parent)).expect("a direct-object receiver binds itself");
        // The frame's own window and count: a call through `call` passes past its receiver
        // (`lane_unit::Frame::function_call`).
        // SAFETY: the call's window of `registers` holds its values.
        let passed = unsafe { registers.0.add(usize::from(call.window - parent)).cast_const() };
        let (callee, _) = lane_push_passed::<H, false, false>(cx, registers, record, target, passed, call.arguments, this, false);
        // The frame's registers live where it stands, the leave's PC or its inner frame's
        // call; the exit wrote only those (`lane_region`), the rest keep the activation's.
        let at = match depth.checked_sub(1) { Some(inner) => frames[chain[inner]].call, None => pc };
        let live = code.register_root_masks(call.target.function);
        let scratch = usize::from(call.base - run.caller_registers);
        Vm::<H>::lane_scratch(scratch, usize::from(call.registers), |register, value| {
            if live.is_none_or(|live| live.is_live(at as usize, register)) {
                callee.set(register, value);
            }
        });
        // The activation's records start at the context's base, past any tier prologue its
        // entry record is.
        (registers, records, view) = (callee, unsafe { (*cx).base }, target.view);
    }
    // SAFETY: the innermost activation's view holds a record for each of its function's PCs.
    let resume = unsafe { records.add(pc as usize) };
    (registers, resume, lane_carried_at(cx, view, registers, pc))
}

/// What an activation carries into the record at `pc` of its function's `view`: the script
/// state, and the accumulator where the record reads one.
fn lane_carried_at<H: Host>(cx: *mut LaneContext<H>, view: *const LaneView, registers: Registers, pc: u32) -> Carried {
    let mut carried = Carried::script(cx);
    // SAFETY: a resolved target's view outlives the lane run.
    if let Some(&register) = unsafe { &*view }.accumulator_registers.get(pc as usize)
        && register != NO_ACCUMULATOR
    {
        carried.acc = Slot::of(registers.get(register));
    }
    carried
}

/// A lane body's call at `call_pc` of the running activation (`lane_region`'s `Call`): the
/// activation `lane_script_call`'s common form makes, then the callee's own lane body. A
/// callee whose body returns completes the call (`lane_return_plain`), the result in the
/// call's register; one that leaves, or has no body, leaves the lane at its record in that
/// activation (`LaneContext::callee_resume`). A call the common form does not make misses,
/// before any of its effects.
///
/// # Safety
/// `context` is the running lane's context, whose activation's registers hold the caller's
/// state; nothing the call runs allocates or collects.
/// A lane body's read of a capture `packed` names (depth in its high half, slot in its low),
/// by the lane's own `LoadCapture` lookup (`lane_read_capture_value`): its value, or
/// `Value::DELETED` for none or an uninitialized binding, which leaves the body at the read.
/// `ArgumentsLength` of a lane body's entry function (`lane_arguments_length`): the count a
/// keeping activation kept, else the count an unmaterialized binding answers. `DELETED` where
/// the lane's own handler must read the materialized object, which the body's leave reaches.
pub(in crate::vm) unsafe extern "C" fn lane_body_arguments_length<H: Host>(_vm: u64, _residual: u64, context: u64, slot: u64) -> u64 {
    if !crate::DYNAMIC_EXECUTION_ENABLED || context == 0 { return Value::DELETED.to_bits(); }
    let cx = context as usize as *mut LaneContext<H>;
    let value = match unsafe { lane_keeping_activation(cx) } {
        Some((argc, _)) => Value::integer(i32::from(argc)),
        None => match unsafe { lane_unmaterialized_arguments(cx, slot as usize) } {
            Some((_, count)) => Value::number(count as f64),
            None => Value::DELETED,
        },
    };
    value.to_bits()
}

/// `ArgumentGet` of that binding at an integer index a keeping activation kept or an
/// unmaterialized binding holds (`lane_argument_get`); any other key leaves at the record.
pub(in crate::vm) unsafe extern "C" fn lane_body_argument_get<H: Host>(_vm: u64, _residual: u64, context: u64, slot: u64, index: u64) -> u64 {
    if !crate::DYNAMIC_EXECUTION_ENABLED || context == 0 { return Value::DELETED.to_bits(); }
    let cx = context as usize as *mut LaneContext<H>;
    let index = Value::from_bits(index);
    if let Some((argc, function)) = unsafe { lane_keeping_activation(cx) }
        && let Some(index) = index.as_int().and_then(|index| u16::try_from(index).ok()).filter(|index| *index < argc)
    {
        // SAFETY: the context's program outlives the lane run, and the keeping activation
        // holds its `argc` values after the function's registers (`lane_keep_arguments`).
        let registers = unsafe { &*(*cx).code }.function(function as usize).registers;
        return unsafe { (*cx).registers }.get(registers + index).to_bits();
    }
    match unsafe { lane_unmaterialized_arguments(cx, slot as usize) } {
        Some((values, count)) => index
            .as_int()
            .and_then(|index| usize::try_from(index).ok())
            .filter(|index| *index < count)
            // SAFETY: `values` holds `count` kept values, and the index is below it.
            .map_or(Value::DELETED, |index| unsafe { *values.add(index) })
            .to_bits(),
        None => Value::DELETED.to_bits(),
    }
}

pub(super) unsafe extern "C" fn lane_body_capture<H: Host>(_vm: u64, _residual: u64, context: u64, packed: u64) -> u64 {
    // As `lane_body_call`: static regions recover captures through their semantic operation,
    // and an ahead body has no lane context to read them from.
    if !crate::DYNAMIC_EXECUTION_ENABLED || context == 0 { return Value::DELETED.to_bits(); }
    let cx = context as usize as *mut LaneContext<H>;
    let (depth, slot) = ((packed >> u16::BITS) as u16, packed as u16);
    let value = match native_frames::innermost_callee_env(cx) {
        Some(env) => {
            let vm = unsafe { vm(cx) };
            // SAFETY: as `Vm::walked_capture_slots`; no collection runs in the lane.
            vm.walked_capture_slots(env, false, depth).and_then(|(slots, root)| vm.plain_capture(unsafe { &*slots }, root, slot).0)
        }
        None => lane_read_capture_value::<H, true>(cx, depth, slot).0,
    };
    value
        .filter(|value| value.to_bits() & crate::value::ValueLayout::TAG_MASK != crate::value::ValueLayout::INTERNAL_TAG)
        .unwrap_or(Value::DELETED)
        .to_bits()
}

/// A lane body's store of `value` to the capture `packed` names (depth in its high half,
/// slot in its low), by the lane's own stores (`lane_store_own_capture`, else
/// `lane_capture_store`): 1 where it stored, else 0, which leaves the body at the store,
/// before it.
///
/// # Safety
/// As `lane_body_capture`.
pub(super) unsafe extern "C" fn lane_body_capture_store<H: Host>(_vm: u64, _residual: u64, context: u64, packed: u64, value: u64) -> u64 {
    if !crate::DYNAMIC_EXECUTION_ENABLED || context == 0 { return 0; }
    let cx = context as usize as *mut LaneContext<H>;
    let (depth, slot, value) = ((packed >> u16::BITS) as u16, packed as u16, Value::from_bits(value));
    let stored = match native_frames::innermost_callee_env(cx) {
        Some(env) => {
            // SAFETY: the context's program outlives the lane run.
            let (code, program) = unsafe { (&*(*cx).code, (*cx).program) };
            lane_environment_store(unsafe { vm(cx) }, code, program, env, depth, slot, value)
        }
        None => (depth == 0 && lane_store_own_capture(cx, slot, value)) || lane_capture_store(cx, depth, slot, value),
    };
    u64::from(stored)
}

/// Whether a body's run that ended at `exit` counts toward its retirement and
/// reoptimization: a leave into a callee that only lacked a body while warming toward one
/// (`LaneContext::callee_warming`) does not, as the next run may find the callee's body. Only
/// a `Callee` leave reads the flag: the callee's own code may run nested bodies before the
/// leave resolves, whose other ends must not take it.
fn lane_leave_counts<H: Host>(cx: *mut LaneContext<H>, exit: super::compiled::LaneExit) -> bool {
    // SAFETY: the running lane's context, read and reset by the run that left into the callee.
    exit != super::compiled::LaneExit::Callee || !unsafe { std::mem::take(&mut (*cx).callee_warming) }
}

/// With diagnostics, counts a leave of `own`'s body into a warming callee, which
/// `lane_leave_counts` keeps from its feedback, in the view's report.
fn lane_note_warming_leave<H: Host>(cx: *mut LaneContext<H>, own: &LaneView) {
    if unsafe { vm(cx) }.programs.js_jit_diagnostics_enabled() {
        own.tier().body_stats.warming_leaves.set(own.tier().body_stats.warming_leaves.get() + 1);
    }
}

/// Where the lane continues after a run of `method`, `own`'s body, on the activation whose
/// registers are `r`: the activations of the native frames it left inside first
/// (`native_frames::advance_into_frames`), then the record its leave names in the innermost, or the
/// innermost's completion; `lane_body_left` adds the leave as feedback (`LaneMethod::feedback`).
enum LaneBodyLeft {
    /// Irreversible cancellation leaves the lane without dispatching another record.
    Terminated,
    Resume(Registers, Ip, Carried),
    /// The activation's body raised an exception (`Vm::lane_raised`) at the record: the
    /// lane unwinds from it, or the call that made the activation pops it (`lane_pop_raised`).
    Raised(Ip),
    /// The activation completes with the value, by the record.
    Completed(Ip, Value),
}



/// Records that a run of `own`'s body ended at `exit`, in the diagnostics report's leave table;
/// nothing the lane does next reads it.
#[inline(always)]
fn lane_record_end<H: Host>(cx: *mut LaneContext<H>, own: &LaneView, method: &super::compiled::LaneMethod, exit: super::compiled::LaneExit) {
    if !matches!(exit, super::compiled::LaneExit::Returned { .. }) && crate::trace::Channel::BodyLeave.on() {
        eprintln!("QUENCH_BODY_LEAVE function={} exit={exit:?}", lane_running_function(cx));
    }
    if unsafe { vm(cx) }.programs.js_jit_diagnostics_enabled() {
        own.tier().body_stats.ended(exit, &method.exits, &method.inlined, super::compiled::take_lane_exit_line());
    }
}

/// `LaneView::note_lane_body_end`, counting the retirement it makes in the VM's tier events.
#[inline(always)]
fn lane_note_body_end<H: Host>(cx: *mut LaneContext<H>, own: &LaneView, exit: super::compiled::LaneExit, left_new: impl FnOnce((Option<u32>, usize))) {
    if own.note_lane_body_end(exit, false, left_new) {
        unsafe { vm(cx) }.programs.tier_events().record(Event::Retired);
    }
}

/// Counts an entry whose body the lane could not leave inside of (`lane_body_admits`): in the VM's
/// tier events and, with diagnostics, the view's report.
#[cold]
fn lane_body_refused<H: Host>(vm: &Vm<H>, own: &LaneView) {
    vm.programs.tier_events().record(Event::Refused);
    if vm.programs.js_jit_diagnostics_enabled() {
        own.tier().body_stats.refused.set(own.tier().body_stats.refused.get() + 1);
    }
}

fn lane_body_left<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    own: &LaneView,
    method: &super::compiled::LaneMethod,
    exit: super::compiled::LaneExit,
) -> (LaneBodyLeft, super::compiled::LaneExit) {
    lane_record_end(cx, own, method, exit);
    if exit == super::compiled::LaneExit::Terminated {
        // A fault can bypass the native exit's register snapshots. Discard its
        // native frames instead of materializing stale homes for guest execution.
        native_frames::discard_frames(cx);
        return (LaneBodyLeft::Terminated, exit);
    }
    let feedback = method.feedback(exit, unsafe { &*(*cx).code });
    (lane_frames_resumed(cx, r, (own, Some(method)), exit), feedback)
}

/// The activation a leave resumes in: the one the leaving body ran in for a native call's callee, else
/// the innermost frame a native-frame advance made the running one, where there is one.
fn lane_resumed_activation<'a, H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    (own, root): (&'a LaneView, Option<&'a super::compiled::LaneMethod>),
    callee: bool,
) -> (Registers, &'a LaneView, Option<&'a super::compiled::LaneMethod>) {
    if callee {
        return (r, own, root);
    }
    match native_frames::advance_into_frames(cx) {
        // SAFETY: the advance made the innermost frame the running activation.
        Some((own, method)) => (unsafe { (*cx).registers }, own, Some(method)),
        None => (r, own, root),
    }
}

/// Where the lane continues after native code of the activation with registers `r`, a body of
/// `root`'s or a region's, left with `exit`: in the innermost of the native frames it left inside, which
/// the lane links and continues in first (`native_frames::advance_into_frames`; a leave into a callee's
/// activation already linked them and went on in it), then at the record `exit` names there, or the
/// innermost's completion. `own` is the activation's view; `root` the body that ran, where one did,
/// whose inlined frames an `exit` that was not inside a native frame names.
fn lane_frames_resumed<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    (own, root): (&LaneView, Option<&super::compiled::LaneMethod>),
    exit: super::compiled::LaneExit,
) -> LaneBodyLeft {
    let callee = matches!(exit, super::compiled::LaneExit::Callee);
    let (r, own, method) = lane_resumed_activation(cx, r, (own, root), callee);
    // SAFETY: the running activation's records start at the context's base.
    let base = unsafe { (*cx).base };
    match exit.resumed() {
        // SAFETY: the record that raised is one of the activation's function.
        super::compiled::LaneExit::Threw { pc } => LaneBodyLeft::Raised(unsafe { base.add(pc) }),
        super::compiled::LaneExit::Terminated | super::compiled::LaneExit::Entry | super::compiled::LaneExit::Stub => unreachable!("termination leaves before recovery; an entry leave or an unentered call resumes at its first record"),
        super::compiled::LaneExit::At(pc) => {
            lane_body_resume_at(cx, r, own, loop_body::header_for_tier_up(cx, own, pc).unwrap_or(pc))
        }
        super::compiled::LaneExit::Inlined { frame, pc } => {
            let method = method.expect("a leave inside an inlined callee is a lane body's");
            let (registers, resume, carried) = lane_body_inlined_activation(cx, r, base, InlinedRun::of_body(method), frame, pc);
            LaneBodyLeft::Resume(registers, resume, carried)
        }
        // A native call made its callee's activation and left the lane there.
        super::compiled::LaneExit::Callee => {
            let mut carried = Carried::script(cx);
            // SAFETY: `lane_body_call` set both before the body left.
            let (registers, resume) = unsafe { ((*cx).registers, (*cx).callee_resume) };
            carried.acc = Slot::of(unsafe { (*cx).callee_acc });
            LaneBodyLeft::Resume(registers, resume, carried)
        }
        // SAFETY: the record that completes the activation is one of its function's.
        super::compiled::LaneExit::Returned { pc, value } => LaneBodyLeft::Completed(unsafe { base.add(pc) }, value),
    }
}

/// Reloads the heap bases the running body's rows read through the payload (`Vm::refresh_body_bases`), as
/// every call, construct and step helper of the body ends: the callee's run or an allocation may have
/// moved them.
///
/// # Safety
/// `context` is the running lane's.
pub(super) unsafe fn refresh_body_bases<H: Host>(context: u64) {
    let cx = context as usize as *mut LaneContext<H>;
    // SAFETY: the caller's contract.
    unsafe { vm(cx).refresh_body_bases() };
}

/// Names `payload`, the dispatch of the native loop region that runs on the activation of the lane
/// `context`, to the helpers its rows call (`lane_region_call`), and returns the one it replaces:
/// a region's calls run lane code that may enter regions of its own.
///
/// # Safety
/// `context` is the running lane's.
pub(super) unsafe fn lane_region_payload<H: Host>(context: usize, payload: usize) -> usize {
    // SAFETY: the caller's contract.
    std::mem::replace(unsafe { &mut (*(context as *mut LaneContext<H>)).region_payload }, payload)
}

/// The helper a loop region's call row runs (`LaneHelper::RegionCall`): the call at `call_pc` of the
/// activation the lane context names, whose registers the region runs on, as `lane_body_call`
/// makes it, then the heap bases the region's payload holds reloaded (`LaneContext::region_payload`)
/// besides the body frame's, which the callee's run or an allocation may have moved.
///
/// # Safety
/// `context` is the running lane's, which the region entered (`lane_region_payload`), and `call_pc` a call record of its function.
pub(super) unsafe extern "C" fn lane_region_call<H: Host>(vm: u64, residual: u64, context: u64, call_pc: u64) -> u64 {
    // SAFETY: the caller's contract.
    let status = unsafe { body_calls::lane_body_call::<H>(vm, residual, context, call_pc) };
    let cx = context as usize as *mut LaneContext<H>;
    // SAFETY: as above.
    unsafe { self::vm(cx).refresh_region_bases((*cx).region_payload, lane_direct_calls(cx)) };
    status
}

/// Leaves the lane at `record`, where the running activation's body raised the exception in
/// `Vm::lane_raised`: the general loop unwinds from there, from the frames frameless
/// activations become first (`lane_in_place`).
fn lane_raised_exit<H: Host>(cx: *mut LaneContext<H>, record: Ip) -> Ip {
    let vm = unsafe { vm(cx) };
    let (function, throw_pc) = super::compiled::raise_site_parts(vm.lane_raise_site);
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if let Some(error) = vm.lane_completion.raised_mut() { error.capture_source_location(code, function, throw_pc); }
    if let Some(settled) = raised_windows::settle_raised_window(cx, record) {
        return settled;
    }
    if !vm.lane_stack.activations.is_empty() {
        // SAFETY: `record` is one of the running function's records.
        let call_pc = unsafe { record.offset_from((*cx).base) } as usize;
        vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
        vm.materialize_deferred_lane();
    }
    exit(record)
}

/// Where the lane continues after a body left at `pc` of `own`'s function on registers `r`: in
/// the loop's published BaseJIT code where it has a resume stub for `pc` (`loop_resume`),
/// else at the record, with the accumulator that record reads.
fn lane_body_resume_at<H: Host>(cx: *mut LaneContext<H>, r: Registers, own: &LaneView, pc: usize) -> LaneBodyLeft {
    let accumulator = own.accumulator_registers.get(pc).copied().filter(|&register| register != NO_ACCUMULATOR);
    if accumulator.is_none() && let Some(left) = loop_resume::lane_loop_resume(cx, r, own, pc) {
        return left;
    }
    let mut carried = Carried::script(cx);
    if let Some(register) = accumulator {
        carried.acc = Slot::of(r.get(register));
    }
    // SAFETY: the body leaves at a PC of the function, whose records are contiguous.
    LaneBodyLeft::Resume(r, unsafe { (*cx).base.add(pc) }, carried)
}

/// Whether activating `target` leaves the running program. A target from
/// `LaneStack::script_targets` never does: `Vm::script_call_holds` admitted it for the VM's
/// active program, which is the lane's (`lane_enter_program` sets both), so the fast call
/// forms take that fact as proven (`MAY_CROSS` false) and only the general activation asks.
#[inline(always)]
fn lane_crosses<H: Host, const MAY_CROSS: bool>(cx: *mut LaneContext<H>, target: &ScriptCallTarget) -> bool {
    MAY_CROSS && target.program() != unsafe { (*cx).program }
}

/// `lane_activate` past its checks: the call passes at most `target`'s parameters, the lane
/// stack has room (`lane_activation_room`), and the call may complete its caller. Pushes
/// the activation and returns its registers and the callee's first record; it makes no
/// call, so a handler activating through it keeps its registers. Without `GENERAL` its
/// callers (the fast call forms) have sent another program's target to the general form
/// (`lane_crosses`).
#[inline(always)]
fn lane_push_activation<H: Host, const GENERAL: bool, const SETTLES: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    arguments: u16,
    this: Value,
    constructs: bool,
) -> (Registers, Ip) {
    // SAFETY: `ip` is a record of the running view, whose window of `r` holds its values.
    let (passed, argc) = unsafe { (r.0.add(usize::from(arguments)).cast_const(), ImmediateLayout::argument_count((*ip).imm())) };
    lane_push_passed::<H, GENERAL, SETTLES>(cx, r, ip, target, passed, argc, this, constructs)
}

/// `lane_push_activation` of the `argc` values at `passed`, at most `target`'s parameters
/// and `FIXED_ARGUMENT_COPIES`, for the call record at `ip`; `SETTLES` for a settling
/// target's call (`Completion::SettlesPromise`).
#[inline(always)]
#[allow(clippy::too_many_arguments)]
fn lane_push_passed<H: Host, const GENERAL: bool, const SETTLES: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: *const Value,
    argc: u16,
    this: Value,
    constructs: bool,
) -> (Registers, Ip) {
    // Only `lane_script_call_settles` activates a settling target, and it says so statically,
    // so the other call forms decide the completion without reading the target's entry.
    debug_assert_eq!(SETTLES, target.settles(), "a settling target activates through its own call form");
    let callee_registers = lane_fill_window(unsafe { vm(cx) }, target, passed, argc);
    lane_enter_window::<H, GENERAL, SETTLES>(cx, r, ip, target, callee_registers, argc, this, constructs, None, None)
}

/// A plain call of `target`, of the running program, passed the `argc` values at `passed` (at
/// most its parameters) and not completing its caller, whose entry cell holds a published body
/// (`LaneView::cell_method`): the body runs on the activation's window before the activation
/// exists. The call is a leaf the context holds (`CONTEXT_LEAF`: the caller's receiver and
/// environment are the leaf's to restore), so a body that returns completes the call with the
/// caller's registers and the next record, nothing pushed and nothing to pop; a leave, and any
/// helper that observes activations (`lane_materialize_running_leaf`), make the activation the
/// push would have made, in the room the run reserved for it (`CALLEE_ACTIVATION_PENDING`),
/// and resume as the body's prologue would (`lane_body_concluded`). `None`, which changes
/// nothing, where the body does not run: the lane cannot make the activations a leave inside
/// its inlined calls would (`lane_body_admits`).
#[inline(never)]
fn lane_enter_cell_body<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: *const Value,
    argc: u16,
    this: Value,
) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the program store keeps a derived view alive with its program.
    let own = unsafe { &*target.view };
    let method = own.cell_method()?;
    // Most entries of a published body come through its cell: one of the audit's interpreted
    // epoch activates the call as the lane's own would (`lane_body_audit`).
    if own.audit_entry(false) {
        return None;
    }
    let window = lane_fill_window(vm, target, passed, argc);
    if !lane_body_admits(cx, method, CALLEE_ACTIVATION_PENDING) {
        // SAFETY: the window starts at the stack's top, which the fill moved.
        unsafe { vm.lane_stack.values.set_top(window.0) };
        return None;
    }
    lane_begin_cell_leaf(cx, ip, r, target, argc, this, window);
    let run = super::compiled::BodyRun {
        method, direct_calls: lane_direct_calls(cx), program: unsafe { (*cx).program }, residual: unsafe { &*(*cx).code },
        registers: window.0, receiver: lane_entry_receiver(cx, own.binds_this()), captures: capture_reads(target.capture), lane_context: cx.cast(),
        pending: CALLEE_ACTIVATION_PENDING };
    Some(lane_cell_body_ended(cx, window, own, target.function, method, vm.run_lane_body(&run)))
}

/// Makes the call of `target` the context's running leaf (`CONTEXT_LEAF`), which holds what its
/// activation would (`lane_materialize_leaf`): the callee's receiver, environment, captures,
/// registers and records are the context's, the caller's are the leaf's; the entry is counted.
#[inline(always)]
fn lane_begin_cell_leaf<H: Host>(cx: *mut LaneContext<H>, ip: Ip, r: Registers, target: &ScriptCallTarget, argc: u16, this: Value, window: Registers) {
    unsafe { vm(cx) }.programs.record_js_jit_lane_entry(target.program(), target.function);
    unsafe { vm(cx) }.programs.tier_events().record(Event::CellCrossed);
    // SAFETY: the running lane's context, and the callee's view outlives its program.
    unsafe {
        (*cx).leaf = LeafCall {
            call: ip, form: CONTEXT_LEAF, argc, caller_registers: r, caller_base: (*cx).base, target, caller_program: None,
        };
        window.set_this(this);
        window.set_env(target.env);
        window.set_capture(target.capture);
        ((*cx).registers, (*cx).base) = (window, (*target.view).records());
    }
}

/// Where the lane continues after the body `lane_enter_cell_body` ran on `window` ended at
/// `exit`: the caller, past the call, where the body returned and the leaf still runs; else
/// the leave, in the activation made now. A helper that pushed it resolved targets since the
/// call, so the callee is `own` and `function`, not the call's target.
#[inline(always)]
fn lane_cell_body_ended<H: Host>(
    cx: *mut LaneContext<H>,
    window: Registers,
    own: &LaneView,
    function: u32,
    method: &super::compiled::LaneMethod,
    exit: super::compiled::LaneExit,
) -> Resumed {
    if let super::compiled::LaneExit::Returned { value, .. } = exit
        && !unsafe { (*cx).leaf.call }.is_null()
    {
        // SAFETY: the window held the callee's registers; the completed call leaves the stack as it found it.
        unsafe {
            (*cx).callee_warming = false;
            vm(cx).lane_stack.values.set_top(window.0);
        }
        lane_record_end(cx, own, method, exit);
        lane_note_body_end(cx, own, exit, |_| {});
        let (registers, next) = lane_complete_leaf(cx, value, CONTEXT_LEAF).expect("the leaf runs until it completes or materializes");
        return Resumed::At(registers, next, Carried::script(cx));
    }
    lane_materialize_running_leaf(cx);
    lane_body_concluded::<H>(cx, window, own.start(), own, method, exit, function)
}

/// The window of `target`'s plain activation at the lane stack's top, holding the `argc`
/// values at `passed` as its parameters, which the stack's values cover from here on.
#[inline(always)]
fn lane_fill_window<H: Host>(vm: &mut Vm<H>, target: &ScriptCallTarget, passed: *const Value, argc: u16) -> Registers {
    let count = usize::from(target.registers);
    let stack = &mut vm.lane_stack;
    // SAFETY: capacity holds the window's admitted room (`ScriptCallTarget::room`); the
    // registers live at entry are written before the length covers them, and no activation's
    // window moves. A register past `fill` is written before any instruction reads it, and
    // a collection reads it only where liveness proves it live (`RegisterRoots::entry_fill`).
    // Parameter `k` lives in register `k` of a plain activation (`Vm::place_plain_parameters`).
    unsafe {
        let registers = stack.values.top();
        fill_admitted_window(registers, usize::from(target.fill), count);
        copy_arguments(registers, passed, argc);
        stack.values.set_top(registers.add(count + lane_values::CONTEXT));
        Registers(registers)
    }
}

/// `lane_push_passed` past its window, which the stack's values cover from `window` on and
/// which holds the callee's registers: the activation, and the context made the callee's.
/// A native frame's materialization enters its window here too (`native_frames::advance_into_frames`).
#[inline(always)]
#[allow(clippy::too_many_arguments)]
fn lane_enter_window<H: Host, const GENERAL: bool, const SETTLES: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    callee_registers: Registers,
    argc: u16,
    this: Value, constructs: bool, skipped: Option<SkippedForwarder>,
    // The register of the first value a keeping activation kept past its registers
    // (`ScriptActivation::kept`), which marks it forwarding; `None` for any other.
    kept: Option<u16>,
) -> (Registers, Ip) {
    // The receiver goes to its context word first, so it holds no register past the push.
    callee_registers.set_this(this);
    let vm = unsafe { vm(cx) };
    let stack = &mut vm.lane_stack;
    // Only a plain call activates another program's callee (`Vm::resolve_script_call_target`).
    let cross = lane_crosses::<H, GENERAL>(cx, target);
    let activation = Activation {
        native: crate::vm::compiled::ShadowFrame::EMPTY, function: target.function,
        call: ip,
        caller_base: unsafe { (*cx).base },
        caller_registers: r,
        caller_program: unsafe { (*cx).program },
        kind: ActivationKind::Script(ScriptActivation {
            callee: target.callee,
            argc,
            completion: if skipped.is_some() { Completion::Forwarder } else { Completion::of(constructs, cross, SETTLES) },
            forwards: kept.is_some(),
            kept: kept.unwrap_or(0),
            environment: false,
            record: std::ptr::null_mut(),
        }),
    };
    // SAFETY: the capacity check above leaves room for the activation.
    unsafe { stack.push_activation(activation, callee_registers.0) };
    if let Some(skipped) = skipped { stack.forwarders.push(skipped); }
    // SAFETY: the program store keeps a derived view alive with its program.
    let base = unsafe { (*target.view).records() };
    unsafe {
        (*cx).registers = callee_registers;
        (*cx).base = base;
    }
    callee_registers.set_env(target.env);
    callee_registers.set_capture(target.capture);
    if cross {
        lane_enter_program(cx, target.program());
    }
    vm.programs.record_js_jit_lane_entry(target.program(), target.function);
    // A construction runs its body from the first record; the tier enters plain calls.
    let start = if constructs { base } else { unsafe { (*target.view).start() } };
    (callee_registers, start)
}

/// The frameless target of another program's function `callee` a native calls from the
/// lane (`Vm::lane_native_callback`), as a trap's (`proxy_traps::lane_trap_target`).
fn lane_cross_callback_target<H: Host>(cx: *mut LaneContext<H>, callee: Value) -> Option<(ScriptCallTarget, bool)> {
    proxy_traps::lane_trap_target(cx, callee).filter(|&(_, crosses)| crosses)
}

/// The activation of a native's call of `target` with `args` from the lane's running
/// function (`Vm::lane_native_callback`), as the lane's own call would make it from the call
/// record `call`, completing to the native (`Completion::ReturnsToNative`): by its shape
/// (`PreparedShape`), or, for a gathering target, whose rest array it makes, or a call
/// without room, which grows the stack for the general path it takes, as
/// `lane_activate_keeping` makes it. Its first record, or `None` where the lane would not
/// activate the call.
fn lane_push_callback<H: Host>(
    cx: *mut LaneContext<H>,
    call: Ip,
    target: &ScriptCallTarget,
    args: &[Value],
    this: Value,
    crosses: bool,
) -> Option<Ip> {
    debug_assert_eq!(crosses, lane_crosses::<H, true>(cx, target), "a native's lane callee crosses where its program is another");
    if !crosses {
        // SAFETY: the running lane's context, which nothing else accesses.
        let shape = PreparedShape::of(unsafe { &*cx }, call, target, args.len());
        if let Some(shape) = &shape
            && let Some(start) = lane_push_prepared(cx, &shape.activation, shape.room, &shape.entry(target, this), args)
        {
            return Some(start);
        }
    }
    let (r, arguments) = (unsafe { (*cx).registers }, ActivationArguments::Kept(args.as_ptr(), args.len()));
    let (_, start) = if crosses {
        lane_activate_keeping::<H, true>(cx, r, call, target, arguments, this, false, None).ok()?
    } else {
        lane_activate_keeping::<H, false>(cx, r, call, target, arguments, this, false, None).ok()?
    };
    let vm = unsafe { vm(cx) };
    if let Some(ActivationKind::Script(script)) = vm.lane_stack.activations.last_mut().map(|activation| &mut activation.kind) {
        script.completion = Completion::ReturnsToNative;
    }
    Some(start)
}

/// Writes the `passed` values into the window's locals at `local`: each of the first `bound` as
/// its parameter's local, and every one after the `locals`, as the value a frame keeps for legacy
/// reflection.
///
/// # Safety
/// `local` starts room for the `locals` and the `passed` values after them.
unsafe fn write_window_arguments(local: *mut Value, locals: usize, passed: &[Value], bound: usize) {
    // SAFETY: the caller's contract.
    unsafe {
        for (slot, &value) in passed.iter().enumerate() {
            if slot < bound {
                local.add(slot).write(value);
            }
            local.add(locals + slot).write(value);
        }
    }
}

/// `lane_activate` of an environment target (`CallEntry::Environment`): its window holds
/// its registers, then its environment, made now as the frame's promotion would make it
/// (each captured slot its parameter's argument or `undefined`, every other slot owned
/// elsewhere), then its frame locals (each parameter its argument, a captured slot owned
/// by the environment, every other local `undefined`), then the values passed. The
/// environment is reachable only from the window until the lane leaves, which makes the
/// activation a frame holding it.
#[inline(always)]
fn lane_activate_environment<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    passed: &[Value],
    (this, constructs): (Value, bool),
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the running view.
    let i = unsafe { &*ip };
    // Another program's callee enters its program and completes across (`Completion::Cross`).
    let cross = target.program() != unsafe { (*cx).program };
    let Ok(argc) = u16::try_from(passed.len()) else {
        return Err(exit(ip));
    };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if returns && !lane_returning_call_admitted(cx) {
        return Err(exit(ip));
    }
    // SAFETY: the program store keeps a derived view alive with its program, and an
    // environment target's view has a window (`ScriptCallTarget::entry`).
    let layout = unsafe { (*target.view).environment_window.unwrap_unchecked() };
    let (rest, self_binding) = (layout.rest, layout.self_binding);
    // A body reading its `arguments` keeps every value passed past its parameters too, as
    // a frame does where legacy reflection (`f.arguments`) can read them; elsewhere nothing
    // observes them, and the window keeps only those its parameters bind. Only a call
    // passing more values than the parameters reads the body's plan.
    let extra = argc > target.params && !rest && {
        let Some(code) = vm.programs.residual(target.program()) else {
            return Err(exit(ip));
        };
        let plan = code.function(target.function as usize).call_plan(code);
        if !plan.reads_passed_arguments && plan.legacy_reflection {
            return Err(exit(ip));
        }
        !plan.reads_passed_arguments
    };
    if vm.with_scope_entered {
        return Err(exit(ip));
    }
    let (passed, argc) = if extra { (&passed[..usize::from(target.params)], target.params) } else { (passed, argc) };
    // A rest body keeps every value passed, the room sized for its parameters and the rest.
    let extra = usize::from(argc.saturating_sub(target.params));
    if vm.lane_stack.activations.len() >= vm.lane_stack.activation_limit.get()
        || vm.lane_stack.values.room()
            < usize::from(target.room) + extra
    {
        return Err(lane_script_call_frame::<H>(ip, usize::from(target.room) + extra));
    }
    // The rest array, made before the window is: the values past the other parameters,
    // which the rest parameter's local holds (`lane_activate_keeping` gathers likewise).
    // A plain branch: `bool::then` with this closure stayed an out-of-line call on every
    // activation.
    let gathered = if rest {
        let fixed = usize::from(target.params) - 1;
        Some(vm.rest_parameter_array(passed.get(fixed..).unwrap_or_default()))
    } else {
        None
    };
    let count = usize::from(target.registers);
    let locals = usize::from(layout.locals);
    let stack = &mut vm.lane_stack;
    let held = count + usize::from(WINDOW_LOCALS);
    debug_assert!(fill_room::<SCRIPT_FILL_BLOCK>(held + locals) <= usize::from(target.room));
    // SAFETY: capacity holds the window (`ScriptCallTarget::room`); each slot is written
    // before the length covers it, and no activation's window moves.
    let callee_registers = unsafe {
        let registers = stack.values.top();
        // Every register live at entry (`ScriptCallTarget::fill`) and every local starts
        // `undefined` within the target's reserved room (`ScriptCallTarget::room`); the
        // metadata entries are then written, and parameter `k` local `k` with its argument
        // where one was passed. The environment is made when one is needed.
        fill_window(registers, target.entry_registers(), Value::UNDEFINED);
        fill_window(registers.add(count), held - count + locals, Value::UNDEFINED);
        let entries = registers.add(count);
        entries.add(usize::from(WINDOW_ENVIRONMENT)).write(Value::DELETED);
        entries
            .add(usize::from(WINDOW_CAPTURED))
            .write(std::mem::transmute::<u64, Value>(layout.captured));
        let storage = crate::heap::EnvironmentSlots::lay_out_in_place(entries.add(usize::from(WINDOW_STORAGE)), locals);
        entries
            .add(usize::from(WINDOW_SLOTS))
            .write(std::mem::transmute::<u64, Value>(storage as u64));
        let local = registers.add(held);
        // The few values a call passes are copied in place: one pass writes each as its
        // parameter's local and, after the locals, as the value a frame keeps for legacy
        // reflection, with no library copy per run.
        write_window_arguments(local, locals, passed, usize::from(argc.min(target.params)));
        if let Some(gathered) = gathered {
            local.add(usize::from(target.params) - 1).write(gathered);
        }
        if let Some(slot) = self_binding {
            local.add(usize::from(slot)).write(target.callee);
        }
        stack.values.set_top(registers.add(held + locals + usize::from(argc) + lane_values::CONTEXT));
        Registers(registers)
    };
    let activation = Activation {
        native: crate::vm::compiled::ShadowFrame::EMPTY, function: target.function,
        call: ip,
        caller_base: unsafe { (*cx).base },
        caller_registers: r,
        caller_program: unsafe { (*cx).program },
        kind: ActivationKind::Script(ScriptActivation {
            callee: target.callee,
            argc,
            completion: Completion::of(constructs, cross, false),
            forwards: false,
            kept: 0,
            environment: true,
            record: std::ptr::null_mut(),
        }),
    };
    // SAFETY: the capacity check above leaves room for the activation.
    unsafe { stack.push_activation(activation, callee_registers.0) };
    // SAFETY: the program store keeps a derived view alive with its program.
    let base = unsafe { (*target.view).records() };
    unsafe {
        (*cx).registers = callee_registers;
        (*cx).base = base;
    }
    callee_registers.set_env(target.env);
    callee_registers.set_capture(target.capture);
    callee_registers.set_this(this);
    if cross {
        lane_enter_program(cx, target.program());
    }
    vm.programs.record_js_jit_lane_entry(target.program(), target.function);
    Ok((callee_registers, base))
}

/// The environment of the environment window whose entries start at `entries`
/// (`WINDOW_ENVIRONMENT`): the one already made, or a new environment of `function` of
/// `program` under `parent` that takes over the slots the window held in place, its
/// captured ones from the locals, which then hold `DELETED` for them as a frame's do. The
/// window reaches the new storage from then on. The environment binds the activation's
/// `this`, where its closures' arrows find it (`Vm::captured_lexical_this`), as a frame's
/// promotion carries its bindings; an arrow's own `this` is that same lexical value. The
/// environment of a window over a record also takes over the activation's dynamic `bindings`
/// (`FrameRecord::dynamic_bindings`, `Activation::take_record_bindings`), as a frame's
/// promotion takes its own (`Vm::promote_frame_environment`); any other passes none.
///
/// # Safety
/// `entries` starts the entries of a live environment window (`lane_activate_environment`).
unsafe fn window_environment<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    entries: *mut Value,
    function: u32,
    parent: Value,
    program: ProgramId,
    this: Value,
    bindings: Option<Vec<(crate::bytecode::Atom, Value)>>,
) -> Value {
    // SAFETY: as the caller guarantees.
    unsafe {
        let made = *entries.add(usize::from(WINDOW_ENVIRONMENT));
        if !made.is_deleted() {
            return made;
        }
        let slots = window_slots_taken(entries);
        // A non-arrow binds its `this` where its closures' arrows find it
        // (`Vm::captured_lexical_this`), as a frame does when a closure or the body itself
        // can observe its implicit bindings (`Function::activation_bindings_observable`);
        // any other scope names only its program, which needs no allocation.
        let mut bindings = bindings.unwrap_or_default();
        let body = code.function(function as usize);
        if !body.is_arrow && body.activation_bindings_observable(code) && body.maker_bindings_read(code) {
            bindings.insert(0, (vm.runtime_atoms.lexical_this, this));
        }
        let scope = window_scope_ref(program, bindings);
        let (environment, storage) = vm.heap.alloc_environment(parent, function, slots, scope);
        // Its storage links to its parent's for its closures' outer captures
        // (`EnvironmentSlots::link`), as a capture walk would find the parent's.
        if let Some(crate::heap::EnvironmentRecord { function: owner, slots: parent_slots, .. }) = vm.heap.environment(parent)
            && *owner != u32::MAX
            && *owner != super::ROOT_FUNCTION_ID
            && let Some(parent_storage) = parent_slots.dense_storage()
            && let Some(own) = (*storage).dense_storage()
        {
            crate::heap::EnvironmentSlots::link(own, parent_storage, vm.heap.collection_epoch());
        }
        entries.add(usize::from(WINDOW_ENVIRONMENT)).write(environment);
        entries
            .add(usize::from(WINDOW_SLOTS))
            .write(std::mem::transmute::<u64, Value>(storage as u64));
        environment
    }
}

/// The slots of an environment made from the window whose entries are `entries`: the locals a
/// closure captured, each cleared in the window, which the environment owns from then on.
///
/// # Safety
/// `entries` starts the entries of a live environment window (`lane_activate_environment`).
unsafe fn window_slots_taken(entries: *mut Value) -> crate::heap::EnvironmentSlots {
    // SAFETY: as the caller guarantees.
    unsafe {
        let captured = std::mem::transmute::<Value, u64>(*entries.add(usize::from(WINDOW_CAPTURED)));
        let in_place = &*(std::mem::transmute::<Value, u64>(*entries.add(usize::from(WINDOW_SLOTS)))
            as *const crate::heap::EnvironmentSlots);
        let locals = entries.add(usize::from(WINDOW_LOCALS));
        let window = EnvironmentWindow { locals: in_place.len() as u16, captured, rest: false, self_binding: None };
        // SAFETY: the mask names locals of the window, which hold owned values.
        let slots = crate::heap::EnvironmentSlots::from_captured(in_place.len(), window.captured, locals);
        // Each captured local, one per bit of the mask, which names no slot past the locals.
        debug_assert_eq!(captured.checked_shr(u32::from(window.locals)).unwrap_or(0), 0);
        let mut remaining = captured;
        while remaining != 0 {
            locals.add(remaining.trailing_zeros() as usize).write(Value::DELETED);
            remaining &= remaining - 1;
        }
        slots
    }
}

/// The scope of a window's environment: its program's alone, which needs no allocation, or
/// holding the dynamic `bindings` it takes over.
fn window_scope_ref(program: ProgramId, bindings: Vec<(crate::bytecode::Atom, Value)>) -> crate::heap::EnvironmentScopeRef {
    if bindings.is_empty() {
        return crate::heap::EnvironmentScopeRef::of_program(program.raw());
    }
    crate::heap::EnvironmentScopeRef::new(crate::heap::EnvironmentScope {
        program: Some(program.raw()),
        root_eval_scope: false,
        binding_site_pc: None,
        dynamic_bindings: bindings.into(),
        with_objects: Box::default(),
    })
}

/// The body of [[Construct]] for a constructor that only stores its parameters into fields
/// of `this` (`ScriptCallTarget::initializes`): its receiver
/// (`Vm::inline_construct_receiver`), and whether every store was a cached add
/// (`Vm::primary_field_add_hit`), which runs no guest code, so the body completed. After a
/// miss the constructor activates on the receiver: its body repeats the stores made so far
/// as stores of the same values to the own data properties they added, which leaves the
/// object as one activation would. A body whose adds all hit leaves its `ConstructPlan`,
/// with which a later construct allocates the finished object at once
/// (`lane_planned_construction`), which comes first. Out of line, so the construct keeps
/// its tail dispatch.
#[inline(never)]
fn lane_initialize_fields<H: Host>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    callee: Value,
    constructor: Value,
    function: u32,
    argument: impl Fn(u16) -> Value,
) -> Option<(Value, bool)> {
    let stores = code.function(function as usize).initializer_stores(&code.constants)?;
    lane_initialize_stores(vm, callee, constructor, |vm, this, each| {
        lane_add_stores(vm, code, this, stores, argument, |_, _| None, each)
    })
}

/// The receiver `Vm::inline_construct_receiver` allocates for a constructor that forwards its
/// arguments (`lane_script_construct_keeping`): from `callee`'s holding plan `plan` where it
/// has no fields, else from the template, which leaves that plan. `lane_script_construct` sends a
/// forwarding target here before it tests `ScriptCallTarget::initializes`, so a callee's plan
/// is only ever this one or `lane_initialize_fields`'s.
fn lane_planned_receiver<H: Host>(
    vm: &mut Vm<H>,
    callee: Value,
    plan: Option<&ConstructPlan>,
) -> Option<Value> {
    if let Some(plan) = plan.filter(|plan| plan.fields == 0) {
        return Some(plan.allocate(&mut vm.heap, |_| Value::UNDEFINED));
    }
    let template = vm.inline_construct_template(callee)?;
    let (prototype, shape) = (template.proto(), template.shape());
    let this = vm.heap.alloc_object(template);
    if let Some(index) = construct_plan_index(callee)
        && let Some(callee_layout) = vm.function_prototype_layout(callee)
    {
        vm.lane_stack.construct_plans[index] = ConstructPlan {
            callee,
            callee_layout,
            prototype,
            shape,
            kind: ConstructPlanKind::Forwarding,
            ..EMPTY_CONSTRUCT_PLAN
        }
        .finish();
        watch_construct_plan(vm, index, true, &[callee, prototype]);
    }
    Some(this)
}

/// `lane_activate` for a target that keeps its passed values, or for values a forwarding
/// activation or frame kept: the activation's registers and the callee's first record, or
/// the record to continue at when the call takes the general path. Out of line, so the
/// common activation keeps its code. Without `MAY_CROSS` its callers route the running
/// program's targets, as every path but a plain call's makes them (`lane_script_target`),
/// so it takes that fact as proven.
#[inline(never)]
#[allow(clippy::too_many_arguments)]
fn lane_activate_keeping<H: Host, const MAY_CROSS: bool>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    target: &ScriptCallTarget,
    arguments: ActivationArguments,
    this: Value,
    constructs: bool,
    forwarder: Option<SkippedForwarder>,
) -> Result<(Registers, Ip), Ip> {
    let vm = unsafe { vm(cx) };
    // SAFETY: `ip` is a record of the running view.
    let i = unsafe { &*ip };
    // A plain call passed more values than its parameters activates another program's callee
    // here too (`lane_activate`).
    let cross = lane_crosses::<H, MAY_CROSS>(cx, target);
    debug_assert!(!(cross && forwarder.is_some()));
    let argc = match arguments {
        ActivationArguments::Window(_) => usize::from(ImmediateLayout::argument_count(i.imm())),
        ActivationArguments::Kept(_, count) => count,
    };
    #[cfg(feature = "profile-lane-exits")]
    if let Some(body) = vm.programs.residual(target.program()).and_then(|code| {
        let body = code.function_get(target.function as usize)?;
        let plan = body.call_plan(code);
        Some(format!(
            "keeping {} @{:?} entry={} argc={argc} params={} strict={} legacy={} forwards={} arguments={}",
            body.name.map(|atom| code.atoms[atom as usize].to_string()).unwrap_or_default(),
            body.source_span.map(|span| span.start), target.entry as u8, target.params, body.strict,
            plan.legacy_reflection, plan.forwards_arguments, body.arguments_slot.is_some(),
        ))
    }) {
        super::lane_exits::record_detail(body);
    }
    let count = usize::from(target.registers);
    // A forwarding activation keeps every value passed after its registers, as does one for
    // a skipped forwarding constructor, whose frame passed them on, and one passed more values
    // than it has parameters.
    // A rest body keeps nothing its rest array holds, unless a kept `arguments` or legacy
    // reflection reads them (`TARGET_GATHERS_KEEPING`).
    let gathers = target.entry == CallEntry::Gathers;
    let keeps = forwarder.is_some()
        || if gathers {
            target.forms & TARGET_GATHERS_KEEPING != 0
        } else {
            target.forwards() || argc > usize::from(target.params)
        };
    let window_size = if keeps { count + argc } else { count };
    // The rest array, made before the window is: the values past the other parameters, read
    // in place from the caller's window or the kept values.
    // A rest view that keeps the values reads them in place (`LaneFrame::rest_view`).
    let rest = (gathers && !(keeps && target.forms & TARGET_REST_VIEW != 0)).then(|| {
        let fixed = usize::from(target.params) - 1;
        let passed: &[Value] = match arguments {
            // SAFETY: the window holds `argc` registers of the caller.
            ActivationArguments::Window(base) => unsafe { std::slice::from_raw_parts(r.0.add(usize::from(base)), argc) },
            // SAFETY: kept values hold `argc` values.
            ActivationArguments::Kept(values, _) => unsafe { std::slice::from_raw_parts(values, argc) },
        };
        vm.rest_parameter_array(passed.get(fixed..).unwrap_or_default())
    });
    // A call that returns its callee's completion completes its caller too, which only an
    // activation's return does in the lane. A host permitting proper tail calls
    // sends strict terminal calls to the general dispatch path instead.
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if returns && !lane_returning_call_admitted(cx) {
        return Err(exit(ip));
    }
    if argc > usize::from(u16::MAX)
        || vm.with_scope_entered
    {
        return Err(exit(ip));
    }
    // Capacity, the guest-call budget and a due collection (`LaneStack::activation_limit`).
    if vm.lane_stack.activations.len() >= vm.lane_stack.activation_limit.get()
        || vm.lane_stack.values.room()
            < fill_room::<ACTIVATION_FILL_BLOCK>(window_size)
    {
        return Err(lane_script_call_frame::<H>(ip, fill_room::<ACTIVATION_FILL_BLOCK>(window_size)));
    }
    let stack = &mut vm.lane_stack;
    // SAFETY: capacity holds the window; each slot is written before the length covers
    // it, and no activation's window moves. Parameter `k` lives in register `k` of a
    // plain activation (`Vm::place_plain_parameters`).
    let callee_registers = unsafe {
        let registers = stack.values.top();
        fill_window(registers, count, Value::UNDEFINED);
        match arguments {
            ActivationArguments::Window(base) => {
                for index in 0..argc.min(usize::from(target.params)) {
                    registers.add(index).write(r.get(base + index as u16));
                }
            }
            ActivationArguments::Kept(values, _) => {
                lane_place_kept(registers, values, argc, usize::from(target.params));
            }
        }
        if keeps {
            lane_keep_arguments(registers.add(count), r, arguments, argc);
        }
        // A rest view's register holds `undefined`: its reads take the kept values.
        if gathers {
            registers.add(usize::from(target.params) - 1).write(rest.unwrap_or(Value::UNDEFINED));
        }
        stack.values.set_top(registers.add(window_size + lane_values::CONTEXT));
        Registers(registers)
    };
    let activation = Activation {
        native: crate::vm::compiled::ShadowFrame::EMPTY, function: target.function,
        call: ip,
        caller_base: unsafe { (*cx).base },
        caller_registers: r,
        caller_program: unsafe { (*cx).program },
        kind: ActivationKind::Script(ScriptActivation {
            callee: target.callee,
            // An activation keeping nothing passed its parameters alone, which its window holds
            // (a rest body's rest array among them): its materialization reads them there.
            argc: if keeps { argc } else { argc.min(usize::from(target.params)) } as u16,
            completion: if forwarder.is_some() {
                Completion::Forwarder
            } else {
                Completion::of(constructs, cross, false)
            },
            forwards: keeps,
            kept: if keeps { target.registers } else { 0 },
            environment: false,
            record: std::ptr::null_mut(),
        }),
    };
    // SAFETY: the capacity check above leaves room for the activation.
    unsafe { stack.push_activation(activation, callee_registers.0) };
    if let Some(forwarder) = forwarder {
        stack.forwarders.push(forwarder);
    }
    // SAFETY: the program store keeps a derived view alive with its program.
    let base = unsafe { (*target.view).records() };
    unsafe {
        (*cx).registers = callee_registers;
        (*cx).base = base;
    }
    callee_registers.set_env(target.env);
    callee_registers.set_capture(target.capture);
    callee_registers.set_this(this);
    if cross {
        lane_enter_program(cx, target.program());
    }
    vm.programs.record_js_jit_lane_entry(target.program(), target.function);
    let start = if constructs { base } else { unsafe { (*target.view).start() } };
    Ok((callee_registers, start))
}

/// Place kept values in a frameless activation's parameter registers.
///
/// # Safety
/// `registers` holds `params` writable registers and `values` holds `argc` values.
#[cold]
#[inline(never)]
unsafe fn lane_place_kept(registers: *mut Value, values: *const Value, argc: usize, params: usize) {
    for index in 0..argc.min(params) {
        unsafe { registers.add(index).write(*values.add(index)) };
    }
}

/// Keep a forwarding activation's passed values after its registers.
///
/// # Safety
/// `kept` holds `argc` writable slots; `arguments` names `argc` readable values.
#[cold]
#[inline(never)]
unsafe fn lane_keep_arguments(
    kept: *mut Value,
    r: Registers,
    arguments: ActivationArguments,
    argc: usize,
) {
    for index in 0..argc {
        let value = match arguments {
            ActivationArguments::Window(base) => r.get(base + index as u16),
            // SAFETY: kept values lie below the new window, or in a frame, and stay put.
            ActivationArguments::Kept(values, _) => unsafe { *values.add(index) },
        };
        unsafe { kept.add(index).write(value) };
    }
}

/// A frameless call without room on the lane stack: grow the stack, then take the
/// general path, which pushes a frame. Out of line so the activation path saves no
/// registers.
#[cold]
#[inline(never)]
fn lane_script_call_frame<H: Host>(ip: Ip, room: usize) -> Ip {
    let cx = lane_context::<H>();
    let vm = unsafe { vm(cx) };
    let stack = &vm.lane_stack;
    // The callee's own room, which a function of many registers makes larger than a common
    // window: reserving less would send each of its calls at this depth here again.
    let room = room.max(LANE_SCRIPT_WINDOW);
    let full = stack.full(room);
    vm.materialize_lane_activations(cx);
    vm.lane_stack.grow(full, room);
    exit(ip)
}

/// Lane-stack room a frameless call's growth reserves at least: a common window.
const LANE_SCRIPT_WINDOW: usize = 4 * ACTIVATION_FILL_BLOCK;

/// A Wasm view's handler for `op` where it differs from a JavaScript view's: a reference call
/// enters Wasm functions and a return completes a Wasm activation; a value row (a capture
/// access, `this`) reads the context a Wasm view lacks.
fn wasm_lane_handler<H: Host>(op: Op) -> Option<Option<LaneHandler>> {
    let call = LaneHandler { handler: reference_call_handler::<H>(), produces: false };
    let ret = LaneHandler { handler: lane_return_wasm::<H>, produces: false };
    if matches!(op.staged(), Some(crate::bytecode::Decoder::Value)) {
        // A value row reads the receiver and the captures from the context, which a Wasm view lacks.
        return Some(None);
    }
    match op.class() {
        Class::Call => Some(Some(call)),
        Class::Return => Some(Some(ret)),
        _ => None,
    }
}

lane_handler! {
    /// A Wasm view's return: the Wasm activation's completion first, which a Wasm callee
    /// returns to far more often than to a script caller; any other takes
    /// `lane_return_general`'s order.
    fn lane_return_wasm<>(cx, r, ip, i, view) {
        if let Some(resumed) = lane_complete_wasm_activation(cx, r.get(i.a)) {
            resume!(cx, resumed)
        }
        sibling!(lane_return_general::<H>, r, ip, view)
    }
}

return_handler! {
    /// Return from an inline call to its caller; returning from the loop's
    /// entry frame belongs to the general loop.
    /// `LEAF` where the record is a leaf's (`LaneView::specialize_leaf_returns`).
    fn lane_return<LEAF: u8>(cx, r, ip, i, view) {
        if let Some(resumed) = lane_complete_plain_activation::<H, LEAF>(cx, r.get(i.a)) {
            resume!(cx, resumed)
        }
        sibling!(lane_return_general::<H>, r, ip, view)
    }
}

return_handler! {
    /// `LoadConst` of the register the next record, a `Return`, returns
    /// (`specialize_constant_returns`): the constant's return in one record, as `return;` and
    /// `return null;` compile. Any return past the common one writes the register and takes
    /// the `Return` record's own path.
    fn lane_return_constant<LEAF: u8>(cx, r, ip, i, view) {
        let value = i.constant();
        if let Some(resumed) = lane_complete_plain_activation::<H, LEAF>(cx, value) {
            resume!(cx, resumed)
        }
        r.set(i.a, value);
        sibling!(lane_return_general::<H>, r, following(ip), view)
    }
}

lane_handler! {
    /// `lane_return` past the common return (`lane_complete_plain_activation`): another
    /// program's activation, which a program that calls across programs returns from as
    /// often as the common return; any other completion takes `lane_return_other`. Out of
    /// line, so `lane_return` keeps its registers.
    #[inline(never)]
    fn lane_return_general<>(cx, r, ip, i, view) {
        let value = r.get(i.a);
        if let Some(resumed) = lane_complete_wasm_activation(cx, value) {
            resume!(cx, resumed)
        }
        if let Some(resumed) = lane_complete_cross_activation(cx, value) {
            resume!(cx, resumed)
        }
        if let Some(resumed) = lane_complete_array_step(cx, value) {
            resume!(cx, resumed)
        }
        if let Some(resumed) = lane_complete_returning_chain(cx, value) {
            resume!(cx, resumed)
        }
        sibling!(lane_return_other::<H>, r, ip, view)
    }
}

lane_handler! {
    /// `lane_return_general` of any other activation's completion, or the frame's return.
    #[inline(never)]
    fn lane_return_other<>(cx, r, ip, i, view) {
        if let Some(resumed) = lane_complete_returning(cx, ip, r.get(i.a)) {
            resume!(cx, resumed)
        }
        resume!(cx, lane_return_frame::<H>(r, ip))
    }
}


/// The completion `lane_return_from` expects of the activation it returns from.
#[inline(always)]
const fn returning_completion(crosses: bool, constructs: bool, settles: bool) -> Completion {
    if crosses { Completion::Cross } else if constructs { Completion::Constructs } else if settles { Completion::SettlesPromise } else { Completion::Plain }
}

/// `lane_return_plain` of the innermost activation, a script one whose call keeps its
/// result: of the caller's program (`Completion::Plain`), or, where `CROSSES`, of another
/// (`Completion::Cross`), which enters the caller's program first, or, where `CONSTRUCTS`, a
/// `new` of its program (`Completion::Constructs`), or, where `SETTLES`, a settling async
/// call (`Completion::SettlesPromise`), whose promise the value resolves and the call yields.
/// `INTO_BODY` admits a returning call too.
#[inline(always)]
fn lane_return_from<H: Host, const CROSSES: bool, const INTO_BODY: bool, const CONSTRUCTS: bool, const SETTLES: bool>(cx: *mut LaneContext<H>, mut value: Value) -> Option<(Registers, Ip)> {
    debug_assert!(unsafe { (*cx).leaf.call }.is_null(), "a leaf's own returns complete it");
    let vm = unsafe { vm(cx) };
    // A resolution that would observe the value returns it from the frame instead.
    let then = if SETTLES { lane_settled_then(vm, value)? } else { Value::UNDEFINED };
    // A construction yields its receiver, the activation's `this`, for a non-object result.
    if CONSTRUCTS && !vm.is_object_like(value) { value = unsafe { (*cx).registers }.this(); }
    let stack = &mut vm.lane_stack;
    let depth = stack.activations.len().checked_sub(1)?;
    // SAFETY: `depth` is below the length; a reference, not `last`'s `Option`, so the
    // address needs no null test.
    let top = unsafe { stack.activations.get_unchecked(depth) };
    let expected = returning_completion(CROSSES, CONSTRUCTS, SETTLES);
    let ActivationKind::Script(script) = &top.kind else { return None };
    if script.completion != expected { return None; }
    // SAFETY: the call record belongs to the caller's live view.
    let destination = unsafe { (*top.call).a };
    if !INTO_BODY && destination & crate::bytecode::RETURN_REGISTER != 0 {
        if CROSSES || CONSTRUCTS || SETTLES {
            return None;
        }
        return lane_return_chain(cx, value);
    }
    let destination = destination & crate::bytecode::REGISTER_MASK;
    let (call, caller_registers, caller_base, window) = (top.call, top.caller_registers, top.caller_base, top.window_word());
    let caller_program = top.caller_program;
    // SAFETY: a script activation holds no drop glue and no Wasm storage
    // (`Activation::frame_storage_bytes`); the values hold no drop glue.
    unsafe {
        stack.activations.discard_top();
        stack.values.release_window(window);
    }
    // A return from inside a `with` leaves its scope without an exit.
    stack.drop_with_objects_from(stack.activations.len());
    // The caller's memory view reads its program's records (`MemoryView::script`), which an
    // activation of the caller's own JavaScript program left in place.
    if CROSSES {
        lane_enter_program(cx, caller_program);
        unsafe { (*cx).memory = MemoryView::script(cx) };
    }
    debug_assert!(unsafe { (*cx).memory.bytes } == cx.cast::<u8>(), "a JavaScript run carries its context");
    unsafe { (*cx).registers = caller_registers; (*cx).base = caller_base; }
    if SETTLES { value = lane_settle_promise(cx, value, then); }
    caller_registers.set(destination, value);
    Some((caller_registers, following(call)))
}

/// `lane_return_plain` of a plain activation that returns the completion of its call, and
/// whose callers do in turn (`return f(...)`), down to the plain activation whose call takes
/// `value`: that activation's caller resumes with it, as the run's completion one activation
/// at a time (`lane_complete_plain_chain`) makes it. `None`, which changes nothing, for a run
/// another completion ends; the general completions take it.
#[inline(always)]
fn lane_return_chain<H: Host>(cx: *mut LaneContext<H>, value: Value) -> Option<(Registers, Ip)> {
    let vm = unsafe { vm(cx) };
    let stack = &mut vm.lane_stack;
    let activations: &[Activation] = &stack.activations;
    // The innermost returns its call's completion, which the caller of `lane_return_from` proved.
    let mut index = activations.len().checked_sub(1)?;
    let (outer, destination) = loop {
        index = index.checked_sub(1)?;
        let activation = &activations[index];
        let ActivationKind::Script(script) = &activation.kind else { return None };
        if script.completion != Completion::Plain {
            return None;
        }
        // SAFETY: the call record belongs to the caller's live view.
        let destination = unsafe { (*activation.call).a };
        if destination & crate::bytecode::RETURN_REGISTER == 0 {
            break (activation, destination);
        }
    };
    debug_assert!(matches!(&activations.last()?.kind, ActivationKind::Script(top) if top.completion == Completion::Plain));
    let (call, caller_registers, caller_base, window) = (outer.call, outer.caller_registers, outer.caller_base, outer.window_word());
    stack.drop_owned_from(index + 1);
    // SAFETY: script activations hold no drop glue or Wasm storage; the values hold no drop glue.
    unsafe {
        stack.activations.set_len(index);
        stack.values.release_window(window);
        (*cx).registers = caller_registers; (*cx).base = caller_base;
    }
    caller_registers.set(destination & crate::bytecode::REGISTER_MASK, value);
    Some((caller_registers, following(call)))
}

/// Complete the innermost lane activation with `value`, which the record at `ip` of that
/// activation returns, as a return from it does: its caller resumes after the call with the
/// value in the call's result register, or, for a call that returns its callee's
/// completion, completes in turn. `None` when no activation runs: the running function is a
/// VM frame.
#[inline(always)]
fn lane_complete_activation<H: Host>(cx: *mut LaneContext<H>, ip: Ip, mut value: Value) -> Option<Resumed> {
    if let Some(resumed) = lane_complete_plain_chain(cx, value) {
        return Some(resumed);
    }
    let vm = unsafe { vm(cx) };
    if let Some(Activation { kind: ActivationKind::Script(ScriptActivation { completion: Completion::ToWasm, .. }), .. }) = vm.lane_stack.activations.last() {
        return Some(lane_complete_to_wasm(cx, ip, value));
    }
    if proxy_traps::trap_result_needs_general_path(vm, vm.lane_stack.activations.last(), value) {
        return Some(Resumed::Exit(lane_frame_return(vm, ip, value)));
    }
    // A settling activation whose promise's resolution would observe the value returns it
    // from its frame, whose pending call resolves the promise (`lane_settled_then`); else the
    // `then` read here is the one its resolution uses.
    let mut then = Value::UNDEFINED;
    if settling(vm.lane_stack.activations.last()?) {
        let Some(read) = lane_settled_then(vm, value) else { return Some(Resumed::Exit(lane_frame_return(vm, ip, value))) };
        then = read;
    }
    let mut activation = vm.lane_stack.pop_activation()?;
    loop {
        let (caller_memory, this) = lane_restore_caller(cx, &activation);
        if let ActivationKind::Script(script) = &activation.kind {
            // A native's callback ends its run, whatever the native's own call record is.
            if let Some(ended) = body_calls::ends_run(cx, &activation, script.completion, this, value) {
                return Some(ended);
            }
            if script.completion == Completion::ArrayStep {
                return Some(lane_step_array_iteration(cx, &activation, value));
            }
            if script.completion.is_generator() {
                return Some(lane_generator_returned(cx, &activation, caller_memory, value));
            }
            // [[Construct]] of an ordinary constructor yields its returned object,
            // otherwise the receiver it allocated. A skipped forwarding constructor returns
            // `undefined` after the method, so its construction yields the receiver.
            // A trap of another program (`proxy_traps::lane_trap_target`) completes as a
            // trap, not as `Completion::Cross`, and leaves its program the same way.
            if script.completion.crosses() || activation.caller_program != unsafe { (*cx).program } {
                lane_enter_program(cx, activation.caller_program);
            }
            value = setters::completed_value(vm, &activation, script.completion, this, value);
            if script.completion == Completion::Forwarder {
                value = this;
                // A native frame's skipped constructor is its descriptor's, which no entry holds.
                if activation.native.callee.is_null() { vm.lane_stack.forwarders.pop(); }
            }
            if script.completion == Completion::SettlesPromise {
                value = lane_settle_promise(cx, value, then);
            }
        } else if let ActivationKind::WasmEntry { result, .. } = activation.kind {
            // The export's caller runs its own program again, as the run's JavaScript.
            lane_enter_program(cx, activation.caller_program);
            unsafe {
                (*cx).inline_calls = false;
                (*cx).script_calls = true;
                (*cx).instance = Value::DELETED;
            }
            value = vm.wasm_export_result(value, result);
        }
        // SAFETY: the call record belongs to the caller's live view.
        if unsafe { (*activation.call).a } & crate::bytecode::RETURN_REGISTER == 0 {
            return Some(lane_resume_after_call(&activation, caller_memory, value));
        }
        // The call returns its callee's completion: its caller completes in turn, an
        // activation here or the frame in the general loop, which the exit hands it to.
        if lane_caller_returns_in_frame(vm, value, &mut then) {
            return Some(Resumed::Exit(lane_frame_return(vm, activation.call, value)));
        }
        activation = vm.lane_stack.pop_activation().expect("the caller activation is the innermost");
    }
}

/// The return with `value` of the innermost activation, a JavaScript import's callee
/// (`Completion::ToWasm`): its Wasm caller resumes after the call with the value's Wasm form,
/// in its own program, instance and memory, which the callee may have grown. A value whose
/// conversion could run guest code or throw returns from the callee's frame, whose pending
/// call converts it (`CallCompletion::ToWasm`).
#[inline(never)]
fn lane_complete_to_wasm<H: Host>(cx: *mut LaneContext<H>, ip: Ip, value: Value) -> Resumed {
    let vm = unsafe { vm(cx) };
    let call = *vm.lane_stack.to_wasm.last().expect("an import activation has its entry");
    let encoded = match call.result {
        None => Some(Value::UNDEFINED),
        Some(crate::WasmType::I32) => value.as_number().map(|number| Value::integer(crate::value::number_to_i32(number))),
        Some(crate::WasmType::F32) => value.as_number().map(|number| Value::integer((number as f32).to_bits() as i32)),
        Some(crate::WasmType::F64) => value.as_number().map(|number| vm.encode_bits64(number.to_bits())),
        Some(_) => None,
    };
    let Some(encoded) = encoded else {
        return Resumed::Exit(lane_frame_return(vm, ip, value));
    };
    vm.lane_stack.to_wasm.pop();
    let activation = vm.lane_stack.pop_activation().expect("the import's activation is the innermost");
    lane_restore_caller(cx, &activation);
    lane_enter_program(cx, activation.caller_program);
    let memory = match call.memory {
        Some(binding) => {
            let fresh = memory_view(vm, binding);
            unsafe { (*cx).resolved = (binding, fresh) };
            fresh
        }
        None => MemoryView::NONE,
    };
    unsafe {
        (*cx).inline_calls = true;
        (*cx).script_calls = false;
        (*cx).instance = call.instance;
        (*cx).memory = memory;
    }
    lane_resume_after_call(&activation, memory, encoded)
}

/// The return of the innermost activation, a Wasm one whose call keeps its result: its
/// caller, Wasm, or JavaScript for an export's activation (`ActivationKind::WasmEntry`),
/// resumes after the call with `value`, in its JavaScript form for an export. `None`, which
/// changes nothing, leaves any other return to the general completions.
#[inline(always)]
fn lane_complete_wasm_activation<H: Host>(cx: *mut LaneContext<H>, mut value: Value) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    let top = vm.lane_stack.activations.last()?;
    if matches!(top.kind, ActivationKind::Script(_))
        // SAFETY: the call record belongs to the caller's live view.
        || unsafe { (*top.call).a } & crate::bytecode::RETURN_REGISTER != 0
    {
        return None;
    }
    let activation = vm.lane_stack.pop_activation()?;
    let (caller_memory, _) = lane_restore_caller(cx, &activation);
    if let ActivationKind::WasmEntry { result, .. } = activation.kind {
        // The export's caller runs its own program again, as the run's JavaScript.
        lane_enter_program(cx, activation.caller_program);
        unsafe {
            (*cx).inline_calls = false;
            (*cx).script_calls = true;
            (*cx).instance = Value::DELETED;
        }
        value = vm.wasm_export_result(value, result);
    }
    Some(lane_resume_after_call(&activation, caller_memory, value))
}

/// The value-producing records that may return their result from the frame
/// (`lane_returns`), as `lane_returning` parameters.
const RETURNING_FIELD: u8 = 0;
const RETURNING_UNARY: u8 = 1;
const RETURNING_BINARY: u8 = 2;
const RETURNING_OBJECT: u8 = 3;
const RETURNING_LITERAL: u8 = 4;
/// A `RETURNING_FIELD` read of a register or `this` at a site that reads neither `name` nor
/// `length`: the site's primary own entry (`Vm::primary_own_field_hit`), installed by
/// `lane_returning_field_first`.
const RETURNING_FIELD_OWN: u8 = 5;
/// `RETURNING_FIELD_OWN` at a site past one shape (`Vm::polymorphic_field_hit`).
const RETURNING_FIELD_POLYMORPHIC: u8 = 6;
/// `RETURNING_FIELD_OWN` at a site whose primary entry names a prototype holder
/// (`Vm::primary_holder_field_hit`).
const RETURNING_FIELD_HOLDER: u8 = 7;
/// `RETURNING_FIELD_OWN` at a site with an inherited entry (`Vm::inherited_field_hit`).
const RETURNING_FIELD_INHERITED: u8 = 8;
/// `RETURNING_FIELD` of a nested site whose steps hit primary own entries
/// (`lane_nested_own_value`).
const RETURNING_FIELD_NESTED: u8 = 9;
/// A returning `MakeObjectLiteral` (`return { ... }`): the literal `lane_make_object_literal`
/// makes, returned from the frame.
const RETURNING_OBJECT_LITERAL: u8 = 10;
/// `RETURNING_FIELD` of a private name of a register or `this`: the site's private field
/// (`lane_private_field_value`); a method, accessor or missing field takes `RETURNING_FIELD`.
const RETURNING_FIELD_PRIVATE: u8 = 11;
/// `RETURNING_FIELD` at a site whose reads met a getter (`FieldSiteTier::Getter`): the getter
/// activation first, as `lane_get_field_getter` makes it, so no cached data probe precedes it.
const RETURNING_FIELD_GETTER: u8 = 12;

/// The cached read of a single-base returning `GetField` of `KIND` (`RETURNING_FIELD_OWN`,
/// `_POLYMORPHIC`, `_HOLDER`, `_INHERITED`) at `cache`: a hit, which runs no guest code.
#[inline(always)]
fn returning_field_hit<H: Host, const KIND: u8>(
    vm: &mut Vm<H>,
    code: &ResidualProgram,
    object: Value,
    cache: u16,
) -> Option<Value> {
    match KIND {
        RETURNING_FIELD_OWN => vm.primary_own_field_hit(code, object, cache),
        RETURNING_FIELD_POLYMORPHIC => vm.inline_polymorphic_field_hit(code, object, cache),
        RETURNING_FIELD_HOLDER => vm.primary_holder_field_hit(code, object, cache),
        _ => vm.inherited_field_hit(code, object, cache),
    }
}

/// The value a frameless read target (`CallEntry::reads`, `CallEntry::ForwardsRead`)
/// returns for a call passing `arguments.get(k)` as parameter `k` (`None` where not passed) on
/// `this`, where the reads its records have quickened to hit. Answering it at the call
/// leaves nothing for an activation to observe: each hit runs no guest code and allocates
/// nothing. `None` for any other record state or a miss, which the call activates to run.
///
/// # Safety
/// `cx` is the running lane's context and `target` a target of its program.
#[inline(always)]
unsafe fn lane_call_read<H: Host>(
    cx: *mut LaneContext<H>,
    target: &ScriptCallTarget,
    arguments: ReadArguments,
    this: Value,
) -> Option<Value> {
    // SAFETY: the context's program outlives the lane run.
    let (vm, code) = unsafe { (vm(cx), &*(*cx).code) };
    // A forwarding body's answer is its method's leaf read on the field it reads, so both
    // kinds reach one leaf read, which the call handler then holds once.
    let (target, arguments, this) = if target.entry == CallEntry::ForwardsRead {
        // SAFETY: as for `ForwardRead::of`.
        let (callee, receiver) = unsafe { ForwardRead::of::<H>(target) }?.method(vm, code, arguments, this)?;
        // SAFETY: as `Vm::script_call_entry`; a read resolves no target and collects nothing.
        let inner = unsafe { &*vm.script_call_entry(callee)? };
        if !inner.entry.reads() {
            return None;
        }
        let inner_this = lane_direct_call_this(vm, inner, receiver)?;
        // The call passes the parameters in order, so its argument `k` is parameter `k`.
        (inner, arguments.within(target.params), inner_this)
    } else {
        (target, arguments, this)
    };
    match target.entry {
        // The receiver the call binds (`lane_direct_call_this`), which is what it returns.
        CallEntry::ReadsThis => Some(this),
        // SAFETY: a capture-read target of the running program.
        CallEntry::ReadsCapture => unsafe { lane_read_capture(vm, target) },
        // SAFETY: as for `LeafRead::of`.
        _ => unsafe { LeafRead::of::<H>(target) }?.run(vm, code, arguments, this),
    }
}

/// The capture a `CallEntry::ReadsCapture` target's closure environment holds, read as its
/// frameless activation's `LoadCapture` would (`lane_load_capture_walk`); an uninitialized
/// binding misses.
///
/// # Safety
/// `target` is a `CallEntry::ReadsCapture` target of the running program, whose view holds
/// its `LoadCapture` record first.
#[inline(never)]
unsafe fn lane_read_capture<H: Host>(vm: &mut Vm<H>, target: &ScriptCallTarget) -> Option<Value> {
    // SAFETY: the program store keeps a derived view alive with its program.
    let imm = unsafe { &*(*target.view).records() }.imm();
    let (depth, slot) = (ImmediateLayout::capture_depth(imm), ImmediateLayout::capture_slot(imm));
    let slots = capture_reads(target.capture);
    if depth == 0 && !slots.is_null() {
        // SAFETY: as `ScriptCallTarget::capture`.
        return unsafe { crate::heap::EnvironmentSlots::read_storage(slots, slot) };
    }
    let (slots, root) = vm.walked_capture_slots(target.env, false, depth)?;
    // SAFETY: as `Vm::walked_capture_slots`; no collection runs in the lane.
    vm.owned_capture(unsafe { &*slots }, root, slot)
}

/// The values a call that a read answers passed (`lane_call_read`): parameter `k` is the
/// call window's register `base + k` while `k < passed`, else unpassed. A concrete value,
/// not a closure, so the reads it feeds are one copy whatever forwarded them.
/// `lane_call_read` of the call at `site`, memoized when it answers (`lane_note_read`). Out
/// of line: the read's calls take stack temporaries, which a handler inlining them would hold
/// on its common path.
///
/// # Safety
/// As `lane_call_read`.
#[inline(never)]
unsafe fn lane_answered_call<H: Host>(
    cx: *mut LaneContext<H>,
    site: Ip,
    target: &ScriptCallTarget,
    arguments: ReadArguments,
    this: Value,
) -> Option<Value> {
    // SAFETY: the caller's contract.
    let value = unsafe { lane_read_answer(cx, target, arguments, this) };
    // A mutating operation must never enter the pure read memo.
    if value.is_some() && target.entry != CallEntry::AppendsCapture {
        lane_note_read(cx, site, target, arguments, this);
    }
    value
}

/// The value `target`'s read answers a call with, or what a capture append returns, without the
/// site's memo: what a call whose record has no memo form (a method call's) is answered by.
///
/// # Safety
/// As `lane_call_read`.
#[inline(always)]
unsafe fn lane_read_answer<H: Host>(
    cx: *mut LaneContext<H>,
    target: &ScriptCallTarget,
    arguments: ReadArguments,
    this: Value,
) -> Option<Value> {
    if target.entry == CallEntry::AppendsCapture {
        return unsafe { capture_append::run(cx, target, arguments) };
    }
    unsafe { lane_call_read(cx, target, arguments, this) }
}

/// Passed arguments stay in the call window; missing parameters read as absent.
#[derive(Clone, Copy)]
struct ReadArguments {
    registers: Registers,
    base: u16,
    passed: u16,
}

impl ReadArguments {
    /// A call that passes nothing, as `[[Get]]` calls a getter: `get` reads no register.
    const NONE: Self = Self { registers: Registers(std::ptr::null_mut()), base: 0, passed: 0 };

    #[inline(always)]
    fn get(self, parameter: u16) -> Option<Value> {
        (parameter < self.passed).then(|| self.registers.get(self.base + parameter))
    }

    /// The arguments a body of `params` parameters passes on in order.
    #[inline(always)]
    fn within(self, params: u16) -> Self {
        Self { passed: self.passed.min(params), ..self }
    }
}

/// The hit a field record of a read body answers with: its quickened primary entry, own or
/// held by a record prototype (`own_formed_handler`, `lane_get_field_holder`). Each hit is
/// its cache's own validated read, whatever the record's state when it runs.
#[derive(Clone, Copy)]
enum FieldHit {
    Own(u16),
    Holder(u16),
}

/// Every bound own-field read (`own_formed_handler`), of `this` and of a register.
fn own_bound_handlers<H: Host>() -> [*const (); 18] {
    macro_rules! row { ($site:expr) => { lane_row::<H, FIELD_LEAF_READ, ACC_NONE, { $site }> as *const () } }
    own_sites!(row)
}

impl FieldHit {
    /// The hit `record`'s quickened handler names; `None` for any other record state.
    #[inline(always)]
    fn of<H: Host>(record: &LaneInstruction) -> Option<Self> {
        let handler = record.handler;
        if own_bound_handlers::<H>().contains(&handler)
            || math_field_call_handlers::<H>().contains(&handler)
        {
            Some(Self::Own(record.c))
        } else if handler == lane_row::<H, FIELD_LEAF_READ, ACC_NONE, HELD_SITE_THIS> as *const ()
            || handler == lane_row::<H, FIELD_LEAF_READ, ACC_NONE, HELD_SITE_REGISTER> as *const ()
        {
            Some(Self::Holder(record.c))
        } else {
            None
        }
    }

    /// The hit on `object`; `None` for a miss.
    #[inline(always)]
    fn run<H: Host>(self, vm: &mut Vm<H>, code: &ResidualProgram, object: Value) -> Option<Value> {
        match self {
            Self::Own(cache) => vm.primary_own_field_hit(code, object, cache),
            Self::Holder(cache) => vm.primary_record_holder_field_hit(code, object, cache),
        }
    }
}

/// The read a `CallEntry::reads` body answers with, by the state its records quickened to.
#[derive(Clone, Copy)]
enum LeafRead {
    /// Its returning `GetField` (`lane_returning` of `kind`) on the object `base` names: the
    /// kind's hit (`returning_field_hit`), or for a holder a record prototype's method read
    /// with no call.
    Field { base: u16, kind: u8, cache: u16 },
    /// Its nested own read (`nested_own_field_hit`) of field site `site`.
    Nested { site: u32 },
    /// Its field record's hit, then the dense element the parameter `index` names.
    Element { base: u16, field: FieldHit, index: u16 },
    /// Its returning private field read (`RETURNING_FIELD_PRIVATE`) of `atom` at its record
    /// `site`, under the home the callee's environment `environment` finds.
    Private { base: u16, atom: crate::bytecode::Atom, site: usize, environment: Value, function: u32 },
}

impl LeafRead {
    /// The read `target`'s records answer with now; `None` for a record state no read hits.
    ///
    /// # Safety
    /// `target` is a `CallEntry::reads` target of the running program, whose view holds its
    /// returning record first and, for an element read, its `GetIndex` record after it.
    #[inline(always)]
    unsafe fn of<H: Host>(target: &ScriptCallTarget) -> Option<Self> {
        // SAFETY: the program store keeps a derived view alive with its program.
        let entry = unsafe { &*(*target.view).records() };
        if target.entry == CallEntry::ReadsElement {
            // SAFETY: as the function's contract.
            let element = unsafe { &*(*target.view).records().add(1) };
            return Some(Self::Element { base: entry.b, field: FieldHit::of::<H>(entry)?, index: element.c });
        }
        let handler = entry.handler;
        if handler == lane_returning::<H, RETURNING_FIELD_NESTED, NOT_LEAF> as *const () {
            return Some(Self::Nested { site: entry.imm() });
        }
        if handler == lane_returning::<H, RETURNING_FIELD_PRIVATE, NOT_LEAF> as *const () {
            return Some(Self::Private {
                base: entry.b,
                atom: entry.imm(),
                site: std::ptr::from_ref(entry).addr(),
                environment: target.env,
                function: target.function,
            });
        }
        let kind = if handler == lane_returning::<H, RETURNING_FIELD_POLYMORPHIC, NOT_LEAF> as *const () {
            RETURNING_FIELD_POLYMORPHIC
        } else if handler == lane_returning::<H, RETURNING_FIELD_OWN, NOT_LEAF> as *const () {
            RETURNING_FIELD_OWN
        } else if handler == lane_returning::<H, RETURNING_FIELD_HOLDER, NOT_LEAF> as *const () {
            RETURNING_FIELD_HOLDER
        } else if handler == lane_returning::<H, RETURNING_FIELD_INHERITED, NOT_LEAF> as *const () {
            RETURNING_FIELD_INHERITED
        } else {
            return None;
        };
        Some(Self::Field { base: entry.b, kind, cache: entry.c })
    }

    /// The read's value for a call passing `arguments` on `this`; `None` for a miss.
    #[inline(always)]
    fn run<H: Host>(
        self,
        vm: &mut Vm<H>,
        code: &ResidualProgram,
        arguments: ReadArguments,
        this: Value,
    ) -> Option<Value> {
        let base = |base: u16| lane_read_base(crate::bytecode::FieldBase(base), arguments, this);
        match self {
            Self::Element { base: field_base, field, index } => {
                let array = field.run(vm, code, base(field_base)?)?;
                vm.direct_dense_element(array, arguments.get(index)?)
            }
            Self::Nested { site } => {
                // SAFETY: a nested record of the running program names its site.
                let site = unsafe { code.field_sites.get_unchecked(site as usize) };
                nested_own_field_hit(vm, code, site, lane_read_base(site.base, arguments, this)?)
            }
            // The callee runs frameless, capturing from its closure's environment.
            Self::Private { base: field_base, atom, site, environment, function } => {
                vm.site_private_field(code, site, (environment, function, false), base(field_base)?, atom)
            }
            Self::Field { base: field_base, kind, cache } => {
                let object = base(field_base)?;
                match kind {
                    RETURNING_FIELD_POLYMORPHIC => {
                        returning_field_hit::<H, RETURNING_FIELD_POLYMORPHIC>(vm, code, object, cache)
                    }
                    RETURNING_FIELD_OWN => returning_field_hit::<H, RETURNING_FIELD_OWN>(vm, code, object, cache),
                    // A record prototype's method, read with no call; any other declines the
                    // read, and the activation's own record reads it.
                    RETURNING_FIELD_HOLDER => vm.primary_record_holder_field_hit(code, object, cache),
                    _ => returning_field_hit::<H, RETURNING_FIELD_INHERITED>(vm, code, object, cache),
                }
            }
        }
    }
}

/// A `CallEntry::ForwardsRead` body's reads: the field of `this` or a parameter it reads,
/// then the method of that field's value it calls.
#[derive(Clone, Copy)]
struct ForwardRead {
    base: u16,
    field: FieldHit,
    method: FieldHit,
}

impl ForwardRead {
    /// The reads `target`'s records answer with now; `None` for a record state no read hits.
    ///
    /// # Safety
    /// `target` is a `CallEntry::ForwardsRead` target of the running program, whose view
    /// holds its method read after its field read.
    #[inline(always)]
    unsafe fn of<H: Host>(target: &ScriptCallTarget) -> Option<Self> {
        // SAFETY: the program store keeps a derived view alive with its program.
        let (field, method) = unsafe {
            let records = (*target.view).records();
            (&*records, &*records.add(1))
        };
        Some(Self { base: field.b, field: FieldHit::of::<H>(field)?, method: FieldHit::of::<H>(method)? })
    }

    /// The method the body calls and its receiver, for a call passing `arguments` on `this`.
    #[inline(always)]
    fn method<H: Host>(
        self,
        vm: &mut Vm<H>,
        code: &ResidualProgram,
        arguments: ReadArguments,
        this: Value,
    ) -> Option<(Value, Value)> {
        let base = lane_read_base(crate::bytecode::FieldBase(self.base), arguments, this)?;
        let receiver = self.field.run(vm, code, base)?;
        Some((self.method.run(vm, code, receiver)?, receiver))
    }
}

/// A read a call site's memo makes (`MemoRead`): its field steps as copies of the field
/// cache entries that answered them (`Vm::record_field_entry_hit`), so a step is one shape
/// test. A read of a polymorphic or inherited entry, which probes further, has no memo.
#[derive(Clone, Copy)]
enum MemoLeaf {
    /// The field of the object `base` names (`lane_read_base`).
    Field { base: u16, field: super::FieldCache },
    /// That field's array, then its dense element the parameter `index` names.
    Element { base: u16, field: super::FieldCache, index: u16 },
    /// That field's array, then its `length` (`Vm::array_length_field`).
    Length { base: u16, field: super::FieldCache },
    /// That field's object, then its own field `second`.
    Nested { base: u16, field: super::FieldCache, second: super::FieldCache },
}

/// The memo shapes `lane_script_call_memo` takes as its parameter: a leaf's step
/// (`MemoLeaf::shape`), with `MEMO_FORWARD` set for a leaf a forwarding body reaches
/// (`MemoRead::Forward`), so a site's handler makes its memo's steps with no dispatch on them.
const MEMO_FIELD: u8 = 0;
const MEMO_ELEMENT: u8 = 1;
const MEMO_LENGTH: u8 = 2;
const MEMO_NESTED: u8 = 3;
const MEMO_FORWARD: u8 = 4;

impl MemoLeaf {
    /// Its step's memo shape.
    fn shape(&self) -> u8 {
        match self {
            Self::Field { .. } => MEMO_FIELD,
            Self::Element { .. } => MEMO_ELEMENT,
            Self::Length { .. } => MEMO_LENGTH,
            Self::Nested { .. } => MEMO_NESTED,
        }
    }

    /// The memo form of `read`, whose hits the active program's caches just answered; `None`
    /// for a polymorphic or inherited read.
    fn of<H: Host>(vm: &Vm<H>, code: &ResidualProgram, read: LeafRead) -> Option<Self> {
        let entry = |hit: FieldHit| match hit {
            FieldHit::Own(cache) | FieldHit::Holder(cache) => vm.field_cache_entry(cache),
        };
        Some(match read {
            LeafRead::Field { base, kind: RETURNING_FIELD_OWN | RETURNING_FIELD_HOLDER, cache } => {
                Self::Field { base, field: vm.field_cache_entry(cache) }
            }
            LeafRead::Field { .. } => return None,
            // The memo holds for its callee alone, whose environment fixes the home, so the
            // site's shape and slot under it are a plain own field step.
            LeafRead::Private { base, site, environment, .. } => {
                Self::Field { base, field: vm.site_private_field_entry(site, environment)? }
            }
            LeafRead::Element { base, field, index } => Self::Element { base, field: entry(field), index },
            LeafRead::Nested { site } => {
                // SAFETY: a nested record of the running program names its site.
                let site = unsafe { code.field_sites.get_unchecked(site as usize) };
                let (base, field) = (site.base.0, vm.field_cache_entry(site.first.1));
                match site.second {
                    None => Self::Field { base, field },
                    Some((atom, _)) if atom == vm.length_atom => Self::Length { base, field },
                    Some((_, second)) => Self::Nested { base, field, second: vm.field_cache_entry(second) },
                }
            }
        })
    }

    /// This memo with its steps as `Vm::formed_entry` makes them of the objects a call passing
    /// `arguments` on `this` reads, which its steps just answered: each step then proves its
    /// shapes and storage forms by whole-word compares (`Vm::record_field_formed_hit`).
    fn formed<H: Host>(self, vm: &Vm<H>, arguments: ReadArguments, this: Value) -> Self {
        let base_of = |base: u16| lane_read_base(crate::bytecode::FieldBase(base), arguments, this);
        let formed = |field: super::FieldCache, base: u16| base_of(base).map_or(field, |object| vm.formed_entry(field, object));
        match self {
            Self::Field { base, field } => Self::Field { base, field: formed(field, base) },
            Self::Element { base, field, index } => Self::Element { base, field: formed(field, base), index },
            Self::Length { base, field } => Self::Length { base, field: formed(field, base) },
            Self::Nested { base, field, second } => {
                let object = base_of(base).and_then(|object| vm.record_field_entry_hit(field, object));
                let second = object.map_or(second, |object| vm.formed_entry(second, object));
                Self::Nested { base, field: formed(field, base), second }
            }
        }
    }

    /// `LeafRead::run` of the read this memo records, of the step `shape` names (a constant
    /// where it inlines); `None` for a memo of another step.
    #[inline(always)]
    fn run<H: Host>(
        &self,
        shape: u8,
        vm: &Vm<H>,
        arguments: ReadArguments,
        this: Value,
        this_record: Option<&crate::heap::Object>,
    ) -> Option<Value> {
        match *self {
            Self::Field { base: field_base, field } if shape == MEMO_FIELD => memo_first_step(vm, field, field_base, arguments, this, this_record),
            Self::Element { base: field_base, field, index } if shape == MEMO_ELEMENT => {
                let array = memo_first_step(vm, field, field_base, arguments, this, this_record)?;
                vm.direct_dense_element(array, arguments.get(index)?)
            }
            Self::Length { base: field_base, field } if shape == MEMO_LENGTH => {
                let array = memo_first_step(vm, field, field_base, arguments, this, this_record)?;
                vm.array_length_field(array, vm.length_atom)
            }
            Self::Nested { base: field_base, field, second } if shape == MEMO_NESTED => {
                #[cfg(feature = "profile-field-primitives")]
                vm.profile.field_primitives.hit(crate::profile::field_primitives::Path::MemoPairAttempt);
                let object = memo_first_step(vm, field, field_base, arguments, this, this_record)?;
                #[cfg(feature = "profile-field-primitives")]
                vm.profile.field_primitives.hit(crate::profile::field_primitives::Path::MemoPairFirstHit);
                let value = vm.record_field_formed_hit(second, object);
                #[cfg(feature = "profile-field-primitives")]
                if value.is_some() { vm.profile.field_primitives.hit(crate::profile::field_primitives::Path::MemoPairHit); }
                value
            }
            _ => None,
        }
    }
}

/// A memo leaf's first step (`MemoLeaf::run`): `field` of the object `base` names, read
/// from `this`'s record where the caller holds it (a forwarding body's receiver, already
/// proven a direct object).
#[inline(always)]
fn memo_first_step<H: Host>(
    vm: &Vm<H>,
    field: super::FieldCache,
    base: u16,
    arguments: ReadArguments,
    this: Value,
    this_record: Option<&crate::heap::Object>,
) -> Option<Value> {
    match this_record {
        Some(record) if base == crate::bytecode::FieldBase::THIS.0 => vm.record_field_formed_hit_in(field, record),
        _ => vm.record_field_formed_hit(field, lane_read_base(crate::bytecode::FieldBase(base), arguments, this)?),
    }
}

/// What a call site's read target answered with (`lane_script_call_memo`), so the site's
/// next call of the same callee makes the hits alone: the target's read, or a forwarding
/// body's field and method reads and the read of the method they found. Every part depends
/// on the callee alone, whose body is fixed, and on the shapes its steps name.
#[derive(Clone, Copy)]
enum MemoRead {
    Leaf(MemoLeaf),
    Forward {
        /// The forwarding body's field read: the object `base` names, then its method.
        base: u16,
        field: super::FieldCache,
        method_field: super::FieldCache,
        /// The forwarding body's parameters, which it passes on in order.
        params: u16,
        /// The method the reads found, a `CallEntry::reads` target, whose `this` is not lexical.
        method: Value,
        read: MemoLeaf,
    },
}

impl MemoRead {
    /// Its memo shape (`MEMO_FIELD` .. `MEMO_FORWARD`).
    fn shape(&self) -> u8 {
        match self {
            Self::Leaf(read) => read.shape(),
            Self::Forward { read, .. } => MEMO_FORWARD | read.shape(),
        }
    }
}

/// The `lane_script_call_memo` instantiation of memo shape `shape` (`MemoRead::shape`).
fn script_call_memo_handler<H: Host>(shape: u8) -> Handler {
    const _: () = assert!(MEMO_NESTED < MEMO_FORWARD);
    macro_rules! shapes {
        ($($shape:expr),*) => {
            match shape {
                $(shape if shape == $shape => lane_script_call_memo::<H, { $shape }> as Handler,)*
                _ => unreachable!("a memo shape is a leaf step, forwarded or not"),
            }
        };
    }
    shapes!(
        MEMO_FIELD,
        MEMO_ELEMENT,
        MEMO_LENGTH,
        MEMO_NESTED,
        MEMO_FORWARD | MEMO_FIELD,
        MEMO_FORWARD | MEMO_ELEMENT,
        MEMO_FORWARD | MEMO_LENGTH,
        MEMO_FORWARD | MEMO_NESTED
    )
}

/// A call site's memo of its read (`MemoRead`), valid for `callee` in the generation and
/// program it was made in, as `ScriptCallTarget` is.
#[derive(Clone, Copy)]
struct ReadMemo {
    /// The call record that made it, whose slot (`CallOperand::memo`) it is.
    site: Ip,
    callee: Value,
    admission: Admission,
    this_binding: ThisBinding,
    read: MemoRead,
}

/// Slots of the read memo table (`LaneStack::read_memos`): it bounds the table's memory, and a
/// table that fills starts again empty, so the sites that read since make their memos again.
const READ_MEMOS: usize = 4096;

/// The memo the call record `site` made, in the slot it names (`CallOperand::memo`); `None`
/// before its first, or once the table refilled and gave the slot to another site.
#[inline(always)]
fn site_read_memo<'a>(memos: &'a [ReadMemo], site: &LaneInstruction) -> Option<&'a ReadMemo> {
    // SAFETY: a memo's site is a call record (`Op::makes_script_call`), whose operand is `call`.
    let slot = unsafe { site.operand.call.memo };
    memos.get(slot as usize).filter(|held| std::ptr::eq(held.site, site))
}

/// Records `target`'s read at the call record `site` (`lane_memoize_read`) unless the site's
/// own memo of this generation missed, which keeps the full form until the generation ends.
#[inline(always)]
fn lane_note_read<H: Host>(
    cx: *mut LaneContext<H>,
    site: Ip,
    target: &ScriptCallTarget,
    arguments: ReadArguments,
    this: Value,
) {
    let stack = unsafe { &vm(cx).lane_stack };
    // SAFETY: `site` is a call record of the running view.
    if site_read_memo(&stack.read_memos, unsafe { &*site }).is_none_or(|held| held.admission.generation() != stack.generation) {
        lane_memoize_read(cx, site, target, arguments, this);
    }
}

/// The memo of the read `target` just answered at `site` for `arguments` and `this`, and the
/// site's memo form (`lane_script_call_memo`); nothing for an arrow's own `this`, which the
/// memo does not hold, or a read whose records no longer hit.
#[cold]
#[inline(never)]
fn lane_memoize_read<H: Host>(
    cx: *mut LaneContext<H>,
    site: Ip,
    target: &ScriptCallTarget,
    arguments: ReadArguments,
    this: Value,
) {
    // SAFETY: the context's program outlives the lane run.
    let (vm, code) = unsafe { (vm(cx), &*(*cx).code) };
    // The memo answers the site from now on, so no call of it links its record: its record
    // names the callee for the bodies that inline it (`lane_site_targets`).
    // SAFETY: `site` is a record of the running view.
    vm.note_site_callee(unsafe { &(*site).call_link }, super::compiled::CallTarget {
        callee: super::compiled::CalleeBinding::Identity(target.callee), function: target.function });
    if target.this_binding == ThisBinding::Lexical {
        return;
    }
    let read = if target.entry == CallEntry::ForwardsRead {
        // SAFETY: as for `ForwardRead::of`.
        let Some(forward) = (unsafe { ForwardRead::of::<H>(target) }) else {
            return;
        };
        let Some((method, _)) = forward.method(vm, code, arguments, this) else {
            return;
        };
        // SAFETY: as `Vm::script_call_entry`; nothing here resolves a target or collects.
        let Some(inner) = vm.script_call_entry(method).map(|inner| unsafe { &*inner }) else {
            return;
        };
        if !inner.entry.reads() || inner.this_binding == ThisBinding::Lexical {
            return;
        }
        // SAFETY: as for `LeafRead::of`.
        let Some(read) = (unsafe { LeafRead::of::<H>(inner) }) else {
            return;
        };
        let entry = |hit: FieldHit| match hit {
            FieldHit::Own(cache) | FieldHit::Holder(cache) => vm.field_cache_entry(cache),
        };
        let Some(leaf) = MemoLeaf::of(vm, code, read) else {
            return;
        };
        // The steps as whole-word compares of the objects this call read (`MemoLeaf::formed`).
        let (field, method_field) = (entry(forward.field), entry(forward.method));
        let base = lane_read_base(crate::bytecode::FieldBase(forward.base), arguments, this);
        let receiver = base.and_then(|base| vm.record_field_entry_hit(field, base));
        let read = match receiver.and_then(|receiver| lane_receiver_this(vm, inner.this_binding, receiver)) {
            Some(method_this) => leaf.formed(vm, arguments.within(target.params), method_this),
            None => leaf,
        };
        MemoRead::Forward {
            base: forward.base,
            field: base.map_or(field, |base| vm.formed_entry(field, base)),
            method_field: receiver.map_or(method_field, |receiver| vm.formed_entry(method_field, receiver)),
            params: target.params,
            method,
            read,
        }
    } else {
        // SAFETY: as for `LeafRead::of`.
        let Some(read) = (unsafe { LeafRead::of::<H>(target) }) else {
            return;
        };
        match MemoLeaf::of(vm, code, read) {
            Some(read) => MemoRead::Leaf(read.formed(vm, arguments, this)),
            None => return,
        }
    };
    let handler = script_call_memo_handler::<H>(read.shape());
    let memo = ReadMemo {
        site,
        callee: target.callee,
        admission: vm.lane_stack.current_admission(),
        this_binding: target.this_binding,
        read,
    };
    let memos = &mut vm.lane_stack.read_memos;
    // SAFETY: `site` is a call record (`Op::makes_script_call`) of the running view, whose operand is
    // `call`, written as `requicken` writes it.
    unsafe {
        if site_read_memo(memos, &*site).is_some() {
            memos[(*site).operand.call.memo as usize] = memo;
        } else {
            if memos.len() == READ_MEMOS {
                memos.clear();
            }
            (*site.cast_mut()).operand.call.memo = memos.len() as u32;
            memos.push(memo);
        }
    }
    requicken::<H>(site, handler);
}

/// The value the memo of the call record `i` answers its call with (`ReadMemo`); `None`
/// where the memo is another site's or stale, the call is another callee's or a construction's
/// (`lane_constructing`), or a hit misses.
///
/// # Safety
/// `cx` is the running lane's context and `i` its call record.
#[inline(always)]
unsafe fn lane_memo_read<H: Host, const SHAPE: u8>(
    cx: *mut LaneContext<H>,
    r: Registers,
    i: &LaneInstruction,
) -> Option<Value> {
    let vm: &Vm<H> = unsafe { vm(cx) };
    let callee = r.get(i.b);
    let held = site_read_memo(&vm.lane_stack.read_memos, i)?;
    if held.callee != callee
        // A pending construction refuses every memo (`LaneStack::set_refused`).
        || held.admission != vm.lane_stack.admission
    {
        return None;
    }
    // A memo's steps read `this` only as a field base, which hits on a direct object alone: the
    // receiver binds itself then (`lane_receiver_this`), and any other receiver, whatever it
    // binds, misses the step as its binding would, so the receiver stands for `this` untested.
    if held.this_binding == ThisBinding::Lexical {
        return None;
    }
    let this = r.get(i.c);
    let arguments = ReadArguments {
        registers: r,
        base: ImmediateLayout::call_window_base(i.imm()),
        passed: ImmediateLayout::argument_count(i.imm()),
    };
    let leaf = SHAPE & !MEMO_FORWARD;
    match &held.read {
        MemoRead::Leaf(read) if SHAPE & MEMO_FORWARD == 0 => read.run(leaf, vm, arguments, this, None),
        MemoRead::Forward { base, field, method_field, params, method, read }
            if SHAPE & MEMO_FORWARD != 0 =>
        {
            let base = lane_read_base(crate::bytecode::FieldBase(*base), arguments, this)?;
            let receiver = vm.record_field_formed_hit(*field, base)?;
            let record = vm.heap.object_record_by_id(receiver.direct_object_index()?);
            if vm.record_field_formed_hit_in(*method_field, record)? != *method {
                return None;
            }
            // A memo's method binds no lexical `this` (`lane_memoize_read`), so the receiver, a
            // direct object, is its `this` (`lane_receiver_this`), and a step on `this` reads
            // its record.
            // The call passes the parameters in order, so its argument `k` is parameter `k`.
            read.run(leaf, vm, arguments.within(*params), receiver, Some(record))
        }
        _ => None,
    }
}

script_handler! {
    /// `lane_script_call_full` at a site whose read call made a memo (`lane_memoize_read`): the
    /// memo's hits, of its shape `SHAPE` (`MemoRead::shape`), answer the call as the read
    /// target's would. A call the memo does not answer takes the full form, which the site
    /// then keeps; a run that admits no read call (`lane_returning_call_admitted`) takes it
    /// once.
    fn lane_script_call_memo<SHAPE: u8>(cx, r, ip, i, view) {
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        // A run that admits no read call leaves the memo to the next.
        if !unsafe { (*cx).script_calls } || (returns && !lane_returning_call_admitted(cx)) {
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        }
        let Some(value) = (unsafe { lane_memo_read::<H, SHAPE>(cx, r, i) }) else {
            requicken::<H>(ip, lane_script_call_full::<H>);
            sibling!(lane_script_call_full::<H>, r, ip, Carried::script_in(cx, view))
        };
        if !returns {
            r.set(i.a, value);
            next!(cx, r, following(ip), Carried::script_in(cx, view))
        }
        lane_return_value!(cx, ip, value)
    }
}

/// The object a read body's field record names: `this`, or the parameter its activation
/// would hold in that register; `None` for an unpassed one, whose `undefined` no read hits.
#[inline(always)]
fn lane_read_base(
    base: crate::bytecode::FieldBase,
    arguments: ReadArguments,
    this: Value,
) -> Option<Value> {
    match base.register_index() {
        Some(register) => arguments.get(register),
        // A local base (`FieldBase::local`) names no activation register; the call runs.
        None if base.local_index().is_some() => None,
        None => Some(this),
    }
}

/// The `lane_returning` kind of a value record that returns its result from the frame.
fn returning_kind(instruction: WideInstruction) -> Option<u8> {
    if !instruction.returns_from_frame() {
        return None;
    }
    let traits = instruction.op().traits();
    if traits.has(Traits::RETURNING_FIELD) { Some(RETURNING_FIELD) }
    else if traits.has(Traits::RETURNING_UNARY) { Some(RETURNING_UNARY) }
    else if traits.has(Traits::RETURNING_BINARY) { Some(RETURNING_BINARY) }
    else if traits.has(Traits::RETURNING_OBJECT) { Some(RETURNING_OBJECT) }
    else if traits.has(Traits::RETURNING_OBJECT_LITERAL) { Some(RETURNING_OBJECT_LITERAL) }
    else if traits.has(Traits::RETURNING_LITERAL) { Some(RETURNING_LITERAL) }
    else { None }
}

script_handler! {
    /// A value record that returns its result from the frame (`returning_kind`): the value
    /// as the record's own handler computes it, then the activation's completion, or the VM
    /// frame's return of it from the general loop (`lane_frame_return`). A value the
    /// handler does not compute takes the general path.
    fn lane_returning<KIND: u8, LEAF: u8>(cx, r, ip, i, view) {
        let value = unsafe {
            match KIND {
                RETURNING_FIELD_OWN
                | RETURNING_FIELD_POLYMORPHIC
                | RETURNING_FIELD_HOLDER
                | RETURNING_FIELD_INHERITED => {
                    let code = &*(*cx).code;
                    let vm = vm(cx);
                    let value = lane_single_field_base(cx, r, i.b).and_then(|object| {
                        if KIND == RETURNING_FIELD_POLYMORPHIC {
                            polymorphic_read(vm, code, ip, object).map(|(value, _)| value)
                        } else {
                            returning_field_hit::<H, KIND>(vm, code, object, i.c)
                        }
                    });
                    let Some(value) = value else {
                        if KIND == RETURNING_FIELD_POLYMORPHIC {
                            sibling!(lane_returning::<H, RETURNING_FIELD, LEAF>, r, ip, Carried::script_in(cx, view))
                        }
                        sibling!(lane_returning_field_miss::<H, LEAF>, r, ip, Carried::script_in(cx, view))
                    };
                    Some(value)
                }
                RETURNING_FIELD_PRIVATE => {
                    let code = &*(*cx).code;
                    let value = lane_field_base(cx, r, crate::bytecode::FieldBase(i.b))
                        .and_then(|object| lane_private_field_value(cx, ip.addr(), code, object, i.imm()));
                    let Some(value) = value else {
                        sibling!(lane_returning::<H, RETURNING_FIELD, LEAF>, r, ip, Carried::script_in(cx, view))
                    };
                    Some(value)
                }
                RETURNING_FIELD_NESTED => {
                    let Some(value) = lane_nested_own_value(cx, r, i).or_else(|| lane_nested_polymorphic_value(cx, r, ip)) else {
                        sibling!(lane_returning::<H, RETURNING_FIELD, LEAF>, r, ip, Carried::script_in(cx, view))
                    };
                    Some(value)
                }
                // A read that meets its site's getter activates it, as `lane_get_field`
                // does: the record returns from the frame, so the getter's completion
                // completes this activation too (`lane_complete_activation`).
                RETURNING_FIELD_GETTER => {
                    return match lane_getter_activation(cx, r, ip, i) {
                        Ok((registers, base)) => next!(cx, registers, base, Carried::script(cx)),
                        // A native getter that raised is not called again: the general path raises it.
                        Err(next) if (vm(cx)).lane_completion.is_raised() => next,
                        Err(_) => sibling!(lane_returning::<H, RETURNING_FIELD, LEAF>, r, ip, Carried::script(cx)),
                    };
                }
                RETURNING_FIELD => match lane_field_value(cx, r, i) {
                    Some(value) => Some(value),
                    None => {
                        return match lane_getter_activation(cx, r, ip, i) {
                            Ok((registers, base)) => next!(cx, registers, base, Carried::script_in(cx, view)),
                            Err(next) => next,
                        };
                    }
                },
                RETURNING_UNARY => lane_unary_value(cx, r, i).or_else(|| lane_operation_in_place(cx, ip, r, i, true)),
                RETURNING_BINARY => lane_returning_binary_value(cx, r, i).or_else(|| lane_operation_in_place(cx, ip, r, i, false)),
                RETURNING_OBJECT => Some(lane_object_pair(cx, r, i.imm(), [i.b, i.c])),
                RETURNING_OBJECT_LITERAL => Some(lane_object_literal_value(cx, r, i.imm(), lane_literal_window(i))),
                _ => lane_literal_value(cx, r, i),
            }
        };
        let Some(value) = value else {
            return exit(ip);
        };
        lane_return_value!(cx, ip, value, LEAF)
    }
}

/// The value of a `Unary` (`unary`) or `Binary` record whose operands the lane's own values
/// decline, made by the general operation in place (`lane_in_place`): it may reach guest code
/// (an object's `ToPrimitive` hook) or throw, which takes the general path. `None` for an
/// operand the lane cannot read. Out of line, so the returning handlers keep their code.
#[cold]
#[inline(never)]
fn lane_operation_in_place<H: Host>(cx: *mut LaneContext<H>, ip: Ip, r: Registers, i: &LaneInstruction, unary: bool) -> Option<Value> {
    let operator = i.imm();
    if unary {
        let operand = r.get(i.b);
        return lane_in_place(cx, ip, |vm, code| vm.unary(code, operator, operand));
    }
    let (left, right) = (lane_operand_value(cx, r, i.b)?, lane_operand_value(cx, r, i.c)?);
    lane_in_place(cx, ip, |vm, code| vm.binary(code, operator, left, right))
}

script_handler! {
    /// A returning `Binary` of arithmetic operator `OP` on a register and a register or, where
    /// `CONSTANT`, a constant, resolved when the view was derived
    /// (`specialize_register_operands`) as `lane_operator` resolves a non-returning one: two
    /// integers decide it here with no dispatch on the operator, any other operands take
    /// `lane_returning_operator_other`.
    fn lane_returning_operator<OP: u32, CONSTANT: bool, LEAF: u8>(cx, r, ip, i, view) {
        let right = if CONSTANT { i.constant() } else { r.get(i.c) };
        let Some(value) = super::operations::integer_operator::<OP>(r.get(i.b), right) else {
            sibling!(lane_returning_operator_other::<H, OP, CONSTANT, LEAF>, r, ip, Carried::script_in(cx, view))
        };
        lane_return_value!(cx, ip, value, LEAF)
    }
}

script_handler! {
    /// `lane_returning_operator` of operands other than two integers: other Numbers, then the
    /// concatenation and BigInt values `lane_binary_value` decides; any other takes the
    /// general path. Out of line, so the integer case keeps few values live.
    #[inline(never)]
    fn lane_returning_operator_other<OP: u32, CONSTANT: bool, LEAF: u8>(cx, r, ip, i, view) {
        let (left, right) = (r.get(i.b), if CONSTANT { i.constant() } else { r.get(i.c) });
        let value = super::operations::number_value_operator::<OP>(left, right)
            .or_else(|| (OP == super::operations::ADDITION).then(|| lane_concatenation(cx, left, right)).flatten())
            .or_else(|| lane_bigint_value(cx, OP, left, right));
        let Some(value) = value else {
            return exit(ip);
        };
        lane_return_value!(cx, ip, value, LEAF)
    }
}

script_handler! {
    /// A returning `GetField`'s first run: a single read that names neither `name` nor
    /// `length` (`Vm::reads_function_info`) takes `RETURNING_FIELD_OWN`; any other keeps
    /// `RETURNING_FIELD`, whose cached read prepares them. Every kind keeps the record's leaf
    /// form (`LEAF`, `LaneView::specialize_leaf_returns`).
    #[inline(never)]
    fn lane_returning_field_first<LEAF: u8>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let handler = returning_field_first_kind::<H, LEAF>(unsafe { vm(cx) }, unsafe { &*(*cx).code }, i);
        requicken::<H>(ip, handler);
        sibling!(handler, r, ip, Carried::script_in(cx, view))
    }
}

/// The kind a returning `GetField` takes on its first run (`lane_returning_field_first`),
/// which its record and site alone decide.
fn returning_field_first_kind<H: Host, const LEAF: u8>(
    vm: &Vm<H>,
    code: &ResidualProgram,
    i: &LaneInstruction,
) -> Handler {
    if i.b != crate::bytecode::FieldBase::NESTED && vm.is_private_name(i.imm()) {
        return lane_returning::<H, RETURNING_FIELD_PRIVATE, LEAF>;
    }
    if is_single_field_base(i.b) && !vm.reads_function_info(i.imm()) {
        lane_returning::<H, RETURNING_FIELD_OWN, LEAF>
    } else if lane_field_site_tier(vm, code, i) == FieldSiteTier::Nested {
        lane_returning::<H, RETURNING_FIELD_NESTED, LEAF>
    } else {
        lane_returning::<H, RETURNING_FIELD, LEAF>
    }
}

script_handler! {
    /// A miss of a single-entry returning read (`RETURNING_FIELD_OWN`, `_HOLDER`,
    /// `_INHERITED`): the record moves to the kind its site's tier calls for
    /// (`lane_field_site_tier`), as `lane_get_field_miss` moves a plain read; the read itself
    /// takes `RETURNING_FIELD`.
    #[inline(never)]
    fn lane_returning_field_miss<LEAF: u8>(cx, r, ip, i, view) {
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        // The single-entry tiers read the object records alone; a receiver in a heap cell
        // keeps the general cached read.
        let cell_receiver = unsafe { lane_single_field_base(cx, r, i.b) }
            .is_some_and(|object| object.direct_object_index().is_none());
        let handler: Option<Handler> = match lane_field_site_tier(unsafe { vm(cx) }, code, i) {
            // A local base has no single-base kind (`is_single_field_base`).
            tier if tier != FieldSiteTier::Nested && !is_single_field_base(i.b) => {
                Some(lane_returning::<H, RETURNING_FIELD, LEAF>)
            }
            FieldSiteTier::Own | FieldSiteTier::Holder | FieldSiteTier::Inherited if cell_receiver => {
                Some(lane_returning::<H, RETURNING_FIELD, LEAF>)
            }
            FieldSiteTier::Nested => Some(lane_returning::<H, RETURNING_FIELD_NESTED, LEAF>),
            FieldSiteTier::General => Some(lane_returning::<H, RETURNING_FIELD, LEAF>),
            FieldSiteTier::Getter => Some(lane_returning::<H, RETURNING_FIELD_GETTER, LEAF>),
            FieldSiteTier::Polymorphic => Some(lane_returning::<H, RETURNING_FIELD_POLYMORPHIC, LEAF>),
            FieldSiteTier::Holder => Some(lane_returning::<H, RETURNING_FIELD_HOLDER, LEAF>),
            FieldSiteTier::Inherited => Some(lane_returning::<H, RETURNING_FIELD_INHERITED, LEAF>),
            FieldSiteTier::Own => None,
        };
        if let Some(handler) = handler {
            requicken::<H>(ip, handler);
        }
        sibling!(lane_returning::<H, RETURNING_FIELD, LEAF>, r, ip, Carried::script_in(cx, view))
    }
}

script_handler! {
    /// A JavaScript `Call` of a user function that needs a VM frame (no frameless target,
    /// `Vm::resolve_script_call_target`): the frame and pending call the general loop's
    /// in-loop call makes (`Vm::push_in_loop_call`), entered in place. Lane activations become
    /// frames first, as leaving the lane would make them (`materialize_lane_activations`).
    /// Any other call takes the general path, and the record resolves anew on its next run.
    #[inline(never)]
    fn lane_frame_call<>(cx, r, ip, i, view) {
        let vm = unsafe { vm(cx) };
        // SAFETY: the context's program outlives the lane run.
        let code = unsafe { &*(*cx).code };
        let callee = r.get(i.b);
        let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
        let target = vm.in_loop_call_target(code, callee);
        let admitted = |target: &(ProgramId, u32, Value)| {
            // SAFETY: the context outlives the lane run.
            let script_calls = unsafe { (*cx).script_calls };
            script_calls && (!returns || lane_returning_call_admitted(cx))
        };
        let Some(target) = target.filter(admitted) else {
            if let Some(resumed) = lane_start_async_call(cx, r, ip, i, callee) {
                resume!(cx, resumed)
            }
            requicken::<H>(ip, script_call_handler::<H>(i.imm()));
            return exit(ip);
        };
        resume!(cx, lane_push_frame_call(cx, r, ip, i, target, callee, r.get(i.c), FrameCallArguments::Window(0)))
    }
}

/// `lane_frame_call` of an async function the general loop would push as a settling call
/// (`Vm::in_loop_settling_target`): the callee starts as a job (`Vm::start_async_call`) beside
/// the caller's activations, as a native that runs beside them does (`lane_call_native_out`),
/// so its first `await` suspends its window in place and the caller continues in the lane with
/// the promise. `None` leaves the call to the general path: a call that completes its caller,
/// or a callee of another program or not yet derived.
#[inline(never)]
fn lane_start_async_call<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, i: &LaneInstruction, callee: Value) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    if !unsafe { (*cx).script_calls } || i.a & crate::bytecode::RETURN_REGISTER != 0 {
        return None;
    }
    let (program, function, env) = vm.in_loop_settling_target(code, callee)?;
    if program != unsafe { (*cx).program } || !vm.lane_call_may_derive(program, function) {
        return None;
    }
    let window = usize::from(ImmediateLayout::call_window_base(i.imm()));
    let argc = usize::from(ImmediateLayout::argument_count(i.imm()));
    // SAFETY: the call's window is registers of the running function; the values are copied
    // before any activation becomes a frame.
    let arguments = super::call_arguments::CallArguments::from_slice(unsafe { std::slice::from_raw_parts(r.0.add(window), argc) });
    let this = r.get(i.c);
    // SAFETY: `ip` is a record of the active view, which is the running function's.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    let beside = lane_park_async_caller(vm, cx, call_pc);
    let context = CallContext::user_function(function, callee);
    let result = vm.start_async_call(code, function, env, this, arguments.as_slice(), context);
    note_allocation(vm);
    vm.lane_stack.refresh_activation_limit();
    Some(lane_async_call_resumed(vm, cx, ip, i, call_pc, beside, result))
}

/// Where the lane goes once `lane_start_async_call`'s job has run its first step: on with the
/// promise in the call's register, or out with the error, materializing the deferred caller
/// the job left unobserved so the error has a frame to unwind.
fn lane_async_call_resumed<H: Host>(vm: &mut Vm<H>, cx: *mut LaneContext<H>, ip: Ip, i: &LaneInstruction, call_pc: usize, beside: bool, result: Result<Value, JsError>) -> Resumed {
    let unobserved = beside && vm.lane_deferred.take().is_some();
    match result {
        Ok(promise) => {
            // The activations may have become frames, whose registers the context now names.
            let r = unsafe { (*cx).registers };
            r.set(i.a, promise);
            Resumed::At(r, following(ip), Carried::script(cx))
        }
        Err(error) => {
            if unobserved {
                vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
                vm.materialize_deferred_lane();
            }
            vm.lane_completion.raise(error);
            Resumed::Exit(exit(ip))
        }
    }
}

/// Where `lane_start_async_call`'s caller resumes once the callee's job settles its first
/// step: beside other activations, a deferred lane call the job materializes only if it
/// observes the caller (true); otherwise the caller's own frame, resuming past the call.
fn lane_park_async_caller<H: Host>(vm: &mut Vm<H>, cx: *mut LaneContext<H>, call_pc: usize) -> bool {
    let beside = !vm.lane_stack.activations.is_empty();
    if beside {
        vm.lane_deferred = Some(DeferredLaneCall { cx: cx.cast(), call_pc, frames: vm.frames.len() });
    } else {
        // SAFETY: the context outlives the lane run.
        let frame = unsafe { (*cx).frame() };
        vm.frames[frame].pc = call_pc + 1;
        vm.frames[frame].pc_is_resume = true;
    }
    beside
}

/// The facts that keep function `function` of `program` out of a frameless activation, for
/// the census of frame calls and constructions.
#[cfg(feature = "profile-lane-exits")]
fn frame_entry_census<H: Host>(vm: &Vm<H>, program: ProgramId, function: u32) -> Option<String> {
    vm.programs.residual(program).and_then(|callee_code| {
        let body = callee_code.function_get(function as usize)?;
        let plan = body.call_plan(callee_code);
        let closures = body.code.iter().any(|packed| body.widened(*packed).op().makes_closure());
        Some(format!(
            "{} @{:?} registers_only={} env_activation={} arrow={} rest={} closures={} arguments={} handlers={} class_ctor={} async={} generator={} promoted={}/{} simple_params={} selective={} self={} plain={} in_loop={} legacy={} live={} addresses={} initial={:?} name_ops={:?} unpromoted={:?}",
            body.name.map(|atom| callee_code.atoms[atom as usize].to_string()).unwrap_or_default(),
            body.source_span.map(|span| span.start), plan.registers_only, plan.environment_activation, body.is_arrow, body.rest,
            closures, body.arguments_slot.is_some(), !body.handlers.is_empty(), body.is_class_constructor, body.is_async,
            body.is_generator, body.local_registers.len(), body.locals, body.simple_parameters, body.selective_capture_slots.is_some(),
            body.self_binding_slot.is_some(), plan.plain, plan.in_loop, plan.legacy_reflection, plan.live_parameters,
            plan.addresses_locals, body.initial_register,
            body.code.iter().map(|packed| body.widened(*packed)).filter(|instruction|
                instruction.op().is_name_operation())
                .map(|instruction| format!("{:?}:{}", instruction.op(), { let atom = instruction.atom_index() as usize; if atom < callee_code.atoms.len() { callee_code.atoms[atom].replace('\0', "~") } else { "?".into() } }))
                .collect::<Vec<_>>(),
            body.local_atoms.iter().enumerate()
                .filter(|(slot, _)| !body.local_registers.iter().any(|entry| usize::from(entry.local) == *slot))
                .map(|(_, atom)| callee_code.atoms[*atom as usize].replace('\0', "~"))
                .collect::<Vec<_>>(),
        ))
    })
}

/// `lane_frame_call`'s call of `callee`, resolved to the in-loop `target`, with receiver
/// `this` and the call window's values past its first `skip` (a forwarded call's own
/// arguments, `Vm::forwarded_call`): entered directly when the JavaScript tier promoted it,
/// else pushed as the general loop's in-loop call pushes it.
#[allow(clippy::too_many_arguments)]
#[inline(never)]
fn lane_push_frame_call<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    i: &LaneInstruction,
    target: (ProgramId, u32, Value),
    callee: Value,
    this: Value,
    passed: FrameCallArguments<'_>,
) -> Resumed {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    // A callee of another program runs in the lane only where the lane admits its program.
    if target.0 != unsafe { (*cx).program }
        && !vm.programs.residual(target.0).is_some_and(|callee_code| vm.lane_admits(callee_code))
    {
        return Resumed::Exit(exit(ip));
    }
    // A callee that has not made its deferred runs takes the general path, as a lane call's
    // does (`ProgramStore::lane_call_may_derive`): entering its frame here derived its view at
    // its first call, a callee run once included (jiti npm scenario: -2.1% instructions).
    if !vm.lane_call_may_derive(target.0, target.1) {
        return Resumed::Exit(exit(ip));
    }
    #[cfg(feature = "profile-lane-exits")]
    if let Some(body) = frame_entry_census(vm, target.0, target.1) {
        super::lane_exits::record_detail(format!("frame call {body}"));
    }
    let window = ImmediateLayout::call_window_base(i.imm());
    let argc = ImmediateLayout::argument_count(i.imm());
    // A function the JavaScript tier promoted is entered directly, as the general loop's
    // in-loop call enters it (`Vm::js_jit_compiled_call`); a guard miss pushes its frame. A
    // forwarded call is pushed, as the general loop's (`Vm::try_inline_call_apply`).
    // SAFETY: the call's window is registers of the running function, which the direct
    // call only reads.
    let arguments = match passed {
        FrameCallArguments::Window(skip) => (skip == 0).then(|| unsafe {
            std::slice::from_raw_parts(r.0.add(usize::from(window)), usize::from(argc))
        }),
        FrameCallArguments::List(list) => Some(list),
    };
    if let Some(arguments) = arguments
        && let Some(value) = vm.js_jit_compiled_call(code, (target.0, target.1), returns, arguments)
    {
        r.set(i.a, value);
        return Resumed::At(r, following(ip), Carried::script(cx));
    }
    vm.materialize_lane_activations(cx);
    // The caller is now the innermost frame, its registers the frame's.
    let (frame, r) = unsafe { ((*cx).frame(), (*cx).registers) };
    // SAFETY: the call record lies in the running view.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    // SAFETY: the call's window is registers of the caller frame, which the push neither
    // moves nor frees before it copies them; a list outlives the push.
    let arguments: *const [Value] = match passed {
        FrameCallArguments::Window(skip) => unsafe {
            std::ptr::slice_from_raw_parts(r.0.add(usize::from(window) + skip), usize::from(argc) - skip)
        },
        FrameCallArguments::List(list) => list,
    };
    let destination = i.a & crate::bytecode::REGISTER_MASK;
    let pushed = vm.push_in_loop_call(
        code,
        frame,
        call_pc + 1,
        target,
        callee,
        this,
        unsafe { &*arguments },
        destination,
    );
    match pushed {
        Some(Ok(StepResult::PushFrame {
            destination,
            call_guard,
            completion,
            ..
        })) => {
            // A callee of another program runs in its own, which the push made active
            // and the loop's executing one sets aside as the loop's own push does.
            let caller_program = (target.0 != unsafe { (*cx).program }).then(|| {
                // SAFETY: the general loop's executing program outlives the lane run.
                let executing = unsafe { &mut *(*cx).executing };
                let saved = super::dispatch_frame::SavedProgram {
                    id: executing.id,
                    retained: std::mem::replace(&mut executing.retained, vm.programs.get(target.0)),
                };
                executing.id = target.0;
                lane_enter_program(cx, target.0);
                saved
            });
            // SAFETY: the general loop's pending calls outlive the lane run.
            unsafe { &mut *(*cx).pending }.push(PendingGeneralCall {
                caller: frame,
                caller_cursor: None,
                call_pc: call_pc as u32,
                destination,
                completion,
                returns,
                call_guard: Some(call_guard),
                caller_program,
            });
            // The pushed frame's guard narrows the activations the thread admits.
            vm.lane_stack.refresh_activation_limit();
            // The tier observes the frame's entry as the general loop's would, and a
            // native result continues at the `Return` that completes the frame.
            let callee_frame = frame + 1;
            // SAFETY: the context's program, now the callee's, outlives the lane run.
            if let Some(return_pc) = vm.js_tier_frame_entry(unsafe { &*(*cx).code }, callee_frame) {
                vm.frames[callee_frame].pc = return_pc;
            }
            lane_enter_script_frame(cx, callee_frame)
        }
        // A failed push (the guest call depth) throws at the call, as the general path's.
        Some(Err(error)) => {
            vm.lane_completion.raise(error);
            Resumed::Exit(exit(ip))
        }
        _ => Resumed::Exit(exit(ip)),
    }
}

/// A JavaScript `Call` of an exported Wasm function that `Vm::wasm_export_frame_call`
/// admits: its frame, over the instance environment, pushed with the pending call that
/// converts its result (`CallCompletion::WasmExport`) and entered in this lane, as a Wasm
/// call's frame is (`wasm_calls::lane_call_frame`), so the call nests no native frame and no
/// run of the general loop. Lane activations become frames first, as for any frame call.
/// `None` leaves the call to the native: a run that is not a frame's own JavaScript run
/// (`LaneContext::script_calls`), a callee native code may run, a call completing a caller
/// the lane does not complete (`lane_returning_call_admitted`), or another program the lane
/// does not admit.
#[inline(never)]
fn lane_wasm_export_frame<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, i: &LaneInstruction) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    if !unsafe { (*cx).script_calls }
        || (returns && !lane_returning_call_admitted(cx))
        || vm.execution_mode == ExecutionMode::Compiled
    {
        return None;
    }
    // SAFETY: the call's window is registers of the running function, read before any
    // activation becomes a frame.
    let args = unsafe { lane_call_window(r, i) };
    let (program, function, env, encoded, result) = vm.wasm_export_frame_call(r.get(i.b), args)?;
    let callee_code = vm.programs.get(program)?;
    if !vm.lane_admits(&callee_code) || !vm.lane_call_may_derive(program, function) {
        return None;
    }
    if let Some(resumed) = lane_activate_wasm_export(cx, r, ip, program, function, env, &encoded, result) {
        return Some(resumed);
    }
    vm.materialize_lane_activations(cx);
    let caller = unsafe { (*cx).frame() };
    // SAFETY: the call record lies in the running view.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    vm.frames[caller].pc = call_pc + 1;
    vm.frames[caller].pc_is_resume = true;
    // The callee runs in its own program, which its frame belongs to and the loop's executing
    // one sets aside as a frame call into another program does (`lane_push_frame_call`).
    let caller_program = unsafe { (*cx).program };
    lane_enter_program(cx, program);
    let call_guard = match vm.push_wasm_frame_over(&callee_code, function, env, &encoded) {
        Ok(guard) => guard,
        Err(error) => {
            // An exhausted guest stack traps, which reaches the caller as a `RuntimeError`.
            lane_enter_program(cx, caller_program);
            // SAFETY: the context's program, the caller's again, outlives the lane run.
            let error = vm.trap_raised_in_javascript(unsafe { &*(*cx).code }, error); vm.lane_completion.raise(error);
            return Some(Resumed::Exit(exit(ip)));
        }
    };
    // SAFETY: the general loop's executing program outlives the lane run.
    let executing = unsafe { &mut *(*cx).executing };
    let saved = super::dispatch_frame::SavedProgram {
        id: executing.id,
        retained: std::mem::replace(&mut executing.retained, Some(callee_code)),
    };
    executing.id = program;
    // The run goes on as a Wasm run (`LaneContext::inline_calls`) until the frame returns,
    // which completes on the general path, as it completes any call into another program
    // (`lane_return_frame`); the caller's lane run starts afresh there.
    unsafe {
        (*cx).inline_calls = true;
        (*cx).script_calls = false;
    }
    // SAFETY: the general loop's pending calls outlive the lane run.
    unsafe { &mut *(*cx).pending }.push(PendingGeneralCall {
        caller,
        caller_cursor: None,
        call_pc: call_pc as u32,
        destination: i.a & crate::bytecode::REGISTER_MASK,
        completion: CallCompletion::WasmExport(result),
        returns,
        call_guard: Some(call_guard),
        caller_program: Some(saved),
    });
    // The pushed frame's guard narrows the activations the thread admits.
    vm.lane_stack.refresh_activation_limit();
    Some(lane_enter_frame(cx, caller + 1, 0))
}

/// `lane_wasm_export_frame`'s call as a frameless Wasm activation of the export
/// (`ActivationKind::WasmEntry`) over its instance environment, pushed as a Wasm call's
/// activation is (`wasm_calls::enter_wasm_function`) beside the caller's activations, which
/// stay activations. The run goes on as a Wasm run (`LaneContext::inline_calls`) until the
/// activation returns (`lane_complete_activation`). `None`, which changes nothing, where the
/// callee has no lane view yet or the lane no room for it: the frame call takes it.
#[inline(always)]
#[allow(clippy::too_many_arguments)]
fn lane_activate_wasm_export<H: Host>(
    cx: *mut LaneContext<H>,
    r: Registers,
    ip: Ip,
    program: ProgramId,
    function: u32,
    instance: Value,
    encoded: &[Value],
    result: Option<crate::WasmType>,
) -> Option<Resumed> {
    let vm = unsafe { vm(cx) };
    let lane_view = vm
        .programs
        .lane_views(program)?
        .get(function as usize)
        .and_then(super::program_store::derived_lane_view)?;
    let shape = lane_view.activation?;
    let base = lane_view.records();
    let stack = &mut vm.lane_stack;
    let count = usize::from(shape.registers);
    let frame_storage_bytes = count.saturating_mul(std::mem::size_of::<Value>());
    if frame_storage_bytes
        > crate::stack::GuestCallGuard::remaining_storage_bytes().saturating_sub(stack.wasm_storage_bytes)
        || stack.activations.len() >= stack.activation_limit.get()
        || vm.frames.len() + stack.activations.len() >= super::dispatch_frame::WASM_ACTIVATION_LIMIT
        || stack.values.room() < fill_room::<ACTIVATION_FILL_BLOCK>(count)
    {
        return None;
    }
    let window = stack.values.len();
    let passed = encoded.len().min(usize::from(shape.params));
    // SAFETY: capacity holds the window; each slot is written before the length covers it,
    // and no activation's window moves.
    let callee_registers = unsafe {
        let registers = stack.values.as_mut_ptr().add(window);
        fill_window(registers, count, shape.initial);
        for (offset, &value) in encoded[..passed].iter().enumerate() {
            registers.add(usize::from(shape.parameters) + offset).write(value);
        }
        stack.values.set_len(window + count + lane_values::CONTEXT);
        // A Wasm activation runs with its caller's receiver and environment (`ActivationState::of`).
        Registers(registers).set_this(r.this());
        Registers(registers).set_env(r.env());
        Registers(registers).set_capture(r.capture());
        Registers(registers)
    };
    let (caller_program, caller_base) = unsafe { ((*cx).program, (*cx).base) };
    // SAFETY: capacity holds the activation.
    unsafe {
        let at = stack.values.as_mut_ptr().wrapping_add(window);
        stack.push_activation(Activation {
            native: super::compiled::ShadowFrame::EMPTY,
            function,
            call: ip,
            caller_base,
            caller_registers: r,
            caller_program,
            kind: ActivationKind::WasmEntry { instance, result, frame_storage_bytes },
        }, at);
    }
    lane_enter_program(cx, program);
    // A fresh activation's memory register holds no memory until the function's instance
    // binding loads it.
    unsafe {
        (*cx).registers = callee_registers;
        (*cx).base = base;
        (*cx).memory = MemoryView::NONE;
        (*cx).instance = instance;
        (*cx).inline_calls = true;
        (*cx).script_calls = false;
    }
    let view = Carried { memory: MemoryView::NONE, integers: crate::value::IntegerEncoding::TAG, acc: Slot::of(Value::UNDEFINED) };
    Some(Resumed::At(callee_registers, base, view))
}

/// `new` of a user constructor that needs a VM frame, made in place as the general loop's
/// in-loop construction makes it (`Vm::inline_construct_target`): lane activations become
/// frames, the receiver is allocated, and the constructor's frame is pushed with the pending
/// construction that substitutes the receiver for a non-object result
/// (`lane_return_script_frame`). Any other construction takes the general path.
#[inline(never)]
fn lane_frame_construct<H: Host>(cx: *mut LaneContext<H>, r: Registers, ip: Ip, i: &LaneInstruction) -> Ip {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let callee = r.get(i.b);
    let returns = i.a & crate::bytecode::RETURN_REGISTER != 0;
    // The checks `inline_construct_target` makes of the callee alone, before activations
    // become frames for it. A constructor of another program is pushed in its own, where the
    // lane admits it.
    let pushable = match vm.heap.function(callee) {
        Some(FunctionRecord { kind: FunctionKind::User(program, id), realm, .. }) => {
            *realm == vm.realm.globals
                && if *program == unsafe { (*cx).program } {
                    code.function_get(*id as usize).is_some_and(Vm::<H>::inline_constructible)
                } else {
                    vm.programs.residual(*program).is_some_and(|callee_code| {
                        vm.lane_admits(callee_code)
                            && callee_code
                                .function_get(*id as usize)
                                .is_some_and(Vm::<H>::inline_constructible)
                    })
                }
        }
        _ => false,
    };
    if !pushable
        || !unsafe { (*cx).script_calls && (*cx).script_constructs }
        || vm.construct_target.is_some()
        || returns && !lane_returning_call_admitted(cx)
    {
        return exit(ip);
    }
    vm.materialize_lane_activations(cx);
    // The caller is now the innermost frame, its registers the frame's.
    let (frame, r) = unsafe { ((*cx).frame(), (*cx).registers) };
    let Some((program, id, env, this)) = vm.inline_construct_target(code, frame, callee) else {
        return exit(ip);
    };
    #[cfg(feature = "profile-lane-exits")]
    if let Some(body) = frame_entry_census(vm, program, id) {
        super::lane_exits::record_detail(format!("frame construct {body}"));
    }
    // Allocating the receiver can make a collection due.
    note_allocation(vm);
    // SAFETY: the call record lies in the running view.
    let call_pc = unsafe { ip.offset_from((*cx).base) } as usize;
    vm.frames[frame].pc = call_pc + 1;
    vm.frames[frame].pc_is_resume = true;
    let argc = usize::from(ImmediateLayout::argument_count(i.imm()));
    // SAFETY: the construction's window is registers of the caller frame, which the push
    // neither moves nor frees before it copies them.
    let arguments: *const [Value] = unsafe { std::ptr::slice_from_raw_parts(r.0.add(usize::from(i.c)), argc) };
    vm.set_construct_target(Some(super::activation::ConstructionTarget { callee, new_target: callee }));
    // A constructor of another program runs in its own, which the push makes active and the
    // loop's executing one sets aside, as `lane_push_frame_call` pushes a call.
    let caller_program = (program != unsafe { (*cx).program }).then(|| {
        // SAFETY: the general loop's executing program outlives the lane run.
        let executing = unsafe { &mut *(*cx).executing };
        let saved = super::dispatch_frame::SavedProgram {
            id: executing.id,
            retained: std::mem::replace(&mut executing.retained, vm.programs.get(program)),
        };
        executing.id = program;
        lane_enter_program(cx, program);
        saved
    });
    // SAFETY: the context's program is now the callee's, which outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let pushed = vm.push_general_user_frame(code, id, env, this, unsafe { &*arguments }, CallContext::user_function(id, callee));
    vm.set_construct_target(None);
    match pushed {
        Ok(call_guard) => {
            // SAFETY: the general loop's pending calls outlive the lane run.
            unsafe { &mut *(*cx).pending }.push(PendingGeneralCall {
                caller: frame,
                caller_cursor: None,
                call_pc: call_pc as u32,
                destination: i.a & crate::bytecode::REGISTER_MASK,
                completion: CallCompletion::Constructor(this),
                returns,
                call_guard: Some(call_guard),
                caller_program,
            });
            // The pushed frame's guard narrows the activations the thread admits.
            vm.lane_stack.refresh_activation_limit();
            let callee_frame = frame + 1;
            if let Some(return_pc) = vm.js_tier_frame_entry(code, callee_frame) {
                vm.frames[callee_frame].pc = return_pc;
            }
            lane_enter_script_frame(cx, callee_frame).into_loop()
        }
        // A failed push (the guest call depth) throws at the construction, as the general
        // path's. The caller's program is the executing one again.
        Err(error) => {
            if let Some(saved) = caller_program {
                // SAFETY: as above.
                let executing = unsafe { &mut *(*cx).executing };
                executing.id = saved.id;
                executing.retained = saved.retained;
                lane_enter_program(cx, saved.id);
            }
            vm.lane_completion.raise(error);
            exit(ip)
        }
    }
}

/// Continue in JavaScript frame `frame` at its resume point, with the lane's per-frame
/// facts for it: `new` activates in place only from an ordinary body
/// (`LaneContext::script_constructs`).
#[inline(always)]
fn lane_enter_script_frame<H: Host>(cx: *mut LaneContext<H>, frame: usize) -> Resumed {
    let vm = unsafe { vm(cx) };
    // SAFETY: the context's program outlives the lane run.
    let code = unsafe { &*(*cx).code };
    let function = vm.frames[frame].function;
    unsafe {
        (*cx).script_constructs = code
            .function_get(function as usize)
            .is_some_and(|function| function.dispatch == crate::bytecode::DispatchClass::General);
    }
    lane_enter_frame(cx, frame, vm.frames[frame].pc)
}

/// The return of the running JavaScript frame with `value` to the caller frame the general
/// loop's pending call names, made in place as that loop makes it: the frame retires, an
/// in-loop `new` substitutes its receiver for a non-object result, and the caller continues
/// with the value in the call's register. A call that returns its callee's completion
/// completes its caller in turn: another pending caller here, or the loop's own frame,
/// which the general loop returns from at that call (`lane_frame_return`). A call into
/// another program returns to the caller's, as the loop's return restores it.
#[inline(never)]
fn lane_return_script_frame<H: Host>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    mut value: Value,
    mut retired: bool,
) -> Ip {
    let vm = unsafe { vm(cx) };
    let pending = unsafe { &mut *(*cx).pending };
    let mut frame = unsafe { (*cx).frame() };
    let mut exit_ip = ip;
    loop {
        // An async callee's promise settles on the general path (`PendingGeneralCall::completion`);
        // a generator whose activation became a frame finishes here as there (`PendingGeneralCall::completion`).
        let returns_here = pending.last().is_some_and(|call| lane_completes_return(cx, call, frame, retired));
        if !returns_here {
            // A record that has not run yet runs again on the general path; one that ran (a
            // call made, `retired`) completes the loop's own frame with the value there.
            if !retired {
                return exit(exit_ip);
            }
            return lane_frame_return(vm, exit_ip, value);
        }
        let mut call = pending.pop().expect("a pending call names the returning frame");
        let completed = vm.frames.pop().expect("the returning frame is the innermost");
        match call.completion.take_generator() {
            Some(resume) => {
                let stop = super::generator::MaterializedStop::Returned;
                value = vm.finish_materialized_generator_step(completed, resume, value, stop);
                note_allocation(vm);
            }
            None => {
                vm.finish_frame_scopes(&completed);
                vm.pool_frame(completed);
            }
        }
        retired = true;
        // A call into another program returns to the caller's, which the loop executes again.
        if let Some(saved) = call.caller_program.take() {
            // SAFETY: the general loop's executing program outlives the lane run.
            let executing = unsafe { &mut *(*cx).executing };
            executing.id = saved.id;
            executing.retained = saved.retained;
            lane_enter_program(cx, saved.id);
        }
        drop(call.call_guard);
        frame = call.caller;
        // The completion may read the caller's register (`CallCompletion::Assigned`), which
        // names the register file `active_registers` holds.
        vm.active_registers = vm.frames[frame].registers.as_mut_ptr();
        value = vm.completed_call_value(&call.completion, frame, call.destination, value);
        if !call.returns {
            vm.write(frame, call.destination, value);
            return lane_enter_script_frame(cx, frame).into_loop();
        }
        // The caller completes too, at its call record.
        let (_, call_ip, _) = lane_frame_state(cx, frame, call.call_pc as usize);
        exit_ip = call_ip;
    }
}

/// Return from a frame the general loop or a frame push made. Out of line
/// so the activation return saves no registers.
#[cold]
#[inline(never)]
fn lane_return_frame<H: Host>(r: Registers, ip: Ip) -> Resumed {
    let cx = lane_context::<H>();
    // SAFETY: called only while a lane runs, from its return handler.
    let i = unsafe { &*ip };
    let vm = unsafe { vm(cx) };
    if !unsafe { (*cx).inline_calls } && unsafe { (*cx).script_calls } {
        return Resumed::Exit(lane_return_script_frame(cx, ip, r.get(i.a), false));
    }
    let pending = unsafe { &mut *(*cx).pending };
    if unsafe { (*cx).inline_calls }
        && pending.last().is_some_and(|call| {
            matches!(call.completion, CallCompletion::WasmExport(_)) && call.caller + 2 == vm.frames.len()
        })
    {
        return lane_return_wasm_export(cx, r.get(i.a));
    }
    // An in-loop `new` substitutes its receiver for a non-object result;
    // the general path owns that [[Construct]] step.
    if !unsafe { (*cx).inline_calls }
        || pending.last().is_none_or(|call| {
            !matches!(call.completion, CallCompletion::Value)
                || call.caller_program.is_some()
        })
    {
        return Resumed::Exit(exit(ip));
    }
    let value = r.get(i.a);
    let Some(call) = pending.pop() else {
        return Resumed::Exit(exit(ip));
    };
    vm.retire_wasm_frame();
    vm.active_registers = vm.frames[call.caller].registers.as_mut_ptr();
    vm.write(call.caller, call.destination, value);
    drop(call.call_guard);
    let pc = vm.frames[call.caller].pc;
    lane_enter_frame(cx, call.caller, pc)
}

/// The return of an exported function's frame a JavaScript call pushed
/// (`lane_wasm_export_frame`) with its encoded `value`: the frame retires, its caller's
/// program runs again as the run's JavaScript (`LaneContext::script_calls`), and the call's
/// register takes the value's JavaScript form (`CallCompletion::WasmExport`), or, for a call
/// that completes its caller, the caller returns it.
#[cold]
#[inline(never)]
fn lane_return_wasm_export<H: Host>(cx: *mut LaneContext<H>, value: Value) -> Resumed {
    let vm = unsafe { vm(cx) };
    // SAFETY: the general loop's pending calls outlive the lane run.
    let mut call = unsafe { &mut *(*cx).pending }.pop().expect("the export's frame has its pending call");
    let CallCompletion::WasmExport(result) = call.completion else {
        unreachable!("the caller tested the completion");
    };
    vm.retire_wasm_frame();
    let saved = call.caller_program.take().expect("an export's frame runs its own program");
    // SAFETY: the general loop's executing program outlives the lane run.
    let executing = unsafe { &mut *(*cx).executing };
    executing.id = saved.id;
    executing.retained = saved.retained;
    lane_enter_program(cx, saved.id);
    unsafe {
        (*cx).inline_calls = false;
        (*cx).script_calls = true;
    }
    drop(call.call_guard);
    let frame = call.caller;
    vm.active_registers = vm.frames[frame].registers.as_mut_ptr();
    let value = vm.wasm_export_result(value, result);
    if call.returns {
        // The caller completes too, at its call record, as a returning frame call's does
        // (`lane_return_script_frame`).
        let (_, call_ip, _) = lane_frame_state(cx, frame, call.call_pc as usize);
        return Resumed::Exit(lane_return_script_frame(cx, call_ip, value, true));
    }
    vm.write(frame, call.destination, value);
    lane_enter_script_frame(cx, frame)
}

/// A lane opcode's handler, and whether that handler is an accumulator
/// producer: whenever it falls through to the next record, it has written
/// its result register and carries the written value into that record.
#[derive(Clone, Copy)]
struct LaneHandler {
    handler: Handler,
    produces: bool,
}

impl LaneHandler {
    const fn producer(handler: Handler) -> Option<Self> {
        Some(Self {
            handler,
            produces: true,
        })
    }
}

/// The handler serving opcode `OP` whose accumulator field is `ACC`, derived
/// from the opcode's semantic family; `None` when the general path executes
/// the opcode.
const fn handler_for<H: Host, const OP: u16, const BACKWARD: bool, const ACC: u8>()
-> Option<LaneHandler> {
    let Some(op) = Op::from_index(OP as usize) else {
        return None;
    };
    // The opcodes past a byte are selected per record (`derive_lane_view`); a generated row
    // is their only table entry.
    if OP as usize >= 1 << u8::BITS && !lane_runs_row(op) {
        return None;
    }
    if I32BinaryOperator::from_register_op(op).is_some()
        || I32BinaryOperator::from_immediate_op(op).is_some()
    {
        return LaneHandler::producer(lane_i32_binary::<H, OP, ACC>);
    }
    let handler: Handler = if I32BinaryOperator::from_jump_op(op).is_some()
        || I32BinaryOperator::from_immediate_jump_op(op).is_some()
    {
        lane_compare_jump::<H, OP, BACKWARD, ACC>
    } else if MemoryLoad::from_direct_op(op).is_some() {
        return LaneHandler::producer(lane_load::<H, OP, ACC>);
    } else if MemoryStore::from_direct_op(op).is_some() {
        lane_store::<H, OP, ACC>
    } else {
        if lane_runs_row(op) {
            return Some(LaneHandler { handler: lane_row::<H, OP, ACC, FLAG_UNREAD>, produces: row_produces(op) });
        }
        match op.class() {
            Class::WasmI32ShiftRightUnsignedAnd => {
                return LaneHandler::producer(lane_bit_field::<H, ACC>);
            }
            Class::WasmSelect => return LaneHandler::producer(lane_select::<H, ACC>),
            Class::WasmI32AddJump => {
                return LaneHandler::producer(lane_add_jump_nonzero::<H, BACKWARD, ACC>);
            }
            Class::WasmI32Unary => return LaneHandler::producer(lane_i32_unary::<H, ACC>),
            Class::WasmFloatBinary32 | Class::WasmFloatBinary64 => {
                return LaneHandler::producer(lane_float_binary::<H, OP, ACC>);
            }
            Class::WasmFloatUnary32 | Class::WasmFloatUnary64 => {
                return LaneHandler::producer(lane_float_unary::<H, OP, ACC>);
            }
            Class::WasmI64Binary => return LaneHandler::producer(lane_i64_binary::<H, ACC>),
            Class::WasmI64BinaryImmediate => return LaneHandler::producer(lane_i64_binary_immediate::<H, ACC>),
            Class::WasmI64Unary => return LaneHandler::producer(lane_i64_unary::<H, ACC>),
            Class::WasmScalarConvert => {
                return LaneHandler::producer(lane_scalar_convert::<H, ACC>);
            }
            _ => match other_handler::<H, BACKWARD, ACC>(op) {
                Some(handler) => handler,
                None => return None,
            },
        }
    };
    Some(LaneHandler {
        handler,
        produces: false,
    })
}

/// The handlers of the jumps (`other_handler`), whose direction decides whether they run a
/// safepoint, then of the Wasm GC steps (`wasm_gc_handler`).
const fn jump_handler<H: Host, const BACKWARD: bool, const ACC: u8>(opcode: Op) -> Option<Handler> {
    match opcode.class() {
        Class::JumpBinaryFalse => Some(lane_jump_binary_false::<H, BACKWARD>),
        Class::Jump => Some(lane_jump_always::<H, BACKWARD>),
        Class::JumpFalse => Some(lane_jump_false::<H, BACKWARD>),
        Class::JumpTrue => Some(lane_jump_true::<H, BACKWARD>),
        Class::WasmBranchTable => Some(lane_branch_table::<H, BACKWARD>),
        Class::WasmJumpI32Zero => Some(lane_jump_i32_zero::<H, true, BACKWARD, ACC, false>),
        Class::WasmJumpI32NonZero => Some(lane_jump_i32_zero::<H, false, BACKWARD, ACC, false>),
        _ => wasm_gc_handler::<H>(opcode),
    }
}

/// The handlers of a class's private elements, none of which runs guest code: a field's
/// definition, a method's brand, and the brand checks of a read and of `#x in`.
const fn private_element_handler<H: Host>(opcode: Op) -> Option<Handler> {
    match opcode.class() {
        Class::DefinePrivateField => Some(lane_define_private_field::<H>),
        Class::MarkPrivateName => Some(lane_mark_private_name::<H>),
        Class::CheckPrivate => Some(lane_check_private::<H>),
        Class::PrivateIn => Some(lane_private_in::<H>),
        _ => None,
    }
}

/// The handlers of the iterator protocol's steps: an array's intrinsic iterator, a close
/// that ends without a call, and the bookkeeping of the iterators a frame must close.
const fn iterator_handler<H: Host>(opcode: Op) -> Option<Handler> {
    match opcode.class() {
        Class::GetIterator => Some(lane_get_iterator::<H>),
        Class::IteratorClose => Some(lane_iterator_close::<H>),
        Class::AppendArray => Some(lane_append_array::<H>),
        Class::IteratorCleanupPush => Some(lane_iterator_cleanup_push::<H>),
        Class::RequireIteratorResult => Some(lane_require_iterator_result::<H>),
        Class::IteratorCleanupPop => Some(lane_iterator_cleanup_pop::<H>),
        _ => None,
    }
}

/// Handlers that neither produce nor read the accumulator, apart from the
/// branch tests, which read it.
const fn other_handler<H: Host, const BACKWARD: bool, const ACC: u8>(opcode: Op) -> Option<Handler> {
    match opcode.class() {
        Class::StoreName => Some(lane_store_name_first::<H>),
        Class::DefineArrayElement => Some(lane_define_array_element::<H>),
        Class::StoreLocal | Class::StoreEnvLocal => Some(lane_store_local::<H>),
        Class::LoadCallee => Some(lane_load_callee::<H>),
        Class::InitializeTdz => Some(lane_initialize_tdz::<H>),
        Class::CloneEnv => Some(lane_clone_env::<H>),
        Class::GetField => Some(lane_get_field_first::<H>),
        _ if opcode.field_store().is_some() => match opcode.field_store() {
            Some(store) => Some(field_store_row::<H>(store)),
            None => None,
        },
        Class::ToPropertyKey => Some(lane_to_property_key::<H>),
        Class::DefinePropertyRecord => Some(lane_define_property_record::<H>),
        Class::DefineField => Some(lane_define_field::<H>),
        _ if private_element_handler::<H>(opcode).is_some() => private_element_handler::<H>(opcode),
        Class::CopyDataProperties => Some(lane_copy_data_properties::<H>),
        _ if iterator_handler::<H>(opcode).is_some() => iterator_handler::<H>(opcode),
        _ if for_in_steps::for_in_handler::<H, BACKWARD>(opcode).is_some() => for_in_steps::for_in_handler::<H, BACKWARD>(opcode),
        _ if opcode.steps_in_lane() => Some(lane_general_step::<H>),
        _ if denoted_handler::<H>(opcode).is_some() => denoted_handler::<H>(opcode),
        Class::GetIndex => Some(lane_get_index::<H>),
        Class::SetIndex => Some(element_write_row::<H>()),
        Class::MakeConstArray => Some(lane_make_const_array::<H>),
        Class::StringCaseIndex => Some(lane_string_case_index::<H>),
        Class::LoadLocal | Class::LoadEnvLocal => Some(lane_load_local::<H>),
        Class::WasmInstanceBinding => Some(lane_instance_binding::<H, false>),
        Class::WasmGlobalGet => Some(lane_global_get::<H>),
        Class::WasmSimd => Some(lane_wasm_simd::<H>),
        Class::WasmMemoryLoad => Some(lane_wasm_memory_load::<H>),
        Class::WasmMemoryAddress => Some(lane_wasm_memory_address::<H>),
        Class::WasmMemoryStore => Some(lane_wasm_memory_store::<H>),
        Class::WasmSimdShuffle => Some(lane_wasm_simd_shuffle::<H>),
        Class::WasmGlobalSet => Some(lane_global_set::<H>),
        Class::WasmFillRegisters => Some(lane_fill_registers::<H>),
        Class::CallKnown => Some(known_call_handler::<H>()),
        Class::Call => Some(lane_script_call::<H, ANY_ARGC, false>),
        Class::CallArray => Some(lane_call_array::<H>),
        Class::CallSpread => Some(lane_call_spread::<H>),
        Class::Delete => Some(lane_delete::<H>),
        Class::Construct => Some(lane_script_construct::<H>),
        Class::LoadName => Some(lane_load_name_resolve::<H, LOAD_NAME>),
        Class::LoadNameCall => Some(lane_load_name_resolve::<H, LOAD_NAME_CALL>),
        Class::LoadNameTypeof => Some(lane_load_name_resolve::<H, LOAD_NAME_TYPEOF>),
        Class::MakeObject2 => Some(lane_make_object2::<H>),
        Class::MakeClosure => Some(lane_make_closure::<H>),
        Class::MakeObjectLiteral => Some(lane_make_object_literal::<H>),
        Class::MakeArray => Some(lane_make_array::<H>),
        Class::MakeObject => Some(lane_make_object::<H>),
        Class::CreateRegExpLiteral => Some(lane_regexp_literal::<H>),
        Class::CallForwardingArguments => Some(lane_forward_call::<H>),
        Class::SuperConstArrayObject2 => Some(lane_const_array_object2::<H>),
        Class::Return => Some(lane_return::<H, NOT_LEAF>),
        _ if suspend_handler::<H>(opcode).is_some() => suspend_handler::<H>(opcode),
        _ => jump_handler::<H, BACKWARD, ACC>(opcode),
    }
}

/// Dense fast handlers cover the first opcode byte; later opcodes use general dispatch.
const TABLE_SLOTS: usize = crate::bytecode::OPCODE_COUNT.next_multiple_of(TABLE_ROW as usize);

/// Opcodes per generated table row.
const TABLE_ROW: u16 = 16;
const TABLE_ROWS: usize = TABLE_SLOTS / TABLE_ROW as usize;
// `lane_table` lists one generated row per sixteen opcodes.
const _: () = assert!(TABLE_ROWS == 18, "add a `table_row!` to `lane_table` per sixteen new opcodes");

macro_rules! table_row {
    ($h:ty, $backward:literal, $acc:expr, $row:literal) => {
        [
            handler_for::<$h, { $row * TABLE_ROW }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 1 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 2 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 3 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 4 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 5 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 6 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 7 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 8 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 9 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 10 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 11 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 12 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 13 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 14 }, $backward, { $acc }>(),
            handler_for::<$h, { $row * TABLE_ROW + 15 }, $backward, { $acc }>(),
        ]
    };
}

const fn flatten_rows(
    rows: [[Option<LaneHandler>; TABLE_ROW as usize]; TABLE_ROWS],
) -> [Option<LaneHandler>; TABLE_SLOTS] {
    let mut table = [None; TABLE_SLOTS];
    let mut slot = 0;
    while slot < TABLE_SLOTS {
        table[slot] = rows[slot / TABLE_ROW as usize][slot % TABLE_ROW as usize];
        slot += 1;
    }
    table
}

/// One handler table: the opcode's handler for one jump direction and one
/// accumulator field.
type Table = [Option<LaneHandler>; TABLE_SLOTS];

macro_rules! lane_table {
    ($h:ty, $backward:literal, $acc:expr) => {
        flatten_rows([
            table_row!($h, $backward, $acc, 0),
            table_row!($h, $backward, $acc, 1),
            table_row!($h, $backward, $acc, 2),
            table_row!($h, $backward, $acc, 3),
            table_row!($h, $backward, $acc, 4),
            table_row!($h, $backward, $acc, 5),
            table_row!($h, $backward, $acc, 6),
            table_row!($h, $backward, $acc, 7),
            table_row!($h, $backward, $acc, 8),
            table_row!($h, $backward, $acc, 9),
            table_row!($h, $backward, $acc, 10),
            table_row!($h, $backward, $acc, 11),
            table_row!($h, $backward, $acc, 12),
            table_row!($h, $backward, $acc, 13),
            table_row!($h, $backward, $acc, 14),
            table_row!($h, $backward, $acc, 15),
            table_row!($h, $backward, $acc, 16),
            table_row!($h, $backward, $acc, 17),
        ])
    };
}

struct LaneTable<H>(std::marker::PhantomData<H>);

impl<H: Host> LaneTable<H> {
    /// Tables indexed by jump direction (forward, then backward: a
    /// safepoint) and by accumulator field.
    const TABLES: [[Table; ACC_POSITIONS]; 2] = [
        [
            lane_table!(H, false, ACC_NONE),
            lane_table!(H, false, ACC_A),
            lane_table!(H, false, ACC_B),
            lane_table!(H, false, ACC_C),
            lane_table!(H, false, ACC_PAIR),
        ],
        [
            lane_table!(H, true, ACC_NONE),
            lane_table!(H, true, ACC_A),
            lane_table!(H, true, ACC_B),
            lane_table!(H, true, ACC_C),
            lane_table!(H, true, ACC_PAIR),
        ],
    ];
}

/// Whether the lane may run `instruction` from its view record: every
/// register it names lies inside the register file and carries no flag.
pub(super) fn lane_fields_fit(instruction: WideInstruction, function: &Function) -> bool {
    let registers = function.registers;
    let op = instruction.op();
    let fields = [
        (InstructionField::A, instruction.a()),
        (InstructionField::B, instruction.b()),
        (InstructionField::C, instruction.c()),
    ];
    let numeric_local = instruction.writes_numeric_local()
        && instruction.a() & crate::bytecode::RETURN_REGISTER == 0
        && instruction.result_register() < function.locals;
    let registers_fit = fields
        .iter()
        .all(|&(field, value)| match op.field_layout(field) {
            FieldLayout::ResultRegister if field == InstructionField::A && numeric_local => true,
            // A lane call reads its return flag from the field (`lane_call_fits`).
            FieldLayout::ResultRegister
                if field == InstructionField::A
                    && (op.traits().has(crate::bytecode::Traits::FRAME_RETURNABLE)
                        || (op.is_binary() && instruction.returns_from_frame())) =>
            {
                instruction.result_register() < registers
            }
            FieldLayout::FieldBase => {
                value == crate::bytecode::FieldBase::NESTED
                    || crate::bytecode::FieldBase(value)
                        .register_index()
                        .is_none_or(|register| register < registers)
            }
            FieldLayout::OptionalRegister | FieldLayout::OptionalReadRegister => value
                .checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS)
                .is_none_or(|register| register < registers),
            FieldLayout::Operand => {
                let operand = crate::bytecode::Operand(value);
                operand.kind() != Some(crate::bytecode::OperandKind::Register)
                    || operand.payload() < registers
            }
            layout => !layout.is_register_field() || value < registers,
        });
    let window_fits = op.field_layout(InstructionField::B) != FieldLayout::RegisterWindowBase
        || u32::from(instruction.b()) + u32::from(instruction.c()) <= u32::from(registers);
    let pair_fits = op.immediate_layout() != ImmediateLayout::RegisterPair || {
        let (first, second) = ImmediateLayout::register_pair(instruction.imm());
        first < registers && second < registers
    };
    registers_fit && window_fits && pair_fits
}

/// The record operand of `instruction` at `pc`, or `None` when its jump or
/// constant cannot be resolved.
fn lane_operand(
    instruction: WideInstruction,
    pc: usize,
    constants: &[Value],
) -> Option<LaneOperand> {
    let record = std::mem::size_of::<LaneInstruction>() as isize;
    Some(match instruction.op().immediate_role() {
        ImmediateRole::JumpTarget => {
            let distance = isize::try_from(instruction.imm()).ok()? - isize::try_from(pc).ok()?;
            LaneOperand {
                jump: distance.checked_mul(record)?,
            }
        }
        // A case selector reads its run of constants from the context by index, as a constant
        // array reads its elements' (`lane_make_const_array`).
        ImmediateRole::ConstantIndex
            if instruction.op().is_string_case_index() || instruction.op().class() == Class::MakeConstArray =>
        {
            let start = instruction.imm() as usize;
            constants.get(start..start.checked_add(usize::from(instruction.b()))?)?;
            LaneOperand { imm: instruction.imm() }
        }
        ImmediateRole::ConstantIndex => LaneOperand {
            constant: *constants.get(instruction.imm() as usize)?,
        },
        _ if holds_field_hint(instruction.op()) => LaneOperand {
            field: FieldOperand { imm: instruction.imm(), shape: super::NO_FIELD_RECEIVER },
        },
        _ if instruction.op().makes_script_call() => LaneOperand {
            call: CallOperand { imm: instruction.imm(), memo: NO_READ_MEMO },
        },
        _ => LaneOperand {
            imm: instruction.imm(),
        },
    })
}

/// A `Call` runs in the lane only as the general loop pushes one in place: it evaluates no
/// direct or parameter-scope `eval`, which a window activation's call record runs apart (`lane_eval`). It, `GetField`, `Unary` and `Binary` may return their
/// result from the frame (`lane_returns`, `lane_returning`); a returning record runs no
/// other result flag.
fn lane_call_fits(instruction: WideInstruction) -> bool {
    match instruction.op().class() {
        Class::Call | Class::CallArray | Class::CallSpread => {
            lane_returns(instruction)
                && !instruction.direct_eval()
                && !instruction.parameter_eval()
        }
        Class::CallForwardingArguments => lane_returns(instruction),
        Class::Construct => {
            lane_returns(instruction)
                && !instruction.is_super_construct()
                && !ImmediateLayout::construct_array_arguments(instruction.imm())
        }
        Class::GetField => lane_returns(instruction) || lane_sinks_field(instruction),
        Class::Unary | Class::MakeObject2 | Class::SuperConstArrayObject2 | Class::MakeObjectLiteral => {
            lane_returns(instruction)
        }
        Class::Binary if instruction.returns_from_frame() => lane_returns(instruction),
        _ if spreads_rest_view(instruction) => lane_returns(instruction),
        _ => true,
    }
}

/// Whether `instruction`'s staged row is a call spreading a rest parameter kept as a view
/// (`Passing::Rest`): the interpreter's own decode names it, so no opcode is listed here.
fn spreads_rest_view(instruction: WideInstruction) -> bool {
    matches!(crate::staged::Operation::<u64, ()>::decode_names(instruction),
        Some(crate::staged::Operation::SpreadCall { passing: crate::staged::Passing::Rest, .. }))
}

/// A `Call` record's operand, flagged when only the `Await` right after the call reads its
/// result: the await overwrites the result register, or liveness (`live`) shows it dead after
/// the await. A settling call there makes its promise only where one becomes observable
/// (`ImmediateLayout::LANE_CALL_RESULT_AWAITED_FLAG`). Liveness is derived only for a call
/// followed by an `Await`, of a function whose suspension derives it anyway
/// (`Vm::suspend_activation`).
fn lane_call_awaited_marked<'live>(
    operand: LaneOperand,
    decoded: &[WideInstruction],
    pc: usize,
    live: &dyn Fn() -> Option<&'live std::rc::Rc<crate::compile::liveness::RegisterMasks>>,
) -> LaneOperand {
    let call = decoded[pc];
    let Some(&awaited) = decoded.get(pc + 1) else {
        return operand;
    };
    if !call.op().is_call() || call.result_flags() != 0 || !awaited.op().is_await() {
        return operand;
    }
    let result = call.result_register();
    let feeds = awaited.register_b() == result
        && (awaited.result_register() == result
            || live()
                .and_then(|masks| masks.get(pc + 2))
                .is_some_and(|live| crate::compile::liveness::register_dead(live, usize::from(result))));
    if !feeds {
        return operand;
    }
    // SAFETY: a `Call`'s operand is its immediate (`lane_operand`).
    let imm = unsafe { operand.imm };
    LaneOperand { imm: imm | ImmediateLayout::LANE_CALL_RESULT_AWAITED_FLAG }
}

/// A `Call` record's operand, flagged when liveness (`live`, the registers live before each
/// pc) shows its result register dead after the call: nothing reads the value the callee
/// returns (`ImmediateLayout::lane_call_result_used`).
fn lane_call_result_marked(
    operand: LaneOperand,
    instruction: WideInstruction,
    function: &Function,
    pc: usize,
) -> LaneOperand {
    if !instruction.op().is_call() || !function.register_roots.call_result_dead(pc) {
        return operand;
    }
    // SAFETY: a `Call`'s operand is its immediate (`lane_operand`).
    let imm = unsafe { operand.imm };
    LaneOperand { imm: imm | ImmediateLayout::LANE_CALL_RESULT_UNUSED_FLAG }
}

/// Whether the `Call` at `pc` is an iteration step: no arguments, its result checked by the
/// `RequireIteratorResult` after it, as the compiler emits a for-of or destructuring step,
/// whose result register only the step's own `done` and `value` reads take
/// (`lane_iterator_step`).
fn lane_iteration_step(decoded: &[WideInstruction], pc: usize) -> bool {
    let call = decoded[pc];
    call.result_flags() == 0
        && ImmediateLayout::argument_count(call.imm()) == 0
        && decoded.get(pc + 1).is_some_and(|next| {
            next.op().is_require_iterator_result() && next.register_b() == call.result_register()
        })
}

/// The records of a for-of step after its iteration `Call` (`lane_for_of_step`), by offset
/// from it: the `done` read of the step's result, then its test.
/// The for-of step's `RequireIteratorResult`, whose otherwise unused `a` the compiler sets
/// when the step's value goes only to an array pattern (`FunctionCompiler::for_iterable`).
const FOR_OF_REQUIRE_RESULT: usize = 1;
const FOR_OF_DONE_READ: usize = 2;
const FOR_OF_DONE_TEST: usize = 3;

/// How a for-of step's records test its `done` read (`lane_for_of_step`). As `for_of` emits
/// it, a `JumpFalse` into the body jumps over the `Jump` that leaves the loop; the rewrite
/// that threads a jump over a jump makes them one `JumpTrue` that leaves it.
/// `lane_generator_step`'s `READS` for a for-of step of each `ForOfTest` form.
const STEP_READS_EMITTED: u8 = 1;
const STEP_READS_THREADED: u8 = 2;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
enum ForOfTest {
    /// `JumpFalse` to the `value` read, past a `Jump` out of the loop.
    Emitted,
    /// `JumpTrue` out of the loop, the `value` read after it.
    Threaded,
}

impl ForOfTest {
    /// The offset of the record that leaves the loop: the `Jump` after the test, or the
    /// threaded test itself.
    const fn exit(self) -> usize {
        match self {
            Self::Emitted => FOR_OF_DONE_TEST + 1,
            Self::Threaded => FOR_OF_DONE_TEST,
        }
    }

    /// The offset of the `value` read, which follows the record that leaves the loop.
    const fn value_read(self) -> usize {
        self.exit() + 1
    }

    /// The records the step spans, its `Call` through its `value` read.
    const fn records(self) -> usize {
        self.value_read() + 1
    }
}

/// How the iteration step at `pc` (`lane_iteration_step`) begins a for-of step: after its
/// `RequireIteratorResult`, a plain read of the result into a register, a test of that
/// register (`ForOfTest`), and a second plain read of the result where the body begins.
/// `lane_iterator_step_reads` then makes the reads from the step itself; their atoms it
/// tests as it runs.
fn lane_for_of_step(decoded: &[WideInstruction], pc: usize) -> Option<ForOfTest> {
    let result = decoded[pc].result_register();
    let record = |offset: usize| decoded.get(pc + offset).copied();
    let reads_result = |offset: usize| {
        record(offset).is_some_and(|read| read.op().is_get_field() && read.result_flags() == 0 && read.b() == result)
    };
    record(FOR_OF_REQUIRE_RESULT).filter(|require| require.op().class() == Class::RequireIteratorResult)?;
    let done = record(FOR_OF_DONE_READ).filter(|_| reads_result(FOR_OF_DONE_READ))?.result_register();
    let test = record(FOR_OF_DONE_TEST).filter(|test| test.a() == done)?;
    let form = match test.op().class() {
        Class::JumpFalse => ForOfTest::Emitted,
        Class::JumpTrue => ForOfTest::Threaded,
        _ => return None,
    };
    let exit = record(form.exit())?;
    let leaves = exit.op().class().eq(if form == ForOfTest::Emitted { Class::Jump } else { Class::JumpTrue })
        && exit.jump_target() as usize > pc + form.value_read();
    let enters = form == ForOfTest::Threaded || test.jump_target() as usize == pc + form.value_read();
    (leaves && enters && reads_result(form.value_read())).then_some(form)
}

/// The records of a destructuring step after its iteration `Call` (`lane_binding_step`), by
/// offset from it: the `done` read, its move to the pattern's done flag, the threaded test
/// leaving the step, and the `value` read.
const BINDING_DONE_READ: usize = 2;
const BINDING_DONE_MOVE: usize = 3;
const BINDING_DONE_TEST: usize = 4;
const BINDING_VALUE_READ: usize = 5;

/// Whether the iteration step at `pc` (`lane_iteration_step`) is a destructuring step as
/// `binding_iterator_step` emits it once its test is threaded: a plain read of the result's
/// `done`, a move of it to another register, a `JumpTrue` of it past the step, and a plain
/// read of the result's `value`. `lane_iterator_step_binding` then makes the reads and the
/// move from the step itself; their atoms it tests as it runs.
fn lane_binding_step(decoded: &[WideInstruction], pc: usize) -> bool {
    let result = decoded[pc].result_register();
    let record = |offset: usize| decoded.get(pc + offset).copied();
    let reads_result = |offset: usize| {
        record(offset).is_some_and(|read| read.op().is_get_field() && read.result_flags() == 0 && read.b() == result)
    };
    let (Some(done), Some(flag), Some(test), Some(value)) =
        (record(BINDING_DONE_READ), record(BINDING_DONE_MOVE), record(BINDING_DONE_TEST), record(BINDING_VALUE_READ))
    else {
        return false;
    };
    let done = done.result_register();
    reads_result(BINDING_DONE_READ)
        && reads_result(BINDING_VALUE_READ)
        && flag.op().is_move()
        && flag.result_flags() == 0
        && flag.b() == done
        && flag.a() != done
        && flag.a() != result
        && test.op().class().eq(Class::JumpTrue)
        && test.a() == done
        && test.jump_target() as usize > pc + BINDING_VALUE_READ
        && value.result_register() != done
        && value.result_register() != flag.a()
        && pc + BINDING_VALUE_READ + 1 < decoded.len()
}

/// A nested `GetField` whose only result flag stores its value to a field of `this` too
/// (`lane_get_field_sink`).
fn lane_sinks_field(instruction: WideInstruction) -> bool {
    instruction.result_flags() == crate::bytecode::SET_THIS_REGISTER
        && instruction.writes_current_this()
}

/// Whether the instruction's only result flag, if any, returns the result from the frame.
fn lane_returns(instruction: WideInstruction) -> bool {
    instruction.result_flags() & !crate::bytecode::RETURN_REGISTER == 0
}

/// The register every compiled linear-memory access of `function` goes
/// through, when there is exactly one: the direct accesses', or in a body with none, its
/// vector accesses' (`WasmMemoryAddress`) when the prologue binds it, as lowering binds a
/// memory32 memory once per call.
pub(super) fn memory_register(function: &Function) -> Option<u16> {
    let instructions = || function.code.iter().map(|packed| function.widened(*packed));
    let direct = instructions().filter_map(|instruction| match instruction.op() {
        op if MemoryLoad::from_direct_op(op).is_some()
            || MemoryStore::from_direct_op(op).is_some() => Some(instruction.b()),
        op if op.is_wasm_memory_size() => Some(instruction.b()),
        op if op.is_wasm_memory_fill() => Some(instruction.a()),
        _ => None,
    });
    single_register(direct).or_else(|| {
        let vector = single_register(
            instructions().filter(|instruction| instruction.op().is_wasm_memory_address()).map(|instruction| instruction.c()),
        )?;
        instructions()
            .take_while(|instruction| {
                matches!(instruction.op().class(), Class::WasmFillRegisters | Class::WasmInstanceBinding)
            })
            .any(|instruction| instruction.op().is_wasm_instance_binding() && instruction.a() == vector)
            .then_some(vector)
    })
}

/// The one register `registers` names, when they name exactly one.
fn single_register(mut registers: impl Iterator<Item = u16>) -> Option<u16> {
    let first = registers.next()?;
    registers.all(|register| register == first).then_some(first)
}

/// Whether a lane run of `instruction` could write `register`.
fn lane_writes(instruction: WideInstruction, register: u16) -> bool {
    let op = instruction.op();
    let result = matches!(
        op.field_layout(InstructionField::A),
        FieldLayout::ResultRegister | FieldLayout::WriteRegister | FieldLayout::ReadWriteRegister
    ) && instruction.a() == register;
    let optional = op.field_layout(InstructionField::B) == FieldLayout::OptionalRegister
        && instruction
            .b()
            .checked_sub(crate::bytecode::OPTIONAL_REGISTER_BIAS)
            == Some(register);
    let filled = op.is_wasm_fill_registers()
        && (instruction.b()..instruction.b().saturating_add(instruction.c())).contains(&register);
    result || optional || filled
}

/// The shortest straight-line lane run the general loop enters. Entering
/// builds the lane context and memory view, which one or two lane
/// instructions do not repay: on V8-v7 fixed work, three keeps every
/// JavaScript benchmark within one percent of the general path or better
/// (one and two cost DeltaBlue three percent), and leaves Wasm loops,
/// whose runs are long, unchanged.
const LANE_ENTRY_MIN_RUN: usize = 3;

/// `LANE_ENTRY_MIN_RUN` in a function with no loop the lane runs whole: each call the
/// general loop makes into it enters the lane anew, so a run must repay a fresh lane
/// context.
const LANE_ENTRY_MIN_CALL_RUN: usize = 8;

/// Whether records may read the accumulator. Without sibling calls every
/// handler returns to the lane loop, which carries no accumulator.
const ACCUMULATOR: bool = cfg!(quench_lane_tail_calls);

/// The handler of a returning record of `kind` (`returning_kind`) in a view that has no leaf form.
fn returning_handler<H: Host>(kind: u8) -> Handler {
    match kind {
        RETURNING_FIELD => lane_returning_field_first::<H, NOT_LEAF>,
        RETURNING_UNARY => lane_returning::<H, RETURNING_UNARY, NOT_LEAF>,
        RETURNING_BINARY => lane_returning::<H, RETURNING_BINARY, NOT_LEAF>,
        RETURNING_OBJECT => lane_returning::<H, RETURNING_OBJECT, NOT_LEAF>,
        RETURNING_OBJECT_LITERAL => lane_returning::<H, RETURNING_OBJECT_LITERAL, NOT_LEAF>,
        _ => lane_returning::<H, RETURNING_LITERAL, NOT_LEAF>,
    }
}

/// Derive a function's lane view from its bytecode and its program's
/// constants.
fn derive_lane_view<'live, H: Host>(
    function_id: u32,
    function: &Function,
    constants: &[Value],
    heap: &crate::heap::Heap,
    kind: crate::bytecode::ProgramKind,
    live: &dyn Fn() -> Option<&'live std::rc::Rc<crate::compile::liveness::RegisterMasks>>,
    sites: &[crate::bytecode::FieldSite],
    loop_tier: bool,
    diagnostics: bool,
    tiers: &'static Tiers,
) -> LaneView {
    // Each pass below reads instructions by PC; they are decoded once, here.
    let decoded: Vec<WideInstruction> = function.instructions().collect();
    // Every backward jump observes host termination, including allocation-free
    // Wasm loops. Collection and stack-floor exits share this safepoint.

    let tables = const { &LaneTable::<H>::TABLES };
    // Only Wasm bodies access linear memory.
    let memory_register = (kind == crate::bytecode::ProgramKind::Wasm)
        .then(|| memory_register(function))
        .flatten();
    let entries = entered_records(&decoded, function.parameter_end_pc);
    // Wasm instructions, whose fusions the passes under `wasm` make, occur only in Wasm
    // bodies: JavaScript compiles to none of them.
    let wasm = kind == crate::bytecode::ProgramKind::Wasm;
    let resolves_names = function.has_dynamic_scope_access();
    // One function-wide fact, consulted per local load; it scans the whole body.
    let kept_arguments = std::cell::OnceCell::new();
    let mut producer: Option<u16> = None;
    // Per instruction: the general path executes it, and its record reads
    // the accumulator.
    let mut exits = Vec::with_capacity(function.code.len());
    let mut reads_accumulator = Vec::with_capacity(function.code.len());
    // Per instruction: the register whose value a record reading the accumulator reads
    // there, `NO_ACCUMULATOR` for a record that reads none.
    let mut accumulator_registers = Vec::with_capacity(function.code.len());
    // Per instruction: the register its selected record carries as the
    // accumulator to the record after it.
    let mut produced = Vec::with_capacity(function.code.len());
    let mut records: Box<[LaneInstruction]> = function
        .code
        .iter()
        .enumerate()
        .map(|(pc, _)| {
            let instruction = decoded[pc];
            let op = instruction.op();
            let binds_memory =
                op.is_wasm_instance_binding() && Some(instruction.a()) == memory_register;
            let memory_access = MemoryLoad::from_direct_op(op).is_some()
                || MemoryStore::from_direct_op(op).is_some();
            let keeps_view = if memory_access {
                Some(instruction.b()) == memory_register
            } else {
                binds_memory
                    || memory_register.is_none_or(|register| !lane_writes(instruction, register))
            };
            let operand = lane_operand(instruction, pc, constants)
                .filter(|_| {
                    keeps_view && lane_fields_fit(instruction, function) && lane_call_fits(instruction)
                })
                .map(|operand| lane_call_result_marked(operand, instruction, function, pc))
                .map(|operand| lane_call_awaited_marked(operand, &decoded, pc, live));
            // Control reaches this record only from the previous one when nothing enters it
            // (`entered_records`); the general loop never enters at a record that reads the
            // accumulator.
            let carried = producer.take().filter(|_| ACCUMULATOR && !entries.contains(pc));
            let acc = carried.map_or(ACC_NONE, |register| {
                accumulator_field(instruction, register)
            });
            // A table is backward when one of its entries jumps back.
            let backward_jump = if op.is_wasm_branch_table() {
                    crate::bytecode::branch_table_entries(pc, instruction).any(|entry| {
                        decoded[entry].imm() as usize <= pc
                    })
                } else {
                    op.immediate_role() == ImmediateRole::JumpTarget
                        && instruction.imm() as usize <= pc
                };
            let selected = operand.and_then(|_| if binds_memory {
                Some(LaneHandler {
                    handler: lane_instance_binding::<H, true> as Handler,
                    produces: false,
                })
            } else if op.is_wasm_f64_unary()
                && F64UnaryOperator::from_tag(instruction.imm())
                    == Some(F64UnaryOperator::SquareRoot)
            {
                tables[usize::from(backward_jump)][usize::from(acc)].get(op as usize).copied().flatten()
                    .and_then(|_| {
                        LaneHandler::producer(match acc {
                            ACC_NONE => lane_f64_sqrt::<H, ACC_NONE> as Handler,
                            ACC_A => lane_f64_sqrt::<H, ACC_A> as Handler,
                            ACC_B => lane_f64_sqrt::<H, ACC_B> as Handler,
                            ACC_C => lane_f64_sqrt::<H, ACC_C> as Handler,
                            _ => lane_f64_sqrt::<H, ACC_PAIR> as Handler,
                        })
                    })
            } else if let Some(handler) = float_arithmetic(op, instruction.imm())
                .map(|arith| FloatArithmetic::<H>::HANDLERS[usize::from(op.is_wasm_f64_binary())][usize::from(arith)][usize::from(acc)])
                .or_else(|| i64_operator_handler::<H>(op, instruction.imm(), acc))
            {
                tables[usize::from(backward_jump)][usize::from(acc)].get(op as usize).copied().flatten()
                    .and_then(|_| LaneHandler::producer(handler))
            } else if matches!(op.class(), Class::LoadLocal | Class::LoadLocalPlain | Class::ArgumentsLength | Class::ArgumentGet)
                && function.arguments_slot == u16::try_from(instruction.local_slot()).ok()
                && let Some(kept) = *kept_arguments.get_or_init(|| function.kept_arguments())
            {
                let forwards = decoded.get(pc + 1).is_some_and(|next| {
                    next.op().is_call_forwarding_arguments()
                        && next.call_window().last() == Some(instruction.result_register())
                });
                Some(LaneHandler {
                    handler: match op.class() {
                        Class::ArgumentsLength => lane_arguments_length::<H> as Handler,
                        Class::ArgumentGet => lane_argument_get::<H> as Handler,
                        _ if kept == crate::bytecode::KeptArguments::Passes && !forwards => {
                            lane_load_kept_arguments_object::<H> as Handler
                        }
                        _ => lane_load_forwarded_arguments::<H> as Handler,
                    },
                    produces: false,
                })
            } else if spreads_rest_view(instruction) {
                Some(LaneHandler { handler: lane_call_rest::<H> as Handler, produces: false })
            } else if op.reads_arguments() {
                Some(LaneHandler {
                    handler: if op.class().eq(Class::ArgumentsLength) {
                        lane_frame_arguments::<H, false> as Handler
                    } else {
                        lane_frame_arguments::<H, true> as Handler
                    },
                    produces: false,
                })
            } else if op.is_call() && lane_iteration_step(&decoded, pc) {
                Some(LaneHandler {
                    handler: match lane_for_of_step(&decoded, pc) {
                        Some(ForOfTest::Emitted) => lane_iterator_step_reads::<H, false> as Handler,
                        Some(ForOfTest::Threaded) => lane_iterator_step_reads::<H, true> as Handler,
                        None if lane_binding_step(&decoded, pc) => lane_iterator_step_binding::<H> as Handler,
                        None => lane_iterator_step::<H> as Handler,
                    },
                    produces: false,
                })
            } else if op.is_store_env_local() && resolves_names {
                None
            } else if op.is_get_field() && lane_sinks_field(instruction) {
                Some(LaneHandler {
                    handler: lane_get_field_sink_first::<H> as Handler,
                    produces: false,
                })
            } else if let Some(kind) = returning_kind(instruction) {
                Some(LaneHandler { handler: returning_handler::<H>(kind), produces: false })
            } else if let Some(handler) = wasm.then(|| wasm_lane_handler::<H>(op)).flatten() {
                handler
            } else {
                tables[usize::from(backward_jump)][usize::from(acc)]
                    .get(op as usize)
                    .copied()
                    .flatten()
            });
            // A generated row reads its record's `a` as its result register (`LaneFields::wide`);
            // a record whose `a` carries result flags (a numeric local target) runs the general
            // step, which decodes them, so no row tests for them.
            let row = tables[usize::from(backward_jump)][usize::from(acc)].get(op as usize).copied().flatten();
            let selected = selected.map(|chosen| {
                let flagged = lane_runs_row(op)
                    && matches!(op.field_layout(InstructionField::A), FieldLayout::ResultRegister)
                    && instruction.a() & !crate::bytecode::REGISTER_MASK != 0;
                if flagged && row.is_some_and(|row| row.handler as *const () == chosen.handler as *const ()) {
                    LaneHandler { handler: lane_general_step::<H>, ..chosen }
                } else {
                    chosen
                }
            });
            producer = selected
                .filter(|selected| selected.produces)
                .map(|_| instruction.a());
            produced.push(producer);
            exits.push(selected.is_none());
            reads_accumulator.push(selected.is_some() && acc != ACC_NONE);
            accumulator_registers.push(
                carried.filter(|_| selected.is_some() && acc != ACC_NONE).unwrap_or(NO_ACCUMULATOR),
            );
            let handler = selected.map_or(lane_exit::<H> as Handler, |selected| selected.handler) as *const ();
            LaneInstruction {
                handler,
                operand: operand.unwrap_or(LaneOperand { imm: 0 }),
                a: instruction.a(),
                b: instruction.b(),
                // A kept argument read finds the values after the function's registers, whose
                // count its unused field carries (`lane_argument_get`).
                c: if handler == lane_argument_get::<H> as Handler as *const () {
                    function.registers as u16
                } else {
                    instruction.c()
                },
                call_link: std::cell::Cell::new(NO_CALL_LINK),
            }
        })
        .collect();
    // Each record's handler before any fusion: a record still holding it
    // runs only its own instruction.
    let selected: Vec<*const ()> = records.iter().map(|record| record.handler).collect();
    // Whether a record's handler serves `op` with accumulator field `acc`.
    let serves = |handler: *const (), op: u16, acc: u8| {
        tables[0][usize::from(acc)]
            .get(usize::from(op))
            .copied()
            .flatten()
            .is_some_and(|served| handler == served.handler as *const ())
    };
    // The direction and accumulator field (among `accs`) of the plain handler serving `op`
    // that `handler` is, for an instruction whose handler depends on its jump's direction.
    let plain_served = |handler: *const (), op: u16, accs: &[u8]| {
        [false, true].into_iter().find_map(|backward| {
            accs.iter().copied().find(|&acc| {
                tables[usize::from(backward)][usize::from(acc)]
                    .get(usize::from(op))
                    .copied()
                    .flatten()
                    .is_some_and(|served| handler == served.handler as *const ())
            })
            .map(|acc| (backward, acc))
        })
    };
    // Runs of vector instructions execute as one record each (`vector_region`): placed
    // before the fusions below, which then leave each region's first record alone. Only a
    // body with SIMD operators derives the liveness they read.
    let vectors = wasm
        && decoded.iter().any(|instruction| matches!(instruction.op().class(), Class::WasmSimd | Class::WasmSimdShuffle));
    let vector_regions: Box<[vector_region::VectorRegion]> = match vectors.then(live).flatten() {
        Some(live) => vector_region::vector_regions(
            &decoded,
            constants,
            heap,
            memory_register,
            live,
            &entries,
            &exits,
            &produced,
        ),
        None => Vec::new(),
    }
    .into_boxed_slice();
    for region in &vector_regions {
        records[region.first()].handler = vector_region::region_handler::<H>() as *const ();
        records[region.first()].operand = LaneOperand { region };
    }
    if wasm {
        // A table follows its selected entry's jump, so every entry must run in
        // the lane.
        for (pc, &instruction) in decoded.iter().enumerate() {
            if instruction.op().is_wasm_branch_table()
                && crate::bytecode::branch_table_entries(pc, instruction).any(|entry| exits[entry])
            {
                records[pc].handler = lane_exit::<H> as Handler as *const ();
                exits[pc] = true;
                reads_accumulator[pc] = false;
                accumulator_registers[pc] = NO_ACCUMULATOR;
            }
        }
        // An add of a constant whose sum the next record loads from runs with
        // that load as one record: the load reads the sum as its carried
        // accumulator, so control reaches it only from the add.
        for pc in 0..records.len().saturating_sub(1) {
            let instruction = decoded[pc];
            let next = decoded[pc + 1];
            let plain_add = serves(records[pc].handler, opc::WasmI32AddImmediate, ACC_NONE);
            let carried_load = serves(records[pc + 1].handler, next.op() as u16, ACC_C);
            if instruction.op().is_wasm_i32_add_immediate()
                && plain_add
                && carried_load
                && let Some(fused) = add_load_handler::<H>(next.op())
            {
                // A float operator taking the loaded f64 joins the fusion.
                let operator = (next.op().is_wasm_f64_load() && pc + 2 < records.len())
                    .then(|| decoded[pc + 2])
                    .filter(|third| third.op().is_wasm_f64_binary())
                    .and_then(|third| {
                        let second = float_arithmetic(third.op(), third.imm())?;
                        let left = [ACC_B, ACC_C].into_iter().find(|acc| {
                            records[pc + 2].handler
                                == FloatArithmetic::<H>::HANDLERS[1][usize::from(second)]
                                    [usize::from(*acc)] as *const ()
                        })? == ACC_B;
                        Some(AddLoadF64::<H>::HANDLERS[usize::from(second)][usize::from(left)])
                    });
                records[pc].handler = operator.unwrap_or(fused) as *const ();
            }
        }
        // An i32 load whose value the next record's branch table selects on
        // runs with that table as one record.
        for pc in 0..records.len().saturating_sub(1) {
            let instruction = decoded[pc];
            let next = decoded[pc + 1];
            let field = [ACC_NONE, ACC_C]
                .into_iter()
                .find(|acc| serves(records[pc].handler, instruction.op() as u16, *acc));
            if let Some(field) = field
                && next.a() == instruction.a()
                && serves(records[pc + 1].handler, opc::WasmBranchTable, ACC_NONE)
                && let Some(fused) = load_table_handler::<H>(instruction.op(), field, false)
            {
                records[pc].handler = fused as *const ();
                // A plain add of a constant ahead of a load reading its own
                // field joins as well.
                if pc > 0
                    && field == ACC_NONE
                    && serves(records[pc - 1].handler, opc::WasmI32AddImmediate, ACC_NONE)
                    && let Some(fused) = load_table_handler::<H>(instruction.op(), ACC_NONE, true)
                {
                    records[pc - 1].handler = fused as *const ();
                }
            }
        }
        // A shift left by a constant whose result the next record adds runs
        // with that add as one record.
        for pc in 0..records.len().saturating_sub(1) {
            let variant = |op: u16, acc: u8, at: usize| serves(records[at].handler, op, acc);
            let field = [ACC_NONE, ACC_B]
                .into_iter()
                .position(|acc| variant(opc::WasmI32ShiftLeftImmediate, acc, pc));
            let left = [ACC_C, ACC_B]
                .into_iter()
                .position(|acc| variant(opc::WasmI32Add, acc, pc + 1));
            if let (Some(field), Some(left)) = (field, left) {
                records[pc].handler = ScaledIndex::<H>::HANDLERS[field][left] as *const ();
            }
        }
        // An i32 load, the operator taking the loaded value and the store of
        // its result run as one record.
        for pc in 0..records.len().saturating_sub(2) {
            let load = decoded[pc];
            let combine = decoded[pc + 1];
            let store = decoded[pc + 2];
            if !load.op().is_wasm_i32_load() || !store.op().is_wasm_i32_store() {
                continue;
            }
            let field = [ACC_NONE, ACC_C]
                .into_iter()
                .find(|&acc| serves(records[pc].handler, opc::WasmI32Load, acc));
            let left = [ACC_C, ACC_B]
                .into_iter()
                .position(|acc| serves(records[pc + 1].handler, combine.op() as u16, acc));
            if let (Some(field), Some(left)) = (field, left)
                && store.a() == combine.a()
                && serves(records[pc + 2].handler, opc::WasmI32Store, ACC_A)
                && let Some(fused) = i32_update_handler::<H>(combine.op(), left == 1, field)
            {
                records[pc].handler = fused as *const ();
            }
        }
        // A constant that the next record stores runs with that store as one
        // record.
        for pc in 0..records.len().saturating_sub(1) {
            let next = decoded[pc + 1];
            if serves(records[pc].handler, opc::LoadConst, ACC_NONE)
                && serves(records[pc + 1].handler, next.op() as u16, ACC_A)
                && let Some(fused) = constant_store_handler::<H>(next.op())
            {
                records[pc].handler = fused as *const ();
            }
        }
        // A load whose value the next record stores runs with that store as
        // one record.
        for pc in 0..records.len().saturating_sub(1) {
            let instruction = decoded[pc];
            let next = decoded[pc + 1];
            let field = [ACC_NONE, ACC_C]
                .into_iter()
                .find(|acc| serves(records[pc].handler, instruction.op() as u16, *acc));
            let carried_store = serves(records[pc + 1].handler, next.op() as u16, ACC_A);
            if let Some(field) = field
                && carried_store
                && let Some(fused) = load_store_handler::<H>(instruction.op(), next.op(), field)
            {
                records[pc].handler = fused as *const ();
            }
        }
    }
    // The zero-test jump `handler` is, as (taken on zero, backward), when it carries no
    // register and reads its operand plainly or from the accumulator.
    let plain_zero_jump = |handler: *const ()| {
        let plain = ZeroJumps::<H, false>::HANDLERS;
        (0..2).flat_map(|zero| (0..2).map(move |backward| (zero, backward))).find(|&(zero, backward)| {
            [ACC_NONE, ACC_A]
                .into_iter()
                .any(|acc| handler == plain[zero][backward][usize::from(acc)] as *const ())
        })
    };
    // Each record's i32 load with its address field, if it is a plain one.
    let i32_load = |records: &[LaneInstruction], pc: usize| {
        let op = decoded[pc].op();
        [ACC_NONE, ACC_C].into_iter().find(|&acc| serves(records[pc].handler, op as u16, acc)).filter(|_| {
            matches!(
                op.class(),
                Class::WasmI32Load | Class::WasmI32Load8S | Class::WasmI32Load8U | Class::WasmI32Load16S | Class::WasmI32Load16U
            )
        })
    };
    if wasm {
        // An i32 add or subtract of a constant, the and of a constant over its result and an
        // immediate comparison jump testing that run as one record.
        for pc in 0..records.len().saturating_sub(2) {
            let (first, mask, jump) = (decoded[pc], decoded[pc + 1], decoded[pc + 2]);
            let Some(acc) = [ACC_NONE, ACC_B].into_iter().find(|&acc| serves(records[pc].handler, first.op() as u16, acc))
            else {
                continue;
            };
            if !matches!(first.op().class(), Class::WasmI32AddImmediate | Class::WasmI32SubtractImmediate)
                || !mask.op().is_wasm_i32_and_immediate()
                || mask.b() != first.a()
                || jump.a() != mask.a()
                || ![ACC_NONE, ACC_B].into_iter().any(|acc| serves(records[pc + 1].handler, opc::WasmI32AndImmediate, acc))
            {
                continue;
            }
            let Some((backward, _)) = plain_served(records[pc + 2].handler, jump.op() as u16, &[ACC_NONE, ACC_A])
            else {
                continue;
            };
            if let Some(fused) = offset_mask_jump_handler::<H>(first.op(), jump.op(), backward, acc) {
                records[pc].handler = fused as *const ();
            }
        }
        // An i32 operator of a constant and a register comparison jump reading its result run as
        // one record.
        for pc in 0..records.len().saturating_sub(1) {
            let (first, jump) = (decoded[pc], decoded[pc + 1]);
            if !serves(records[pc].handler, first.op() as u16, ACC_NONE)
                || I32BinaryOperator::from_jump_op(jump.op()).is_none()
                || (jump.a() != first.a() && jump.b() != first.a())
            {
                continue;
            }
            let Some((backward, _)) = plain_served(records[pc + 1].handler, jump.op() as u16, &[ACC_NONE, ACC_A, ACC_B])
            else {
                continue;
            };
            if let Some(fused) = immediate_compare_jump_handler::<H>(first.op(), jump.op(), backward) {
                records[pc].handler = fused as *const ();
            }
        }
        // An i32 load whose value the next record's i32 load takes as its address runs with it as
        // one record; so does an i32 load whose value the next record's zero-test jump tests.
        for pc in 0..records.len().saturating_sub(1) {
            let Some(acc) = i32_load(&records, pc) else {
                continue;
            };
            let (load, next) = (decoded[pc], decoded[pc + 1]);
            let fused = if load.op().is_wasm_i32_load()
                && i32_load(&records, pc + 1).is_some()
                && next.c() == load.a()
            {
                load_load_handler::<H>(next.op(), acc)
            } else if let Some((zero, backward)) = plain_zero_jump(records[pc + 1].handler)
                && next.a() == load.a()
            {
                load_jump_handler::<H>(load.op(), acc, zero == 1, backward == 1)
            } else {
                None
            };
            if let Some(fused) = fused {
                records[pc].handler = fused as *const ();
            }
        }
        // Two plain i32 loads whose values the next record's i32 operator combines run with it
        // as one record.
        for pc in 0..records.len().saturating_sub(2) {
            let (first, second, combine) = (decoded[pc], decoded[pc + 1], decoded[pc + 2]);
            if first.op() != second.op()
                || i32_load(&records, pc) != Some(ACC_NONE)
                || i32_load(&records, pc + 1) != Some(ACC_NONE)
                || first.a() == second.a()
                || second.c() == first.a()
                || ![ACC_NONE, ACC_B, ACC_C].into_iter().any(|acc| serves(records[pc + 2].handler, combine.op() as u16, acc))
            {
                continue;
            }
            let first_left = if (combine.b(), combine.c()) == (first.a(), second.a()) {
                true
            } else if (combine.b(), combine.c()) == (second.a(), first.a()) {
                false
            } else {
                continue;
            };
            if let Some(fused) = load_pair_binary_handler::<H>(first.op(), combine.op(), first_left) {
                records[pc].handler = fused as *const ();
            }
        }
        // An i32 operator, a constant load and a select reading them run as one record.
        for pc in 0..records.len().saturating_sub(2) {
            let (operator, constant) = (decoded[pc], decoded[pc + 1]);
            let Some(acc) = [ACC_NONE, ACC_B, ACC_C].into_iter().find(|&acc| serves(records[pc].handler, operator.op() as u16, acc))
            else {
                continue;
            };
            if !serves(records[pc + 1].handler, opc::LoadConst, ACC_NONE)
                || ![ACC_NONE, ACC_B, ACC_C, ACC_PAIR]
                    .into_iter()
                    .any(|acc| serves(records[pc + 2].handler, opc::WasmSelect, acc))
                || !constant.op().is_load_const()
            {
                continue;
            }
            if let Some(fused) = operator_constant_select_handler::<H>(operator.op(), acc) {
                records[pc].handler = fused as *const ();
            }
        }
        // A plain move whose value the next record's i32 load takes as its address runs with it
        // as one record.
        for pc in 0..records.len().saturating_sub(1) {
            if serves(records[pc].handler, opc::Move, ACC_NONE)
                && i32_load(&records, pc + 1).is_some()
                && decoded[pc + 1].c() == decoded[pc].a()
                && let Some(fused) = move_load_handler::<H>(decoded[pc + 1].op(), ACC_NONE)
            {
                records[pc].handler = fused as *const ();
            }
        }
        // A plain i32 store followed by a move runs with it as one record.
        for pc in 0..records.len().saturating_sub(1) {
            let op = decoded[pc].op();
            let Some(acc) = [ACC_NONE, ACC_A, ACC_C].into_iter().find(|&acc| serves(records[pc].handler, op as u16, acc)) else {
                continue;
            };
            if [ACC_NONE, ACC_B].into_iter().any(|acc| serves(records[pc + 1].handler, opc::Move, acc))
                && let Some(fused) = store_move_handler::<H>(op, acc)
            {
                records[pc].handler = fused as *const ();
            }
        }
    }
    // A record's plain jump, with its direction.
    let jump_direction = |handler: *const ()| {
        [false, true].into_iter().find(|&backward| {
            tables[usize::from(backward)][usize::from(ACC_NONE)][opc::Jump as usize]
                .is_some_and(|jump| handler == jump.handler as *const ())
        })
    };
    // A jump whose target is a plain move or add of a small constant runs
    // that instruction itself and jumps past it: the target's successor
    // then sees the accumulator the target would have carried. A table
    // entry stays a plain jump, since tables take the entry's jump without
    // running its record. This runs before the fusions below, which take a
    // following jump's record as a plain jump.
    let entry_jumps = branch_table_entry_records(&decoded);
    let record_bytes = size_of::<LaneInstruction>() as isize;
    for (pc, &instruction) in decoded.iter().enumerate() {
        let target = instruction.imm() as usize;
        if !instruction.op().is_jump()
            || jump_direction(records[pc].handler).is_none()
            || entry_jumps.contains(pc)
            || target + 1 >= records.len()
        {
            continue;
        }
        let absorbed = decoded[target];
        let plain = |op: u16| absorbed.op() as u16 == op && serves(records[target].handler, op, ACC_NONE);
        let backward = target <= pc;
        // In compiled mode an OSR site's backedge must remain a standalone jump record.
        // The lane's `THROUGH` fusion would replace both its handler and jump distance.
        if loop_tier && backward {
            continue;
        }
        let (handler, c) = if plain(opc::Move) {
            (JumpFusions::<H>::THROUGH[0][usize::from(backward)], 0)
        } else if plain(opc::WasmI32AddImmediate)
            && let Ok(step) = i16::try_from(absorbed.imm() as i32)
        {
            (
                JumpFusions::<H>::THROUGH[1][usize::from(backward)],
                step as u16,
            )
        } else {
            continue;
        };
        records[pc] = LaneInstruction {
            handler: handler as *const (),
            operand: LaneOperand {
                jump: (target as isize + 1 - pc as isize) * record_bytes,
            },
            a: absorbed.a(),
            b: absorbed.b(),
            c,
            call_link: std::cell::Cell::new(NO_CALL_LINK),
        };
    }
    // Two plain moves in a row run as one record.
    let mut pc = 0;
    while pc + 1 < records.len() {
        if serves(records[pc].handler, opc::Move, ACC_NONE)
            && serves(records[pc + 1].handler, opc::Move, ACC_NONE)
        {
            // A jump after the pair joins it.
            let jump = records
                .get(pc + 2)
                .and_then(|record| jump_direction(record.handler))
                .filter(|backward| !loop_tier || !backward);
            records[pc].handler = match jump {
                None => lane_move_pair::<H, false, false> as Handler,
                Some(false) => lane_move_pair::<H, true, false>,
                Some(true) => lane_move_pair::<H, true, true>,
            } as *const ();
            pc += 2;
        } else {
            pc += 1;
        }
    }
    // A plain move or add of a constant whose next record jumps runs with
    // that jump as one record.
    for pc in 0..records.len().saturating_sub(1) {
        let plain = |op: u16| serves(records[pc].handler, op, ACC_NONE);
        let add = if plain(opc::Move) {
            false
        } else if plain(opc::WasmI32AddImmediate) {
            true
        } else {
            continue;
        };
        if let Some(backward) = jump_direction(records[pc + 1].handler) {
            // Leave a hot OSR latch's jump record visible to `install_loop_sites`.
            if loop_tier && backward {
                continue;
            }
            records[pc].handler =
                JumpFusions::<H>::THEN[usize::from(add)][usize::from(backward)] as *const ();
        }
    }
    if wasm {
        // A move whose next record is a zero-test jump that carries no register runs with that
        // jump as one record.
        for pc in 0..records.len().saturating_sub(1) {
            let Some(move_acc) = [ACC_NONE, ACC_B]
                .into_iter()
                .position(|acc| serves(records[pc].handler, opc::Move, acc))
            else {
                continue;
            };
            if let Some((zero, backward)) = plain_zero_jump(records[pc + 1].handler) {
                records[pc].handler = MoveZeroJumps::<H>::HANDLERS[zero][backward][move_acc] as *const ();
            }
        }
    }
    if wasm {
        // An f64 arithmetic record whose result the next f64 operator takes
        // through the accumulator runs with it as one record; pairs tile a
        // chain from its start.
        let mut pc = 0;
        while pc + 1 < records.len() {
            let instruction = decoded[pc];
            let next = decoded[pc + 1];
            let pair = (|| {
                if !next.op().is_wasm_f64_binary() {
                    return None;
                }
                let second = float_arithmetic(next.op(), next.imm())?;
                let left_of = |records: &[LaneInstruction]| {
                    [ACC_B, ACC_C]
                        .into_iter()
                        .find(|acc| {
                            records[pc + 1].handler
                                == FloatArithmetic::<H>::HANDLERS[1][usize::from(second)]
                                    [usize::from(*acc)] as *const ()
                        })
                        .map(|acc| acc == ACC_B)
                };
                if instruction.op().is_wasm_f64_load() {
                    let plain = tables[0][usize::from(ACC_NONE)][opc::WasmF64Load as usize]?;
                    if records[pc].handler != plain.handler as *const () {
                        return None;
                    }
                    let left = left_of(&records)?;
                    // An arithmetic whose result the record after it stores
                    // (`mem[x] += v`) joins as well.
                    let updates =
                        pc + 2 < records.len() && usize::from(second) < FLOAT_PAIR_FIRSTS && {
                            let store = decoded[pc + 2];
                            store.op().is_wasm_f64_store()
                                && store.a() == next.a()
                                && [ACC_NONE, ACC_A]
                                    .into_iter()
                                    .any(|acc| serves(records[pc + 2].handler, opc::WasmF64Store, acc))
                        };
                    if updates {
                        return Some((
                            FloatPairs::<H>::UPDATES[usize::from(second)][usize::from(left)],
                            3,
                        ));
                    }
                    return Some((
                        FloatPairs::<H>::LOADS[usize::from(second)][usize::from(left)],
                        2,
                    ));
                }
                if !instruction.op().is_wasm_f64_binary() {
                    return None;
                }
                let first = float_arithmetic(instruction.op(), instruction.imm())?;
                if usize::from(first) >= FLOAT_PAIR_FIRSTS {
                    return None;
                }
                let field = FUSED_ACC_FIELDS.iter().position(|acc| {
                    records[pc].handler
                        == FloatArithmetic::<H>::HANDLERS[1][usize::from(first)][usize::from(*acc)]
                            as *const ()
                })?;
                let left = left_of(&records)?;
                Some((
                    FloatPairs::<H>::HANDLERS[usize::from(first)][usize::from(second)]
                        [usize::from(left)][field],
                    2,
                ))
            })();
            // An f64 arithmetic whose result the next record stores, when only
            // the arithmetic reaches that store.
            let pair = pair.or_else(|| {
                let first = float_arithmetic(instruction.op(), instruction.imm())?;
                // The fused record writes the arithmetic's result itself, so the
                // store may read it plainly or through the accumulator.
                let store_runs = [ACC_NONE, ACC_A]
                    .into_iter()
                    .any(|acc| serves(records[pc + 1].handler, opc::WasmF64Store, acc));
                if !instruction.op().is_wasm_f64_binary()
                    || usize::from(first) >= FLOAT_PAIR_FIRSTS
                    || !next.op().is_wasm_f64_store()
                    || next.a() != instruction.a()
                    || entries.contains(pc + 1)
                    || !store_runs
                {
                    return None;
                }
                let field = FUSED_ACC_FIELDS.iter().position(|acc| {
                    records[pc].handler
                        == FloatArithmetic::<H>::HANDLERS[1][usize::from(first)][usize::from(*acc)]
                            as *const ()
                })?;
                Some((FloatPairs::<H>::STORES[usize::from(first)][field], 2))
            });
            match pair {
                Some((fused, span)) => {
                    records[pc].handler = fused as *const ();
                    pc += span;
                }
                None => pc += 1,
            }
        }
        // A dispatch head (an add of a constant fused with the load and table
        // after it) reads the register both take from the accumulator when every
        // edge into it carries that register there, as an interpreter's latches
        // carry its program counter.
        let unfused = |records: &[LaneInstruction], from: usize, to: usize| {
            (from..=to).all(|pc| records[pc].handler == selected[pc])
        };
        // The register the record at `pc` carries as the accumulator when it
        // falls through, if it runs only itself and nothing fused runs into it.
        let carried_through = |records: &[LaneInstruction], pc: usize| {
            unfused(records, pc.saturating_sub(FUSION_REACH), pc)
                .then_some(produced[pc])
                .flatten()
        };
        // The register an edge into `target` carries, per edge; `None` when an
        // edge carries none (or one this analysis does not follow).
        // The carrying variant of the zero-test jump `handler`, if it is one.
        let carrying_zero_jump = |handler: *const ()| {
            let plain = ZeroJumps::<H, false>::HANDLERS
                .as_flattened()
                .as_flattened();
            let carrying = ZeroJumps::<H, true>::HANDLERS.as_flattened().as_flattened();
            plain
                .iter()
                .position(|&plain| handler == plain as *const ())
                .map(|index| carrying[index])
        };
        let edges_carry = |records: &[LaneInstruction], target: usize| -> Option<u16> {
            let mut carried: Option<u16> = None;
            let mut agree = |register: Option<u16>| match (register, carried) {
                (None, _) => false,
                (Some(register), None) => {
                    carried = Some(register);
                    true
                }
                (Some(register), Some(known)) => register == known,
            };
            if target > 0 && !exits[target - 1] {
                use crate::bytecode::ControlFlowLayout as Flow;
                match decoded[target - 1]
                    .op()
                    .control_flow_layout()
                {
                    Flow::Fallthrough => {
                        if !agree(carried_through(records, target - 1)) {
                            return None;
                        }
                    }
                    Flow::Jump | Flow::BranchTable | Flow::Terminal => {}
                    // A call's return or a branch not taken carries no register.
                    Flow::Call | Flow::ConditionalJump => return None,
                }
            }
            for (pc, packed) in function.code.iter().enumerate() {
                let instruction = function.widened(*packed);
                if instruction.op().immediate_role() != ImmediateRole::JumpTarget {
                    continue;
                }
                let jump = instruction.imm() as usize;
                let through = JumpFusions::<H>::THROUGH
                    .iter()
                    .flatten()
                    .any(|&handler| records[pc].handler == handler as *const ());
                if through {
                    // The record runs its target and lands after it.
                    if jump + 1 == target
                        && !agree(Some(decoded[jump].a()))
                    {
                        return None;
                    }
                    continue;
                }
                if jump != target {
                    continue;
                }
                // A zero-test jump can carry any register (`ZeroJumps`).
                if carrying_zero_jump(records[pc].handler).is_some() {
                    continue;
                }
                if !instruction.op().is_jump() || entry_jumps.contains(pc) || entries.contains(pc) || pc == 0 {
                    return None;
                }
                let then = JumpFusions::<H>::THEN
                    .iter()
                    .flatten()
                    .any(|&handler| records[pc - 1].handler == handler as *const ());
                let pair = pc >= 2
                    && [true, false].into_iter().any(|backward| {
                        records[pc - 2].handler
                            == if backward {
                                lane_move_pair::<H, true, true> as Handler
                            } else {
                                lane_move_pair::<H, true, false> as Handler
                            } as *const ()
                    });
                // Entering a pair's second move runs that move's own record.
                if pair && !then && entries.contains(pc - 1) && carried_through(records, pc - 1).is_none() {
                    return None;
                }
                let register = if then || pair {
                    Some(decoded[pc - 1].a())
                } else if jump_direction(records[pc].handler).is_some() {
                    carried_through(records, pc - 1)
                } else {
                    None
                };
                if !agree(register) {
                    return None;
                }
            }
            carried
        };
        for pc in 0..records.len().saturating_sub(1) {
            let add = decoded[pc];
            let load = decoded[pc + 1];
            let Some(head) = load_table_handler::<H>(load.op(), ACC_NONE, true) else {
                continue;
            };
            if records[pc].handler != head as *const ()
                || load.c() != add.b()
                || add.a() == add.b()
                || edges_carry(&records, pc) != Some(add.b())
            {
                continue;
            }
            if let Some(carried) = load_table_handler::<H>(load.op(), ACC_C, true) {
                records[pc].handler = carried as *const ();
                reads_accumulator[pc] = true;
                accumulator_registers[pc] = add.b();
                for (jump, packed) in function.code.iter().enumerate() {
                    let instruction = function.widened(*packed);
                    if instruction.op().immediate_role() == ImmediateRole::JumpTarget
                        && instruction.imm() as usize == pc
                        && let Some(carrying) = carrying_zero_jump(records[jump].handler)
                    {
                        records[jump].handler = carrying as *const ();
                        records[jump].c = add.b();
                    }
                }
            }
        }
        // A move-and-load head whose every incoming edge carries the moved register reads it from
        // the accumulator (a pointer walk carried around its loop); a latch of store, move and
        // zero-test jump on that register, right after the load, tests and carries the register
        // the load leaves there.
        for pc in 0..records.len().saturating_sub(1) {
            let (moving, load) = (decoded[pc], decoded[pc + 1]);
            let Some(head) = move_load_handler::<H>(load.op(), ACC_NONE) else {
                continue;
            };
            if !ACCUMULATOR
                || records[pc].handler != head as *const ()
                || moving.a() == moving.b()
                || edges_carry(&records, pc) != Some(moving.b())
            {
                continue;
            }
            let Some(carried) = move_load_handler::<H>(load.op(), ACC_B) else {
                continue;
            };
            records[pc].handler = carried as *const ();
            reads_accumulator[pc] = true;
            accumulator_registers[pc] = moving.b();
            for (jump, packed) in function.code.iter().enumerate() {
                let instruction = function.widened(*packed);
                if instruction.op().immediate_role() != ImmediateRole::JumpTarget
                    || instruction.imm() as usize != pc
                {
                    continue;
                }
                let Some(carrying) = carrying_zero_jump(records[jump].handler) else {
                    continue;
                };
                let latch = plain_zero_jump(records[jump].handler);
                records[jump].handler = carrying as *const ();
                records[jump].c = moving.b();
                // The loop's load, store, move and latch in a row: the load leaves the walked
                // register in the accumulator for the latch to test and carry.
                if let Some((zero, backward)) = latch
                    && jump == pc + 4
                    && instruction.a() == moving.b()
                    && load.a() == moving.b()
                    && !entries.contains(pc + 1)
                    && !entries.contains(pc + 2)
                    && !entries.contains(pc + 3)
                    && decoded[pc + 3].op().is_move()
                    && let Some(store_op) = Some(decoded[pc + 2].op())
                    && let Some(fused) = store_move_handler::<H>(store_op, ACC_NONE)
                    && records[pc + 2].handler == fused as *const ()
                    && let Some(latch) = store_move_jump_handler::<H>(store_op, zero == 1, backward == 1)
                {
                    records[pc + 2].handler = latch as *const ();
                    reads_accumulator[pc + 2] = true;
                    accumulator_registers[pc + 2] = moving.b();
                }
            }
        }
        // A bit-field extraction and a following i32 operator run as one record.
        for pc in 0..records.len().saturating_sub(1) {
            let second = decoded[pc + 1];
            let Some(acc) = [ACC_NONE, ACC_B]
                .into_iter()
                .find(|&acc| serves(records[pc].handler, opc::WasmI32ShiftRightUnsignedAndImmediate, acc))
            else {
                continue;
            };
            if !decoded[pc].op().is_wasm_i32_shift_right_unsigned_and_immediate()
                || ![ACC_NONE, ACC_B, ACC_C].into_iter().any(|acc| serves(records[pc + 1].handler, second.op() as u16, acc))
            {
                continue;
            }
            if let Some(fused) = bit_field_then_handler::<H>(second.op(), acc) {
                records[pc].handler = fused as *const ();
            }
        }
        // An immediate equality jump that falls through to a plain i32 load runs with it as one
        // record (which reads the address from its register, written whether or not the
        // accumulator also holds it).
        for pc in 0..records.len().saturating_sub(1) {
            let jump = decoded[pc];
            if !matches!(jump.op().class(), Class::WasmJumpI32EqualImmediate | Class::WasmJumpI32NotEqualImmediate)
                || i32_load(&records, pc + 1).is_none()
            {
                continue;
            }
            let Some((backward, acc)) = plain_served(records[pc].handler, jump.op() as u16, &[ACC_NONE, ACC_A]) else {
                continue;
            };
            if let Some(fused) = compare_jump_load_handler::<H>(jump.op(), decoded[pc + 1].op(), backward, acc) {
                records[pc].handler = fused as *const ();
            }
        }
        // Two i32 adds, or an add and a counted loop's step and test, run as one record; other
        // fusions take their records first.
        for pc in 0..records.len().saturating_sub(1) {
            let (first, second) = (decoded[pc], decoded[pc + 1]);
            let Some(acc) = [ACC_NONE, ACC_B, ACC_C].into_iter().find(|&acc| serves(records[pc].handler, first.op() as u16, acc))
            else {
                continue;
            };
            if !matches!(first.op().class(), Class::WasmI32AddRegister | Class::WasmI32AddImmediate) {
                continue;
            }
            let Some((backward, _)) = plain_served(records[pc + 1].handler, second.op() as u16, &[ACC_NONE, ACC_B, ACC_C])
            else {
                continue;
            };
            if let Some(fused) = add_pair_handler::<H>(first.op(), second.op(), backward, acc) {
                records[pc].handler = fused as *const ();
            }
        }
        // A fused record that runs a following zero-test jump itself carries its own result when
        // the jump is taken; where the jump now carries another register to a head reading it
        // (`carrying_zero_jump`), that record runs only its own instruction again.
        for jump in 1..records.len() {
            if !ZeroJumps::<H, true>::HANDLERS
                .as_flattened()
                .as_flattened()
                .iter()
                .any(|&carrying| records[jump].handler == carrying as *const ())
            {
                continue;
            }
            let carried = records[jump].c;
            let before = jump - 1;
            let move_jump = MoveZeroJumps::<H>::HANDLERS
                .as_flattened()
                .as_flattened()
                .iter()
                .any(|&fused| records[before].handler == fused as *const ());
            let load_jump = (0..2).any(|zero| {
                (0..2).any(|backward| {
                    [ACC_NONE, ACC_C].into_iter().any(|acc| {
                        load_jump_handler::<H>(decoded[before].op(), acc, zero == 1, backward == 1)
                            .is_some_and(|fused| records[before].handler == fused as *const ())
                    })
                })
            });
            if (move_jump || load_jump) && decoded[before].a() != carried {
                records[before].handler = selected[before];
            }
        }
    }
    specialize_register_operands::<H>(&decoded, kind, constants, &mut records);
    specialize_updates::<H>(&mut records);
    specialize_updated_index_reads::<H>(&mut records);
    specialize_updated_index_operators::<H>(&mut records);
    specialize_negated_instanceof::<H>(&mut records);
    specialize_frame_locals::<H>(function, &mut records);
    specialize_captures::<H>(&mut records);
    // A Wasm view's records take no JavaScript context (`script_handler!`): it has no environment windows.
    let environment_window = (kind != crate::bytecode::ProgramKind::Wasm)
        .then(|| specialize_environment_window::<H>(function, &decoded, &mut records)).flatten();
    let (loops, osr_rejections) = if loop_tier && kind != crate::bytecode::ProgramKind::Wasm {
        install_loop_sites::<H>(
            function_id,
            function,
            &decoded,
            constants,
            sites,
            live,
            (diagnostics, tiers),
            &mut records,
        )
    } else {
        Default::default()
    };
    // The fused records are script handlers; Wasm bodies run none.
    if !wasm {
        specialize_load_branch_pairs::<H>(&mut records);
        specialize_update_jumps::<H>(&decoded, &mut records);
        specialize_nullish_back_edges::<H>(&decoded, &mut records);
        specialize_update_back_edges::<H>(&decoded, &mut records);
        specialize_store_moves::<H>(&mut records);
        specialize_operator_pairs::<H>(&decoded, &function.handlers, &mut records, live().map(|masks| &**masks));
        specialize_int32_truncations::<H>(&mut records, live().map(|masks| &**masks));
        specialize_raw_operators::<H>(&decoded, &function.handlers, &mut records, live().map(|masks| &**masks));
        specialize_typed_addresses::<H>(&mut records);
        specialize_capture_updates::<H>(&mut records);
        specialize_constant_returns::<H>(&mut records);
        specialize_script_calls::<H>(&mut records, function.undefined_register);
        specialize_proved_arrays::<H>(&decoded, &mut records, &raw_results::raw_result_triples(&decoded, &function.handlers, || live().map(|masks| &**masks)));
        specialize_moved_index_reads::<H>(&mut records);
        specialize_value_jumps::<H>(&decoded, &mut records, live().map(|masks| &**masks));
        specialize_array_literals::<H>(&decoded, &mut records);
    }
    // Loop kernels take their test records last, keeping each record's final handler.
    let loop_kernels = if !wasm && (!loop_tier || crate::jit_mode::base_only()) {
        loop_kernel::install_loop_kernels::<H>(&decoded, constants, function, &exits, &mut records)
    } else {
        Box::default()
    };
    // A record reads the accumulator its predecessor produced only when control reaches it
    // from that predecessor running its own handler. A fusion replaces a record's handler, or
    // runs records ahead of it and lands past them, without carrying what the replaced or
    // skipped producers wrote (a fused postfix update skips its `IncDec` row), so a plain
    // accumulator reader within reach of any fused record reads its operand from the register.
    if !wasm {
        const FUSED_REACH: usize = 6;
        let changed: Vec<bool> = records.iter().zip(&selected).map(|(record, &selected)| record.handler != selected).collect();
        for pc in 1..records.len() {
            if !changed[pc.saturating_sub(FUSED_REACH)..pc].iter().any(|&changed| changed) {
                continue;
            }
            let op = decoded[pc].op() as u16;
            let Some((backward, _)) = plain_served(records[pc].handler, op, &[ACC_A, ACC_B, ACC_C, ACC_PAIR]) else { continue };
            if let Some(plain) = tables[usize::from(backward)][usize::from(ACC_NONE)].get(usize::from(op)).copied().flatten() {
                records[pc].handler = plain.handler as *const ();
            }
        }
    }
    let min_run = if closes_loop(&decoded, &exits) {
        LANE_ENTRY_MIN_RUN
    } else {
        LANE_ENTRY_MIN_CALL_RUN
    };
    // A resumed JavaScript loop body's straight tail jumps back to its head, so its run
    // continues there; a Wasm body resumes nowhere, and following its jumps only made more
    // of its PCs entries, whose lane runs a `return_call` chain left at once (TOD-19:
    // `return_call_ref.wast` 510 -> 797 ms).
    let runs = lane_runs_ahead(&decoded, &exits, min_run, !wasm);
    let mut entries = vec![0u64; runs.len().div_ceil(u64::BITS as usize)];
    for (pc, (run, reads)) in runs.iter().zip(&reads_accumulator).enumerate() {
        if *run >= min_run && !reads {
            entries[pc / u64::BITS as usize] |= 1 << (pc % u64::BITS as usize);
        }
    }
    let entries = entries.into_boxed_slice();
    let returns_from_entry = reads_accumulator.first() == Some(&false) && entry_run_returns(&decoded, &exits);
    let activation = ActivationShape::of(function);
    let hinted_records = |names: bool| -> Box<[u32]> {
        decoded
            .iter()
            .enumerate()
            .filter(|&(pc, instruction)| {
                holds_field_hint(instruction.op())
                    && is_global_name_access(instruction.op()) == names
                    && !loops.iter().any(|site| site.hookable && site.header as usize == pc)
            })
            .map(|(pc, _)| pc as u32)
            .collect()
    };
    let (field_records, name_records) = (hinted_records(false), hinted_records(true));
    let string_case_filters = string_case_filter::specialize::<H>(heap, constants, &decoded, &mut records);
    let records = Records::new(records, decoded.iter().fold(false, |seen, instruction| seen || has_operand_feedback(instruction.op())));
    let first = records.base();
    // The first loop closing at a backedge owns it, as a front-to-back search would find it.
    let mut loop_at_backedge: Vec<(u32, u32)> = loops.iter().enumerate().map(|(index, site)| (site.backedge, index as u32)).collect();
    loop_at_backedge.sort_unstable();
    loop_at_backedge.dedup_by_key(|&mut (backedge, _)| backedge);
    LaneView {
        records,
        entries,
        tiers,
        memory_register,
        activation,
        target_body: std::cell::OnceCell::new(),
        _string_case_filters: string_case_filters,
        environment_window,
        returns_from_entry,
        loops,
        loop_at_backedge: loop_at_backedge.into_boxed_slice(),
        vector_regions,
        _loop_kernels: loop_kernels,
        start: std::cell::Cell::new(first),
        prologue: std::cell::UnsafeCell::new(LaneInstruction {
            handler: std::ptr::null(),
            operand: LaneOperand { imm: 0 },
            a: 0,
            b: 0,
            c: 0,
            call_link: std::cell::Cell::new(NO_CALL_LINK),
        }),
        tier_direct: std::cell::Cell::new(None),
        tier: std::cell::OnceCell::new(),
        entry: super::compiled::entry_cell::EntryCell::new(),
        accumulator_registers: accumulator_registers.into_boxed_slice(),
        plain_backward_jump_sites: decoded
            .iter()
            .enumerate()
            .filter(|(pc, instruction)| instruction.op().is_jump() && instruction.jump_target() <= *pc as u32)
            .count(),
        osr_rejections: (!osr_rejections.is_empty())
            .then(|| osr_rejections.into_boxed_slice()),
        field_records,
        name_records,
    }
}

/// Whether a record holds an own-field hint (`LaneInstruction::field_hint`) in a `field`
/// operand: every field read or store's of its receiver, and a global name access's or top-level
/// `var` capture read's of the global object (`lane_load_name_bound`, `lane_load_root_var`).
fn holds_field_hint(op: Op) -> bool {
    op.is_field_store() || op.is_get_field() || op.is_load_capture() || is_global_name_access(op)
}

/// Whether an instruction is a by-name load (`LOAD_NAME`) or store, whose hint a global
/// lexical declaration clears (`LaneView::clear_name_hints`).
fn is_global_name_access(op: Op) -> bool {
    op.traits().has(crate::bytecode::Traits::GLOBAL_NAME_ACCESS)
}

/// Whether an instruction's record leaves its `call_link` unread: any but a call's, whose
/// handlers keep their target hint there (`linked_script_call_entry`).
fn holds_no_call_link(op: Op) -> bool {
    !op.traits().has(crate::bytecode::Traits::CALL_LINK)
}

/// Gives each backward `Jump` whose loop the shared compiler admits (`analyze_osr_region`) the
/// record that counts it and enters its native code (`lane_loop_jump`). Runs after every
/// other pass, which read a jump record's distance from its operand.
fn install_loop_sites<'live, H: Host>(
    function_id: u32,
    function: &Function,
    decoded: &[WideInstruction],
    constants: &[Value],
    sites: &[crate::bytecode::FieldSite],
    live: &dyn Fn() -> Option<&'live std::rc::Rc<crate::compile::liveness::RegisterMasks>>,
    (diagnostics, tiers): (bool, &'static Tiers),
    records: &mut [LaneInstruction],
) -> (Box<[LoopSite]>, Vec<(super::compiled::RegionRejection, usize)>) {
    let backward = lane_jump_always::<H, true> as Handler as *const ();
    let table_entries = branch_table_entry_records(decoded);
    // A fused record ahead of a jump runs that jump itself, reading its offset from the jump's
    // record (`JumpFusions::THEN`, a move pair with its jump): a site there would replace the
    // offset those records read with the site (the eslint npm scenario under --jit jumped to
    // a site address read as an offset).
    let fused_into = |pc: usize| {
        let then = pc >= 1
            && JumpFusions::<H>::THEN
                .iter()
                .flatten()
                .any(|&handler| records[pc - 1].handler == handler as *const ());
        let pair = pc >= 2
            && [lane_move_pair::<H, true, false> as Handler, lane_move_pair::<H, true, true>]
                .iter()
                .any(|&handler| records[pc - 2].handler == handler as *const ());
        // A branch table takes its entry's jump offset the same way (`lane_branch_table`):
        // babel-minify-wtb's generator `switch` under --jit jumped to a site read as an offset.
        then || pair || table_entries.contains(pc)
    };
    // The masks are derived for the first loop site only: a body without a backward jump
    // needs none, and every view under a loop tier had derived them (npm scenarios under
    // --jit: axios -3.6%, playwright -2.5% instructions).
    let masks = std::cell::OnceCell::new();
    let live = || *masks.get_or_init(live);
    let mut rejections = Vec::new();
    let sites: Vec<(usize, LoopSite)> = (0..records.len())
        .filter(|pc| records[*pc].handler == backward && decoded[*pc].op().is_jump() && !fused_into(*pc))
        .map(|pc| {
            let header = decoded[pc].jump_target();
            let (region, promotion_only, analysis_failure, call_boundary_pcs) = match super::compiled::analyze_osr_region_detailed(
                function,
                decoded,
                constants,
                sites,
                live(),
                header,
                pc as u32, super::compiled::MethodCalls::Inliner,
            ) {
                Ok(region) => {
                    let call_boundary_pcs = region.call_boundary_pcs();
                    (std::cell::OnceCell::from(region), false, None, call_boundary_pcs)
                }
                // A call may run inlined: the site makes its region once it is hot.
                Err(failure)
                    if failure.is_call_boundary() && live().is_some() =>
                {
                    (
                        std::cell::OnceCell::new(),
                        false,
                        Some(failure),
                        vec![failure.pc],
                    )
                }
                Err(failure) => {
                    let reason = failure.reason;
                    if diagnostics {
                        if let Some((_, count)) =
                            rejections.iter_mut().find(|(existing, _)| *existing == reason)
                        {
                            *count += 1;
                        } else {
                            rejections.push((reason, 1));
                        }
                    }
                    // A loop the region analysis rejects keeps its site, diagnostics or not: its
                    // function's lane body may run it (`lane_loop_retire`), and the
                    // site retires to the plain jump where none does. A diagnostics run tiers
                    // as any other.
                    (std::cell::OnceCell::new(), false, Some(failure), Vec::new())
                }
            };
            (
                pc,
                LoopSite {
                    function: function_id,
                    promotion_only,
                    analysis_failure,
                    call_boundary_pcs: call_boundary_pcs.into_boxed_slice(),
                    region,
                    inline_region: std::cell::OnceCell::new(),
                    header,
                    backedge: pc as u32,
                    jump: records[pc].jump(),
                    header_handler: std::cell::Cell::new(std::ptr::null()),
                    hookable: holds_no_call_link(decoded[header as usize].op()),
                    taken: std::cell::Cell::new(0),
                    needed: std::cell::Cell::new(tiers.loops.warmup_taken),
                    entering: std::cell::Cell::new(true),
                    declines_in_row: std::cell::Cell::new(0),
                    skipped_entries: std::cell::Cell::new(0),
                    diagnostics,
                    tiers,
                    lane_backedge_count: std::cell::Cell::new(0),
                    native_entry_attempts: std::cell::Cell::new(0),
                    native_region_runs: std::cell::Cell::new(0),
                    tier_ups: std::cell::Cell::new(0),
                    body_runs: std::cell::Cell::new(0),
                    entry_guard_misses: std::cell::Cell::new(0),
                    native_exits: std::cell::Cell::new(0),
                    widenings: std::cell::Cell::new(0),
                    compile_attempts: std::cell::Cell::new(0),
                    compile_successes: std::cell::Cell::new(0),
                    tier: std::cell::RefCell::default(), body: std::cell::RefCell::new(LoopBody::initial(tiers)), body_seen: std::cell::Cell::new(0), body_due: std::cell::Cell::new(0), body_offered: std::cell::Cell::new(false),
                },
            )
        })
        .collect();
    let mut sites = sites;
    // BaseJIT's stencils run a loop the interpreter's kernel takes slower than the kernel does:
    // under `--b-jit` that loop keeps no site, so its kernel runs it (`install_loop_kernels`).
    if crate::jit_mode::base_only() {
        sites.retain(|(pc, site)| !loop_kernel::LoopKernel::accepts(decoded, constants, function, site.header as usize, *pc));
    }
    let headers: Vec<u32> = sites.iter().map(|(_, site)| site.header).collect();
    for (pc, site) in &mut sites {
        // The header names its site by the distance to the site's jump (`lane_header_site`).
        site.hookable &= headers.iter().filter(|header| **header == site.header).count() == 1
            && u16::try_from(*pc - site.header as usize).is_ok_and(|distance| distance < NO_CALL_LINK);
    }
    let pcs: Vec<usize> = sites.iter().map(|(pc, _)| *pc).collect();
    let sites: Box<[LoopSite]> = sites.into_iter().map(|(_, site)| site).collect();
    for (pc, site) in pcs.into_iter().zip(sites.iter()) {
        records[pc].handler = lane_loop_jump::<H> as Handler as *const ();
        records[pc].operand = LaneOperand { site };
        if site.hookable {
            records[site.header as usize].call_link.set((pc - site.header as usize) as u16);
        }
    }
    (sites, rejections)
}

/// The relation jump against the integer constant `index`, and the operand `record.c` holds:
/// the value itself where it fits 16 bits, else its constant-table index.
fn integer_constant_relation_jump<H: Host>(constants: &[Value], operator: u32, index: u16, backward: bool) -> Option<(Handler, u16)> {
    let constant = *constants.get(usize::from(index))?;
    let Some(value) = constant.as_int() else {
        // Another Number (`x < 0.5`) reads from the table too: its integer test declines
        // once, and the site moves to the Number test (`requicken_number_relation`).
        constant.as_number()?;
        return Some((relation_jump_table_handler::<H>(operator, backward), index));
    };
    Some(match i16::try_from(value) {
        Ok(small) => (relation_jump_handler::<H, true>(operator, backward), small as u16),
        Err(_) => (relation_jump_table_handler::<H>(operator, backward), index),
    })
}

/// Gives each lane record whose operands are registers the handler for that operand shape,
/// with the decoded registers in its fields, so it decodes no operand kinds: `Binary` of a
/// specialized operator (`operator_handler`), also with a constant right operand carried in
/// the record, `GetIndex` and `JumpBinaryFalse`, also with a small integer constant right
/// operand carried in the record.
fn specialize_register_operands<H: Host>(
    decoded: &[WideInstruction],
    kind: crate::bytecode::ProgramKind,
    constants: &[Value],
    records: &mut [LaneInstruction],
) {
    let binary = lane_binary::<H> as Handler as *const ();
    // A Wasm view's `GetIndex` (a multi-value result's read) keeps the general handler: the
    // register form reaches its context through a JavaScript view (`script_handler!`).
    let get_index = if kind == crate::bytecode::ProgramKind::Wasm {
        std::ptr::null()
    } else {
        lane_get_index::<H> as Handler as *const ()
    };
    let forward_test = lane_jump_binary_false::<H, false> as Handler as *const ();
    let backward_test = lane_jump_binary_false::<H, true> as Handler as *const ();
    let unary = unary_handler::<H>() as *const ();
    let returning_binary = lane_returning::<H, RETURNING_BINARY, NOT_LEAF> as Handler as *const ();
    let forward_false_jump = lane_jump_false::<H, false> as Handler as *const ();
    for (pc, &instruction) in decoded.iter().enumerate() {
        // A forward `JumpFalse` of this record's result follows it (`lane_typeof_test_jump`).
        let tested_next = records.get(pc + 1).is_some_and(|next| next.handler == forward_false_jump && next.a == records[pc].a);
        let record = &mut records[pc];
        if record.handler == returning_binary {
            specialize_returning_operator::<H>(instruction, constants, record);
            continue;
        }
        if record.handler == unary {
            if instruction.imm() == crate::bytecode::UNARY_TYPEOF_INDEX {
                record.handler = lane_typeof_index::<H> as Handler as *const ();
            } else if tested_next && let Some(handler) = typeof_test_jump_handler::<H>(instruction.imm()) {
                record.handler = handler as *const ();
            } else if let Some(handler) = unary_operator_handler::<H>(instruction.imm()) {
                record.handler = handler as *const ();
            }
            continue;
        }
        if ![binary, get_index, forward_test, backward_test].contains(&record.handler) {
            continue;
        }
        let (left, right) = (instruction.operand_b(), instruction.operand_c());
        use crate::bytecode::OperandKind::{Constant, Register};
        if record.handler == binary && let Some(handler) = constant_left_operator_handler::<H>(instruction, constants) {
            record.handler = handler as *const ();
            continue;
        }
        let (Some(Register), Some(right_kind)) = (left.kind(), right.kind()) else {
            continue;
        };
        if record.handler == binary {
            if instruction.numeric_local_target().is_some() {
                continue;
            }
            let operator = instruction.binary_operator();
            if operator == INSTANCEOF_OPERATOR && right_kind == Register {
                record.handler = lane_instanceof_value::<H> as Handler as *const ();
                record.b = left.payload();
                record.c = right.payload();
                continue;
            }
            let compares = operator <= super::operations::LAST_COMPARISON_OPERATOR;
            match right_kind {
                Register => {
                    let handler = if compares {
                        lane_relation_value::<H, false> as Handler
                    } else {
                        let Some(handler) = operator_handler::<H, false>(operator) else {
                            continue;
                        };
                        handler
                    };
                    record.handler = handler as *const ();
                    record.c = right.payload();
                }
                Constant => {
                    let Some(constant) = constants.get(usize::from(right.payload())) else {
                        continue;
                    };
                    let strict = super::operations::equality_operator(operator)
                        .is_some_and(|(strict, _)| strict);
                    let handler = if let Some(operator) = u16::try_from(operator).ok().filter(|_| compares) {
                        // The constant takes the immediate's place, so the operator moves to `c`.
                        record.c = operator;
                        if strict && constant.as_number().is_none() {
                            lane_strict_constant_value::<H> as Handler
                        } else {
                            lane_relation_value::<H, true> as Handler
                        }
                    } else {
                        let Some((handler, operand)) = constant_operator_handler::<H>(operator, *constant) else {
                            continue;
                        };
                        record.handler = handler as *const ();
                        record.operand = operand;
                        record.b = left.payload();
                        continue;
                    };
                    record.handler = handler as *const ();
                    record.operand = LaneOperand {
                        constant: *constant,
                    };
                }
                _ => continue,
            }
            record.b = left.payload();
            continue;
        }
        let backward = record.handler == backward_test;
        if record.handler != get_index
            && u32::from(instruction.a()) == INSTANCEOF_OPERATOR
            && right_kind == Register
        {
            let handler: Handler = if backward {
                lane_jump_instanceof_false::<H, true>
            } else {
                lane_jump_instanceof_false::<H, false>
            };
            record.handler = handler as *const ();
            record.b = left.payload();
            record.c = right.payload();
            continue;
        }
        let equality = (record.handler != get_index)
            .then(|| super::operations::equality_operator(u32::from(instruction.a())))
            .flatten();
        let constant = (right_kind == Constant)
            .then(|| constants.get(usize::from(right.payload())).copied())
            .flatten();
        let nullish = equality.zip(constant).and_then(|((strict, negated), constant)| {
            let test = match constant {
                Value::NULL | Value::UNDEFINED if !strict => NULLISH_LOOSE,
                Value::NULL => NULLISH_NULL,
                Value::UNDEFINED => NULLISH_UNDEFINED,
                _ => return None,
            };
            Some(match test {
                NULLISH_NULL => equality_test_handler!(lane_jump_nullish_false::<H, NULLISH_NULL>, backward, negated),
                NULLISH_UNDEFINED => {
                    equality_test_handler!(lane_jump_nullish_false::<H, NULLISH_UNDEFINED>, backward, negated)
                }
                _ => equality_test_handler!(lane_jump_nullish_false::<H, NULLISH_LOOSE>, backward, negated),
            })
        });
        let boolean = equality.zip(constant).and_then(|((strict, negated), constant)| match constant {
            Value::TRUE if strict => Some(equality_test_handler!(lane_jump_boolean_false::<H, true>, backward, negated)),
            Value::FALSE if strict => Some(equality_test_handler!(lane_jump_boolean_false::<H, false>, backward, negated)),
            _ => None,
        });
        if let Some(handler) = nullish.or(boolean) {
            record.handler = handler as *const ();
            record.b = left.payload();
            continue;
        }
        if right_kind == Constant
            && record.handler != get_index
            && super::operations::equality_operator(u32::from(instruction.a()))
                .is_some_and(|(strict, _)| strict)
            && constants
                .get(usize::from(right.payload()))
                .is_some_and(|constant| constant.is_heap())
        {
            let handler: Handler = if backward {
                lane_jump_strict_constant_false::<H, true>
            } else {
                lane_jump_strict_constant_false::<H, false>
            };
            record.handler = handler as *const ();
            record.b = left.payload();
            record.c = right.payload();
            continue;
        }
        if right_kind == Constant
            && record.handler != get_index
            && let Some((handler, operand)) = integer_constant_relation_jump::<H>(constants, u32::from(instruction.a()), right.payload(), backward)
        {
            record.handler = handler as *const ();
            record.b = left.payload();
            record.c = operand;
            continue;
        }
        if right_kind != Register {
            continue;
        }
        let handler: Handler = if record.handler == get_index {
            element_read_row::<H>()
        } else if let Some((true, negated)) = equality {
            equality_test_handler!(lane_jump_strict_equal_false::<H>, backward, negated)
        } else {
            relation_jump_handler::<H, false>(u32::from(instruction.a()), backward)
        };
        record.handler = handler as *const ();
        record.b = left.payload();
        record.c = right.payload();
    }
}

/// Coalesce a plain local load or a direct capture read with the following register/register
/// comparison branch. The second record remains independently callable for branch-table and
/// jump-target entry.
fn specialize_load_branch_pairs<H: Host>(records: &mut [LaneInstruction]) {
    for pc in 0..records.len().saturating_sub(1) {
        let reads_capture = is_row::<H, CAPTURE_READ>(records[pc].handler);
        if !is_row::<H, { opc::LoadLocalPlain }>(records[pc].handler) && !reads_capture {
            continue;
        }
        // A register jump test runs its operator's instantiation (`relation_jump_handler`),
        // and the fused record that operator's (`load_relation_jump_handler`).
        let branch = &records[pc + 1];
        let operator = u32::from(branch.a);
        let Some(backward) = [false, true].into_iter().find(|&backward| {
            branch.handler == relation_jump_handler::<H, false>(operator, backward) as *const ()
        }) else {
            continue;
        };
        records[pc].handler = load_relation_jump_handler::<H>(operator, backward, reads_capture) as *const ();
    }
}

/// Runs each `LoadConst` whose register the next record, a `Return`, returns as one record
/// (`lane_return_constant`). The `Return` record stays for jumps that reach it, and the
/// fused record's general return continues there.
fn specialize_constant_returns<H: Host>(records: &mut [LaneInstruction]) {
    let load = lane_row::<H, { opc::LoadConst }, ACC_NONE, FLAG_UNREAD> as Handler as *const ();
    let ret = lane_return::<H, NOT_LEAF> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        if records[pc].handler == load && records[pc + 1].handler == ret && records[pc + 1].a == records[pc].a {
            records[pc].handler = lane_return_constant::<H, NOT_LEAF> as Handler as *const ();
        }
    }
}

/// Gives each `IncDec` record the handler of its direction, and runs each `ToNumeric` whose
/// result the next record, an `IncDec`, reads as one record (`lane_postfix_update`). The
/// `IncDec` record stays for jumps that reach it; it reads no accumulator, and neither does
/// its successor, since it produces none.
fn specialize_updates<H: Host>(records: &mut [LaneInstruction]) {
    for pc in 0..records.len().saturating_sub(1) {
        let (conversion, update) = (&records[pc], &records[pc + 1]);
        let Some(decrement) = update_direction::<H>(update) else { continue };
        if !is_row::<H, { opc::ToNumeric }>(conversion.handler) || update.b != conversion.a {
            continue;
        }
        let handler: Handler = if decrement {
            lane_postfix_update::<H, true>
        } else {
            lane_postfix_update::<H, false>
        };
        records[pc] = LaneInstruction {
            handler: handler as *const (),
            operand: LaneOperand { imm: 0 },
            a: conversion.a,
            b: conversion.b,
            c: update.a,
            call_link: std::cell::Cell::new(NO_CALL_LINK),
        };
    }
}

/// Gives each `IncDec` whose result the next record, a register `GetIndex`, reads as its
/// index the fused update and read (`lane_update_get_index`). The `GetIndex` record stays as
/// it is, for a jump that enters it and for a read the fused record leaves to it.
fn specialize_updated_index_reads<H: Host>(records: &mut [LaneInstruction]) {
    let read = element_read_row::<H>() as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        let (update, next) = (&records[pc], &records[pc + 1]);
        let Some(decrement) = update_direction::<H>(update) else { continue };
        if next.handler != read || next.c != update.a {
            continue;
        }
        let handler: Handler = if decrement {
            lane_update_get_index::<H, true>
        } else {
            lane_update_get_index::<H, false>
        };
        records[pc].handler = handler as *const ();
    }
}

/// Applies `$apply!` to the arithmetic operators the lane fuses with a neighbouring record
/// (`arithmetic_operator`), as a comma-separated list of `operations` constants.
macro_rules! fused_arithmetic {
    ($apply:ident) => {
        $apply!(ADDITION, SUBTRACTION, MULTIPLICATION, DIVISION)
    };
}
mod raw_results;
mod loop_kernel;

/// The operator of a record running an arithmetic operator on two registers (`lane_operator`
/// or `lane_operator_numbers`) that the lane fuses (`fused_arithmetic`); `None` for any other
/// handler.
fn arithmetic_operator<H: Host>(handler: *const ()) -> Option<u32> {
    macro_rules! find {
        ($($operator:ident),*) => {
            $(if handler == lane_operator::<H, $operator> as Handler as *const ()
                || handler == lane_operator_numbers::<H, $operator> as Handler as *const ()
            {
                return Some($operator);
            })*
        };
    }
    fused_arithmetic!(find);
    None
}

/// The operator of a `lane_operator_double_constant` record (`fused_arithmetic`); `None` for
/// any other handler.
fn double_constant_operator<H: Host>(handler: *const ()) -> Option<u32> {
    macro_rules! find {
        ($($operator:ident),*) => {
            $(if handler == lane_operator_double_constant::<H, $operator> as Handler as *const () {
                return Some($operator);
            })*
        };
    }
    fused_arithmetic!(find);
    None
}

/// Gives each fused update and read (`lane_update_get_index`) whose element the next record,
/// an arithmetic operator on two registers, takes as an operand the fused update, read and
/// operation (`lane_update_get_index_operator`). The read and operator records stay as they
/// are, for a jump that enters them and for a step the fused record leaves to them.
fn specialize_updated_index_operators<H: Host>(records: &mut [LaneInstruction]) {
    let increment = lane_update_get_index::<H, false> as Handler as *const ();
    let decrement = lane_update_get_index::<H, true> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(2) {
        let (update, read, operator) = (&records[pc], &records[pc + 1], &records[pc + 2]);
        if (update.handler != increment && update.handler != decrement)
            || (operator.b != read.a && operator.c != read.a)
        {
            continue;
        }
        let Some(op) = arithmetic_operator::<H>(operator.handler) else {
            continue;
        };
        let decrementing = update.handler == decrement;
        let other = super::operations::number_result_is_commutative(op)
            .then_some(if operator.b == read.a { operator.c } else { operator.b });
        macro_rules! fused {
            ($($operator:ident),*) => {
                match (op, decrementing) {
                    $(($operator, true) => lane_update_get_index_operator::<H, true, $operator> as Handler,
                    ($operator, false) => lane_update_get_index_operator::<H, false, $operator> as Handler,)*
                    _ => continue,
                }
            };
        }
        records[pc].handler = fused_arithmetic!(fused) as *const ();
        if let Some(other) = other {
            records[pc].c = other;
        }
    }
}

/// Gives each arithmetic operator whose result the next arithmetic operator takes as an
/// operand the fused pair (`lane_operator_pair`, or `lane_operator_constant_pair` after a
/// double constant's operator). Records a fused record before them already
/// runs are skipped, so a pair starts where control arrives; both records stay as they are,
/// for jumps and for a step the pair leaves to them.
///
/// Liveness (`live`) selects the variant that leaves a first result dead after the pair
/// unstored on the fast path (`lane_operator_pair`'s `FIRST_DEAD`).
fn specialize_operator_pairs<H: Host>(decoded: &[WideInstruction], handlers: &[crate::bytecode::Handler], records: &mut [LaneInstruction], live: Option<&crate::compile::liveness::RegisterMasks>) {
    let mut pc = 0;
    while pc + 1 < records.len() {
        let covered = fused_width::<H>(records[pc].handler);
        if covered > 1 {
            pc += covered;
            continue;
        }
        let (first, second) = (&records[pc], &records[pc + 1]);
        let constant = double_constant_operator::<H>(first.handler);
        let (Some(left), Some(right)) =
            (constant.or_else(|| arithmetic_operator::<H>(first.handler)), arithmetic_operator::<H>(second.handler))
        else {
            pc += 1;
            continue;
        };
        if second.b != first.a && second.c != first.a {
            pc += 1;
            continue;
        }
        let after = live.and_then(|masks| masks.get(pc + 2));
        let first_dead = second.a == first.a || after.is_some_and(|after| crate::compile::liveness::register_dead(after, usize::from(first.a)));
        let raw = first_dead && constant.is_none() && raw_results::raw_result_allowed(decoded, handlers, live, pc + 1);
        macro_rules! seconds {
            ($first:ident; $($second:ident),*) => {
                match (right, first_dead, constant.is_some(), raw) {
                    $(($second, false, false, _) => lane_operator_pair::<H, $first, $second, false, false> as Handler,
                      ($second, true, false, false) => lane_operator_pair::<H, $first, $second, true, false> as Handler,
                      ($second, true, false, true) => lane_operator_pair::<H, $first, $second, true, true> as Handler,
                      ($second, false, true, _) => lane_operator_constant_pair::<H, $first, $second, false> as Handler,
                      ($second, true, true, _) => lane_operator_constant_pair::<H, $first, $second, true> as Handler,)*
                    _ => unreachable!("an arithmetic operator the lane fuses"),
                }
            };
        }
        macro_rules! pairs {
            ($($first:ident),*) => {
                match left {
                    $($first => seconds!($first; ADDITION, SUBTRACTION, MULTIPLICATION, DIVISION),)*
                    _ => unreachable!("an arithmetic operator the lane fuses"),
                }
            };
        }
        records[pc].handler = fused_arithmetic!(pairs) as *const ();
        pc += 2;
    }
}

/// Gives each addition or subtraction whose result the next record only truncates to an
/// int32 (`| 0` of it, the sum's register dead after: the truncation overwrites it, or
/// liveness says so) the record that writes the truncated wrapping sum
/// (`lane_operator_int32`). The truncation keeps its record for jumps that reach it and for
/// operands the fused record declines.
fn specialize_int32_truncations<H: Host>(records: &mut [LaneInstruction], live: Option<&crate::compile::liveness::RegisterMasks>) {
    use super::operations::{ADDITION, BITWISE_OR, SUBTRACTION};
    let truncation = lane_operator_integer_constant::<H, BITWISE_OR> as Handler as *const ();
    let fusions: [(Handler, Handler); 4] = [
        (lane_operator::<H, ADDITION>, lane_operator_int32::<H, ADDITION, false>),
        (lane_operator::<H, SUBTRACTION>, lane_operator_int32::<H, SUBTRACTION, false>),
        (lane_operator_integer_constant::<H, ADDITION>, lane_operator_int32::<H, ADDITION, true>),
        (lane_operator_integer_constant::<H, SUBTRACTION>, lane_operator_int32::<H, SUBTRACTION, true>),
    ];
    for pc in 0..records.len().saturating_sub(1) {
        let (first, second) = (&records[pc], &records[pc + 1]);
        let truncates = second.handler == truncation && second.b == first.a && second.imm() == 0;
        let Some(&(_, fused)) = fusions.iter().find(|(own, _)| *own as *const () == first.handler) else {
            continue;
        };
        let dead = second.a == first.a
            || live
                .and_then(|masks| masks.get(pc + 2))
                .is_some_and(|after| crate::compile::liveness::register_dead(after, usize::from(first.a)));
        if truncates && dead {
            records[pc].handler = fused as *const ();
        }
    }
}

/// Gives each lone arithmetic record (`lane_operator`, `lane_operator_numbers`) whose result
/// may stay raw (`raw_results::raw_result_allowed`) its raw form (`lane_operator_raw`,
/// `lane_operator_numbers_raw`): as `a*b + c*d + e*f`'s first product, which waits for the
/// next product's pair. A record a fused record before it covers runs inside that record.
fn specialize_raw_operators<H: Host>(decoded: &[WideInstruction], handlers: &[crate::bytecode::Handler], records: &mut [LaneInstruction], live: Option<&crate::compile::liveness::RegisterMasks>) {
    if !handlers.is_empty() || live.is_none() {
        return;
    }
    macro_rules! forms {
        ($($operator:ident),*) => {
            [$((lane_operator::<H, $operator> as Handler, lane_operator_raw::<H, $operator> as Handler),
               (lane_operator_numbers::<H, $operator> as Handler, lane_operator_numbers_raw::<H, $operator> as Handler)),*]
        };
    }
    let forms = fused_arithmetic!(forms);
    for pc in 0..records.len() {
        let Some(&(_, raw)) = forms.iter().find(|(own, _)| *own as *const () == records[pc].handler) else {
            continue;
        };
        if raw_results::raw_result_allowed(decoded, handlers, live, pc) {
            records[pc].handler = raw as *const ();
        }
    }
}

/// Gives each address computation `t = x + K; [u = t >> S;] r = base[u or t]` whose read is
/// a register-operand element read (`element_read_row`) the fused record
/// `lane_typed_address_get`, on the addition. The records after it keep their handlers, for
/// jumps into them and for the cases the fused record leaves to them. The read's base must
/// not be an intermediate, which the fused record writes only after reading the element.
fn specialize_typed_addresses<H: Host>(records: &mut [LaneInstruction]) {
    use super::operations::{ADDITION, SHIFT_RIGHT};
    let add = lane_operator_integer_constant::<H, ADDITION> as Handler as *const ();
    let shift = lane_operator_integer_constant::<H, SHIFT_RIGHT> as Handler as *const ();
    let read = element_read_row::<H>() as *const ();
    let write = element_write_row::<H>() as *const ();
    for pc in 0..records.len() {
        if records[pc].handler != add {
            continue;
        }
        let t = records[pc].a;
        if let (Some(second), Some(third)) = (records.get(pc + 1), records.get(pc + 2))
            && second.handler == shift
            && second.b == t
            && third.handler == read
            && third.c == second.a
            && third.b != t
            && third.b != second.a
        {
            records[pc].handler = lane_typed_address_get::<H, true, UNSEEN_TYPED_KIND> as Handler as *const ();
            continue;
        }
        if let (Some(second), Some(third)) = (records.get(pc + 1), records.get(pc + 2))
            && second.handler == shift
            && second.b == t
            && third.handler == write
            && third.c == second.a
            && ![t, second.a].contains(&third.b)
            && ![t, second.a].contains(&third.a)
        {
            records[pc].handler = lane_typed_address_set::<H, true, UNSEEN_TYPED_KIND> as Handler as *const ();
            continue;
        }
        if let Some(second) = records.get(pc + 1)
            && second.handler == write
            && second.c == t
            && second.b != t
            && second.a != t
        {
            records[pc].handler = lane_typed_address_set::<H, false, UNSEEN_TYPED_KIND> as Handler as *const ();
            continue;
        }
        if let Some(second) = records.get(pc + 1)
            && second.handler == read
            && second.c == t
            && second.b != t
        {
            records[pc].handler = lane_typed_address_get::<H, false, UNSEEN_TYPED_KIND> as Handler as *const ();
        }
    }
}

/// How many records a fused record at the head of a run executes on its fast path: three for
/// `lane_update_get_index_operator`, two for `lane_update_get_index`, one for any other.
fn fused_width<H: Host>(handler: *const ()) -> usize {
    macro_rules! triple {
        ($($operator:ident),*) => {
            [$(lane_update_get_index_operator::<H, false, $operator> as Handler as *const (),
               lane_update_get_index_operator::<H, true, $operator> as Handler as *const ()),*]
        };
    }
    if fused_arithmetic!(triple).contains(&handler) {
        3
    } else if handler == lane_update_get_index::<H, false> as Handler as *const ()
        || handler == lane_update_get_index::<H, true> as Handler as *const ()
    {
        2
    } else {
        1
    }
}

/// The proved records (`specialize_proved_arrays`), each with the generic record it proves
/// the array of and the offset from the record to the one whose `b` names the base (the
/// read's, after a fused update): the one table both directions read (`proved_handler`,
/// The proved records (`specialize_proved_arrays`), each with the generic record it proves
/// the array of and the offset from the record to the one whose `b` names the base (the
/// read's, after a fused update): the one table both directions read (`proved_handler`,
/// `generic_handler`).
fn proved_records<H: Host>() -> impl Iterator<Item = (Handler, Handler, usize)> {
    macro_rules! updated_operators {
        ($($operator:ident),*) => {
            [$((lane_update_get_index_operator::<H, false, $operator> as Handler,
                lane_update_get_index_operator_proved::<H, false, $operator, false> as Handler, 1),
               (lane_update_get_index_operator::<H, true, $operator> as Handler,
                lane_update_get_index_operator_proved::<H, true, $operator, false> as Handler, 1)),*]
        };
    }
    [
        (element_read_row::<H>(), lane_get_index_proved::<H> as Handler, 0),
        (lane_update_get_index::<H, false> as Handler, lane_update_get_index_proved::<H, false> as Handler, 1),
        (lane_update_get_index::<H, true> as Handler, lane_update_get_index_proved::<H, true> as Handler, 1),
        (element_write_row::<H>(), lane_set_index_proved::<H> as Handler, 0),
        (element_write_row::<H>(), lane_set_index_proved_heap::<H> as Handler, 0),
        (lane_set_index_move::<H> as Handler, lane_set_index_move_proved::<H> as Handler, 0),
    ]
    .into_iter()
    .chain(fused_arithmetic!(updated_operators))
}

/// The proved record of generic `handler`, with its base offset (`proved_records`): its raw
/// form (`raw_results::raw_proved_records`) where `raw` and it has one.
fn proved_handler<H: Host>(handler: *const (), raw: bool) -> Option<(Handler, usize)> {
    raw.then(raw_results::raw_proved_records::<H>)
        .into_iter()
        .flatten()
        .chain(proved_records::<H>())
        .find(|&(generic, _, _)| generic as *const () == handler)
        .map(|(_, proved, access)| (proved, access))
}

/// The generic record of proved `handler`, canonical or raw (`proved_records`).
fn generic_handler<H: Host>(handler: *const ()) -> Option<Handler> {
    proved_records::<H>()
        .chain(raw_results::raw_proved_records::<H>())
        .find(|&(_, proved, _)| proved as *const () == handler)
        .map(|(generic, _, _)| generic)
}

/// Gives each element read and store whose register base its innermost loop does not
/// redefine the proved record (`proved_handler`), which reaches the element through the
/// run's proof of the array's storage (`ArrayStorageProofs`) instead of decoding the array:
/// the loop proves the array once, at its first access, and each access after checks only
/// that its slot still proves the base. A base whose proof slot another such base of the
/// same loop takes keeps its record, as their accesses would evict each other's proofs.
/// V8-v7 NavierStokes, whose `lin_solve` row loop reads four elements and stores one each
/// iteration: 795.3 -> 717.4 instructions per element stored, Callgrind, no-JIT static
/// production build, compile cache and startup snapshot off, x86_64 4 vCPU, 2026-11-01;
/// Crypto -4.7% instructions at fixed iterations, the other six within +0.06%.
///
/// The proofs alone decide soundness, whatever control flow does: a base the loop
/// redefines through a definition `defined_register` does not report only misses its
/// proof, and its record takes the generic one. Aggregate profiles count each generic
/// store, so they keep the generic records.
fn specialize_proved_arrays<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction], raw: &crate::bitset::BitSet) {
    if cfg!(feature = "profile-aggregate") {
        return;
    }
    let loops: Vec<std::ops::RangeInclusive<usize>> = decoded
        .iter()
        .enumerate()
        .filter(|(pc, instruction)| {
            instruction.op().immediate_role() == ImmediateRole::JumpTarget && instruction.imm() as usize <= *pc
        })
        .map(|(pc, instruction)| instruction.imm() as usize..=pc)
        .collect();
    // Each candidate: its record, proved handler, base register and innermost loop.
    let candidates: Vec<(usize, Handler, u16, usize)> = (0..records.len())
        .filter_map(|pc| {
            let (proved, access) = proved_handler::<H>(records[pc].handler, raw.contains(pc))?;
            let base = records.get(pc + access)?.b;
            let (index, _) = loops
                .iter()
                .enumerate()
                .filter(|(_, body)| body.contains(&pc) && body.contains(&(pc + access)))
                .min_by_key(|(_, body)| body.end() - body.start())?;
            decoded[loops[index].clone()]
                .iter()
                .all(|instruction| instruction.defined_register() != Some(base))
                .then_some((pc, proved, base, index))
        })
        .collect();
    for &(pc, proved, base, index) in &candidates {
        let slot = crate::heap::ArrayStorageProofs::slot(base);
        let shared = candidates.iter().any(|&(_, _, other, other_index)| {
            other_index == index && other != base && crate::heap::ArrayStorageProofs::slot(other) == slot
        });
        if !shared {
            records[pc].handler = proved as *const ();
        }
    }
}

/// Gives each integer comparison kept as a value (`lane_relation_value`), and each integer
/// bitwise or remainder operator with an integer constant (`lane_operator_integer_constant`),
/// whose next record branches on that value (`lane_jump_false`, `lane_jump_true`) the fused
/// value and branch (`lane_value_jump`). The jump record stays, for jumps that enter it and for
/// the operands the fused record leaves to the value's own path.
fn specialize_value_jumps<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction], live: Option<&crate::compile::liveness::RegisterMasks>) {
    use super::operations::{BITWISE_AND, BITWISE_OR, BITWISE_XOR, REMAINDER, SHIFT_LEFT, SHIFT_RIGHT};
    macro_rules! fused {
        ($constant:literal, $op:expr, $write:literal) => {
            [
                lane_value_jump::<H, $constant, false, false, { $op }, $write> as Handler,
                lane_value_jump::<H, $constant, true, false, { $op }, $write>,
                lane_value_jump::<H, $constant, false, true, { $op }, $write>,
                lane_value_jump::<H, $constant, true, true, { $op }, $write>,
            ]
        };
    }
    macro_rules! integer_constant {
        ($($op:ident),*) => {
            [$((lane_operator_integer_constant::<H, $op> as Handler as *const (), fused!(true, $op, true), fused!(true, $op, false)),)*]
        };
    }
    // Per value handler: the fused records that write the value, and those that may not.
    let values: [(*const (), [Handler; 4], [Handler; 4]); 8] = {
        let [a, b, c, d, e, f] = integer_constant!(BITWISE_AND, BITWISE_OR, BITWISE_XOR, REMAINDER, SHIFT_LEFT, SHIFT_RIGHT);
        let relation = |constant: bool| -> (*const (), [Handler; 4], [Handler; 4]) {
            if constant {
                (lane_relation_value::<H, true> as Handler as *const (), fused!(true, RELATION_VALUE, true), fused!(true, RELATION_VALUE, false))
            } else {
                (lane_relation_value::<H, false> as Handler as *const (), fused!(false, RELATION_VALUE, true), fused!(false, RELATION_VALUE, false))
            }
        };
        [relation(false), relation(true), a, b, c, d, e, f]
    };
    let jumps: [*const (); 4] = [
        lane_jump_false::<H, false> as Handler as *const (),
        lane_jump_false::<H, true> as Handler as *const (),
        lane_jump_true::<H, false> as Handler as *const (),
        lane_jump_true::<H, true> as Handler as *const (),
    ];
    for pc in 0..records.len().saturating_sub(1) {
        let (value, jump) = (&records[pc], &records[pc + 1]);
        if jump.a != value.a {
            continue;
        }
        let Some(&(_, writes, reads)) = values.iter().find(|(handler, _, _)| *handler == value.handler) else {
            continue;
        };
        let Some(index) = jumps.iter().position(|&handler| handler == jump.handler) else {
            continue;
        };
        // Dead past the jump: neither successor of the jump record (the next record, the jump's
        // target) has the value live before it.
        let dead_before = |at: usize| {
            live.and_then(|masks| masks.get(at))
                .is_some_and(|before| crate::compile::liveness::register_dead(before, usize::from(value.a)))
        };
        let target = decoded[pc + 1].imm() as usize;
        let dead = dead_before(pc + 2) && dead_before(target);
        records[pc].handler = if dead { reads[index] } else { writes[index] } as *const ();
    }
}

/// Gives each register `Move` that a proved element read follows (`specialize_proved_arrays`)
/// the fused copy and read (`lane_move_get_index_proved`). The read record stays, for a jump
/// that enters it and for the pair's declined proofs.
fn specialize_moved_index_reads<H: Host>(records: &mut [LaneInstruction]) {
    let copy = lane_row::<H, { opc::Move }, ACC_NONE, FLAG_UNREAD> as Handler as *const ();
    let read = lane_get_index_proved::<H> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        if records[pc].handler == copy && records[pc + 1].handler == read {
            records[pc].handler = lane_move_get_index_proved::<H> as Handler as *const ();
        }
    }
}

/// Gives each `MakeArray` of a literal whose elements are defined by the records right after
/// it, a `DefineArrayElement` of a register value for each index in order (`Allocation::ArrayOf`),
/// the literal made at once (`lane_make_array_elements`). The definitions stay: nothing jumps
/// between them, and a run entered past the `MakeArray` takes them as before.
fn specialize_array_literals<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction]) {
    let make = lane_make_array::<H> as Handler as *const ();
    for pc in 0..records.len() {
        if records[pc].handler == make
            && matches!(Allocation::decode(decoded[pc], &decoded[pc + 1..]), Some((_, Allocation::ArrayOf { .. })))
        {
            records[pc].handler = lane_make_array_elements::<H> as Handler as *const ();
        }
    }
}

/// Gives each backward unconditional jump whose target is an integer update (`lane_row` of `IncDec`),
/// then optionally a register copy of its result (a `Move`'s `lane_row`), then a forward test against a
/// small constant (`lane_jump_binary_false_small`), the fused back edge, update, copy and test
/// (`lane_jump_back_update_small`). The head's records stay, for the loop's entry and for the
/// values the fused record leaves to them.
fn specialize_update_back_edges<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction]) {
    let back = lane_jump_always::<H, true> as Handler as *const ();
    let copy = lane_row::<H, { opc::Move }, ACC_NONE, FLAG_UNREAD> as Handler as *const ();
    for pc in 0..records.len() {
        if records[pc].handler != back {
            continue;
        }
        let head = decoded[pc].imm() as usize;
        let (Some(update), Some(decrement)) = (records.get(head), records.get(head).and_then(|update| update_direction::<H>(update)))
        else {
            continue;
        };
        let moved = records.get(head + 1).is_some_and(|next| next.handler == copy && next.b == update.a);
        let Some(test) = records.get(head + 1 + usize::from(moved)) else {
            continue;
        };
        let operator = u32::from(test.a);
        if test.handler != relation_jump_handler::<H, true>(operator, false) as *const () {
            continue;
        }
        records[pc].handler = update_back_small_handler::<H>(operator, decrement, moved) as *const ();
    }
}

/// Gives each backward unconditional jump whose target is a forward nullish test
/// (`lane_jump_nullish_false`) the fused back edge and test (`lane_jump_back_nullish`). The
/// test record stays, for the loop's entry and for the values it leaves to that record.
fn specialize_nullish_back_edges<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction]) {
    let back = lane_jump_always::<H, true> as Handler as *const ();
    for pc in 0..records.len() {
        if records[pc].handler != back {
            continue;
        }
        let Some(test) = records.get(decoded[pc].imm() as usize) else {
            continue;
        };
        macro_rules! fused {
            ($nullish:expr) => {
                [false, true].into_iter().find_map(|negated| {
                    (test.handler == equality_test_handler!(lane_jump_nullish_false::<H, { $nullish }>, false, negated) as *const ())
                        .then(|| if negated {
                            lane_jump_back_nullish::<H, true, { $nullish }> as Handler
                        } else {
                            lane_jump_back_nullish::<H, false, { $nullish }> as Handler
                        })
                })
            };
        }
        if let Some(handler) = fused!(NULLISH_NULL).or_else(|| fused!(NULLISH_UNDEFINED)).or_else(|| fused!(NULLISH_LOOSE)) {
            records[pc].handler = handler as *const ();
        }
    }
}

/// Gives each `IncDec` that an unconditional jump follows the fusion `update_fusion` makes of it. The
/// jump and test records stay, for a jump that enters them and for the update's own slow path.
fn specialize_update_jumps<H: Host>(decoded: &[WideInstruction], records: &mut [LaneInstruction]) {
    for pc in 0..records.len().saturating_sub(1) {
        let fused = update_fusion::<H>(&records[pc], &records[pc + 1], |offset| records.get(decoded[pc + 1].imm() as usize + offset));
        if let Some(fused) = fused {
            records[pc].handler = fused as *const ();
        }
    }
}

/// The handler of the `IncDec` record `update` that the record `jump` follows, where `jump` is an unconditional
/// jump: the fused update and jump (`lane_inc_dec_jump`), or, when the jump goes back to the loop's forward integer
/// register test (`test`, read only then), the update, jump and test (`lane_inc_dec_loop`). `None` for any other
/// pair. The loader (`specialize_update_jumps`) and a loop site that retires (`lane_loop_retire`) fuse by it, so a
/// declined loop runs what the interpreter's own does.
fn update_fusion<'a, H: Host>(update: &LaneInstruction, jump: &LaneInstruction, at: impl Fn(usize) -> Option<&'a LaneInstruction>) -> Option<Handler> {
    let decrement = update_direction::<H>(update)?;
    let backward = match jump.handler {
        plain if plain == lane_jump_always::<H, true> as Handler as *const () => true,
        plain if plain == lane_jump_always::<H, false> as Handler as *const () => false,
        _ => return None,
    };
    let looped = || -> Option<Handler> {
        let test = at(0).filter(|_| backward)?;
        let operator = u32::from(test.a);
        if test.handler == relation_jump_handler::<H, false>(operator, false) as *const () {
            return Some(update_loop_handler::<H>(operator, decrement, test.b == update.a));
        }
        // A test against a constant in the record.
        if test.handler == relation_jump_handler::<H, true>(operator, false) as *const () {
            return Some(update_small_loop_handler::<H>(operator, decrement));
        }
        // A fused load and test (`specialize_load_branch_pairs`), whose test record follows.
        let operator = u32::from(at(1)?.a);
        [false, true].into_iter()
            .find(|&capture| test.handler == load_relation_jump_handler::<H>(operator, false, capture) as *const ())
            .map(|capture| update_load_loop_handler::<H>(operator, decrement, capture))
    };
    Some(looped().unwrap_or_else(|| update_jump::<H>(decrement, backward)))
}

/// Whether `record`, an `IncDec` running its row (`lane_row`), decrements (its immediate flag);
/// `None` for any other record.
fn update_direction<H: Host>(record: &LaneInstruction) -> Option<bool> {
    is_row::<H, { opc::IncDec }>(record.handler).then(|| record.imm() != 0)
}

/// The row handler (`lane_row`) of an `IncDec` of the direction a fused update's `DECREMENT` names,
/// which the fused record runs where its own fast form does not take the value.
#[inline(always)]
fn inc_dec_row<H: Host, const DECREMENT: bool>() -> Handler {
    if DECREMENT { lane_row::<H, { opc::IncDec }, ACC_NONE, FLAG_SET> } else { lane_row::<H, { opc::IncDec }, ACC_NONE, FLAG_CLEAR> }
}

/// The fused update and jump (`lane_inc_dec_jump`) of an `IncDec` that decrements or not,
/// and a jump backward or forward.
fn update_jump<H: Host>(decrement: bool, backward: bool) -> Handler {
    match (decrement, backward) {
        (false, false) => lane_inc_dec_jump::<H, false, false>,
        (false, true) => lane_inc_dec_jump::<H, false, true>,
        (true, false) => lane_inc_dec_jump::<H, true, false>,
        (true, true) => lane_inc_dec_jump::<H, true, true>,
    }
}

/// Gives each `SetIndex` whose stored value the next record, a register `Move`, copies the
/// fused store and copy (`lane_set_index_move`). The `Move` record stays, for a jump that
/// enters it and for the store's own slow path.
fn specialize_store_moves<H: Host>(records: &mut [LaneInstruction]) {
    let store = element_write_row::<H>() as *const ();
    let copy = lane_row::<H, { opc::Move }, ACC_NONE, FLAG_UNREAD> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        if records[pc].handler == store && records[pc + 1].handler == copy && records[pc + 1].b == records[pc].a {
            records[pc].handler = lane_set_index_move::<H> as Handler as *const ();
        }
    }
}

/// An environment-window record's immediate: its own (a local slot or closure function, at
/// most `ENVIRONMENT_WINDOW_FIELD`) below, the function's register count above.
const ENVIRONMENT_WINDOW_SHIFT: u32 = u16::BITS;
const ENVIRONMENT_WINDOW_FIELD: u32 = (1 << ENVIRONMENT_WINDOW_SHIFT) - 1;

/// An environment-window record's own immediate and the window's register count.
#[inline(always)]
fn environment_window_fields(i: &LaneInstruction) -> (usize, u16) {
    let imm = i.imm();
    ((imm & ENVIRONMENT_WINDOW_FIELD) as usize, (imm >> ENVIRONMENT_WINDOW_SHIFT) as u16)
}

/// Gives a function whose locals an environment activation or a suspended frame's window could
/// hold (`CallPlan::environment_activation`, `CallPlan::suspended_environment`) the local and
/// closure records that read either a
/// frame or such an activation's window (`lane_load_window_local`), each record's
/// immediate also carrying the register count (`environment_window_fields`); the count
/// when every such record took one. Each other record keeps its handler, and a function
/// any record of which cannot keeps all of them.
fn specialize_environment_window<H: Host>(
    function: &Function,
    decoded: &[WideInstruction],
    records: &mut [LaneInstruction],
) -> Option<EnvironmentWindow> {
    if u32::from(function.locals) > u64::BITS
        || (function.arguments_slot.is_some() && !function.reads_passed_arguments_only() && !function.arguments_ride_window())
    {
        return None;
    }
    // A function that resolves names at run time stores and makes closures through the scope
    // its activation carries (`scoped_names`).
    let scoped = function.has_dynamic_scope_access();
    let registers = function.registers;
    // The handlers derivation gives these records alone: a record any other pass gave a
    // handler, such as one carrying an accumulator to the next, keeps the function's.
    let plain = plain_window_handlers::<H>();
    let mut replacements = Vec::new();
    for (pc, &instruction) in decoded.iter().enumerate() {
        match window_record(function, instruction) {
            WindowRecord::Keeps => {}
            WindowRecord::Eval => replacements.push((pc, lane_eval::direct_eval::<H>(), instruction.imm())),
            WindowRecord::Local(own) => {
                let handler = records[pc].handler;
                let row = is_row::<H, { opc::LoadLocalPlain }>(handler) || is_row::<H, { opc::StoreLocalPlain }>(handler);
                if own > ENVIRONMENT_WINDOW_FIELD || !(row || plain.iter().any(|plain| *plain as *const () == handler)) {
                    return None;
                }
                let handler = window_local_handler::<H>(function, instruction.op(), own as usize, scoped);
                replacements.push((pc, handler, own | u32::from(registers) << ENVIRONMENT_WINDOW_SHIFT));
            }
        }
    }
    for (pc, handler, imm) in replacements {
        records[pc].handler = handler as *const ();
        records[pc].operand = LaneOperand { imm };
    }
    Some(EnvironmentWindow {
        locals: function.locals,
        captured: (0..usize::from(function.locals))
            .filter(|slot| function.local_slot_uses_environment(*slot))
            .fold(0, |mask, slot| mask | 1 << slot),
        rest: function.rest,
        self_binding: function.self_binding_slot,
    })
}

/// The capture rows the capture passes fuse (`specialize_captures`, `specialize_capture_updates`,
/// `specialize_load_branch_pairs`) and whose read a fused update falls back to.
const CAPTURE_READ: u16 = opc::LoadCapture;
const CAPTURE_WRITE: u16 = opc::StoreCapture;

/// Gives each capture record its handler by the capture's depth, which the bytecode fixes:
/// a `LoadCapture` past the function's own scope the one that reads remembered walks
/// (`lane_load_outer_capture`), a `StoreCapture` past it the lane's walking store
/// (`lane_store_outer_capture`); a depth-0 store followed by a read of the same capture runs
/// both (`lane_store_capture_load`). The other depth-0 records keep the handlers that read
/// the running function's dense slots.
fn specialize_captures<H: Host>(records: &mut [LaneInstruction]) {
    let load = |handler: *const ()| is_row::<H, CAPTURE_READ>(handler);
    let store = |handler: *const ()| is_row::<H, CAPTURE_WRITE>(handler);
    for pc in 0..records.len() {
        let record = &records[pc];
        let own = ImmediateLayout::capture_depth(record.imm()) == 0;
        let handler: Handler = if load(record.handler) && !own {
            lane_load_outer_capture::<H>
        } else if store(record.handler) && !own {
            lane_store_outer_capture::<H>
        } else if store(record.handler)
            && records.get(pc + 1).is_some_and(|next| load(next.handler) && next.imm() == record.imm())
        {
            lane_store_capture_load::<H>
        } else if let Some(near) = row_near::<H, CAPTURE_READ>(record.handler).or_else(|| row_near::<H, CAPTURE_WRITE>(record.handler)) {
            // Its own scope's capture: the row reads its depth as the zero it is.
            near
        } else {
            continue;
        };
        records[pc].handler = handler as *const ();
    }
    // Two outer reads in a row run as one record; the second keeps its own handler for a
    // jump that enters it and for the pair's misses.
    let outer = lane_load_outer_capture::<H> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        if records[pc].handler == outer && records[pc + 1].handler == outer {
            records[pc].handler = lane_load_outer_capture_pair::<H> as Handler as *const ();
        }
    }
}

/// Gives each own capture's read (`lane_load_capture`) whose value an int32 sum or difference
/// with a constant (`lane_operator_int32`) takes, and whose truncated result the record after
/// stores back to the same capture (`lane_store_capture`, `lane_store_capture_load`), the fused
/// update (`lane_update_capture_int32`) of the form its end takes (`UpdateForm`). The records
/// stay for jumps and for steps the update leaves to them.
fn specialize_capture_updates<H: Host>(records: &mut [LaneInstruction]) {
    use super::operations::{ADDITION, SUBTRACTION};
    let load = |handler: *const ()| is_row::<H, CAPTURE_READ>(handler);
    let store = |handler: *const ()| is_row::<H, CAPTURE_WRITE>(handler);
    let store_load = lane_store_capture_load::<H> as Handler as *const ();
    let add = lane_operator_int32::<H, ADDITION, true> as Handler as *const ();
    let subtract = lane_operator_int32::<H, SUBTRACTION, true> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(3) {
        let (read, operator, truncation, write) = (&records[pc], &records[pc + 1], &records[pc + 2], &records[pc + 3]);
        if !load(read.handler)
            || (operator.handler != add && operator.handler != subtract)
            || operator.b != read.a
            || (!store(write.handler) && write.handler != store_load)
            || write.imm() != read.imm()
            || write.a != truncation.a
        {
            continue;
        }
        let form = if store(write.handler) { UPDATE_STORES } else { UPDATE_LOADS };
        macro_rules! forms {
            ($($form:ident),*) => {
                match (operator.handler == add, form) {
                    $((true, $form) => lane_update_capture_int32::<H, ADDITION, $form> as Handler,
                      (false, $form) => lane_update_capture_int32::<H, SUBTRACTION, $form> as Handler,)*
                    _ => unreachable!("an update form"),
                }
            };
        }
        let handler = forms!(UPDATE_STORES, UPDATE_LOADS);
        records[pc].handler = handler as *const ();
    }
}

/// Gives each frame `LoadLocal` and `StoreLocal` record the handler of its slot's static
/// binding facts (`lane_load_frame_local`): a slot a mapped `arguments` mirrors, or a self
/// binding a store must leave, keeps the general handler.
fn specialize_frame_locals<H: Host>(function: &Function, records: &mut [LaneInstruction]) {
    let load = lane_load_local::<H> as Handler as *const ();
    let store = lane_store_local::<H> as Handler as *const ();
    for record in records.iter_mut() {
        let slot = record.imm() as usize;
        if (record.handler != load && record.handler != store)
            || super::arguments::mapped_arguments_slot(function, slot).is_some()
        {
            continue;
        }
        let environment = function.local_slot_uses_environment(slot);
        let handler: Handler = match (record.handler == load, environment) {
            (true, true) => lane_load_frame_local::<H, true>,
            (true, false) => lane_load_frame_local::<H, false>,
            _ if function.is_self_binding_slot(slot) => continue,
            (false, true) => lane_store_frame_local::<H, true>,
            (false, false) => lane_store_frame_local::<H, false>,
        };
        record.handler = handler as *const ();
    }
}

/// Runs each `instanceof` value record whose result the next record, a `JumpTrue`, tests as
/// one record (`lane_instanceof_jump_true`), with the jump's distance taken from the fused
/// record. The `JumpTrue` record stays for jumps that reach it.
fn specialize_negated_instanceof<H: Host>(records: &mut [LaneInstruction]) {
    let instanceof = lane_instanceof_value::<H> as Handler as *const ();
    let forward = lane_jump_true::<H, false> as Handler as *const ();
    let backward = lane_jump_true::<H, true> as Handler as *const ();
    for pc in 0..records.len().saturating_sub(1) {
        let (test, jump) = (&records[pc], &records[pc + 1]);
        if test.handler != instanceof
            || (jump.handler != forward && jump.handler != backward)
            || jump.a != test.a
        {
            continue;
        }
        let handler: Handler = if jump.handler == backward {
            lane_instanceof_jump_true::<H, true>
        } else {
            lane_instanceof_jump_true::<H, false>
        };
        let distance = jump.jump() + size_of::<LaneInstruction>() as isize;
        records[pc].handler = handler as *const ();
        records[pc].operand = LaneOperand { jump: distance };
    }
}

/// The handler of a specialized `Binary` operator, with a register or (`CONSTANT`) a constant
/// right operand.
/// A `JumpBinaryFalse` integer test handler's operator parameter that names none: the
/// handler reads the operator from the record's `a` field (`relation_operator`).
const RECORD_RELATION: u32 = u32::MAX;

/// `$pick!` of the comparison `$operator` the lane decides with its own instantiation of a
/// jump test, else of `RECORD_RELATION`, whose handler reads the record's operator.
macro_rules! relation_operators {
    ($operator:expr, $pick:ident) => {{
        use oxc_ast::ast::BinaryOperator as B;
        const EQUALITY: u32 = B::Equality as u32;
        const INEQUALITY: u32 = B::Inequality as u32;
        const STRICT_EQUALITY: u32 = B::StrictEquality as u32;
        const STRICT_INEQUALITY: u32 = B::StrictInequality as u32;
        const LESS_THAN: u32 = B::LessThan as u32;
        const LESS_EQUAL: u32 = B::LessEqualThan as u32;
        const GREATER_THAN: u32 = B::GreaterThan as u32;
        const GREATER_EQUAL: u32 = B::GreaterEqualThan as u32;
        const BITWISE_AND: u32 = B::BitwiseAnd as u32;
        const BITWISE_OR: u32 = B::BitwiseOR as u32;
        const BITWISE_XOR: u32 = B::BitwiseXOR as u32;
        match $operator {
            EQUALITY => $pick!(EQUALITY),
            INEQUALITY => $pick!(INEQUALITY),
            STRICT_EQUALITY => $pick!(STRICT_EQUALITY),
            STRICT_INEQUALITY => $pick!(STRICT_INEQUALITY),
            LESS_THAN => $pick!(LESS_THAN),
            LESS_EQUAL => $pick!(LESS_EQUAL),
            GREATER_THAN => $pick!(GREATER_THAN),
            GREATER_EQUAL => $pick!(GREATER_EQUAL),
            // The truth of an integer bitwise result (`integer_test_i32`).
            BITWISE_AND => $pick!(BITWISE_AND),
            BITWISE_OR => $pick!(BITWISE_OR),
            BITWISE_XOR => $pick!(BITWISE_XOR),
            _ => $pick!(RECORD_RELATION),
        }
    }};
}

/// The operator of an integer jump test (`lane_jump_binary_false_registers`,
/// `lane_jump_binary_false_small`): `OP`, fixed when the view was derived
/// (`relation_jump_handler`), else the record's.
#[inline(always)]
fn relation_operator<const OP: u32>(i: &LaneInstruction) -> u32 {
    if OP == RECORD_RELATION { u32::from(i.a) } else { OP }
}

/// The staged comparison of two integers under `operator`, the Int32 arm a handler proves by
/// observing both operands: `None` for any other pair or operator, which the general chain decides.
#[inline(always)]
fn lane_integer_comparison(operator: u32, left: Value, right: Value) -> Option<crate::staged::Comparison> {
    let relation = crate::vm::operations::NumberRelation::from_operator(operator)?;
    (left.as_int().is_some() && right.as_int().is_some())
        .then_some(crate::staged::Comparison::Relation { relation, domain: crate::staged::Domain::Int32 })
}

/// The integer jump test handler of `operator` (`SMALL`: against a small constant, else two
/// registers) that branches `backward` or not: a comparison's own instantiation, which
/// decides it with no dispatch on the operator, else the one reading the record's.
fn relation_jump_handler<H: Host, const SMALL: bool>(operator: u32, backward: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            match (SMALL, backward) {
                (true, true) => lane_jump_binary_false_small::<H, true, { $op }, false> as Handler,
                (true, false) => lane_jump_binary_false_small::<H, false, { $op }, false> as Handler,
                (false, true) => lane_jump_binary_false_registers::<H, true, { $op }> as Handler,
                (false, false) => lane_jump_binary_false_registers::<H, false, { $op }> as Handler,
            }
        };
    }
    relation_operators!(operator, pick)
}

/// `relation_jump_handler` against an integer constant outside the record's 16 bits, read from
/// the program's constants (`lane_small_constant`).
fn relation_jump_table_handler<H: Host>(operator: u32, backward: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            if backward {
                lane_jump_binary_false_small::<H, true, { $op }, true> as Handler
            } else {
                lane_jump_binary_false_small::<H, false, { $op }, true> as Handler
            }
        };
    }
    relation_operators!(operator, pick)
}

/// `requicken_number_relation` of a small-constant jump test, whose out-of-line case reads
/// the operator from the record: the operator instantiation `relation_jump_handler` gave it.
///
/// # Safety
/// As `note_operands`.
unsafe fn requicken_small_number_relation<H: Host, const BACKWARD: bool, const TABLE: bool>(
    cx: *mut LaneContext<H>,
    ip: Ip,
    left: Value,
    right: Value,
) {
    macro_rules! pick {
        ($op:expr) => {
            // SAFETY: the caller's.
            unsafe { requicken_number_relation::<H, BACKWARD, { $op }, true, TABLE>(cx, ip, left, right) }
        };
    }
    // SAFETY: the record is a live record of the running view.
    relation_operators!(u32::from(unsafe { (*ip).a }), pick)
}

/// The fused update, back edge and register test handler (`lane_inc_dec_loop`) of the test's
/// `operator`: as `relation_jump_handler` picks, the comparison's own instantiation; `counter`
/// where the test's left operand is the updated register.
fn update_loop_handler<H: Host>(operator: u32, decrement: bool, counter: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            match (decrement, counter) {
                (true, true) => lane_inc_dec_loop::<H, true, { $op }, true> as Handler,
                (true, false) => lane_inc_dec_loop::<H, true, { $op }, false> as Handler,
                (false, true) => lane_inc_dec_loop::<H, false, { $op }, true> as Handler,
                (false, false) => lane_inc_dec_loop::<H, false, { $op }, false> as Handler,
            }
        };
    }
    relation_operators!(operator, pick)
}

/// The fused back edge, update, copy and small-constant test handler
/// (`lane_jump_back_update_small`) of the test's `operator`.
fn update_back_small_handler<H: Host>(operator: u32, decrement: bool, moved: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            match (decrement, moved) {
                (true, true) => lane_jump_back_update_small::<H, true, true, { $op }> as Handler,
                (true, false) => lane_jump_back_update_small::<H, true, false, { $op }> as Handler,
                (false, true) => lane_jump_back_update_small::<H, false, true, { $op }> as Handler,
                (false, false) => lane_jump_back_update_small::<H, false, false, { $op }> as Handler,
            }
        };
    }
    relation_operators!(operator, pick)
}

/// The fused update, back edge and small-constant test handler (`lane_inc_dec_small_loop`) of
/// the test's `operator`.
fn update_small_loop_handler<H: Host>(operator: u32, decrement: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            if decrement {
                lane_inc_dec_small_loop::<H, true, { $op }> as Handler
            } else {
                lane_inc_dec_small_loop::<H, false, { $op }> as Handler
            }
        };
    }
    relation_operators!(operator, pick)
}

/// The fused update, back edge, load and register test handler (`lane_inc_dec_load_loop`) of
/// the test's `operator`, after a local (`capture` false) or capture read.
fn update_load_loop_handler<H: Host>(operator: u32, decrement: bool, capture: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            match (decrement, capture) {
                (true, true) => lane_inc_dec_load_loop::<H, true, true, { $op }> as Handler,
                (true, false) => lane_inc_dec_load_loop::<H, true, false, { $op }> as Handler,
                (false, true) => lane_inc_dec_load_loop::<H, false, true, { $op }> as Handler,
                (false, false) => lane_inc_dec_load_loop::<H, false, false, { $op }> as Handler,
            }
        };
    }
    relation_operators!(operator, pick)
}

/// The fused load and register jump test handler (`lane_load_jump_binary_false_registers`) of
/// `operator`, after a local (`capture` false) or capture read, branching `backward` or not:
/// as `relation_jump_handler` picks, the comparison's own instantiation.
fn load_relation_jump_handler<H: Host>(operator: u32, backward: bool, capture: bool) -> Handler {
    macro_rules! pick {
        ($op:expr) => {
            match (backward, capture) {
                (true, true) => lane_load_jump_binary_false_registers::<H, true, true, { $op }> as Handler,
                (true, false) => lane_load_jump_binary_false_registers::<H, true, false, { $op }> as Handler,
                (false, true) => lane_load_jump_binary_false_registers::<H, false, true, { $op }> as Handler,
                (false, false) => lane_load_jump_binary_false_registers::<H, false, false, { $op }> as Handler,
            }
        };
    }
    relation_operators!(operator, pick)
}

/// Gives a returning `Binary` record of an arithmetic operator on a register and a register
/// or constant its operator's `lane_returning_operator`, its fields resolved as
/// `specialize_register_operands` resolves a non-returning one's; any other keeps
/// `lane_returning`.
fn specialize_returning_operator<H: Host>(instruction: WideInstruction, constants: &[Value], record: &mut LaneInstruction) {
    use crate::bytecode::OperandKind::{Constant, Register};
    let (left, right) = (instruction.operand_b(), instruction.operand_c());
    if left.kind() != Some(Register) || instruction.numeric_local_target().is_some() {
        return;
    }
    let constant = match right.kind() {
        Some(Register) => None,
        Some(Constant) => match constants.get(usize::from(right.payload())) {
            Some(constant) => Some(*constant),
            None => return,
        },
        _ => return,
    };
    macro_rules! pick {
        ($op:expr) => {
            if constant.is_some() {
                lane_returning_operator::<H, { $op }, true, NOT_LEAF> as Handler
            } else {
                lane_returning_operator::<H, { $op }, false, NOT_LEAF> as Handler
            }
        };
    }
    let Some(handler) = arithmetic_operators!(instruction.binary_operator(), pick) else {
        return;
    };
    record.handler = handler as *const ();
    record.b = left.payload();
    match constant {
        Some(constant) => record.operand = LaneOperand { constant },
        None => record.c = right.payload(),
    }
}

/// The handler of an arithmetic `Binary` of a Number constant and a register (`1 / i`,
/// `k - x`), which keeps the record's encoded operands and immediate for the general case
/// (`lane_operator_constant_left`); `None` for any other instruction.
fn constant_left_operator_handler<H: Host>(instruction: WideInstruction, constants: &[Value]) -> Option<Handler> {
    use crate::bytecode::OperandKind::{Constant, Register};
    let (left, right) = (instruction.operand_b(), instruction.operand_c());
    if left.kind() != Some(Constant) || right.kind() != Some(Register) || instruction.numeric_local_target().is_some() {
        return None;
    }
    constants.get(usize::from(left.payload()))?.as_number()?;
    macro_rules! pick {
        ($op:expr) => {
            lane_operator_constant_left::<H, { $op }> as Handler
        };
    }
    arithmetic_operators!(instruction.binary_operator(), pick)
}

fn operator_handler<H: Host, const CONSTANT: bool>(operator: u32) -> Option<Handler> {
    macro_rules! pick {
        ($op:expr) => {
            if CONSTANT { lane_operator_constant::<H, { $op }> as Handler } else { lane_operator::<H, { $op }> as Handler }
        };
    }
    arithmetic_operators!(operator, pick)
}

/// The handler of an arithmetic operator whose right operand is `constant`, with the operand
/// its record carries: an integer as the immediate, its tag proved here once
/// (`lane_operator_integer_constant`); any other value as the constant.
fn constant_operator_handler<H: Host>(operator: u32, constant: Value) -> Option<(Handler, LaneOperand)> {
    let Some(integer) = constant.as_int() else {
        macro_rules! double {
            ($($op:ident),*) => {
                match operator {
                    $($op => lane_operator_double_constant::<H, $op> as Handler,)*
                    _ => operator_handler::<H, true>(operator)?,
                }
            };
        }
        let handler = if constant.as_number().is_some() { fused_arithmetic!(double) } else { operator_handler::<H, true>(operator)? };
        return Some((handler, LaneOperand { constant }));
    };
    macro_rules! pick {
        ($op:expr) => {
            lane_operator_integer_constant::<H, { $op }> as Handler
        };
    }
    Some((arithmetic_operators!(operator, pick)?, LaneOperand { imm: integer as u32 }))
}

/// Whether some loop of `function`, from a backward jump's target through the jump, has no
/// instruction the lane exits at.
/// Whether one activation of `function` may run an instruction more than once: it has a
/// backward jump, or a branch table, whose entries may jump back.
fn may_loop(function: &Function) -> bool {
    function.code.iter().enumerate().any(|(pc, packed)| {
        let instruction = function.widened(*packed);
        instruction.op().is_wasm_branch_table()
            || (instruction.op().immediate_role() == ImmediateRole::JumpTarget
                && instruction.imm() as usize <= pc)
    })
}

/// How many lane records control reaches from each PC before one that exits, counted up
/// to `cap`: where `follows_jumps`, a `Jump` continues at its target, as a resumed loop body
/// does, and any other record at the next PC. Each pass extends every count by one step, so
/// `cap` passes reach the fixed point the capped counts allow; without jumps one pass does.
/// An `Await` counts as `cap`: a resumed async frame's lane run that stops there suspends
/// without the general loop (`Vm::lane_stop_awaits`), so a short run to it repays its entry.
fn lane_runs_ahead(decoded: &[WideInstruction], exits: &[bool], cap: usize, follows_jumps: bool) -> Vec<usize> {
    let next = |pc: usize| match decoded[pc].op().class() {
        Class::Jump if follows_jumps => decoded[pc].imm() as usize,
        _ => pc + 1,
    };
    let mut runs = vec![0usize; exits.len()];
    for _ in 0..cap {
        let mut changed = false;
        for pc in (0..exits.len()).rev() {
            let run = if decoded[pc].op().is_await() {
                cap
            } else if exits[pc] {
                0
            } else {
                (1 + runs.get(next(pc)).copied().unwrap_or(0)).min(cap)
            };
            changed |= run != runs[pc];
            runs[pc] = run;
        }
        if !changed {
            break;
        }
    }
    runs
}

/// Whether the straight-line run from the first instruction, through its unconditional jumps,
/// reaches a `Return` before any record the lane exits at.
fn entry_run_returns(decoded: &[WideInstruction], exits: &[bool]) -> bool {
    let mut pc = 0;
    for _ in 0..decoded.len() {
        if exits.get(pc).is_none_or(|exits| *exits) {
            return false;
        }
        match decoded[pc].op().class() {
            Class::Return => return true, _ if decoded[pc].returns_from_frame() => return true, // fused with its return
            Class::Jump => pc = decoded[pc].imm() as usize,
            _ => pc += 1,
        }
    }
    false
}

fn closes_loop(decoded: &[WideInstruction], exits: &[bool]) -> bool {
    decoded.iter().enumerate().any(|(pc, &instruction)| {
        let target = instruction.imm() as usize;
        instruction.op().immediate_role() == ImmediateRole::JumpTarget
            && target <= pc
            && !exits[target..=pc].contains(&true)
    })
}

/// The register field of `instruction` that reads `register`, as an
/// accumulator position; `ACC_NONE` when no register field reads it, or more
/// than one does. A register pair's first register is the last resort.
fn accumulator_field(instruction: WideInstruction, register: u16) -> u8 {
    let mut fields = InstructionField::ALL.iter().copied().filter(|&field| {
        instruction.op().field_layout(field).reads_register()
            && instruction.field_value(field) == register
    });
    match (fields.next(), fields.next()) {
        (Some(field), None) => field.accumulator(),
        (None, _)
            if instruction.op().immediate_layout() == ImmediateLayout::RegisterPair
                && ImmediateLayout::register_pair(instruction.imm()).0 == register =>
        {
            ACC_PAIR
        }
        _ => ACC_NONE,
    }
}

/// Two inline words cover 128 instruction PCs without a heap allocation;
/// larger functions spill to contiguous words without limiting their size.
const INLINE_INSTRUCTION_WORDS: usize = 2;
const INSTRUCTION_WORD_BITS: usize = u64::BITS as usize;

struct InstructionSet(SmallVec<[u64; INLINE_INSTRUCTION_WORDS]>);

impl InstructionSet {
    fn new(count: usize) -> Self {
        Self(std::iter::repeat_n(0, count.div_ceil(INSTRUCTION_WORD_BITS)).collect())
    }

    fn insert(&mut self, pc: usize) {
        self.0[pc / INSTRUCTION_WORD_BITS] |= 1 << (pc % INSTRUCTION_WORD_BITS);
    }

    fn contains(&self, pc: usize) -> bool {
        self.0[pc / INSTRUCTION_WORD_BITS] & (1 << (pc % INSTRUCTION_WORD_BITS)) != 0
    }
}

/// The records of every branch table's entries, whose jump offsets the table reads.
fn branch_table_entry_records(instructions: &[WideInstruction]) -> InstructionSet {
    let mut entries = InstructionSet::new(instructions.len());
    for (pc, &instruction) in instructions.iter().enumerate() {
        if instruction.op().is_wasm_branch_table() {
            for entry in crate::bytecode::branch_table_entries(pc, instruction) {
                entries.insert(entry);
            }
        }
    }
    entries
}

/// The records control enters other than from the record before: jump targets, and the end of
/// a generator's parameter initialization, where its first resumption starts.
fn entered_records(instructions: &[WideInstruction], parameter_end_pc: u32) -> InstructionSet {
    let mut targets = InstructionSet::new(instructions.len());
    for instruction in instructions {
        let target = instruction.imm() as usize;
        if instruction.op().immediate_role() == ImmediateRole::JumpTarget
            && target < instructions.len()
        {
            targets.insert(target);
        }
    }
    if parameter_end_pc != 0 {
        targets.insert(parameter_end_pc as usize);
    }
    targets
}

impl<H: Host> Vm<H> {
    /// The lane view a general-loop entry of `function` runs with, or null when it runs
    /// without one (`ProgramStore::entry_lane_view`).
    pub(super) fn entry_lane_view(&self, program: ProgramId, function: u32) -> *const LaneView {
        if !H::RUNS_LANE || !self.execution_mode.allows_dynamic_execution() { return std::ptr::null(); }
        let diagnostics = self.programs.reports_on_drop();
        let tiers = self.programs.tiers();
        // A Wasm function that may loop gets its view at entry; a JavaScript one derives it
        // once a loop turns hot (`Vm::note_back_edge`).
        let wasm = self.programs.residual(program).is_some_and(|code| code.kind == crate::bytecode::ProgramKind::Wasm);
        self.programs
            .entry_lane_view(program, function, |code| wasm && may_loop(code), |code, constants, kind, live, sites| {
                derive_lane_view::<H>(
                    function,
                    code,
                    constants,
                    &self.heap,
                    kind,
                    live,
                    sites,
                    self.tier_may_run(crate::jit_mode::Tier::ANY),
                    diagnostics,
                    tiers,
                )
            })
            .unwrap_or(std::ptr::null())
    }

    /// Whether a lane run of `program` credits its functions' loop work: a Wasm program in
    /// compiled execution without an eager artifact (selective tiering) promotes its functions
    /// one by one, by calls and by loop work.
    fn lane_credits_backedges(&self, code: &ResidualProgram, program: ProgramId) -> bool {
        code.kind == crate::bytecode::ProgramKind::Wasm
            && self.execution_mode == super::ExecutionMode::Compiled
            && matches!(self.programs.compiled(program), Some(None))
            && self.programs.wasm_module_selective(program)
    }

    /// Whether the instruction at `pc` of `view` runs in the lane.
    #[inline(always)]
    pub(super) fn lane_runs(view: *const LaneView, pc: usize) -> bool {
        // SAFETY: a non-null view has an entry for every validated PC.
        crate::DYNAMIC_EXECUTION_ENABLED
            && !view.is_null()
            && unsafe {
                let entries: &[u64] = &(*view).entries;
                *entries.get_unchecked(pc / u64::BITS as usize)
                    & (1 << (pc % u64::BITS as usize)) != 0
            }
    }

    /// Whether a call from a native enters `view` at its first instruction: where the general
    /// loop would, or where the lane runs the call whole (`LaneView::returns_from_entry`).
    #[inline(always)]
    pub(super) fn lane_runs_call(view: *const LaneView) -> bool {
        // SAFETY: a non-null view lives with its program.
        Self::lane_runs(view, 0) || crate::DYNAMIC_EXECUTION_ENABLED && !view.is_null() && unsafe { (*view).returns_from_entry }
    }

    /// Run lane instructions from `pc` in `frame` and return the PC of the
    /// first one that needs the general path; lane calls and returns update
    /// `frame` and `pending` as the general loop would. Kept out of line so
    /// the general loop's code generation, which serves JavaScript, does not
    /// depend on the lane.
    #[inline(never)]
    #[allow(clippy::too_many_arguments)]
    pub(super) fn run_fast_lane(
        &mut self,
        code: &ResidualProgram,
        program: ProgramId,
        view: *const LaneView,
        frame: &mut usize,
        pc: usize,
        pending: &mut Vec<PendingGeneralCall>,
        executing: &mut super::dispatch_frame::ExecutingProgram,
        inline_calls: bool,
    ) -> usize {
        // SAFETY: the cursor's view outlives the lane run.
        let view = unsafe { &*view };
        let base = view.records();
        let registers = Registers(self.frames[*frame].registers.as_mut_ptr());
        let entered = self.enter_lane_floor(code, program);
        let start = LaneStart {
            code,
            program,
            root: LaneRoot::Frame(*frame),
            registers,
            base,
            this: self.frame_lane_this(*frame),
            pending,
            executing,
            inline_calls,
            script_calls: inline_calls
                && code.kind != crate::bytecode::ProgramKind::Wasm
                && *frame + 1 == self.frames.len(),
            script_constructs: code
                .function_get(self.frames[*frame].function as usize)
                .is_some_and(|function| {
                    function.dispatch == crate::bytecode::DispatchClass::General
                }),
            floor: entered.cell,
        };
        let mut context = self.lane_context(start);
        let ip = self.drive_lane(&mut context, entered, |cx| {
            // SAFETY: `cx` is the only access path to the context during the run.
            unsafe { (*cx).memory = frame_memory_view(cx, view, registers) };
            // SAFETY: the view has one record per instruction, and residual
            // validation establishes every reachable PC.
            unsafe { base.add(pc) }
        });
        *frame = context.frame();
        // SAFETY: handlers only return records of the active view.
        unsafe { ip.offset_from(context.base) as usize }
    }

    /// Raises the stack floor for a lane run of `program`: below the native stack's slack, or
    /// at once where a collection is due or the run credits loop work, so its backward jumps
    /// count in `lane_safepoint` (`LaneContext::backedges_left`). The floor lives in the VM's
    /// interrupt state, where a termination request raises it; entry sets it before reading
    /// the request, the request raises it after setting itself, so one of the two sees the
    /// other.
    fn enter_lane_floor(&mut self, code: &ResidualProgram, program: ProgramId) -> LaneFloor {
        let floor = if self.heap.should_collect() || self.lane_credits_backedges(code, program) {
            COLLECTION_DUE_FLOOR
        } else {
            stack_pointer().saturating_sub(LANE_STACK_SLACK)
        };
        let cell: *const std::sync::atomic::AtomicUsize = self.execution_interrupt.lane_floor();
        let outer_cell = LANE_FLOOR.with(|current| current.replace(cell));
        // SAFETY: the VM holds its interrupt state for the whole run.
        let outer_floor = unsafe { &*cell }.swap(floor, std::sync::atomic::Ordering::SeqCst);
        if self.execution_interrupt.is_termination_requested() {
            unsafe { &*cell }.store(COLLECTION_DUE_FLOOR, std::sync::atomic::Ordering::SeqCst);
        }
        LaneFloor { cell, outer_cell, outer_floor }
    }

    /// Restores the floor `entered` raised: an enclosing run of this VM keeps a raised floor
    /// raised, and a termination request raises it for good.
    fn leave_lane_floor(&self, entered: LaneFloor) {
        // SAFETY: the VM holds its interrupt state for the whole run.
        let floor = unsafe { &*entered.cell };
        if self.execution_interrupt.is_termination_requested() {
            floor.store(COLLECTION_DUE_FLOOR, std::sync::atomic::Ordering::SeqCst);
        } else {
            floor.store(entered.outer_floor, std::sync::atomic::Ordering::Relaxed);
        }
        LANE_FLOOR.with(|current| current.set(entered.outer_cell));
    }

    /// `Vm::call_value` of `callee` from the native a lane called (`LaneNativeCall`), run as
    /// the lane's own call of it would run: an activation of that lane (`lane_script_target`,
    /// `lane_activate_keeping`) whose completion ends the run with its value
    /// (`Completion::ReturnsToNative`). Any other exit makes the activations frames, the
    /// callback's the entry frame of the general loop that finishes the call
    /// (`Vm::run_frames_after_lane_exit`), as a general call of it would have run it. `None`
    /// leaves the call to the general path: a native not running from the lane's frame, or a
    /// callee or call no lane call would activate.
    pub(super) fn lane_native_callback(
        &mut self,
        callee: Value,
        receiver: Value,
        args: &[Value],
    ) -> Option<Result<Value, JsError>> {
        if !self.execution_mode.allows_dynamic_execution() { return None; }
        let site = self.lane_native?;
        let cx: *mut LaneContext<H> = site.cx.cast();
        // The native runs from the lane's frame, the innermost, with no activation above it:
        // `lane_call_native` made them frames, and only this run makes more.
        if site.frames != self.frames.len()
            || lane_context::<H>() != cx
            || !self.lane_stack.activations.is_empty()
            || self.lane_deferred.is_some()
            || self.with_scope_entered
        {
            return None;
        }
        // SAFETY: the lane's context lives while its native runs; nothing else accesses it.
        // A due collection runs on the general path, whose safepoints take it; the lane's
        // floor, set for the native's caller, bounds this run's stack as it bounds the lane's
        // own calls (`LANE_STACK_SLACK`).
        if !unsafe { (*cx).script_calls } || self.active_program != unsafe { (*cx).program } || self.heap.should_collect() {
            return None;
        }
        // Each nested run takes native stack, as the general loop's would (`Vm::enter_stack`),
        // whose exhaustion the general path raises.
        let _stack = crate::stack::StackGuard::enter().ok()?;
        // A collection since the lane entered retires the targets it resolved.
        self.lane_stack.enter_generation((self.heap.collection_epoch(), self.realm.globals));
        // Another program's callee (a library's function a benchmark's native call reaches)
        // runs as that program's activation, whose completion leaves the program to re-enter.
        let (target, crosses) = match lane_script_target(cx, callee) {
            Some(target) => (target, false),
            None => lane_cross_callback_target(cx, callee)?,
        };
        let this = lane_call_this(self, &target, receiver)?;
        let registers = self.active_registers;
        // SAFETY: as above; the context holds no drop glue. A completion to the native restores
        // the state of the native's caller (`lane_restore_caller`), so only an exit, which makes
        // frames, writes the copy back.
        let saved = unsafe { std::ptr::read(cx) };
        let (code, program) = (saved.code, saved.program);
        let mut pending = self.pending_call_stacks.pop().unwrap_or_default();
        let mut executing = super::dispatch_frame::ExecutingProgram { id: program, retained: None };
        unsafe {
            (*cx).pending = &mut pending;
            (*cx).executing = &mut executing;
        }
        let Some(start) = lane_push_callback(cx, site.call, &target, args, this, crosses) else {
            unsafe {
                (*cx).pending = saved.pending;
                (*cx).executing = saved.executing;
            }
            self.pending_call_stacks.push(pending);
            return None;
        };
        unsafe { (*cx).memory = MemoryView::script(cx) };
        let exit = lane_dispatch(cx, start);
        let outcome = match self.lane_completion.take_native_returned() {
            Some(value) => {
                unsafe {
                    (*cx).pending = saved.pending;
                    (*cx).executing = saved.executing;
                }
                if crosses {
                    lane_enter_program(cx, program);
                }
                Ok(value)
            }
            None => {
                // SAFETY: handlers only return records of the active view.
                let pc = unsafe { exit.offset_from((*cx).base) } as usize;
                // The callback's frame runs in its own program, which the general loop
                // finishes it in.
                let code = if crosses {
                    self.programs.residual(target.program()).map_or(code, std::ptr::from_ref)
                } else {
                    code
                };
                self.materialize_lane_exit(cx);
                let frame = unsafe { (*cx).frame() };
                debug_assert!(frame >= site.frames, "the callback's activation became a frame");
                self.frames[frame].pc = pc;
                let raised = self.lane_completion.take_raised();
                // SAFETY: as above.
                unsafe { lane_restore_context(cx, saved) };
                // SAFETY: the lane's program outlives its run.
                let code = unsafe { &*code };
                let exited = super::dispatch_frame::LaneExit { executing, raised };
                let result = self.run_frames_after_lane_exit(code, frame, &mut pending, exited);
                debug_assert_eq!(self.frames.len(), site.frames + 1, "the loop leaves the callback's frame");
                self.complete_user_frame(code, result, false).and_then(FrameOutcome::into_value)
            }
        };
        pending.clear();
        self.pending_call_stacks.push(pending);
        self.active_registers = registers;
        if self.active_program != program {
            self.set_active_program(program);
        }
        Some(outcome)
    }

    /// `Vm::call_value` of `callee` from a native running beside the lane's activations
    /// (`DeferredLaneCall`), run as an activation above them whose completion ends the run
    /// with its value (`Completion::ReturnsToNative`), so they stay activations and the call
    /// stays deferred. A materialization while it runs makes the activations below it the
    /// native caller's frames, with the lane's outer pending calls (`NativeBoundary`); an exit
    /// finishes the callback's frames in the general loop, as `lane_native_callback`'s does,
    /// and the native then returns to its caller's frame, as an observed deferred call does.
    /// `None` leaves the call to the general path: another lane, program or frame count, a
    /// callee no lane call would activate, or a boundary already in place.
    pub(super) fn lane_deferred_callback(
        &mut self,
        callee: Value,
        receiver: Value,
        args: &[Value],
    ) -> Option<Result<Value, JsError>> {
        if !self.execution_mode.allows_dynamic_execution() { return None; }
        let deferred = self.lane_deferred?;
        let cx: *mut LaneContext<H> = deferred.cx.cast();
        if deferred.frames != self.frames.len()
            || lane_context::<H>() != cx
            || self.lane_stack.activations.is_empty()
            || self.lane_stack.native_boundary.is_some()
            || self.with_scope_entered
        {
            return None;
        }
        // SAFETY: as `lane_native_callback`'s.
        if !unsafe { (*cx).script_calls } || self.active_program != unsafe { (*cx).program } || self.heap.should_collect() {
            return None;
        }
        let _stack = crate::stack::StackGuard::enter().ok()?;
        self.lane_stack.enter_generation((self.heap.collection_epoch(), self.realm.globals));
        let target = lane_script_target(cx, callee)?;
        // A callback of another program would enter it from the native's caller's view.
        if target.program() != unsafe { (*cx).program } {
            return None;
        }
        let this = lane_call_this(self, &target, receiver)?;
        let registers = self.active_registers;
        // SAFETY: as `lane_native_callback`'s; the copy is the innermost caller activation's
        // state, which an in-lane completion restores and an exit rebuilds as a frame's.
        let saved = unsafe { std::ptr::read(cx) };
        let (code, program) = (saved.code, saved.program);
        // SAFETY: the deferred call's record lies in the caller activation's view.
        let call = unsafe { saved.base.add(deferred.call_pc) };
        let lower = self.lane_stack.activations.len();
        let Some(start) = lane_push_callback(cx, call, &target, args, this, false) else {
            // A push that found no room made the activations frames, as the native's
            // observation of the frame stack would have.
            if self.frames.len() != deferred.frames {
                self.lane_deferred = None;
                self.resume_deferred_caller(deferred.call_pc, deferred.frames);
            }
            return None;
        };
        // The callback's activation is made: a materialization from now on gives the
        // caller's activations the outer pending calls and executing program.
        let mut pending = self.pending_call_stacks.pop().unwrap_or_default();
        let mut executing = super::dispatch_frame::ExecutingProgram { id: program, retained: None };
        unsafe {
            (*cx).pending = &mut pending;
            (*cx).executing = &mut executing;
        }
        self.lane_stack.native_boundary =
            Some(NativeBoundary {
                activation: lower,
                pending: saved.pending,
                executing: saved.executing,
                deferred,
                natives: self.realm.promise.active_native.len(),
            });
        // A callback of a native an earlier callback's frames run nests its own boundary.
        let outer_boundary_frames = self.lane_stack.boundary_frames.take();
        // A native the callback calls defers in its own turn, with its own window.
        self.lane_deferred = None; let window = self.running_window.take();
        unsafe { (*cx).memory = MemoryView::script(cx) };
        let exit = lane_dispatch(cx, start);
        let returned = self.lane_completion.take_native_returned();
        let mut boundary_frames = std::mem::replace(&mut self.lane_stack.boundary_frames, outer_boundary_frames);
        let outcome = match (returned, boundary_frames) {
            // Completed in the lane above its caller's activations: the call stays deferred.
            (Some(value), None) => {
                self.lane_stack.native_boundary = None;
                unsafe {
                    (*cx).pending = saved.pending;
                    (*cx).executing = saved.executing;
                }
                self.lane_deferred = Some(deferred); self.running_window = window;
                Ok(value)
            }
            (returned, _) => {
                let exit_pc = returned.is_none().then(|| {
                    // SAFETY: handlers only return records of the active view.
                    let pc = unsafe { exit.offset_from((*cx).base) } as usize;
                    self.lane_stack.boundary_frames = None;
                    self.materialize_lane_exit(cx);
                    if let Some(made) = std::mem::replace(&mut self.lane_stack.boundary_frames, outer_boundary_frames) {
                        boundary_frames = Some(made);
                    }
                    let frame = unsafe { (*cx).frame() };
                    self.frames[frame].pc = pc;
                    frame
                });
                // The caller's activations are frames: the lane continues in the innermost,
                // the native's caller, once the callback's frames finish.
                let caller = deferred.frames
                    + boundary_frames.expect("the caller's activations became frames above the native's")
                    - 1;
                self.lane_stack.native_boundary = None;
                // SAFETY: as above; the copy is restored before the general loop runs, as
                // `lane_native_callback`'s is, then made the caller frame's.
                unsafe {
                    lane_restore_context(cx, saved);
                    let frame_registers = Registers(self.frames[caller].registers.as_mut_ptr());
                    (*cx).root = LaneRoot::Frame(caller);
                    (*cx).registers = frame_registers;
                    frame_registers.set_this(self.frame_lane_this(caller));
                    frame_registers.set_env(Value::DELETED);
                    (*cx).registers.set_capture(std::ptr::null());
                    (*cx).outer = NO_OUTER_WALK;
        (*cx).root_walk = NO_OUTER_WALK;
                    (*cx).memory = MemoryView::script(cx);
                }
                let result = match (returned, exit_pc) {
                    (Some(value), _) => Ok(value),
                    (None, Some(frame)) => {
                        let raised = self.lane_completion.take_raised();
                        // SAFETY: the lane's program outlives its run.
                        let code = unsafe { &*code };
                        let exited = super::dispatch_frame::LaneExit { executing, raised };
                        let result = self.run_frames_after_lane_exit(code, frame, &mut pending, exited);
                        self.complete_user_frame(code, result, false).and_then(FrameOutcome::into_value)
                    }
                    (None, None) => unreachable!("an exit records its frame"),
                };
                pending.clear();
                self.pending_call_stacks.push(std::mem::take(&mut pending));
                self.active_registers = self.frames[caller].registers.as_mut_ptr();
                if self.active_program != program {
                    self.set_active_program(program);
                }
                return Some(result);
            }
        };
        pending.clear();
        self.pending_call_stacks.push(pending);
        self.active_registers = registers;
        if self.active_program != program {
            self.set_active_program(program);
        }
        Some(outcome)
    }
}

/// Restores the copy `saved` a native's callback took of the lane's context before it ran
/// (`Vm::lane_native_callback`). The copy's array storage proofs predate whatever the
/// callback changed, so they retire.
///
/// # Safety
/// `cx` is the running lane's context, which nothing else accesses.
unsafe fn lane_restore_context<H: Host>(cx: *mut LaneContext<H>, saved: LaneContext<H>) {
    unsafe {
        std::ptr::write(cx, saved);
        (*cx).proofs.retire();
    }
}

/// What a native's loop of calls of one callee with one receiver from the lane that called
/// it proves once (`Vm::prepare_lane_callback`), as JSC's `CachedCall` links its callee once
/// per loop: the lane, the native's site in it and the context its caller resumes with, the
/// callee's frameless target and the `this` it binds, resolved under `epoch`, the native
/// stack the calls run on and the pending calls their frames would take. Each call
/// (`Vm::call_prepared_lane`) tests only what the native's own steps between calls can
/// change, and leaves any other call to `Vm::call_value`.
pub(super) struct PreparedLaneCallback<H: Host> {
    cx: *mut LaneContext<H>,
    site: LaneNativeCall,
    receiver: Value,
    target: ScriptCallTarget,
    this: Value,
    /// The collection epoch `target` was resolved under; a collection retires it.
    epoch: u64,
    /// The lane's context as the native's caller left it, which a callback that leaves the
    /// lane restores (`lane_restore_context`). It holds no drop glue.
    caller: LaneContext<H>,
    /// The activation calls passing its argument count push, made once (`PreparedShape`).
    shape: Option<PreparedShape>,
    pending: Vec<PendingGeneralCall>,
    _stack: crate::stack::StackGuard,
}

/// The activation of a native's callback for calls passing `argc` values (`lane_push_callback`),
/// made once per prepared loop: every field but its window, which each call takes from the
/// lane stack, and the window's layout: its `registers`, the `passed` values its parameters
/// bind, whether it `keeps` every value passed after its registers (where a forwarded
/// `arguments` or a sloppy function's legacy reflection can observe those past its
/// parameters), its whole `size` and the `room` its admission needs.
#[derive(Clone, Copy)]
struct PreparedShape {
    argc: usize,
    activation: Activation,
    registers: usize,
    passed: usize,
    keeps: bool,
    size: usize,
    room: usize,
}

impl PreparedShape {
    /// The shape of `target`'s activations from the native whose caller's context is
    /// `caller`, for calls passing `argc` values; `None` for a gathering target, whose rest
    /// array each call makes (`lane_activate_keeping`).
    #[inline(always)]
    fn of<H: Host>(caller: &LaneContext<H>, call: Ip, target: &ScriptCallTarget, argc: usize) -> Option<Self> {
        if target.entry == CallEntry::Gathers || argc > usize::from(u16::MAX) {
            return None;
        }
        let (params, registers) = (usize::from(target.params), usize::from(target.registers));
        let keeps = target.forwards() || argc > params && !target.drops_extra_arguments();
        let size = if keeps { registers + argc } else { registers };
        let activation = Activation {
            native: crate::vm::compiled::ShadowFrame::EMPTY, function: target.function,
            call,
            caller_base: caller.base,
            caller_registers: caller.registers,
            caller_program: caller.program,
            kind: ActivationKind::Script(ScriptActivation {
                callee: target.callee,
                argc: if keeps { argc } else { argc.min(params) } as u16,
                completion: Completion::ReturnsToNative,
                forwards: keeps,
                kept: if keeps { target.registers } else { 0 },
                environment: false,
                record: std::ptr::null_mut(),
            }),
        };
        let room = usize::from(target.room).max(fill_room::<ACTIVATION_FILL_BLOCK>(size));
        Some(Self { argc, activation, registers, passed: argc.min(params), keeps, size, room })
    }
}

/// What entering an activation of a `PreparedShape` for one receiver reads
/// (`lane_enter_prepared`): the shape's window layout and the target's view, environment and
/// captures.
#[derive(Clone, Copy)]
struct PreparedEntry {
    view: *const LaneView,
    env: Value,
    capture: *const usize,
    this: Value,
    registers: usize,
    passed: u16,
    argc: u16,
    keeps: bool,
    size: usize,
    program: ProgramId,
    function: u32,
}

impl PreparedShape {
    /// The entry of its activations of `target` with `this`.
    #[inline(always)]
    fn entry(&self, target: &ScriptCallTarget, this: Value) -> PreparedEntry {
        PreparedEntry {
            view: target.view,
            env: target.env,
            capture: target.capture,
            this,
            registers: self.registers,
            passed: self.passed as u16,
            argc: self.argc as u16,
            keeps: self.keeps,
            size: self.size,
            program: target.program(),
            function: target.function,
        }
    }
}

/// The activation of a `PreparedShape`, `activation` with its admission's `room`, for a call
/// with `args` (`entry`): the window filled, the activation pushed and the context made the
/// callee's. `None`, which changes nothing, where the lane stack lacks room.
#[inline(always)]
fn lane_push_prepared<H: Host>(
    cx: *mut LaneContext<H>,
    activation: &Activation,
    room: usize,
    entry: &PreparedEntry,
    args: &[Value],
) -> Option<Ip> {
    let window = lane_admit_prepared(cx, activation, room)?;
    // SAFETY: the admission pushed the activation over the window; `args` holds
    // `entry.argc` values.
    Some(unsafe { lane_enter_prepared(cx, entry, args, window) })
}

/// `lane_push_prepared`'s admission: `activation` pushed over a window at the lane stack's
/// top with `room`, whose address it answers for the entry to fill. `None`, which
/// changes nothing, where the lane stack lacks room.
#[inline(always)]
fn lane_admit_prepared<H: Host>(cx: *mut LaneContext<H>, activation: &Activation, room: usize) -> Option<*mut Value> {
    let stack = &mut unsafe { vm(cx) }.lane_stack;
    if stack.activations.len() >= stack.activation_limit.get() || stack.values.room() < room {
        return None;
    }
    // SAFETY: as `lane_push_callback`'s.
    let at = stack.values.top();
    unsafe { stack.push_activation(*activation, at) };
    Some(at)
}

/// The activation `entry` enters, whose window starts at `registers`,
/// for a call with `args`: the window filled and the context made the callee's. Its first
/// record.
///
/// # Safety
/// The lane stack's capacity holds the window, and `args` holds `entry.argc` values.
#[inline(always)]
unsafe fn lane_enter_prepared<H: Host>(
    cx: *mut LaneContext<H>,
    entry: &PreparedEntry,
    args: &[Value],
    registers: *mut Value,
) -> Ip {
    unsafe {
        fill_window(registers, entry.registers, Value::UNDEFINED);
        copy_arguments(registers, args.as_ptr(), entry.passed);
        if entry.keeps {
            copy_arguments(registers.add(entry.registers), args.as_ptr(), entry.argc);
        }
        lane_enter_filled(cx, entry, registers)
    }
}

/// `lane_enter_prepared` of a call passing `values`, written from where the caller holds
/// them (an array step's element, index and array) rather than copied from memory.
///
/// # Safety
/// As `lane_enter_prepared`'s, for `entry.argc == N`.
#[inline(always)]
unsafe fn lane_enter_prepared_values<H: Host, const N: usize>(
    cx: *mut LaneContext<H>,
    entry: &PreparedEntry,
    values: [Value; N],
    registers: *mut Value,
) -> Ip {
    unsafe {
        let registers = lane_fill_prepared_values::<H, N>(entry, values, registers);
        lane_enter_filled(cx, entry, registers)
    }
}

/// `lane_enter_prepared_values` of the activation that returned from the window it holds,
/// at the lane stack's top, entered again for its next call (`lane_step_array_iteration_in_place`):
/// its return left the context its own and the stack's length past its window, so only the
/// window is filled again.
///
/// # Safety
/// As `lane_enter_prepared_values`'s, for the innermost activation, whose window `entry`
/// entered at `registers` and whose return the context still holds.
#[inline(always)]
unsafe fn lane_reenter_prepared_values<H: Host, const N: usize>(
    cx: *mut LaneContext<H>,
    entry: &PreparedEntry,
    values: [Value; N],
    registers: *mut Value,
) -> Ip {
    unsafe {
        let registers = lane_fill_prepared_values::<H, N>(entry, values, registers);
        // A capture walk inside the returned run may have cached the closure's dense slots in the
        // window's capture word (`lane_capture_value`): the same environment's, which the entry
        // passes as it passed it before.
        Registers(registers).set_capture(entry.capture);
        debug_assert!(
            (*cx).registers.0 == registers
                && (*cx).base == (*entry.view).records()
                && Registers(registers).this() == entry.this
                && Registers(registers).env() == entry.env
                && Registers(registers).capture() == entry.capture
                && vm(cx).lane_stack.activations.last().is_some_and(|activation| activation.window_ptr() == registers),
            "a returning activation's context is its own"
        );
        let vm = vm(cx);
        vm.programs.record_js_jit_lane_entry(entry.program, entry.function);
        // SAFETY: the program store keeps a derived view alive with its program.
        (*entry.view).start()
    }
}

/// The window of an activation of `entry` at `registers` filled for a call
/// passing `values` (`lane_enter_prepared_values`): its registers.
///
/// # Safety
/// As `lane_enter_prepared_values`'s.
#[inline(always)]
unsafe fn lane_fill_prepared_values<H: Host, const N: usize>(
    entry: &PreparedEntry,
    values: [Value; N],
    registers: *mut Value,
) -> *mut Value {
    debug_assert_eq!(usize::from(entry.argc), N);
    unsafe {
        fill_window(registers, entry.registers, Value::UNDEFINED);
        for (index, value) in values.into_iter().enumerate() {
            if index < usize::from(entry.passed) {
                registers.add(index).write(value);
            }
        }
        if entry.keeps {
            registers.add(entry.registers).cast::<[Value; N]>().write_unaligned(values);
        }
        registers
    }
}

/// The activation `entry` enters whose window, at `registers`, is filled: the context made the callee's. Its first record.
///
/// # Safety
/// As `lane_enter_prepared`'s; the window's values are written.
#[inline(always)]
unsafe fn lane_enter_filled<H: Host>(
    cx: *mut LaneContext<H>,
    entry: &PreparedEntry,
    registers: *mut Value,
) -> Ip {
    let vm = unsafe { vm(cx) };
    unsafe { vm.lane_stack.values.set_top(registers.add(entry.size + lane_values::CONTEXT)) };
    lane_install_entry(cx, entry, registers);
    vm.programs.record_js_jit_lane_entry(entry.program, entry.function);
    // SAFETY: the program store keeps a derived view alive with its program.
    unsafe { (*entry.view).start() }
}

/// The context made `entry`'s callee's, running over the window at `registers`, wherever it lies.
#[inline(always)]
fn lane_install_entry<H: Host>(cx: *mut LaneContext<H>, entry: &PreparedEntry, registers: *mut Value) {
    // SAFETY: the program store keeps a derived view alive with its program.
    unsafe {
        (*cx).registers = Registers(registers);
        (*cx).base = (*entry.view).records();
        Registers(registers).set_this(entry.this);
        Registers(registers).set_env(entry.env);
        Registers(registers).set_capture(entry.capture);
    }
}

/// The activation of a suspended frame (`generator_windows`) enters its window at `registers`,
/// a register file of its own that no lane stack holds, at the record of `pc`, where the frame
/// resumes: the context made the callee's.
///
/// # Safety
/// `registers` holds the callee's registers, which nothing else writes while it runs, and `pc`
/// is a record of its view.
#[inline(always)]
unsafe fn lane_enter_suspended<H: Host>(
    cx: *mut LaneContext<H>,
    entry: &PreparedEntry,
    registers: *mut Value,
    pc: usize,
) -> Ip {
    lane_install_entry(cx, entry, registers);
    // SAFETY: the program store keeps a derived view alive with its program.
    unsafe { (*entry.view).records().add(pc) }
}

impl<H: Host> Vm<H> {
    /// `lane_native_callback`'s tests and resolution, made once for a native's loop of calls
    /// of `callee` with `receiver`: `None` where none of them would run in the lane.
    pub(super) fn prepare_lane_callback(&mut self, callee: Value, receiver: Value) -> Option<PreparedLaneCallback<H>> {
        if !self.execution_mode.allows_dynamic_execution() || self.lane_deferred.is_some() {
            return None;
        }
        let site = self.lane_native?;
        let cx: *mut LaneContext<H> = site.cx.cast();
        if site.frames != self.frames.len()
            || lane_context::<H>() != cx
            || !self.lane_stack.activations.is_empty()
            || self.with_scope_entered
            // SAFETY: the lane's context lives while its native runs.
            || !unsafe { (*cx).script_calls }
            || self.active_program != unsafe { (*cx).program }
        {
            return None;
        }
        let stack = crate::stack::StackGuard::enter().ok()?;
        let epoch = self.heap.collection_epoch();
        self.lane_stack.enter_generation((epoch, self.realm.globals));
        let target = lane_script_target(cx, callee)?;
        let this = lane_call_this(self, &target, receiver)?;
        Some(PreparedLaneCallback {
            cx,
            site,
            receiver,
            target,
            this,
            epoch,
            // SAFETY: as `lane_native_callback`'s copy; the native's caller resumes with it.
            caller: unsafe { std::ptr::read(cx) },
            shape: None,
            pending: self.pending_call_stacks.pop().unwrap_or_default(),
            _stack: stack,
        })
    }

    /// Ends a prepared loop: its pending-call stack returns to the pool.
    pub(super) fn finish_lane_callback(&mut self, prepared: PreparedLaneCallback<H>) {
        let PreparedLaneCallback { mut pending, .. } = prepared;
        pending.clear();
        self.pending_call_stacks.push(pending);
    }

    /// `lane_native_callback` of the prepared callee with `args`, past what the loop proved:
    /// it tests the frame depth, the lane's activations and program, a due collection and
    /// the collection epoch, which the native's steps between calls can change. `None`
    /// leaves the call to the general path.
    pub(super) fn call_prepared_lane(
        &mut self,
        prepared: &mut PreparedLaneCallback<H>,
        args: &[Value],
    ) -> Option<Result<Value, JsError>> {
        let cx = prepared.cx;
        let site = prepared.site;
        // SAFETY: the lane's context lives while its native runs.
        let program = unsafe { (*cx).program };
        if site.frames != self.frames.len()
            || !self.lane_stack.activations.is_empty()
            || self.lane_deferred.is_some()
            || self.with_scope_entered
            || self.active_program != program
            || self.heap.should_collect()
        {
            return None;
        }
        if self.heap.collection_epoch() != prepared.epoch {
            prepared.epoch = self.heap.collection_epoch();
            self.lane_stack.enter_generation((prepared.epoch, self.realm.globals));
            let callee = prepared.target.callee;
            prepared.target = lane_script_target(cx, callee)?;
            prepared.this = lane_call_this(self, &prepared.target, prepared.receiver)?;
            prepared.shape = None;
        }
        if prepared.shape.as_ref().is_none_or(|shape| shape.argc != args.len()) {
            prepared.shape = PreparedShape::of(&prepared.caller, site.call, &prepared.target, args.len());
        }
        let registers = self.active_registers;
        let mut executing = super::dispatch_frame::ExecutingProgram { id: program, retained: None };
        // SAFETY: as `lane_native_callback`'s.
        unsafe {
            (*cx).pending = &mut prepared.pending;
            (*cx).executing = &mut executing;
        }
        let restore_pending = |cx: *mut LaneContext<H>, caller: &LaneContext<H>| unsafe {
            (*cx).pending = caller.pending;
            (*cx).executing = caller.executing;
        };
        let pushed = match &prepared.shape {
            Some(shape) => lane_push_prepared(cx, &shape.activation, shape.room, &shape.entry(&prepared.target, prepared.this), args),
            None => None,
        };
        let Some(start) = pushed.or_else(|| {
            lane_push_callback(cx, site.call, &prepared.target, args, prepared.this, false)
        }) else {
            restore_pending(cx, &prepared.caller);
            return None;
        };
        unsafe { (*cx).memory = MemoryView::script(cx) };
        let exit = lane_dispatch(cx, start);
        let outcome = match self.lane_completion.take_native_returned() {
            Some(value) => {
                restore_pending(cx, &prepared.caller);
                Ok(value)
            }
            None => {
                // SAFETY: handlers only return records of the active view.
                let pc = unsafe { exit.offset_from((*cx).base) } as usize;
                self.materialize_lane_exit(cx);
                let frame = unsafe { (*cx).frame() };
                debug_assert!(frame >= site.frames, "the callback's activation became a frame");
                self.frames[frame].pc = pc;
                let raised = self.lane_completion.take_raised();
                // SAFETY: as `lane_native_callback`'s; the copy holds no drop glue.
                unsafe { lane_restore_context(cx, std::ptr::read(&prepared.caller)) };
                // SAFETY: the lane's program outlives its run.
                let code = unsafe { &*prepared.caller.code };
                let exited = super::dispatch_frame::LaneExit { executing, raised };
                let result = self.run_frames_after_lane_exit(code, frame, &mut prepared.pending, exited);
                debug_assert_eq!(self.frames.len(), site.frames + 1, "the loop leaves the callback's frame");
                prepared.pending.clear();
                self.complete_user_frame(code, result, false).and_then(FrameOutcome::into_value)
            }
        };
        self.active_registers = registers;
        if self.active_program != program {
            self.set_active_program(program);
        }
        Some(outcome)
    }
}

/// Dispatch lane records from `ip` until a handler exits; the record it exits at.
#[inline(always)]
fn lane_dispatch<H: Host>(cx: *mut LaneContext<H>, mut ip: Ip) -> Ip {
    loop {
        #[cfg(feature = "profile-lane-exits")]
        {
            // The record's opcode from its packed instruction: the census needs the mix, and
            // the lane record keeps only the handler.
            let function = lane_running_function(cx);
            let code = unsafe { &*(*cx).code };
            let pc = unsafe { ip.offset_from((*cx).base) as usize };
            if let Some(body) = code.function_get(function as usize)
                && let Some(packed) = body.code.get(pc)
            {
                super::lane_exits::dispatch(body.widened(*packed).op());
            }
        }
        // SAFETY: handlers have returned, so no other access is live.
        let (view, registers, acc) = unsafe {
            let acc = std::mem::replace(&mut (*cx).resumed_acc, Slot::of(Value::UNDEFINED));
            ((*cx).memory, (*cx).registers, acc)
        };
        let next = handler(ip)(
            registers,
            ip,
            view.bytes,
            view.reach,
            crate::value::IntegerEncoding::TAG,
            acc,
        );
        let (ip_next, left) = exited(next);
        if left {
            return ip_next;
        }
        ip = ip_next;
    }
}

